window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[10] = [{"id":1439,"category_id":10,"category_code":"s10","source_id":1,"title":"کارمند تازه وارد ","content":"مردی به استخدام یک شرکت بزرگ چندملیتی درآمد. در اولین روز کار خود، با کافه تریا تماس گرفت و فریاد زد: یک فنجان قهوه برای من بیاورید.\r\nصدایی از آن طرف پاسخ داد: شماره داخلی را اشتباه گرفته ای\r\nمی دانی تو با کی داری حرف می زنی ؟\r\nکارمند تازه وارد گفت: نه\r\nصدای آن طرف گفت: من مدیر اجرایی شرکت هستم، احمق\r\nمرد تازه وارد با لحنی حق به جانب گفت: و تو میدانی با کی حرف میزنی بیچاره.\r\nمدیر اجرایی گفت: نه\r\nکارمند تازه وارد گفت: خوبه و سریع گوشی را گذاشت.\r\n"},{"id":1440,"category_id":10,"category_code":"s10","source_id":2,"title":"ویلون زن ","content":"در یک سحرگاه سرد ماه ژانویه، مردی وارد ایستگاه متروی واشینگتن دی سی شد  و شروع به نواختن ویلون کرد. این مرد در عرض ۴۵ دقیقه، شش قطعه ازبهترین قطعات باخ را نواخت. از آنجا که شلوغ ترین ساعات صبح بود، هزاران نفر برایرفتن به سر کارهای‌شان به سمت مترو هجوم آورده بودند.\r\n\r\nسه دقیقه گذشته بود که مرد میانسالی....\r\nمتوجه نوازنده شد. از سرعت قدم‌هایش کاست و چند ثانیه‌ای توقف کرد، بعد با عجله به سمت مقصد خود براه افتاد.\r\n\r\nیک دقیقه بعد، ویلون‌زن اولین انعام خود را دریافت کرد. خانمی بی‌آنکه توقف کند یک اسکناس یک دلاری به درون کاسه‌اش انداخت و با عجله براه خود ادامه داد.\r\n\r\nچند دقیقه بعد، مردی در حالیکه گوش به موسیقی سپرده بود، به دیوار پشت‌ سر تکیه داد، ولی ناگاهان نگاهی به ساعت خود انداخت وبا عجله از صحنه دور شد،\r\n\r\nکسی که بیش از همه به ویلون زن توجه نشان داد، کودک سه ساله‌ای بود که مادرش با عجله و کشان کشان بهمراه می ‌برد.\r\n کودک یک لحظه ایستاد و به تماشای ویلون‌زن پرداخت، مادر محکم تر کشید وکودک در حالیکه همچنان نگاهش به ویلون‌زن بود، بهمراه مادر براه افتاد،\r\nاین صحنه، توسط چندین کودک دیگرنیز به همان ترتیب تکرار شد، و والدین‌شان بلا استثنا برای بردن‌شان به زور متوسل شدند.\r\n در طول مدت ۴۵ دقیقه‌ای که ویلون‌زن می نواخت، تنها شش نفر، اندکی توقف کردند. بیست نفر انعام دادند، بی‌آنکه مکثی کرده باشند، و سی و دو دلار عاید ویلون‌زن شد. وقتیکه ویلون‌زن از نواختن دست کشید و سکوت بر همه جا حاکم شد، نه کسی متوجه شد. نه کسی تشویق کرد،\r\n ونه کسی او را شناخت.\r\n\r\n هیچکس نمی‌دانست که این ویلون‌زن همان (جاشوا بل ) یکی از بهترین موسیقیدانان جهان است، و نوازنده‌ی یکی از پیچیده‌ترین قطعات نوشته شده برای ویلون به ارزش سه ونیم میلیون دلار،\r\n می‌باشد.\r\n\r\n جاشوا بل، دو روز قبل از نواختن در سالن مترو، در یکی از تاتر های شهر بوستون، برنامه‌ای اجرا کرده بود که تمام بلیط هایش پیش‌فروش شده بود، وقیمت متوسط هر بلیط یکصد دلار بود.\r\n\r\n این یک داستان حقیقی است،نواختن جاشوا بل در ایستگاه مترو توسط واشینگتن‌پست ترتیب داده شده بود، وبخشی از تحقیقات اجتماعی برای سنجش توان شناسایی، سلیقه و الوویت ‌های مردم بود.\r\n"},{"id":1441,"category_id":10,"category_code":"s10","source_id":3,"title":"سیرک ","content":"یادم می آید وقتی که نوجوان بودم، یک شب با پدرم در صف خرید بلیط سیرک ایستاده بودیم. جلوی ما یک خانواده پرجمعیت ایستاده بودند. به نظر می رسید پول زیادی نداشتند.\r\nشش بچه که همگی زیر دوازده سال بودند، لباس های کهنه ولی...\r\nدر عین حال تمیـز پوشیده بودنـد. بچه ها همگی با ادب بودند. دوتا دوتا پشت پدر و مادرشان، دست همدیگر را گرفته بودند و با هیجان در مورد برنامه ها و شعبده بازی هایی که قرار بود ببینند، صحبت می کردند. مادر بازوی شوهرش را گرفته بود و با عشق به او لبخند می زد.\r\nوقتی به باجه بلیط فروشی رسیدند، متصدی باجه از پدر خانواده پرسید:« چند عدد بلیط می خواهید؟» پدر جواب داد: « لطفاً شش بلیط برای بچه ها و دو بلیط برای بزرگسالان.»\r\nمتصدی باجه، قیمت بلیط ها را گفت. پدر به باجه نزدیکتر شد و به آرامی پرسید:« ببخشید، گفتید چه قدر؟» متصدی باجه دوباره قیمت بلیط ها را تکرار کرد.\r\nپدر و مادر بچه ها با ناراحتی زمزمه کردند. معلوم بود که مرد پول کافی نداشت. حتماً فکر می کرد که به بچه های کوچکش چه جوابی بدهد؟\r\nناگهان پدرم دست در جیبش برد و یک اسکناس بیست دلاری بیرون آورد و روی زمین انداخت. بعد خم شد، پول را از زمین برداشت، به شانه مرد زد و گفت: « ببخشید آقا، این پول از جیب شما افتاد!»\r\nمرد که متوجه موضوع شده بود، همان طور که اشک از چشمانش سرازیر می شد، گفت:« متشکرم آقا.»\r\nپدر خانواده مرد شریفی بود ولی درآن لحظه برای اینکه پیش بچه ها شرمنده نشود، کمک پدرم را قبول کرد.\r\nبعد از این که بچه ها داخل سیرک شدند، من و پدرم از صف خارج شدیم و به طرف خانه حرکت کردیم.\r\n"},{"id":1442,"category_id":10,"category_code":"s10","source_id":4,"title":"آرایشگر... ","content":"در شهری در آمریکا،آرایشگری زندگی می‌کرد که سالها بچه‌دار نمی‌شد.او نذر کرد که اگر بچه‌دار شود، تا یک ماه سر همه مشتریان را به رایگان اصلاح کند. بالاخره خدا خواست و او بچه‌دار شد! روز اول یک شیرینی فروش ایتالیائی وارد مغازه شد. پس ازپایان کار، هنگامیکه قناد خواست پول\r\n بدهد، آرایشگر ماجرا را به او گفت. فردای آن روز وقتی آرایشگر خواست مغازه‌اش را باز کند، یک جعبه بزرگ شیرینی و یک کارت تبریک و تشکر از طرف قناد دم در بود. روز دوم یک گل فروش هلندی به او مراجعه کرد و هنگامی که خواست حساب کند، آرایشگرماجرا را به او گفت.. فردای آن روز وقتی آرایشگر خواست مغازه‌اش راباز کند، یک دسته گل بزرگ و یک کارت تبریک و تشکر از طرف گل فروش دم در بود. روز سوم یک مهندس ایرانی به او مراجعه کرد. در پایان آرایشگرماجرا را به او گفت و از گرفتن پول  امتناع کرد. حدس بزنید فردای آن روز وقتی آرایشگر خواست مغازه‌اش را باز کند، با چه\r\nمنظره‌ای روبروشد؟\r\nفکرکنید. شما هم یک ایرانی هستید...\r\n\r\nچهل تا ایرانی، همه سوار بر آخرین مدل ماشین، دم در سلمانی صف کشیده بودند و غر می‌زدند که پس این مردک چرا مغازه‌اش را باز نمی‌کند.\r\n"},{"id":1443,"category_id":10,"category_code":"s10","source_id":5,"title":"روستایی فقیر ","content":"روستایی فقیری که از تنگدستی و سختی معیشت جانش به لب رسیده بود، نزد آخوند ده رفت و گفت: آملا، فشار زندگی آنقدر مرا در تنگنا قرار داده که به فکر خودکشی افتاده ام. از روی زن و بچه هایم خجالت می کشم، زیرا حتی قادر به تامین نان خالی برای آنان نیستم. با زن، شش فرزند قد و نیم قد، مادر و خواهرم در یک اتاق کوچک مخروبه زندگی می کنیم، که با هر نم باران آب به داخل آن چکه می کند. این اتاق آنقدر کوچک است که شب وقتی چسبیده به هم در آن می خوابیم، پای یکی دو نفرمان از درگاه بیرون می ماند. دیگر ادامه این وضع برایم قابل تحمل نیست... پیش تو، که مقرب درگاه خدا هستی، آمده ام تا نزد او شفاعت کنی که گشایشی در وضع من و خانواده ام حاصل شود. \r\nآخوند پرسید: \r\nاز مال دنیا چه داری؟ \r\nروستایی گفت: \r\nهمه دار و ندارم یک گاو، یک خر، دو بز، سه گوسفند، چهار مرغ و یک خروس است. \r\nآخوند گفت: \r\nمن به یک شرط به تو کمک می کنم و آن این است که قول بدهی هرچه گفتم انجام بدهی. \r\nروستایی که چاره ای نداشت، ناگزیر شرط را پذیرفت و قول داد....\r\nآخوند گفت: \r\nامشب وقتی خواستید بخوابید باید گاو را هم به داخل اتاق ببری. روستایی برآشفت که: آملا، من به تو گفتم که اتاق آنقدر کوچک است که حتی من و خانواده ام نیز در آن جا نمی گیریم. تو چگونه می خواهی که گاو را هم به اتاق ببرم؟! \r\nآخوند گفت: فراموش نکن که قول داده ای هر چه گفتم انجام دهی وگرنه نباید از من انتظار کمک داشته باشی. \r\nصبح روز بعد، روستایی پریشان و نزار نزد آخوند رفت و گفت: دیشب هیچ یک از ما نتوانستیم بخوابیم. سر و صدا و لگداندازی گاو خواب را به چشم همه ما حرام کرد. \r\nآخوند یکبار دیگر قول روستایی را به او یادآوری کرد و گفت: \r\nامشب علاوه بر گاو، باید خر را نیز به داخل اتاق ببری. \r\nچند روز به این ترتیب گذشت و هر بار که روستایی برای شکایت از وضع خود نزد آخوند می رفت، او دستور می داد که یکی دیگر از حیوانات را نیز به داخل اتاق ببرد تا این که همه حیوانات هم خانه روستایی و خانواده اش شدند! روز آخر روستایی با چشمانی گود افتاده، سراپای زخمی و لباس پاره نزد آخوند رفت و گفت که واقعا ادامه این وضع برایش امکان پذیر نیست! \r\nآخوند دستی به ریش خود کشید و گفت: دوره سختی ها به پایان رسیده و به زودی گشایشی که می خواستی حاصل خواهد شد. پس از آن به روستایی گفت که شب گاو را از اتاق بیرون بگذارد! \r\nماجرا در جهت معکوس تکرار شد و هر روز که روستایی نزد آخوند می رفت، این یک به او می گفت که یکی دیگر از حیوانات را از اتاق خارج کند تا این که آخرین حیوان، خروس نیز بیرون گذاشته شد. \r\nروز بعد وقتی روستایی نزد آخوند رفت، آخوند از وضع او سئوال کرد و روستایی گفت: خدا عمرت را دراز کند آملا، پس از مدتها، دیشب خواب راحتی کردیم. به راستی نمی دانم به چه زبانی از تو تشکر کنم. آه که چه راحت شدیم.\r\n"},{"id":1444,"category_id":10,"category_code":"s10","source_id":6,"title":"رعیت و عتیقه فروش ","content":"عتیقه فروشی در روستایی به منزل رعیتی ساده وارد شد. دید کاسه ای نفیس و قدیمی دارد که در گوشه ای افتاده و گربه در آن آب میخورد. دید اگر قیمت کاسه را بپرسد رعیت ملتفت مطلب میشود و قیمت گرانی بر آن می نهد. لذا گفت: عموجان چه گربه قشنگی داری آیا حاضری آن را به من بفروشی؟ رعیت گفت:...\r\nچند می خری؟ گفت: یک درهم. رعیت گربه را گرفت و به دست عتیقه فروش داد و گفت: خیرش را ببینی. عتیقه فروش پیش از خروج از خانه با خونسردی گفت: عموجان این گربه ممکن است در راه تشنه اش شود بهتر است کاسه آب را هم به من بفروشی. رعیت گفت: قربان من به این وسیله تا به حال پنج گربه فروخته ام. کاسه فروشی نیست.\r\n"},{"id":1445,"category_id":10,"category_code":"s10","source_id":7,"title":"مادر ","content":"پس از 21 سال زندگی مشترک همسرم از من خواست که با کس دیگری برای شام و سینما بیرون بروم. زنم گفت که مرا دوست دارد ولی مطمئن است که این زن هم مرا دوست دارد و از بیرون رفتن با من لذت خواهد برد.\r\nآن زن مادرم بود که 19 سال پیش از این بیوه شده بود.  ولی مشغله های زندگی و داشتن 3 بچه باعث شده بود که من فقط در موارد اتفاقی ونامنظم به او سر بزنم.\r\nآن شب به او زنگ زدم تا برای سینما و شام بیرون برویم...\r\nمادرم با نگرانی پرسید که مگر چه شده؟\r\nاو از آن دسته افرادی بود که یک تماس تلفنی شبانه و یا یک دعوت غیر منتظره را نشانه یک خبر بد میدانست. به او گفتم: بنظرم رسید بسیار دلپذیر خواهد بود که اگر ما دو امشب را با هم باشیم.  او پس از کمی تامل گفت که او نیز از این ایده لذت خواهد برد.\r\nآن جمعه پس از کار وقتی برای بردنش میرفتم کمی عصبی بودم. وقتی رسیدم دیدم که او هم کمی عصبی بود کتش را پوشیده بود و جلوی درب ایستاده بود، لباسی را پوشیده بود که در آخرین جشن سالگرد ازدواجش پوشیده بود. با چهره ای روشن همچون فرشتگان به من لبخند زد.\r\nوقتی سوار ماشین میشد گفت که به دوستانش گفته امشب با پسرم برای گردش بیرون میروم. و آنها خیلی تحت تاثیر قرار گرفته اند و نمیتوانند برای شنیدن ما وقع امشب منتظر بمانند. \r\nما به رستورانی رفتیم که هر چند لوکس نبود ولی بسیار راحت و دنج بود. دستم را چنان گرفته بود که گوئی همسر رئیس جمهور بود. \r\nپس از اینکه نشستیم به خواندن منوی رستوران مشغول شدم. هنگام خواندن از بالای منو نگاهی به چهره مادرم انداختم و دیدم با لبخندی حاکی از یاد آوری خاطرات گذشته به من می نگرد، و به من گفت یادش می آید که وقتی من کوچک بودم و با هم به رستوران میرفتیم او بود که منوی رستوران را میخواند. من هم در پاسخ گفتم که حالا وقتش رسده که تو استراحت کنی و بگذاری که من این لطف را در حق تو بکنم.\r\nهنگام صرف شام مکالمه قابل قبولی داشتیم، هیچ چیز غیر عادی بین ما رد و بدل نشد بلکه صحبتها پیرامون وقایع جاری بود و آنقدرحرف زدیم که سینما را از دست دادیم.\r\n\r\nوقتی او را به خانه رساندم گفت که باز هم با من بیرون خواهد رفت به شرط اینکه او مرا دعوت کند و من هم قبول کردم. وقتی به خانه برگشتم همسرم از من پرسید که آیا شام بیرون با مادرم خوش گذشت؟\r\nمن هم در جواب گفتم خیلی بیشتر از آنچه که میتوانستم تصور کنم. چند روز بعد مادرم در اثر یک حمله قلبی شدید درگذشت و همه چیز بسیار سریعتر از آن واقع شد که بتوانم کاری کنم. کمی بعد پاکتی حاوی کپی رسیدی از رستورانی که با مادرم در آن شب در آنجا غذا خوردیم بدستم رسید. یادداشتی هم بدین مضمون بدان الصاق شده بود:\r\n نمیدانم که آیا در آنجا خواهم بود یا نه ولی هزینه را برای 2 نفر پرداخت کرده ام یکی برای تو و یکی برای همسرت. \r\n\r\nو تو هرگز نخواهی فهمید که آنشب برای من چه مفهومی داشته است، دوستت دارم پسرم.\r\n"},{"id":1446,"category_id":10,"category_code":"s10","source_id":8,"title":"سر پیری و معرکه گیری ","content":"یه مرد ۸۰ ساله میره پیش دکترش برای چک آپ. دکتر ازش در مورد وضعیت فعلیش می پرسه و پیرمرد با غرور جواب میده:\r\nهیچوقت به این خوبی نبودم. تازگیا با یه دختر ۲۵ ساله ازدواج کردم و حالا باردار شده و کم کم داره موقع زایمانش میرسه. نظرت چیه دکتر؟...\r\nدکتر چند لحظه فکر میکنه و میگه: خب… بذار یه داستان برات تعریف کنم. من یه نفر رو می شناسم که شکارچی ماهریه. اون هیچوقت تابستونا رو برای شکار کردن از دست نمیده.\r\nیه روز که می خواسته بره شکار از بس عجله داشته اشتباهی چترش رو به جای تفنگش بر میداره و میره توی جنگل.. همینطور که میرفته جلو یهو از پشت درختها یه پلنگ وحشی ظاهر میشه و میاد به طرفش. \r\nشکارچی چتر رو می گیره به طرف پلنگ و نشونه می گیره و ….. بنگ! پلنگ کشته میشه و میفته روی زمین!\r\nپیرمرد با حیرت میگه: این امکان نداره! حتما' یه نفر دیگه پلنگ رو با تیر زده!\r\nدکتر یه لبخند میزنه و میگه: دقیقا' منظور منم همین بود!\r\n"},{"id":1447,"category_id":10,"category_code":"s10","source_id":9,"title":"جانشین پادشاه ","content":"روزی از روزها، پادشاهی سالخورده که دو پسرش را در جنگ با دشمنان از دست داده بود، تصمیم گرفت برای خود جانشینی انتخاب کند. پادشاه تمام جوانان شهر را جمع کرد و به هر کدام دانه ی گیاهی داد و از آنها خواست، دانه را در یک گلدان بکارند تا دانه رشد کند و گیاه رشد کرده را در روز معینی نزد او بیاورند. پینک یکی از آن جوان ها بود و تصمیم داشت....\r\nتمام تلاش خود را برای پادشاه شدن بکار گیرد، بنابراین با تمام جدیت تلاش کرد تا دانه را پرورش دهد ولی موفق نشد. به این فکر افتاد که دانه را در آب و هوای دیگری پرورش دهد، به همین دلیل به کوهستان رفت و خاک آنجا را هم آزمایش کرد ولی موفق نشد. پینک حتی با کشاورزان دهکده های اطراف شهر مشورت کرد ولی همه این کارها بی فایده بود و نتوانست گیاه را پرورش دهد. بالاخره روز موعود فرا رسید. همه جوان ها در قصر پادشاه جمع شده و گیاه کوچک خودشان را در گلدان برای پادشاه آورده بودند. پادشاه به همه گلدان ها نگاه کرد. وقتی نوبت به پینک رسید، پادشاه از او پرسید: پس گیاه تو کو؟ پینک ماجرا را برای پادشاه تعریف کرد... در این هنگام پادشاه دست پینک را بالا برد و او را جانشین خود اعلام کرد! همه جوانان به این انتخاب پادشاه اعتراض کردند. پادشاه روی تخت نشست و گفت: این جوان درستکارترین جوان شهر است. من قبلاً همه دانه ها را در آب جوشانده بودم، بنابراین هیچ یک از دانه ها نمی بایست رشد می کردند. پادشاه ادامه داد: مردم به پادشاهی نیاز دارند که در عین راستگویی و درستکاری با آنها صادق باشد، نه آن پادشاهی که برای رسیدن به قدرت و حفظ آن دست به هر عمل ریا کارانه ای بزند!\r\n"},{"id":1448,"category_id":10,"category_code":"s10","source_id":10,"title":"پدر ","content":"مردی ۸۵ ساله با پسر تحصیل کرده ۴۵ ساله اش روی مبل خانه خود نشسته بودند ناگهان کلاغی کنار پنجره‌شان نشست. پدر از فرزندش پرسید: این چیه؟ پسر پاسخ داد: کلاغ.\r\nپس از چند دقیقه دوباره پرسید این چیه؟ پسر گفت : بابا من که همین الان بهتون گفتم: کلاغه.\r\nبعد از مدت کوتاهی پیر مرد برای سومین بار پرسید: این چیه؟ عصبانیت در پسرش موج میزد و با همان حالت گفت: کلاغه کلاغ!....\r\nپدر به اتاقش رفت و با دفتر خاطراتی قدیمی برگشت. صفحه ای را باز کرد و به \r\nپسرش گفت که آن را بخواند.\r\nدر آن صفحه این طور نوشته شده بود:\r\nامروز پسر کوچکم ۳ سال دارد. و روی مبل نشسته است هنگامی که کلاغی روی پنجره نشست پسرم ۲۳ بار نامش را از من پرسید و من ۲۳ بار به او گفتم که نامش کلاغ است.\r\nهر بار او را عاشقانه بغل می‌کردم و به او جواب می‌دادم و به هیچ وجه عصبانی  نمی‌شدم و در عوض علاقه بیشتری نسبت به او پیدا می‌کردم.\r\n"},{"id":1449,"category_id":10,"category_code":"s10","source_id":11,"title":"لذت زندگی ","content":"ادیسون در سنین پیری پس از کشف لامپ، یکی از ثروتمندان آمریکا به شمار میرفت و درآمد سرشارش را تمام و کمال در آزمایشگاه مجهزش که ساختمان بزرگی بود هزینه می کرد...\r\nاین آزمایشگاه، بزرگترین عشق پیرمرد بود. هر روز اختراعی جدید در آن شکل می گرفت تا آماده بهینه سازی و ورود به بازار شود.\r\n\r\nدر همین روزها بود که نیمه های شب از اداره آتش نشانی به پسر ادیسون اطلاع دادند، آزمایشگاه پدرش در آتش می سوزد و حقیقتا کاری از دست کسی بر نمی آید و تمام تلاش ماموان فقط برای جلوگیری از گسترش آتش به سایر ساختمانها است! \r\nآنها تقاضا داشتند که موضوع به نحو قابل قبولی به اطلاع پیرمرد رسانده شود...\r\nپسر با خود اندیشید که احتمالا پیرمرد با شنیدن این خبر سکته می کند و لذا از بیدار کردن او منصرف شد و خودش را به محل حادثه رساند و با کمال تعجب دید که پیرمرد در مقابل ساختمان آزمایشگاه روی یک صندلی نشسته است و سوختن حاصل تمام عمرش را نظاره می کند!!! \r\nپسر تصمیم گرفت جلو نرود و پدر را آزار ندهد. او می اندیشید که پدر در بدترین شرایط عمرش بسر می برد. \r\nناگهان پدر سرش را برگرداند و پسر را دید و با صدای بلند و سر شار از شادی گفت: پسر تو اینجایی؟ می بینی چقدر زیباست؟!! رنگ آمیزی شعله ها را می بینی؟!! حیرت آور است!!!\r\nمن فکر می کنم که آن شعله های بنفش به علت سوختن گوگرد در کنار فسفر به وجود آمده است! وای! خدای من، خیلی زیباست! کاش مادرت هم اینجا بود و این منظره زیبا را می دید. کمتر کسی در طول عمرش امکان دیدن چنین منظره زیبایی را خواهد داشت! نظر تو چیست پسرم؟!! \r\nپسر حیران و گیج جواب داد: پدر تمام زندگیت در آتش می سوزد و تو از زیبایی رنگ شعله ها صحبت می کنی؟!!!!!! \r\nچطور میتوانی؟! من تمام بدنم می لرزد و تو خونسرد نشسته ای؟!\r\nپدر گفت: پسرم از دست من و تو که کاری بر نمی آید. مامورین هم که تمام تلاششان را می کنند. در این لحظه بهترین کار لذت بردن از منظره ایست که دیگر تکرار نخواهد شد...! \r\nدر مورد آزمایشگاه و باز سازی یا نو سازی آن فردا فکر می کنیم! الآن موقع این کار نیست! به شعله های زیبا نگاه کن که دیگر چنین امکانی را نخواهی داشت!!\r\nتوماس آلوا ادیسون سال بعد مجددا در آزمایشگاه جدیدش مشغول کار بود و همان سال یکی از بزرگترین اختراع بشریت یعنی ضبط صدا را تقدیم جهانیان نمود. آری او گرامافون را درست یک سال پس از آن واقعه اختراع کرد.\r\n"},{"id":1450,"category_id":10,"category_code":"s10","source_id":12,"title":"سخاوت ","content":"پسر بچه ای وارد بستنی فروشی شد و پشت میزی نشست. پیشخدمت یک لیوان آب برایش آورد. پسر بچه پرسید: (( یک بستنی میوه ای چند است؟ )) پیشخدمت پاسخ داد : (( 50 سنت )) . پسر بچه دستش را در جیبش برد و شروع به شمردن کرد . بعد پرسید : (( یک بستنی ساده چند است ؟ ))\r\nدر همین حال ، تعدادی از مشتریان در انتظار میز خالی بودند و پیشخدمت با عصبانیت پاسخ داد: 35 سنت\r\nپسر دوباره سکه هایش را شمرد و گفت : لطفأ یک بستنی ساده...\r\nپیشخدمت بستنی را آورد و به دنبال کار خود رفت.\r\nپسرک نیز پس از خوردن بستنی پول را به صندوق پرداخت و رفت\r\nوقتی پیشخدمت بازگشت از آنچه دید شوکه شد. آنجا در کنار ظرف خالی بستنی، 2 سکه 5 سنتی و 5 سکه 1 سنتی گذاشته شده بود. برای انعام پیشخدمت\r\n"},{"id":1451,"category_id":10,"category_code":"s10","source_id":13,"title":"حکایت شرلوک هلمز ","content":"شرلوک هلمز، کارآگاه معروف، و معاونش واتسون رفته بودند صحرانوردی و شب هم چادری زدند و زیر آن خوابیدند. نیمه های شب هلمز بیدار شد و آسمان را نگریست. بعد واتسون را بیدار کرد و گفت: \"نگاهی به بالا بینداز و به من بگو چه می بینی؟...\r\n\" واتسون گفت:\"میلیون ها ستاره می بینم\".هلمز گفت: \"چه نتیجه ای می گیری؟\". واتسون گفت: \"از لحاظ روحانی نتیجه می گیرم که خداوند بزرگ است و ما چقدر در این دنیا حقیریم. از لحاظ ستاره شناسی نتیجه می گیرم که زهره در برج مشتری ست، پس باید اوایل تابستان باشد. از لحاظ فیزیکی نتیجه می گیرم که مریخ در محاذات قطب است، پس باید ساعت حدود سه نیمه شب باشد \". \r\nشرلوک هلمز قدری فکر کرد و گفت: \"واتسون! تو احمقی بیش نیستی! نتیجه ی اول و مهمی که باید بگیری این است که چادر ما را دزدیده اند.\r\n"},{"id":1452,"category_id":10,"category_code":"s10","source_id":14,"title":"درخواست از فرشته","content":"یه زوج ۶۰ ساله به مناسبت سی و پنجمین سالگرد ازدواجشون رفته بودند بیرون که یه جشن کوچیک دو نفره بگیرن. وقتی توی پارک زیر یه درخت نشسته بودند یهو یه فرشتهء کوچیک خوشگل جلوشون ظاهر شد و گفت: به خاطر اینکه شما همیشه یه زوج فوق العاده بودین و تمام مدت به همدیگه وفادار بودین من برای هر کدوم از شما یه دونه آرزو برآورده میکنم.\r\nزن از خوشحالی پرید بالا و گفت: اوه! چه عالی! من میخوام همراه شوهرم به یه سفر دور دنیا بریم. فرشته چوب جادوییش رو تکون داد و پوف! دو تا بلیط درجه اول برای بهترین تور مسافرتی دور دنیا توی دستهای زن ظاهر شد!\r\nحالا نوبت شوهر بود که آرزو کنه. مرد چند لحظه فکر کرد و گفت:....\r\nخب… این خیلی رمانتیکه. ولی چنین بخت و شانسی فقط یه بار توی زندگی آدم پیش میاد. بنابراین خیلی متاسفم عزیزم… آرزوی من اینه که یه همسری داشته باشم که ۳۰ سال از من کوچیکتر باشه!\r\nزن و فرشته جا خوردند و خیلی دلخور شدند. ولی آرزو آرزوئه. و باید برآورده بشه.\r\nفرشته چوب جادوییش رو تکون داد و پوف! مرد ۹۰ سالش شد!\r\nنتیجهء اخلاقی: مردها ممکنه زرنگ و  بدجنس باشند ، ولی فرشته ها زن هستند.\r\n"},{"id":1453,"category_id":10,"category_code":"s10","source_id":15,"title":"فرشته کوچک ","content":"درِ مطب دکتر به شدت به صدا درآمد. دکتر گفت در را شکستی! بیا تو. در باز شد و دختر کوچولوی نه ساله ای که خیلی پریشان بود به طرف دکتر دوید و گفت : آقای دکتر! مادرم! مادرم! و در حالی که نفس نفس میزد ادامه داد : التماس میکنم با من بیایید، مادرم خیلی مریض است. دکتر گفت :...\r\nباید مادرت را اینجا بیاوری، من برای ویزیت به خانه کسی نمیروم. دختر گفت : ولی دکتر، من نمیتوانم، اگر شما نیایید او میمیرد! و اشک از چشمانش سرازیر شد. \r\nدل دکتر به رحم آمد و تصمیم گرفت همراه او برود. دختر، دکتر را به طرف خانه راهنمایی کرد، جایی که مادر بیمارش در رختخواب افتاده بود. دکتر شروع کرد به معاینه و توانست با آمپول و قرص، تب او را پایین بیاورد و نجاتش دهد. او تمام شب را بر بالین زن ماند، تا صبح که علایم بهبودی در او دیده شد. زن به سختی چشمانش را باز کرد و از دکتر به خاطر کاری که کرده بود تشکرکرد. دکتر به او گفت : باید از دخترت تشکر کنی، اگر او نبود حتماً میمردی! مادر با تعجب گفت : ولی دکتر، دختر من سه سال است که از دنیا رفته! و به عکس بالای تختش اشاره کرد. پاهای دکتر از دیدن عکس روی دیوار سست شد. این همان دختر بود! یک فرشته کوچک و زیبا.\r\n"},{"id":1454,"category_id":10,"category_code":"s10","source_id":16,"title":"مار را چگونه باید نوشت؟ ","content":"روستایی بود دور افتاده که مردم ساده دل و بی سوادی در آن سکونت داشتند. مردی شیاد از ساده لوحی آنان استفاده کرده و بر آنان به نوعی حکومت می کرد. برحسب اتفاق گذر یک معلم به آن روستا افتاد و متوجه دغلکاری های شیاد شد و او را نصیحت کرد که از اغفال مردم دست بردارد و گرنه او را رسوا می کند. اما مرد شیاد نپذیرفت. بعد از اتمام حجت٬ معلم با مردم روستا از فریبکاری های شیاد سخن گفت و نسبت به حقه های او هشدار داد. بعد از کلی مشاجره بین معلم و شیاد قرار بر این شد که فردا در میدان روستا معلم و مرد شیاد مسابقه بدهند تا معلوم شود کدامیک باسواد و کدامیک بی سواد هستند.\r\nدر روز موعود همه مردم روستا در میدان ده گرد آمده بودند تا ببینند آخر کار، چه می شود.\r\nشیاد به معلم گفت: بنویس «مار» \r\nمعلم نوشت: مار \r\nنوبت شیاد که رسید شکل مار را روی خاک کشید. \r\nو به مردم گفت: شما خود قضاوت کنید کدامیک از اینها مار است؟ \r\nمردم که سواد نداشتند متوجه نوشته مار نشدند اما همه شکل مار را شناختند و به جان معلم افتادند تا می توانستند او را کتک زدند و از روستا بیرون راندند. \r\nشرح حکایت \r\nاگر می خواهیم بر دیگران تأثیر بگذاریم یا آنها را با خود همراه کنیم بهتر است با زبان، رویکرد و نگرش خود آنها، با آنها سخن گفته و رفتار کنیم. همیشه نمی توانیم با اصول و چارچوب فکری خود دیگران را مدیریت کنیم. باید افکار و مقاصد خود را به زبان فرهنگ، نگرش، اعتقادات، آداب و رسوم و پیشینه آنان ترجمه کرد و به آنها داد.\r\n"},{"id":1455,"category_id":10,"category_code":"s10","source_id":17,"title":"کفن دزد","content":"آورده اند که کفن دزدی در بستر مرگ افتاده بود،پسر خویش را فراخواند، پسر به نزد پدر رفت گفت ای پدر امرت چیست ؟پدر گفت ،پسرم من تمام عمر به کفن دزدی مشغول بودم و همواره نفرین خلقی بدنبالم بود اکنون که در بستر مرگم و فرشتهءمرگ را نزدیک حس میکنم بار این نفرین بیش از پیش بردوشم سنگینی میکند.از تو میخواهم بعد از مرگم چنان کنی که خلایق مرا دعا کنند و از خدای یکتا مغفرت مرا خواهند.\r\nسر گفت ای پدر چنان کنم که میخواهی و از این پس مرد و زن را به دعایت مشغول سازم\r\nپدر همان دم جان به جان آفرین تسلیم کرد.\r\nاز فردا پسر شغل پدر پیشه کرد با این تفاوت که کفن از مردگان خلایق می دزدید و چوبی در شکم آن مردگان فرو مینمود وازآن پس خلایق میگفتند خدا کفن دزد اول را بیامرزد که فقط میدزدید وچنین بر مردگان ما روا نمیداشت.‬‬\r\n"},{"id":1456,"category_id":10,"category_code":"s10","source_id":18,"title":"سه قطعه ی معیوب","content":"درباره کیفیت محصولات و استانداردهای کیفیت در ژاپن بسیار شنیده اید. این داستان هم که در مورد شرکت آی بی ام اتفاق افتاده در نوع خود شنیدنی است. چند سال پیش، آی بی ام تصمیم گرفت که تولید یکی از قطعات کامپیوترهایش را به ژاپنیها بسپارد. در مشخصات تولید محصول نوشته بود: سه قطعه معیوب در هر 10000 قطعه ای که تولید می شود قابل قبول است. هنگامیکه قطعات تولید شدند و...\r\nبرای آی بی ام فرستاده شدند، نامه ای همراه آنها بود با این مضمون «مفتخریم که سفارش شما را سر وقت آماده کرده و تحویل می دهیم. برای آن سه قطعه معیوبی هم که خواسته بودید خط تولید جداگانه ای درست کردیم و آنها را هم ساختیم. امیدواریم این کار رضایت شما را فراهم سازد.\r\n"},{"id":1457,"category_id":10,"category_code":"s10","source_id":19,"title":"ارزیابی خود","content":"پسر کوچکی وارد مغازه ای شد، جعبه نوشابه را به سمت تلفن هل داد. بر روی جعبه رفت تا دستش به دکمه های تلفن برسد و شروع کرد به گرفتن شماره. مغازه دار متوجه پسر بود و به مکالماتش گوش می داد.\r\nپسرک پرسید: \"خانم، می توانم خواهش کنم کوتاه کردن چمن های حیاط خانه تان را به من بسپارید؟\"\r\nزن پاسخ داد: \"کسی هست که این کار را برایم انجام می دهد.\" \r\nپسرک گفت: \"خانم، من این کار را با نصف قیمتی که او می دهد انجام خواهم داد\"\r\nزن در جوابش گفت که از کار این فرد کاملا راضی است.\r\nپسرک بیشتر اصرار کرد و پیشنهاد داد: «خانم، من پیاده رو و جدول جلوی خانه را هم برایتان جارو می کنم. در این صورت شما در یکشنبه زیباترین چمن را در کل شهر خواهید داشت.» مجددا زن پاسخش منفی بود.\r\nپسرک در حالی که لبخندی بر لب داشت، گوشی را گذاشت. مغازه دار که به صحبت های او گوش داده بود به سمتش رفت و گفت: پسر...، از رفتارت خوشم آمد؛ به خاطر اینکه روحیه خاص و خوبی داری دوست دارم کاری به تو بدهم. \r\nپسر جوان جواب داد: \"نه ممنون، من فقط داشتم عملکردم را می سنجیدم. من همان کسی هستم که برای این خانم کار می کند.\"\r\n"},{"id":1458,"category_id":10,"category_code":"s10","source_id":20,"title":"تیمارستان ","content":"مردی در هنگام رانندگی، درست جلوی حیاط یک تیمارستان پنچر شد و مجبورشد همانجا به تعویض لاستیک بپردازد\r\nهنگامی که سرگرم این کار بود، ماشین دیگری به سرعت ازروی مهره های چرخ که در کنار ماشین بودند گذشت و آنها را به درون جوی آب انداخت و آب مهره ها را برد\r\nمرد حیران مانده بود که چکار کند. تصمیم گرفت که ماشینش را همانجارها کند و برای خرید مهره چرخ برود\r\nدر این حین، یکی از دیوانه ها که از پشت نرده های حیاط تیمارستان نظاره گر این ماجرا بود، او را صدا زد و گفت:\r\nاز ٣ چرخ دیگر ماشین، از هر کدام یک مهره بازکن و این لاستیک را با ٣ مهره ببند و برو تا به تعمیرگاه برسی.\r\nآن مرد اول توجهی به این حرف نکرد ولی بعد که با خودش فکر کرد دید راست می گوید و بهتر است همین کار را بکند.\r\nپس به راهنمایی او عمل کرد و لاستیک زاپاس را بست.\r\nهنگامی که خواست حرکت کند رو به آن دیوانه کرد و گفت: «خیلی فکر جالب و هوشمندانه ای داشتی. \r\nپس چرا توی تیمارستان انداختنت؟\r\nدیوانه لبخندی زد و گفت: من اینجام چون دیوانه ام. ولی احمق که نیستم!\r\n"},{"id":1459,"category_id":10,"category_code":"s10","source_id":21,"title":"راز خوشبختی ","content":"تاجری پسرش را برای آموختن «راز خوشبختی» نزد خردمندی فرستاد. پسر جوان چهل روز تمام در صحرا راه رفت تا اینکه سرانجام به قصری زیبا بر فراز قله کوهی رسید. مرد خردمندی که او در جستجویش بود آنجا زندگی می‌کرد.\r\nبه جای اینکه با یک مرد مقدس روبه رو شود وارد تالاری شد که جنب و جوش بسیاری در آن به چشم می‌خورد، فروشندگان وارد و خارج می‌شدند، مردم در گوشه‌ای گفتگو می‌کردند، ارکستر کوچکی موسیقی لطیفی می‌نواخت و روی یک میز انواع و اقسام خوراکی‌ها لذیذ چیده شده بود. خردمند با این و آن در گفتگو بود و جوان ناچار شد دو ساعت صبر کند تا نوبتش فرا رسد.\r\nخردمند با دقت به سخنان مرد جوان که دلیل ملاقاتش را توضیح می‌داد گوش کرد اما به او گفت که فعلأ وقت ندارد که «راز خوشبختی» را برایش فاش کند. پس به او پیشنهاد کرد که گردشی در قصر بکند و حدود دو ساعت دیگر به نزد او بازگردد.\r\nمرد خردمند اضافه کرد:\r\n اما از شما خواهشی دارم. آنگاه یک قاشق کوچک به دست پسر جوان داد و دو قطره روغن در آن ریخت و گفت: در تمام مدت گردش این قشق را در دست داشته باشید و کاری کنید که روغن آن نریزد.\r\nمرد جوان شروع کرد به بالا و پایین کردن پله‌ها، در حالیکه چشم از قاشق بر نمی‌داشت. دو ساعت بعد نزد خردمند بازگشت.\r\nمرد خردمند از او پرسید:«آیا فرش‌های ایرانی اتاق نهارخوری را دیدید؟ آیا باغی که استاد باغبان ده سال صرف آراستن آن کرده است دیدید؟ آیا اسناد و مدارک ارزشمند مرا که روی پوست آهو نگاشته شده دیدید؟»\r\nجوان با شرمساری اعتراف کرد که هیچ چیز ندیده، تنها فکر او این بوده که قطرات روغنی را که خردمند به او سپرده بود حفظ کند.\r\nخردمند گفت: «خب، پس برگرد و شگفتی‌های دنیای من را بشناس. آدم نمی‌تواند به کسی اعتماد کند، مگر اینکه خانه‌ای را که در آن سکونت دارد بشناسد.»\r\nمرد جوان این‌بار به گردش در کاخ پرداخت، در حالیکه همچنان قاشق را به دست داشت، با دقت و توجه کامل آثار هنری را که زینت بخش دیوارها و سقف‌ها بود می‌نگریست. او باغ‌ها را دید و کوهستان‌های اطراف را، ظرافت گل‌ها و دقتی را که در نصب آثار هنری در جای مطلوب به کار رفته بود تحسین کرد. وقتی به نزد خردمند بازگشت همه چیز را با جزئیات برای او توصیف کرد.\r\nخردمند پرسید: «پس آن دو قطره روغنی را که به تو سپردم کجاست؟»\r\nمرد جوان قاشق را نگاه کرد و متوجه شد که آنها را ریخته است.\r\nآن وقت مرد خردمند به او گفت:\r\n«راز خوشبختی این است که همه شگفتی‌های جهان را بنگری بدون اینکه دو قطره روغن داخل قاشق را فراموش کنی»\r\n"},{"id":1460,"category_id":10,"category_code":"s10","source_id":22,"title":"اصل موضوع را فراموش نکن ","content":"مرد قوی هیکل ، در چوب بری استخدام شد و تصمیم گرفت خوب کار کند .\r\nروز اول 18 درخت برید . رئیسش به او تبریک گفت و او را به ادامه کار تشویق کرد . روز بعد با انگیزه بیشتری کار کرد ، ولی 15 درخت برید .\r\nروز سوم بیشتر کار کرد ، اما فقط 10 درخت برید . به نظرش آمد که ضعیف شده است . نزدیکش رفت و...\r\nعذر خواست و گفت : نمی دانم چرا هر چه بیشتر تلاش می کنم ، درخت کمتری می برم\r\nرئیس پرسید : آخرین بار کی تبرت را تیز کردی ؟\r\nاو گفت : برای این کار وقت نداشتم . تمام مدت مشغول بریدن درختان بودم\r\n"},{"id":1461,"category_id":10,"category_code":"s10","source_id":23,"title":"ایرانی باهوش ","content":"همین چند هفته پیش بود که یک ایرانی داخل بانک در منهتن نیویورک شد و یک شماره از دستگاه گرفت.\r\nوقتی شماره اش از بلندگو اعلام شد بلند شد و پیش کارشناس بانک رفت و گفت که برای مدت دو هفته قصد سفر تجاری به اروپا را داره و به همین دلیل نیاز به یک وام فوری بمبلغ 5000 دلار داره\r\nکارشناس نگاهی به تیپ و لباس موجه مرد کرد و گفت که برای اعطای وام نیاز به قدری وثیقه و گارانتی داره..\r\nو مرد هم سریع دستش را کرد توی جیبش و کلید ماشین فراری جدیدش را که دقیقا جلوی در بانک پارک کرده بود را به کارشناس داد و رئیس بانک هم پس از تطابق مشخصات مالک خودرو بالاخره با وام آقا موافقت کرد آنهم فقط برای دو هفته .\r\nکارمند بانک هم سریع کلید ماشین گرانقیمت را گرفت و...\r\nماشین به پارکینگ بانک در طبقه پائین انتقال داد.\r\nخلاصه مرد بعد از دو هفته همانطور که قرار بود برگشت 5000 دلار + 15.86دلار کارمزد وام رو پرداخت کرد..\r\nکارشناس رو به مرد کرد و از قول رئیس بانک گفت \" از اینکه بانک ما رو انتخاب کردید متشکریم\"\r\nو گفت ما چک کردیم ومعلوم شد که شما یک مولتی میلیونر هستید ولی فقط من یک سوال برام باقی مانده که با این همه ثروت چرا به خودتون زحمت دادین که 5000 دلار از ما وام گرفتید؟\r\nایرونی یه نگاهی به کارشناس بیچاره کرد و گفت: تو فقط به من بگو کجای نیویورک میتونم ماشین 250.000 دلاری رو برای 2 هفته یا اطمینان خاطر با فقط 15.86 دلار پارک کنم.\r\n"},{"id":1462,"category_id":10,"category_code":"s10","source_id":24,"title":"بدتر از بد","content":"پدر در حال رد شدن از کنار اتاق خواب پسرش بود،\r\nبا تعجب دید که تخت خواب کاملاً مرتب و همه چیز جمع و جور شده.\r\nیک پاکت هم به روی بالش گذاشته شده و روش نوشته بود «پدر».\r\nبا بدترین پیش داوری های ذهنی پاکت رو باز کرد و با دستان لرزان نامه رو خوند:....\r\nپدر عزیزم\r\nبا اندوه و افسوس فراوان برایت می نویسم، من مجبور بودم با دوست دختر جدیدم فرار کنم، چون می خواستم جلوی رویایی با مادر و تو رو بگیرم، من احساسات واقعی رو با ماریا پیدا کردم، او واقعا معرکه است، اما می دانستم که تو اون رو نخواهی پذیرفت، به خاطر تیزبینی هاش، خالکوبی هاش، لباسهای تنگ موتورسواریش و به خاطر اینکه سنش از من خیلی بیشتره، این فقط یه احسسات نیست... ماریا به من گفت می تونیم شاد و خوشبخت بشیم، اون یکی تریلی توی جنگل داره و کلی هیزم برای تمام زمستون، ما یک رویای مشترک داریم برای داشتن تعدادی بچه، ماریا چشمان من رو به حقیقت باز کرد که ماریجونا واقعا به کسی صدمه نمی زنه. ما اون رو برای خودمون می کاریم و برای تجارت با کمک آدمای دیگه که تو مزرعه هستن، برای معامله با کوکائین و اکستازی احتیاج داریم، فقط به اندازه مصرف خودمون، در ضمن دعا می کنیم که علم بتونه درمانی برای ایدز پیدا کنه و ماریا بهتر بشه. اون لیاقتش رو داره . نگران نباش پدر من 15 سالمه و می دونم چطور از خودم رقابت کنم یک روز مطمئنم که برای دیدار تون بر می گردم و اونوقت تو می تونی نوه های زیادت رو ببینی\r\nبا عشق پسرت جان\r\nپاورقی، پدر هیچ کدوم از جریانات بالا واقعی نبود من بالا هستم خونه دوستم تامی فقط می خواستم بهت یاداوری کنم که در دنیا چیزهای بدتری هم هست نسبت به کارنامه مدرسه که روی میزمه \r\nدوستت دارم\r\nهر وقت برای اومدن به خونه امن بود بهم زنگ بزن.\r\n"},{"id":1463,"category_id":10,"category_code":"s10","source_id":25,"title":"حکایت موسی و بهشت ","content":"روزی حضرت موسی در خلوت خویش از خدایش سئوال می کند : آیا کسی هست که با من وارد بهشت گردد ؟ خطاب میرسد : آری ! موسی با حیرت می پرسد : آن شخص کیست ؟ خطاب میرسد : او مرد قصابی است در فلان محله ، موسی می پرسد : میتوانم به دیدن او بروم ؟ خطاب میرسد : مانعی ندارد !\r\nفردای آن روز موسی به محل مربوطه رفته و مرد قصاب را ملاقات می کند و می گید : من مسافری گم کرده راه هستم ، آیا می توانم شبی را مهمان تو باشم ؟ قصاب در جواب می گوید : مهمان حبیب خداست ، لختی بنشین تا کارم را انجام دهم ، آن گاه با هم به خانه می رویم ، موسی با کنجکاوی وافری به حرکات مرد قصاب می نگرد و می بیند که او قسمتی از گوشت ران گوسفند را برید و قسمتی از جگر آنرا جدا کرد در پارچه ای پیچید و...\r\nکنار گذاشت . ساعاتی بعد قصاب می گوید : کار من تمام است برویم ، سپس با موسی به خانه قصاب می روند و به محض ورود به خانه ، رو به موسی کرده و می گوید : لحظه ای تامل کن ! موسی مشاهده می کند که طنابی را به درختی در حیاط بسته ، آنرا باز کرده و آرام آرام طناب را شل کرد . شیئی در وسط توری که مانند تورهای ماهیگیری بود نظر موسی را به خودجلب کرد ، وقتی تور به کف حیاط رسید ، پیرزنی را در میان آن دید با مهربانی دستی بر صورت پیرزن کشید ، سپس با آرامش و صبر و حوصله مقداری غذا به  او داد ، دست و صورت او را تمیز کرد و خطاب به پیرزن گفت : مادرجان دیگر کاری نداری ، و پیرزن می گوید : پسرم ان شاءالله که در بهشت همنشین موسی شوی .\r\n سپس قصاب پیرزن را مجدداً در داخل تور نهاده بر بالای درخت قرارداده و پیش موسی آمده و با تبسمی می گوید : او مادر من است و آن قدر پیر شده که مجبورم او را این گونه نگهداری کنم  و از همه جالب تر آن که همیشه این دعا را برای من می خواند که \" انشاء الله در بهشت با موسی همنشین شوی ! \" \r\nچه دعایی !! آخر من کجا و بهشت کجا ؟ آن هم با موسی ! \r\nموسی لبخندی می زند و به قصاب می گوید : من موسی هستم و تویقیناً به خاطر دعای مادر در بهشت همنشین من خواهی شد ! \r\n"},{"id":1464,"category_id":10,"category_code":"s10","source_id":26,"title":"مدیران جدید","content":"پنج آدمخوار در یک شرکت استخدام شدند. \r\nهنگام مراسم خوشامدگویی رئیس شرکت گفت: \"شما همه جزو تیم ما هستید. شما اینجا حقوق خوبی می گیرید و میتوانید به غذاخوری شرکت رفته و هر مقدار غذا که دوست داشتید بخورید. بنابراین فکر کارکنان دیگر را از سر خود بیرون کنید.\" \r\nآدمخوارها قول دادند که با کارکنان شرکت کاری نداشته باشند. \r\nچهار هفته بعد رئیس شرکت به آنها سر زد و گفت: \"می دانم که شما خیلی  سخت کار میکنید. من از همه شما راضی هستم. امّا یکی از نظافتچی های ما ناپدید شده است. کسی از شما میداند که چه اتفاقی برای او افتاده است؟\"\r\nآدمخوارها اظهار بی اطلاعی کردند\r\nبعد از اینکه رئیس شرکت رفت، رهبر آدمخوارها از بقیه  پرسید: \r\n\" کدوم یک از شما نادونا اون نظافت چی رو خورده ؟\" \r\nیکی از آدمخوارها با اکراه دستش را بالا آورد. رهبر آدمخوارها گفت:\r\n\"ای احمق ! طی این چهار هفته ما مدیران، مسئولان و مدیران پروژه ها را خوردیم و هیچ کس چیزی نفهمید و حالا تو اون آقا را خوردی و رئیس متوجه شد! از این به بعد لطفاً افرادی را که کار میکنند نخورید...\"\r\n"},{"id":1465,"category_id":10,"category_code":"s10","source_id":27,"title":"اصل موضوع را فراموش نکن ","content":"خانمی طوطی ای خرید . اما روز بعد آن را به مغازه برگرداند. او به صاحب مغازه گفت این پرنده صحبت نمی کند . صاحب مغازه گفت : آیا در قفسش آینه ای هست ؟ طوطی ها عاشق آینه هستند ، آن ها تصویرشان را در آینه می بینند و شروع به صحبت می کنند . آن خانم یک آینه خرید و رفت .\r\nروز بعد باز آن خانم برگشت . طوطی هنوز صحبت نمی کرد . صاحب مغازه پرسید : نردبان چه ؟ آیا در قفسش نردبانی هست ؟ طوطی ها عاشق نردبان هستند. آن خانم یک نردبان خرید و رفت .\r\nاما روز بعد باز هم آن خانم آمد .\r\nصاحب مغازه گفت : آیا طوطی شما در قفسش تاب دارد ؟ نه ؟ خب مشکل همین است . به محض این که شروع به تاب خوردن کند ، حرف زدنش تحسین همه را بر می انگیزد . آن خانم با بی میلی یک تاب خرید و رفت .\r\nوقتی که آن خانم روز بعد وارد مغازه شد ، چهره اش کاملأ تغییر کرده بود . او گفت : طوطی مرد .\r\nصاحب مغازه شوکه شد و پرسید : آیا او حتی یک کلمه هم حرف نزد ؟ آن خانم پاسخ داد  چرا ، درست قبل از مردنش با صدای ضعیفی گفت آیا در آن مغازه غذایی برای طوطی ها نمی فروختند ؟\r\n"},{"id":1466,"category_id":10,"category_code":"s10","source_id":28,"title":"استخدام ","content":"یک شرکت بزرگ قصد استخدام یک نفر را داشت. بدین منظور آزمونی برگزار کرد که یک پرسش داشت. پرسش این بود:\r\nشما در یک شب طوفانی در حال رانندگی هستید. از جلوی یک ایستگاه اتوبوس می‌گذرید. سه نفر داخل ایستگاه منتظر اتوبوس هستند. یک پیرزن که در حال مرگ است. یک پزشک که قبلاً جان شما را نجات داده است. یک خانم/آقا که در رویاهایتان خیال ازدواج با او را دارید. شما می‌توانید تنها یکی از این سه نفر را سوار کنید. کدام را انتخاب خواهید کرد؟ دلیل خود را شرح دهید...\r\nقاعدتاً این آزمون نمی‌تواند نوعی تست شخصیت باشد زیرا هر پاسخی دلیل خودش را دارد.\r\nپیرزن در حال مرگ است، شما باید ابتدا او را نجات دهید. هر چند او خیلی پیر است و به هر حال خواهد مرد.\r\nشما باید پزشک را سوار کنید. زیرا قبلاً جان شما را نجات داده است و این فرصتی است که می‌توانید جبران کنید. اما شاید هم بتوانید بعداً جبران کنید.\r\nشما باید شخص مورد علاقه‌تان را سوار کنید زیرا اگر این فرصت را از دست دهید ممکن است هرگز قادر نباشید مثل او را پیدا کنید.\r\nاز دویست نفری که در این آزمون شرکت کردند، شخصی که استخدام شد دلیلی برای پاسخ خود نداد. او نوشته بود:\r\nسوئیچ ماشین را به پزشک می‌دهم تا پیرزن را به بیمارستان برساند و خودم به همراه همسر رویاهایم منتظر اتوبوس می‌مانیم.\r\n"},{"id":1467,"category_id":10,"category_code":"s10","source_id":29,"title":"باور ها ","content":"در یک باشگاه بدنسازی پس از اضافه کردن 5 کیلوگرم به رکورد قبلی ورزشکاری از وی خواستند که رکورد جدیدی برای خود ثبت کند. اما او موفق به این کار نشد. پس از او خواستند وزنه ای که 5 کیلوگرم از رکوردش کمتر است را امتحان کند. این دفعه او براحتی وزنه را بلند کرد. این مسئله برای ورزشکار جوان و دوستانش امری کاملا طبیعی به نظر می رسید.\r\nاما برای طراحان این آزمایش جالب و هیجان انگیز بود چرا که آنها اطلاعات غلط به وزنه بردار داده بودند. او در مرحله اول از عهده بلند کردن وزنه ای برنیامده بود که در واقع 5 کیلوگرم از رکوردش کمتر بود و در حرکت دوم ناخودآگاه موفق به بهبود رکوردش به میزان 5 کیلوگرم شده بود. او در حالی و با این «باور» وزنه را بلند کرده بود که خود را قادر به انجام آن می‌دانست.\r\n\r\nنتیجه‌گیری:\r\nهر فردی خود را ارزیابی می‌کند و این برآورد مشخص خواهد ساخت که او چه خواهد شد. شما نمی‌توانید بیش از آن چیزی بشوید که باور دارید «هستید». اما بیش از آنچه باور دارید «می‌توانید» انجام دهید.\r\n"},{"id":1468,"category_id":10,"category_code":"s10","source_id":30,"title":"سگ و قصاب ","content":"قصاب با دیدن سگی که به طرف مغازه اش نزدیک می شد حرکتی کرد که دورش کند اما کاغذی را در دهان سگ  دید .کاغذ را گرفت.روی کاغذ نوشته بود\" لطفا ۱۲ سوسیس و یه ران گوشت بدین\".۱۰ دلار همراه کاغذ بود.قصاب که تعجب کرده بود  سوسیس و گوشت را در کیسه ای گذاشت و در دهان سگ گذاشت. سگ هم کیسه راگرفت و رفت .\r\nقصاب که کنجکاو شده بود و از طرفی وقت بستن مغازه بود تعطیل کرد و بدنبال سگ راه افتاد .\r\nسگ  در خیابان  حرکت کرد تا به محل خط کشی رسید. با حوصله ایستاد تا  چراغ سبز شد و  بعد از خیابان رد شد. قصاب به دنبالش راه افتاد. سگ رفت تا به ایستگاه اتوبوس رسید نگاهی به تابلو  حرکت اتوبوس ها کرد و ایستاد .قصاب متحیر از حرکت سگ منتظر ماند.\r\nاتوبوس امد, سگ جلوی اتوبوس امد و شماره انرا نگاه کرد و به ایستگاه برگشت .صبر کرد تا اتوبوس بعدی امد دوباره شماره انرا چک کرد. اتوبوس درست بود سوار شد.قصاب هم در حالی که دهانش از حیرت باز بود سوار شد.\r\nاتوبوس در حال حرکت به سمت  حومه شهر  بود وسگ منظره بیرون را تماشا می کرد .پس از چند خیابان سگ روی پنجه باند شد و زنگ اتوبوس را زد .اتوبوس ایستاد و سگ با کیسه پیاده شد.قصاب هم به دنبالش.\r\nسگ در خیابان حرکت کرد تا به خانه ای رسید .گوشت را روی پله گذاشت و   کمی عقب رفت و خودش را به در  کوبید .اینکار را بازم تکرار کرد اما کسی در را باز نکرد.\r\nسگ به طرف محوطه باغ رفت   و روی دیواری باریک پرید و خودش را به پنجره رساند و سرش را چند بار به پنجره زد و بعد به پایین پرید و به پشت در برگشت.\r\nمردی  در را باز کرد و شروع  به فحش دادن  و تنبیه  سگ و کرد.قصاب با عجله به مرد نزدیک شد و داد زد :چه کار می کنی دیوانه؟ این سگ یه نابغه است. این باهوش ترین سگی هست که من تا بحال دیدم.\r\nمرد نگاهی به قصاب کرد و گقت:تو به این میگی باهوش ؟این دومین بار تو این هفته است که این احمق کلیدش را فراموش می کنه !!!\r\n\r\nنتیجه اخلاقی :\r\n\r\nاول اینکه مردم هرگز از چیزهایی که دارند راضی نخواهند بود.\r\nو دوم اینکه چیزی که شما انرا بی ارزش می دانید بطور قطع برای کسانی دیگر ارزشمند و غنیمت است .\r\nسوم اینکه بدانیم دنیا پر از این تناقضات است.\r\nپس سعی کنیم ارزش واقعی هر چیزی را درک کنیم و مهمتر اینکه قدر داشته های مان را بدانیم.\r\n"},{"id":1469,"category_id":10,"category_code":"s10","source_id":31,"title":"اول رییس","content":"یه روز مسوول فروش ، منشی دفتر ، و مدیر شرکت برای ناهار به سمت سلف قدم می زدند... یهو یه چراغ جادو روی زمین پیدا می کنن و روی اون رو مالش میدن و جن چراغ ظاهر میشه... جن میگه: من برای هر کدوم از شما یک آرزو برآورده می کنم... منشی می پره جلو و میگه: اول من ، اول من...!\r\nمن می خوام که توی باهاماس باشم ، سوار یه قایق بادبانی شیک باشم و هیچ نگرانی و غمی از دنیا نداشته باشم... پوووف!\r\n منشی ناپدید میشه... بعد مسوول فروش می پره جلو و میگه: «حالا من ، حالا من!... من می خوام توی هاوایی کنار ساحل لم بدم ، یه ماساژور شخصی و یه منبع بی انتهای آبجو داشته باشم و تمام عمرم حال کنم»... پوووف! مسوول فروش هم ناپدید میشه... بعد جن به مدیر میگه: حالا نوبت توئه... مدیر میگه: من می خوام که اون دو تا هر دوشون بعد از ناهار توی شرکت باشن!\r\n"},{"id":1470,"category_id":10,"category_code":"s10","source_id":32,"title":"شام آخر ","content":"لئوناردو داوینچی هنگام کشیدن تابلوی شام آخر دچار مشکل بزرگی شد: می‌بایست نیکی را به شکل عیسی و بدی را به شکل یهودا، از یاران مسیح که هنگام شام تصمیم گرفت به او خیانت کند، تصویر می‌کرد. کار را نیمه تمام رها کرد تا مدل‌های آرمانیش را پیدا کند.\r\nروزی در یک مراسم همسرایی، تصویر کامل مسیح را در چهره یکی از آن جوانان همسرا یافت. جوان را به کارگاهش دعوت کرد و از چهره‌اش اتودها و طرح‌هایی برداشت.\r\nسه سال گذشت. تابلو شام آخر تقریبأ تمام شده بود....\r\nاما داوینچی هنوز برای یهودا مدل مناسبی پیدا نکرده بود. کاردینال مسئول کلیسا کم کم به او فشار می‌آورد که نقاشی دیواری را زودتر تمام کند.\r\nنقاش پس از روزها جستجو، جوان شکسته و ژنده‌پوش و مستی را در جوی آبی یافت. به زحمت از دستیارانش خواست او را تا کلیسا بیاورند، چون دیگر فرصتی برای طرح برداشتن نداشت.\r\nگدا را که درست نمی‌فهمید چه خبر است، به کلیسا آوردند: دستیاران سرپا نگه‌اش داشتند و در همان وضع، داوینچی از خطوط بی‌تقوایی، گناه و خودپرستی که به خوبی بر آن چهره نقش بسته بودند، نسخه برداری کرد.\r\nوقتی کارش تمام شد، گدا، که دیگر مستی کمی از سرش پریده بود، چشم‌هایش را باز کرد و نقاشی پیش رویش را دید و با آمیزه‌ای از شگفتی و اندوه گفت: «من این تابلو را قبلأ دیده‌ام!»\r\nداوینچی با تعجب پرسید: «کی؟»\r\n- سه سال قبل، پیش از آنکه همه چیزم را از دست بدهم. موقعی که در یک گروه همسرایی آواز می‌خواندم، زندگی پر رویایی داشتم و هنرمندی از من دعوت کرد تا مدل نقاشی چهره عیسی شوم !!!!\r\n"},{"id":1471,"category_id":10,"category_code":"s10","source_id":33,"title":"قهوه تلخ و زندگی ","content":"چند دوست دوران دانشجویی که پس از فارغ التحصیلی هر یک شغل های مختلفی داشتند و در کار و زندگی خود نیز موفق بودند، پس از مدت ها با هم به دانشگاه سابق شان رفتند تا با استادشان دیداری تازه کنند. \r\n\r\nآنها مشغول صحبت شده بودند و طبق معمول بیشتر حرف هایشان هم شکایت از زندگی بود. استادشان در حین صحبت آنها قهوه آماده می کرد. او قهوه جوش را روی میز گذاشت و از دانشجوها خواست که برای خود قهوه بریزند. \r\n\r\nروی میز لیوان های متفاوتی قرار داشت; شیشه ای، پلاستیکی، چینی، بلور و لیوان های دیگر. وقتی همه دانشجوها قهوه هایشان را ریخته بودند و هر یک لیوانی در دست داشت، استاد مثل همیشه آرام و با مهربانی گفت:\r\nبچه ها، ببینید; همه شما لیوان های ظریف و زیبا را انتخاب کردید و الان فقط لیوان های زمخت و ارزانقیمت روی میز مانده اند. \r\n\r\nدانشجوها که از حرف های استاد شگفت زده شده بودند، ساکت بودند و استاد حرف هایش را به این ترتیب ادامه داد: «در حقیقت، چیزی که شما واقعا می خواستید قهوه بود و نه لیوان. اما لیوان های زیبا را انتخاب کردید و در عین حال نگاه تان به لیوان های دیگران هم بود. زندگی هم مانند قهوه است و شغل، حقوق و جایگاه اجتماعی ظرف آن است. این ظرف ها زندگی را تزیین می کنند اما کیفیت آن را تغییر نخواهند داد. \r\n\r\nالبته لیوان های متفاوت در علاقه شما به نوشیدن قهوه تاثیر خواهند گذاشت، اما اگر بیشتر توجه تان به لیوان باشد و چیزهای با ارزشی مانند کیفیت قهوه را فراموش کنید و از بوی آن لذت نبرید، معنی واقعی نوشیدن قهوه را هم از دست خواهید داد. پس، از حالا به بعد تلاش کنید نگاه تان را از لیوان بردارید و در حالیکه چشم هایتان را بسته اید، از نوشیدن قهوه لذت ببرید.\r\nمشاور"},{"id":1472,"category_id":10,"category_code":"s10","source_id":34,"title":"مشاور","content":"یک مشاور می‌میرد و در آن دنیا در صفی که هزاران نفر جلوی او بودند برای محاسبه اعمالش می‌ایستد. اندکی نگذشته بود که فرشته محاسب میز خود را ترک می‌کند و صف طولانی را طی کرده و به سمت مشاور می‌آید و به گرمی به او سلام کرده و احترام می‌گذارد. فرشته، مشاور را به اول صف برده و او را بر روی مبل راحتی کنار میزش می‌نشاند...\r\nمشاور می‌گوید: \"من از این توجه شما سپاسگزارم، اما چه چیزی باعث شده که این گونه با من رفتار کنید؟\" فرشته محاسب می‌گوید: ما برای افراد مسن احترام ویژه‌ای قائل می‌شویم. ما یک پردازش اولیه بر روی تمامی کارنامه‌های اعمال انجام داده‌ایم و من ساعاتی را که شما به عنوان ساعات مشاوره برای مشتریان خود اعلام کرده‌اید  جمع زدم. بر اساس محاسبه من، شما حداقل 193 سال سن دارید!\r\n"},{"id":1473,"category_id":10,"category_code":"s10","source_id":35,"title":"سفر مجردی","content":"مردی باهمسرش در خانه تماس گرفت و گفت:\"عزیزم ازمن خواسته شده که با رئیس و چند تا از دوستانش برای ماهیگیری به کانادا برویم\"\r\nما به مدت یک هفته آنجا خواهیم بود.این فرصت خوبی است تا ارتقای شغلی که منتظرش بودم بگیرم بنابراین لطفا لباس های کافی برای یک هفته برایم بردار و وسایل ماهیگیری مرا هم آماده کن.\r\nما از اداره حرکت خواهیم کرد و من سر راه وسایلم را از خانه برخواهم داشت ، راستی اون لباس های راحتی ابریشمی آبی رنگم را هم بردار! \r\nزن با خودش فکر کرد که این مساله یک کمی غیرطبیعی است اما بخاطر این که نشان دهد همسر خوبی است دقیقا کارهایی را که همسرش خواسته بود انجام داد.\r\nهفته بعد مرد به خانه آمد ، یک کمی خسته به نظر می رسید اما ظاهرش خوب ومرتب بود.\r\nهمسرش به او خوش آمد گفت و از او پرسید که آیا او ماهی گرفته است یا نه ؟\r\nمرد گفت :\"بله تعداد زیادی ماهی قزل آلا،چند تایی ماهی فلس آبی و چند تا هم اره ماهی گرفتیم . اما چرا اون لباس راحتی هایی که گفته بودم برایم نگذاشتی ؟\" \r\nجواب زن خیلی جالب بود.\r\nزن جواب داد : لباس های راحتی رو توی جعبه وسایل ماهیگیریت گذاشته بودم ؟!\r\n"},{"id":1474,"category_id":10,"category_code":"s10","source_id":36,"title":"قدرت کلام ","content":"روزی مرد کوری روی پله‌های ساختمانی نشسته و کلاه و تابلویی را در کنار پایش قرار داده بود روی تابلو خوانده میشد: من کور هستم لطفا کمک کنید . روزنامه نگارخلاقی از کنار او میگذشت نگاهی به او انداخت فقط چند سکه د ر داخل کلاه بود.او چند سکه داخل کلاه انداخت و بدون اینکه از مرد کور اجازه بگیرد تابلوی او را برداشت ان را برگرداند و اعلان دیگری روی ان نوشت و تابلو را کنار پای او گذاشت و...\r\nآنجا را ترک کرد. عصر انروز روز نامه نگار به ان محل برگشت و متوجه شد که کلاه مرد کور پر از سکه و اسکناس شده است مرد کور از صدای قدمهای او خبرنگار را شناخت و خواست اگر او همان کسی است که ان تابلو را نوشته بگوید ،که بر روی ان چه نوشته است؟روزنامه نگار جواب داد:چیز خاص و مهمی نبود،من فقط نوشته شما را به شکل دیگری نوشتم و لبخندی زد و به راه خود ادامه داد. مرد کور هیچوقت ندانست که او چه نوشته است ولی روی تابلوی او خوانده میشد: \r\nامروز بهار است، ولی من نمیتوانم آنرا ببینم  !!!\r\n"},{"id":1475,"category_id":10,"category_code":"s10","source_id":37,"title":"تله موش ","content":"موش ازشکاف دیوار سرک کشید تا ببیند این همه سروصدا برای چیست ..\r\nمرد مزرعه دار تازه از شهر رسیده بود و بسته ای با خود آورده بود و زنش با خوشحالی مشغول باز کردن بسته بود.\r\nموش لب هایش را لیسید و با خود گفت : کاش یک غذای حسابی باشد  .... \r\nاما همین که بسته را باز کردند ، از ترس تمام بدنش به لرزه افتاد ؛ چون صاحب مزرعه یک تله موش خریده بود.\r\nموش با سرعت به مزرعه برگشت تا این خبر جدید را به همه ی حیوانات بدهد . او به هرکسی که می رسید ، می گفت :« توی مزرعه یک تله موش آورده اند، صاحب مزرعه یک تله موش خریده است .. . . »!\r\nمرغ با شنیدن این خبر بال هایش را تکان داد و گفت : « آقای موش ، برایت متأسفم . از این به بعد خیلی باید مواظب خودت باشی ، به هر حال من کاری به تله موش ندارم ، تله موش هم ربطی به من ندارد.»\r\nمیش وقتی خبر تله موش را شنید ، صدای بلند سرداد و گفت : «آقای موش من فقط می توانم دعایت کنم که توی تله نیفتی ، چون خودت خوب می دانی که تله موش به من ربطی ندارد. مطمئن باش که دعای من پشت و پناه تو خواهد بود.»\r\nموش که از حیوانات مزرعه انتظار همدردی داشت ، به سراغ گاو رفت....\r\n اما گاو هم با شنیدن خبر ، سری تکان داد و گفت : « من که تا حالا ندیده ام یک گاوی توی تله موش بیفتد.!» او این را گفت و زیر لب خنده ای کرد ودوباره مشغول چرید شد.\r\nسرانجام ، موش ناامید از همه جا به سوراخ خودش برگشت و در این فکر بود که اگر روزی در تله موش بیفتد ، چه می شود؟\r\nدر نیمه های همان شب ، صدای شدید به هم خوردن چیزی در خانه پیچید.. زن مزرعه دار بلافاصله بلند شد و به سوی انباری رفت تا موش را که در تله افتاده بود ، ببیند.\r\nاو در تاریکی متوجه نشد که آنچه در تله موش تقلا می کرده ، موش نبود ، بلکه یک مار خطرناکی بود که دمش در تله گیر کرده بود . همین که زن به تله موش نزدیک شد ، مار پایش را نیش زد و صدای جیغ و فریادش به هوا بلند شد. صاحب مزرعه با شنیدن صدای جیغ از خواب پرید و به طرف صدا رفت ، وقتی زنش را در این حال دید او را فوراً به بیمارستان رساند. بعد از چند روز ، حال وی بهتر شد. اما روزی که به خانه برگشت ، هنوز تب داشت . زن همسایه که به عیادت بیمار آمده بود ، گفت :« برای تقویت بیمار و قطع شدن تب او هیچ غذایی مثل سوپ مرغ نیست ..»\r\nمرد مزرعه دار که زنش را خیلی دوست داشت فوراً به سراغ مرغ رفت و ساعتی بعد بوی خوش سوپ مرغ در خانه پیچید.\r\nاما هرچه صبر کردند ، تب بیمار قطع نشد. بستگان او شب و روز به خانه آن ها رفت و آمد می کردند تا جویای سلامتی او شوند. برای همین مرد مزرعه دار مجبور شد ، میش را هم قربانی کند تا باگوشت آن برای میهمانان عزیزش غذا بپزد.\r\nروزها می گذشت و حال زن مزرعه دار هر روز بدتر می شد . تا این که یک روز صبح ، در حالی که از درد به خود می پیچید ، از دنیا رفت و خبر مردن او خیلی زود در روستا پیچید. افراد زیادی در مراسم خاک سپاری او شرکت کردند. بنابراین ، مرد مزرعه دار مجبور شد ، از گاوش هم بگذرد و غذای مفصلی برای میهمانان دور و نزدیک تدارک ببیند.\r\nحالا ، موش به تنهایی در مزرعه می گردید و به حیوانان زبان بسته ای فکر می کرد که کاری به کار تله موش نداشتند!\r\nنتیجه : اگر شنیدی مشکلی برای کسی پیش آمده است و ربطی هم به تو ندارد ، کمی بیشتر فکر کن ؛ شاید خیلی هم بی ربط نباشد ...!!!\r\n"},{"id":1476,"category_id":10,"category_code":"s10","source_id":38,"title":"دوچرخه سواری با خدا ","content":"من در ابتدا خداوند را یک ناظر ؛ مانند یک رئیس یا یک قاضی میدانستم که دنبال شناسائی خطاها ئی است که من انجام داده ام و بدین طریق خداوند میداند وقتی که من مردم ؛ شایسته بهشت هستم و یا مستحق جهنم .\r\n\r\nوقتی قدرت فهم من بیشتر شد؛ به نظرم رسید که گویا زندگی تقریبا مانند دوچرخه سواری با یک دوچرخه دو نفره است و دریافتم که خدا در صندلی عقب در پا زدن به من کمک می⁯کند.\r\n\r\nنمیدانم چه زمانی بود که خدا به من پیشنهاد داد جایمان را عوض کنیم؛ از آن موقع زندگی ام بسیار فرق کرد؛ زندگی ام با نیروی افزوده شده او خیلی بهتر شد؛ وقتی کنترل زندگی دست من بود من راه را می دانستم و تقریبا برایم خسته کننده بود ولی تکراری و قابل پیش بینی و معمولا فاصله ها را از کوتاهترین مسیر می رفتم.\r\n \r\nاما وقتی خدا هدایت زندگی مرا در دست گرفت؛ او بلد بود...\r\nاز میانبرهای هیجان انگیز و از بالای کوهها و از میان صخره ها و با سرعت بسیار زیاد حرکت کند و به من پیوسته می گفت : « تو فقط پا بزن ».\r\n\r\nمن نگران و مظطرب بودم پرسیدم « مرا به کجا می بری ؟ » او فقط خندید و جواب نداد و من کم کم به او اطمینان کردم !\r\n \r\nوقتی می گفتم : « میترسم » . او به عقب بر می⁯گشت و دستانم را می گرفت و من آرام می شدم .\r\n\r\nاو مرا نزد مردمی می⁯برد و آنها نیاز مرا بصورت هدیه می⁯دادند و این سفر ما، یعنی من وخدا ادامه داشت تا از آن مردم دور شدیم .\r\n\r\nخدا گفت : هدیه را به کسانی دیگر بده و آنها بار اضافی سفر زندگی است و وزنشان خیلی زیاد است؛ بنابراین من بار دیگر هدیه⁯ها را به مردمانی دیگر بخشیدم و فهمیدم « دریافت هدیه ها بخاطر بخشیدن های قبلی من بوده است » و با این وجود بار ما در سفر سبک تر است .\r\n\r\nمن در ابتدا در کنترل زندگی ام به خدا اعتماد نکردم؛ فکر می⁯کردم او زندگی ام را متلاشی میکند؛ اما او اسرار دوچرخه سواری « زندگی » را به من نشان داد و خدا می⁯دانست چگونه از راههای باریک مرا رد کند و از جاهای پر از سنگلاخ به جاهای تمیز ببرد و برای عبور از معبرهای ترسناک پرواز کند.\r\n\r\nومن دارم یاد می گیرم که ساکت باشم و در عجیب ترین جاها فقط پا بزنم و من دارم ازدیدن مناظر و برخورد نسیم خنک به صورتم در کنار همراه دائمی خود « خدا » لذت می⁯برم و من هر وقتی نمیتوانم از موانع بگذرم؛ او فقط لبخند می⁯زند و می گوید :  پابزن\r\n"},{"id":1477,"category_id":10,"category_code":"s10","source_id":39,"title":"ابراز عشق ","content":"یک روز آموزگار از دانش آموزانی که در کلاس بودند پرسید آیا می توانید راهی غیر تکراری برای ابراز عشق ، بیان کنید؟ برخی از دانش آموزان گفتند با بخشیدن عشقشان را معنا می کنند.. برخی «دادن گل و هدیه» و «حرف های دلنشین » را راه بیان عشق عنوان کردند. شماری دیگر هم گفتند «با هم بودن در تحمل رنجها و لذت بردن از خوشبختی» را راه بیان عشق می دانند .\r\n در آن بین ، پسری برخاست و پیش از این که شیوه دلخواه خود را برای ابراز عشق بیان کند، داستان کوتاهی تعریف کرد: یک روز زن و شوهر جوانی که هر دو زیست شناس بودند طبق معمول برای تحقیق به جنگل رفتند. آنان وقتی به بالای تپّه رسیدند درجا میخکوب شدند .\r\nیک قلاده ببر بزرگ، جلوی زن و شوهر ایستاده و به آنان خیره شده بود. شوهر، تفنگ شکاری به همراه نداشت و دیگر راهی برای فرار نبود.\r\n\r\nرنگ صورت زن و شوهر پریده بود و در مقابل ببر، جرات کوچک ترین حرکتی نداشتند . ببر، آرام به طرف آنان حرکت کرد. همان لحظه، مرد زیست شناس فریادزنان فرار کرد و همسرش را تنها گذاشت. بلافاصله ببر به سمت شوهر دوید و چند دقیقه بعد ضجه های مرد جوان به گوش زن رسید. ببر رفت و زن زنده ماند .\r\n\r\nداستان به اینجا که رسید دانش آموزان شروع کردند به محکوم کردن آن مرد.\r\n\r\nراوی اما پرسید : آیا می دانید آن مرد در لحظه های آخر زندگی اش چه فریاد می زد؟\r\n\r\nبچه ها حدس زدند حتما از همسرش معذرت خواسته که او را تنها گذاشته است !\r\n\r\nراوی جواب داد: نه، آخرین حرف مرد این بود که «عزیزم ، تو بهترین مونسم بودی.از پسرمان خوب مواظبت کن و به او بگو پدرت همیشه عاشقت بود. ››\r\n\r\nقطره های بلورین اشک، صورت راوی را خیس کرده بود که ادامه داد: همه زیست شناسان می دانند ببر فقط به کسی حمله می کند که حرکتی انجام می دهد و یا فرار می کند. پدر من در آن لحظه وحشتناک ، با فدا کردن جانش پیش مرگ مادرم شد و او را نجات داد. این صادقانه ترین و بی ریاترین ترین راه پدرم برای بیان عشق خود به مادرم و من بود.\r\n"},{"id":1478,"category_id":10,"category_code":"s10","source_id":40,"title":"داستان طرح واکسن امیر کبیر ","content":"در سال 1264 قمری، نخستین برنامه‌ی دولت ایران برای واکسن زدن به فرمان امیرکبیر آغاز شد. در آن برنامه، کودکان و نوجوانانی ایرانی را آبله‌کوبی می‌کردند. اما چند روز پس از آغاز آبله‌کوبی به امیر کبیر خبردادند که مردم از روی ناآگاهی نمی‌خواهند واکسن بزنند.. به‌ویژه که چند تن از فالگیرها و دعانویس‌ها در شهر شایعه کرده بودند که واکسن زدن باعث راه ‌یافتن جن به خون انسان می‌شود هنگامی که خبر رسید پنج نفر به علت ابتلا به بیماری آبله جان باخته‌اند، امیر بی‌درنگ فرمان داد هر کسی که حاضر نشود آبله بکوبد باید پنج تومان به صندوق دولت جریمه بپردازد. او تصور می کرد که با این فرمان همه مردم آبله می‌کوبند. اما نفوذ سخن دعانویس‌ها و نادانی مردم بیش از آن بود که فرمان امیر را بپذیرند. شماری که پول کافی داشتند، ....\r\nپنج تومان را پرداختند و از آبله‌کوبی سرباز زدند. شماری دیگر هنگام مراجعه مأموران در آب انبارها پنهان می‌شدند یا از شهر بیرون می‌رفتند روز بیست و هشتم ماه ربیع الاول به امیر اطلاع دادند که در همه‌ی شهر تهران و روستاهای پیرامون آن فقط سی‌صد و سی نفر آبله کوبیده‌اند. در همان روز، پاره دوزی را که فرزندش از بیماری آبله مرده بود، به نزد او آوردند. امیر به جسد کودک نگریست و آنگاه گفت: ما که برای نجات بچه‌هایتان آبله‌کوب فرستادیم. پیرمرد با اندوه فراوان گفت: حضرت امیر، به من گفته بودند که اگر بچه را آبله بکوبیم جن زده می‌شود. امیر فریاد کشید: وای از جهل و نادانی، حال، گذشته از اینکه فرزندت را از دست داده‌ای باید پنج تومان هم جریمه بدهی. پیرمرد با التماس گفت: باور کنید که هیچ ندارم. امیرکبیر دست در جیب خود کرد و پنج تومان به او داد و سپس گفت: حکم برنمی‌گردد، این پنج تومان را به صندوق دولت بپرداز چند دقیقه دیگر، بقالی را آوردند که فرزند او نیز از آبله مرده بود. این بار امیرکبیر دیگر نتوانست تحمل کند. روی صندلی نشست و با حالی زار شروع به گریستن کرد. در آن هنگام میرزا آقاخان وارد شد. او در کمتر زمانی امیرکبیر را در حال گریستن دیده بود. علت را پرسید و ملازمان امیر گفتند که دو کودک شیرخوار پاره دوز و بقالی از بیماری آبله مرده‌اند. میرزا آقاخان با شگفتی گفت: عجب، من تصور می‌کردم که میرزا احمدخان، پسر امیر، مرده است که او این چنین های‌های می‌گرید. سپس، به امیر نزدیک شد و گفت: گریستن، آن هم به این گونه، برای دو بچه‌ی شیرخوار بقال و چقال در شأن شما نیست. امیر سر برداشت و با خشم به او نگریست، آنچنان که میرزا آقاخان از ترس بر خود لرزید. امیر اشک‌هایش را پاک کرد و گفت: خاموش باش. تا زمانی که ما سرپرستی این ملت را بر عهده داریم، مسئول مرگشان ما هستیم.\r\nمیرزا آقاخان آهسته گفت: ولی اینان خود در اثر جهل آبله نکوبیده‌اند امیر با صدای رسا گفت: و مسئول جهلشان نیز ما هستیم. اگر ما در هر روستا و کوچه و خیابانی مدرسه بسازیم و کتابخانه ایجاد کنیم، دعانویس‌ها بساطشان را جمع می‌کنند. تمام ایرانی‌ها اولاد حقیقی من هستند و من از این می‌گریم که چرا این مردم باید این قدر جاهل باشند که در اثر نکوبیدن آبله بمیرند.\r\n"},{"id":1479,"category_id":10,"category_code":"s10","source_id":41,"title":"شاه عباس و امور اقتصادی","content":"شاه عباس از وزیر خود پرسید:\r\nامسال اوضاع اقتصادی کشور چگونه است؟\r\nوزیر گفت:\r\nالحمدالله به گونه ای است که تمام پینه دوزان توانستند به زیارت کعبه روند!\r\nشاه عباس گفت:\r\nنادان اگر اوضاع مالی مردم خوب بود کفاشان میبایست به مکه میرفتند نه پینه دوزان، چونکه مردم نمیتوانند کفش بخرند ناچار به تعمیرش میپردازند، بررسی کن و علت آنرا پیدا نما تا کار را اصلاح کنیم.\r\n"},{"id":1480,"category_id":10,"category_code":"s10","source_id":42,"title":"فرض کنید . . .","content":"به شما، این امکان را میدهند که از بین سه نفر یک رئیس برای دنیا انتخاب کنیدکه بتواند به بهترین وجه دنیا را رهبری کرده صلح و ترقی و خوشبختی برای بشریت به ارمغان بیاورد.\r\n\r\nبین این سه داوطلب کدام را انتخاب میکنید.\r\n\r\nقبلا یک سوال: شما مشاور و مددکار اجتماعی هستید . . . .\r\n\r\nزن حامله ای میشناسید که هشت فرزند دارد. سه فرزند او ناشنوا، دو فرزند کور و یکی عقب مانده هستند. در ضمن خود این خانم مبتلا به مرض سیفیلیس است. از شما مشورت میخواهد که آیا سقط جنین کند یا نه . . . . با تجارب زندگی که دارید به ایشان چه پیشنهادی میدهید؟\r\n\r\nخواهید گفت سقط کند؟\r\n\r\nفعلا بریم سراغ سه نامزد ریاست بر جهان\r\nشخص اول:\r\n\r\nاو با سیاستمداران رشوه خوار و بد نام کار میکند، از فالگیر غیب گو و منجم مشورت میگیرد. در کنار زنش دو معشوقه دارد. شدیدا سیگاری بوده و روزی هم ده لیوان مشروب میخورد.\r\n\r\nشخص دوم :\r\n\r\nاز دو محل کار اخراج شده، تا ساعت 12 ظهر میخوابد.در مدرسه چند بار رفوزه شده.در جوانی تریاک میکشیده و تحصیلات آنچنانی ندارد. ایشان روزی یک بطر ویسکی میخورد، بی تحرک و چاق است.\r\n\r\nشخص سوم:\r\n\r\nدولت کشورش به ایشان مدال شجاعت داده، گیاهخوار بوده و دارای سلامت کامل هست. به سیگارومشروب دست نمیزند و در گذشته هیچ گونه رسوایی به بار نیاورده.\r\n\r\nبه چه کسی رأی میدهید؟\r\n\r\nکاندید اول : فرانکلین روز ولت\r\n\r\nکاندید دوم : وینستون چرچیل\r\nکاندید سوم :آدولف هیتلر\r\n\r\nچه درسی میگیریم؟\r\n\r\nراستی خانم حامله فراموش نشود؟\r\n\r\nاگر به آن خانم پیشنهاد سقط جنین دادید همان بس که لودویگ فان بتهوون را به کشتن دادید!\r\n"},{"id":1481,"category_id":10,"category_code":"s10","source_id":43,"title":"سخنی با فاحشه ها ","content":"تعجب کردی!؟... میدانم در کسوت مردان آبرومند، اندیشیدن به تو رسم، و گفتن از تو ننگ است! اما میخواهم برایت بنویسم.\r\nشنیده ام، تن می فروشی، برای لقمه نان! چه گناه کبیره ای…! میدانم که میدانی همه ترا پلید می دانند، من هم مانند همه ام\r\nراستی روسپی! از خودت پرسیدی چرا اگر در سرزمین من و تو، زنی زنانگی اش را بفروشد که نان در بیارد رگ غیرت اربابانبیرون می زند !!اما اگر همان زن کلیه اش را بفروشد تا نانی بخرد و یا شوهر زندانی اش آزاد شود این «ایثار» است ! مگر هردواز یک تن نیست؟ مگر هر دو جسم فروشی نیست؟\r\nتن در برابر نان ننگ است...\r\nبفروش ! تنت را حراج کن… من در دیارم کسانی را دیدم که دین خدا را چوب میزنند به قیمت دنیایشان\r\nشرفت را شکر که اگر میفروشی از تن می فروشی نه از دین\r\nشنیده ام روزه میگیری،\r\nغسل میکنی،\r\nنماز میخوانی،\r\nچهارشنبه ها نذر حرم امامزاده صالح داری،\r\nرمضان بعد از افطار کار می کنی،\r\nمحرم تعطیلی.\r\nمن از آن میترسم که روزی با ظاهری عالمانه، جمعه بازار دین خدا را براه کنم، زهد را بساط کنم، غسل هم نکنم، چهارشنبه هم به حرم امامزاده صالح نروم، پیش از افطار و پس از افطار مشغول باشم، محرم هم تعطیل نکنم!\r\nفاحشه!!!… دعایم کن\r\n"},{"id":1482,"category_id":10,"category_code":"s10","source_id":44,"title":"مردی که جهان را نجات داد! ","content":"اشتباه نکنید این فرد نه یک سیاستمدار بود و نه رییس یک سازمان بین‌المللی.\r\nباید داستان را از اول مرور کنیم و به تاریخ اول سپتامبر سال 1983 برگردیم:\r\nاول سپتامبر سال 1983 بود و جنگ سرد بین ابرقدرت‌های جهان -شوروی و آمریکا- با شدت تمام دنبال می‌شد ، یک هواپیمای خطوط هوایی کره از فرودگاه جان اف ‌کندی نیویورک به مقصد سئول کره جنوبی حرکت می‌کرد.\r\nدر نیمه راه ، هواپیمای مسافری به اشتباه وارد حریم هوایی شوروی شد. جت‌های روسی به این هواپیما نزدیک شدند، خلبانان جت‌های روسی نمی‌دانستند که هواپیما حاوی مسافرهای عادی است ، آنها به هواپیما اخطار کردند که اگر خودش را معرفی نکند ، به آن شلیک خواهند کرد ولی در نهایت پاسخی دریافت نکردند....\r\nگفته می‌شود در واقع پرسنل پرواز هواپیما اخطار جنگنده‌های روسی را دریافت نکرده بودند ، البته تا به امروز تئوری‌های زیادی در این مورد وجود دارد. یک ساعت گذشت و جت‌ها همچنان ، هواپیما را همراهی می‌کردند تا اینکه از مقامات روسی دستور رسید که هواپیما نابود شود. این کار انجام شد و در نتیجه 269 مسافر کشته شدند...\r\n\r\nبعد از اینکه همه متوجه فاجعه شدند ، مقامات روسی سعی کردند عمل خود را توجیه کنند ولی رونالد ریگان رییس جمهور وقت آمریکا روس‌ها را بربر دانست و کار آنها را «جنایتی علیه بشر که نباید فراموش شود» تلقی کرد.\r\nتنش بین ابرقدرت‌های به حداکثر خود رسیده بود و نظامیان هر دو جبهه در حالت آماده‌باش نظامی قرار گرفته بودند.\r\nدر یک شب سرد در 26سپتامبر سال 1983، استانیسلاو یوگرافوویچ پتروف یک سرهنگ دوم نیروهای موشکی استراتژیک سر کارش بود او به جای همکارش که به علتی نتوانسته بود در محل کار ظاهر شود ، پست می‌داد و آسمان شوروی را پایش می‌کرد...\r\nکمی از نیمه‌شب گذشته بود که پتروف هشداری از یک کامپیوتر گرفت : یک موشک اتمی از سوی آمریکا شلیک شده و مقصدش مسکو است!!!\r\nپروتکل نظامی از پیش تعریف‌ شده روس‌ها در چنین شرایطی این بود که همه سلاح‌های اتمی برای انجام یک ضد حمله به صورت سریع و آنی فعال شوند و پس از آن به مقامات نظامی و سیاسی اطلاع داده شود.\r\nصدای آلارم‌ها در پناهگاهی که پتروف در آن بود به گوش می‌رسید و نورهای قرمز به نشانه شناسایی موشک اتمی آمریکایی‌ها به وسیله ماهواره‌های روسی همه جا روشن بودند.\r\nولی پتروف حس می‌کرد هشدار کامپیوترها درست نباشد ، او فکر کرد که اگر آمریکا واقعا قصد حمله به شوروی را داشته باشد از همه موشک‌هایش استفاده می‌کند و با پرتاب صرفا یک موشک ، فرصت ضدحمله را به روس‌ها نمی‌دهد.\r\n\r\nلحظاتی بعد استرس در پناهگاه بیشتر شد و همه افسرها در تشویش بودند چرا که کامپیوترها ، موشک‌های دوم ، سوم ، چهارم و پنجم را هم شناسایی کرده بودند.\r\nپتروف دو راه پیش رو داشت : به غریزه‌اش اعتماد کند و همه اخطارهای کامپیوترها را ناشی از اشتباه آنها بداند و یا طبق پروتکل نظامی ، سیستم موشکی شوروی را فعال کند و آغازگر جنگی شود که بی‌شک موجب مرگ میلیون‌ها نفر می‌شود.\r\nپتروف کار اول را انجام داد!!!\r\nبا گذشت دقایقی معلوم شد که حق با پتروف بوده است.همه اینها ناشی از خطای کامپوتر و نقص در یک قطعه چند دلاری بود.پتروف حالا یک قهرمان بود ، او از جنگ اتمی پیشگیری کرده بود ، افسران دور و برش ، تصمیم شجاعانه او را ستودند.\r\nولی مقامات کرملین اینگونه فکر نمی‌کردند ، او به هر حال از پروتکل نظامی تخطی کرده بود ، اگر تصمیم او اشتباه از آب در می‌آمد ، جان میلیون‌ها نفر از شهروندان شوروی را به خطر می‌انداخت. بنابراین تصمیم گرفته شد که پتروف به بازنشستگی پیش از موعد برود ، با حقوقی حدود 200 دلار در ماه!\r\nتا سال 1988 به خاطر حفظ اسرار نظامی کسی از تصمیم قهرمانانه پتروف آگاه نشد ، در این زمان یکی از افسران حاضر در آن پناهگاه کتابی در مورد واقعه نوشت و همه چیز را توضیح داد.\r\nقرار است در سال 2008 مستندی با عنوان «مردی که دنیا را نجات داد» ساخته شود.\r\n\r\n\r\n\r\nهیچ کس نمی‌داند که اگر پتروف ،آن افسر 44ساله‌ ،آن شب در آن پناهگاه نبود ، چه اتفاقی می‌افتاد و باز کسی نمی تواند حدس بزند اگر همکار آقای پتروف آن روز در شیفت خودش حاضر می‌شد چه تصمیمی می‌گرفت ولی مسلم است که پتروف بیشتر از هر شخص دیگری باعث نجات جان انسان‌ها شده است.\r\nشاید اگر آن تصمیم پتروف نبود ، الان من و شما در پشت مانیتورهایمان در حال خواندن این متن نبودیم!!!\r\n"},{"id":1483,"category_id":10,"category_code":"s10","source_id":45,"title":"حکایتی تکان دهنده از عدالت علی(ع) ","content":"زنی به نام «سوده همدانی» از شیعیان امام بود، در جنگ صفین برای تشجیع(ترغیب شجاعتشان) سربازان و فرزندان دلاورش، اشعار حماسی می‌خواند، که سخت بر معاویه گران آمد و نام او را ثبت کرد.\r\nروزگار گذشت و امام علی علیه‌السلام به شهادت رسید، و فرماندار معاویه بسر بن ارطاة، بر شهر همدان مسلط گشت، و هر چه می‌خواست انجام می‌‌داد، و کسی جرئت اعتراض یا مخالفت را نداشت سرانجام سوده، سوار بر شتر به دربار معاویه در شام رفت، و از قتل و غارت و فساد فرماندار به معاویه شکایت کرد.\r\nمعاویه او را شناخت و سرزنش کرد، و گفت:\r\nیاد داری که در جنگ صفّین چه می‌کردی؟ حال دستور می‌دهم تو را سوار بر شتری برهنه تحویل فرماندارم بدهند تا هر گونه دوست دارد، با تو رفتار کند؟...\r\nسوده، در حالی که اشک می‌ریخت این اشعار را خواند:\r\nصلّی الاله علی جسم تضمّنه قبر فاصبح فیه العدل مدفوناً\r\nقد حالف الحق لا یبغی بد بدلا فصار بالحق و الایمان مقروناً\r\n«خدایا درود بر پیکر پاکی فرست که چون دفن شد عدالت هم دفن شد،\r\nو خدا سوگند خورده که همتایی برای او نیاورد، و تنها او با حق و ایمان همراه بود»\r\nمعاویه با شگفتی پرسید: \r\nچه کسی را می‌گویی؟ و این اشعار را پیرامون چه شخصی خواندی؟\r\nسوده گفت:\r\nحضرت علی علیه‌السلام را می‌گویم که چون رفت، عدالت هم رفت.\r\nمعاویه! فرماندار امام علی علیه‌السلام در همدان چند کیلو گندم از من اضافه گرفت، به کوفه رفتم وقتی رسیدم که امیرالمومنین علی علیه‌السلام برای نماز مغرب بپا خاسته بود تا مرا دید نشست و فرمود: حاجتی داری؟\r\nماجرا را شرح دادم، و گفتم\r\nچند کیلو گندم مهم نیست، می‌ترسم فرماندار تو به سوی تجاوز و رشوه‌خواری پیش رفته و آبروی حکومت اسلامی خدشه‌دار شود.\r\nامام علی علیه‌السلام با شنیدن سخنان من گریست و گفت:\r\nخدایا تو گواهی که من آنها را برای ستم به مردم دعوت نکردم.\r\nسپس قطعه پوستی گرفت و بر روی آن نوشت:\r\nبسم‌الله الرحمن الرحیم، قد جائتکم بینةٌ مِن ربّکم فَاوفوا الکیلَ و المیزان، و لا تَبخَسوا النّاسَ اَشیائهُم، و لا تُفسدوا فی الارض بعد اصلاحها، (1) ذالکم خیرٌ لکُم مَن یَقبِضُهُ. والسّلام؛‌ دلیل روشنی از طرف پروردگارتان برای شما آمده است؛ بنابراین، حق پیمانه و وزن را ادا کنید! و از اموال مردم چیزی نکاهید! و در روی زمین، بعد از آن که (در پرتو ایمان و دعوت انبیاء) اصلاح شده است، فساد نکنید!\r\nسپس دستور داد که:\r\nکارهای فرمانداری خود را بررسی و جمع‌آوری کن، تو را عزل کردم و به زودی فرماندار جدید خواهد آمد، و همه چیز را از تو تحویل خواهد گرفت.\r\nنامه را به من داد، نه آن را بست، و نه لاک و مُهر کرد، بلافاصله پس از بازگشت من به «شهر همدان» فرماندار عزل و دیگری به جای او آمد.\r\nمعاویه، آن روز شکایت من از چند کیلو گندم اضافی بود، اما امروز به تو شکایت کردم که فرماندار تو «بسر بن ازطاة» شراب می‌خورد، تجاوز می‌کند، مال مردم را به یغما می‌برد،‌ خون بی‌گناهان را می‌ریزد؛ و تو به جای اجرای عدالت و عزل فرماندار فسادگر، مرا تهدید به مرگ می‌کنی؟ و ادعا داری که خلیفه مسلمین می‌باشی؟\r\n"},{"id":1484,"category_id":10,"category_code":"s10","source_id":46,"title":"شک ","content":"هیزم شکن صبح از خواب بیدار شد و دید تبرش ناپدید شده. شک کرد که همسایه اش آن را دزدیده باشد برای همین تمام روز او را زیر نظر گرفت. متوجه شد همسایه اش در دزدی مهارت دارد مثل یک دزد راه می رود مثل دزدی که می خواهد چیزی را پنهان کند پچ پچ میکند. آن قدر از شکش مطمئن شد که تصمیم گرفت به خانه برگردد لباسش را عوض کند و نزد قاضی برود. اما همین که وارد خانه شد تبرش را پیدا کرد. زنش آن را جابه جا کرده بود. مرد از خانه بیرون رفت و دوباره همسایه را زیر نظر گرفت: و دریافت که او مثل یک آدم شریف راه می رود حرف می زند و رفتار می کند."},{"id":1485,"category_id":10,"category_code":"s10","source_id":47,"title":"اگه کوسه ها آدم بودن ","content":"دختر کوچولوی صاحبخانه از آقای \" کی \" پرسید:\r\nاگر کوسه ها آدم بودند با ماهی های کوچولو مهربانتر میشدند؟\r\nآقای کی گفت : البته ! اگر کوسه ها آدم بودند\r\nتوی دریا برای ماهیها جعبه های محکمی میساختند\r\nهمه جور خوراکی توی آن میگذاشتند\r\nمواظب بودند که همیشه پر آب باشد\r\n...\r\nهوای بهداشت ماهی های کوچولو را هم داشتند\r\nبرای آنکه هیچوقت دل ماهی کوچولو نگیرد\r\nگاهگاه مهمانی های بزرگ بر پا میکردند\r\nچون که گوشت ماهی شاد از ماهی دلگیر لذیذتر است !\r\nبرای ماهی ها مدرسه میساختند\r\nوبه آنها یاد میدادند که چه جوری به طرف دهان کوسه شنا کنند\r\nدرس اصلی ماهیها اخلاق بود\r\nبه آنها می قبولاندند که زیبا ترین و باشکوه ترین کار برای یک ماهی این است\r\nکه خودش را در نهایت خوشوقتی تقدیم یک کوسه کند\r\nبه ماهی کوچولو یاد میدادند که چطور به کوسه ها معتقد باشند\r\nو چه جوری خود را برای یک آینده زیبا مهیا کنند\r\nآینده یی که فقط از راه اطاعت به دست میآیید\r\nاگر کوسه ها ادم بودند\r\nدر قلمروشان البته هنر هم وجود داشت\r\nاز دندان کوسه تصاویر زیبا و رنگارنگی می کشیدند\r\nته دریا نمایشنامه به روی صحنه میآوردند که در آن ماهی کوچولو های قهرمان\r\nشاد و شنگول به دهان کوسه ها شیرجه میرفتند\r\nهمراه نمایش آهنگهای محسور کننده یی هم مینواختند که بی اختیار\r\nماهیهای کوچولو را به طرف دهان کوسه ها میکشاند\r\nدر آنجا بی تردید مذهبی هم وجود داشت\r\nکه به ماهیها می آموخت\r\n\"زندگی واقعی در شکم کوسه ها آغاز میشود\"\r\n"},{"id":1486,"category_id":10,"category_code":"s10","source_id":48,"title":"یک طنز از ایتالو کالوینو ","content":"شهری بود که همة اهالی آن دزد بودند. شبها پس از صرف شام، هرکس دسته کلید بزرگ و فانوس را برمیداشت و از خانه بیرون میزد؛ برای دستبرد زدن به خانة یک همسایه. حوالی سحر با دست پر به خانه برمیگشت، به خانة خودش که آن را هم دزد زده بود. به این ترتیب، همه در کنار هم به خوبی و خوشی زندگی میکردند؛ چون هرکس از دیگری می دزدید و او هم متقابلاً از دیگری، تا آنجا که آخرین نفر از اولی می دزدید. داد و ستدهای تجاری و به طور کلی خرید و فروش هم در این شهر به همین منوال صورت میگرفت؛ هم از جانب خریدارها و هم از جانب فروشنده ها. دولت هم به سهم خود سعی میکرد حق و حساب بیشتری از اهالی بگیرد و آنها را تیغ بزند و اهالی هم به سهم خود نهایت سعی و کوشش خودشان را میکردند که سر دولت را شیره بمالند و نم پس ندهند و چیزی از آن بالا بکشند؛ به این ترتیب در این شهر زندگی به آرامی سپری میشد. نه کسی خیلی ثروتمند بود و نه کسی خیلی فقیر و درمانده.\r\nروزی، چطورش را نمیدانیم؛ مرد درستکاری گذرش به شهر افتاد و آنجا را برای اقامت انتخاب کرد. شبها به جای اینکه با دسته کلید و فانوس دور کوچه ها راه بیفتد برای دزدی، شامش را که میخورد، سیگاری دود میکرد و شروع میکرد به خواندن رمان. \r\nدزدها میامدند؛ چراغ خانه را روشن میدیدند و راهشان را کج میکردند و میرفتند. \r\nاوضاع از این قرار بود تا اینکه اهالی، احساس وظیفه کردند که به این تازه وارد توضیح بدهند که گرچه خودش اهل این کارها نیست، ولی حق ندارد مزاحم کار دیگران بشود. هرشب که در خانه میماند، معنیش این بود که خانواده ای سر بی شام زمین میگذارد و روزبعدهم چیزی برای خوردن ندارد.\r\nبدین ترتیب، مرد درستکار در برابر چنین استدلالی چه حرفی برای گفتن میتوانست داشته باشد؟ بنابراین پس از غروب آفتاب، او هم از خانه بیرون میزد و همانطور که از او خواسته بودند، حوالی صبح برمیگشت؛ ولی دست به دزدی نمیزد. آخر او فردی بود درستکار و اهل اینکارها نبود. میرفت روی پل شهر میایستاد و مدتها به جریان آب رودخانه نگاه میکرد و بعد به خانه برمیگشت و میدید که خانه اش مورد دستبرد قرار گرفته است. \r\nدر کمتر از یک هفته، مرد درستکار دار و ندارد خود را از دست داد؛ چیزی برای خوردن نداشت و خانه اش هم که لخت شده بود. ولی مشکلی این نبود. چرا که این وضعیت البته تقصیر خود او بود. نه! مشکل چیز دیگری بود. قضیه از این قرار بود که این آدم با این رفتارش، حال همه را گرفته بود! او اجازه داده بود دار و ندارش را بدزدند بی آنکه خودش دست به مال کسی دراز کند. به این ترتیب، هر شب یک نفر بود که پس از سرقت شبانه از خانة دیگری، وقتی صبح به خانة خودش وارد میشد، میدید خانه و اموالش دست نخورده است؛ خانه ای که مرد درستکار باید به آن دستبرد میزد. \r\nبه هر حال بعد از مدتی به تدریج، آنهایی که شبهای بیشتری خانه شان را دزد نمیزد رفته رفته اوضاعشان از بقیه بهتر شد و مال و منالی به هم میزدند و برعکس، کسانی که دفعات بیشتری به خانة مرد درستکار (که حالا دیگر البته از هر چیز به درد نخوری خالی شده بود) دستبرد میزدند، دست خالی به خانه برمیگشتند و وضعشان روز به روز بدتر میشد و خود را فقیرتر میافتند. \r\nبه این ترتیب، آن عده ای که موقعیت مالیشان بهتر شده بود، مانند مرد درستکار، این عادت را پیشه کردند که شبها پس از صرف شام، بروند روی پل چوبی و جریان آب رودخانه را تماشا کنند. این ماجرا، وضعیت آشفتة شهر را آشفته تر میکرد؛ چون معنیش این بود که باز افراد بیشتری از اهالی ثروتمندتر و بقیه فقیرتر میشدند. \r\nبه تدریج، آنهایی که وضعشان خوب شده بود و به گردش و تفریح روی پل روی آوردند، متوچه شدند که اگر به این وضع ادامه بدهند، به زودی ثروتشان ته میکشد و به این فکر افتادند که \"چطور است به عده ای از این فقیرها پول بدهیم که شبها به جای ما هم بروند دزدی\". قراردادها بسته شد، دستمزدها تعیین و پورسانتهای هر طرف را هم مشخص کردند: آنها البته هنوز دزد بودند و در همین قرار و مدارها هم سعی میکردند سر هم کلاه بگذارند و هرکدام از طرفین به نحوی از دیگری چیزی بالا میکشید و آن دیگری هم از ... . اما همانطور که رسم اینگونه قراردادهاست، آنها که پولدارتر بودند و ثروتمندتر و تهیدستها عموماً فقیرتر میشدند. \r\nعده ای هم آنقدر ثروتمند شدند که دیگر برای ثروتمند ماندن، نه نیاز به دزدی مستقیم داشتند و نه اینکه کسی برایشان دزدی کند. ولی مشکل اینجا بود که اگر دست از دزدی میکشیدند، فقیر میشدند؛ چون فقیرها در هر حال از آنها میدزدیدند. فکری به خاطرشان رسید؛ آمدند و فقیرترین آدمها را استخدام کردند تا اموالشان را در مقابل دیگر فقیرها حفاظت کنند، ادارة پلیس برپا شد و زندانها ساخته شد. \r\nبه این ترتیب، چند سالی از آمدن مرد درستکار به شهر نگذشته بود که مردم دیگر از دزدیدن و دزدیده شدن حرفی به میان نمیاوردند. صحبتها حالا دیگر فقط از دارا و ندار بود؛ اما در واقع هنوز همه دزد بودند. \r\n"},{"id":1487,"category_id":10,"category_code":"s10","source_id":49,"title":"پند لقمان ","content":"روزی لقمان به پسرش گفت:\r\n\r\nامروز به تو 3 پند می دهم که کامروا شوی.\r\n\r\nاول اینکه سعی کن در زندگی بهترین غذای جهان را بخوری!\r\nدوم اینکه در بهترین بستر و رختخواب جهان بخوابی!\r\nو سوم اینکه در بهترین کاخها و خانه های جهان زندگی کنی!\r\n\r\nپسر لقمان گفت ای پدر ما یک خانواده بسیار فقیر هستیم\r\nچطور من می توانم این کارها را انجام دهم؟\r\nلقمان جواب داد:\r\nاگر کمی دیر تر و کمتر غذا بخوری\r\nهر غذایی که میخوری طعم بهترین غذای جهان را می دهد.\r\n\r\nاگر بیشتر کار کنی و کمی دیرتر بخوابی\r\nدر هر جا که خوابیده ای احساس می کنی بهترین خوابگاه جهان است.\r\n\r\nو اگر با مردم دوستی کنی و در قلب آنها جای گیری\r\nآن گاه بهترین خانه های جهان مال توست\r\n"},{"id":1488,"category_id":10,"category_code":"s10","source_id":50,"title":"بخت با من یار نیست ","content":"روزی روزگاری نه در زمان های دور، در همین حوالی مردی زندگی می کرد که همیشه از زندگی خود گله مند بود و ادعا میکرد \"بخت با من یار نیست\" و تا وقتی بخت من خواب است زندگی من بهبود نمی یابد. پیر خردمندی وی را پند داد تا برای بیدار کردن بخت خود به فلان کشور نزد جادوگری توانا برود. او رفت و رفت تا در جنگلی سرسبز به گرگی رسید. گرگ پرسید: \"ای مرد کجا می روی؟\"\r\nمرد جواب داد: \"می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\"\r\nگرگ گفت : \"میشود از او بپرسی که چرا من هر روز گرفتار سر دردهای وحشتناک می شوم؟\"\r\nمرد قبول کرد و به راه خود ادامه داد.\r\nاو رفت و رفت تا به مزرعه ای وسیع رسید که دهقانانی بسیار در آن سخت کار می کردند.\r\nیکی از کشاورزها جلو آمد و گفت : \"ای مرد کجا می روی ؟\"\r\nمرد جواب داد: \"می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\"\r\nکشاورز گفت : \"می شود از او بپرسی که چرا پدرم وصیت کرده است من این زمین را از دست ندهم زیرا ثروتی بسیار در انتظارم خواهد بود، در صورتی که در این زمین هیچ گیاهی رشد نمیکند و حاصل زحمات من بعد از پنج سال سرخوردگی و بدهکاری است ؟\"\r\nمرد قبول کرد و به راه خود ادامه داد. او رفت و رفت تا به شهری رسید که مردم آن همگی در هیئت نظامیان بودند و گویا همیشه آماده برای جنگ.\r\nشاه آن شهر او را خواست و پرسید : \"ای مرد به کجا می روی ؟\"\r\nمرد جواب داد: \"می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\"\r\nشاه گفت : \" آیا می شود از او بپرسی که چرا من همیشه در وحشت دشمنان بسر می برم و ترس از دست دادن تاج و تختم را دارم، با ثروت بسیار و سربازان شجاع تاکنون در هیچ جنگی پیروز نگردیده ام ؟\"\r\nمرد قبول کرد و به راه خود ادامه داد. پس از راهپیمایی بسیار بالاخره جادوگری را که در پی اش راه ها پیموده بود را یافت و ماجراهای سفر را برایش تعریف کرد. جادوگر بر چهره مرد مدتی نگریست سپس رازهای را که در را ازش سوال شده بود با وی در میان گذاشت و گفت : \"از امروز بخت تو بیدار شده است برو و از آن لذت ببر!\"\r\nو مرد با بختی بیدار باز گشت...\r\nبه شاه شهر نظامیان گفت : \"تو رازی داری که وحشت برملا شدنش آزارت می دهد، با مردم خود یک رنگ نبوده ای، در هیچ جنگی شرکت نمی کنی، از جنگیدن هیچ نمی دانی، زیرا تو یک زن هستی و چون مردم تو زنان را به پادشاهی نمی شناسند، ترس از دست دادن قدرت تو را می آزارد. و اما چاره کار تو ازدواج است، تو باید با مردی ازدواج کنی تا تو را غمخوار باشد و همراز، مردی که در جنگ ها فرماندهی کند و بر دشمنانت بدون احساس ترس بتازد.\"\r\nشاه اندیشید و سپس گفت : \"حالا که تو راز مرا و نیاز مرا دانستی با من ازدواج کن تا با هم کشوری آباد بسازیم.\"\r\nمرد خنده ای کرد و گفت : \"بخت من تازه بیدار شده است، نمی توانم خود را اسیر تو نمایم، من باید بروم و بخت خود را بیازمایم، می خواهم ببینم چه چیز برایم جفت و جور کرده است!\" \r\nو رفت...\r\nبه دهقان گفت : \"وصیت پدرت درست بوده است، شما باید در زیر زمین بدنبال ثروت باشی نه بر روی آن، در زیر این زمین گنجی نهفته است، که با وجود آن نه تنها تو که خاندانت تا هفت پشت ثروتمند خواهند زیست.\"\r\nکشاورز گفت: \"پس اگر چنین است تو را هم از این گنج نصیبی است، بیا باهم شریک شویم که نصف این گنج از آن تو می باشد.\"\r\nمرد خنده ای کرد و گفت : \"بخت من تازه بیدار شده است، نمی توانم خود را اسیر گنج نمایم، من باید بروم و بخت خود را بیازمایم، می خواهم ببینم چه چیز برایم جفت و جور کرده است!\" \r\nو رفت...\r\nسپس به گرگ رسید و تمام ماجرا را برایش تعریف کرد و سپس گفت: \"سردردهای تو از یکنواختی خوراک است اگر بتوانی مغز یک انسان کودن و کور مغز را بخوری دیگر سر درد نخواهی داشت!\" \r\nخواننده محترم شما اگر جای گرگ بودید چکار می کردید ؟ \r\nبله. درست است! گرگ هم همان کاری را کرد که شاید شما هم می کردید، مرد بیدار بخت قصه ی ما را به جرم غفلت از بخت بیدارش درید و مغز او را خورد.\r\n"},{"id":1489,"category_id":10,"category_code":"s10","source_id":51,"title":"مهربانی همیشه ارزشمندتر است ","content":"بانوى خردمندى در کوهستان سفر مى کرد که سنگ گران قیمتى را در جوى آبى پیدا کرد. روز بعد به مسافرى رسید که گرسنه بود. بانوى خردمند کیفش را باز کرد تا در غذایش با مسافر شریک شود. مسافر گرسنه، سنگ قیمتى را در کیف بانوى خردمند دید، از آن خوشش آمد و از او خواست که آن سنگ را به او بدهد... .\r\nزن خردمند هم بى درنگ، سنگ را به او داد.مسافر بسیار شادمان شد و از این که شانس به او روى کرده بود، از خوشحالى سر از پا نمى شناخت. او مى دانست که جواهر به قدرى با ارزش است که تا آخر عمر، مى تواند راحت زندگى کند، ولى چند روز بعد، مرد مسافر به راه افتاد تا هرچه زودتر، بانوى خردمند را پیدا کند. \r\n \r\nبالاخره هنگامى که او را یافت، سنگ را پس داد و گفت: خیلى فکر کردم. مى دانم این سنگ چقدر با ارزش است، اما آن را به تو پس مى دهم با این امید که چیزى ارزشمندتر از آن به من بدهى. اگر مى توانى، آن محبتى را به من بده که به تو قدرت داد این سنگ را به من ببخشى!\r\n"},{"id":1490,"category_id":10,"category_code":"s10","source_id":52,"title":"عشق ","content":"یک روز آموزگار از دانش آموزانی که در کلاس بودند پرسید آیا می توانید راهی غیر تکراری برای ابراز عشق ، بیان کنید؟ برخی از دانش آموزان گفتند با بخشیدن عشقشان را معنا می کنند. برخی «دادن گل و هدیه» و «حرف های دلنشین» را راه بیان عشق عنوان کردند. شماری دیگر هم گفتند «با هم بودن در تحمل رنجها و لذت بردن از خوشبختی» را راه بیان عشق می دانند.\r\nدر آن بین ، پسری برخاست و پیش از این که شیوه دلخواه خود را برای ابراز عشق بیان کند، داستان کوتاهی تعریف کرد: یک روز زن و شوهر جوانی که هر دو زیست شناس بودند طبق معمول برای تحقیق به جنگل رفتند. آنان وقتی به بالای تپّه رسیدند درجا میخکوب شدند.\r\nیک قلاده ببر بزرگ، جلوی زن و شوهر ایستاده و به آنان خیره شده بود. شوهر، تفنگ شکاری به همراه نداشت و دیگر راهی برای فرار نبود.\r\nرنگ صورت زن و شوهر پریده بود و در مقابل ببر، جرات کوچک ترین حرکتی نداشتند. ببر، آرام به طرف آنان حرکت کرد. همان لحظه، مرد زیست شناس فریادزنان فرار کرد و همسرش را تنها گذاشت. بلافاصله ببر به سمت شوهر دوید و چند دقیقه بعد ضجه های مرد جوان به گوش زن رسید. ببر رفت و زن زنده ماند.\r\n\r\nداستان به اینجا که رسید دانش آموزان شروع کردند به محکوم کردن آن مرد.\r\nراوی اما پرسید : آیا می دانید آن مرد در لحظه های آخر زندگی اش چه فریاد می زد؟\r\n\r\nبچه ها حدس زدند حتما از همسرش معذرت خواسته که او را تنها گذاشته است!\r\n\r\nراوی جواب داد: نه، آخرین حرف مرد این بود که «عزیزم ، تو بهترین مونسم بودی.از پسرمان خوب مواظبت کن و به او بگو پدرت همیشه عاشقت بود.›› \r\n\r\nقطره های بلورین اشک، صورت راوی را خیس کرده بود که ادامه داد: همه زیست شناسان می دانند ببر فقط به کسی حمله می کند که حرکتی انجام می دهد و یا فرار می کند. پدر من در آن لحظه وحشتناک ، با فدا کردن جانش پیش مرگ مادرم شد و او را نجات داد. این صادقانه ترین و بی ریاترین ترین راه پدرم برای بیان عشق خود به مادرم و من بود .\r\n"},{"id":1491,"category_id":10,"category_code":"s10","source_id":53,"title":"گابریال گارسیا مارکز ","content":"در 15 سالگی آموختم که مادران از همه بهتر می دانند ، و گاهی اوقات پدران هم\r\nدر 20 سالگی یاد گرفتم که کار خلاف فایده ای ندارد ، حتی اگر با مهارت انجام شود \r\nدر 25 سالگی دانستم که یک نوزاد ، مادر را از داشتن یک روز هشت ساعته و پدر را از داشتن یک شب هشت ساعته، محروم می کند\r\nدر 30 سالگی پی بردم که قدرت ، جاذبه مرد است و جاذبه ، قدرت زن\r\nدر 35 سالگی متوجه شدم که آینده چیزی نیست که انسان به ارث ببرد ؛ بلکه چیزی است که خود می سازد\r\nدر 40 سالگی آموختم که رمز خوشبخت زیستن ، در آن نیست که کاری را که دوست داریم انجام دهیم ؛ بلکه در این است که کاری را که انجام می دهیم دوست داشته باشیم\r\nدر 45 سالگی یاد گرفتم که 10 درصد از زندگی چیزهایی است که برای انسان اتفاق می افتد و 90 درصد آن است که چگونه نسبت به آن واکنش نشان می دهند  \r\nدر 50 سالگی پی بردم که کتاب بهترین دوست انسان و پیروی کورکورانه بد ترین دشمن وی است....\r\nدر 55 سالگی پی بردم که تصمیمات کوچک را باید با مغز گرفت و تصمیمات بزرگ را با قلب\r\nدر 60 سالگی متوجه شدم که بدون عشق می توان ایثار کرد اما بدون ایثار هرگز نمی توان عشق ورزید  \r\nدر 65 سالگی آموختم که انسان برای لذت بردن از عمری دراز ، باید بعد از خوردن آنچه لازم است ، آنچه را نیز که میل دارد بخورد\r\nدر 70 سالگی یاد گرفتم که زندگی مساله در اختیار داشتن کارتهای خوب نیست ؛ بلکه خوب بازی کردن با کارتهای بد است\r\nدر 75 سالگی دانستم که انسان تا وقتی فکر می کند نارس است ، به رشد وکمال خود ادامه می دهد و به محض آنکه گمان کرد رسیده شده است ، دچار آفت می شود  \r\nدر 80 سالگی پی بردم که دوست داشتن و مورد محبت قرار گرفتن بزرگترین لذت دنیا استدر 85 سالگی دریافتم که همانا زندگی زیباست.\r\n"},{"id":1492,"category_id":10,"category_code":"s10","source_id":54,"title":"مدیران موفق! ","content":"روزی مدیر یکی از شرکتهای بزرگ در حالیکه به سمت دفتر کارش می رفت چشمش به جوانی افتاد که در کنار دیوار ایستاده بود و به اطراف خود نگاه میکرد. \r\nجلو رفت و از او پرسید: «شما ماهانه چقدر حقوق دریافت می کنی؟»\r\nجوان با تعجب جواب داد: «ماهی 2000 دلار.»\r\nمدیر با نگاهی آشفته دست به جیب شد و از کیف پول خود 6000 دلار را\r\nدر آورده و به جوان داد و به او گفت: «این حقوق سه ماه تو، برو و دیگر اینجا پیدایت نشود، ما به کارمندان خود حقوق می دهیم که کار کنند نه اینکه یکجا بایستند و بیکار به اطراف نگاه کنند.»\r\nجوان با خوشحالی از جا جهید و به سرعت دور شد. مدیر از کارمند دیگری که در نزدیکیش بود پرسید: «آن جوان کارمند کدام قسمت بود؟»\r\nکارمند با تعجب از رفتار مدیر خود به او جواب داد: «او پیک پیتزا فروشی بود که برای کارکنان پیتزا آورده بود.»\r\nبرخی از مدیران حتی کارکنان خود را در طول دوره مدیریت خود ندیده و آنها را نمی شناسند. ولی در برخی از مواقع تصمیمات خیلی مهمی را در باره آنها گرفته و اجرا می کنند.\r\n"},{"id":1493,"category_id":10,"category_code":"s10","source_id":55,"title":"قهرمان","content":"کودکی ده ساله که دست چپش در یک حادثه رانندگی از بازو قطع شده بود ، برای تعلیم فنون رزمی جودو به یک استاد سپرده شد. پدر کودک اصرار داشت استاد از فرزندش یک قهرمان جودو بسازد استاد پذیرفت و به پدر کودک قول داد که یک سال بعد می تواند فرزندش را در مقام قهرمانی کل باشگاه ها ببیند.\r\nدر طول شش ماه استاد فقط روی بدن سازی کودک کار کرد.\r\n و در عرض این شش ماه حتی یک فن جودو را به او تعلیم نداد. بعد از 6 ماه خبررسید که یک ماه بعد مسابقات محلی در شهر برگزار می شود.استاد به کودک ده ساله فقط یک فن آموزش داد و تا زمان برگزاری مسابقات فقط روی آن تک فن کار کرد.سر انجام مسابقات انجام شدو کودک توانست در میان اعجاب همگان با آن تک فن همه حریفان خود را شکست دهد!سه ماه بعد کودک توانست در مسابقات بین باشگاه ها نیز با استفاده از همان تک فن برنده شود و سال بعد نیز در مسابقات کشوری، آن کودک یک دست موفق شد تمام حریفان را زمین بزند و به عنوان قهرمان سراسری کشورانتخاب گردد. وقتی مسابقات به پایان رسید، در راه بازگشت به منزل، کودک از استاد رازپیروزی اش را پرسید. استاد گفت: \"دلیل پیروزی تو این بود که اولاً به همان یک فن به خوبی مسلط بودی، ثانیاً تنها امیدت همان یک فن بود، و سوم اینکه راه شناخته شده مقابله با این فن ، گرفتن دست چپ حریف بود که تو چنین دستی نداشتی!\r\nیاد بگیر که در زندگی ، از نقاط ضعف خود به عنوان نقاط قوت خود استفاده کنی.راز موفقیت در زندگی ، داشتن امکانات نیست ، بلکه استفاده از \"بی امکانی\" به عنوان نقطه قوت است.\r\n"},{"id":1494,"category_id":10,"category_code":"s10","source_id":56,"title":"راه بهشت ","content":"مردی با اسب و سگش در جاده‌ای راه می‌رفتند. هنگام عبور از کنار درخت عظیمی، صاعقه‌ای فرود آمد و آنها را کشت. اما مرد نفهمید که دیگر این دنیا را ترک کرده است و همچنان با دو جانورش پیش رفت. گاهی مدت‌ها طول می‌کشد تا مرده‌ها به شرایط جدید خودشان پی ببرند.\r\nپیاده‌روی درازی بود، تپه بلندی بود، آفتاب تندی بود، عرق می‌ریختند و به شدت تشنه بودند. در یک پیچ جاده دروازه تمام مرمری عظیمی دیدند که به میدانی با سنگفرش طلا باز می‌شد و\r\n در وسط آن چشمه‌ای بود که آب زلالی از آن جاری بود. رهگذر رو به مرد دروازه‌بان کرد: «روز به خیر، اینجا کجاست که اینقدر قشنگ است؟»\r\nدروازه‌بان: «روز به خیر، اینجا بهشت است.»\r\n- «چه خوب که به بهشت رسیدیم، خیلی تشنه‌ایم.»\r\nدروازه‌بان به چشمه اشاره کرد و گفت: «می‌توانید وارد شوید و هر چه قدر دلتان می‌خواهد بوشید.»\r\n- اسب و سگم هم تشنه‌اند.\r\nنگهبان: واقعأ متأسفم. ورود حیوانات به بهشت ممنوع است.\r\nمرد خیلی ناامید شد، چون خیلی تشنه بود، اما حاضر نبود تنهایی آب بنوشد. از نگهبان تشکر کرد و به راهش ادامه داد. پس از اینکه مدت درازی از تپه بالا رفتند، به مزرعه‌ای رسیدند. راه ورود به این مزرعه، دروازه‌ای قدیمی بود که به یک جاده خاکی با درختانی در دو طرفش باز می‌شد. مردی در زیر سایه درخت‌ها دراز کشیده بود و صورتش را با کلاهی پوشانده بود، احتمالأ خوابیده بود.\r\nمسافر گفت: روز به خیر\r\nمرد با سرش جواب داد.\r\n- ما خیلی تشنه‌ایم.، من، اسبم و سگم.\r\nمرد به جایی اشاره کرد و گفت: میان آن سنگ‌ها چشمه‌ای است. هرقدر که می‌خواهید بنوشید.\r\nمرد، اسب و سگ، به کنار چشمه رفتند و تشنگی‌شان را فرو نشاندند.\r\nمسافر از مرد تشکر کرد. مرد گفت: هر وقت که دوست داشتید، می‌توانید برگردید.\r\nمسافر پرسید: فقط می‌خواهم بدانم نام اینجا چیست؟\r\n- بهشت\r\n- بهشت؟ اما نگهبان دروازه مرمری هم گفت آنجا بهشت است!\r\n- آنجا بهشت نیست، دوزخ است.\r\nمسافر حیران ماند: باید جلوی دیگران را بگیرید تا از نام شما استفاده نکنند! این اطلاعات غلط باعث سردرگمی زیادی می‌شود!\r\n- کاملأ برعکس؛ در حقیقت لطف بزرگی به ما می‌کنند. چون تمام آنهایی که حاضرند بهترین دوستانشان را ترک کنند، همانجا می‌مانند..\r\n"},{"id":1495,"category_id":10,"category_code":"s10","source_id":57,"title":"جهان سوم","content":"از قول ایشان نقل شده است : روزی در آخر ساعت درس، یکی از دانشجویانم که دانشجوی دوره دکترا و اهل نروژ بود از من پرسید  :  استاد! شما که از جهان سوم می آیید، جهان سوم کجاست؟\r\nفقط چند دقیقه به آخر کلاس مانده بود. من در جواب مطلبی را فی البداهه گفتم که روز به روز بیشتر به آن اعتقاد پیدا می کنم. به آن دانشجو گفتم\r\nجهان سوم جایی است که هر کس بخواهد مملکتش را آباد کند، خانه اش خراب می شود و هر کس که بخواهد خانه اش آباد باشد، باید در تخریب مملکتش بکوشد.\r\n"},{"id":1496,"category_id":10,"category_code":"s10","source_id":58,"title":"بهشت و جهنم ","content":"روزی یک مرد روحانی با خداوند مکالمه ای داشت : \"خداوندا! دوست دارم بدانم بهشت و جهنم چه شکلی هستند؟ \"، خداوند او را به سمت دو در هدایت کرد و یکی از آنها را باز کرد ، مرد نگاهی به داخل انداخت ، درست در وسط اتاق یک میز گرد بزرگ وجود داشت که روی آن یک ظرف خورش بود ، که آنقدر بوی خوبی داشت که دهانش آب افتاد ، افرادی که دور میز نشسته بودند بسیار لاغر مردنی و مریض حال بودند ، به نظر قحطی زده می آمدند ، آنها در دست خود قاشق هایی با دسته بسیار بلند داشتند که این دسته ها به بالای بازوهایشان وصل شده بود و هر کدام از آنها به راحتی می توانستند دست خود را داخل ظرف خورش ببرند تا قاشق خود را پر نمایند ، اما از آن جایی که این دسته ها از بازوهایشان بلند تر بود ، نمی توانستند....\r\nدستشان را برگردانند و قاشق را در دهان خود فرو ببرند . مرد روحانی با دیدن صحنه بدبختی و عذاب آنها غمگین شد ، خداوند گفت : \"تو جهنم را دیدی ، حال نوبت بهشت است\" ، آنها به سمت اتاق بعدی رفتند و خدا در را باز کرد ، آنجا هم دقیقا مثل اتاق قبلی بود ، یک میز گرد با یک ظرف خورش روی آن و افراد دور میز ، آنها مانند اتاق قبل همان قاشق های دسته بلند را داشتند ، ولی به اندازه کافی قوی و چاق بوده ، می گفتند و می خندیدند،\r\nمرد روحانی گفت :\r\n\"خداوندا نمی فهمم؟!\" ، خداوند پاسخ داد : \"ساده است ، فقط احتیاج به یک مهارت دارد ، می بینی؟ اینها یاد گرفته اند که به یکدیگر غذا بدهند ، در حالی که آدم های طمع کار اتاق قبل تنها به خودشان فکر می کنند !\" هنگامی که موسی فوت می کرد ، به شما می اندیشید ، هنگامی که عیسی مصلوب می شد ، به شما فکر می کرد ، هنگامی که محمد (ص) وفات می یافت نیز به شما می اندیشید ، گواه این امر کلماتی است که آنها در دم آخر بر زبان آورده اند ، این کلمات از اعماق قرون و اعصار به ما یادآوری می کنند که یکدیگر را  دوست داشته باشید ، که به همنوع خود مهربانی نمایید ، که همسایه خود را دوست بدارید ، زیرا که هیچ کس به تنهایی وارد بهشت خدا (ملکوت الهی) نخواهد شد .\r\n"},{"id":1497,"category_id":10,"category_code":"s10","source_id":59,"title":"اوج بخشندگی ","content":"حاتم را پرسیدند که :« هرگز از خود کریمتر دیدی؟»\r\nگفت : بلی، روزی در خانه غلامی یتیم فرودآمدم و وی ده گوسفند داشت. فی الحال یک گوسفند بکشت و بپخت وپیش من آورد. مرا قطعه ای از آن خوش آمد ، بخوردم .\r\nگفتم : « والله این بسی خوش بود.»\r\nغلام بیرون رفت ویک یک گوسفند را می کشت وآن موضع را (آن قسمت ) را می پخت وپیش ...\r\nمن می آورد. و من ازاین موضوع آگاهی نداشتم.چون بیرون آمدم که سوار شوم دیدم که بیرون خانه خون بسیار ریخته است.\r\nپرسیدم که این چیست؟\r\nگفتند : وی (غلام) همه گوسفندان خود را بکشت (سربرید) .\r\nوی را ملامت کردم که : چرا چنین کردی؟\r\nگفت : سبحان الله ترا چیزی خوش آید که من مالک آن باشم و در آن بخیلی کنم؟\r\nپس حاتم را پرسیدندکه :« تو در مقابله آن چه دادی؟»\r\nگفت : « سیصد شتر سرخ موی و پانصد گوسفند.»\r\nگفتند : « پس تو کریمتر از او باشی! »\r\nگفت : « هیهات ! وی هرچه داشت داده است و من آز آن چه داشتم و از بسیاری ؛ اندکی بیش ندادم.»\r\n"},{"id":1498,"category_id":10,"category_code":"s10","source_id":60,"title":"قلب زنان جهان را می چرخاند ...","content":"از هنگامی که خداوند مشغول خلق کردن زن بود، شش روز می گذشت\r\nفرشته ای ظاهر شد و عرض کرد:چرا این همه وقت صرف این یکی می فرمایید ؟\r\nخداوند پاسخ داد:دستور کار او را دیده ای ؟\r\nاو باید کاملا\" قابل شستشو باشد، اما پلاستیکی نباشد.\r\nباید بتواند با خوردن قهوه تلخ بدون شکر و غذای شب مانده کار کند.\r\nباید دامنی داشته باشد که همزمان دو بچه را در خودش جا دهد و وقتی از\r\nجایش بلند شد ناپدید شود.\r\nای داشته باشد که بتواند همه دردها را، از زانوی خراشیده گرفته تا\r\nقلب شکسته، درمان کند.\r\nاین همه کار برای یک روز خیلی زیاد است. باشد فردا تمامش بفرمایید .\r\nخداوند فرمود:نمی شود !! چیزی نمانده تا کار خلق این مخلوقی.....\r\nرا که این همه به من نزدیک است،تمام کنم.\r\nاز این پس می تواند هنگام بیماری، خودش را درمان کند، یک خانواده را با\r\nیک قرص نان سیر کند و یک بچه پنج سال را وادار کند دوش بگیرد.\r\n\r\nفرشته نزدیک شد و به زن دست زد.\r\nاما ای خداوند، او را خیلی نرم آفریدی .\r\nبله نرم است، اما او را سخت هم آفریده ام. تصورش را هم نمی توانی بکنی\r\nکه تا چه حد می تواند تحمل کند و زحمت بکشد .\r\n\r\n\r\nفرشته پرسید:فکر هم می تواند بکند ؟\r\nخداوند پاسخ داد:نه تنها فکر می کند، بلکه قوه استدلال و مذاکره هم دارد.\r\nآن گاه فرشته متوجه چیزی شد و به گونه زن دست زد.\r\nای وای، مثل اینکه این نمونه نشتی دارد. به شما گفتم که در این یکی\r\nزیادی مواد مصرف کرده اید.\r\nخداوند مخالفت کرد:آن که نشتی نیست، اشک است.\r\nفرشته پرسید:اشک دیگر چیست ؟\r\nخداوند گفت:اشک وسیله ای است برای ابراز شادی، اندوه، درد، نا امیدی،\r\nتنهایی، سوگ و غرورش.\r\nفرشته متاثر شد.\r\nشما نابغه اید ای خداوند، شما فکر همه چیز را کرده اید، چون زن ها\r\nواقعا\" حیرت انگیزند.\r\nزن ها قدرتی دارند که مردان را متحیر می کنند.\r\nهمواره بچه ها را به دندان می کشند.\r\nسختی ها را بهتر تحمل می کنند.\r\nبار زندگی را به دوش می کشند،\r\nولی شادی، عشق و لذت به فضای خانه می پراکنند.\r\nوقتی می خواهند جیغ بزنند، با لبخند می زنند.\r\nوقتی می خواهند گریه کنند، آواز می خوانند.\r\nوقتی خوشحالند گریه می کنند.\r\nو وقتی عصبانی اند می خندند.\r\nبرای آنچه باور دارند می جنگند.\r\nدر مقابل بی عدالتی می ایستند.\r\nوقتی مطمئن اند راه حل دیگری وجود دارد، نه نمی پذیرند.\r\nبدون کفش نو سر می کنند، که بچه هایشان کفش نو داشته باشند.\r\nبرای همراهی یک دوست مضطرب، با او به دکتر می روند.\r\nبدون قید و شرط دوست می دارند.\r\nوقتی بچه هایشان به موفقیتی دست پیدا می کنند گریه می کنند و وقتی\r\nدوستانشان پاداش می گیرند، می خندند.\r\nدر مرگ یک دوست، دل شان می شکند.\r\nدر از دست دادن یکی از اعضای خانواده اندوهگین می شوند،\r\nبا اینحال وقتی می بینند همه از پا افتاده اند، قوی، پابرجا می مانند.\r\nآنها می رانند، می پرند، راه می روند، می دوند که نشانتان بدهند چه قدر برایشان مهم هستید.\r\nقلب زن است که جهان را به چرخش در می آورد\r\nزن ها در هر اندازه و رنگ و شکلی موجودند می دانند که بغل کردن و\r\nبوسیدن می تواند هر دل شکسته ای را التیام بخشد\r\nکار زن ها بیش از بچه به دنیا آوردن است، آنها شادی و امید به ارمغان\r\nمی آورند. آنها شفقت و فکر نو می بخشند\r\nزن ها چیزهای زیادی برای گفتن و برای بخشیدن دارند\r\n\r\nخداوند گفت:این مخلوق عظیم فقط یک عیب دارد\r\n\r\nفرشته پرسید:چه عیبی ؟\r\n\r\nخداوند گفت:قدر خودش را نمی داند.\r\n"},{"id":1499,"category_id":10,"category_code":"s10","source_id":61,"title":"گفتگوی بین بچه شتر و مادرش ","content":"آورده اند روزی میان یک ماده شتر و فرزندش گفت وگویی به شرح زیر صورت گرفت: \r\nبچه شتر: مادر جون چند تا سوال برام پیش آمده است. آیا می تونم ازت بپرسم؟ \r\nشتر مادر: حتما عزیزم. چیزی ناراحتت کرده است؟ \r\nبچه شتر: چرا ما کوهان داریم؟ \r\nشتر مادر: خوب پسرم. ما حیوانات صحرا هستیم. در کوهان آب و غذا ذخیره می کنیم تا در صحرا که چیزی پیدا نمی شود بتوانیم دوام بیاوریم. \r\nبچه شتر: چرا پاهای ما دراز و کف و پای ما گرد است؟ ....\r\nشتر مادر: پسرم. قاعدتا برای راه رفتن در صحرا و تندتر راه رفتن داشتن این نوع دست و پا ضروری است. \r\nبچه شتر: چرا مژه های بلند و زخیم داریم؟ بعضی وقت ها مژه ها جلوی دید من را می گیرد. \r\nشتر مادر: پسرم این مژه های بلند و ضخیم یک نوع پوشش حفاظتی است که چشم ها ما را در مقابل باد و شن های بیابان محافظت می کنند. \r\nبچه شتر: فهمیدم. پس کوهان برای ذخیره کردن آب است برای زمانی که ما در بیابان هستیم. پاهایمان برای راه رفتن در بیابان است و مژه هایمان هم برای محافظت چشمهایمان در برابر باد و شن های بیابان است... . \r\nبچه شتر: فقط یک سوال دیگر دارم... ... \r\nشتر مادر: بپرس عزیزم. \r\nبچه شتر: پس ما در این باغ وحش چه غلطی می کنیم؟\r\n"},{"id":1500,"category_id":10,"category_code":"s10","source_id":62,"title":"چادر","content":"شرلوک هلمز، کارآگاه معروف، و معاونش واتسون رفته بودند صحرانوردی و شب هم چادری زدند و زیر آن خوابیدند. نیمه های شب هلمز بیدار شد و آسمان را نگریست. بعد واتسون را بیدار کرد و گفت: \"نگاهی به بالا بینداز و به من بگو چه می بینی؟\" واتسون گفت:\"میلیون ها ستاره می بینم\".هلمز گفت: چه نتیجه ای می گیری؟\r\nواتسون گفت: \"از لحاظ روحانی نتیجه می گیرم که خداوند بزرگ است و ما چقدر در این دنیا حقیریم. از لحاظ ستاره شناسی نتیجه می گیرم که زهره در برج مشتری ست، پس باید اوایل تابستان باشد. از لحاظ فیزیکی نتیجه می گیرم که مریخ در محاذات قطب است، پس باید ساعت حدود سه نیمه شب باشد.\" \r\nشرلوک هلمز قدری فکر کرد و گفت: \"واتسون! تو احمقی بیش نیستی! نتیجه ی اول و مهمی که باید بگیری این است که چادر ما را دزدیده اند.\r\n"},{"id":1501,"category_id":10,"category_code":"s10","source_id":63,"title":"همه چهار زن دارند! ","content":"روزی روزگاری تاجر ثروتمندی بود که 4 زن داشت.\r\n\r\nزن چهارم را از همه بیشتر دوست داشت و او را مدام با خریدن جواهرات گران قیمت و غذاهای خوشمزه خوشحال می‌کرد. بسیار مراقبش بود و بهترین چیزها را به او می‌داد.‌‌\r\n\r\nزن سومش را هم خیلی دوست داشت و به او افتخار می‌کرد. اگرچه واهمه شدیدی داشت که روزی او تنهایش بگذارد.\r\n\r\nواقعیت این است که او زن دومش را هم بسیار دوست داشت. او زنی بسیار مهربان بود که دائما نگران و مراقب همسرش بود. مرد در هر مشکلی به او پناه می‌برد و او نیز به تاجر کمک می‌کرد تا گره کارش را بگشاید و از مخمصه بیرون بیاید.\r\n\r\nاما زن اول مرد، زنی بسیار وفادار و توانا بود که در حقیقت عامل اصلی ثروتمند شدن او و موفق بودنش\r\nدر زندگی بود که اصلا مورد توجه مرد نبود. با اینکه از صمیم قلب عاشق شوهرش بود اما مرد تاجر به ندرت وجود او را در خانه ای که تمام کارهایش با او بود حس می‌کرد و تقریبا هیچ توجهی به او نداشت.\r\n\r\nروزی مرد احساس مریضی کرد و قبل از آنکه دیر شود فهمید که به زودی خواهد مرد. به دارایی زیاد و زندگی مرفه خود اندیشید و با خود گفت: ‌\"من اکنون 4 زن دارم، اما اگر بمیرم دیگر هیچ کسی را نخواهم داشت و تنها و بیچاره خواهم شد\"! بنابراین تصمیم گرفت با زنانش حرف بزند و برای تنهایی‌اش فکری بکند.\r\n\r\nاول از همه سراغ زن چهارم رفت و گفت:\"من تورا بیشتر از همه دوست دارم و از همه بیشتر به تو توجه کرده ام و انواع راحتی ها را برایت فراهم آورده ام ، حالا در برابر این همه محبت من آیا در مرگ با من همراه می‌شوی تا تنها نمانم؟\"زن به سرعت گفت : \" هرگز\" و مرد را رها کرد.\r\n\r\nناچار با قلبی که به شدت شکسته بود نزد زن سوم رفت و گفت:‌\"من در زندگی تو را بسیار دوست داشتم آیا در این سفر همراه من خواهی آمد؟\"زن گفت: \" البته که نه! زندگی در اینجا بسیار خوب است. تازه من بعد از تو می‌خواهم دوباره ازدواج کنم \" قلب مرد یخ کرد.\r\n\r\nمرد تاجر به زن دوم رو آورد و گفت:\"تو همیشه به من کمک کرده ای . این بار هم به کمکت نیاز شدیدی دارم شاید تو از همیشه بیشتر می‌توانی در مرگ همراه من باشی؟ \"زن گفت :\" این بار با دفعات دیگر فرق دارد . من نهایتا می‌توانم تا گورستان همراه جسم بی جان تو بیایم اما در مرگ،...متاسفم\"! گویی صاعقه ای به قلب مرد آتش زد.\r\n\r\nدر همین حین صدایی او را به خود آورد:\"من با تو می‌مانم ، هرجا که بروی\"، تاجر نگاهش کرد، زن اول بود که پوست و استخوان شده بود ، انگار سوءتغذیه، بیمارش کرده باشد. غم سراسر وجودش را تیره و ناخوش کرده بود و هیچ زیبایی و نشاطی برایش باقی نمانده بود . تاجر سرش را به زیر انداخت و آرام گفت:\" باید آن روزهایی که می‌توانستم به تو توجه می‌کردم و مراقبت بودم ...\"\r\n\r\nدر حقیقت همه ما چهار زن داریم! ا\r\n\r\nلف: زن چهارم بدن ماست که مهم نیست چقدر زمان و پول صرف زیبا کردن او بکنیم وقت مرگ، اول از همه او ما را ترک می‌کند.\r\n\r\nب: زن سوم دارایی‌های ماست. هر چقدر هم برایمان عزیز باشند وقتی بمیریم به دست دیگران خواهد افتاد.\r\n\r\nج : زن دوم که خانواده و دوستان ما هستند. هر چقدر هم صمیمی و عزیز باشند ، وقت مردن نهایتا تا سر مزارمان کنارمان خواهند ماند.\r\nد: زن اول که روح ماست. غالبا به آن بی توجهیم و تمام وقت خود را صرف تن و پول و دوست می‌کنیم.او ضامن توانمندی های ماست اما ما ضعیف و درمانده رهایش کرده ایم تا روزی که قرار است همراه ما باشد، اما دیگر هیچ قدرت و توانی برایش باقی نمانده است.\r\n"},{"id":1502,"category_id":10,"category_code":"s10","source_id":64,"title":"بوم خاکستری ","content":"یک\r\nدخترک به همراه سایر همکلاسی ها  سوار بر وانت به سوی آینده ای رنگی ، در حرکت است. فاطمه  در سر آرزوی کسب مقام استانی در رشته نقاشی دارد تا شاید بتواند با فروش جایزه اش اندکی از سرفه های خشک  پدر بکاهد. معلم هر\r\nاز گاهی از پنجره نگاهی به دانش آموزان می اندازد. دخترک مداد های رنگی شکسته و مداد شمعی های رنگ و رو رفته اش را که معلم انگلیسی شان از مهد کودک ور شکسته خواهر زاده اش برایش آورده ،  نگاه می کند. اما هر چه می جوید\r\nمداد قرمز در آنها نمی یابد. اگر رنگ قرمز لازم شود چه کند.ضربان قلب دخترک آهسته،  تند میشود. وانت عباسٍ خدا زوزه کشان از آخرین سینه کش خدا حافظی می کند و وارد جاده آسفالت می شود. جمله به خاطر اشک مادر احتیاط روی درب عقب وانت به زور خودنمایی می کند.\r\n\r\nدو\r\n\r\nراننده آخرین لقمه املت را با یک تکه پیاز بزرگ می بلعد. سبیلش را با گوشه دهان پاک می کند و راه می افتد. سرمست از بیمه 200 میلیونی امپراطور جاده ها ،  نه تنها با مقررات جاده بلکه با شیون های بی صدای مادران زجر کشیده از جفای روزگار هم می جنگد. 110 تا ، 120 تا ، 130 تا .  ولوم ضبط را بالاتر  می برد یکی به دادُم برسه واویلا . سبقت ممنوع ،  رعایت حق\r\nتقدم ، دست انداز ، سرعت گیر ، پیچ خطرناک و ...  . جیغ دخترکان و پسرکان در نعره مستانه ترمز های بادی تریلی محو می شود.\r\n\r\nسه\r\n\r\nجمله امپراطور جاده ها ، روی گل پخش کن های تریلی به نوشته پشت درب وانت پوز خند می زند. دخترک دیگر به مداد رنگی قرمز نیاز ندارد. مسابقه نقاشی قبل از شروع تمام شد. بوم خاکستری قرمز شده است. صدای فیسٍ باز شدن درب نوشابه خانواده راننده ، تلنگر مرگ در مقابله با  مشتهای عاطفه و محبت است که تا دقایقی دیگر  مادران داغ دار سوار بروانت پسرٍ عباسٍ خدا بر سر و سینه خواهند زد.\r\n"},{"id":1503,"category_id":10,"category_code":"s10","source_id":65,"title":"دزدی ایمان ","content":"نقل است که در روزگاری نه چندان دور کاروانی از تجار بهمراه مال التجاره فراوان به قصد تجارت راهی دیاری دوردست شد. در میانه راه حرامیان کمین کرده به قصد غارت اموال به کاروان یورش بردند. طولی نکشید که محافظان کاروان از پای درآمده یا تسلیم گشته و دزدان به جمع آوری اموال و اثاث از روی شتران مشغول شدند. حرامیان هرچه بود گرد آوردند از مسکوکات و جواهرات و امتعه و هر چه ارزشمند بود به زور ستاندند. در بین اموال مسروقه یکی ازحرامیان کیسه ای پر\r\nاز سکه های زر یافت که بسیار مایه تعجب بود چه آنکه در داخل همان کیسه به همراه سکه های زر تکه کاغذی یافت که روی آن آیه ای از قرآن در مضمون دفع بلا نوشته شده بود. حرامی شادی کنان کیسه را به نزد سر دسته دزدان برد و تمسخر کنان اشارتی نیز به دعای دفع بلا نمود. رئیس دزدان چون واقعه بدید دستور داد صاحب کیسه را احضار کنند. طولی نکشید که تاجری فلک زده مویه کنان به پای سردسته حرامیان افتاد که آن کیسه از آن من بود و لعن و نفرین بسیار نثار عالم دینی نمود و همی گفت که من گول آن\r\nعالم را خوردم و تا آن لحظه معتقد بودم که دعای دفع بلا واقعا کارگر خواهد بود. رئیس حرامیان اندکی به فکر فرو رفت سپس دستور داد کیسه زر را به صاحبش بر گردانند. یکی از حرامیان برآشفت که این چه تدبیری است و مگر ما قطاع الطریق نیستیم و چه رئیس دزدان پاسخ چنین داد: ای ابله، درست است که ما دزد مال مردم ایم اما هرگز قرار نبود که دزد ایمان مردم.\r\n"},{"id":1504,"category_id":10,"category_code":"s10","source_id":66,"title":"مرگ همکار ","content":"یکروز وقتى کارمندان به اداره رسیدند، اطلاعیه بزرگى را در تابلوى اعلانات دیدند که روى آن نوشته شده بود:\r\n \r\n دیروز فردى که مانع پیشرفت شما در این اداره بود درگذشت. شما را به شرکت در مراسم تشییع جنازه که ساعت 10 در سالن اجتماعات برگزار مى‌شود دعوت مى‌کنیم.\r\n\r\nدر ابتدا، همه از دریافت خبر مرگ یکى از همکارانشان ناراحت مى‌شدند امّا پس از مدتى، کنجکاو مى‌شدند که بدانند کسى که مانع پیشرفت آن‌ها در اداره مى‌شده که بوده است.\r\nاین کنجکاوى، تقریباً تمام کارمندان را ساعت10 به سالن\r\n اجتماعات کشاند. رفته رفته که جمعیت زیاد مى‌شد هیجان هم بالا مى‌رفت. همه پیش خود فکر مى‌کردند: این فرد چه کسى بود که مانع پیشرفت ما در اداره بود؟ به هر حال خوب شد که مرد!\r\n \r\nکارمندان در صفى قرار گرفتند و یکى یکى نزدیک تابوت مى‌رفتند و وقتى به درون تابوت نگاه مى‌کردند ناگهان خشکشان مى‌زد و زبانشان بند مى‌آمد.\r\n \r\nآینه‌اى درون تابوت قرار داده شده بود و هر به درون تابوت نگاه مى‌کرد، تصویر خود را مى‌دید. نوشته‌اى نیز بدین مضمون در کنار آینه بود:\r\n\r\nتنها یک نفر وجود دارد که مى‌تواند مانع رشد شما شود و او هم کسى نیست جزء خود شما. شما تنها کسى هستید که مى‌توانید زندگى‌تان را متحوّل کنید. شما تنها کسى هستید که مى‌توانید بر روى شادى‌ها، تصورات و موفقیت‌هایتان اثر گذار باشید. شما تنها کسى هستید که مى‌توانید به خودتان کمک کنید.\r\n \r\nزندگى شما وقتى که رئیستان، دوستانتان، والدین‌تان، شریک زندگى‌تان یا محل کارتان تغییر مى‌کند، دستخوش تغییر نمى‌شود. زندگى شما تنها فقط وقتى تغییر مى‌کند که شما تغییر کنید، باورهاى محدود کننده خود را کنار بگذارید و باور کنید که شما تنها کسى هستید که مسئول زندگى خودتان مى‌باشید.\r\n \r\nمهم‌ترین رابطه‌اى که در زندگى مى‌توانید داشته باشید، رابطه با خودتان است.\r\n \r\nخودتان را امتحان کنید. مواظب خودتان باشید. از مشکلات، غیرممکن‌ها و چیزهاى از دست داده نهراسید. خودتان و واقعیت‌هاى زندگى خودتان را بسازید.\r\n\r\nدنیا مثل آینه است. انعکاس افکارى که فرد قویاً به آن‌ها اعتقاد دارد را به او باز مى‌گرداند. تفاوت‌ها در روش نگاه کردن به زندگى است. \r\n"},{"id":1505,"category_id":10,"category_code":"s10","source_id":67,"title":"راز پیروزی اسکندر در ایران ","content":"میگویند اسکندر قبل از حمله به ایران درمانده و مستأصل بود. از خود میپرسید که چگونه باید بر مردمی که از مردم من بیشتر میفهمند حکومت کنم؟ \r\n\r\nیکی از مشاوران میگوید: «کتابهایشان را بسوزان. بزرگان و خردمندانشان را بکش ..\r\nو دستور بده به زنان و کودکانشان تجاوز کنند».\r\n\r\nاما ظاهراً یکی دیگر از مشاوران (به قول برخی، ارسطو) پاسخ میدهد:\r\n\r\n«نیازی به چنین کاری نیست. از میان مردم آن سرزمین، آنها را که نمیفهمند و کم سوادند، به کارهای بزرگ بگمار. آنها که میفهمند و باسوادند، به کارهای کوچک و پست بگمار. بی سوادها و نفهم ها همیشه شکرگزار تو خواهند بود و هیچگاه توانایی طغیان نخواهند داشت. فهمیده ها و با سوادها هم یا به سرزمینهای دیگر کوچ میکنند یا خسته و سرخورده، عمر خود را تا لحظه مرگ، در گوشه ای از آن سرزمین در انزوا سپری خواهند کرد...».\r\n"},{"id":1506,"category_id":10,"category_code":"s10","source_id":68,"title":"هر چه خدا بخواهد ","content":"سالهای بسیار دور پادشاهی زندگی می کرد که وزیری داشت.\r\n\r\nوزیر همواره می گفت: هر اتفاقی که رخ می دهد به صلاح ماست.\r\n\r\nروزی پادشاه برای پوست کندن میوه کارد تیزی طلب کرد اما در حین بریدن میوه انگشتش را برید، وزیر که در آنجا بود گفت: نگران نباشید تمام چیزهایی که رخ میدهد در جهت خیر و صلاح شماست !\r\n\r\nپادشاه از این سخن وزیر برآشفت و از رفتار او\r\nدر برابر این اتفاق آزرده خاطر شد و دستور زندانی کردن وزیر را داد...\r\n\r\nچند روز بعد پادشاه با ملازمانش برای شکار به نزدیکی جنگلی رفتند. پادشاه در حالی که مشغول اسب سواری بود راه را گم کرد و وارد جنگل انبوهی شد و از ملازمان خود دور افتاد، در حالی که پادشاه به دنبال راه بازگشت بود به محل سکونت قبیلهای رسید که مردم آن در حال تدارک مراسم قربانی برای خدایانشان بودند،  زمانی که مردم پادشاه خوش سیما را دیدند خوشحال شدند زیرا تصور کردند وی بهترین قربانی برای تقدیم به خدای آنهاست!!!\r\n\r\nآنها پادشاه را در برابر تندیس الهه خود بستند تا وی را بکشند، اما ناگهان یکی از مردان قبیله فریاد کشید: چگونه می توانید این مرد را برای قربانی کردن انتخاب کنید در حالی که وی بدنی ناقص دارد، به انگشت او نگاه کنید !!! به همین دلیل وی را قربانی نکردند و آزاد شد.\r\n\r\nپادشاه که به قصر رسید وزیر را فراخواند و گفت: اکنون فهمیدم منظور تو از اینکه می گفتی هر چه رخ می دهد به صلاح شماست چه بوده زیرا بریده شدن انگشتم موجب شد زندگی ام نجات یابد اما در مورد تو چی؟ تو به زندان افتادی این امر چه خیر و صلاحی برای تو داشت؟!!\r\nوزیر پاسخ داد: پادشاه عزیز مگر نمی بینید، اگر من به زندان نمی افتادم مانند همیشه در جنگل به همراه شما بودم در آنجا زمانی که شما را قربانی نکردند مردم قبیله مرا برای قربانی کردن انتخاب می کردند، بنابراین می بینید که حبس شدن نیز برای من مفید بود!!!\r\n"},{"id":1507,"category_id":10,"category_code":"s10","source_id":69,"title":"ما چقدر زود باور هستیم","content":"دانشجویی که سال آخر دانشگاه را می گذراند به خاطر پروژه ای که انجام داده بود جایزه اول را گرفت. او در پروژه خود از ۵۰ نفر خواسته بود تا دادخواستی مبنی بر کنترل سخت و یا حذف ماده شیمیایی «دی هیدروژن مونوکسید» توسط دولت را امضا کنند و برای این خواسته خود دلایل زیر را عنوان کرده بود...\r\n۱- مقدار زیاد آن باعث عرق کردن زیاد و استفراغ می شود.\r\n۲- یک عنصر اصلی باران اسیدی است\r\n۳- وقتی به حالت گاز در می آید بسیار سوزاننده است\r\n۴- استنشاق تصادفی آن باعث مرگ فرد می شود.\r\n۵- باعث فرسایش اجسام می شود\r\n۶- حتی روی ترمز اتوموبیل ها اثر منفی می گذارد\r\n۷- حتی در تومورهای سرطانی نیز یافت شده است\r\nاز ۵۰ نفر فوق ۴۳ نفر دادخواست را امضا کردند. ۶ نفر به طور کلی علاقه ای نشان ندادند و اما فقط یک نفر می دانست که ماده شیمیایی «در هیدروژن مونوکسید» در واقع همان آب است!\r\nعنوان پروژه دانشجوی فوق «ما چقدر زود باور هستیم» بود!!!!\r\n"},{"id":1508,"category_id":10,"category_code":"s10","source_id":70,"title":"هدیه ","content":"اولین سال تدریس در یکی از روستا ها تدریس می کردم . اواسط اردیبهشت بود\r\n.موقع تدریس صدای شکستن شیئی در کلاس توجه مرا به خود جلب کرد. از گریه\r\nهای ابوالفضل فهمیدم گلدانی را که با خود به کلاس آورده بود از زیر میزش\r\nافتاد و شکست . اشک هایش را پاک کردم و با هم تکه های  شکسته گلدان  را\r\nجمع کردیم . روی یکی از تکه های گلدان کاغذ کوچکی چسبانده شده بود. سپاس\r\nمعلم ، روزت مبارک.\r\n"},{"id":1509,"category_id":10,"category_code":"s10","source_id":71,"title":"اینجا هم همینطور ","content":"پیرمرد روی نیمکت نشسته بود و کلاهش را روی سرش کشیده بود و استراحت می کرد. سواری نزدیک شد و از او پرسید: هی پیری! مردم این شهر چه جور آدم هاییند؟ \r\nپیرمرد پرسید: مردم شهر تو چه جوریند؟ \r\nگفت: مزخرف ! ..\r\nپیرمرد گفت: این جا هم همین طور! \r\nبعد از چند ساعت سوار دیگری نزدیک شد و همین سؤال را پرسید. \r\nپیرمرد باز هم از او پرسید :مردم شهر تو چه جوریند؟ \r\nگفت: خب! مهربونند. \r\nپیرمرد گفت: این جا هم همین طور !!!!\r\n"},{"id":1510,"category_id":10,"category_code":"s10","source_id":72,"title":"سرعت یعنی این! ","content":"سه تا پسر درباره پدرهایشان لاف می زدند:\r\n\r\nاولی گفت: «پدر من سریعترین دونده است. اون می تونه یک تیر رو با تیرکمون پرتاب کنه و بعد از شروع به دویدن، از تیر جلو بزنه.»\r\n\r\nدومی گفت: «تو به این میگی سرعت؟ پدر من شکارچیه. اون شلیک میکنه و زودتر از گلوله به شکار میرسه.»\r\n\r\nسومی سرشو تکون داد و گفت: «شما دو تا هیچی راجع به سریع بودن نمی دونید. پدر من کارمند دولتی است. اون کارشو ساعت ۴:۳۰ تعطیل میکنه و ۳:۴۵ تو خونه است!»\r\n"},{"id":1511,"category_id":10,"category_code":"s10","source_id":73,"title":"از کرَه گی دُم نداشتن ","content":"مردی خری دید به گل در نشسته و صاحب خر از بیرون کشیدن آن درمانده . مساعدت را ( برای کمک کردن ) دست در دُم خر زده قُوَت کرد( زور زد ) . دُم از جای کنده آمد . فغان از صاحب خر برخاست که \" تاوان بده !\" \r\nمرد به قصد فرار به کوچه یی دوید ، بن بست یافت . خود را به خانه یی درافگند . زنی آنجا کنار حوض خانه چیزی میشست و بار حمل داشت ( حامله بود ) . از آن هیاهو و آواز در بترسید ، بار بگذاشت ( سِقط کرد ) . خانه خدا ( صاحبِ خانه ) نیز با صاحب خر هم آواز شد . \r\nمردِ گریزان بر بام خانه دوید . راهی نیافت ، از بام به کوچه یی فروجست که در آن طبیبی خانه داشت . مگر جوانی پدر بیمارش را به انتظار نوبت در سایهء دیوار خوابانده بود ؛ مرد بر آن پیر بیمار فرود آمد ، چنان که بیمار در حای بمُرد .. پدر مُرده نیز به خانه خدای و صاحب خر پیوست !\r\nمَرد ، همچنان گریزان ، در سر پیچ کوچه با یهودی رهگذر سینه به سینه شد و بر زمینش افگند . پاره چوبی در چشم یهودی رفت و کورش کرد . او نیز نالان و خونریزان به جمع متعاقبان پیوست !\r\nمرد گریزان ، به ستوه از این همه، خود را به خانهء قاضی افگند که \" دخیلم! \" . مگر قاضی در آن ساعت با زن شاکیه خلوت کرده بود . چون رازش فاش دید ، چارهء رسوایی را در جانبداری از او یافت : و چون از حال و حکایت او آگاه شد ، مدعیان را به درون خواند ... \r\nنخست از یهودی پرسید .\r\nگفت : این مسلمان یک چشم مرا نابینا کرده است . قصاص طلب میکنم .\r\nقاضی گفت : دَیتِ مسلمان بر یهودی نیمه بیش نیست . باید آن چشم دیگرت را نیز نابینا کند تا بتوان از او یک چشم برکند !\r\nو چون یهودی سود خود را در انصراف از شکایت دید ، به پنجاه دینار جریمه محکومش کرد !\r\nجوانِ پدر مرده را پیش خواند .\r\nگفت : این مرد از بام بلند بر پدر بیمار من افتاد ، هلاکش کرده است . به طلب قصاص او آمده ام .\r\nقاضی گفت : پدرت بیمار بوده است ، و ارزش حیات بیمار نیمی از ارزش شخص سالم است . حکم عادلانه این است که پدر او را زیر همان دیوار بنشانیم و تو بر او فرودآیی ، چنان که یک نیمهء جانش را بستانی !\r\n\r\nو جوانک را نیز که صلاح در گذشت دیده بود ، به تأدیهء سی دینار جریمهء شکایت بیمورد محکوم کرد !\r\nچون نوبت به شوی آن زن رسید که از وحشت بار افکنده بود ، گفت : قصاص شرعاً هنگامی جایز است که راهِ جبران مافات بسته باشد . حالی میتوان آن زن را به حلال در فراش ( عقد ازدواج )  این مرد کرد تا کودکِ از دست رفته را جبران کند . طلاق را آماده باش !\r\nمردک فغان برآورد و با قاضی جدال میکرد ، که ناگاه صاحب خر برخاست و به جانب در دوید ..\r\nقاضی آواز داد : هی ! بایست که اکنون نوبت توست !\r\nصاحب خر همچنان که میدود فریاد کرد : مرا شکایتی نیست . محکم کاری را ، به آوردن مردانی میروم که شهادت دهند خر مرا  از گره گی دُم نبوده است.\r\n"},{"id":1512,"category_id":10,"category_code":"s10","source_id":74,"title":"خوشحالی ","content":"حدود نیمه های شب بود.\r\nدمیتری کولدارف ، هیجان زده و آشفته و دیوانه وار به آپارتمان پدر و مادرش دوید و تمام اتاقها را با عجله زیر پا گذاشت. در این ساعت ، والدین او قصد داشتند بخوابند. خواهرش در رختخواب خود دراز کشیده و گرم خواندن آخرین صفحه ی یک رمان بود. برادران دبیرستانی اش خواب بودند.\r\nپدر و مادرش متعجبانه پرسیدند:\r\nــ تا این وقت شب کجا بودی ؟ چه ات شده ؟\r\nــ وای که نپرسید! اصلاً فکرش را نمیکردم! انتظارش را نداشتم! حتی …\r\nحتی باور کردنی نیست!\r\nبلند بلند خندید و از آنجایی که رمق نداشت سرپا بایستد ، روی مبل نشست و ادامه داد:\r\nــ باور نکردنی! تصورش را هم نمی توانید بکنید! این هاش ، نگاش کنید!\r\nخواهرش از تخت به زیر جست ، پتویی روی شانه هایش افکند و به طرف او رفت. برادران محصلش هم از خواب بیدار شدند.\r\nــ آخر چه ات شده ؟ رنگت چرا پریده ؟\r\nــ از بس که خوشحالم ، مادر جان! حالا دیگر در سراسر روسیه مرا می شناسند! سراسر روسیه! تا امروز فقط شما خبر داشتید که در این دار دنیا کارمند دون پایه ای به اسم دمیتری کولدارف وجود خارجی دارد! اما حالا سراسر روسیه از وجود من خبردار شده است! مادر جانم! وای خدای من!\r\nبا عجله از روی مبل بلند شد ، بار دیگر همه ی اتاقهای آپارتمان را به زیر پا کشید و دوباره نشست.\r\nــ بالاخره نگفتی چه اتفاقی افتاده ؟ درست حرف بزن ؟\r\nــ زندگی شماها به زندگی حیوانات وحشی می ماند ، نه روزنامه می خوانید ، نه از اخبار خبر دارید ، حال آنکه روزنامه ها پر از خبرهای جالب است! تا اتفاقی می افتد فوری چاپش میکنند. هیچ چیزی مخفی نمی ماند! وای که چقدر خوشبختم! خدای من! مگر غیر از این است که روزنامه ها فقط از آدمهای سرشناس می نویسند؟ … ولی حالا ، راجع به من هم نوشته اند!\r\nــ نه بابا! ببینمش!\r\nرنگ از صورت پدر پرید. مادر ، نگاه خود را به شمایل مقدسین دوخت و صلیب بر سینه رسم کرد. برادران دبیرستانی اش از جای خود جهیدند و با پیراهن خوابهای کوتاه به برادر بزرگشان نزدیک شدند.\r\nــ آره ، راجع به من نوشته اند! حالا دیگر همه ی مردم روسیه ، مرا می شناسند! مادر جان ، این روزنامه را مثل یک یادگاری در گوشه ای مخفی کنید! گاهی اوقات باید بخوانیمش. بفرمایید ، نگاش کنید!\r\nروزنامه ای را از جیب در آورد و آن را به دست پدر داد. آنگاه انگشت خود را به قسمتی از روزنامه که با مداد آبی رنگ ، خطی به دور خبری کشیده بود ، فشرد و گفت:\r\nــ بخوانیدش!\r\nپدر ، عینک بر چشم نهاد.\r\nــ معطل چی هستید ؟ بخوانیدش!\r\nمادر ، باز نگاه خود را به شمایل مقدسین دوخت و صلیب بر سینه رسم کرد. پدر سرفه ای کرد و مشغول خواندن شد: « در تاریخ 29 دسامبر ، مقارن ساعت 23 ، دمیتری کولدارف … »\r\nــ می بینید ؟ دیدید ؟ ادامه اش بدهید!\r\nــ  دمیتری کولدارف کارمند دون پایه ی دولت ، هنگام خروج از مغازه ی آبجو فروشی واقع در مالایا برونا (ساختمان متعلق به آقای کوزیخین) به علت مستی … \r\nــ می دانید با سیمون پترویچ رفته بودیم آبجو بزنیم … می بینید ؟ جزء به جزء نوشته اند! ادامه اش بدهید! ادامه!\r\nــ  به علت مستی ، تعادل خود را از دست داد ، سکندری رفت و به زیر پاهای اسب سورتمه ی ایوان دروتف که در همان محل متوقف بود ، افتاد. سورچی مذکور اهل روستای دوریکین از توابع بخش یوخوسکی است. اسب وحشت زده از روی کارمند فوق الذکر جهید و سورتمه را که یکی از تجار رده ی 2 مسکو به اسم استپان لوکف سرنشین آن بود ، از روی بدن شخص مزبور ، عبور داد. اسب رمیده ، بعد از طی مسافتی توسط سرایدارهای ساختمانهای همان خیابان ، مهار شد. کولدارف که به حالت اغما افتاده بود ، به کلانتری منتقل گردید و تحت معاینه ی پزشکی قرار گرفت. ضربه ی وارده به پشت گردن او … \r\nــ پسِ گردنم ، پدر ، به مال بند اسب خورده بود . بخوانیدش ؛ ادامه اش بدهید!\r\nــ « … به پشت گردن او ، ضربه ی سطحی تشخیص داده شده است. کمکهای ضروری پزشکی ، بعد از تنظیم صورتمجلس و تشکیل پرونده ، در اختیار مصدوم قرار داده شد »\r\nــ دکتر برای پس گردنم ، کمپرس آب سرد تجویز کرد. خواندید که ؟ ها ؟ محشر است! حالا دیگر این خبر در سراسر روسیه پیچید!\r\nآنگاه روزنامه را با عجله از دست پدرش قاپید ، آن را چهار تا کرد و در جیب کت خود چپاند و گفت:\r\nــ مادر جان ، من یک تک پا می روم تا منزل ماکارف ، باید نشانشان داد … بعدش هم سری به ناتالیا ایوانونا و آنیسیم واسیلیچ میزنم و میدهم آنها هم بخوانند … من رفتم! خداحافظ!\r\nاین را گفت و کلاه نشاندار اداری را بر سر نهاد و شاد و پیروزمند ، به کوچه دوید.\r\n"},{"id":1513,"category_id":10,"category_code":"s10","source_id":75,"title":"شانس خود را امتحان کنید ","content":"مرد جوانی در آرزوی ازدواج با دختر کشاورزی بود.\r\nکشاورز گفت برو در آن قطعه زمین بایست. من سه گاو نر را آزاد می کنم اگر توانستی دم یکی از این گاو نرها را بگیری من دخترم را به تو خواهم داد. مرد قبول کرد. در طویله اولی که بزرگترین بود باز شد .\r\nباور کردنی نبود بزرگترین و خشمگین ترین گاوی که در تمام عمرش دیده بود. گاو با سم به زمین می کوبید و به طرف مرد جوان حمله برد. جوان خود را کنار کشید تا گاو از مرتع گذشت. دومین در طویله که کوچکتر بود باز شد.\r\nگاوی کوچکتر از قبلی که با سرعت حرکت کرد .\r\n\r\nجوان پیش خودش گفت : منطق می گوید این را ولش کنم چون گاو بعدی کوچکتر است و این ارزش جنگیدن ندارد. سومین در طویله هم باز شد و همانطور که فکر میکرد ضعیفترین و کوچکترین گاوی بود که در تمام عمرش دیده بود.\r\n\r\nپس لبخندی زد و در موقع مناسب روی گاو پرید و دستش را دراز کرد تا دم گاو را بگیرد.اما.........گاو دم نداشت!!!!\r\n\r\nزندگی پر از ارزشهای دست یافتنی است اما اگر به آنها اجازه رد شدن بدهیم ممکن است که دیگر هیچ وقت نصیبمان نشود. برای همین سعی کن که همیشه اولین شانس را دریابی.\r\n"},{"id":1514,"category_id":10,"category_code":"s10","source_id":76,"title":"شاهدان","content":"مسافری در شهر بلخ جماعتی را دید که مردی زنده را در تابوت انداخته و به سوی گورستان می برند و آن بیچاره مرتب داد و فریاد می زند و خدا و پیغمبر را به شهادت می گیرد که \" والله، بالله من زنده ام! چطور می خواهید مرا به خاک بسپارید؟\"\r\n\r\nاما چند ملا که پشت سر تابوت هستند، بی توجه به حال و احوال او رو به مردم کرده و می گویند: \" پدرسوخته ی ملعون دروغ می گوید. مُرده\"\r\nمسافر حیرت زده حکایت را پرسید. گفتند: «این مرد فاسق و تاجری ثروتمند و بدون وارث است. چند مدت پیش که به سفر رفته بود، چهار شاهد عادل خداشناس در محضر قاضی بلخ شهادت دادند که ُمرده و قاضی نیز به مرگ او گواهی داد. پس یکی از مقدسین شهر زنش را گرفت و یکی دیگر اموالش را تصاحب کرد. حالا بعد از مرگ برگشته و ادعای حیات می کند. حال آنکه ادعای مردی فاسق در برابر گواهی چهار عادل خداشناس مسموع و مقبول نمی افتد. این است که به حکم قاضی به قبرستانش میبریم، زیرا که دفن میّت واجب است و معطل نهادن جنازه شرعا ً جایز نیست!\"\r\n"},{"id":1515,"category_id":10,"category_code":"s10","source_id":77,"title":"وضو","content":"اسمش علی بود .جانباز شیمیایی 8 سال دفاع مقدس . دیروز مراسم سومین روز\r\nشهادت او را برگزار کردند.26 سال قبل من و علی در مدرسه ابتدایی علوی\r\nدرس می خواندیم. شیطان بودیم و شلوغ . گاهی اوقات برای در آوردن لج ناظم\r\nمدرسه موقع نماز  بدون مسح پا وضو می گرفتیم. سه سال قبل که  دانش\r\nآموختگان سال های قبل  دورهم جمع شده بودند، علی باز هم بدون مسح پا وضو\r\nگرفت . پاهای سردار شهید آذری قبل از خودش وارد بهشت شده بودند.\r\n"},{"id":1516,"category_id":10,"category_code":"s10","source_id":78,"title":"راز ثروتمندی","content":"مردی چهار پسر داشت. هنگامی  که در بستر بیماری افتاد، یکی از پسرها به برادرانش گفت: «یا شما مواظب پدر باشید و از او ارثی نبرید، یا من پرستاری اش می کنم و از مال او چیزی نمی خواهم؟!» برادران با خوش حالی نگه داری از پدر را به عهده او گذاشتند و رفتند. پس از مدتی پدر مُرد. شبی پسر در خواب دید که به او می گویند در فلان جا، صد دینار است، برو آن را بردار، اما بدان که در آن خیر و برکتی نیست!\r\nپسر سراغ پول ها نرفت. دو شب بعد هم همان خواب ها تکرار شد تا آن که در شب سوم خواب دید که می گویند، در فلان مکان یک درهم است. آن را بردار که پرخیر و برکت است!\r\nپسر صبح از خواب برخاست و همان  جایی که خواب دیده بود، رفت و یک درهم را برداشت. در راه با آن دو ماهی خرید. هنگامی که شکم آن ها را پاره کرد، در شکم هر کدام یک دُر یافت. یکی از دُرها را به درگاه سلطان برد. پادشاه که از آن خوشش آمده بود، پول زیادی به پسر داد و گفت: اگر لنگه دیگر آن  را بیاوری، پول بیش تری می گیری!\r\nپسر دُر دیگر را نیز به قصر شاه برد. سلطان با دیدن دُر به وعده اش عمل کرد و پسر به برکت احترام به پدرش از ثروت مندترین مردان روزگار شد.\r\n"},{"id":1517,"category_id":10,"category_code":"s10","source_id":79,"title":"مکافات عمل ","content":"فرزندی پدر پیرش را کُول کرد و به کوهستان  برد. وقتی به بالای کوه رسید، پسر غاری پیدا کرد و پدر را آن جا گذاشت. هنگامی که می خواست برگردد، با خنده های پدر پیرش مواجه شد. پسر با تعجب به او نگاه کرد و گفت: «به چه می خندی پدر؟!»\r\nپدر نگاهی به پسر جوانش کرد و گفت: «من هم چون تو، روزی پدر پیر و ناتوانم را همین جا رها کردم و رفتم و حالا تو مرا این جا آوردی. روزی هم پسرت تو را به این جا خواهد آورد!»\r\nپسر لحظه ای به حرف های پدرش اندیشید و آن گاه از ترس آن که مبادا روزی پسرش هم با او چنین کند، پدر را برداشت و به خانه آورد.\r\n"},{"id":1518,"category_id":10,"category_code":"s10","source_id":80,"title":"پیپ استالین و اعتراف هیات گرجستانی ","content":"در روزگاری نه چندان دور یک هیات از گرجستان برای ملاقات با استالین به مسکو آمده بودند . پس از جلسه استالین متوجه شد که پیپش گم شده است و به همین خاطر از رییس \" کا.گ.ب \" خواست تا ببیند آیا کسی از هیات گرجستانی پیپ او را برداشته است یا نه ؟\r\nپس از چند ساعت استالین پیپش را در کشوی میزش پیدا کرد و از رییس \" کا.گ.ب \" خواست که هیات گرجی را آزاد کند .\r\nرییس \" کا.گ.ب \" اما گفت : \" متاسفم رفیق ، تقریبا نصف هیات اقرار کرده اند که پیپ را برداشته اند و تعدادی هم موقع بازجویی مرده اند.\r\n"},{"id":1519,"category_id":10,"category_code":"s10","source_id":81,"title":"زندگی مجدد","content":"جوانى ادعا مى کرد که قبلاً هم زندگى کرده است... و دانشمندان شکاکى که او را تست مى کردند شکست را با تلخى تمام پذیرفتند. این موردى بود که نه قادر به توصیف و توضیح آن بودند و نه مى توانستند آن را تکذیب کنند. \r\nوالدین «شانتى دوى» خانواده اى از طبقه متوسط جامعه بودند که در شهر دهلى هندوستان در آرامش زندگى مى کردند، تا اینکه در سال ،۱۹۲۶ « شانتى» دیده به جهان گشود.. در ابتداى تولد هیچ چیز غیرعادى نبود. اما... \r\nهمچنانکه او بزرگتر مى شد و دوران کودکى را پشت سرمى گذاشت مادرش متوجه شد که فرزندش دچار گیجى و سردرگمى است وقتى کمى بیشتر به کارهاى او دقت کرد، به نظرش رسید که\r\n او با یک شخص خیالى مشغول صحبت و گفت وگو است. \r\nاو هفت سال بیشتر نداشت با این حال والدینش در مورد سلامتى عقل او نگران شدند.. در همان سال بود که شانتى کوچک به مادرش گفت قبلاً در شهر کوچکى به نام موترا زندگى مى کرده است و به توصیف خانه اى پرداخت که روزگارى در آن زندگى کرده است.. مادر شانتى گفته هاى دختر را براى پدربازگو کرد و پدر نیز فرزندش را پیش پزشک برد. بعد از اینکه «شانتى» داستان عجیب خود را براى پزشک گفت؛ او تنها سرش را تکان مى داد. اگر این دختر دچار بیمارى عقلى بود مورد بسیار نادرى به شمار مى رفت و اگر چنین نبود دکتر جرأت بیان حقیقت را نداشت.. دکتر به پدر شانتى توصیه کرد گه گاه سؤالاتى را از دخترش بکند و اگر پاسخهایش همچنان یکسان بود، مجدداً به وى مراجعه کنند. \r\n«شانتى» هرگز داستانش را تغییر نداد. تا اینکه به سن ۹ سالگى رسید. در این مدت والدین پریشان حال او دیگر از حرفهایش متعجب نمى شدند زیرا با بى میلى پذیرفته بودند که دخترشان دیوانه شده است. \r\nسال ۱۹۳۵ بود. روزى شانتى به والدینش گفت او در موترا ازدواج کرده و سه فرزند به دنیا آورده است. سپس مشخصات کودکان او خود نام آنها را گفت و ادعا کرد نام خودش در زندگى قبلى اش «لوجى» بوده است اما والدینش تنها مى خندیدند و اندوه خود را پنهان مى کردند. \r\nدر یک بعدازظهر که شانتى و مادرش مشغول آماده کردن عصرانه بودند، کسى در زد و دختر به طرف در دوید تا در را باز کند. اما بازگشت وى بیش از حد معمول طول کشید. شانتى به غریبه اى که روى پله ها ایستاده بود، خیره شده بود او گفت مادر! این مرد پسرعموى شوهرم است. او هم در شهر موترا در محلى نه چندان دورتر از منزل ما زندگى مى کرد. \r\nآن مرد واقعاً در شهر موترا زندگى مى کرد و آمده بود تا در مورد کارى با پدر شانتى گفت وگو کند.. او شانتى را نمى شناخت اما به والدین دختر گفت پسرعمویى دارد که همسر او لوجى نام داشت و ۱۰ سال قبل، هنگام به دنیا آوردن فرزندش جان خود را از دست داد. \r\nوالدین دلواپس و پریشان شانتى داستان عجیب دخترشان را براى او تعریف کردند و مرد غریبه نیز موافقت کرد در مراجعت بعدى خود به دهلى پسرعمویش را همراه بیاورد تا ببینند شانتى او را مى شناسد یا خیر. \r\nدختر جوان از این موضوع اطلاع نداشت، اما زمانیکه مرد غریبه وارد شد، شانتى به سوى او رفت و با صداى لرزان وبعض آلود گفت این مرد شوهرش است که پیش او بازگشته است. والدین شانتى به همراه مرد که کاملاً گیج و متحیر شده بود نزد مقامات رفتند و داستان باورنکردنى خود را بازگو کردند. دولت هند تیم مخصوصى از دانشمندان تشکیل داد تا در مورد این موضوع که توجه عموم را به خود جلب کرده بود؛ بررسى و تحقیق به عمل آورد.. آیا شانتى واقعاً صورت تناسخ یافته لوجى بود؟ \r\nدانشمندان شانتى را با خود به شهر کوچک موترا بردند. هنگامى که وى از قطار پیاده شد مادر و برادرشوهرش را شناخت و نام آنها را به زبان آورد و به راحتى با زبان محلى موترا با آنان گفت وگو کرد. در حالیکه والدینش فقط به او زبان هندى آموخته بودند. دانشمندان با حیرت فراوان به آزمایشاتشان ادامه دادند. آنان چشمان شانتى را بستند و او را سوار کالسکه کردند. شانتى بدون تأمل، راننده را در شهر هدایت مى کرد و مشخصات مهم هر ناحیه اى را که از آن عبور مى کردند، توصیف مى کرد و او به راننده گفت که در انتهاى کوچه باریکى توقف کند. \r\nاو گفت: اینجا مکانى است که من زندگى مى کردم. هنگامى که چشمانش را گشودند او پیرمردى را دید که جلوى خانه نشسته بود و سیگار مى کشید. شانتى به همراهانش گفت: آن مرد پدر شوهرش است! در واقع آن مرد پدر شوهر لوجى بود. شانتى بطور باورنکردنى دو فرزند بزرگترش را شناخت. اما کوچکترین آنها را که تولدش به قیمت زندگى لوجى تمام شده بود، نشناخت. \r\nدانشمندان عقیده داشتند کودکى که در دهلى به دنیا آمده به نحوى زندگى خانواده اى را با تمام جزییات به یاد مى آورد. گزارش آنها حاکى از این بود که هیچ نشانى از فریبکارى وجود ندارد و همچنین براى آنچه که دیده اند نمى توانند دلیل و توضیحى ارائه دهند. \r\nداستان کاملاً مستند شانتى دوى که اکنون به عنوان کارمند دولت در دهلى نو زندگى آرامى دارد در پرونده هاى پزشکى و دولتى به ثبت رسیده است. در سال ۱۹۸۵ وى در پاسخ به سؤال متخصصین گفته بود. یاد گرفته است تا خودش را با زندگى در زمان حال تطبیق دهد و اشتیاق دیرینه او به گذشته عجیبش، آن چنان مزاحمتى براى اوایجاد نکرده است. \r\n"},{"id":1520,"category_id":10,"category_code":"s10","source_id":82,"title":"درسی از ابومسلم خراسانی ","content":"شاگرد معمار، جوانی بسیار باهوش اما عجول بود گاهی تا گوشی برای شنیدن می یافت شروع می کرد تعریف نمودن از توانایی های خویش در معماری و در نهایت می نالید از این که کسی قدر او را نمی داند و حقوقش پایین است.\r\n\r\nروزی برای سلمانی به راه افتاد دید سلمانی مشغول است و کسی را موی کوتاه می کند . فرصت را مناسب شمرده و باز از هنر خویش بگفت و اینکه کسی قدر او را نمی داند و او هنوز نتوانسته خانه خوبی برای خویش دست و پا کند. به اینجای کار که رسید کار سلمانی هم تمام شد .\r\n\r\nمردی که مویش کوتاه شده بود رو به جوان کرده و گفت\r\nآیا چون هنر داری دیگران باید برایت اسباب آسایش بگسترند ؟!\r\n\r\nجوان گفت: آری\r\n\r\nمرد تنومند دستی به موهای سفیدش کشید و گفت: اگر هنر تو نقش زیبای کاشانه ایی شود پولی گیری در غیر اینصورت با گدای کوچه و بازار فرقی نداری .\r\n\r\nچون از او دور شد جوانک از استاد سلمانی پرسید او که بود که اینچنین گستاخانه با من سخن گفت؟\r\n\r\nاستاد خندید و گفت سالار ایرانیان، ابومسلم خراسانی. جوان لرزید و گفت: آری حق با او بود من بیش از حد پر توقع هستم.\r\n\r\nاندیشمند یگانه کشورمان ارد بزرگ می گوید : “آنچه بدست خواهی آورد فراتر از رنج و زحمتت نخواهد بود .”\r\nابومسلم خراسانی با این حرف به آن جوان آموخت هنر بدون کار هیچ ارزشی ندارد و هنرمند بیکار و بی ثمر هم با گدا فرقی ندارد.\r\n"},{"id":1521,"category_id":10,"category_code":"s10","source_id":83,"title":"انتقام زن ","content":"زنگ در را به صدا در آوردند. نادژدا پترونا ، مالک آپارتمانی که محل وقوع داستان ماست ، شتابان از روی کاناپه بلند شد و دوان دوان به طرف در رفت. با خود میگفت: « لابد شوهرم است … »\r\nاما وقتی در را باز کرد ، با مردی ناآشنا روبرو شد. مردی بلند قامت و خوش قیافه ، با پالتو پوست نفیس و عینک دسته طلایی در برابرش ایستاده بود ؛ گره بر ابرو و چین بر پیشانی داشت ؛ چشمهای خواب آلودش با نوعی بیحالی و بی اعتنایی ، به دنیای خاکی ما مینگریستند. نادژدا پرسید:\r\nــ فرمایش دارید ؟\r\nــ من پزشک هستم خانم محترم. از طرف خانواده ای به اسم … به اسم چلوبیتیف به اینجا دعوت شده ام …\r\nچلوبیتیف نیستید؟\r\nــ چرا … خودم هستم … اما شما را به خدا آقای دکتر … معذرت میخواهم. شوهرم گذشته از آنکه تب داشت ، دندانش هم آپسه کرده بود. خود او خدمتتان نامه نوشته و خواهش کرده بود تشریف بیاورید اینجا ولی شما ، از بس دیر کردید که او نتوانست درد دندان را تحمل کند و رفت پیش دندانساز.\r\nــ هوم … حق این بود که نزد دندانپزشکش می رفت و مزاحم من نمی شد …\r\nاین را گفت و اخم کرد. حدود یک دقیقه در سکوت گذشت.\r\nــ آقای دکتر از زحمتی که به شما دادیم و شما را تا اینجا کشاندیم عذر میخواهم … باور کنید اگر شوهرم میدانست که تشریف می آورید ، ممکن نبود پیش دندانساز برود … ببخشید …\r\nدقیقه ای دیگر در سکوت گذشت. نادژدا پترونا پشت گردن خود را خاراند. دکتر زیر لب لندلندکنان گفت:\r\nــ خانم محترم ، لطفاً مرخصم کنید! جایز نیست بیش از این معطل شوم. وقت ماها آنقدر ارزش دارد که …\r\nــ یعنی … من که … من که معطلتان نکرده ام …\r\nــ ولی خانم محترم ، بنده که نمی توانم بدون دریافت حق القدم از خدمتتان مرخص شوم!\r\nنادژدا پترونا تا بناگوش سرخ شد و تته پته کنان گفت:\r\nــ حق القدم ؟ آه ، بله ، حق با شماست … باید حق القدم داد ، درست می فرمایید … شما زحمت کشیده اید ، تشریف آورده اید اینجا … ولی آقای دکتر … باور بفرمایید شرمنده ام … موقعی که شوهرم از منزل بیرون میرفت ، کیف پولمان را هم با خودش برد … متأسفانه یک پاپاسی در خانه ندارم …\r\nــ هوم! … عجیب است! … پس می فرمایید تکلیف بنده چیست؟ من که نمیتوانم همین جا بنشینم و منتظر شوهرتان باشم. اتاقهایتان را بگردید شاید پولی پیدا کنید … حق القدم من ، در واقع مبلغ قابلی نیست …\r\nــ آقای دکتر باور بفرمایید شوهرم تمام پولمان را با خودش برده … من واقعاً شرمنده ام … اگر پولی همراهم بود ممکن نبود بخاطر یک روبل ناقابل ، این وضع … وضع احمقانه را تحمل کنم …\r\nــ مردم تلقی عجیبی از حق القدم پزشک ها دارند … به خدا قسم که تلقی شان مایه ی حیرت است! طوری رفتار میکنند که انگار ما آدم نیستیم. کار و زحمت ما را ، کار به حساب نمی آورند … فکر کنید اینهمه راه را آمده ام و زحمت کشیده ام … وقتم را تلف کرده ام …\r\nــ مشکل شما را می فهمم آقای دکتر ، ولی قبول بفرمایید گاهی اوقات ممکن است در خانه ی آدم حتی یک صناری پیدا نشود!\r\nــ آه … من چه کار به این « گاهی اوقات ها » دارم ؟ خانم محترم شما واقعاً که … ساده و غیر منطقی تشریف دارید … خودداری از پرداخت حق القدم یک پزشک … عملی است ــ حتی نمیتوانم بگویم ــ خلاف وجدان … از اینکه نمیتوانم از دست شما به پاسبان سر کوچه شکایت کنم ، آشکارا سوءاستفاده میکنید … واقعاً که عجیب است!\r\nآنگاه اندکی این پا و آن پا کرد … بجای تمام بشریت ، احساس شرمندگی میکرد … صورت نادژدا پترونا به قدری سرخ شد که گفتی لپهایش مشتعل شده بودند ؛ عضلات چهره اش از شدت نفرت و انزجار ، تاب برداشته بودند ؛ بعد از سکوتی کوتاه ، با لحن تندی گفت:\r\nــ بسیار خوب! یک دقیقه به من مهلت بدهید! … الان کسی را به دکان سر کوچه مان می فرستم ، شاید بتوانم از او قرض بگیرم … حق القدمتان را می پردازم ، نگران نباشید.\r\nسپس به اتاق مجاور رفت و یادداشتی برای کاسب سر گذر نوشت. دکتر پالتو پوست خود را در آورد ، به اتاق پذیرایی رفت و روی مبلی یله داد. هر دو خاموش و منتظر بودند. حدود پنج دقیقه بعد ، جواب آمد. نادژدا پترونا سر پاکت را باز کرد ، از لای یادداشت جوابیه ی کاسب ، یک اسکناس یک روبلی در آورد و آن را به طرف دکتر دراز کرد. چشمهای پزشک از شدت خشم درخشیدند. اسکناس را روی میز گذاشت و گفت:\r\nــ خانم محترم از قرار معلوم ، بنده را دست انداخته اید … شاید نوکرم یک روبل بگیرد ولی … بنده هرگز! ببخشید …\r\nــ پس چقدر میخواهید ؟!\r\nــ معمولاً ده روبل می گیرم … البته اگر مایل باشید می توانم از شما پنج روبل قبول کنم.\r\nــ پنج روبلم کجا بود ؟ … من همان اول کار به شما گفتم: پول ندارم!\r\nــ یادداشت دیگری برای کاسب سر گذر بفرستید. آدمی که بتواند به شما یک روبل قرض بدهد ، چرا پنج روبل ندهد؟ مگر برایش فرق میکند؟ خانم محترم ، لطفاً بیش از این معطلم نکنید. من آدم بیکاری نیستم ، وقت ندارم …\r\nــ گوش کنید آقای دکتر ، اگر اسمتان را « گستاخ » ندانم ، دستکم باید بگویم که .. کم لطف و نامهربان تشریف دارید! نه! خشن و بیرحم! حالیتان شد؟ شما … نفرت انگیز هستید!\r\nنادژدا پترونا به طرف پنجره چرخید و لب به دندان گرفت ؛ قطره های درشت اشک از چشمهایش فرو غلتیدند. با خود فکر کرد:\r\n« مردکه ی پست فطرت! بی شرف! حیوان صفت! به خودش اجازه میدهد … جرأت میکند … آخر چرا نباید وضع وحشتناک و اسفناک مرا درک کند؟ … لعنتی! صبر کن تا حالیت کنم! »\r\nدر این لحظه به سمت دکتر چرخید ؛ آثار رنج و التماس بر چهره اش نقش خورده بود. با صدایی آرام و لحنی ملتمسانه گفت:\r\nــ آقای دکتر! آقای دکتر کاش قلبی در سینه تان می تپید ، کاش میخواستید درک کنید … هرگز راضی نمیشدید بخاطر پول … اینقدر رنج و عذابم بدهید … خیال میکنید درد و غصه ی خودم کم است؟ …\r\nدر این لحظه دست برد و شقیقه های خود را فشرد ؛ خرمن گیسوانش در یک چشم به هم زدن ــ گفتی فنری را فشرده بود ، نه شقیقه هایش را ــ بر شانه هایش فرو ریخت …\r\nــ از دست شوهر نادانم عذاب میکشم … این بیغوله ی گند و نفرت انگیز را تحمل میکنم … و حالا یک مرد تحصیل کرده به خودش اجازه میدهد ملامتم کند ، سرکوفتم بزند. خدای من! تا کی باید عذاب بکشم؟\r\nــ ولی خانم محترم ، قبول کنید که موقعیت خاص صنف ما …\r\nاما دکتر ناچار شد خطابه ای را که آغاز کرده بود قطع کند: نادژدا پترونا تلوتلو خورد و به بازوان دکتر که به طرف او دراز شده بود ، در آویخت و از هوش رفت … سر او به سمت شانه ی دکتر خم شد و روی آن آرمید.\r\nدقیقه ای بعد ، زمزمه کنان گفت:\r\nــ بیایید از این طرف … جلو شومینه دکتر … جلوتر … همه چیز را برایتان تعریف میکنم … همه چیز …\r\nساعتی بعد دکتر ، آپارتمان نادژدا پترونا را ترک گفت ؛\r\nهم دلخور بود ؛ هم شرمنده ؛ هم سرخوش … در حالی که سوار سورتمه ی خود میشد ، زیر لب گفت:\r\n\" انسان وقتی صبح ها از خانه اش بیرون می رود ، نباید پول زیاد با خودش بردارد! یک وقت ناچار میشود پولش را بسلفد\"\r\n"},{"id":1522,"category_id":10,"category_code":"s10","source_id":84,"title":"سرباز معلول ","content":"داستان درباره سربازی است که پس از جنگ ویتنام می خواست به خانه خود بازگردد.\r\nسرباز قبل از این که به خانه برسد، از نیویورک با پدر و مادرش تماس گرفت و گفت:« پدر و مادر عزیزم، جنگ تمام شده و من می خواهم به خانه بازگردم، ولی خواهشی از شما دارم. رفیقی دارم که می خواهم او را با خود به خانه بیاورم.»\r\n\r\nپدر و مادر او در پاسخ گفتند:« ما با کمال میل مشتاقیم که او را ببینیم.»\r\n\r\nپسر ادامه داد:« ولی موضوعی است که باید در مورد او بدانید، او در جنگ به شدت آسیب دیده و در اثر برخورد با مین یک دست و یک پای خود را از دست داده است و جایی برای رفتن ندارد و من می خواهم که اجازه دهید او با ما زندگی کند.»\r\nپدرش گفت:« پسر عزیزم، متأسفیم که این مشکل برای دوست تو بوجود آمده است. ما کمک می کنیم تا او جایی برای زندگی در شهر پیدا کند.»\r\n\r\nپسر گفت:« نه، من می خواهم که او در منزل ما زندگی کند.»\r\n\r\nآنها در جواب گفتند:« نه، فردی با این شرایط موجب دردسر ما خواهد بود. ما فقط مسئول زندگی خودمان هستیم و اجازه نمی دهیم او آرامش زندگی ما را برهم بزند. بهتر است به خانه بازگردی و او را فراموش کنی.»\r\n\r\nدر این هنگام پسر با ناراحتی تلفن را قطع کرد و پدر و مادر او دیگر چیزی نشنیدند.\r\n\r\nچند روز بعد پلیس نیویورک به خانواده پسر اطلاع داد که فرزندشان در سانحه سقوط از یک ساختمان بلند جان باخته و آنها مشکوک به خودکشی هستند.\r\nپدر و مادر آشفته و سراسیمه به طرف نیویورک پرواز کردند و برای شناسایی جسد پسرشان به پزشکی قانونی مراجعه کردند. با دیدن جسد، قلب پدر و مادر از حرکت ایستاد. پسر آنها یک دست و پا داشت!\r\n"},{"id":1523,"category_id":10,"category_code":"s10","source_id":85,"title":"ماجرای دو گرگ ","content":"دو تا گرگ بودند که از کوچکی با هم دوست بودند و هر شکاری که به چنگ می آوردند با هم می خوردند و تو یک غار با هم زندگی می کردند. یک سال زمستان بدی شد و بقدری برف رو زمین نشست که این دو گرگ گرسنه ماندند و هر چه ته مانده لاشه های شکارهای پیش مانده بود خوردند که برف بند بیاید و پی شکار بروند اما برف بند نیامد و آنها ناچار به دشت زدند اما هر چه رفتند دهن گیره ای گیر نیاوردند، برف هم دست بردار نبود و کم کم داشت شب می شد و آنها از زور سرما و گرسنگی نه راه پیش داشتند نه راه پس.\r\n\r\nیکی از آنها که دیگر نمی توانست راه برود به دوستش گفت:\r\n\"چاره نداریم مگه اینکه بزنیم به ده.\"\r\n\r\nـ \"بزنیم به ده که بریزن سرمون نفله مون کنن؟\"\r\n\r\nـ \"بریم به اون آغل بزرگه که دامنه کوهه یه گوسفندی ورداریم در ریم.\"\r\n\r\nـ \"معلوم میشه مخت عیب کرده. کی آغلو تو این شب برفی تنها میذاره. رفتن همون و زیر چوب و چماق له شدن همون. چنون دخلمونو میارن که جدمون پیش چشممون بیاد.\"\r\n\r\nـ \"تو اصلاً ترسویی. شکم گشنه که نباید از این چیزا بترسه.\"\r\n\r\nـ \"یادت رفته بابات چه جوری مرد؟ مثه دزد ناشی زد به کاهدون و تکه گنده هش شد گوشش\"\r\n\r\nـ \"بازم اسم بابام رو آوردی؟ تو اصلاً به مرده چکار داری؟ مگه من اسم بابای تو رو میارم که از بس که خر بود یه آدمیزاد مفنگی دست آموزش کرده بود برده بودش تو ده که مرغ و خروساشو بپاد و اینقده گشنگی بهش داد تا آخرش مرد و کاه کردن تو پوستش و آبرو هر چی گرگ بود برد؟\"\r\n\r\nـ \"بابای من خر نبود از همه داناتر بود. اگر آدمیزاد امروز روزم به من اعتماد می کرد، می رفتم باش زندگی می کردم. بده یه همچین حامی قلتشنی مثه آدمیزاد را داشته باشیم؟ حالا تو میخوای بزنی به ده، برو تا سر تو بِبُرن، بِبَرن تو ده کله گرگی بگیرن.\"\r\n\r\nـ \"من دیگه دارم از حال میرم. دیگه نمی تونم پا از پا وردارم.\"\r\n\r\nـ \"اه\" مث اینکه راس راسکی داری نفله میشی. پس با همین زور و قدرتت میخواسی بزنی به ده؟\"\r\n\r\nـ \"آره، ‌نمی خواستم به نامردی بمیرم. می خواستم تا زنده ام مرد و مردونه زندگی کنم و طعمه خودمو از چنگ آدمیزاد بیرون بیارم.\"\r\n\r\n \r\n\r\nگرگ ناتوان این را گفت و حالش بهم خورد و به زمین افتاد و دیگر نتوانست از جایش تکان بخورد. دوستش از افتادن او خوشحال شد و دور ورش چرخید و پوزه اش را لای موهای پهلوش فرو برد و چند جای تنش را گاز گرفت. رفیق زمین گیر از کار دوستش سخت تعجب کرد و جویده جویده از او پرسید:\r\n\r\nـ \"داری چکار می کنی؟ منو چرا گاز می گیری؟\"\r\n\r\nـ \"واقعاً که عجب بی چشم و روی هستی. پس دوستی برای کی خوبه؟ تو اگه نخوای یه فداکاری کوچکی در راه دوست عزیز خودت بکنی پس برای چی خوبی؟\" \r\n\r\nـ \"چه فداکاری ای؟\"\r\n\r\nـ \"تو که داری میمیری. پس اقلاً بذار من بخورمت که زنده بمونم.\"\r\n\r\nـ منو بخوری؟\" \r\n\r\nـ \"آره مگه تو چته؟\" \r\n\r\nـ \"آخه ما سالهای سال با هم دوست جون جونی بودیم.\"\r\n\r\nـ \"برای همینه که میگم باید فداکاری کنی.\"\r\n\r\nـ \"آخه من و تو هر دومون گرگیم. مگه گرگ، گرگو می خوره؟\"\r\n\r\nـ \"چرا نخوره؟ اگرم تا حالا نمی خورده، من شروع می کنم تا بعدها بچه هامونم یاد بگیرن.\"\r\n\r\nـ \"آخه گوشت من بو میده\"\r\n\r\nـ \"خدا باباتو بیامرزه؛ من دارم از نا می رم تو میگی گوشتم بو میده؟\r\n\r\nـ \"حالا راس راسی میخوای منو بخوری؟\"\r\n\r\nـ \"معلومه چرا نخورم؟\" \r\n\r\nـ \"پس یه خواهشی ازت دارم.\"\r\n\r\nـ \"چه خواهشی؟\"\r\n\r\nـ \"بذار بمیرم وقتی مردم هر کاری میخوای بکن.\"\r\n\r\nـ \"واقعاً که هر چی خوبی در حقت بکنن انگار نکردن. من دارم فداکاری می کنم و می خام زنده زنده بخورمت تا دوستیمو بهت نشون بدم. مگه نمی دونی اگه نخورممت لاشت میمونه رو زمین اونوخت لاشخورا می خورنت؟ گذشته از این وقتی که مردی دیگه بو میگیری و ناخوشم می کنه.\"\r\n\r\n \r\n\r\nگرگ نابکار این را گفت و زنده زنده شکم دوست خود را درید و دل و جگر او را داغ داغ بلعید ...\r\n"},{"id":1524,"category_id":10,"category_code":"s10","source_id":86,"title":"یک اتفاق جالب ","content":"چند وقتی بود در بخش مراقبت های ویژه یک بیمارستان معروف، بیماران یک تخت به خصوص در حدود ساعت ۱۱ صبح روزهای یکشنبه جان می سپردند و این موضوع ربطی به نوع بیماری و شدت و ضعف مرض آنان نداشت. این مسئله باعث شگفتی پزشکان آن بخش شده بود، به طوری که بعضی آن را با مسائل ماورای طبیعی و بعضی دیگر با خرافات و ارواح و\r\nاجنه و موارد دیگر در ارتباط می دانستند. کسی قادر به حل این مسئله نبود. که چرا بیمار آن تخت درست در ساعت ۱۱ صبح روزهای یکشنبه می مرد. به همین دلیل گروهی از پزشکان متخصص بین المللی برای بررسی موضوع تشکیل جلسه دادند و پس از ساعت ها بحث و تبادل نظر بالاخره تصمیم بر این شد که در اولین یکشنبه ماه، چند دقیقه قبل از ساعت ۱۱ در محل مذکور برای مشاهده این پدیده عجیب و غریب حاضر شوند. در محل و ساعت موعود، بعضی صلیب کوچکی در دست گرفته و در حال دعا بودند، بعضی دوربین فیلمبرداری با خود آورده و... دو دقیقه به ساعت ۱۱ مانده بود که « پوکی جانسون » نظافتچی پاره وقت روزهای یکشنبه وارد اتاق شد. دوشاخه برق دستگاه حفظ حیات  را از پریز برق درآورد و دوشاخه جاروبرقی خود را به پریز زد و مشغول کار شد!\r\n"},{"id":1525,"category_id":10,"category_code":"s10","source_id":87,"title":"من دخترک را همان جا رها کردم! ","content":"دو راهب که مراحلی از سیر و سلوک را گذرانده بودند و از دیاری به دیار دیگر سفر میکردند سر راه خود دختری را دیدند که در کنار رودخانه ایستاده بود و تردید داشت که از آن بگذرد.\r\nوقتی راهبان نزدیک رودخانه رسیدند دخترک از آنها تقاضای کمک کرد. یکی از راهبان بلادرنگ دختر را برداشت و از رودخانه گذراند.\r\nراهبان به راه خود ادامه دادند و\r\nمسافتی طولانی را پیمودند تا به مقصد رسیدند.\r\nدر همین هنگام راهب دوم که ساعت ها سکوت کرده بود خطاب به همراه خود گفت: \" دوست عزیز، ما راهبان نباید به زنان نزدیک شویم. تماس با آنها برخلاف عقاید و مقررات مکتب ماست. در صورتیکه تو دخترک را بغل کردی و از رودخانه عبور دادی.\r\nراهب اولی با خونسردی و با حالتی بی تفاوت پاسخ داد: \"من دخترک را همان جا رها کردم ولی تو هنوز به آن چسبیده ای و آن را رها نمیکنی.\"\r\n"},{"id":1526,"category_id":10,"category_code":"s10","source_id":88,"title":"استجابت دعای زوج جوان","content":"زن و شوهری بعد از سالیانی که از ازدواجشون می گذشت در حسرت داشتن فرزند به سر می بردند. با هرکسی که تونسته بودند مشورت کرده بودند اما نتیجه ای نداشت، تا این که به نزد کشیش شهرشون رفتند.\r\nپس از این که مشکلشون رو به کشیش گفتند، او در جواب اون زوج گفت: ناراحت نباشید من مطمئنم که خداوند دعاهای شما رو شنیده و به زودی به شما فرزندی عطا خواهد نمود. با این وجود من قصد دارم به شهر رم برم و مدتی در اون جا اقامت داشته باشم، قول می دهم وقتی به واتیکان رفتم حتما برای استجابت دعای شما شمعی روشن کنم.\r\nزوج جوان با خوشحالی فراوان از کشیش تشکر کردند. قبل از این که کشیش اون جا رو ترک کنه، بازگشت و گفت:\r\nمن مطمئنم که همه چیز با خوبی و خوشی حل می شه و شما حتما صاحب فرزند خواهید شد. اقامت من در شهر رم حدود 15 سال به طول خواهد انجامید، ولی قول می دم وقتی برگشتم حتما به دیدن شما بیام.\r\n15 سال گذشت و کشیش دوباره به شهرش بازگشت. یه نیمروز تابستان که توی اتاقش در کلیسا استراحت می کرد، یاد قولی افتاد که 15 سال پیش به اون زوج جوان داده بود و تصمیم گرفت یه سری به اونا بزنه پس به طرف خونه اونا به راه افتاد. وقتی به محل اقامت اون زوجی که سال ها پیش با اون مشورت کرده بودند رسید زنگ در را به صدا در آورد.\r\nصدای جیغ و فریاد و گریه چند تا بچه تمام فضا رو پر کرده بود. خوشحال شد و فهمید که بالاخره دعاهای این زوج استجابت شده و اونا صاحب فرزند شده اند.\r\nوقتی وارد خونه شد بیشتر از یه دوجین بچه رو دید که دارن از سر و کول همدیگه بالا میرن وهمه جا رو گذاشتن رو سرشون و وسط اون شلوغی و هرج و مرج هم مامانشون ایستاده بود.\r\nکشیش گفت: فرزندم! می بینم که دعاهاتون مستجاب شده... حالا به من بگو شوهرت کجاست تا به اون هم به خاطر این معجزه تبریک بگم.\r\nزن مایوسانه جواب داد: اون نیست... همین الان خونه رو به مقصد رم ترک کرد.\r\nکشیش پرسید: شهر رم؟ برای چی رفته رم؟\r\nزن پاسخ داد: رفته تا اون شمعی رو که شما واسه استجابت دعای ما روشن کردین خاموش کنه.\r\n"},{"id":1527,"category_id":10,"category_code":"s10","source_id":89,"title":"پازل ","content":"پدر داشت روزنامه می خواند پسر که حوصله اش سر رفته بود پیش پدرش رفت و گفت : پدر بیا بازی کنیم پدر که بی حوصله بود چند تکه از روزنامه که عکس نقشه دنیا بود تکه تکه کرد و به پسرش داد و گفت برو درستش کن . پسر هم رفت و بعد از مدتی عکس را به پدرش داد . پدر دید پسرش نقشه جهان رو کاملاً درست جمع کرده از او پرسید که نقشه جهان رو از کجا یاد گرفتی؟ پسر گفت : من عکس اون آدم پشت صفحه رو درست کردم . وقتی آدمها درست بشن دنیا هم درست میشه."},{"id":1528,"category_id":10,"category_code":"s10","source_id":90,"title":"داستان شیطان و مرد نمازگزار ","content":"مردی صبح زود از خواب بیدار شد تا نمازش را در خانه خدا (مسجد) بخواند. لباس پوشید و راهی خانه خدا شد.\r\nدر راه مسجد، مرد زمین خورد و لباسهایش کثیف شد. او بلند شد، خودش را پاک کرد و به خانه برگشت.\r\nمرد لباسهایش را عوض کرد و دوباره راهی خانه خدا شد. در راه به مسجد و در همان نقطه مجدداً زمین خورد!\r\nاو دوباره بلند شد، خودش را پاک کرد و به خانه برگشت. یک بار دیگر لباسهایش را عوض کرد و راهی خانه خدا شد.\r\nدر راه مسجد، با مردی که چراغ در دست داشت برخورد کرد و نامش را پرسید.\r\nمرد پاسخ داد: (( من دیدم شما در راه به مسجد دو بار به زمین افتادید.))، از این رو چراغ آوردم تا بتوانم راهتان را روشن کنم.\r\nمرد اول از او بطور فراوان تشکر می کند و هر دو راهشان را به طرف مسجد ادامه می دهند. همین که به مسجد رسیدند، مرد اول از مرد چراغ بدست در خواست می کند تا به مسجد وارد شود و با او نماز بخواند.\r\nمرد دوم از رفتن به داخل مسجد خودداری می کند.\r\nمرد اول درخواستش را دوبار دیگر تکرار می کند و مجدداً همان جواب را می شنود.\r\nمرد اول سوال می کند که چرا او نمی خواهد وارد مسجد شود و نماز بخواند.\r\nمرد دوم پاسخ داد: ((من شیطان هستم.)) مرد اول با شنیدن این جواب جا خورد.\r\nشیطان در ادامه توضیح می دهد:\r\n((من شما را در راه به مسجد دیدم و این من بودم که باعث زمین خوردن شما شدم.)) وقتی شما به خانه رفتید، خودتان را تمیز کردید و به راهمان به مسجد برگشتید، خدا همه گناهان شما را بخشید. من برای بار دوم باعث زمین خوردن شما شدم و حتی آن هم شما را تشویق به ماندن در خانه نکرد، بلکه بیشتر به راه مسجد برگشتید. به خاطر آن، خدا همه گناهان افراد خانواده ات را بخشید. من ترسیدم که اگر یک بار دیگر باعث زمین خوردن شما بشوم، آنگاه خدا گناهان افراد دهکده تان را خواهد بخشید.\r\nبنا براین، من سالم رسیدن شما را به خانه خدا (مسجد) مطمئن ساختم.\r\n\r\nنتیجه داستان:\r\nکار خیری را که قصد دارید انجام دهید به تعویق نیاندازید. زیرا هرگز نمی دانید چقدر اجر و پاداش ممکن است ازمواجه با سختی های در حین تلاش به انجام کار خیر دریافت کنید. پارسائی شما می تواند خانواده و قوم تان را بطور کلی نجات بخشد.\r\nاین کار را انجام دهید و پیروزی خدا را ببینید\r\n"},{"id":1529,"category_id":10,"category_code":"s10","source_id":91,"title":"ازدواج یعنی همین ","content":"شاگردی از استادش پرسید: عشق چیست؟\r\nاستاد در جواب گفت: به گندومزار برو و پرخوشه ترین شاخه را بیاور. اما در هنگام عبور از گندومزار، به یاد داشته که نمی توانی به عقب برگردی تا خوشه ای بچینی؟\r\nشاگرد به گندمزار رفت و پس از مدتی طولانی برگشت.\r\nاستاد پرسید: چه آوردی؟\r\nو شاگرد با حسرت جواب داد: هیچ! هر چه جلو می رفتم،\r\nخوشه های پرپشت تر می دیدم و به امید پیدا کردن پرپشت ترین، تا انتهای گندمزار رفتم.\r\nاستاد گفت : عشق یعنی همین!\r\nشاگرد پرسید: پس ازدواج چیست؟\r\nاستاد به سخن آمد که: به جنگل برو و بلندترین درخت را بیاور. اما به یاد داشته باش که باز هم نمی توانی به عقب برگردی!\r\nشاگرد رفت و پس از مدت کوتاهی با درختی برگشت.\r\nاستاد پرسید که شاگرد را چه شد و او در جواب گفت: به جنگل رفتم و اولین درخت بلندی را که دیدم، انتخاب کردم. ترسیدم که اگر جلو بروم، باز هم دست خالی برگردم.\r\nاستاد باز گفت: ازدواج یعنی همین!!\r\n"},{"id":1530,"category_id":10,"category_code":"s10","source_id":92,"title":"مدارس استرالیا ","content":"یک دانشجو برای ادامه تحصیل و گرفتن دکترا همراه با خانواده اش عازم استرالیا شد. در آنجا پسر کوچکشان را در یک مدرسه استرالیایی ثبت نام کردند تا  او هم ادامه تحصیلش را در سیستم آموزش این کشور تجربه کند.\r\nروز اوّل که پسر از مدرسه برگشت، پدر از او پرسید: پسرم تعریف کن ببینم امروز در مدرسه چی یاد گرفتی؟\r\nپسر جواب داد: امروز درباره خطرات سیگار کشیدن به ما گفتند، خانم معلّم برایمان یک کتاب قصّه خواند و\r\nیک کاردستی هم درست کردیم.\r\nپدر پرسید: ریاضی و علوم نخواندید؟ پسر گفت: نه\r\nروز دوّم دوباره وقتی پسر از مدرسه برگشت پدر سؤال خودش را تکرار کرد. پسر جواب داد: امروز نصف روز را ورزش کردیم، یاد گرفتیم که چطور اعتماد به نفسمان را از دست ندهیم، و زنگ آخر هم به کتابخانه رفتیم و به ما یاد دادند که از کتاب های آنجا چطور استفاده کنیم.\r\nبعد از چندین روز که پسر می رفت و می آمد و تعریف می کرد، پدر کم کم نگران شد چرا که می دید در مدرسه پسرش وقت کمی در  هفته صرف ریاضی، فیزیک، علوم، و چیزهایی که از نظر او درس درست و حسابی بودند می شود. از آنجایی که پدر نگران بود که پسرش در این دروس ضعیف رشد کند به پسرش گفت:\r\nپسرم از این به بعد دوشنبه ها مدرسه نرو تا در خانه خودم با تو ریاضی و فیزیک کار کنم.\r\nبنابراین پسر دوشنبه ها  مدرسه نمی رفت. دوشنبه اوّل از مدرسه زنگ زدند که چرا پسرتان نیامده. گفتند مریض است. دوشنبه دوّم هم زنگ زدند باز یک بهانه ای آوردند. بعد از مدّتی مدیر مدرسه مشکوک شد و پدر را به مدرسه فراخواند تا با او صحبت کند.\r\nوقتی پدر به مدرسه رفت باز سعی کرد بهانه بیاورد امّا مدیر زیر بار نمی رفت. بالاخره به ناچار حقیقت ماجرا را تعریف کرد. گفت که نگران پیشرفت تحصیلی پسرش بوده و از این تعجّب می کند که چرا در مدارس استرالیا اینقدر کم درس درست و حسابی می خوانند.\r\nمدیر پس از شنیدن حرف های پدر کمی سکوت کرد و سپس جواب داد:\r\nما هم ۵۰ سال پیش مثل شما فکر می کردیم.\r\n"},{"id":1531,"category_id":10,"category_code":"s10","source_id":93,"title":"گریه ... ","content":"حسن نامی وارد دهی شد و در مکانی که اهالی ده جمع شده بودند نشست و بنای گریه گذاشت. \r\nسبب گریه‌اش را پرسیدند، گفت: من مردغریبی هستم و شغلی ندارم برای بدبختی خودم گریه می‌کنم،\r\nمردم ده او را به شغل کشاورزی گرفتند.\r\n\r\nشب دیگر\r\nدیدند همان مرد باز گریه می‌کند، گفتند حسن آقا دیگر چه شده؟\r\nحالا که شغل پیدا کردی،  گفت: شما همه منزل و ماءوا مسکن دارید و می‌توانید خوتان\r\nرا از سرما\r\nو گرما حفظ کنید ولی من غریبم و خانه ندارم برای همین بدبختی گریه می‌کنم. \r\n\r\nبار دیگر اهالی ده همت کردن و برایش خانه‌ای تهیه کردند و وی را در آنجا جا دادند. \r\n\r\nولی شب باز دیدند دارد گریه می‌کند. وقتی علت را پرسیدند \r\nگفت: هر کدام از شما‌ها همسری دارید ولی من تنها در میان اطاقم می‌خوابم.\r\n\r\nمردم این مشکل او را نیز حل کردند و دختری از دختران ده را به ازدواج او در آوردند.\r\n\r\nولی باز شب هنگام حسن آقا داشت گریه می‌کرد. گفتند باز چی شده،\r\nگفت: همه شما سید هستید و من در میان شما اجنبی هستم. \r\n\r\nبه دستور کدخدا شال سبزی به کمر او بستند تا شاید از صدای گریه او راحت شوند\r\n\r\nولی با کمال تعجب دیدند او شب باز گریه می‌کند، وقتی علت را پرسیدند\r\n\r\nگفت: بر جد غریبم گریه می‌کنم و به شما هیچ ربطی ندارد!!!\r\n"},{"id":1532,"category_id":10,"category_code":"s10","source_id":94,"title":"مزدور ","content":"روزی ابوریحان درس به شاگردان می گفت که خونریز و قاتلی پای به محل درس و بحث نهاد . شاگردان با خشم به او می نگریستند و در دل هزار دشنام به او می دادند که چرا مزاحم آموختن آنها شده است . آن مرد رسوا روی به حکیم نموده چند سئوال ساده نمود و رفت .\r\nفردای آن روز، شاعری مدیحه سرای دربار، پای به محل درس گذارده تا سئوالی از حکیم بپرسد شاگردان به احترامش برخواستند و او را مشایعت نموده تا به پای صندلی استاد برسد.\r\nکه دیدند از استاد خبری نیست هر طرف....\r\nرا نظر کردند اثری از استاد نبود .\r\n\r\nیکی از شاگردان که از آغاز چشمش به استاد بود و او را دنبال می نمود در میانه کوچه جلوی استاد را گرفته و پرسید: چگونه است دیروز آدمکشی به دیدارتان آمد پاسخ پرسش هایش را گفتید و امروز شاعر و نویسنده ایی سرشناس آمده ، محل درس را رها نمودید ؟!\r\nابوریحان گفت: یک بزهکار تنها به خودش و معدودی لطمه میزند ، اما یک نویسنده و شاعر خود فروخته کشوری را به آتش می کشد.\r\nشاگرد متحیر به چشمان استاد می نگریست که ابوریحان بیرونی از او دور شد .\r\n\r\nارد بزرگ اندیشمند یگانه کشورمان می گوید :  هنرمند و نویسنده  مزدور ، از هر کشنده ای زیانبارتر است .\r\nابوریحان بیرونی دانشمند آزاده ایی بود که هیچگاه کسب قدرت او را وسوسه ننمود و همواره عمر خویش را وقف ساختن ابوریحان های دیگر کرد.\r\n"},{"id":1533,"category_id":10,"category_code":"s10","source_id":95,"title":"سیگار و دعا ","content":"در بازگشت از کلیسا، جک از دوستش ماکس می پرسد: «فکر می کنی آیا می شود هنگام دعا کردن سیگار کشید؟»\r\nماکس جواب می دهد: «چرا از کشیش نمی پرسی؟»\r\n\r\nجک نزد کشیش می رود و می پرسد: «جناب کشیش، می توانم وقتی در حال دعا کردن هستم، سیگار بکشم.»\r\nکشیش پاسخ می دهد: «نه، پسرم، نمی شود. این بی ادبی به مذهب است.»\r\nجک نتیجه را برای دوستش ماکس بازگو می کند.\r\n\r\nماکس می گوید: «تعجبی نداره. تو سئوال را درست مطرح نکردی. بگذار من بپرسم.»\r\nماکس نزد کشیش می رود و می پرسد: «آیا وقتی در حال سیگار کشیدنم می توانم دعا کنم ؟»\r\nکشیش مشتاقانه پاسخ می دهد: «مطمئناً، پسرم. مطمئناً.»\r\n"},{"id":1534,"category_id":10,"category_code":"s10","source_id":96,"title":"فکر اقتصادی ","content":"چاک از یک مزرعه‌دار در تکزاس یک الاغ خرید به قیمت ۱۰۰ دلار . قرار شد که مزرعه‌دار الاغ را روز بعد تحویل بدهد. اما روز بعد مزرعه‌دار سراغ چاک آمد و گفت : « متأسفم جوون . خبر بدی برات دارم . الاغه مرد. »\r\nچاک جواب داد : « ایرادی نداره . همون پولم رو پس بده. »\r\nمزرعه‌دار گفت : « نمی‌شه . آخه همه پول رو خرج کردم. »\r\nچاک گفت : « باشه . پس همون الاغ مرده رو بهم بده. »\r\nمزرعه‌دار گفت :\r\n« می‌خوای باهاش چی کار کنی؟ »\r\nچاک گفت : « می‌خوام باهاش قرعه‌کشی برگزار کنم. »\r\nمزرعه‌دار گفت : « نمی‌شه که یه الاغ مرده رو به قرعه‌کشی گذاشت! »\r\nچاک گفت : « معلومه که می‌تونم . حالا ببین . فقط به کسی نمی‌گم که الاغ مرده است. »\r\nیک ماه بعد مزرعه‌دار چاک رو دید و پرسید: « از اون الاغ مرده چه خبر؟ »\r\nچاک گفت : « به قرعه‌کشی گذاشتمش. ۵۰۰ تا بلیت ۲ دلاری فروختم و ۸۹۸ دلار سود کردم. »\r\nمزرعه‌دار پرسید : « هیچ کس هم شکایتی نکرد؟ »\r\nچاک گفت : « فقط همونی که الاغ رو برده بود. من هم ۲ دلارش رو پس دادم »\r\n"},{"id":1535,"category_id":10,"category_code":"s10","source_id":97,"title":"شکل خدایی ","content":"اینل واترمن داستان آهنگری را می گوید که پس از گذراندن جوانی پر شر و شور تصمیم گرفت روحش را وقف خدا کند سالها با علاقه کار کرد به دیگران نیکی کرد اما با تمام پرهیزگاری در زندگیش چیزی درست به نظر نمی آمد حتی مشکلاتش به شدت بیشتر می شدند.\r\n \r\nیک روز عصر دوستی که به دیدنش آمده بود و از وضعیت دشوارش مطلع شد گفت واقعا عجیب است\r\nدرست بعد از اینکه تصمیم گرفتی مردی باخدا شوی زندگیت بدتر شده نمی خواهم ایمانت را ضعیف کنم اما با وجود تمام تلاشهایت در مسیر روحانی هیچ چیز بهتر نشده ! آهنگر بلافاصله پاسخ نداد او هم بارها همین فکر را کرده بود و نمی فهمید چه بر زندگیش آمده است .\r\n\r\nاما نمی خواست دوستش را بدون پاسخ بگذارد روزها به این موضوع فکر کرد تا بالاخره جوابش را یافت روز بعد که دوستش به دیدنش آمده بود گفت : در این کارگاه فولاد خام برایم می آورند و باید از آن شمشیر بسازم می دانی چطور این کار را می کنم ؟ اول تکه ای از فولاد را به اندازه جهنم حرارت می دهم تا سرخ شود بعد با بیرحمی سنگینترین پتک را بر می دارم و پشت سرهم بر آن ضربه می زنم تا اینکه فولاد شکلی را بگیرد که می خواهم بعد آن را در ظرف آب سرد فرو می کنم تا جاییکه تمام این کارگاه را بخار آب فرا می گیرد فولاد به خاطر این تغییر ناگهانی دما ناله می کند و رنج می برد باید این کار را آنقدر تکرار کنم تا به شمشیر مورد نظرم دست پیدا کنم \" یک بار کافی نیست \"آهنگر مدتی سکوت کرد سپس ادامه داد \" گاهی فولادی که به دستم می رسد این عملیات را تاب نمی آورد حرارت پتک سنگین و آ ب سرد تمامش را ترک می اندازد می دانم که از این فولاد هرگز شمشیر مناسبی در نخواهد آمد \"\r\n\r\nآنگاه مکثی کرد و ادامه داد \" می دانم که خدا دارد مرا در آتش رنج فرو می برد ضربات پتکی را که بر زندگی من وارد کرده پذیرفته ام و گاهی به شدت احساس سرما می کنم انگار فولادی باشم که از آبدیده شدن رنج می برد .\r\nاما تنها چیزی که می خواهم این است : \" خدای من از کارت دست نکش تا شکلی را که تو می خواهی به خود گیرم با هر روشی که می پسندی ادامه بده هر مدت که لازم است ادامه بده اما هرگز مرا به کوه فولادهای بیفایده پرتاب نکن \"\r\n"},{"id":1536,"category_id":10,"category_code":"s10","source_id":98,"title":"اتاق کار فرشتگان چه جوری خنک می شود؟ ","content":"دروغگویی می میرد و به جهان آخرت می رود.\r\n\r\nدر آنجا مقابل دروازه های بهشت می ایستد سپس دیوار بزرگی می بیند که ساعت های مختلفی روی آن قرار گرفته بود.\r\n\r\nاز یکی از فرشتگان می پرسد “این ساعت ها برای چه اینجا قرار گرفته اند؟”\r\n\r\nفرشته پاسخ می دهد :”این ساعت ها ساعت های دروغ سنج هستند و هر کس روی زمین یک ساعت دروغ سنج دارد و هر بار آن فرد یک دروغ بگو ید عقربه ی ساعت یک درجه جلوتر میرود”.\r\n\r\nمرد گفت :”چه جالب آن ساعت کیه؟!”....\r\nفرشته پاسخ داد :”مادر ترزا او حتی یک دروغ هم نگفته بنابراین ساعتش اصلاً حرکت نکرده است.\r\n\r\n- وای باور کردنی نیست . خوب آن ساعت کیه؟\r\nفرشته پاسخ داد : ساعت آبراهام لینکلن(رئیس جمهور سابق آمریکا) عقربه اش دوبار تکان خورد!\r\n\r\n - خیلی جالبه راستی ساعت من کجاست ؟\r\n\r\nفرشته پاسخ داد : آن در اتاق کار سرپرست فرشتگان است و از آن به عنوان پنکه سقفی استفاده می کنند.\r\n"},{"id":1537,"category_id":10,"category_code":"s10","source_id":99,"title":"پیرزن تنها ","content":"اولین تصویری که در ذهنم از دیدن چهره تکیده اش تصویر شد ، گنجشککی تنها بود ، بیمار و هراسان در زیر درختی در بی آبی سخت کوهپایه ای بی صدا، که چند صباحی از دم وباز دمش بیش نمانده است. اضطرابی سخت در صورت و آرامشی نرم در سیرت، شیارهای روزگاران بر صورت و خاطرات بی وفایان در سیرت، شوهرش مرده، خاطره ای از او بر چهره مانده ، در خانه سوخته پسرش تنها و بیکس می خوابد، زیرا که همسر جگر گوشه اش با او راحت نیست !!!\r\nتاریخ تولد خود را نمی دانست، حتی برای اثبات ندانستنش قسم نیز می خورد ، چهر ه اش نماینگر آن بود که همه مغول را نیز دید ه است ...\r\nبوی کباب و سرخی سیب او را به بسا ط ما کشانده بود، اما غرورش اجازه هیچ درخواستی را از ما نمی داد، تنها در گوشه ای با جامگانی که سا لها از قدمت سوزن زدنشان می گذشت ، نشست. چه آرامشی، چه هراسی، چه دردی و چه نشاطی، همه چیز در او بود.تنهایش را به عظمت یک نخل پر رطب حس کردم،\r\nجنوبی پیرزن، آفتاب خورده، شوهر مرده، پسر رانده بی کس، در انتظار مرگ...\r\nآیا لبان او را نیز روزی پسری آرزو کرده است ؟؟؟\r\nکجا، زیر کدامین درخت، در کنار کدامین بساط، در کدامین فصل جان او را خواهی گرفت ؟؟؟\r\n"},{"id":1538,"category_id":10,"category_code":"s10","source_id":100,"title":"طلب بخشش به سبک بچه زرنگ ها ","content":"کودکی به مامانش گفت، من واسه تولدم دوچرخه می خوام. بابی پسر خیلی شری بود. همیشه اذیت می کرد. مامانش بهش گفت آیا حقته که این دوچرخه رو برات بگیریم واسه تولدت؟\r\n\r\nبابی گفت، آره. مامانش بهش گفت، برو تو اتاق خودت و یه نامه برای خدا بنویس و ازش بخواه به خاطر کارای خوبی که انجام دادی بهت یه دوچرخه بده\r\nنامه شماره یک\r\nسلام خدای عزیز\r\n\r\nاسم من بابی هست. من یک پسر خیلی خوبی بودم و حالا ازت می خوام که یه دوچرخه بهم بدی.\r\nدوستار تو\r\nبابی \r\n\r\nبابی کمی فکر کرد و دید که این نامه چون دروغه کارساز نیست و دوچرخه ای گیرش نمی یاد. برا همین نامه رو پاره کرد.\r\n\r\nنامه شماره دو\r\n\r\nسلام خدا\r\nاسم من بابیه و من همیشه سعی کردم که پسر خوبی باشم. لطفاً واسه تولدم یه دوچرخه بهم بده.\r\nبابی \r\n\r\nاما بابی یه کمی فکر کرد و دید که این نامه هم جواب نمی ده واسه همین پارش کرد. \r\n\r\nنامه شماره سه\r\n\r\nسلام خدا\r\nاسم من بابی هست. درسته که من بچه خوبی نبودم ولی اگه واسه تولدم یه دوچرخه بهم بدی قول می دم که بچه خوبی باشم.\r\nبابی \r\n\r\nبابی کمی فکر کرد و با خودش گفت که شاید این نامه هم جواب نده. واسه همین پارش کرد. تو فکر فرو رفت. رفت به مامانش گفت که می خوام برم کلیسا. مامانش دید که کلکش کار ساز بوده، بهش گفت خوب برو ولی قبل از شام خونه باش.\r\n\r\nبابی رفت کلیسا. یکمی نشست وقتی دید هیچ کسی اونجا نیست، پرید و مجسمه مادر مقدس رو کش رفت ( دزدید ) و از کلیسا فرار کرد.\r\n\r\nبعدش مستقیم رفت تو اتاقش و نامه جدیدش رو نوشت.\r\n\r\nنامه شماره چهار\r\n\r\nسلام خدا\r\nمامانت پیش منه. اگه می خواییش واسه تولدم یه دوچرخه بهم بده.\r\nبابی\r\n"},{"id":1539,"category_id":10,"category_code":"s10","source_id":101,"title":"قیمت مغز .... ","content":"بالاخره دکتر وارد شد ، با نگاهی خسته ، ناراحت و جدی .\r\n\r\nدکتر در حالی که قیافه نگرانی به خودش گرفته بود گفت :\"متاسفم که باید حامل خبر بدی براتون باشم , تنها امیدی که در حال حاضر برای عزیزتون باقی مونده، پیوند مغزه .\"\r\n\r\n\"این عمل ، کاملا در مرحله أزمایش ، ریسکی و خطرناکه ولی در عین حال راه دیگه ای هم وجود نداره, بیمه کل هزینه عمل را پرداخت میکنه ولی هز ینه مغز رو خودتون باید پرداخت کنین .\"\r\n\r\nاعضا خانواده در سکوت مطلق به گفته های دکتر گوش می کردن , بعد از مدتی بالاخره یکیشون پرسید :\" خب , قیمت یه مغز چنده؟\";\r\nدکتر بلافاصله جواب داد :\"5000$ برای مغز یک زن و 200$ برای مغز یک مرد .\"\r\nموقعیت نا جوری بود , خانم های داخل اتاق سعی می کردن نخندن و نگاهشون با آقایون داخل اتاق تلاقی نکنه , بعضی ها هم با خودشون پوز خند می زدن !\r\n\r\nبالاخره یکی طاقت نیاورد و سوالی که پرسیدنش آرزوی همه بود از دهنش پرید که : \"چرا مغز خانم ها گرونتره ؟ \"\r\n\r\nدکتر با معصومیت بچگانه ای برای حضار داخل اتاق توضیح داد که : \" این قیمت استاندارد عمله ! باید یادآوری کنم که مغز آقایون چون استفاده میشه، خب دست دومه و طبیعتا ارزونتر !\"\r\n"},{"id":1540,"category_id":10,"category_code":"s10","source_id":102,"title":"ملاقات یک انسان با خدا ","content":"روزی یک مرد روحانی با خداوند مکالمه ای داشت: 'خداوندا! دوست دارم بدانم بهشت و جهنم چه شکلی هستند؟ '، خداوند او را به سمت دو در هدایت کرد و یکی از آنها را باز کرد، مرد نگاهی به داخل انداخت، درست در وسط اتاق یک میز گرد بزرگ وجود داشت که روی آن یک ظرف خورش بود، که آنقدر بوی خوبی داشت که دهانش آب افتاد،...\r\n افرادی که دور میز نشسته بودند بسیار لاغر مردنی و مریض حال بودند، به نظر قحطی زده می آمدند، آنها در دست خود قاشق هایی با دسته بسیار بلند داشتند که این دسته ها به بالای بازوهایشان وصل شده بود و هر کدام از آنها به راحتی می توانستند دست خود را داخل ظرف خورش ببرند تا قاشق خود را پر نمایند، اما از آن جایی که این دسته ها از بازوهایشان بلند تر بود، نمی توانستند دستشان را برگردانند و قاشق را در دهان خود فرو ببرند.\r\n\r\nمرد روحانی با دیدن صحنه بدبختی و عذاب آنها غمگین شد، خداوند گفت: 'تو جهنم را دیدی، حال نوبت بهشت است'، آنها به سمت اتاق بعدی رفتند و خدا در را باز کرد، آنجا هم دقیقا مثل اتاق قبلی بود، یک میز گرد با یک ظرف خورش روی آن و افراد دور میز، آنها مانند اتاق قبل همان قاشق های دسته بلند را داشتند، ولی به اندازه کافی قوی و چاق بوده، می گفتند و می خندیدند، مرد روحانی گفت: 'خداوندا نمی فهمم؟!'، خداوند پاسخ داد: 'ساده است، فقط احتیاج به یک مهارت دارد، می بینی؟ اینها یاد گرفته اند که به یکدیگر غذا بدهند، در حالی که آدم های طمع کار اتاق قبل تنها به خودشان فکر می کنند!'\r\n\r\nهنگامی که موسی فوت می کرد، به شما می اندیشید، هنگامی که عیسی مصلوب می شد، به شما فکر می کرد، هنگامی که محمد وفات می یافت نیز به شما می اندیشید، گواه این امر کلماتی است که آنها در دم آخر بر زبان آورده اند، این کلمات از اعماق قرون و اعصار به ما یادآوری می کنند که یکدیگر را دوست داشته باشید، که به همنوع خود مهربانی نمایید، که همسایه خود را دوست بدارید، زیرا که هیچ کس به تنهایی وارد بهشت خدا (ملکوت الهی) نخواهد شد.\r\n"},{"id":1541,"category_id":10,"category_code":"s10","source_id":103,"title":"چه کشکی، چه پشمی ","content":"چوپانی گله را به صحرا برد به درخت گردوی تنومندی رسید.\r\nاز آن بالا رفت و به چیدن گردو مشغول شد که ناگهان گردباد سختی در گرفت،\r\nخواست فرود آید، ترسید. باد شاخه ای را که چوپان روی آن بود به این طرف و آن طرف می برد.\r\nدید نزدیک است که بیفتد و دست و پایش بشکند.\r\nدر حال مستاصل شد....\r\nاز دور بقعه امامزاده ای را دید و گفت:\r\nای امام زاده گله ام نذر تو، از درخت سالم پایین بیایم.\r\nقدری باد ساکت شد و چوپان به\r\nشاخه قوی تری دست زد و جای پایی پیدا کرده و خود را محکم گرفت.\r\nگفت:\r\nای امام زاده خدا راضی نمی شود که زن و بچه من بیچاره از تنگی و خواری بمیرند و تو همه گله را صاحب شوی...\r\nنصف گله را به تو می دهم و نصفی هم برای خودم...\r\nقدری پایین تر آمد.\r\nوقتی که نزدیک تنه درخت رسید گفت:\r\nای امام زاده نصف گله را چطور نگهداری می کنی؟\r\nآنهار ا خودم نگهداری می کنم در عوض کشک و پشم نصف گله را به تو می دهم.\r\nوقتی کمی پایین تر آمد گفت:\r\nبالاخره چوپان هم که بی مزد نمی شود کشکش مال تو، پشمش مال من به عنوان دستمزد.\r\nوقتی باقی تنه را سُرخورد و پایش به زمین رسید نگاهی به گنبد امامزاده انداخت و گفت:\r\nمرد حسابی چه کشکی چه پشمی؟\r\nما از هول خودمان یک غلطی کردیم\r\nغلط زیادی که جریمه ندارد.\r\n"},{"id":1542,"category_id":10,"category_code":"s10","source_id":104,"title":"مشکلات زندگی ","content":"استادی درشروع کلاس درس، لیوانی پراز آب به دست گرفت. آن را بالا گرفت که همه ببینند. بعد از شاگردان پرسید:\r\nبه نظر شما وزن این لیوان چقدر است؟\r\nشاگردان جواب دادند:\r\n50 گرم ، 100 گرم ، 150 گرم\r\nاستاد گفت:\r\nمن هم بدون وزن کردن، نمی دانم دقیقا“ وزنش چقدراست.\r\nاما سوال من این است: اگر من این لیوان آب را چند دقیقه همین طور نگه دارم، چه اتفاقی خواهد افتاد؟\r\nشاگردان گفتند: هیچ اتفاقی نمی افتد.\r\nاستاد پرسید:\r\nخوب، اگر یک ساعت همین طور نگه دارم، چه اتفاقی می افتد؟\r\nیکی از شاگردان گفت: دست تان کم کم درد میگیرد.\r\n\r\nحق با توست... حالا اگر یک روز تمام آن را نگه دارم چه؟\r\n\r\nشاگرد دیگری گفت: دست تان بی حس می شود. عضلات به شدت تحت فشار قرار میگیرند و فلج می شوند. و مطمئنا“ کارتان به بیمارستان خواهد کشید و همه شاگردان خندیدند\r\nاستاد گفت: خیلی خوب است. ولی آیا در این مدت وزن لیوان تغییرکرده است؟\r\n\r\nشاگردان جواب دادند: نه\r\nپس چه چیز باعث درد و فشار روی عضلات می شود؟ درعوض من چه باید بکنم؟\r\n\r\nشاگردان گیج شدند. یکی از آنها گفت: لیوان را زمین بگذارید.\r\n\r\nاستاد گفت: دقیقا“ مشکلات زندگی هم مثل همین است.\r\n\r\nاگر آنها را چند دقیقه در ذهن تان نگه دارید.\r\n\r\nاشکالی ندارد. اگر مدت طولانی تری به آنها فکر کنید، به درد خواهند آمد.\r\n\r\nاگر بیشتر از آن نگه شان دارید، فلج تان می کنند و دیگر قادر به انجام کاری نخواهید بود.\r\n\r\nفکرکردن به مشکلات زندگی مهم است.. اما مهم تر آن است که درپایان هر روز و پیش از خواب، آنها را زمین بگذارید.\r\n\r\nبه این ترتیب تحت فشار قرار نمی گیرند، هر روز صبح سرحال و قوی بیدار می شوید و قادر خواهید بود از عهده هرمسئله و چالشی که برایتان پیش می آید، برآیید!\r\n\r\nدوست من، یادت باشد که لیوان آب را همین امروز زمین بگذاری.\r\n\r\nزندگی همین است! \r\n"},{"id":1543,"category_id":10,"category_code":"s10","source_id":105,"title":"نیاز ","content":"لوئیز رفدفن ، زنی بود با لباسهای کهنه و مندرس ، و نگاهی مغموم . وارد خواربار فروشی محله شد و با فروتنی از صاحب مغازه خواست کمی خواروبار به او بدهد. به نرمی گفت شوهرش بیمار است و نمی تواند کار کند و شش بچه شان بی غذا مانده اند.\r\n\r\nجان لانگ هاوس، صاحب مغازه، با بی اعتنایی محلش نگذاشت و با حالت بدی خواست او را بیرون کند.\r\nزن نیازمند در حالی که اصرار میکرد گفت: «آقا شما را به خدا به محض اینکه بتوانم پولتان را میآورم .»\r\n\r\nجان گفت نسیه نمی دهد. مشتری دیگری که کنار پیشخوان ایستاده بود و گفت و گوی آن دو را می شنید به مغازه دار گفت : «ببین این خانم چه میخواهد خرید این خانم با من .»\r\n\r\nخواربار فروش گفت: لازم نیست خودم می دهم لیست خریدت کو ؟\r\n\r\nلوئیز گفت : اینجاست.\r\n\r\n- « لیست ات را بگذار روی ترازو به اندازه وزنش هر چه خواستی ببر.» !!\r\n\r\nلوئیز با خجالت یک لحظه مکث کرد، از کیفش تکه کاغذی درآورد و چیزی رویش نوشت و آن را روی کفه ترازو گذاشت. همه با تعجب دیدند کفه ترازو پایین رفت.\r\n\r\nخواربارفروش باورش نمیشد.\r\nمشتری از سر رضایت خندید.\r\n\r\nمغازه دار با ناباوری شروع به گذاشتن جنس در کفه دیگر ترازو کرد کفه ترازو برابر نشد، آن قدر چیز گذاشت تا کفه ها برابر شدند.\r\n\r\nدر این وقت، خواربار فروش با تعجب و دلخوری تکه کاغذ را برداشت ببیند روی آن چه نوشته است.\r\nکاغذ لیست خرید نبود، دعای زن بود که نوشته بود:\r\n« ای خدای عزیزم تو از نیاز من با خبری، خودت آن را برآورده کن »\r\n"},{"id":1544,"category_id":10,"category_code":"s10","source_id":106,"title":"آینده نگری! ","content":"جوون: ببخشین آقا ، می تونم بپرسم ساعت چنده؟\r\nپیرمرد:معلومه که نه!\r\nجوون: ولی چرا؟! مثلا اگه ساعت رو به من بگی چی از دست میدی؟!\r\nپیرمرد: ممکنه ضرر کنم اگه ساعت رو به تو بگم!\r\nجوون: میشه بگی چطور همچین چیزی ممکنه؟!\r\nپیرمرد: ببین… اگه من ساعت رو به تو بگم ، ممکنه تو تشکر کنی و فردا هم بخوای دوباره ساعت رو از من بپرسی!\r\nجوون: کاملا امکانش هست!\r\nپیرمرد: ممکنه ما دو سه بار دیگه هم همدیگه رو ملاقات کنیم و تو اسم و آدرس من رو بپرسی!\r\nجوون: کاملا امکان داره!\r\nپیرمرد: یه روز ممکنه تو بیای به خونهء من و بگی که فقط داشتی از اینجا رد می شدی و اومدی که یه سر به من بزنی! بعد من ممکنه از روی تعارف تو رو به یه فنجون چایی دعوت کنم! بعد از این دعوت من ، ممکنه تو بازم برای خوردن چایی بیای خونهء من و بپرسی که این چایی رو کی درست کرده؟!\r\nجوون: ممکنه!\r\nپیرمرد: بعد من بهت می گم که این چایی رو دخترم درست کرده! بعد من مجبور میشم دختر خوشگل و جوونم رو بهت معرفی کنم و تو هم دختر من رو می پسندی!\r\nمرد جوون لبخند میزنه!\r\nپیرمرد: بعد تو سعی می کنی که بارها و بارها دختر من رو ملاقات کنی! ممکنه دختر من رو به سینما دعوت کنی و با همدیگه بیرون برید!\r\nمرد جوون لبخند میزنه!\r\nپیرمرد: بعد ممکنه دختر من کم کم از تو خوشش بیاد و چشم انتظار تو بشه! بعد از ملاقاتهای متوالی ، تو عاشق دختر من میشی و بهش پیشنهاد ازدواج می کنی!\r\nمرد جوون لبخند میزنه!\r\nپیرمرد: بعد از یه مدت ، یه روز شما دو تا میاین پیش من و از عشقتون برای من تعریف می کنین و از من اجازه برای ازدواج می خواین!\r\nمرد جوون در حال لبخند: اوه بله!\r\nپیرمرد با عصبانیت: مردک ابله! من هیچوقت دخترم رو به ازدواج یکی مثل تو که حتی یه ساعت مچی هم از خودش نداره در نمیارم..!!\r\n"},{"id":1545,"category_id":10,"category_code":"s10","source_id":107,"title":"نقش شیطان در اقتصاد ","content":"روزی که ” پدر صمعان “ کشیش بزرگ پای پیاده بسوی دهی میرفت تا برای مردم موعظه کند وآنان را از دام  شیطان نجات دهد مردی زخمی را دید که روی زمین دراز کشیده بود و  ناله میکرد و کمک میخواست \r\nپدر صمعان در دلش گفت : \r\n” این مرد حتماً دزد است . شاید می خواسته مسافرها را لخت کند و نتوانسته . کسی زخمی اش کرده  می ترسم بمیرد و مرا متهم به کشتن او کنند”....\r\nاز کمک به او منصرف شد و به سفرش ادامه داد. اما فریاد مردِ محتضر او را متوقف کرد:\r\n ” ترکم نکن ! دارم می میرم بیا جلو! بیا، ما دوست قدیمی هستیم . تو پدر صمعانی ،  من هم نه دزدم و نه دیوانه “\r\nکشیش  با کنجکاوی به مرد نزدیک شد، اما او را نشناخت با کمی ترس پرسید تو کی هستی؟\r\nمرد گفت من شیطان ام !\r\n کشیش  پس از دقت بر بدن کج ومعوج او فریادی از وحشت کشید و گفت :\r\n خداوند تو را به من نشان داد تا تنفرم از تو بیشتر شود. نفرین بر تو. تو باید بمیری.\r\nشیطان گفت : ” بیا  زخمهای مرا ببند… تو نمیفهمی چه میگویی!  اینجا عده ای فرشته به من حمله کردند ومیکاییل با شمشیر دو لبه اش ضربه ای کاری به من وارد کرده.”\r\nکشیش گفت خدا را شکر که میکاییل بشر را از شر شیطان نجات داد .\r\nشیطان گفت :\r\n “تو مرا نفرین میکنی؟ در حالیکه هرچه قدرت وثروت است از من داری. بازار حرفه تو  بدون من کساد است. اگر من بمیرم ، تو هم از گرسنگی می میمیری چون مردم دیگر گناه نمیکنند وبه تو نیازی ندارند. مگر کار تو این نیست که به مردم هشدار بدهی به دام من نیفتند. اگر من اینجا بمیرم تو و کلیسا دیگر به چه دردی میخورند؟ بیا تا تاریک نشده من را نجات بده...”\r\nپدر صمعان شیطان را کول کرد وبطرف خانه راه افتاد ودر راه برای نجات شیطان دعا میکرد !!!\r\n"},{"id":1546,"category_id":10,"category_code":"s10","source_id":108,"title":"هرگز زود قضاوت نکن ! ","content":"مرد مسنی به همراه پسر ٢۵ ساله‌اش در قطار نشسته بود. در حالی که مسافران در صندلی‌های خود نشسته بودند، قطار شروع به حرکت کرد.\r\n\r\nبه محض شروع حرکت قطار پسر ٢۵ ساله که کنار پنجره نشسته بود پر از شور و هیجان شد. دستش را از پنجره بیرون برد و در حالی که هوای در حال حرکت را با لذت لمس می‌کرد فریاد زد: پدر نگاه کن درخت‌ها حرکت می‌کنن. مرد مسن با لبخندی هیجان پسرش را تحسین کرد.\r\n\r\nکنار مرد جوان، زوج جوانی نشسته بودند که\r\nحرف‌های پدر و پسر را می‌شنیدند و از حرکات پسر جوان که مانند یک کودک ۵ ساله رفتار می‌کرد، متعجب شده بودند.\r\n\r\nناگهان جوان دوباره با هیجان فریاد زد: پدر نگاه کن دریاچه، حیوانات و ابرها با قطار حرکت می‌کنند.\r\n\r\nزوج جوان پسر را با دلسوزی نگاه می‌کردند.\r\n \r\nباران شروع شد چند قطره روی دست مرد جوان چکید.\r\n\r\nاو با لذت آن را لمس کرد و چشم‌هایش را بست و دوباره فریاد زد: پدر نگاه کن باران می‌بارد،‌ آب روی من چکید.\r\n\r\nزوج جوان دیگر طاقت نیاورند و از مرد مسن پرسیدند: ‌چرا شما برای مداوای پسرتان به پزشک مراجعه نمی‌کنید؟\r\n\r\nمرد مسن گفت: ما همین الان از بیمارستان بر می‌گردیم. امروز پسر من برای اولین بار در زندگی می‌تواند ببیند.\r\n"},{"id":1547,"category_id":10,"category_code":"s10","source_id":109,"title":"رازهای تصمیمات خدا ","content":"شهسواری به دوستش گفت: بیا به کوهی که خدا آنجا زندگی می کند برویم.میخواهم ثابت کنم که اوفقط بلد است به ما دستور بدهد، وهیچ کاری برای خلاص کردن ما از زیر بار مشقات نمی کند.\r\nدیگری گفت: موافقم .اما من برای ثابت کردن ایمانم می آیم ....\r\nوقتی به قله رسیدند ،شب شده بود. در تاریکی صدایی شنیدند:سنگهای اطرافتان را بار اسبانتان کنید وآنها را پایین ببرید\r\nشهسوار اولی گفت:می بینی؟بعداز چنین صعودی ،از ما می خواهد که بار سنگین تری را حمل کنیم.محال است که اطاعت کنم !\r\nدیگری به دستور عمل کرد. وقتی به دامنه کوه رسید،هنگام طلوع بود و انوار خورشید، سنگهایی را که شهسوار مومن با خود آورده بود،روشن کرد. آنها خالص ترین الماس ها بودند... \r\nمرشد می گوید: تصمیمات خدا مرموزند،اما همواره به نفع ما هستند .\r\n"},{"id":1548,"category_id":10,"category_code":"s10","source_id":110,"title":"انسان از کجا تا به کجا ","content":"قرن ها پیش، در کشوری خاص ، یک نقاش بزرگ وجود داشت. وقتی جوان بود تصمیم گرفت یک چهره ی واقعاً عالی نقش کند که سرور الهی از آن بدرخشد: صورت کسی که چشمانش با آرامشی بی نهایت بدرخشد. بنابراین می خواست کسی را پیدا کند تا صورتش منتقل کننده ی چیزی از فراسو باشد، چیزی ورای این زندگی و این دنیا.\r\n\r\nهنرمند ما عازم سفر شد و سراسر کشور را روستا به روستا، جنگل به جنگل به دنبال چنین شخصی گشت و عاقبت،\r\n\r\nپس از مدت های مدید با چوپانی در کوهستان برخورد کرد که آن معصومیت و درخشش را در چشمانش داشت،\r\n\r\nبا چهره ای که نشانی از وطنی آسمانی در آن نقش بسته بود.\r\n\r\nیک نظر به صورت او کافی بود....\r\n تا همه را متقاعد کند که الوهیت در انسان ها منزل دارد.\r\n\r\nهنرمند تصویری از صورت آن چوپان کشید. میلیون ها نسخه از آن نقاشی به فروش رفت، حتی در سرزمین های دوردست. مردم فقط با آویختن آن نقاشی به دیوار خانه هایشان احساس نعمت و برکت می کردند.\r\n\r\nپس از حدود بیست سال، وقتی که آن هنرمند سالخورده شده بود، فکر دیگری به نظرش رسید.\r\n\r\nتجربه اش در زندگی به او نشان داده بود که تمام انسان ها موجوداتی الهی نیستند و اهریمن نیز در آنان وجود دارد.\r\n\r\nفکر کشیدن چهره ای که نشانگر وجود اهریمن در انسان باشد به نظرش رسید.\r\n\r\nفکر کرد که این دو چهره می توانند یکدیگر را تکمیل کنند و نشان دهنده ی انسان کامل باشند.\r\n\r\nدر روزگار پیری، باردیگر به دنبال یافتن مردی راهی شد که انسان نبود و یک اهریمن بود.\r\n\r\nوارد قمارخانه ها و میکده ها و تیمارستان ها شد. این شخص می باید سرشار از آتش دوزخ باشد، صورتش باید نشانگر کامل اهریمن باشد: زشت و آزاردهنده. او در پی خود تصویر گناه بود.\r\n\r\nاو قبلاً تصویری از الوهیت را نقش بسته بود و حالا در پی کسی بود که کالبد شیطان باشد.\r\n\r\nپس از جست و جویی طولانی، عاقبت با یک محکوم در زندان برخورد کرد. آن مرد مرتکب هفت قتل شده بود و ظرف چند روز آینده قرار بود حلق آویز شود. دوزخ از چشمان آن مرد مشهود بود، او تجسد نفرت بود. صورتش زشت ترین صورتی بود که ممکن بود یافت شود. هنرمند شروع کرد به کشیدن تصویر چهره ی آن مرد.\r\n\r\nوقتی نقاشی را تمام کرد، آن را در کنار آن نقاشی قبلی قرار داد تا تفاوت را ببیند. از نظر هنر نقاشی، گفتن اینکه کدام بهتر بود دشوار بود، هردو عالی بودند. او ایستاد و به هردو تابلو نگاه کرد. آنگاه ناله ای شنید.\r\n\r\nبرگشت و دید که آن زندانی مشغول گریستن است. هنرمند تعجب کرده بود.\r\n\r\nپرسید، \"دوست من چرا گریه می کنی؟\" آیا این تصاویر تو را ناراحت می کنند؟\"\r\n\r\nزندانی گفت، \"در تمام این مدت سعی داشتم چیزی را از تو پنهان کنم، ولی امروز دیگر نتوانستم.\r\n\r\nواضح است که نمی دانی آن تصویر اولی نیز خود من هستم. هردو نقاشی از صورت من است.\r\n\r\nمن همان چوپانی هستم که تو بیست سال پیش در کوهستان دیدی.\r\n\r\nمن برای سقوط خودم در این بیست ساله گریه می کنم. من از بهشت به دوزخ فرو افتاده ام، از الوهیت به اهریمن.\"\r\nتوضیح اینکه این داستان واقعی است و در واقع اصل قضیه در مورد لئوناردو داوینچی نقاش بزرگ ایتالیایی است که برای تابلوی شام آخر حضرت  تصویر حضرت مسیج (ع)‌را نقش کرد و برای تصویر یهودا (‌حواری خائن )‌وقتی به دنبال پرتره مناسب می گشت متاسفانه به همان شخصی برخورد کرد که زمانی چهره حضرت مسیح (ع)‌را از آن ترسیم کرده بود.  \r\n"},{"id":1549,"category_id":10,"category_code":"s10","source_id":111,"title":"مهندسی و مدیریت ","content":"مردی که سوار بر بالن در حال حرکت بود ناگهان به یاد آورد قرار مهمّی دارد؛ ارتفاعش را کم کرد و از مردی که روی زمین بود پرسید:\r\n\r\n\"ببخشید آقا ؛ من قرار مهمّی دارم ، ممکنه به من بگویید کجا هستم تا ببینم به موقع به قرارم می رسم یا نه؟\" \r\n\r\nمرد روی زمین : بله، شما در ارتفاع حدودا ً ۶ متری در طول جغرافیایی \"۱٨'۲۴ﹾ ۸۷ و عرض جغرافیایی \"۴۱'۲۱ﹾ ۳۷ هستید.\r\n\r\nمرد بالن سوار : شما باید مهندس باشید.\r\n\r\nمرد روی زمین :\r\nبله، از کجا فهمیدید؟؟\"\r\n\r\nمرد بالن سوار : چون اطلاعاتی که شما به من دادید اگر چه کاملا ً دقیق بود به درد من نمی خورد و من هنوز نمی دانم کجا هستم و به موقع به قرارم می رسم یا نه؟\"\r\n\r\nمرد روی زمین : شما باید مدیر باشید.\r\n\r\nمرد بالن سوار : بله، از کجا فهمیدید؟؟؟\" \r\n\r\nمرد روی زمین : چون شما نمی دانید کجا هستید و به کجا می خواهید بروید. قولی داده اید و نمی دانید چگونه به آن عمل کنید و انتظار دارید مسئولیت آن را دیگران بپذیرند.\r\n"},{"id":1550,"category_id":10,"category_code":"s10","source_id":112,"title":"یک گام هر چند کوچک ","content":"مردی در کنار ساحل دورافتاده ای قدم می‌زد. مردی را در فاصله دور می بیند که مدام خم می‌شود و چیزی را از روی زمین بر می‌دارد و توی اقیانوس پرت می‌کند. نزدیک تر می شود، می‌بیند مردی بومی صدفهایی را که به ساحل میافتد در آب می‌اندازد.\r\n\r\n - صبح بخیر رفیق، خیلی دلم میخواهد بدانم چه میکنی؟\r\n\r\n- این صدفها را در داخل اقیانوس می اندازم. الآن موقع مد دریاست و این\r\nصدف ها را به ساحل دریا آورده و اگر آنها را توی آب نیندازم از کمبود اکسیژن خواهند مرد.\r\n\r\n- دوست من! حرف تو را می فهمم ولی در این ساحل هزاران صدف این شکلی وجود دارد. تو که نمی‌توانی آنها را به آب برگردانی خیلی زیاد هستند و تازه همین یک ساحل نیست. نمی بینی کار تو هیچ فرقی در اوضاع ایجاد نمیکند؟\r\n\r\nمرد بومی لبخندی زد و خم شد و دوباره صدفی برداشت و به داخل دریا انداخت و گفت:\r\n\r\n\"برای این یکی اوضاع فرق کرد… !\"\r\n"},{"id":1551,"category_id":10,"category_code":"s10","source_id":113,"title":"کمک به رقباء ","content":"یکی از کشاورزان منطقه ای، همیشه در مسابقه‌ها، جایزه بهترین غله را به ‌دست می‌آورد و به ‌عنوان کشاورز نمونه شناخته شده بود. رقبا و همکارانش، علاقه‌مند شدند راز موفقیتش را بدانند. به همین دلیل، او را زیر نظر گرفتند و مراقب کارهایش بودند. پس از مدتی جستجو، سرانجام با نکته‌ عجیب و جالبی روبرو شدند. این کشاورز پس از هر نوبت کِشت، بهترین بذرهایش را به همسایگانش می‌داد و آنان را از این نظر تأمین می‌کرد. بنابراین، همسایگان او می‌بایست برنده‌ مسابقه‌ها می‌شدند نه خود او!....\r\n\r\nکنجکاویشان بیش‌تر شد و کوشش علاقه‌مندان به کشف این موضوع که با تعجب و تحیر نیز آمیخته شده بود، به جایی نرسید. سرانجام، تصمیم گرفتند ماجرا را از خود او بپرسند و پرده از این راز عجیب بردارند.\r\n\r\nکشاورز هوشیار و دانا، در پاسخ به پرسش همکارانش گفت: «چون جریان باد، ذرات بارورکننده غلات را از یک مزرعه به مزرعه‌ دیگر می‌برد، من بهترین بذرهایم را به همسایگان می‌دادم تا باد، ذرات بارورکننده نامرغوب را از مزرعه‌های آنان به زمین من نیاورد و کیفیت محصول‌های مرا خراب نکند!»\r\n\r\nهمین تشخیص درست و صحیح کشاورز، توفیق کامیابی در مسابقه‌های بهترین غله را برایش به ارمغان می‌آورد.\r\n\r\n“گاهی اوقات لازم است با کمک به رقبا و ارتقاء کیفیت و سطح آنها، کاری کنیم که از تأثیرات منفی آنها در امان باشیم”\r\n"},{"id":1552,"category_id":10,"category_code":"s10","source_id":114,"title":"مشتری خود را بشناسید ","content":"یکی از نمایندگان فروش شرکت کوکاکولا، مایوس و نا امید از خاورمیانه بازگشت.\r\n\r\nدوستی از وی پرسید: «چرا در کشورهای عربی موفق نشدی؟»\r\n\r\nوی جواب داد: «هنگامی که من به آنجا رسیدم مطمئن بودم که می توانم موفق شوم و فروش خوبی داشته باشم. اما مشکلی که داشتم این بود که من عربی نمی دانستم. لذا تصمیم گرفتم که پیام خود را از طریق پوستر به آنها انتقال دهم. بنابراین سه پوستر زیر را طراحی کردم:\r\n\r\nپوستر اول ...\r\nمردی را نشان می داد که خسته و کوفته در بیابان بیهوش افتاده بود.\r\n\r\nپوستر دوم مردی که در حال نوشیدن کوکا کولا بود را نشان می داد.\r\n\r\nپوستر سوم مردی بسیار سرحال و شاداب را نشان می داد.\r\n\r\nپوستر ها را در همه جا چسباندم.»\r\n\r\nدوستش از وی پرسید: «آیا این روش به کار آمد؟»\r\n\r\nوی جواب داد: «متاسفانه من نمی دانستم عربها از راست به چپ می خوانند و لذا آنها ابتدا تصویر سوم، سپس دوم و بعد اول را دیدند.»\r\n\r\n    قبل از هر کار جدیدی باید مطالعات اولیه به صورت کامل با در نظر گرفتن همه جوانب انجاه بشه.\r\n"},{"id":1553,"category_id":10,"category_code":"s10","source_id":115,"title":"آزادی ","content":"زن نصف شب از خواب بیدار شد و دید که شوهرش در رختخواب نیست و به دنبال او گشت. شوهرش را در حالی که توی آشپزخانه نشسته بود و به دیوار زل زده بود و در فکری عمیق فرو رفته بود و اشک‌هایش را پاک می‌‌کرد و فنجانی قهوه‌ می‌‌نوشید پیدا کرد ...\r\n\r\nدر حالی‌ که داخل آشپزخانه می‌‌شد پرسید:چی‌ شده عزیزم این موقع شب اینجا نشستی؟!\r\n\r\nشوهرش نگاهش را از دیوار برداشت و گفت:هیچی‌ فقط اون وقتها رو به یاد میارم، ۲۰ سال پیش که تازه همدیگرو ملاقات کرده بودیم ، یادته...؟!\r\nزن که حسابی‌ تحت تاثیر قرار گرفته بود، چشم‌هایش پر از اشک شد و گفت : آره یادمه...\r\n\r\nشوهرش ادامه داد : یادته پدرت که فکر می کردیم مسافرته ما رو توی اتاقت غافلگیر کرد؟!\r\n\r\nزن در حالی‌ که روی صندلی‌ کنار شوهرش می نشست گفت : آره یادمه، انگار دیروز بود!\r\n\r\nمرد بغضش را قورت داد و ادامه داد : یادته پدرت تفنگ رو به سمت من نشونه گرفت و گفت: یا با دختر من ازدواج میکنی‌ یا ۲۰ سال می‌‌فرستمت زندان آب خنک بخوری ؟!\r\n\r\nزن گفت : آره عزیزم اون هم یادمه و یک ساعت بعدش که رفتیم محضر و...!\r\n\r\nمرد نتوانست جلوی گریه اش را بگیرد و گفت: اگه رفته بودم زندان امروز آزاد می شدم.\r\n"},{"id":1554,"category_id":10,"category_code":"s10","source_id":116,"title":"همیشه کیف پولتان را .... ","content":"من خیلی خوشحال بودم !\r\n\r\nمن و نامزدم قرار ازدواجمون رو گذاشته بودیم والدینم خیلی کمکم کردند دوستانم خیلی تشویقم کردند و نامزدم هم دختر فوق العاده ای بود…\r\n\r\nفقط یه چیز من رو یه کم نگران می کرد و اون هم خواهر نامزدم بود…!\r\n\r\nاون دختر باحال ، زیبا و جذابی بود که گاهی اوقات بی پروا با من شوخی های ناجوری می کرد و باعث می شد که من احساس راحتی نداشته باشم…\r\n\r\nیه روز خواهر نامزدم با من تماس گرفت و از من خواست که برم خونه شون برای انتخاب مدعوین عروسی !\r\n\r\nسوار ماشینم شدم و وقتی رفتم اونجا اون تنها بود و بلافاصله رک و راست به من گفت :\r\n\r\nاگه همین الان ۵۰۰ دلار به من بدی بعدش حاضرم با تو …………….!\r\nمن شوکه شده بودم و نمی تونستم حرف بزنم…\r\n\r\nاون گفت: من میرم توی اتاق خواب و اگه تو مایل به این کار هستی بیا پیشم…\r\n\r\nوقتی که داشت از پله ها بالا می رفت من بهش خیره شده بودم و بعد از رفتنش چند دقیقه ایستادم و بعد به طرف در ساختمون برگشتم و از خونه خارج شدم…!\r\n\r\nیهو با چهره نامزدم و چشمهای اشک آلود پدر نامزدم مواجه شدم!!!\r\n\r\nپدر نامزدم من رو در آغوش گرفت و گفت: تو از امتحان ما موفق بیرون اومدی…!\r\n\r\nما خیلی خوشحالیم که چنین دامادی داریم و هیچکس بهتر از تو نمی تونستیم برای دخترمون پیدا کنیم به خانوادهء ما خوش اومدی !!!\r\n\r\nنتیجه اخلاقی: همیشه کیف پولتون رو توی داشبورد ماشینتون بذارید !!!\r\n"},{"id":1555,"category_id":10,"category_code":"s10","source_id":117,"title":"بوی مادر ","content":"روز اول سال تحصیلى، خانم تامپسون معلّم کلاس پنجم دبستان وارد کلاس شد و پس از صحبت هاى اولیه، مطابق معمول به دانش آموزان گفت که همه آن ها را به یک اندازه دوست دارد و فرقى بین آنها قائل نیست. البته او دروغ می گفت و چنین چیزى امکان نداشت. مخصوصاً این که پسر کوچکى در ردیف جلوى کلاس روى صندلى لم داده بود به نام تدى استودارد....\r\n که خانم تامپسون چندان دل خوشى از او نداشت. تدى سال قبل نیز دانش آموز همین کلاس بود. همیشه لباس هاى کثیف به تن داشت، با بچه هاى دیگر نمی جوشید و به درسش هم نمی رسید. او واقعاً دانش آموز نامرتبى بود و خانم تامپسون از دست او بسیار ناراضى بود و سرانجام هم به او نمره قبولى نداد و او را رفوزه کرد.\r\nامسال که دوباره تدى در کلاس پنجم حضور می یافت، خانم تامپسون تصمیم گرفت به پرونده تحصیلى سال هاى قبل او نگاهى بیاندازد تا شاید به علّت درس نخواندن او پی ببرد و بتواند کمکش کند.\r\n\r\nمعلّم کلاس اول تدى در پرونده اش نوشته بود: تدى دانش آموز باهوش، شاد و با استعدادى است. تکالیفش را خیلى خوب انجام می دهد و رفتار خوبى دارد. \"رضایت کامل\".\r\n\r\nمعلّم کلاس دوم او در پرونده اش نوشته بود: تدى دانش آموز فوق العاده اى است. همکلاسیهایش دوستش دارند ولى او به خاطر بیمارى درمان ناپذیر مادرش که در خانه بسترى است دچار مشکل روحى است.\r\n\r\nمعلّم کلاس سوم او در پرونده اش نوشته بود: مرگ مادر براى تدى بسیار گران تمام شده است. او تمام تلاشش را براى درس خواندن می کند ولى پدرش به درس و مشق او علاقه اى ندارد. اگر شرایط محیطى او در خانه تغییر نکند او به زودى با مشکل روبرو خواهد شد.\r\n\r\nمعلّم کلاس چهارم تدى در پرونده اش نوشته بود: تدى درس خواندن را رها کرده و علاقه اى به مدرسه نشان نمی دهد. دوستان زیادى ندارد و گاهى در کلاس خوابش می برد.\r\n\r\nخانم تامپسون با مطالعه پرونده هاى تدى به مشکل او پى برد و از این که دیر به فکر افتاده بود خود را نکوهش کرد. تصادفاً فرداى آن روز، روز معلّم بود و همه دانش آموزان هدایایى براى او آوردند. هدایاى بچه ها همه در کاغذ کادوهاى زیبا و نوارهاى رنگارنگ پیچیده شده بود، بجز هدیه تدى که داخل یک کاغذ معمولى و به شکل نامناسبى بسته بندى شده بود. خانم تامپسون هدیه ها را سرکلاس باز کرد. وقتى بسته تدى را باز کرد یک دستبند کهنه که چند نگینش افتاده بود و یک شیشه عطر که سه چهارمش مصرف شده بود در داخل آن بود. این امر باعث خنده بچه هاى کلاس شد امّا خانم تامپسون فوراً خنده بچه ها را قطع کرد و شروع به تعریف از زیبایى دستبند کرد. سپس آن را همانجا به دست کرد و مقدارى از آن عطر را نیز به خود زد. تدى آن روز بعد از تمام شدن ساعت مدرسه مدتى بیرون مدرسه صبر کرد تا خانم تامپسون از مدرسه خارج شد. سپس نزد او رفت و به او گفت: خانم تامپسون، شما امروز بوى مادرم را می دادید.\r\n\r\nخانم تامپسون، بعد از خداحافظى از تدى، داخل ماشینش رفت و براى دقایقى طولانى گریه کرد. از آن روز به بعد، او آدم دیگرى شد و در کنار تدریس خواندن، نوشتن، ریاضیات و علوم، به آموزش \"زندگی\" و \"عشق به همنوع\" به بچه ها پرداخت و البته توجه ویژه اى نیز به تدى می کرد.\r\n\r\nپس از مدتى، ذهن تدى دوباره زنده شد. هر چه خانم تامپسون او را بیشتر تشویق می کرد او هم سریعتر پاسخ می داد. به سرعت او یکى از با هوش ترین بچه هاى کلاس شد و خانم تامپسون با وجودى که به دروغ گفته بود که همه را به یک اندازه دوست دارد، امّا حالا تدى محبوبترین دانش آموزش شده بود.\r\n\r\nیکسال بعد، خانم تامپسون یادداشتى از تدى دریافت کرد که در آن نوشته بود شما بهترین معلّمى هستید که من در عمرم داشته ام.\r\n\r\nشش سال بعد، یادداشت دیگرى از تدى به خانم تامپسون رسید. او نوشته بود که دبیرستان را تمام کرده و شاگرد سوم شده است. و باز هم افزوده بود که شما همچنان بهترین معلمى هستید که در تمام عمرم داشته ام.\r\n\r\nچهار سال بعد از آن، خانم تامپسون نامه دیگرى دریافت کرد که در آن تدى نوشته بود با وجودى که روزگار سختى داشته است امّا دانشکده را رها نکرده و به زودى از دانشگاه با رتبه عالى فارغ التحصیل می شود. باز هم تأکید کرده بود که خانم تامپسون بهترین معلم دوران زندگیش بوده است.\r\n\r\nچهار سال دیگر هم گذشت و باز نامه اى دیگر رسید. این بار تدى توضیح داده بود که پس از دریافت لیسانس تصمیم گرفته به تحصیل ادامه دهد و این کار را کرده است. باز هم خانم تامپسون را محبوبترین و بهترین معلم دوران عمرش خطاب کرده بود. امّا این بار، نام تدى در پایان نامه کمى طولانی تر شده بود: دکتر تئودور استودارد.\r\n\r\nماجرا هنوز تمام نشده است. بهار آن سال نامه دیگرى رسید. تدى در این نامه گفته بود که با دخترى آشنا شده و می خواهند با هم ازدواج کنند. او توضیح داده بود که پدرش چند سال پیش فوت شده و از خانم تامپسون خواهش کرده بود اگر موافقت کند در مراسم عروسى در کلیسا، در محلى که معمولاً براى نشستن مادر داماد در نظر گرفته می شود بنشیند. خانم تامپسون بدون معطلى پذیرفت و حدس بزنید چکار کرد؟ او دستبند مادر تدى را با همان جاهاى خالى نگین ها به دست کرد و علاوه بر آن، یک شیشه از همان عطرى که تدى برایش آورده بود خرید و روز عروسى به خودش زد.\r\n\r\nتدى وقتى در کلیسا خانم تامپسون را دید او را به گرمى هر چه تمامتر در آغوش فشرد و در گوشش گفت: خانم تامپسون از این که به من اعتماد کردید از شما متشکرم. به خاطر این که باعث شدید من احساس کنم که آدم مهمى هستم از شما متشکرم. و از همه بالاتر به خاطر این که به من نشان دادید که می توانم تغییر کنم از شما متشکرم.\r\n\r\nخانم تامپسون که اشک در چشم داشت در گوش او پاسخ داد: تدى، تو اشتباه می کنى. این تو بودى که به من آموختى که می توانم تغییر کنم. من قبل از آن روزى که تو بیرون مدرسه با من صحبت کردى، بلد نبودم چگونه تدریس کنم.\r\n\r\nبد نیست بدانید که تدى استودارد هم اکنون در دانشگاه آیوا یک استاد برجسته پزشکى است و بخش سرطان دانشکده پزشکى این دانشگاه نیز به نام او نامگذارى شده است ! \r\n"},{"id":1556,"category_id":10,"category_code":"s10","source_id":118,"title":"آیا خدا وجود دارد!؟ ","content":"مردی برای اصلاح به آرایشگاه رفت در بین کار گفتگوی جالبی بین آنها در مورد خدا صورت گرفت آرایشگر گفت:من باور نمیکنم خدا وجود داشته با شد مشتری پرسید چرا؟ آرایشگر گفت : کافیست به خیابان بروی و ببینی مگر میشود با وجود خدای مهربان اینهمه مریضیو درد و رنج وجود داشته باشد؟ مشتری چیزی نگفت و\r\nاز مغازه بیرون رفت به محض اینکه از آرایشگاه بیرون آمد مردی را در خیابان دید با موهای ژولیده و کثیف با سرعت به آرایشگاه برگشت و به آرایشگر گفت می دانی به نظر من آرایشگر ها وجود ندارند مرد با تعجب گفت :چرا این حرف را میزنی؟ من اینجاهستم و همین الان موهای تو را مرتب کردم مشتری با اعتراض گفت : پس چرا کسانی مثل آن مرد بیرون از آریشگاه وجود دارند آرایشگر گفت : آرایشگر ها وجود دارند فقط مردم به ما مراجعه نمیکنند . مشتری گفت : دقیقا همین است خدا وجود دارد فقط مردم به او مراجعه نمیکنند . برای همین است که اینهمه درد و رنج در دنیا وجود دارد.\r\n"},{"id":1557,"category_id":10,"category_code":"s10","source_id":119,"title":"نقش زن در پیشرفت همسر ","content":"میگویند زنها در موفقیت و پیشرفت شوهرانشان نقش بسزایی دارند.\r\nساعد مراغه ای از نخست وزیران دوران پهلوی نقل کرده بود:\r\nزمانی که نایب کنسول شدم با خوشحالی پیش زنم آمدم و این خبر داغ را به اطلاع سرکار خانم رساندم...\r\nاما وی با بی اعتنایی تمام سری جنباند و گفت «خاک بر سرت کنند؛ فلانی کنسول است؛ تو نایب کنسولی؟!»\r\n\r\nگذشت و چندی بعد کنسول شدیم و رفتیم پیش خانم؛ آن هم با قیافهایی حق به جانب...\r\nباز خانم ما را تحویل نگرفت و گفت «خاک بر سرت کنند؛ فلانی معاون وزارت امور خارجه است و تو کنسولی؟!»\r\n\r\nشدیم معاون وزارت امور خارجه؛ که خانم باز گفت «خاک بر سرت؛ فلانی وزیر امور خارجه است و تو...؟!»\r\n\r\nشدیم وزیر امور خارجه گفت «فلانی نخست وزیر است... خاک بر سرت کنند!!!»\r\n\r\nالقصه آنکه شدیم نخست وزیر و این بار با گامهای مطمئن به خانه رفتم و منتظر بودم که خانم حسابی یکه بخورد و به عذر خواهی بیفتد.\r\nتا این خبر را دادم به من نگاهی کرد؛ سری جنباند و آهی کشید و گفت: «خاک بر سر ملتی که تو نخست وزیرش باشی\r\n"},{"id":1558,"category_id":10,"category_code":"s10","source_id":120,"title":"رقابت ","content":"روزی دو شکارچی برای شکار به جنگلی می روند . در حین شکار ناگهان خرس گرسنه ای را می بینند که قصد حمله به آنها را دارد. با دیدن این خرس گرسنه هر دوی آنها پا به فرار می گذارند در حین فرار  ناگهان یکی از آنها می ایستد و وسایل خود را دور می اندازد و کفشهایش را نیز  از پا در می آورد ...\r\nو دور می اندازد دوستش با تعجب از او می پرسد: فکر می کنی با این کار از خرس گرسنه سریع تر خواهی دوید؟ او می گوید : از خرس سریع تر نخواهم دوید ولی از تو سریع تر خواهم دوید در این صورت خرس اول به تو می‌رسد و تو را می خورد و من می توانم فرار کنم!!!\r\n"},{"id":1559,"category_id":10,"category_code":"s10","source_id":121,"title":"ارزش گردش پول ","content":"ماه آپریل است، درکنار یکی از سواحل دریای سیاه. باران می بارد، و شهر کوچک همانند صحرا خالی بنظر می رسد. درست هنگامی است که همه در یک بدهکاری بسر می برند و هر کدام برمنبای اعتبارشان زندگی را گذران می کنند. \r\nناگهان، یک مرد بسیار ثروتمندی وارد شهر می شود. او وارد تنهاهتلی که در این ساحل است می شود، اسکناس 100 یوروئی را روی پیشخوان هتل میگذارد و برای بازدید اتاق هتل و انتخاب آن به طبقه بالا می رود. \r\n صاحب هتل اسکناس 100 یوروئی را برمیدارد و در این فاصله می رود و بدهی خودش را به قصاب می پردازد. \r\nقصاب اسکناس 100 یوروئی را برمیدارد و با عجله به مزرعه پرورش خوک می رود و بدهی خود را به او می پردازد. \r\nمزرعه دار، اسکناس 100 یوروئی را با شتاب برای پرداخت بدهی اش به تامین کننده خوراک دام و سوخت\r\nسوخت میدهد. تامین کننده سوخت و خوراک دام برای پرداخت بدهی خود اسکناس 100 یوروئی را با شتاب پرداخت به فاحشه شهر که به او بدهکار بود میبرد. او در این اوضاع خراب اقتصادی به اعتبار مزرعه دار «خدمتش» را انجام داده بود تا پولش را بعدا دریافت کند. \r\nفاحشه اسکناس را با شتاب به هتل می آورد زیرااو به صاحب هتل بدهکار بود چون هنگامیکه مشتری خودش را یکشب به هتل آورد اتاق را به اعتبار کرایه کرده بود تا بعدا پولش را بپردازد. \r\nحالا هتل دار اسکناس را روی پیشخوان گذاشته است. \r\nدر این هنگام توریست ثروتمند پس از بازدید اتاق های هتل برمیگردد و اسکناس 100 یوروئی خود را برمیدارد و می گوید از اتاق ها خوشش نیامد و شهر را ترک می کند. \r\n  \r\n در این پروسه هیچکس صاحب پول نشده است. ولی بهر حال همه شهروندان در این هنگامه بدهی بهم ندارند همه بدهی هایشان را پرداخته اندو با یک انتظار خوشبینانه ای به آینده نگاه می کنند. \r\n  \r\nخوب است بدانید، که دولت انگلستان ازآغاز تا کنون در طول دوره موجودیتش، به این نحو معامله می کند. \r\n"},{"id":1560,"category_id":10,"category_code":"s10","source_id":122,"title":"همه امور بدان گونه که می نمایند نیستند ","content":"دو فرشته مسافر، برای گذراندن شب، در خانه یک خانواده ثروتمند فرود آمدند. این خانواده رفتار نامناسبی داشتند و دو فرشته را به مهمانخانه مجللشان راه ندادند، بلکه زیرزمین سرد خانه را در اختیار آنها گذاشتند.\r\nفرشته پیر در دیوار زیر زمین شکافی دید و آن را تعمیر کرد. وقتی که فرشته جوان از او پرسید چرا چنین کاری کرده، او پاسخ داد:\" همه امور بدان گونه که می نمایند نیستند.\"\r\nشب بعد، این دو فرشته به منزل یک خانواده فقیر ولی بسیار مهمان نواز رفتند.\r\n بعد از خوردن غذایی مختصر، زن و مرد فقیر، رختخواب خود را در اختیار دو فرشته گذاشتند.\r\nصبح روز بعد، فرشتگان، زن و مرد فقیر را گریان دیدند. گاو آنها که شیرش تنها وسیله گذران زندگیشان بود، در مزرعه مرده بود.\r\nفرشته جوان عصبانی شد و از فرشته پیر پرسید:\" چرا گذاشتی چنین اتفاقی بیفتد؟ خانواده قبلی همه چیز داشتند و با این حال تو کمکشان کردی، اما این خانواده دارایی اندکی دارند و تو گذاشتی که گاوشان هم بمیرد.\"\r\nفرشته پیر پاسخ داد:\"وقتی در زیر زمین آن خانواده ثروتمند بودیم، دیدم که در شکاف دیوار کیسه ای طلا وجود دارد. از آنجا که آنان بسیار حریص و بد دل بودند، شکاف را بستم و طلاها را از دیدشان مخفی کردم. دیشب وقتی در رختخواب زن و مرد فقیر خوابیده بودیم، فرشته مرگ برای گرفتن جان زن فقیر آمد و من به جایش آن گاو را به او دادم. همه امور بدان گونه که می نمایند نیستند و ما گاهی اوقات، خیلی دیر به این نکته پی می بریم.\"\r\n"},{"id":1561,"category_id":10,"category_code":"s10","source_id":123,"title":"دروغ های مادرم ","content":"دست و هیچگاه غذا به اندازهء کافی نداشتیم. روزی قدری برنج به دست آوردیم تا رفع گرسنگی کنیم. مادرم سهم خودش را هم به من داد، یعنی از بشقاب خودش به درون بشقاب من ریخت و گفت،:\r\n\r\n\"فرزندم برنج بخور، من گرسنه نیستم.\" و این اوّلین دروغی بود که به من گفت.\r\n\r\n زمان گذشت و قدری بزرگتر شدم. مادرم کارهای منزل را تمام می‎کرد و بعد برای صید ماهی به نهر کوچکی که در کنار منزلمان بود می‏رفت.  مادرم دوست داشت من ماهی بخورم تا رشد و نموّ خوبی داشته باشم. یک دفعه توانست به فضل خداوند دو ماهی صید کند.  به سرعت به خانه بازگشت و غذا را آماده کرد و دو ماهی را جلوی من گذاشت. شروع به خوردن ماهی کردم و اوّلی را تدریجاً خوردم.\r\n\r\n مادرم ذرّات گوشتی را که به استخوان و تیغ ماهی چسبیده بود جدا می‎کرد و می‎خورد؛\r\n دلم شاد بود که او هم مشغول خوردن است.  ماهی دوم را جلوی او گذاشتم تا میل کند.  امّا آن را فوراً به من برگرداند و گفت:\r\n\r\n\"بخور فرزندم؛ این ماهی را هم بخور؛ مگر نمی‎دانی که من ماهی دوست ندارم؟\"  و این دروغ دومی بود که مادرم به من گفت.\r\n\r\n\r\nقدری بزرگتر شدم و ناچار باید به مدرسه می‎رفتم و آه در بساط نداشتیم که وسایل درس و مدرسه بخریم. مادرم به بازار رفت و با لباس‎فروشی به توافق رسید که قدری لباس بگیرد و به در منازل مراجعه کرده به خانم‎ها بفروشد و در ازاء آن مبلغی دستمزد بگیرد. \r\n\r\n شبی از شب‎های زمستان، باران می‏بارید. مادرم دیر کرده بود و من در منزل منتظرش بودم. از منزل خارج شدم و در خیابان‎های مجاور به جستجو پرداختم و دیدم اجناس را روی دست دارد و به در منازل مراجعه می‎کند. ندا در دادم که، \"مادر بیا به منزل برگردیم؛ دیروقت است و هوا سرد. بقیه کارها را بگذار برای فردا صبح.\"  لبخندی زد و گفت:\r\n\r\n \"پسرم، خسته نیستم.\" و این دفعه سومی بود که مادرم به من دروغ گفت.\r\n\r\n\r\n به روز آخر سال رسیدیم و مدرسه به اتمام می‎رسید.  اصرار کردم که مادرم با من بیاید. من وارد مدرسه شدم و او بیرون، زیر آفتاب سوزان، منتظرم ایستاد.  موقعی که زنگ خورد و امتحان به پایان رسید، از مدرسه خارج شدم. \r\n\r\n مرا در آغوش گرفت و بشارت توفیق از سوی خداوند تعالی داد.  در دستش لیوانی شربت دیدم که خریده بود من موقع خروج بنوشم.  از بس تشنه بودم لاجرعه سر کشیدم تا سیراب شدم. مادرم مرا در بغل گرفته بود و \"نوش جان، گوارای وجود\" می‏گفت.  نگاهم به صورتش افتاد دیدم سخت عرق کرده؛ فوراً لیوان شربت را به سویش گرفتم و گفتم، \"مادر بنوش.\" گفت:\r\n\r\n \"پسرم، تو بنوش، من تشنه نیستم.\" و این چهارمین دروغی بود که مادرم به من گفت.\r\n\r\n\r\nبعد از درگذشت پدرم، تأمین معاش به عهده مادرم بود؛ بیوه‎زنی که تمامی مسئولیت منزل بر شانهء او قرار گرفت. می‏بایستی تمامی نیازها را برآورده کند. زندگی سخت دشوار شد و ما اکثراً گرسنه بودیم. عموی من مرد خوبی بود و منزلش نزدیک منزل ما. غذای بخور و نمیری برایمان می‏فرستاد. وقتی مشاهده کرد که وضعیت ما روز به روز بدتر می‏شود، به مادرم نصیحت کرد که با مردی ازدواج کند که بتواند به ما رسیدگی نماید، چه که مادرم هنوز جوان بود. امّا مادرم زیر بار ازدواج نرفت و گفت:\r\n\r\n \"من نیازی به محبّت کسی ندارم...\" و این پنجمین دروغ او بود.\r\n\r\n\r\nدرس من تمام شد و از مدرسه فارغ‎التّحصیل شدم. بر این باور بودم که حالا وقت آن است که مادرم استراحت کند و مسئولیت منزل و تأمین معاش را به من واگذار نماید. سلامتش هم به خطر افتاده بود و دیگر نمی‏توانست به در منازل مراجعه کند. پس صبح زود سبزی‎های مختلف می‏خرید و فرشی در خیابان می‏انداخت و می‏فروخت. وقتی به او گفتم که این کار را ترک کند که دیگر وظیفهء من بداند که تأمین معاش کنم. قبول نکرد و گفت:\r\n\r\n\"پسرم مالت را از بهر خویش نگه دار؛ من به اندازهء کافی درآمد دارم.\" و این ششمین دروغی بود که به من گفت.\r\n\r\n\r\nدرسم را تمام کردم و وکیل شدم. ارتقاء رتبه یافتم. یک شرکت آلمانی مرا به خدمت گرفت. وضعیتم بهتر شد و به معاونت رئیس رسیدم. احساس کردم خوشبختی به من روی کرده است. در رؤیاهایم آغازی جدید را می‏دیدم و زندگی بدیعی که سراسر خوشبختی بود. به سفرها می‏رفتم.  با مادرم تماس گرفتم و دعوتش کردم که بیاید و با من زندگی کند. امّا او که نمی‏خواست مرا در تنگنا قرار دهد گفت:\r\n\r\n\"فرزندم، من به خوش‏گذرانی و زندگی راحت عادت ندارم.\"\r\n\r\nو این هفتمین دروغی بود که مادرم به من گفت. \r\n\r\n \r\nمادرم پیر شد و به سالخوردگی رسید.  به بیماری سرطان ملعون دچار شد و لازم بود کسی از او مراقبت کند و در کنارش باشد. امّا چطور می‏توانستم نزد او بروم که بین من و مادر عزیزم شهری فاصله بود.  همه چیز را رها کردم و به دیدارش شتافتم.  دیدم بر بستر بیماری افتاده است. وقتی رقّت حالم را دید، تبسّمی بر لب آورد. درون دل و جگرم آتشی بود که همهء اعضاء درون را می‏سوزاند. سخت لاغر و ضعیف شده بود. این آن مادری نبود که من می‎‏شناختم. اشک از چشمم روان شد. امّا مادرم در مقام دلداری من بر آمد و گفت:\r\n\r\n \"گریه نکن، پسرم. من اصلاً دردی احساس نمی‎کنم.\" و این هشتمین دروغی بود که مادرم به من گفت.\r\n\r\n\r\nوقتی این سخن را بر زبان راند، دیدگانش را بر هم نهاد و دیگر هرگز برنگشود. جسمش از درد و رنج این جهان رهایی یافت.\r\n\r\nاین سخن را با جمیع کسانی می‎گویم که در زندگی‎اش از نعمت وجود مادر برخوردارند. این نعمت را قدر بدانید قبل از آن که از فقدانش محزون گردید.\r\n\r\nاین سخن را با کسانی می‎گویم که از نعمت وجود مادر محرومند. همیشه به یاد داشته باشید که چقدر به خاطر شما رنج و درد تحمّل کرده است و از خداوند متعال برای او طلب رحمت و بخشش نمایید.\r\n\r\nمادر دوستت دارم. خدایا او را غریق بحر رحمت خود فرما همانطور که مرا از کودکی تحت پرورش خود قرار داد.\r\n"},{"id":1562,"category_id":10,"category_code":"s10","source_id":124,"title":"دنیا از آنٍ خیال پردازان است.... ","content":"می گویند در زمانهای دور پسری بود که به اعتقاد پدرش هرگز نمی توانست با دستانش کار با ارزشی انجام دهد. این پسر هر روز به کلیسایی در نزدیکی محل زندگی خود می رفت و ساعتها به تکه سنگ مرمر بزرگی که در حیاط کلیسا قرار داشت خیره می شد و هیچ نمی گفت. روزی شاهزاده ای از کنار کلیسا عبور کرد و پسرک را دید که به این تکه سنگ خیره شده است و هیچ نمی گوید. از اطرافیان در مورد پسر پرسید. به او گفتند که او چهار ماه است هر روز به حیاط کلیسا می آید و به این تکه سنگ خیره می شود و هیچ نمی گوید.\r\n\r\nشاهزاده دلش برای پسرک سوخت. کنار او آمد و آهسته به او گفت:\r\n«جوان، به جای بیکار نشسستن و زل زدن به این تخته سنگ، بهتر است برای خود کاری دست و پا کنی و آینده خود را بسازی.»\r\n\r\nپسرک در مقابل چشمان حیرت زده شاهزاده، مصمم و جدی به سوی او برگشت و در چشمانش خیره شد و محکم و متین پاسخ داد: «من همین الان در حال کار کردن هستم!» و بعد دوباره به تخته سنگ خیره شد.\r\n\r\nشاهزاده از جا برخاست و رفت. چند سال بعد به او خبر دادند که آن پسرک از آن تخته سنگ یک مجسمه با شکوه از حضرت داوود ساخته است. مجسمه ای که هنوز هم جزو شاهکارهای مجسمه سازی دنیا به شمار می آید. نام آن پسر «میکل آنژ» بود!\r\n\r\n     قبل از شروع هر کار فیزیکی بهتر است که به اندازه لازم در موردش فکر کرد. حتی اگر زمان زیادی بگیرد.\r\n"},{"id":1563,"category_id":10,"category_code":"s10","source_id":125,"title":"قبل از تلاش برای حل مساله اول آن را خوب بشناسیم.. ","content":"مایکل، راننده اتوبوس شهری، مثل همیشه اول صبح اتوبوسش را روشن کرد و در مسیر همیشگی شروع به کار کرد. در چند ایستگاه اول همه چیز مثل معمول بود و تعدادی مسافر پیاده می شدند و چند نفر هم سوار می شدند. در ایستگاه بعدی، یک مرد با هیکل بزرگ، قیافه ای خشن و رفتاری عجیب سوار شد..\r\n\r\nاو در حالی که به مایکل زل زده بود گفت: «تام هیکل پولی نمی ده!» و رفت و نشست.\r\n\r\nمایکل که تقریباً ریز جثه بود و اساساً آدم ملایمی بود چیزی نگفت اما راضی هم نبود. روز بعد هم\r\nدوباره همین اتفاق افتاد و مرد هیکلی سوار شد و با گفتن همان جمله، رفت و روی صندلی نشست و روز بعد و روز بعد...\r\n\r\nاین اتفاق که به کابوسی برای مایکل تبدیل شده بود خیلی او را آزار می داد. بعد از مدتی مایکل دیگر نمی تواست این موضوع را تحمل کند و باید با او برخورد می کرد. اما چطوری از پس آن هیکل بر می آمد؟ بنابراین در چند کلاس بدنسازی، کاراته و جودو و ... ثبت نام کرد. در پایان تابستان، مایکل به اندازه کافی آماده شده بود و اعتماد به نفس لازم را هم پیدا کرده بود.\r\n\r\nبنابراین روز بعدی که مرد هیکلی سوار اتوبوس شد و گفت: «تام هیکل پولی نمی ده!»\r\n\r\nمایکل ایستاد، به او زل زد و فریاد زد: «برای چی؟»\r\n\r\nمرد هیکلی با چهره ای متعجب و ترسان گفت: «تام هیکل کارت استفاده رایگان داره.»\r\n\r\nپیش از اتخاذ هر اقدام و تلاشی برای حل مسائل، ابتدا مطمئن شوید که آیا اصلاً مسئله ای وجود دارد یا خیر!\r\n"},{"id":1564,"category_id":10,"category_code":"s10","source_id":126,"title":"کودک .... ","content":"کشاورزی تعدادی توله سگ ازنژادی خوب رو گذاشته بود واسه ی فروش. پســــــــر بچه ای رفت سراغش و گفــــــت: می خواهم یکی از اونا رو بخــــرم.کشاورز جواب داد که:اونا نژاد خوبی دارن و کمی گرون هســـــــتند. پســــر کوچولو پولهایی رو که\r\nتوی مشتش نگــــه داشته بود شمرد و گفت:من فقط 29سنت دارم.کشاورز سری تکون داد و گفت: متاســـــــفم پسرم اونا خیلی گرون تر از این حرفا هستند.پسرک خواهش کرد : پـس فقط اجازه بدید نگاهی بهشــون بندازم.و بعد از قبـــــــول کردن\r\nکشاورز رفـــــــــــت سراغ توله ها و چهارتا سگ کوچولوی پشمالو رو دید که با هم بازی می کردن و...\r\nبالا و پایین می پریدن .یهـو یه صدای خـــش خــــش که از لونه ی سگ ها میومد توجه اونو جلب کرد و رفت به سمتش.اونجا یه توله سگ لاغـــر رو دید که جثه اش از بقیه کوچیک تر بود و به دلیل این که یکی از پاهاش معیوب بود لنگ لنگان راه می رفت.یه دفعه چشم های پســـــــــرک برقی زد و دوان دوان رفت سراغ کشـــــاورز و گفــــــت: آقا ممکنه اونو به من بفروشین .کشــــــــاورز با تعجب\r\nپاسخ داد که: پســـــــرم اون لنــــــگه و لاغــــــر.... به سختی هم راه می ره پس نمی تونی باهاش بازی کنی.پسر کوچولو که هنوز چشم هایش می درخشــــید پاچه ی شلوارش را بالا زد و پای مصنوعیش را به کشـــــــــاورز نشون داد و گفت اون توله سگ به کسی نیاز داره که درکش کنه و اشک تموم صورتش رو پوشوند.\r\n"},{"id":1565,"category_id":10,"category_code":"s10","source_id":127,"title":"شوق و امید ","content":"روزی تصمیم گرفتم که دیگر همه چیز را رها کنم .\r\nشغلم را........دوستانم را.........زندگی ام را !\r\nبه جنگلی رفتم تا برای آخرین بار با خدا صحبت کنم .\r\nبه خدا گفتم : آیا می توانی دلیلی برای ادامه زندگی برایم بیاوری ؟\r\nو جواب او مرا شگفت زده کرد.\r\nاو گفت : آیا درخت سرخس و بامبو را می بینی؟\r\nپاسخ دادم : بلی .\r\n\r\nفرمود :\r\nهنگامی که درخت بامبو و سرخس راآفریدم، به خوبی ازآنها مراقبت نمودم .\r\nبه آنها نور و غذای کافی دادم . دیر زمانی نپایید که سرخس سر از خاک برآورد و\r\nتمام زمین را فرا گرفت اما از بامبو خبری نبود .\r\nمن از او قطع امید نکردم .\r\nدر دومین سال سرخسها بیشتر رشد کردند و زیبایی خیره کننده ای به زمین بخشیدند\r\nاما همچنان از بامبوها خبری نبود .من بامبوها را رها نکردم.\r\nدر سالهای سوم و چهارم نیز بامبوها رشد نکردند .\r\nاما من باز از آنها قطع امید نکردم.\r\nدر سال پنجم جوانه کوچکی از بامبو نمایان شد.\r\nدر مقایسه با سرخس کوچک و کوتاه بود اما با گذشت 6 ماه ارتفاع آن به بیش از 100 فوت رسید.\r\n5 سال طول کشیده بود تا ریشه های بامبو به اندازه کافی قوی شوند.\r\nریشه هایی که بامبو را قوی می ساختند و آنچه را برای زندگی به آن نیاز داشت را فراهم می کرد.\r\n\r\nخداوند در ادامه فرمود : آیا می دانی در تمامی این سالها که تو درگیر مبارزه با سختیها و\r\nمشکلات بودی در حقیقت ریشه هایت را مستحکم می ساختی .\r\nمن در تمامی این مدت تو را رها نکردم همانگونه که بامبو ها را رها نکردم .\r\nهرگز خودت را با دیگران مقایسه نکن و بامبو و سرخس دو گیاه متفاوتند\r\nاما هر دو به زیبایی جنگل کمک می کنند.\r\nزمان تو نیز فرا خواهد رسید تو نیز رشد می کنی و قد می کشی !\r\n\r\nاز او پرسیدم : من چقدر قد می کشم .\r\nدر پاسخ از من پرسید : بامبو چقدر رشد می کند؟\r\nجواب دادم : هر چقدر که بتواند .\r\nگفت : تو نیز باید رشد کنی و قد بکشی ، هر اندازه که بتوانی\r\n"},{"id":1566,"category_id":10,"category_code":"s10","source_id":128,"title":"وقتی خدا چیزی را از ما می ستاند .... ","content":"سارا دختر کوچولوی زیبا وباهوش ۵ساله ای بود که یک روز که همراه مادرش برای خرید به مغازه رفته بود چشمش به یک گردنبند مروارید بدلی افتاد .  چقدر دلش اونو می خواست.پس پیش مادرش رفت و از او خواهش کرد که اون گردنبند رو براش بخره. مادر ش گفت: این گردنبند قشنگیه اما چون قیمتش زیاده من برای خریدش واسه تو یه شرط میذارم، شرطم اینه که وقتی رسیدیم خونه من لیست کارهایی رو که میتونی انجام بدی بهت میدم وتو با انجام اون کارا می تونی پول گردنبندتو بپردازی ، سارا  قبول کرد و با زحمت بسیار تونست پول گردنبندشو بپردازه.\r\n\r\nوای که چقدر اون گردنبندو دوست داشت، همه جا اونو به گردنش مینداخت. سارا یه پدر خیلی مهربون داشت که هرشب براش قصه دلخواهشو می گفت. یه شب بعد از اتمام داستان پدرش گفت: دخترم! تو منو دوست داری؟\r\n\r\nاوه! البته پدر من عاشق توام\r\n\r\nپس اون گردنبند مرواریدتو به من بده. _ نه پدر اونو نه! اما می تونم عروسک مورد علاقه ام رو که سال پیش برای تولدم بهم هدیه دادی بهت بدم، قبوله؟....\r\n\r\nپدر : نه عزیزم ولی اشکالی نداره!\r\n\r\nهفته ی بعد دوباره پدرش بعد از خوندن داستان به دخترش گفت: دختر عزیزم تو منو دوست داری؟\r\n\r\nدختر :  البته پدر تو می دونی که من خیلی دوستت دارم و عاشق توام\r\n\r\nپدر: پس اگه راست میگی اون گردنبند مرواریدت رو به من بده \r\n\r\nدختر کوچولو : نه پدر اون نه! اما می تونم اون اسب کوچولو وصورتی ام رو بهت بدم ، اون موهاش خیلی نرمه تو میتونی اونو ببری توی باغ و باهاش بازی کنی\r\n\r\nپدر : نه عزیزم اشکالی نداره، شبت بخیر خوابهای خوب ببینی.. و او نو بوسید.\r\n\r\nچند روز بعد وقتی پدر اومد تا برای دختر کوچولویش داستان بخونه دید که دخترش روی تخت نشسته و گریه می کنه ..\r\n\r\nدخترک پدرش رو صدا کرد وگفت: پدر منو ببخش ... بیا! و دستش رو به سمت پدر برد وقتی مشتش رو باز کرد دونه های گردنبندش توی مشتش بود اونارو توی دست پدرش گذاشت. پدر با یه دست دونه های مروارید رو گرفت و با دست دیگه از جیبش یه جعبه ی بسیار زیبا در آورد که توش گردنبند مروارید اصل بود، پدرش در تمام این مدت اونو نگه داشته بود تا هر وقت دخترک از اون گردنبند بدلی دل کند، اونو بهش هدیه بده!\r\n\r\nاین مسئله درست همان کاری است که خداوند در مورد ما انجام میدهد. او منتظر می ماند تا ما از چیز های بی ارزشی که در زندگی به آن وابسته شده ایم دست برداریم تا او گنج واقعی اش را به ما بدهد...!\r\n\r\nنکته اخلاقی : بدلیجات زندگی شما چه چیزهایی هستند که سفت و سخت به آن چسبیده اید ؟!؟!\r\n"},{"id":1567,"category_id":10,"category_code":"s10","source_id":129,"title":"یک تکه کاغذ ","content":"یک روز صبح نقاش و طراح معروف انگلیسی، ویلیام والکوت می‌خواست مجموعه‌ای\r\nاز نوشته‌ها و طراحی‌های خود را درباره آسمان‌خراش‌های نیویورک،\r\nبسته‌بندی کند. برای خرید کاغذ از خانه خارج شد. اما هیچ مغازه‌ای باز\r\nنبود. به ناچار به دفتر دوستش آقای کرام که یک معمار بود رفت. او فکر کرد\r\nدر آنجا می‌تواند کمی کاغذ پیدا کند....\r\nوقتی به آنجا رسید پسربچه‌ای را دید که در حال مرتب کردن وسایل و\r\nسروسامان دادن به کاغذهای طراحی و کاغذهای بسته‌بندی بود. آقای ویلیام از\r\nپسر پرسید: آن کاغذ چیست؟ پسرک جواب داد: چیز خاصی نیست.\r\n\r\nیک تکه کاغذ بسته‌بندی!\r\n\r\nآقای والکوت به پسر گفت: هیچ چیز معمولی نیست به شرطی که بدانی چه‌طور از\r\nآن استفاده کنی. حال کمی از آن کاغذها را به من بده تا به شما نشان دهم\r\nمنظورم چیست.\r\n\r\nآقای والکوت با سرانگشتان توانمندش در عرض چند دقیقه نقشه اولیه دو\r\nآسمان‌خراش عظیم را روی کاغذها طراحی کرد که یکی از آنها بعدها به قیمت\r\n1000دلار و دیگری به قیمت 5000 دلار به فروش رفت!\r\n"},{"id":1568,"category_id":10,"category_code":"s10","source_id":130,"title":"آیا شیطان وجود دارد....؟ ","content":"آیا شیطان وجود دارد؟\r\n\r\nو آیا خدا شیطان را خلق کرد؟\r\n\r\nاستاد دانشگاه با این سوال ها شاگردانش را به یک چالش ذهنی کشاند.\r\n\r\nآیا خدا هر چیزی که وجود دارد را خلق کرد؟\r\n\r\nشاگردی با قاطعیت پاسخ داد:\"بله او خلق کرد\"\r\n\r\nاستاد پرسید: \"آیا خدا همه چیز را خلق کرد؟\"\r\n\r\nشاگرد پاسخ داد: \"بله, آقا\"\r\n\r\nاستاد گفت: \"اگر خدا همه چیز را خلق کرد, پس او شیطان را نیز خلق کرد. چون شیطان نیز وجود دارد و مطابق قانون که کردار ما نمایانگر صفات ماست , خدا نیز شیطان است\"\r\nشاگرد آرام نشست و پاسخی نداد. استاد با رضایت از خودش خیال کرد بار دیگر توانست ثابت کند که عقیده به مذهب افسانه و خرافه ای بیش نیست.\r\n\r\nشاگرد دیگری دستش را بلند کرد و گفت: \"استاد میتوانم از شما سوالی بپرسم؟\"\r\n\r\nاستاد پاسخ داد: \"البته\"\r\n\r\nشاگرد ایستاد و پرسید: \"استاد, سرما وجود دارد؟\"\r\n\r\nاستاد پاسخ داد: \"این چه سوالی است البته که وجود دارد.... آیا تا کنون حسش نکرده ای؟ \"\r\n\r\nشاگردان به سوال مرد جوان خندیدند.\r\n\r\nمرد جوان گفت: \"در واقع آقا, سرما وجود ندارد. مطابق قانون فیزیک چیزی که ما از آن به سرما یاد می کنیم در حقیقت نبودن گرماست. هر موجود یا شی را میتوان مطالعه و آزمایش کرد وقتیکه انرژی داشته باشد یا آنرا انتقال دهد. و گرما چیزی است که باعث میشود بدن یا هر شی انرژی را انتقال دهد یا آنرا دارا باشد. صفر مطلق (460- F) نبود کامل گرماست. تمام مواد در این درجه بدون حیات و بازده میشوند.. سرما وجود ندارد. این کلمه را بشر برای اینکه از نبودن گرما توصیفی داشته باشد خلق کرد.\" شاگرد ادامه داد: \"استاد تاریکی وجود دارد؟\"\r\n\r\nاستاد پاسخ داد: \"البته که وجود دارد\"\r\n\r\nشاگرد گفت: \"دوباره اشتباه کردید آقا! تاریکی هم وجود ندارد. تاریکی در حقیقت نبودن نور است. نور چیزی است که میتوان آنرا مطالعه و آزمایش کرد. اما تاریکی را نمیتوان. در واقع با استفاده از قانون نیوتن میتوان نور را به رنگهای مختلف شکست و طول موج هر رنگ را جداگانه مطالعه کرد. اما شما نمی توانید تاریکی را اندازه بگیرید. یک پرتو بسیار کوچک نور دنیایی از تاریکی را می شکند و آنرا روشن می سازد. شما چطور می توانید تعیین کنید که یک فضای به خصوص چه میزان تاریکی دارد؟ تنها کاری که می کنید این است که میزان وجود نور را در آن فضا اندازه بگیرید. درست است؟ تاریکی واژه ای است که بشر برای توصیف زمانی که نور وجود ندارد بکار ببرد.\"\r\n\r\nدر آخر مرد جوان از استاد پرسید: \"آقا، شیطان وجود دارد؟\"\r\n\r\nزیاد مطمئن نبود. استاد پاسخ داد: \"البته همانطور که قبلا هم گفتم. ما او را هر روز می بینیم. او هر روز در مثال هایی از رفتارهای غیر انسانی بشر به همنوع خود دیده میشود. او در جنایتها و خشونت های بی شماری که در سراسر دنیا اتفاق می افتد وجود دارد. اینها نمایانگر هیچ چیزی به جز شیطان نیست.\"\r\n\r\nو آن شاگرد پاسخ داد: شیطان وجود ندارد آقا. یا حداقل در نوع خود وجود ندارد. شیطان را به سادگی میتوان نبود خدا دانست. درست مثل تاریکی و سرما. کلمه ای که بشر خلق کرد تا توصیفی از نبود خدا داشته باشد. خدا شیطان را خلق نکرد... شیطان نتیجه آن چیزی است که وقتی بشر عشق به خدا را در قلب خودش حاضر نبیند. مثل سرما که وقتی اثری از گرما نیست خود به خود می آید و تاریکی که در نبود نور می آید.\r\n\r\nنام مرد جوان یا آن شاگرد تیز هوش کسی نبود جز ، آلبرت انیشتن.\r\n"},{"id":1569,"category_id":10,"category_code":"s10","source_id":131,"title":"موفقیت و سقراط ","content":"مرد جوانی از سقراط رمز موفقیت را پرسید که چیست. سقراط به مرد جوان گفت که صبح روز بعد به نزدیکی رودخانه بیاید. هر دو حاضر شدند. سقراط از مرد جوان خواست که همراه او وارد رودخانه شود. وقتی وارد رودخانه شدند و آب به زیر گردنشان رسید سقراط با زیر آب بردن سر مرد جوان، او را شگفت زده کرد.\r\n\r\nمرد تلاش می کرد تا خود را رها کند اما ....\r\nسقراط قوی تر بود و او را تا زمانی که رنگ صورتش کبود شد محکم نگاه داشت. سقراط سر مرد جوان را از آب خارج کرد و اولین کاری که مرد جوان انجام داد کشیدن یک نفس عمیق بود.\r\n\r\nسقراط از او پرسید، \" در آن وضعیت تنها چیزی که می خواستی چه بود؟\" پسر جواب داد: \"هوا\"\r\n\r\nسقراط گفت:\" این راز موفقیت است! اگر همانطور که هوا را می خواستی در جستجوی موفقیت هم باشی بدستش خواهی آورد\" رمز دیگری وجود ندارد.\r\n"},{"id":1570,"category_id":10,"category_code":"s10","source_id":132,"title":"آرزوهای عجیب یک مرد ","content":"یک بنده خدایی، کنار اقیانوس قدم میزد و زیر لب، دعایی را هم زمزمه میکرد. نگاهى به آسمان آبى و دریاى لاجوردین و ساحل طلایى انداخت و گفت :\r\n- خدایا ! میشود تنها آرزوى مرا بر آورده کنى ؟\r\nناگاه، ابرى سیاه، آسمان را پوشاند و رعد و برقى در گرفت و در هیاهوى رعد و برق، صدایى از عرش اعلى بگوش رسید که میگفت :\r\n- چه آرزویى دارى اى بنده ى محبوب من ؟\r\nمرد، سرش را به آسمان بلند کرد و ترسان و لرزان گفت :\r\n- اى خداى کریم ! از تو مى خواهم جاده اى بین کالیفرنیا و هاوایی بسازى تا هر وقت دلم خواست در این جاده رانندگى کنم !\r\nاز جانب خداى متعال ندا آمد که :\r\n- اى بنده ى من ! من ترا بخاطر وفادارى ات بسیار دوست میدارم و ...\r\nمى توانم خواهش ترا بر آورده کنم، اما، هیچ میدانى انجام تقاضاى تو چقدر دشوار است ؟ هیچ میدانى که باید فرمان دهم تا فرشتگانم ته ى اقیانوس آرام را آسفالت کنند ؟ هیچ میدانى چقدر آهن و سیمان و فولاد باید مصرف شود ؟ من همه ى اینها را مى توانم انجام بدهم، اما، آیا نمى توانى آرزوى دیگرى بکنى ؟\r\nمرد، مدتى به فکر فرو رفت، آنگاه گفت :\r\n- اى خداى من! من از کار زنان سر در نمى آورم ! میشود بمن بفهمانى که زنان چرا می گریند؟ میشود به من بفهمانى احساس درونى شان چیست ؟ اصلا میشود به من یاد بدهى که چگونه مى توان زنان را خوشحال کرد؟\r\nصدایی از جانب باریتعالى آمد که : اى بنده من ! آن جاده اى را که خواسته اى، دو باندى باشد یا چهار باندى؟\r\n"},{"id":1571,"category_id":10,"category_code":"s10","source_id":133,"title":"نامه آبراهام لینکلن به معلم پسرش ","content":"به پسرم درس بدهید.\r\nاو باید بداند که همه مردم عادل و همه آن ها صادق نیستند، اما به پسرم بیاموزید که به ازای هر شیاد، انسان صدیقی هم وجود دارد. به او بگوییدبه ازای هر سیاستمدار خودخواه، رهبر جوانمردی هم یافت می شود. به او بیاموزید، که در ازای هر دشمن، دوستی هم هست. می دانم که وقت می گیرد، اما به او بیاموزید اگر با کار و زحمت خویش، یک دلار کاسبی کند بهتر از آن است که جایی روی زمین پنج دلار بیابد. به او بیاموزید که از باختن پند بگیرد. از پیروز شدن لذت ببرد. او را از غبطه خوردن بر حذر دارید. به او نقش و تاثیر مهم خندیدن را یادآور شوید.\r\n....\r\nاگر می توانید، به او نقش موثر کتاب در زندگی را آموزش دهید. به او بگویید تعمق کند، به پرندگان در حال پرواز در دل آسمان دقیق شود. به گل های درون باغچه و زنبورها که در هوا پرواز می کنند، دقیق شود. به پسرم بیاموزید که در مدرسه بهتر این است که مردود شود اما با تقلب به قبولی نرسد. به پسرم یاد بدهید با ملایم ها، ملایم و با گردن کش ها، گردن کش باشد. به او بگویید به عقایدش ایمان داشته باشد حتی اگر همه بر خلاف او حرف بزنند. به پسرم یاد بدهید که همه حرف ها را بشنود و سخنی را که به نظرش درست می رسد انتخاب کند.\r\n\r\nارزش های زندگی را به پسرم آموزش دهید. اگر می توانید به پسرم یاد بدهید که در اوج اندوه تبسم کند.  به او بیاموزید که از اشک ریختن خجالت نکشد. به او بیاموزید که می تواند برای فکر و شعورش مبلغی تعیین کند، اما قیمت گذاری برای دل بی معناست. به او بگویید که تسلیم هیاهو نشود و اگر خود را بر حق می داند پای سخنش بایستد و با تمام قوا بجنگد. در کار تدریس به پسرم ملایمت به خرج دهید اما از او یک نازپرورده نسازید. بگذارید که او شجاع باشد، به او بیاموزید که به مردم اعتقاد داشته باشد توقع زیادی است اما ببینید که چه می توانید بکنید. پسرم کودک کم سال بسیار خوبی است.\r\n"},{"id":1572,"category_id":10,"category_code":"s10","source_id":134,"title":"پهلوان رَضو","content":"دلشوره عجیبی داشت. کمی هم تار می دید ولی مجبور بود. نگاهی به جمعیت\r\nانداخت. گوی را که بلند کرد ، سنگین تر از همیشه به نظر رسید . وقتی آن\r\nرا به هوا پرتاب کرد تا با شانه اش آن را پرتاب کند ، دو گوی در هوا دید\r\nو جا خالی داد. صدای خنده جمعیت بلند شد.\r\nآبی به سر و رویش زد. مرشد معرکه با صدای بلند گفت : اگر خسته جانی بگو\r\nیا علی ، اگر ناتوانی بگو یا علی . مردم دوباره سکوت کردند. زنجیر دو\r\nمتری را دور بازو هایش پیچید. چندین بار با فریاد زورِ نمایشی زد. دویست\r\nتومنش کمه . یه جوون مرد دویست  تومن بذاره تو سینی . صد تومنش خرج زن و\r\nبچه ، صد تومنش خرج کبوتر حرم . آخرین سکه ها و اسکناس ها روی سینی ولو\r\nشدند. دیگر موقع پاره کردن زنجیر بود. پهلوان رَضو با فریادی بلند سعی\r\nکرد زنجیر را پاره کند،  ولی زنجیر پاره نشد...\r\n دوباره تلاش کرد. رگ های\r\nگردنش متورم شده بودند. بدنش میلرزید . عرق سردی روی پیشانی اش نسشته بود\r\nولی حلقه های زنجیر  ظاهراٌ دست به یکی کرده بودند تا این بار آنها در\r\nمقابل پهلوان قدرت نمایی کنند. احساس کرده بود که دارد تمام می شود ، ولی\r\nفکر نمی کرد به این زودی ، آنهم جلوی مردم. نگاهی به آسمان کرد. زیر لب\r\nچیزی زمزمه کرد . با فریاد یا علی خم شد و تمام قدرتش را در بازوانش جمع\r\nکرد و دیگر چیزی نفهمید.\r\nچشم هایش را که باز کرد ، روی تخت بیمارستان بود. دکتر داشت با دامادش\r\nصحبت می کرد: سه تا از رگهای قلبش پاره شدن . من نمی دونم چطور بعد از\r\nسکته تونست زنجیر رو پاره کنه . به هر حال به خیر گذشت. ولی دیگه نمی\r\nتونه معرکه بگیره . لبخندی زد و آهسته زیر لب گفت : یا علی...\r\n"},{"id":1573,"category_id":10,"category_code":"s10","source_id":135,"title":"زیرکی مادرانه ... ","content":"خانم حمیدی برای دیدن پسرش مسعود ، به محل تحصیل او یعنی لندن آمده بود . او در آنجا متوجه شد که پسرش با یک هم اتاقی دختر بنام ویکی زندگی می کند. کاری از دست خانم حمیدی بر نمی آمد و از طرفی هم اتاقی مسعود هم خیلی خوشگل بود. او به رابطه میان آن دو ظنین شده بود و این موضوع باعث کنجکاوی بیشتر او می شد. مسعود که فکر مادرش را خوانده بود گفت :...\r\n\" من می دانم که شما چه فکری می کنید ، اما من به شما اطمینان می دهم که من و ویکی فقط هم اتاقی هستیم . \" \r\nحدود یک هفته بعد ، ویکی پیش مسعود آمد و گفت : \" از وقتی که مادرت از اینجا رفته ، قندان نقره ای من گم شده ، تو فکر نمی کنی که او قندان را برداشته باشد ؟ \" \r\n\" خب ، من شک دارم ، اما برای اطمینان به او ایمیل خواهم زد . \" \r\n\r\nاو در ایمیل خود نوشت : \r\nمادر عزیزم، من نمی گم که شما قندان را از خانه من برداشتید، و در ضمن نمی گم که شما آن را برنداشتید . اما در هر صورت واقعیت این است که قندان از وقتی که شما به تهران برگشتید گم شده . \" \r\n\r\nبا عشق، مسعود \r\n\r\nروز بعد ، مسعود یک ایمیل به این مضمون از مادرش دریافت نمود : \r\n\r\nپسر عزیزم ، من نمی گم تو با ویکی رابطه داری ! ، و در ضـــمن نمی گم که تو باهاش رابطه نداری . اما در هر صورت واقعیت این است که اگر او در تختخواب خودش می خوابید ، حتما تا الان قندان را پیدا کرده بود . \r\n\r\nبا عشق ، مامان\r\n"},{"id":1574,"category_id":10,"category_code":"s10","source_id":136,"title":"قدرت حافظه ","content":"خردمند پیری در دشتی پوشیده از برف قدم می زد که به زن گریانی رسید.\r\nپرسید: چرا می گریی؟\r\n- چون به زندگی ام می اندیشم, به جوانی ام, به زیبایی ای که در آینه می دیدم, و به مردی که دوستش داشتم. خداوند بی رحم است که قدرت حافظه را به انسان بخشیده است. می دانست که\r\nمن بهار عمرم را به یاد می آورم و می گریم. خردمند در میان دشت برف آگین ایستاد, به نقطه ای خیره شد و به فکر فرو رفت.\r\n\r\nزن از گریستن دست کشید و پرسید: در آن جا چه می بینید؟\r\nخردمند پاسخ داد: دشتی از گل سرخ. خداوند, آن گاه که قدرت حافظه را به من می بخشید, بسیار سخاوتمند بود. می دانست در زمستان, همواره می توانم بهار را یه یاد آورم و لبخند بزنم.\r\n"},{"id":1575,"category_id":10,"category_code":"s10","source_id":137,"title":"حکایت یک مشهدی .... ","content":"می گوید در اون سال ها سرباز بگیری بود و من رو بردند به سرباز خونه ای در مشهد… \r\n\r\nهنوز ۴۵ روز نگذشته بود، که دلم برای خانواده ام تنگ شد.\r\n\r\nاما مرخصی ندادن ،منم بدون مرخصی و پای پیاده، از مشهد تا طرقبه ( ۱۸ کیلومتر ) دویدم و بعد از دیدن خانواده، دوباره از طرقبه تا مشهد را دویدم و رفتم پادگان …\r\n\r\nپادگان، که رسیدم دیدم گروهبان متوجه غیبت من و چند نفر دیگه شده ، که همه رو به خط کرد و گفت دور پادگان رو باید بدوید …\r\n\r\nشروع به دویدن که کردیم بعد از 1000 متر سرباز های دیگه خسته شدند، اما من دور کامل دویدم و ایستادم…!\r\n\r\nفرمانده ی گروهان که دویدن من رو ندیده بود، گفت مگه نگفتم دور کامل باید بدوی  \r\n\r\nگفتم دویدم قربان …\r\n\r\nگفت فضولی موقوف ..!\r\n\r\nدوباره باید بدوی…!\r\n\r\nخلاصه، دو دور دیگه به مسافت 8 کیلومتر دویدم و سر حال، جلوی فرمانده ایستادم و همین باعث شد مسیر زندگی ام تغییر کند…!\r\n\r\nیک روز، من رو با یک جیپ ارتشی به میدان سعد آباد مشهد بردند ، برای مسابقه…\r\n\r\nرییس تربیت بدنی تا من رو دید، گفت:\r\n\r\nچرا کفش و لباس ورزشی نپوشیدی؟\r\n\r\nگفتم:\r\n\r\nندارم …!\r\n\r\nگفت :\r\n\r\nخوب برو سر خط الان مسابقه شروع می شه ببینم چند مرده حلاجی ؟\r\n\r\nخلاصه با پوتین و لباس سربازی دویدم و دور اخر همه داد می زدن باریکلا سرباز …\r\n\r\nبرنده که شدم دیدم همه می گن سرباز رکورد ایران رو شکستی …!\r\n\r\nمن اون روز با پوتین و لباس سربازی رکورد ایران رو شکستم و بهم کاپ نقره ای دادن…!\r\n\r\nخبر رکورد شکنی من خیلی زود، به مرکز رسید و بهم امریه دادن تا برم تهران …\r\n\r\nبا اتوبوس به تهران رفتم و پرسان پرسان، خودم رو به دژبانی مرکز رسوندم و با فرمانده ی لشگر که روبرو شدم، گفت:\r\n\r\nتو همون سربازی هستی که با پوتین رکورد شکستی؟\r\n\r\nگفتم :\r\n\r\nبله قربان …\r\n\r\nگفت:\r\n\r\nچرا این قدر دیر امدی و سریع من رو سوار ماشین کردند و به استادیوم امجدیه بردن، که قرار بود مسابقه بزرگی انجام بشه …!\r\n\r\nمسابقه ی دوی ۵۰۰۰ متر بود و من کفش و لباسی رو که رییس تربیت بدنی مشهد داده بود، پوشیدم و رفتم لب خط…!\r\n\r\nیک دفعه صدای تیری شنیدم و هراسناک این طرف اون طرف رو نگاه کردم ببینم چه خبره ؟ که دیدم رییس تربیت بدنی با عصبانیت می گه چرا نمیدوی؟\r\n\r\nبدو..!\r\n\r\nمن نگاه کردم، دیدم، که اون و 17 نفر دیگه، مسافتی از من دور شدن و من تازه فهمیدم ،که صدای شلیک تیر برای اغاز مسابقه بوده و من چون در مشهد فقط با صدای حاضر رو ) مسابقه رو شروع می کردم اینجا هم منتظر همون کلمه بودم ،نه صدای تیر …\r\n\r\nخلاصه شروع کردم به دویدن و یه عده هم من رو هو می کردن و می گفتن:\r\n\r\nمشهدی تو از اخر اولی …!\r\n\r\nدور سوم رو که دویدم تازه به نفر اخر رسیدم و تازه گرم شده بودم …!\r\n\r\nدر دور بعد متوجه شدم، که نفر چهارم هستم و با خودم گفتم:\r\n\r\nخدا رو شکر لااقل چهارم می شم…!\r\n\r\nسه دور تا اخر مسابقه مانده بود، که دیدم فقط یک نفر با فاصله از من جلوتره…!\r\n\r\nدور اخر خودم رو به پشت سرش رسوندم…\r\n\r\nبه خط پایان نزدیک می شدیم که جلو زدم و اول شدم …!\r\n\r\nباز هم رکورد ایران رو شکسته بودم و از عزیز منفرد، که سال ها قهرمان ایران بود جلو زده بودم…!\r\n\r\nاین ها حرف های استاد علی باغبان باشی، قهرمان دوی ایران است، که ۲۹ سال متوالی بدون حتی یک باخت، مقام نخست مسابقات را در ایران داراست و جالب است، بدانید که تا به حال این رکورد در هیچ رشته ی ورزشی در دنیا شکسته نشده…!\r\n\r\nباغبان باشی ۲۱۹ مدال اسیایی و جهانی دارد و در 8 مسابقه ی المپیک شرکت کرده و اول شده!\r\n\r\nادیب زاده می گوید:\r\n\r\nزمان شاه شنیدم ،که پای باغبان باشی شکسته …!\r\n\r\nبا گروه فیلم برداری رفتیم و وقتی با اون مصاحبه کردم با ناراحتی گفت:\r\n\r\nدکتر ها گفته اند باید یک پای من رو قطع کنند …\r\n\r\nشب، که فیلم پخش شد ۵۰ خط تلفن جام جم توسط مردم اِشغال شده بود و همه با عصبانیت می خواستن یه جوری به علی باغبان باشی کمک کنن …\r\n\r\nهمون شب، رضا پهلوی، که در اون زمان ولیعهد بود و نزدیک به ۱۷ سال داشت، به آقای جهان بانی، رییس سازمان ورزش (‌که اوایل انقلاب اعدام شد) دستوری داده بود، که او هم شبانه به در خانه ی باغبان باشی رفته بود و پاسپورتش را درست کرده بودند و روز بعد ساعت ۱۱ صبح از فرودگاه زنگ زد که :\r\n\r\nمثل این‌که معجزه شده و من برای درمان به نیویورک می‌روم.\r\n\r\nدر نیویورک پایش را یک پروفسور بزرگ عمل کرد، بعد از دو ماه، که برگشت از همان فرودگاه مهرآباد به ما زنگ زد، که من می‌خواهم به زودی در یک مسابقه‌ی دو و میدانی شرکت کنم و شما را هم دعوت می‌کنم.\r\n\r\n \r\n\r\nباغبان باشی، اکنون ۸۴ سال سن دارد و هنوز فعالیت ورزشی می کند …!\r\n\r\nاخرین باری، که باغبان باشی را دیدم، دور میدان دروازه قوچان بود؛ به گرمی حال و احوال کردم و او گفت:\r\n\r\nشما مگه من رو می شناسی؟\r\n\r\nلبخندی زدم و گفتم :\r\n\r\nتمام دنیا شما رو می شناسن…!\r\n\r\nباغبان باشی، هنوز در طرقبه زندگی می کند و روحیه ی شاد و ورزش کاری دارد …\r\n"},{"id":1576,"category_id":10,"category_code":"s10","source_id":138,"title":"پس از مرگ","content":"سه دوست در یک اتومبیل به مسافرت رفته بودند و متاسفانه یک تصادف مرگبار باعث شد که هر سه در جا کشته شوند یک لحظه بعد روح هر سه دم دروازه بهشت بود و فرشته نگهبان بهشت داشت آماده می شد که آنها را به بهشت راه دهد.\r\nیک سوال؟!!\r\n\r\n_ الان که هر سه تا دارین وارد بهشت می شین اونجا روی زمین بدن هاتون روی برانکارد در حال تشییع شدن بسوی قبرستان است و خانواده ها و دوستان در حال عزاداری در غم از دست دادن شما هستند دوست دارین وقتی دارن از کنار جنازه راه می رن در مورد شما چی بگن؟\r\n\r\nاولی گفت : دوست دارم پشت سرم بگن که من جز بهترین پزشکان زمان خود بودم و مرد بسیار خوب و عزیزی برای خانواده ام.\r\n\r\nدومی گفت : دوست دارم پشت سرم بگن که من جز بهترین معلم های زمان خود بودم و توانسته ام اثر بسیار بزرگی روی آدمهای نسل بعد از خودم بگذارم.\r\n\r\nسومی گفت : دوست دارم بگن : نگاه کن داره تکون می خوره مثل اینکه زنده است!\r\n"},{"id":1577,"category_id":10,"category_code":"s10","source_id":139,"title":"عروس و مادر شوهر ","content":"دختری بعد از ازدواج نمی توانست با مادرشوهرش کنار بیاید و هر روز با او جر و بحث می کرد.\r\nعاقبت دختر نزد داروسازی که دوست صمیمی پدرش بود رفت و از او تقاضا کرد سمی به او بدهد تا بتواند مادر شوهرش را بکشد!\r\n\r\nداروساز گفت اگر سم خطرناکی به او بدهد و مادرشوهرش بمیرد،همه به او شک خواهند کرد،پس معجونی به دختر داد و گفت که هر روز مقداری از آن را در غذای مادرشوهر بریزد ....\r\nتا سم معجون کم کم در او اثر کند و او را بکشد و توصیه کرد در این مدت با مادرشوهر مدارا کند تا کسی به او شک نبرد.\r\n\r\nدختر معجون را گرفت و خوشحال به خانه برگشت و هر روز مقداری از آن را در غذای مادرشوهر می ریخت و با مهربانی به او می داد.\r\n\r\nهفته ها گذشت و با مهر و محبت عروس،اخلاق مادرشوهر هم بهتر و بهتر شد تا آن جا که یک روز دختر نزد داروساز رفت و به او گفت : دیگر از مادرشوهرم متنفر نیستم. حالا او را مانند مادرم دوست دارم و دیگر دلم نمی خواهد که بمیرد، خواهش می کنم داروی دیگری به من بدهید تا سم را از بدنش خارج کند.\r\n\r\nداروساز لبخندی زد و گفت : دخترم، نگران نباش. آن معجونی که به تو دادم سم نبود بلکه سم در ذهن خود تو بود که حالا با عشق به مادرشوهرت از بین رفته است.\r\nبرای پیروزی ابلیس کافی است آدمهای خوب دست روی دست بگذارند.\r\n"},{"id":1578,"category_id":10,"category_code":"s10","source_id":140,"title":"مرخصی از همسر ","content":"می گویند در دوران قبل که پاسگاه های ژاندارمری در مناطق مرزی و روستایی و دور از شهرها وجود داشته و اکثرا ماموران مستقر در آنها از نقاط دیگر برای خدمت منتقل می شدند باید مدت زیادی را دور از اقوام و بستگان سپری می کردند کما \r\nاینکه سفر و رفت وآمد به سهولت فعلی نبوده شاید بعضی مواقع حتی در طول سال هم امکانی برای مسافرت ماموران به شهر موطن خود پیش نمی آمد و به همین خاطر معدود خانه سازمانی در اختیار فرمانده پاسگاه و برخی ماموران دیگر قرار می گرفت.همسر یکی از فرماندهان پاسگاه که به تازگی هم ازدواج کرده و چندین ماه از زندگیشان ....\r\nدور از شهر و بستگان در منطقه خدمت همسرش می گذشت بدجوری دلتنگ خانواده پدری اش شده بود چندین بار از شوهرش درخواست می کند که برای دیدن پدر ومادرش به شهرشان به اتفاق هم یا به تنهایی مسافرت کند ولی هر بار شوهرش  به بهانه ای از زیر بار موضوع شانه خالی می کند. زن که در این مدت با چگونگی برخورد ماموران زیر دست شوهرش و بعضا مکاتبات آنها برای گرفتن مرخصی و غیره هم کم و وبیش آشنا شده بود به فکر می افتد حالا که همسرش به خواسته وی اهمیتی قائل نمیشود او هم به صورت مکتوب و به مانند ماموران درخواست مرخصی برای رفتن و دیدن خانواده اش بکند پس دست به کار شده و در کاغذی درخواست کتبی به این شرح می نویسد: \r\n\" جناب ..... \r\nفرمانده محترم ... \r\nاینجانب .... همسر حضرتعالی که مدت چندین ماه است پس از ازدواج با شما دور از خانواده و بستگان خود هستم حال که شما بدلیل مشغله بیش از حد کاری فرصت سفر و دیدار بستگان را ندارید بدینوسیله درخواست دارم که با مرخصی اینجانب به مدت .... برای مسافرت و دیدن پدر ومادر واقوام موافقت فرمائید.\" \r\n\"  با احترام ..... همسر شما \" \r\nو نامه را در پوشه مکاتبات همسرش می گذارد. \r\nچند وقت بعد جواب نامه به این مضمون بدستش میرسد: \r\n*سرکار خانم... \r\nعطف به درخواست مرخصی سرکار عالی جهت سفر برای دیدار اقوام *با درخواست شما به شرط تامین جانشین موافقت میشود.\"* \r\nفرمانده ... \r\nخودتان می توانید حدس بزنید که همسر بیچاره با دیدن این جواب قید مسافرت و \r\nدیدن پدرو مادر را زده ماندن در همان محل خدمت شوهر رضایت می دهد. \r\n"},{"id":1579,"category_id":10,"category_code":"s10","source_id":141,"title":"زشت ترین و زیباترین زن دنیا ","content":"مردی تعریف می کرد که با دو دوستش به جنگل های آمازون رفته بود و در آنجا گرفتار قبیله زنان وحشی شدند و آنها دو دوستش را کشتند.\r\nوقتی از او پرسیدند چرا تو زنده ماندی، گفت: زن های وحشی آمازون از هر یک از ما خواستند بعنوان آخرین خواسته و وصیت چیزی را از آنها بخواهیم تا برای هریک از ما انجام بدهند.\r\n\r\nهریک از دوستانم تقاضاهای خود را گفتند و آنان خواسته های دو دوستم را انجام دادند وسپس آنها را کشتند.\r\n\r\nوقتی نوبت به من رسید بسیار وحشت زده و ترسیده بودم....\r\nکه ناگهان فکری به خاطرم رسید و به آنها گفتم:\r\n\r\nآخرین خواسته من در زندگی این است که لطفا زشت ترین شما مرا بکشد!\r\n\r\n\r\nنتیجه اخلاقی : زشت ترین زن دنیا وجود خارجی نداره بخصوص با تکنولوژیهای پزشکی امروزی که بعضا لولو تحویل گرفته و هلو ...\r\n"},{"id":1580,"category_id":10,"category_code":"s10","source_id":142,"title":"گوهر و گردو ","content":"می گویند کشاورزی افریقایی در مزرعه اش زندگی خوب و خوشی را با همسر و فرزندانش داشت. یک روز شنید که در بخشی از افریقا معادن الماسی کشف شده اند و مردمی که به آنجا رفته اند ، با کشف الماس به ثروتی افسانه ای دست یافته اند .\r\n\r\nاو که از شنیدن این خبر هیجان زده شده بود ، تصمیم گرفت برای کشف معدنی الماس به آنجا برود. بنابر این زن و فرزندانش را به دوستی سپرد و مزرعه اش را فروخت و عازم سفر شد .\r\n\r\nاو به مدت ده سال افریقا را زیر پا می گذارد و عاقبت...\r\nبه دنبال بی پولی ، تنهایی و یاس و نومیدی خود را در اقیانوس غرق می کند .\r\n\r\nاما زارع جدیدی که مزرعه را خریده بود ، روزی در کنار رودخانه ای که از وسط مزرعه میگذشت ، چشمش به تکه سنگی افتاد که درخشش عجیبی داشت . او سنگ را برداشت و به نزد جواهر سازی برد . مرد جواهر ساز با دیدن سنگ گفت که آن سنگ الماسی است که نمی توان قیمتی بر آن نهاد.\r\n\r\nمرد زارع به محلی که سنگ را پیدا کرده بود رفت و متوجه شد سرتاسر مزرعه پر از سنگهای الماسی است که برای درخشیدن نیاز به تراش و صیقل داشتند.\r\n\r\nمرد زارع پیشین بدون آنکه زیر پای خود را نگاه کند ، برای کشف الماس تمام افریقا را زیر پا گذاشته بود ، حال آنکه در معدنی از الماس زندگی می کرد !\r\n"},{"id":1581,"category_id":10,"category_code":"s10","source_id":143,"title":"خانم ها باهوش ترینند .... ","content":"خانمی در زمین گلف مشغول بازی بود. ضربه ای به توپ زد که باعث پرتاب توپ به درون بیشه زار کنار زمین شد. خانم برای پیدا کردن توپ به بیشه زار رفت که ناگهان با صحنه ای روبرو شد.\r\n\r\nقورباغه ای در تله ای گرفتار بود. قورباغه حرف می زد! رو به خانم گفت؛ اگر مرا از بند آزاد کنی، سه آرزویت را برآورده می کنم.\r\n\r\nخانم ذوق زده شد و سریع قورباغه را آزاد کرد. قورباغه به او گفت؛ نذاشتی شرایط برآورده کردن آرزوها را بگویم. هر آرزویی که برایت برآورده کردم، ۱۰ برابر آنرا برای همسرت برآورده می کنم!\r\n\r\nخانم کمی تامل کرد و گفت؛ ....\r\nمشکلی ندارد. آرزوی اول خود را گفت؛ من می خواهم زیباترین زن دنیا شوم. قورباغه به او گفت؛ اگر زیباترین شوی شوهرت ۱۰ برابر از تو زیباتر می شود و ممکن است چشم\r\n\r\nزن های دیگر بدنبالش بیافتد و تو او را از دست دهی. خانم گفت؛ مشکلی ندارد. چون من زیباترینم، کس دیگری در چشم او بجز من نخواهم ماند. پس آرزویش برآورده شد.\r\n\r\nبعد گفت که من می خواهم ثروتمند ترین فرد دنیا شوم. قورباغه به او گفت شوهرت ۱۰ برابر ثروتمند تر می شود و ممکن است به زندگی تان لطمه بزند.\r\n\r\nخانم گفت؛ نه هر چه من دارم مال اوست و آن وقت او هم مال من است. پس ثروتمند شد. آرزوی سومش را که گفت قورباغه جا خورد و بدون چون و چرایی برآورده کرد.\r\n\r\nخانم گفت؛ می خواهم به یک حمله قلبی خفیف دچار شوم!\r\n\r\nنکته اخلاقی: خانم ها خیلی باهوش\r\nهستند. پس باهاشون درگیر نشین.\r\n"},{"id":1582,"category_id":10,"category_code":"s10","source_id":144,"title":"ابلیس","content":"مردی کنار بیراهه ای ایستاده بود.\r\nابلیس را دید که با انواع طنابها به دوش درگذر است.\r\nکنجکاو شد و پرسید: ای ابلیس ، این طنابها برای چیست؟\r\nجواب داد: برای اسارت آدمیزاد.\r\nطنابهای نازک برای افراد ضعیف النفس و سست ایمان ،\r\nطناب های کلفت هم برای آنانی که دیر وسوسه می شوند.\r\nسپس از کیسه ای طناب های پاره شده را بیرون ریخت و گفت:\r\nاینها را هم انسان های باایمان که راضی به رضای خدایند و اعتماد به نفس داشتند، پاره کرده اند و اسارت را نپذیرفتند.\r\nمرد گفت طناب من کدام است ؟\r\nابلیس گفت : اگر کمکم کنی که این ریسمان های پاره را گره زنم،\r\nخطای تو را به حساب دیگران می گذارم ...\r\nمرد قبول کرد .\r\nابلیس خنده کنان گفت :\r\nعجب ، با این ریسمان های پاره هم می شود انسان هایی چون تو را به بندگی گرفت...!\r\n"},{"id":1583,"category_id":10,"category_code":"s10","source_id":145,"title":"رسم عشق ","content":"جوانی چند روز قبل از عروسی آبله سختی گرفت و بستری شد...  نامزد وی به عیادتش رفت و در میان صحبتهایش از درد چشم خود نالد بیماری زن شدت گرفت و آبله تمام صورتش را پوشاند...مرد جوان عصازنان به عیادت نامزدش می رفت و از درد چشم مینالید.موعد عروسی فرا رسید زن نگران صورت خود ....\r\nکه آبله آنرا از شکل انداخته بود وشوهراو هم کور شده بود مردم میگفتند چه خوب عروس نازیبا همان بهتر که شوهرش نابینا باشد... 20 سال بعد از ازدواج زن از دنیا رفت،مرد عصایش را کنار گذاشت و چشمانش را گشود... همه تعجب کردند... مرد گفت: من کاری جز شرط عشق را به جا نیاوردم.\r\n"},{"id":1584,"category_id":10,"category_code":"s10","source_id":146,"title":"فرشته نگهبان ","content":"مرد داشت در خیابان حرکت می کرد که ناگهان صدایی از پشت گفت:\r\n- اگر یک قدم دیگه جلو بری کشته می شی .. \r\nمرد ایستاد و در همان لجظه اجری از بالا افتاد جلوی پاش.مرد نفس راحتی کشید و با تعجب دوروبرشو نگاه کرد اما کسی رو ندید .بهر حال نجات پیدا کرده بود . به راهش ادامه داد .به محض اینکه می خواست از خیابان رد بشه باز همان صدا گفت : ....\r\n- ایست \r\nمرد ایستاد و در همان لحظه ماشینی با سرعت عجیبی از جلویش رد شد .بازم نجات پیدا کرد .مرد پرسید تو کی هستی و صدا جواب داد من فرشته نگهبان تو هستم . مرد فکری کرد و گفت : \r\n-پس اون موقعی که من داشتم ازدواج می کردم تو کدوم گوری بودی؟!!!\r\n"},{"id":1585,"category_id":10,"category_code":"s10","source_id":147,"title":"وقت شناس باشید ","content":"در مراسم تودیع پدر پابلو، کشیشی که ۳۰ سال در کلیسای شهر کوچکی خدمت کرده و بازنشسته شده بود، از یکی‌ از سیاستمداران اهل محل برای سخنرانی دعوت شده بود.\r\nدر روز موعود، مهمان سیاستمدار تاخیر داشت و بنابرین کشیش تصمیم گرفت کمی‌ برای مستمعین صحبت کند.\r\nپشت میکروفن قرار گرفته و گفت: ۳۰ سال قبل وارد این شهر شدم.\r\nانگار همین دیروز بود.\r\nراستش را بخواهید، اولین کسی‌ که برای اعتراف وارد کلیسا شد، مرا به وحشت انداخت.\r\nبه دزدی هایش، باج گیری، رشوه خواری، هوس رانی‌.....\r\nزنا با محارم و هر گناه دیگری که تصور کنید اعتراف کرد.\r\nآن روز فکر کردم که جناب اسقف اعظم مرا به بدترین نقطه زمین فرستاده است ولی‌ با گذشت زمان و آشنایی با بقیه اهل محل دریافتم که در اشتباه بوده‌ام و این شهر مردمی نیک دارد.\r\n\r\nدر این لحظه سیاستمدار وارد کلیسا شده و از او خواستند که پشت میکروفن قرار گیرد.\r\nدر ابتدا از اینکه تاخیر داشت عذر خواهی‌ کرد و سپس گفت که به یاد دارد که زمانیکه پدر پابلو وارد شهر شد، او اولین کسی‌ بود که برای اعتراف مراجعه کرد.\r\n\r\nنتیجه اخلاقی‌: وقت شناس باشید !\r\n"},{"id":1586,"category_id":10,"category_code":"s10","source_id":148,"title":"حکایتی از عبید زاکانی ","content":"خواب دیدم قیامت شده است. \r\n\r\n هرقومی را داخل چاله‏ای عظیم انداخته و بر سرهر چاله نگهبانانی گرز به دست گمارده بودند الا چاله‏ی ایرانیان.\r\n\r\nخود را به عبید زاکانی رساندم و پرسیدم: «عبید این چه حکایت است که بر ما اعتماد کرده نگهبان نگمارده‏اند؟»\r\n \r\nگفت:....\r\n«می‌دانند که به خود چنان مشغول شویم که ندانیم در چاهیم یا چاله.»\r\n\r\nخواستم بپرسم: «اگر باشد در میان ما کسی که بداند و عزم بالا رفتن کند...»\r\n\r\nنپرسیده گفت: گر کسی از ما، فیلش یاد هندوستان کند خود بهتر از هر نگهبانی پایش کشیم و به تهِ چاله باز گردانیم!\r\n"},{"id":1587,"category_id":10,"category_code":"s10","source_id":149,"title":"زرنگتر از اصفهانیهای عزیز ","content":"چند شب پیش در میان مریض ها منشی ام وارد شد گفت یک آقایی که ماهی بزرگی در دست دارد آمده است و می خواهد شما را ملاقات کند. \r\nیک مرد میانسال با یک لهجه شدید رشتی وارد شد و در حالی که یک ماهی حدودا ده کیلویی دریک کیسه نایلون بزرگ در دستش بود و شروع کرد به تشکر کردن که من عموی فلان کس هستم و شما جان او را نجات دادی و خلاصه این ماهی تحفه ناقابلی است و ... \r\nهر چه فکر کردم \"فلان کس\" را به یاد نیاوردم ولی ماهی را گرفتم و از او تشکر کردم. \r\nشب ماهی را به خانه بردم و زنم شروع به غرغر کرد که من ماهی پاک نمی کنم! خودمتا نصف شب نشستم و ...\r\nماهی را تمیز کردم و قطعه قطعه نموده و در فریزر گذاشتم. \r\nفردا عصر وارد مطب که شدم دیدم همان مرد رشتی ایستاده است و بسیار مضطرب است. \r\nتا مرا دید به طرفم دوید و گفت آقای دکتر دستم به دامنت...ماهی را پس بده.........من باید این ماهی را به فلان دکتر بدهم اشتباهی به شما دادم...چرا شما به من نگفتی که آن دکتر نیستی و برادرزاده مرا نمی شناسی؟ \r\n\r\nمن که در سالن و جلوی سایر بیماران یکه خورده بودم با دستپاچگی گفتم که ماهی ات الآن در فریزر خانه ماست. \r\nاو هم با ناراحتی گفت: پس پولش را بدهید تا برای دکترش یک ماهی دیگر بخرم. \r\nو من با شرمساری هفتاد هزار تومان به او پرداختم. \r\nچند روز بعد متوجه شدم که ماجرای مشابهی برای تعدادی از همکارانم رخ داده است و ظاهرا آن مرد رشتی یک وانت ماهی به اصفهان آورده و به پزشکان اصفهانی انداخته است!\r\n"},{"id":1588,"category_id":10,"category_code":"s10","source_id":150,"title":"محبت چه کارها که نمی کند...","content":"سالها پیش '' در کشور آلمان '' زن و شوهری زندگی می کردند.آنها هیچ گاه صاحب فرزندی نمی شدند.یک روز که برای تفریح به اتفاق هم از شهر خارج شده و به جنگل رفته بودند '' ببر کوچکی در جنگل '' نظر آنها را به خود جلب کرد.مرد معتقد بود : نباید به آن بچه ببر نزدیک شد.به نظر او ببرمادر جایی در همان حوالی فرزندش را زیر نظر داشت.پس اگر احساس خطر می کرد به هر دوی آنها حمله می کرد و صدمه می زد.اما زن انگار هیچ یک از جملات همسرش را نمی شنید '' خیلی سریع به سمت ببر رفت و بچه ببر را زیر پالتوی خود به آغوش کشید '' دست همسرش را گرفت و گفت :عجله کن!ما باید همین الآن سوار اتوموبیلمان شویم و از اینجا برویم.آنها به آپارتمان خود باز گشتند و به این ترتیب ببر کوچک '' عضوی از ا عضای این خانواده ی کوچک شد و آن دو با یک دنیا عشق و علاقه به ببر رسیدگی می کردند. سالها از پی هم گذشت و ببر کوچک در سایه ی مراقبت و محبت های آن زن و شوهر حالا تبدیل به ببر بالغی شده بود که با آن خانواده بسیار مانوس بود.در گذر ایام '' مرد درگذشت و ...\r\nمدت زمان کوتاهی پس از این اتفاق '' دعوتنامه ی کاری برای یک ماموریت شش ماهه در مجارستان به دست آن خانم رسید.زن '' با همه دلبستگی بی اندازه ای که به ببری داشت که مانند فرزند خود با او مانوس شده بود '' ناچار شده بود شش ماه کشور را ترک کند و از دلبستگی اش دور شود.پس تصمیم گرفت : ببر را برای این مدت به باغ وحش بسپارد.در این مورد با مسوولان باغ وحش صحبت کرد و با تقبل کل هزینه های شش ماهه '' ببر را با یک دنیا دلتنگی به باغ وحش سپرد و کارتی از مسوولان باغ وحش دریافت کرد تا هر زمان که مایل بود '' بدون ممانعت و بدون اخذ بلیت به دیدار ببرش بیاید.دوری از ببر'' برایش بسیار دشوار بود.روزهای آخر قبل از مسافرت '' مرتب به دیدار ببرش می رفت و ساعت ها کنارش می ماند و از دلتنگی اش با ببر حرف می زد.سر انجام زمان سفر فرا رسید و زن با یک دنیا غم دوری '' با ببرش وداع کرد.بعد از شش ماه که ماموریت به پایان رسید '' وقتی زن '' بی تاب و بی قرار به سرعت خودش را به باغ وحش رساند '' در حالی که از شوق دیدن ببرش فریاد می زد : عزیزم '' عشق من '' من بر گشتم '' این شش ماه دلم برایت یک ذره شده بود '' چقدر دوریت سخت بود '' اما حالا من برگشتم '' و در حین ابراز این جملات مهر آمیز '' به سرعت در قفس را گشود : آغوش را باز کرد و ببر را با یک دنیا عشق و محبت و احساس در آغوش کشید.ناگهان '' صدای فریادهای نگهبان قفس '' فضا را پر کرد:نه '' بیا بیرون '' بیا بیرون : این ببر تو نیست.ببر تو بعد از اینکه اینجا رو ترک کردی '' بعد از شش روز از غصه دق کرد و مرد.این یک ببر وحشی گرسنه است.اما دیگر برای هر تذکری دیر شده بود.\r\nببر وحشی با همه عظمت و خوی درندگی '' میان آغوش پر محبت زن '' مثل یک بچه گربه '' رام و آرام بود.اگرچه '' ببر مفهوم کلمات مهر آمیزی را که زن به زبان آلمانی ادا کرده بود '' نمی فهمید '' اما محبت و عشق چیزی نبود که برای درکش نیاز به دانستن زبان و رسم و رسوم خاصی باشد.چرا که عشق آنقدر عمیق است که در مرز کلمات محدود نشود و احساس آنقدر متعالی است که از تفاوت نوع و جنس فرا رود.برای هدیه کردن محبت '' یک دل ساده و صمیمی کافی است '' تا ازدریچه ی یک نگاه پر مهر عشق را بتاباند و مهر را هدیه کند.محبت آنقدر نافذ است که تمام فصل سرمای یاس و نا امیدی را در چشم بر هم زدنی بهار کند.عشق یکی از زیباترین معجزه های خلقت است که هر جا رد پا و اثری از آن به جا مانده تفاوتی درخشان و ستودنی '' چشم گیر است.محبت همان جادوی بی نظیری است که روح تشنه و سر گردان بشر را سیراب می کند و لذتی در عشق ورزیدن هست که در طلب آن نیست.بیا بی قید و شرط عشق ببخشیم تا از انعکاسش '' کل زندگیمان نور باران و لحظه لحظه ی عمر '' شیرین و ارزشمند گردد.در کورترین گره ها '' تاریک ترین نقطه ها '' مسدود ترین راه ها '' عشق بی نظیر ترین معجزه ی راه گشاست.مهم نیست دشوارترین مساله ی پیش روی تو چیست '' ماجرای فوق را به خاطر بسپار و بدان سر سخت ترین قفل ها با کلید عشق و محبت گشودنی است.پس : معجزه ی عشق را امتحان کن !\r\n"},{"id":1589,"category_id":10,"category_code":"s10","source_id":151,"title":"سه پرسش سقراط ","content":"هر زمان شایعه ای روشنیدیدو یا خواستید شایعه ای را تکرار کنید این فلسفه را در ذهن خود داشته باشید!\r\n\r\nدر یونان باستان سقراط به دلیل خرد و درایت فراوانش مورد ستایش بود. روزی فیلسوف بزرگی که از آشنایان سقراط بود،با هیجان نزد او آمد و گفت:سقراط میدانی راجع به یکی ازشاگردانت چه شنیده ام؟\r\n\r\nسقراط پاسخ داد:....\r\n\"لحظه ای صبر کن.قبل از اینکه به من چیزی بگویی از تومی خواهم آزمون کوچکی را که نامش سه پرسش است پاسخ دهی.\"مرد پرسید:سه پرسش؟سقراط گفت:بله درست است.قبل از اینکه راجع به شاگردم بامن صحبت کنی،لحظه ای آنچه را که قصدگفتنش را داری امتحان کنیم.\r\n\r\nاولین پرسش حقیقت است.کاملا مطمئنی که آنچه را که می خواهی به من بگویی حقیقت دارد؟مرد جواب داد:\"نه،فقط در موردش شنیده ام.\"سقراط گفت:\"بسیار خوب،پس واقعا نمیدانی که خبردرست است یا نادرست.\r\n\r\nحالا بیا پرسش دوم را بگویم،\"پرسش خوبی\"آنچه را که در موردشاگردم می خواهی به من بگویی خبرخوبی است؟\"مردپاسخ داد:\"نه،برعکس…\"سقراط ادامه داد:\"پس می خواهی خبری بد در مورد شاگردم که حتی درموردآن مطمئن هم نیستی بگویی؟\"مردکمی دستپاچه شد و شانه بالا انداخت.\r\n\r\nسقراط ادامه داد:\"و اما پرسش سوم سودمند بودن است.آن چه را که می خواهی در مورد شاگردم به من بگویی برایم سودمند است؟\"مرد پاسخ داد:\"نه،واقعا…\"سقراط نتیجه گیری کرد:\"اگرمی خواهی به من چیزی رابگویی که نه حقیقت داردونه خوب است و نه حتی سودمند است پس چرا اصلا آن رابه من می گویی؟\r\n"},{"id":1590,"category_id":10,"category_code":"s10","source_id":152,"title":"فقط انتخاب کنید! ","content":"امت فاکس، نویسنده و فیلسوف معاصر، هنگامی که برای نخستین بار به آمریکا رفته بود برای صرف غذا به رستورانی رفت .\r\nاو که تا آن زمان، هرگز به چنین رستورانی نرفته بود در گوشه ای به انتظار نشست با این نیت که از او پذیرایی شود .\r\nاما هر چه لحظات بیشتری سپری می شد ناشکیبایی او از اینکه می دید پیشخدمت ها کوچکترین توجهی به او ندارند، شدت گرفت .\r\nاز همه بدتر اینکه مشاهده می کرد کسانی پس از او وارد شده بودند و در مقابل بشقاب های پر از غذا نشسته و مشغول خوردن بودند .\r\nاو با ناراحتی به مردی که بر سر میز مجاور نشسته بود نزدیک شد و گفت: ...\r\nمن حدود بیست دقیقه است که در اینجا نشسته ام بدون آنکه کسی کوچکترین توجهی به من نشان دهد .\r\nحالا می بینم شما که پنج دقیقه پیش وارد شدید با بشقابی پر از غذا در مقابلتان اینجا نشسته اید! موضوع چیست؟ مردم این کشور چگونه پذیرایی می شوند؟\r\nمرد با تعجب گفت: ولی اینجا سلف سرویس است. سپس به قسمت انتهایی رستوران جایی که غذاها به مقدار فراوان چیده شده بود، اشاره کرد و ادامه داد: به آنجا بروید، یک سینی بردارید و هر چه می خواهید، انتخاب کنید، پول آن را بپردازید، بعد اینجا بنشینید و آن را میل کنید !\r\nامت فاکس، که قدری احساس حماقت می کرد، دستورات مرد را پی گرفت. اما وقتی غذا را روی میز گذاشت ناگهان به ذهنش رسید که زندگی هم در حکم سلف سرویس است .\r\nهمه نوع رخدادها، فرصت ها، موقعیت ها، شادی ها،سرورها و غم ها در برابر ما قرار دارد. در حالی که اغلب ما بی حرکت به صندلی خود چسبیده ایم و آن چنان محو این هستیم که دیگران در بشقاب خود چه دارند و دچار شگفتی شده ایم که چرا او سهم بیشتری دارد؟\r\nو هرگز به ذهنمان نمی رسد خیلی ساده از جای خود برخیزیم و ببینیم چه چیزهایی فراهم است. سپس آنچه می خواهیم برگزینیم .\r\n"},{"id":1591,"category_id":10,"category_code":"s10","source_id":153,"title":"چه کسی واقعا خدا را دوست دارد؟ ","content":"مردی در عالم رویا فرشته ای را دید که در یک دستش مشعل و در دست دیگرش سطل آبی گرفته بود و در جاده ای روشن و تاریک راه می رفت.\r\nمرد جلو رفت و از فرشته پرسید:« این مشعل و سطل آب را کجا می بری؟»...\r\nفرشتـه جواب داد:« می خواهم با این مشعـل بهشت را آتش بـزنم و با این سطل آب، آتش های جهنم را خاموش کنم. آن وقت ببینم چه کسی واقعاً خدا را دوست دارد!»\r\n"},{"id":1592,"category_id":10,"category_code":"s10","source_id":154,"title":"جور دگر باید دید","content":"هنگامی که ناسا برنامه ی فرستادن فضانوردان به فضا را آغاز کرد با مشکل کوچکی روبرو شد ، آنها دریافتند که خودکارهای موجود در فضای بدون جاذبه کار نمی کنند ، جوهر خودکار به سمت پایین جریان نمی یابد و روی سطح کاغذ نمی ریزد برای حل این مشکل \r\nآنها شرکت مشاورین اندرسون را انتخاب کردندتحقیقات بیش از یک دهه طول کشید ، دوازده میلیون دلار صرف شد و در نهایت آنها خودکاری طراحی کردند که در محیط بدون جاذبه می نوشت زیر آب کار می کرد ، روی هر سطحی حتی کریستال می نوشت و در دمای زیر صفر تا سیصد درجه ی سانتیگراد کار می کرد.\r\nروس ها راه حل ساده تری داشتند آنها از مداد استفاده کردند!!!\r\n"},{"id":1593,"category_id":10,"category_code":"s10","source_id":155,"title":"پرداخت شده است!","content":"روزی روزگاری پسرک فقیری زندگی می کرد که برای گذران زندگی و تامین مخارج تحصیلش دستفروشی می کرد.از این خانه به آن خانه می رفت تا شاید بتواند پولی بدست آورد.روزی متوجه شد که تنها یک سکه 10 سنتی برایش باقیمانده است و این درحالی بود که شدیداً احساس گرسنگی می کرد.تصمیم گرفت از خانه ای مقداری غذا تقاضا کند. بطور اتفاقی درب خانه ای را زد.دختر جوان و زیبائی در را باز کرد.پسرک با دیدن چهره زیبای دختر دستپاچه شد و بجای غذا ، فقط یک لیوان آب درخواست کرد. \r\nدختر که متوجه گرسنگی شدید پسرک شده بود بجای آب برایش یک لیوان بزرگ شیر آورد.پسر با تمانینه و آهستگی شیر را سر کشید و گفت :...\r\n«چقدر باید به شما بپردازم؟ » .دختر پاسخ داد: « چیزی نباید بپردازی.مادر به ما آموخته که نیکی ما به ازائی ندارد.» پسرک گفت: « پس من از صمیم قلب از شما سپاسگذاری می کنم» \r\nسالها بعد دختر جوان به شدت بیمار شد.پزشکان محلی از درمان بیماری او اظهار عجز نمودند و او را برای ادامه معالجات به شهر فرستادند تا در بیمارستانی مجهز ، متخصصین نسبت به درمان او اقدام کنند. \r\nدکتر هوارد کلی ، جهت بررسی وضعیت بیمار و ارائه مشاوره فراخوانده شد.هنگامیکه متوجه شد بیمارش از چه شهری به آنجا آمده برق عجیبی در چشمانش درخشید.بلافاصله بلند شد و بسرعت بطرف اطاق بیمار حرکت کرد.لباس پزشکی اش را بر تن کرد و برای دیدن مریضش وارد اطاق شد.در اولین نگاه اورا شناخت. \r\nسپس به اطاق مشاوره باز گشت تا هر چه زود تر برای نجات جان بیمارش اقدام کند.از آن روز به بعد زن را مورد توجهات خاص خود قرار داد و سر انجام پس از یک تلاش طولانی علیه بیماری ، پیروزی ازآن دکتر کلی گردید. \r\nآخرین روز بستری شدن زن در بیمارستان بود.به درخواست دکتر هزینه درمان زن جهت تائید نزد او برده شد.گوشه صورتحساب چیزی نوشت.آنرا درون پاکتی گذاشت و برای زن ارسال نمود. \r\nزن از باز کردن پاکت و دیدن مبلغ صورتحساب واهمه داشت.مطمئن بود که باید تمام عمر را بدهکار باشد.سرانجام تصمیم گرفت و پاکت را باز کرد.چیزی توجه اش را جلب کرد.چند کلمه ای روی قبض نوشته شده بود.آهسته انرا خواند: \r\n«بهای این صورتحساب قبلاً با یک لیوان شیر پرداخت شده است»\r\n"},{"id":1594,"category_id":10,"category_code":"s10","source_id":156,"title":"من چقدر ثروتمندم ","content":"هوا بدجورى توفانى بود و آن پسر و دختر کوچولو حسابى مچاله شده بودند. هردو لباس هاى کهنه و گشادى به تن داشتند و پشت در خانه مى لرزیدند. \r\n\r\nپسرک پرسید:«ببخشین خانم! شما کاغذ باطله دارین»\r\n\r\nکاغذ باطله نداشتم و وضع مالى خودمان هم چنگى به دل نمى زد و نمى توانستم به آنها کمک کنم. مى خواستم یک جورى از سر خودم بازشان کنم که چشمم به پاهاى کوچک آنها افتاد که توى دمپایى هاى کهنه کوچکشان قرمز شده بود.گفتم:«بیایین تو یه فنجون شیرکاکائوى گرم براتون درست کنم.»آنها را داخل آشپزخانه بردم و کنار بخارى نشاندم تا پاهایشان را گرم کنند. بعد یک فنجان شیرکاکائو و کمى نان برشته و مربا به آنها دادم و مشغول کار خودم شدم. زیر چشمى دیدم که دختر کوچولو فنجان خالى را در دستش گرفت و خیره به آن نگاه کرد. بعد پرسید:....\r\n«ببخشین خانم! شما پولدارین »نگاهى به روکش نخ نماى مبل هایمان انداختم و گفتم:«من اوه… نه!»دختر کوچولو فنجان را با احتیاط روى نعلبکى آن گذاشت و گفت:«آخه رنگ فنجون و نعلبکى اش به هم مى خوره.»آنها درحالى که بسته هاى کاغذى را جلوى صورتشان گرفته بودند تا باران به صورتشان شلاق نزند، رفتند.\r\n\r\nفنجان هاى سفالى آبى رنگ را برداشتم و براى اولین بار در عمرم به رنگ آنها دقت کردم. بعد سیب زمینى ها را داخل آبگوشت ریختم و هم زدم. سیب زمینى، آبگوشت، سقفى بالاى سرم، همسرم، یک شغل خوب و دائمى، همه اینها به هم مى آمدند. صندلى ها را از جلوى بخارى برداشتم و سرجایشان گذاشتم و اتاق نشیمن کوچک خانه مان را مرتب کردم.\r\n\r\nلکه هاى کوچک دمپایى را از کنار بخارى، پاک نکردم. مى خواهم همیشه آنها را همان جا نگه دارم که هیچ وقت یادم نرود چه آدم ثروتمندى هستم.\r\n\r\nدلم می خواد برای فردایی بهتر تلاش کنم.\r\n"},{"id":1595,"category_id":10,"category_code":"s10","source_id":157,"title":"اصرار عجیب پسر کوچولو ","content":"یکی بود یکی نبود. یه روزی روزگاری یه خانواده ی سه نفری بودن. یه پسر کوچولو بود با مادر و پدرش، بعد از یه مدتی خدا یه داداش کوچولوی خوشگل به پسرکوچولوی قصه ی ما میده.\r\n\r\nبعد از چند روز که از تولد نوزاد گذشت پسرکوچولو هی به مامان و باباش اصرار می کنه که اونو با نوزاد تنها بذارن....\r\n اما مامان و باباش می‌ترسیدن که پسرشون حسودی کنه و یه بلایی سر داداش کوچولوش بیاره.\r\n\r\nاصرارهای پسرکوچولوی قصه اونقدر زیاد شد که پدر و مادرش تصمیم گرفتن اینکارو بکنن اما در پشت در اتاق مواظبش باشن.\r\n\r\nپسر کوچولو که با برادرش تنها شد، خم شد روی سرش و گفت : داداش کوچولو! تو تازه از پیش خدا اومدی … به من می گی خدا چه شکلیه ؟ آخه من کم کم داره یادم می ره!\r\n"},{"id":1596,"category_id":10,"category_code":"s10","source_id":158,"title":"شیر عاشق","content":"شیر نری دلباخته‏ی آهوی ماده شد.\r\nشیر نگران معشوق بود و می‏ترسید بوسیله‏ حیوانات دیگر دریده شود. \r\nاز دور مواظبش بود\r\nپس چشم از آهو برنداشت تا یک بار که از دور او را می نگریست، \r\nشیری را دید که به آهو حمله کرد. فوری از جا پرید و جلو آمد. \r\nدید ماده شیری است. چقدر زیبا بود، \r\nگردنی مانند مخمل سرخ و بدنی زیبا و طناز داشت.\r\nبا خود گفت: حتما گرسنه است. همان جا ایستاد و مجذوب زیبایی ماده شیر شد. \r\nو هرگز ندید و هرگز نفهمید که آهو خورده شد.\r\nنتیجه اخلاقی : هیچ وقت به امید معشوقتون نباشید !! و در دنیا رو سه  چیز حساب نکنید اولی خوشگلی تون دومی معشوقتون و سومی را یادم رفت. اها اینکه تو یاد کسی بمونید وقتی لازمه.\r\n"},{"id":1597,"category_id":10,"category_code":"s10","source_id":159,"title":"درخواست سیانور","content":"خانمی وارد داروخانه می‏شه و به دکتر داروساز می‏گه که به سیانور احتیاج داره! داروسازه می‏گه واسه چی سیانور می‌‌خوای؟\r\n\r\nخانمه توضیح می‏ده که لازمه شوهرش را مسموم کنه!\r\n\r\nچشم‌های داروسازه چهارتا می شه و می‏گه: خدا رحم کنه! خانوم من نمی‌تونم به شما سیانور بدم که برید و شوهرتان را بکُشید! این بر خلاف قوانینه! من مجوز کارم را از دست خواهم داد.\r\nهر دوی ما را زندانی خواهند کرد و دیگه بدتر از این نمی‏شه! نه خانوم، نـــه! شما حق ندارید سیانور داشته باشید و حداقل من به شما سیانور نخواهم داد.\r\n\r\nبعد از این حرف خانمه دستش رو می‏بره داخل کیفش و از اون یه عکس می‏آره بیرون... عکسی که در اون شوهرش و زن داروسازه توی یه رستوران داشتند شام می‌خوردند. داروسازه به عکسه نگاه می کنه و می‏گه: چرا به من نگفته بودید که نسخه دارید؟\r\n\r\nنتیجه‌ی اخلاقی: وقتی به داروخانه می‌روید، اول نسخه‌ی خود را نشان بدهید!\r\n"},{"id":1598,"category_id":10,"category_code":"s10","source_id":160,"title":"اگر عمر دوباره داشتم ","content":"اگر عمر دوباره داشتم مى کوشیدم اشتباهات بیشترى مرتکب شوم. همه\r\nچیز را آسان مى گرفتم. از آنچه در عمر اولم بودم  ابله تر می شدم. فقط\r\nشمارى اندک از رویدادهاى جهان را جدى می گرفتم. اهمیت کمترى به\r\nبهداشت می دادم. به مسافرت بیشتر می رفتم. از کوههاى بیشترى بالا می رفتم\r\nو در رودخانه هاى بیشترى شنا می کردم. بستنى بیشتر می خوردم و اسفناج\r\nکمتر. مشکلات واقعى بیشترى مى داشتم و مشکلات واهى کمترى. آخر،\r\nببینید، من از آن آدمهایى بوده ام که بسیار محتاطانه و خیلى عاقلانه\r\nزندگی کرده ام. ساعت به ساعت، روز به روز. اوه، البته من هم لحظات\r\nسرخوشى داشت هام. اما اگر عمر دوباره داشتم از این لحظاتِ خوشى بیشتر\r\nمی داشتم....\r\nمن هرگز جایى بدون یک دماسنج، یک شیشه داروى قرقره، یک\r\nپالتوى بارانى و یک چتر نجات نمى روم. اگر عمر دوباره داشتم، سبک تر\r\nسفر می کردم.\r\nاگر عمر دوباره داشتم، وقتِ بهار زودتر پا برهنه راه می رفتم و وقتِ خزان\r\nدیرتر به این لذت خاتمه می دادم. از مدرسه بیشتر جیم مى شدم. گلوله هاى\r\nکاغذى بیشترى به معلم هایم پرتاب مى کردم. سگهاى بیشترى به خانه\r\nمی آوردم. دیرتر به رختخواب مى رفتم و می خوابیدم. بیشتر عاشق می شدم.\r\nبه ماهیگیرى بیشتر می رفتم. پایکوبى و دست افشانى بیشتر می کردم. سوار\r\nچرخ و فلک بیشتر مى شدم. به سیرک بیشتر می رفتم.\r\nدر روزگارى که تقریبًا همگان وقت و عمرشان را وقفِ بررسى وخامت\r\nاوضاع می کنند، من بر پا مى شدم و به ستایش سهل و آسانتر گرفتن اوضاع می پرداختم \r\nزیرا من با ویل دورانت موافقم که می گوید: شادی از خرد عاقل تر است.\r\nاگر عمر دوباره داشتم، گل مینا از چمنزارها بیشتر می چیدم.\r\n"},{"id":1599,"category_id":10,"category_code":"s10","source_id":161,"title":"حواسمان به گوش هایمان باشد! ","content":"روزی از روزها گروهی از قورباغه های کوچیک تصمیم گرفتند که با هم مسابقه دو بدهند. هدف مسابقه رسیدن به نوک یک برج خیلی بلند بود. جمعیت زیادی برای دیدن مسابقه و تشویق قورباغه ها جمع شده بودند و مسابقه شروع شد. راستش، کسی توی جمعیت باور نداشت که قورباغه های به این کوچیکی بتوانند به نوک برج برسند. شما می تونستید جمله هایی مثل اینها را بشنوید: «اوه، عجب کار مشکلی!!»، «اونها هیچ وقت به نوک برج نمی رسند.» یا «هیچ شانسی برای موفقیتشون نیست. برج خیلی بلنده!»\r\nقورباغه های کوچیک یکی یکی شروع به افتادن کردند بجز بعضی که هنوز....\r\nبا حرارت داشتند بالا و بالاتر می رفتند. جمعیت هنوز ادامه می داد: «خیلی مشکله! هیچ کس موفق نمی شه!» و تعداد بیشتری از قورباغه ها خسته می شدند و از ادامه دادن منصرف. ولی فقط یکی به رفتن ادامه داد؛ بالا، بالا و باز هم بالاتر. این یکی نمی خواست منصرف بشه! بالاخره بقیه از بالا رفتن منصرف شدند به جز اون قورباغه کوچولو که بعد از تلاش زیاد تنها قورباغه ای بود که به نوک رسید! بقیه قورباغه ها مشتاقانه می خواستند بدانند او چگونه این کار رو انجام داده؟\r\nاونا ازش پرسیدند که چطور قدرت رسیدن به نوک برج و موفق شدن رو پیدا کرده؟ و مشخص شد که برنده مسابقه کر بوده!\r\n"},{"id":1600,"category_id":10,"category_code":"s10","source_id":162,"title":"عاقبت اندیشی ","content":"\r\nخواست .رسول اکرم ( ص ) به او فرمودند :\r\n اگر بگویم بکار می بندی ؟\r\n بلی یا رسول الله !\r\n\r\n اگر بگویم بکار می بندی ؟\r\n بلی یا رسول الله\r\n\r\n اگر بگویم بکار می بندی ؟\r\nبلی یا رسول الله ؟\r\n\r\n\r\nرسول اکرم بعد از اینکه سه بار از او قول گرفتند و...او را متوجّه\r\nاهمیّت مطلبی که می خواهد بگوید، کرد ، به او فرمودند :\r\nهر گاه تصمیم بکاری گرفتی ، اول در اثر و نتیجه و عاقبت آن کارفکر کن و بیندیش ، اگر دیدی نتیجه و عاقبتش صحیح است آن را دنبال کن و اگر عاقبتش گمراهی و تباهی است، از تصمیم خود صرف نظر کن.\r\n"},{"id":1601,"category_id":10,"category_code":"s10","source_id":163,"title":"چقدر ما کارمان را دوست داریم! ","content":"یکی از مدیران آمریکایی که مدتی برای یک دوره آموزشی به ژاپن رفته بود، تعریف کرده است که:\r\nکه روزی از خیابانی که چند ماشین در دو طرف آن پارک شده بود می گذشتم. رفتار جوانکی نظرم را جلب کرد. او با جدیت و حرارتی خاص مشغول تمیز کردن یک ماشین بود. بی اختیار ایستادم. مشاهده فردی که این چنین در حفظ و تمیزی ماشین خود می کوشد مرا مجذوب کرده بود. مرد جوان پس از ....\r\nتمیز کردن ماشین و تنظیم آیینه های بغل، راهش را گرفت و رفت چند متر آن طرفتر، در ایستگاه اتوبوس منتظر ایستاد. رفتار وی گیجم کرد.\r\nبه او نزدیک شدم و پرسیدم: «مگر آن ماشینی را که تمیز کردید متعلق به شما نبود؟»\r\nنگاهی به من انداخت و با لبخندی گفت: «من کارگر کارخانه ای هستم که آن ماشین از تولیدات آن است. دلم نمی خواهد اتومبیلی را که ما ساخته ایم کثیف و نامرتب جلوه کند.»\r\n"},{"id":1602,"category_id":10,"category_code":"s10","source_id":164,"title":"اشتباه فرشتگان ","content":"درویشی به اشتباه فرشتگان به جهنم فرستاده میشود .\r\nپس از اندک زمانی داد شیطان در می آید و رو به فرشتگان می کند و می گوید : جاسوس می فرستید به جهنم!؟....\r\nاز روزی که این ادم به جهنم آمده مداوم در جهنم در گفتگو و بحث است و جهنمیان را هدایت می کند و...\r\nحال سخن درویشی که به جهنم رفته بود این چنین است: با چنان عشقی زندگی کن که حتی بنا به تصادف اگر به جهنم افتادی خود شیطان تو را به بهشت باز گرداند.\r\n"},{"id":1603,"category_id":10,"category_code":"s10","source_id":165,"title":"حکمتی از لقمان، شکایت نکنید! ","content":"لقمان در آغاز، برده خواجه ای توانگر و خوش قلب بود. ارباب او در عین جاه و جلال و ثروت و مکنت دچار شخصیتی ضعیف و در برابر ناملایمات زندگی بسیار رنجور بود و با اندک سختی زبان به ناله و گلایه می گشود، این امر لقمان را می آزرد اما راه چاره ای به نظر او نمی رسید، زیرا بیم آن داشت که با اظهار این معنی، غرور خواجه جریحه دار شود و با او راه عناد پیش گیرد. روزگاری دراز وضع بدین منوال گذشت تا روزی یکی از دوستان خواجه خربزه ای به رسم هدیه و نوبر برای او فرستاد. خواجه تحت تأثیر خصائل ویژه لقمان، خربزه را قطعه قطعه نمود به لقمان تعارف کرد و لقمان با روی گشاده و اظهار تشکر آنها را تناول کرد تا به قطعه آخر رسید، در این هنگام\r\nخواجه قطعه آخر را خود به دهان برد و متوجه شد که خربزه به شدت تلخ است. سپس با تعجب زیاد رو به لقمان کرد و گفت: چگونه چنین خربزه تلخی را خوردی و لب به اعتراض نگشودی؟ لقمان که دریافت زمان تهذیب و تأدیب خواجه فرا رسیده است، به آرامی و با احتیاط گفت: واضح است که من تلخی و ناگواری این میوه را به خوبی احساس کردم اما سالهای متمادی من از دست پر برکت شما، لقمه های شیرین و گوارا را گرفته ام، سزاوار نبود که با دریافت اولین لقمه ناگوار، شکوه و شکایت آغاز کنم. خواجه از این برخورد، درس عبرت گرفت و به ضعف و زبونی خود در برابر ناملایمات پی برد و در اصلاح نفس و تهذیب و تقویت روح خود همت گماشت و خود را به صبر و شکیبایی بیاراست.\r\n"},{"id":1604,"category_id":10,"category_code":"s10","source_id":166,"title":"کوهنورد ","content":"کوهنوردی می‌‌خواست به قله‌ای بلندی صعود کند. پس از سال‌ها تمرین و آمادگی، سفرش را آغاز کرد. به صعودش ادامه داد تا این که هوا کاملا تاریک شد. به جز تاریکی هیچ چیز دیده نمی‌شد. سیاهی شب همه جا را پوشانده بود و مرد نمی‌توانست چیزی ببیند حتی ماه و ستاره‌ها پشت انبوهی از ابر پنهان شده بودند. کوهنورد همان‌طور که داشت بالا می‌رفت، در حالی که چیزی به فتح قله نمانده بود، پایش لیز خورد و با سرعت هر چه تمام‌تر سقوط کرد. سقوط همچنان ادامه داشت و او در آن لحظات سرشار از هراس، تمامی خاطرات خوب و بد زندگی‌اش را به یاد می‌آورد. داشت فکر می‌‌کرد چقدر به مرگ نزدیک شده است که ناگهان دنباله طنابی که به دور کمرش حلقه خورده بود بین شاخه های درختی در شیب کوه گیر کرد و مانع از سقوط کاملش شد. در آن لحظات سنگین سکوت، که هیچ امیدی نداشت از ته دل فریاد زد: خدایا کمکم کن !\r\nندایی از دل آسمان پاسخ داد از من چه می‌خواهی؟\r\n- نجاتم بده خدای من!\r\n- آیا به من ایمان داری؟\r\n- آری. همیشه به تو ایمان داشته‌ام \r\n- پس آن طناب دور کمرت را پاره کن!\r\nکوهنورد وحشت کرد. پاره شدن طناب یعنی سقوط بی‌تردید از فراز کیلومترها ارتفاع. گفت: خدایا نمی‌توانم.\r\nخدا گفت: آیا به گفته من ایمان نداری؟\r\nکوهنورد گفت: خدایا نمی توانم. نمی‌توانم.\r\nروز بعد، گروه نجات گزارش داد که جسد منجمد شده یک کوهنورد در حالی پیدا شده که طنابی به دور کمرش حلقه شده بود و تنها دو متر با زمین فاصله داشت...\r\n"},{"id":1605,"category_id":10,"category_code":"s10","source_id":167,"title":"حکایتی از حضرت علی","content":"یک روز امام علی علیه  السلام از کنار یک یهودی گذشتند و آن یهودی با اسبش [بدون اینکه اسبش وارد آب شود یا خیس شود] از روی رود عبور می کرد، پس در همان لحظه امام علی علیه السلام را صدا  زد و عرض کرد: ای آقا! اگر این چیزی که نزد من است نزد شما بود چه کار می کردید؟\r\n\r\nامام علی علیه السلام در جوابش فرمودند: در جایت بایست !...\r\nسپس روی آب ایستاد و آن یهودی میخکوب شد. امام علی علیه السلام نزد او رفت، آنگاه یهودی به امام گفت: ای جوان! چه چیزی گفتی که آب برایت مانند سنگ شد؟ امام علی علیه السلام در جوابش گفت: تو چه چیزی گفتی که از آب عبور کردی؟ آن یهودی در جواب حضرت گفت: من اسم وصیّ پیامبر اسلام علی علیه السلام را بر زبان آوردم و از آب عبور کردم .\r\n\r\nپس حضرت امیرالمؤمنین علیه السلام فرمودند : من همان وصیّ محمد صلی الله علیه و آله هستم؛\r\nآنگاه آن یهودی گفت: حق است، و اسلام آورد.\r\n"},{"id":1606,"category_id":10,"category_code":"s10","source_id":168,"title":"سنگ ، ثروت و عشق","content":"در زمانهای گذشته پادشاهی تخته سنگی را در وسط جاده قرار داد وبرای اینکه عکس العمل مردم را ببیند خودش را در جایی مخفی کرد \r\n\r\nبعضی از بازرگانان وندیمان ثرتمند پادشاه بی تفاوت از کنار تخته سنگ می گذشتند بسیاری هم غرولند می کردند که این چه شهری است که نظم ندارد حاکم این شهر عجب مرد بی عرضه ای است و....\r\nنزدیک غروب یک روستایی که پشتش بار میوه بود نزدیک سنگ شد وبا هر زحمتی که بود تخته سنگ را از وسط جاده برداشت وان را کناری قرار داد ناگهان کیسه ای دید که زیر تخته سنگ قرار داده شده بود کیسه را باز کرد داخل ان سکه های طلا ویک یاداشت پیدا کرد \r\n\r\nپادشاه نوشته بود:هر سد و مانعی می تواند یک شانس برای تغییر زندگی انسان باشد.\r\n"},{"id":1607,"category_id":10,"category_code":"s10","source_id":169,"title":"عقاب ","content":"مردی تخم عقابی پیدا کرد و آن را در لانه مرغی گذاشت . عقاب با بقیه جوجه ها از تخم بیرون آمد و با آن‌ها بزرگ شد . در تمام زندگیش ، او همان کارهایی را انجام داد که مرغ ها می کردند، برای پیدا کردن کرم ها و حشرات زمین را می کند و قدقد می کرد و گاهی با دست و پا زدن بسیار ، کمی در هوا پرواز می‌کرد .\r\nسال ها گذشت و عقاب خیلی پیر شد ....\r\nروزی پرنده باعظمتی را بالای سرش بر فراز آسمان ابری دید . او با شکوه تمام ، با یک حرکت جزئی بالهای طلاییش برخلاف جریان شدید باد پرواز می کرد .\r\nعقاب پیر بهت زده نگاهش کرد و پرسید : این کیست ؟\r\nهمسایه اش پاسخ داد :این یک عقاب است . سلطان پرندگان . او متعلق به آسمان است و ما زمینی هستیم.\r\nعقاب مثل یک مرغ زندگی کرد و مثل یک مرغ مرد . زیرا فکر می کرد یک مرغ است .\r\n"},{"id":1608,"category_id":10,"category_code":"s10","source_id":170,"title":"دوست داشتن در مقابل استفاده کردن","content":"زمانیکه مردی در حال پولیش کردن اتوموبیل جدیدش بود کودک 4 ساله اش  تکه سنگی را بداشت و  بر روی بدنه اتومبیل خطوطی را انداخت.\r\nمرد آنچنان عصبانی شد که دست پسرش را در دست گرفت و چند بار محکم پشت دست او زد بدون انکه به دلیل خشم متوجه شده باشد که با آچار پسرش را تنبیه نموده\r\nدر بیمارستان به سبب شکستگی های فراوان چهار انشگت دست پسر قطع شد \r\nوقتی که پسر چشمان اندوهناک پدرش را دید از او پرسید\r\n\"پدر کی انگشتهای من در خواهند آمد\"\r\nآن مرد آنقدر مغموم بود که هچی نتوانست بگوید به سمت اتوبیل برگشت وچندین باربا لگدبه آن زد\r\nحیران و سرگردان از عمل خویش روبروی اتومبیل نشسته بود و به خطوطی که پسرش روی آن انداخته بود  نگاه می کرد . او نوشته بود \" دوستت دارم پدر\"\r\nروز بعد آن مرد خودکشی کرد \r\nخشم و عشق حد و مرزی ندارنددومی ( عشق) را انتخاب کنید تا زندکی دوست داشتنی داشته باشید و این را به یاد داشته باشیدکه اشیاء برای استفاد شدن و انسانها برای دوست داشتن می باشند\r\nدر حالیک امروزه از انسانها استفاده می شود و اشیاء دوست داشته می شوند.\r\nهمواره در ذهن داشته باشید که: اشیاء برای استفاد شدن و انسانها برای دوست داشتن می باشند\r\nمراقب افکارتان باشید   که تبدیل به گفتارتان میشوند\r\nمراقب گفتارتان باشید که تبدیل به رفتار تان می شود\r\nمراقب رفتار تان باشیدکه تبدیل به عادت می شود\r\nمراقب عادات خود باشیدشخصیت شما می شود \r\nمراقب شخصیت خود باشیدکه سرنوشت شما می شود\r\nخوشحالم که  دوستی این پیام را برای یاد آوری به من فرستاد\r\nامیدوارم که روز خوبی داشته و  هر مشکلی که با آن روبرو هستید \r\nآخرین روز آن باشد و تمام شود \r\n"},{"id":1609,"category_id":10,"category_code":"s10","source_id":171,"title":"زندگی به سبک ویلان!!! ","content":"هنوز هم بعد از این همه سال، چهره‌ی ویلان را از یاد نمی‌برم. در واقع، در طول سی سال گذشته، همیشـه روز اول مـاه کـه حقوق بازنشستگی را دریافت می‌کنم، به یاد ویلان می‌افتم …\r\n\r\nویلان پتی اف، کارمند دبیرخانه‌ی اداره بود. از مال دنیا، جز حقوق اندک کارمندی هیچ عایدی دیگری نداشت. ویلان، اول ماه که حقوق می‌گرفت و جیبش پر می‌شد، شروع می‌کرد به حرف زدن …\r\n\r\nروز اول ماه و هنگامی‌که که از بانک به اداره برمی‌گشت، به‌راحتی می‌شد برآمدگی جیب سمت چپش را تشخیص داد که تمام حقوقش را در آن چپانده بود.\r\n\r\nویلان از روزی که حقوق می‌گرفت تا روز پانزدهم ماه که پولش ته می‌کشید، نیمی از ماه سیگار برگ می‌کشید، نیمـی از مـاه مست بود و سرخوش..\r\nمن یازده سال با ویلان هم‌کار بودم. بعدها شنیدم، او سی سال آزگار به همین نحو گذران روزگار کرده است. روز آخر کـه من از اداره منتقل می‌شدم، ویلان روی سکوی جلوی دبیرخانه نشسته بود و سیگار برگ می‌کشید. به سراغش رفتم تا از او خداحافظی کنم.\r\n\r\nکنارش نشستم و بعد از کلی حرف مفت زدن، عاقبت پرسیدم که چرا سعی نمی کند زندگی‌اش را سر و سامان بدهد تا از این وضع نجات پیدا کند؟\r\n\r\nهیچ وقت یادم نمی‌رود. همین که سوال را پرسیدم، به سمت من برگشت و با چهره‌ای متعجب، آن هم تعجبی طبیعی و اصیل پرسید: کدام وضع؟\r\n\r\nبهت زده شدم.. همین‌طور که به او زل زده بودم، بدون این‌که حرکتی کنم، ادامه دادم:\r\n\r\nهمین زندگی نصف اشرافی، نصف گدایی!!!\r\n\r\nویلان با شنیدن این جمله، همان‌طور که زل زده بود به من، ادامه داد:\r\n\r\nتا حالا سیگار برگ اصل کشیدی؟\r\n\r\nگفتم: نه !\r\n\r\nگفت: تا حالا تاکسی دربست گرفتی؟\r\n\r\nگفتم: نه !\r\n\r\nگفت: تا حالا به یک کنسرت عالی رفتی؟\r\n\r\nگفتم: نه !\r\n\r\nگفت: تا حالا غذای فرانسوی خوردی؟\r\n\r\nگفتم: نه !\r\n\r\nگفت: تا حالا یه هفته مسکو موندی خوش بگذرونی؟\r\n\r\nگفتم: نه !\r\n\r\nگفت: خاک بر سرت، تا حالا زندگی کردی؟\r\n\r\nبا درماندگی گفتم: آره، …. نه، … نمی دونم !!!\r\n\r\nویلان همین‌طور نگاهم می‌کرد. نگاهی تحقیرآمیز و سنگین ….\r\n\r\nحالا که خوب نگاهش می‌کردم، مردی جذاب بود و سالم. به خودم که آمدم، ویلان جلویم ایستاده بود و تاکسی رسیده بود. ویلان سیگار برگی تعارفم کرد و بعد جمله‌ای را گفت. جمله‌ای را گفت که مسیر\r\n\r\nزندگی‌ام را به کلی عوض کرد.\r\n\r\nویلان پرسید: می‌دونی تا کی زنده‌ای؟\r\n\r\nجواب دادم: نه !\r\n\r\nویلان گفت: پس سعی کن دست کم نصف ماه رو زندگی کنی.\r\n"},{"id":1610,"category_id":10,"category_code":"s10","source_id":172,"title":"چه وقت میتوان ازدواج پایدار کرد؟ ","content":"دانایی را پرسیدند: چه وقت برای ازدواج پایدار مناسب است؟ دانا گفت: زمانی که شخص توانا شود! پرسیدند: توانا از لحاظ مالی؟ جواب داد: نی! گفتند: توانا از لحاظ جسمی؟ گفت: نی! پرسیدند: توانا از لحاظ فکری؟ ...\r\nجواب داد: نی! پرسیدند: خود بگو که ما را در این امر دیگر چیزی نیست! دانا گفت: زمانی یک شخص می تواند ازدواج پایدار نماید که اگر تا دیروز نانی را به تنهایی می خورد امروز بتواند آن را با دیگری نصف نماید بدون آنکه اندکی از این مسئله ناراحت گردد!\r\n"},{"id":1611,"category_id":10,"category_code":"s10","source_id":173,"title":"قیمت زیبایی ؟ ","content":"مردی در نمایشگاهی گلدان می فروخت . زنی نزدیک شد و اجناس او را بررسی کرد . بعضی ها بدون تزیین بودند، اما بعضی ها هم طرحهای ظریفی داشتند .زن قیمت گلدانها را پرسید و شگفت زده دریافت که قیمت همه آنها یکی است .او پرسید:....\r\nچرا گلدانهای نقش دار و گلدانهای ساده یک قیمت هستند ؟چرا برای گلدانی که وقت و زحمت بیشتری برده است همان پول گلدان ساده را می گیری؟ \r\nفروشنده گفت: من هنرمندم . قیمت گلدانی را که ساخته ام می گیرم. زیبایی رایگان است .\r\n"},{"id":1612,"category_id":10,"category_code":"s10","source_id":174,"title":"مناظره بیل گیتس با جنرال موتورز ","content":"در یکی از نمایشگاه های ماشین که اخیرا برگزار شده بود بیل گیتس موسس شرکت مایکروسافت و ثروتمندترین مرد جهان صنعت ماشین را با صنعت کامپیوتر مقایسه و ادعا کرد :\r\n\r\nاگر جنرال موتورز با سرعتی معادل سرعت پیشرفت تکنولوژی پیشرفت کرده بود الان همه ما ماشین هایی سوار می شدیم که قیمتشان 25 دلار و میزان مصرف بنزین آنها 4 لیتر در هر 1000 کیلومتر بود؟!....\r\nجنرال موتورز هم در جواب بیل گیتس اعلام کرد ...\r\nاگر جنرال موتوزر هم مانند مایکروسافت پیشرفت کرده بود امروزه ما ماشین هایی با این مشخصات سوار می شدیم :\r\n\r\n1 - کیسه هوا قبل از باز شدن از شما می پرسید : ? \r\n\r\n2 - بدون هیچ دلیلی ماشین شما دو بار در روز تصادف می کرد ؟\r\n\r\n3- برای خاموش کردن ماشین باید دکمه استارت را می زدید ؟\r\n\r\n4 - صندلی های جدید همه را مجبور می کردند بدن خودشان را متناسب و اندازه انها بکنند ؟\r\n\r\n5 - هر بار که خطهای وسط خیابان را از نو نقاشی می کردند شما مجبور بودید یک ماشین جدید بخرید ؟\r\n\r\n6- گاه و بیگاه ماشین شما وسط خیابان ها از حرکت باز می ایستاد و شما چاره ای جز استارت مجدد ندارید ؟\r\n\r\n7- هر بار که جنرال موتورز ماشین جدیدی عرضه میکرد همه خریداران ماشین باید رانندگی را از اول یاد می گرفتند چون هیچ یک از عملکردهای ماشین مانند ماشین های مدل قبلی نبود ؟\r\n"},{"id":1613,"category_id":10,"category_code":"s10","source_id":175,"title":"اعتراف ","content":"مردی برای اعتراف نزد کشیش رفت.\r\n\r\n«پدر مقدس، مرا ببخش. در زمان جنگ جهانی دوم من به یک یهودی پناه دادم»\r\n\r\n«مسلماً تو گناه نکرده ای پسرم»\r\n\r\n«اما من ازش خواستم برای ماندن در انباری من هفته ای بیست شیلینگ بپردازد»...\r\n«خوب البته این یکی زیاد خوب نبوده. اما بالاخره تو جون اون آدم رو نجات دادی، بنابر این بخشیده می شوی»\r\n\r\n«اوه پدر این خیلی عالیه. خیالم راحت شد. حالا میتونم یه سئوال دیگه هم بپرسم؟»\r\n\r\n«چی می خوای بپرسی پسرم؟»\r\n\r\n«به نظر شما باید بهش بگم که جنگ تموم شده؟» \r\n"},{"id":1614,"category_id":10,"category_code":"s10","source_id":176,"title":"دختر فداکار ","content":"همسرم نواز با صدای بلند گفت، تا کی می خوای سرتو توی اون روزنامه فرو کنی؟ میشه بیای و به دختر جونت بگی غذاشو بخوره؟\r\nشوهر روزنامه رو به کناری انداخت و بسوی آنها رفت\r\nتنها دخترم آوا بنظر وحشت زده می آمد. اشک در چشمهایش پر شده بود\r\nظرفی پر از شیربرنج در مقابلش قرار داشت\r\nآوا دختری زیبا و برای سن خود بسیار باهوش بود\r\nگلویم رو صاف کردم و ظرف را برداشتم و گفتم، چرا چند تا قاشق گنده نمی خوری؟\r\nفقط بخاطر بابا عزیزم. آوا کمی نرمش نشان داد و با پشت دست اشکهایش را پاک کرد و گفت\r\nباشه بابا، می خورم، نه فقط چند قاشق، همه شو می خوردم. ولی شما باید.... آوا مکث کرد\r\nبابا، اگر من تمام این شیر برنج رو بخورم، هرچی خواستم بهم میدی؟...\r\nدست کوچک دخترم رو که بطرف من دراز شده بود گرفتم و گفتم، قول میدم. بعد باهاش دست دادم و تعهد کردم\r\nناگهان مضطرب شدم. گفتم، آوا، عزیزم، نباید برای خریدن کامپیوتر یا یک چیز گران قیمت اصرار کنی\r\nبابا از اینجور پولها نداره. باشه؟\r\nنه بابا. من هیچ چیز گران قیمتی نمی خوام.\r\nو با حالتی دردناک تمام شیربرنج رو فرو داد.\r\nدر سکوت از دست همسرم و مادرم که بچه رو وادار به خوردن چیزی که دوست نداشت کرده بودن عصبانی بودم\r\nوقتی غذا تمام شد آوا نزد من آمد. انتظار در چشمانش موج میزد\r\nهمه ما به او توجه کرده بودیم. آوا گفت، من می خوام سرمو تیغ بندازم. همین یکشنبه\r\nتقاضای او همین بود.\r\nهمسرم جیغ زد و گفت، وحشتناکه. یک دختر بچه سرشو تیغ بندازه؟ غیرممکنه. نه در خانواده ما. و مادرم با صدای گوشخراشش گفت، فرهنگ ما با این برنامه های تلویزیونی داره کاملا نابود میشه\r\nگفتم، آوا، عزیزم، چرا یک چیز دیگه نمی خوای؟ ما از دیدن سر تیغ خورده تو غمگین می شیم\r\nخواهش می کنم، عزیزم، چرا سعی نمی کنی احساس ما رو بفهمی؟\r\nسعی کردم از او خواهش کنم. آوا گفت، بابا، دیدی که خوردن اون شیربرنج چقدر برای من سخت بود\r\nآوا اشک می ریخت. و شما بمن قول دادی تا هرچی می خوام بهم بدی. حالا می خوای بزنی زیر قولت\r\nحالا نوبت من بود تا خودم رو نشون بدم. گفتم، مرده و قولش\r\nمادر و همسرم با هم فریاد زدن که، مگر دیوانه شدی؟\r\nنه. اگر به قولی که می دیم عمل نکنیم اون هیچوقت یاد نمی گیره به حرف خودش احترام بذاره\r\nآوا، آرزوی تو برآورده میشه\r\nآوا با سر تراشیده شده صورتی گرد و چشمهای درشت زیبائی پیدا کرده بود\r\nصبح روز دوشنبه آوا رو به مدرسه بردم. دیدن دختر من با موی تراشیده در میون بقیه شاگردها تماشائی بود. آوا بسوی من برگشت و برایم دست تکان داد. من هم دستی تکان دادم و لبخند زدم\r\nدر همین لحظه پسری از یک اتومبیل بیرون آمد و با صدای بلند آوا را صدا کرد و گفت، آوا، صبر کن تا من بیام\r\nچیزی که باعث حیرت من شد دیدن سر بدون موی آن پسر بود. با خودم فکر کردم، پس موضوع اینه\r\nخانمی که از آن اتومبیل بیرون آمده بود بدون آنکه خودش رو معرفی کنه گفت، دختر شما، آوا، واقعا فوق العاده ست. و در ادامه گفت، پسری که داره با دختر شما میره پسر منه\r\nاون سرطان خون داره. زن مکث کرد تا صدای هق هق خودش رو خفه کنه. در تمام ماه گذشته هریش نتونست به مدرسه بیاد. بر اثر عوارض جانبی شیمی درمانی تمام موهاشو از دست داده\r\nنمی خواست به مدرسه برگرده. آخه می ترسید هم کلاسی هاش بدون اینکه قصدی داشته باشن مسخره ش کنن\r\nآوا هفته پیش اون رو دید و بهش قول داد که ترتیب مسئله اذیت کردن بچه ها رو بده. اما، حتی فکرشو هم نمی کردم که اون موهای زیباشو فدای پسر من کنه\r\nآقا، شما و همسرتون از بنده های محبوب خداوند هستین که دختری با چنین روح بزرگی دارین\r\nسر جام خشک شده بودم. و... شروع کردم به گریستن. فرشته کوچولوی من، تو بمن درس دادی که فهمیدم عشق واقعی یعنی چی\r\nخوشبخت ترین مردم در روی این کره خاکی کسانی نیستن که آنجور که می خوان زندگی می کنن. آنها کسانی هستن که خواسته های خودشون رو بخاطر کسانی که دوستشون دارن تغییر میدن\r\nبه این مسئله فکر کنین\r\n"},{"id":1615,"category_id":10,"category_code":"s10","source_id":177,"title":"گربه شیطون ","content":"یه خانومی گربه ای داشت که هووی شوهرش شده بود. آقاهه برای اینکه از شر گربه\r\nراحت بشه، یه روز گربه رو میزنه زیر بغلش و 4 تا خیابون اونطرف تر ولش می کنه.\r\n وقتی خونه میرسه میبینه گربه هه از اون زودتر اومده خونه.\r\nاین کارا رو چند بار دیگه تکرار می کنه، اما نتیجه ای نمیگیره.....\r\nیک روز گربه رو بر میداره میذاره تو ماشین. بعد از گشتن از چند تا بلوار و پل و\r\nرودخانه و. .\r\nخلاصه گربه رو پرت میکنه بیرون.\r\nیک ساعت بعد، زنگ میزنه خونه. زنش گوشی رو برمیداره. مرده میپرسه: \" اون\r\nگربه کره خر  خونس؟\" زنش می گه آره. مرده میگه گوشی رو بده\r\nبهش، من گم شدم.\r\n"},{"id":1616,"category_id":10,"category_code":"s10","source_id":178,"title":"به اقتضای زمان ","content":"زن و مردی جوان ، در اتاق پذیرایی که کاغذ دیواری آن به رنگ آبی آسمانی بود ، دل داده و قلوه گرفته بودند.\r\nمرد خوش قیافه ، جلو دختر جوان زانو زده بود و قسم می خورد:\r\nــ بدون شما عزیزم ، نمی توانم زندگی کنم! قسم می خورم که این عین حقیقت است!\r\nو همچنانکه به سنگینی نفس می زد ، ادامه داد:\r\nــ از لحظه ای که شما را دیدم ، آرامشم از دست رفت! عزیزم حرف بزنید … عزیزم … آره یا نه ؟\r\nزن جوان ، دهان کوچک خود را باز کرد تا جواب دهد اما درست در همین لحظه ، در اتاق اندکی باز شد و برادرش از لای در گفت:\r\nــ لی لی ، لطفاً یک دقیقه بیا بیرون!...\r\nلی لی از در بیرون رفت و پرسید:\r\nــ کاری داشتی ؟!\r\nــ عزیزم ، ببخش که موی دماغتان شدم ولی … من برادرت هستم و وظیفه ی مقدس برادری حکم میکند به تو هشدار بدهم … مواظب این یارو باش! احتیاط کن … مواظب حرف زدنت باش … لازم نیست با او از هر دری حرف بزنی.\r\nــ او دارد به من پیشنهاد ازدواج می کند!\r\nــ من کاری به پیشنهادش ندارم … این تو هستی که باید تصمیم بگیری ، نه من … حتی اگر در نظر داری با او ازدواج کنی ، باز مواظب حرف زدنت باش … من این حضرت را خوب میشناسم … از آن پست فطرتهای دهر است! کافیست حرفی بهش بزنی تا فوری گزارش بدهد …\r\nــ متشکرم ماکس! … خوب شد گفتی … من که نمی شناختمش!\r\nزن جوان به اتاق پذیرایی بازگشت. پاسخ او به پیشنهاد مرد جوان « بله » بود. ساعتی کنار هم نشستند ، بوسه ها رد و بدل کردند ، همدیگر را در آغوش گرفتند و قسمها خوردند اما … اما زن جوان ، احتیاط خود را از دست نداد: جز از عشق و عاشقی ، سخنی بر زبان نیاورد.\r\n"},{"id":1617,"category_id":10,"category_code":"s10","source_id":179,"title":"فراموش نکنیم از کجا آمدیم.... ","content":"منشی رئیس با خود فکر کرد شاید برای گرفتن تخفیف شهریه آمده اند یا شاید\r\nهم پسرشان مشروط شده است و می خواهند به رئیس دانشگاه التماس کنند.\r\nپیرمرد مؤدبانه گفت: «ببخشید آقای رییس هست؟ » منشی با بی حوصلگی گفت:«\r\nایشان تمام روز گرفتارند.» پیر مرد جواب داد : « ما منتظر می مونیم. »\r\nمنشی اصلاً توجهی به آنها نکرد و به این امید بود که بالاخره خسته می\r\nشوند و پی کارشان می روند. اما این طور نشد. بعد از چند ساعت ، منشی خسته\r\nشد و سرانجام تصمیم گرفت مزاحم رییس شود ، هرچند ازاین کار اکراه داشت.\r\nوارد اطاق رئیس شد و به او گفت : « دو تا دهاتی آمده اند و می خواهند شما\r\nراببینند . شاید اگرچند دقیقه ای آنها را ببینید، بروند.» رییس با اوقات\r\nتلخی آهی کشید و سرتکان داد. نفر اول برترین دانشگاه کشور .....\r\nارائه دهنده چندین مقاله در همایش های علمی بزرگ دنیا و مجلات تخصصی ، صاحب چندین\r\nنظریه در مجامع و همایش بین المللی حتماً برای وقتش بیش از دیدن دو دهاتی\r\nبرنامه ریزی کرده است. به علاوه اصلا دوست نداشت دو نفر با لباس های\r\nمندرس وارد اتاقش شوند و روی صندلی های چرمی اوریژنال لدر اطاقش بنشینند.\r\nبا قیافه ای عبوس و در هم از اطاق بیرون آمد. اما پیر زن و پیر مرد رفته\r\nبودند. بویی آشنا به مشامش خورد. شاید به این دلیل بود که خودش هم در\r\nروستا بزرگ شده بود.رئیس رو به منشی کرد و گفت : نگفتن چیکار دارن . منشی\r\nاز اینکه آنها آنجا را ترک کرده بودند با رضایت گفت : نه . از پنجره\r\nنگاهی به بیرون انداخت و به اطاقش برگشت. موقع ناهار رئیس پیام های صوتی\r\nموبایلش را چک کرد : سلام بابا ، می خواستم مادرت رو ببرم دکتر . کیف\r\nپولم رو در ترمینال دزدیدن ، اومدیم دانشگاه ازت کمی پول قرض کنیم . منشی\r\nراهمون نداد . وقتی شماره موبایلت هم را هم گرفتم دوباره همون خانم\r\nنگذاشت با هات صحبت کنم و گفت پیغام بذاریم. الان هم داریم برمی گردیم\r\nخونه ...\r\n"},{"id":1618,"category_id":10,"category_code":"s10","source_id":180,"title":"روز قسمت ","content":"روز قسمت بود. خدا هستی را قسمت می کرد. خدا گفت : چیزی از من بخواهید. هر چه که باشد‚ شما را خواهم داد. سهمتان را از هستی طلب کنید زیرا خدا بسیار بخشنده است.\r\n\r\nو هر که آمد چیزی خواست. یکی بالی برای پریدن و دیگری پایی برای دویدن. یکی جثه ای بزرگ خواست و آن یکی چشمانی تیز. یکی دریا را انتخاب کرد و یکی آسمان را.\r\n\r\nدر این میان کرمی کوچک جلو آمد و به خدا گفت : ....\r\n من چیز زیادی از این هستی نمی خواهم. نه چشمانی تیز و نه جثه ای بزرگ. نه بالی و نه پایی ‚ نه آسمان ونه دریا. تنها کمی از خودت‚ تنها کمی از خودت را به من بده.\r\n\r\nو خدا کمی نور به او داد.\r\n\r\n نام او کرم شب تاب شد.\r\n\r\n خدا گفت : آن که نوری با خود دارد‚ بزرگ است‚ حتی اگربه قدر ذره ای باشد. تو حالا همان خورشیدی که گاهی زیر برگی کوچک پنهان می شوی.\r\n\r\nو رو به دیگران گفت : کاش می دانستید که این کرم کوچک ‚ بهترین را خواست. زیرا که از خدا جز خدا نباید خواست.\r\n\r\n هزاران سال است که او می تابد. روی دامن هستی می تابد. وقتی ستاره ای نیست چراغ کرم شب تاب روشن است و کسی نمی داند که این همان چراغی است که روزی خدا آن را به کرمی کوچک بخشیده است.\r\n"},{"id":1619,"category_id":10,"category_code":"s10","source_id":181,"title":"دلیل قانع کننده ","content":"مرد میانسالی وارد فروشگاه اتومبیل شد. آخرین مدل را دیده و پسندیده بود؛ پس وجه را پرداخت و سوار بر اتومبیل تندروی خود شد و از فروشگاه بیرون آمد.\r\n\r\nقدری راند و از شتاب اتومبیل لذّت برد. وارد بزرگراه شد و قدری بر سرعت اتومبیل افزود. کروکی اتومبیل را پایین داد تا باد به صورتش بخورد و لذّت بیشتری ببرد. چند شاخ مو بر بالای سرش در تب و تاب بود و با حرکت باد به این سوی و آن سوی می‌رفت. پای را بر پدال گاز فشرد و اتومبیل گویی پرنده‌ای بود رها شده از قفس. سرعت به ١٦٠ کیلومتر در ساعت رسید.\r\n\r\nمرد به اوج هیجان رسیده بود. نگاهی به آینه انداخت. دید اتومبیل پلیس به سرعت در پی او می‌آید و چراغ گردانش را روشن کرده و صدای آژیرش را نیز به اوج فلک رسانده است.\r\nمرد اندکی مردّد ماند که از سرعت بکاهد یا فرار را بر قرار ترجیح دهد. لَختی اندیشید. سپس برای آن که قدرت و سرعت اتومبیلش را بیازماید یا به رخ پلیس بکشد بر سرعتش افزود. به ١٨٠ رسید و سپس ٢٠٠ را پشت سر گذاشت، از ٢٢٠ گذشت و به ٢٤٠ رسید. اتومبیل پلیس از نظر پنهان شد و او دانست که پلیس را مغلوب کرده است.\r\n\r\nناگهان به خود آمد و گفت، \"مرا چه می‌شود که در این سنّ و سال با این سرعت می‎رانم؟ باشد که بایستم تا او بیاید و بدانم چه می‌خواهد.\" از سرعتش کاست و سپس در کنار جادّه منتظر ایستاد تا پلیس برسد.\r\n\r\nاتومبیل پلیس آمد و پشت سرش توقّف کرد. افسر پلیس به سوی او آمد، نگاهی به ساعتش انداخت و گفت، \"ده دقیقه دیگر وقت خدمتم تمام است. امروز جمعه است و قصد دارم برای تعطیلات چند روزی به مرخّصی بروم. سرعتت آنقدر بود که تا به حال نه دیده بودم و نه شنیده بودم. خصوصا اینکه به هشدار من توجهی نکردی و وقتی منو پشت سرت دیدی سرعتت رو بیشتر و بیشتر کرده و از دست پلیس فرار کردی. تنها اگر دلیلی قانع‌کننده داشته باشی که چرا به این سرعت می‌راندی، می‌گذارم بروی.\"\r\n\r\nمرد میانسال نگاهی به افسر کرد و گفت، \"می‌دونی، جناب سروان؛ سال‌ها قبل زن من با یک افسر پلیس فرار کرد. وقتی شما رو آژیر کشان پشت سرم دیدم، تصوّر کردم داری اونو برمی‌گردونی\"!\r\n\r\nافسر خندید و گفت: \"روز خوبی داشته باشید، آقا\" و برگشته سوار اتومبیلش شد و رفت.\r\n"},{"id":1620,"category_id":10,"category_code":"s10","source_id":182,"title":"لعنت بر شیطان ","content":"گفتم: «لعنت بر شیطان»!\r\nلبخند زد.\r\nپرسیدم: «چرا می خندی؟»\r\nپاسخ داد:«از حماقت تو خنده ام می گیرد»\r\nپرسیدم: «مگر چه کرده ام؟»\r\nگفت: «مرا لعنت می کنی در حالی که هیچ بدی در حق تو نکرده ام»\r\nبا تعجب پرسیدم: «پس چرا زمین می خورم؟!»\r\nجواب داد:\r\n«نفس تو مانند اسبی است که آن را رام نکرده ای. نفس تو هنوز وحشی است؛ تو را زمین می زند.»\r\nپرسیدم: «پس تو چه کاره ای؟»\r\nپاسخ داد: «هر وقت سواری آموختی، برای رم دادن اسب تو خواهم آمد؛ فعلاً برو سواری بیاموز. در ضمن این قدر مرا لعنت نکن!»\r\nگفتم: «پس حداقل به من بگو چگونه اسب نفسم را رام کنم؟»\r\nدر حالیکه دور می شد گفت: من پیامبر نیستم جوان...\r\n"},{"id":1621,"category_id":10,"category_code":"s10","source_id":183,"title":"کامیون حمل زباله ","content":"روزی من سوار یک تاکسی شدیم، و به فرودگاه رفتیم. \r\nما داشتیم در خط عبوری صحیح رانندگی می کردیم که ناگهان یک ماشین \r\nدرست در جلوی ما از جای پارک بیرون پرید. راننده تاکسی ام محکم ترمز گرفت. \r\nماشین سر خورد، و دقیقاً به فاصله چند سانتیمتر از ماشین دیگر متوقف شد! \r\nراننده ماشین دیگر سرش را ناگهان برگرداند و شروع کرد به ما فریاد زدن. راننده تاکسی ام \r\nفقط لبخند زد و برای آن شخص دست تکان داد.  منظورم این است که او واقعاً دوستانه برخورد\r\n کرد. \r\nبنابراین پرسیدم: ((چرا شما تنها آن رفتار را کردید؟ آن شخص نزدیک بود ماشین تان را از بین \r\nببرد و ما را \r\nبه بیمارستان بفرستد!))\r\nدر آن هنگام بود که راننده تاکسی ام درسی را به من داد که اینک به آن می\r\n گویم: \r\n((قانون کامیون حمل زباله.)) او توضیح داد که بسیاری از افراد مانند کامیون های حمل زباله\r\n هستند. \r\nآنها سرشار از ناکامی،  خشم، و ناامیدی ( زباله) در اطراف می گردند. وقتی زباله  در اعماق\r\n وجودشان \r\n تلنبار می شود، آنها به جایی احتیاج دارند تا آن را تخلیه کنند و گاهی اوقات روی شما خالی\r\n میکنند. \r\nبه خودتان نگیرید. فقط لبخند بزنید، دست تکان بدهید، برایشان آرزوی خیر بکنید، و بروید. \r\nزباله های آنها را نگیرید و پخش کنید به افراد دیگر ی در سرکار، در منزل، یا توی خیابان ها. \r\nحرف آخر این است که افراد موفق اجازه نمی دهند که کامیون های زباله  روزشان را بگیرند و\r\n خراب کنند. \r\nزندگی خیلی کوتاه است که صبح با تأسف ها از خواب برخیزید، از این رو..... ((افرادی را که با\r\n شما خوب رفتار می کنند \r\nدوست داشته باشید. برای آنهایی که رفتار مناسبی ندارند دعا کنید.)) \r\nزندگی ده درصد چیزی است که شما می سازید و نود درصد نحوه برداشت شماست.\r\n"},{"id":1622,"category_id":10,"category_code":"s10","source_id":184,"title":"حکایت آن درخت ","content":"در میان بنی اسرائیل عابدی بود. وی را گفتند:« فلان جا درختی است و قومی آن را می پرستند» عابد خشمگین شد، برخاست و تبر بر دوش نهاد تا آن درخت را برکند. ابلیس به صورت پیری ظاهر الصلاح، بر مسیر او مجسم شد، و گفت:« ای عابد، برگرد و به عبادت خود مشغول باش!» عابد گفت:« نه، بریدن درخت اولویت دارد» مشاجره بالا گرفت و درگیر شدند.\r\n\r\nعابد بر ابلیس غالب آمد و وی را بر زمین کوفت و بر سینه اش نشست. ابلیس در این میان گفت:\r\n«دست بدار تا سخنی بگویم، تو که پیامبر نیستی و خدا بر این کار تو را مامور ننموده است، به خانه برگرد، تا هر روز دو دینار زیر بالش تو نهم؛ با یکی معاش کن و دیگری را انفاق نما و این بهتر و صوابتر از کندن آن درخت است»؛ عابد با خود گفت :« راست می گوید، یکی از آن به صدقه دهم و آن دیگر هم به معاش صرف کنم» و برگشت.\r\n\r\nبامداد دیگر روز، دو دینار دید و بر گرفت. روز دوم دو دینار دید و برگرفت. روز سوم هیچ نبود. خشمگین شد و تبر برگرفت. باز در همان نقطه، ابلیس پیش آمد و گفت:«کجا؟» عابد گفت:«تا آن درخت برکنم»؛ گفت«دروغ است، به خدا هرگز نتوانی کند» در جنگ آمدند. ابلیس عابد را بیفکند چون گنجشکی در دست! عابد گفت: « دست بدار تا برگردم. اما بگو چرا بار اول بر تو پیروز آمدم و اینک، در چنگ تو حقیر شدم؟»\r\n\r\nابلیس گفت:« آن وقت تو برای خدا خشمگین بودی و خدا مرا مسخر تو کرد، که هرکس کار برای خدا کند، مرا بر او غلبه نباشد؛ ولی این بار برای دنیا و دینار خشمگین شدی، پس مغلوب من گشتی»\r\n"},{"id":1623,"category_id":10,"category_code":"s10","source_id":185,"title":"راز زندگی ","content":"در افسانه ها آمده روزی که خداوند جهان را آفرید\r\nفرشتگان مغرب را به بارگاه خود فراخواند\r\nو از آنها خواست تا برای پنهان کردن راز زندگی پیشنهاد بدهند\r\nیکی از فرشتگان به پروردگار گفت: آن را در زمین مدفون کن\r\nفرشته دیگری گفت آن را در زیر دریاها قرار بده\r\nسومی گفت راز زندگی را در کوهها قرار بده\r\nولی خداوند فرمود ....\r\nاگر من بخواهم به گفته های شما عمل کنم\r\nفقط تعداد کمی از بندگانم قادر خواهند بود آن را بیابند\r\nدر حال که من می خواهم راز زندگی در دستر س همه بندگانم باشد\r\nدر این هنگام یکی از فرشتگان گفت فهمیدم کجا ای خدای مهربان\r\nراز زندگی را در قلب بندگانت قرار بده\r\nزیرا هیچکس به این فکر نمی افتد که برای پیدا کردن آن باید به قلب\r\nو درون خودش نگاه کند و خداوند این فکر را پسندید\r\n"},{"id":1624,"category_id":10,"category_code":"s10","source_id":186,"title":"تأثیر حرف دیگران بر ما ","content":"مردی در کنار جاده، دکه ای درست کرد و در آن ساندویچ می فروخت. چون گوشش سنگین بود، رادیو نداشت. چشمش هم ضعیف بود، بنابراین روزنامه هم نمی خواند. او تابلویی بالای سر خود گذاشته بود و محاسن ساندویچ های  خود را شرح داده بود. خودش هم کنار دکه اش می ایستاد و مردم را به خریدن ساندویچ تشویق می کرد و مردم هم می خریدند.\r\n \r\n\r\nکارش بالا گرفت لذا او ابزار کارش را زیادتر کرد. وقتی پسرش از مدرسه نزد او آمد ....\r\nبه کمک او پرداخت. سپس کم کم وضع عوض شد. پسرش گفت: پدر جان، مگر  به اخبار رادیو گوش نداده ای؟ اگر وضع پولی کشور به همین منوال ادامه پیدا کند کار همه خراب خواهد شد و شاید یک کسادی عمومی به وجود می آید. باید خودت را برای این کسادی آماده کنی. پدر با خود فکر کرد هر چه باشد پسرش به مدرسه رفته به اخبار رادیو گوش می دهد و روزنامه هم می خواند پس حتماً آنچه می گوید صحیح است. بنابراین کمتر از گذشته نان و گوشت سفارش داده و تابلوی خود را هم پایین آورد و دیگر در کنار دکه خود نمی ایستاد و مردم را به خرید ساندویچ دعوت نمی کرد. فروش او ناگهان شدیداً کاهش یافت. او سپس رو به فرزند خود کرد و گفت: پسرجان حق با توست. کسادی عمومی شروع شده است.\r\n\r\n \r\nافغانی ها ضرب المثلی دارند بدین مضمون که اگر کسی به تو گفت اسب به او اعتمادنکن اما اگر دو نفر پیدا شندن و به تو گفتند کمی درباره خودت فکر کن. اما اگر سه نفر پیدا شندن و به تو گفتند که اسبی حتماً یک زین برای خودت سفارش بده. این ضرب المثل به خوبی اثر القائات منفی دیگران را بر ما نشان می دهد.\r\n \r\n\r\nآنتونی رابینز یک حرف بسیار خوب در این باره زده که جالبه بدونید: اندیشه های خود را شکل ببخشید در غیر اینصورت دیگران اندیشه های شما را شکل می دهند. خواسته های خود را عملی سازید وگرنه دیگران برای شما برنامه ریزی می کنند.\r\n \r\n\r\nدر واقع اون پدر داشت بهترین راه برای کاسبی رو انجام می داد اما به خاطر افکار پسرش، تصمیمش رو عوض کرد و افکار پسر اونقدر روی اون تأثیر گذاشت که فراموش کرد که خودش داره باعث ورشکستگی می شه و تلقین بحران مالی کشور، باعث شد که زندگی اون آدم عوض بشه.\r\n\r\n\r\nگاهی اوقات ما اونقدر به افکار دیگران توجه می کنیم و به اونها اعتماد بی خودی می کنیم که نه تنها زندگی خودمون رو خراب می کنیم بلکه حتی دیگه چیز دیگه ای رو نمی بینیم و چشمامون به روی  حقیقت ها   می بندیم.\r\n\r\n\r\nخداوند به همه ما فکر، فهم و شعور بخشیده تا بتونیم فرق بین خوب و بد رو تشخیص بدیم. بهتره قبل از اینکه دیگران برای ما تصمیماتی بگیرن که بعد ما رو پشیمون کنه، کمی فکر کنیم و راه درست رو انتخاب کنیم و با انتخاب یک هدف درست از زندگی لذت ببریم. چون زندگی مال ماست.\r\n"},{"id":1625,"category_id":10,"category_code":"s10","source_id":187,"title":"میخواهم معجزه بخرم ","content":"وقتی سارا دخترک هشت ساله‌ای بود، شنید که پدر و مادرش درباره برادر کوچکترش صحبت می‌کنند. فهمید که برادرش سخت بیمار است و آنها پولی برای مداوای او ندارند. پدر به تازگی کارش را از دست داده بود و نمی‌توانست هزینه جراحی پرخرج برادر را بپردازد. سارا شنید که پدر آهسته به مادر گفت: فقط معجزه می‌تواند پسرمان را نجات دهد\r\nسارا با ناراحتی به اتاق خوابش رفت و از زیر تخت قلک کوچکش را در آورد. قلک را شکست، سکه‌ها را روی تخت ریخت و آنها را شمرد، فقط پنج دلار!\r\n\r\nبعد آهسته از در عقبی خانه خارج شد و چند کوچه بالاتر به داروخانه رفت. جلوی پیشخوان انتظار کشید تا داروساز به او توجه کند ولی داروساز سرش شلوغ‌تر از آن بودکه متوجه بچه‌ای هشت ساله شود\r\nدخترک پاهایش را به هم می‌زد و سرفه می‌کرد ولی داروساز توجهی نمی‌کرد. بالاخره حوصله سارا سر رفت و سکه‌ها را محکم روی شیشه پیشخوان ریخت.....\r\nداروساز جا خورد، رو به دخترک کرد و گفت: چه می‌خواهی؟\r\nدخترک جواب داد:‌ برادرم خیلی مریض است، میخواهم معجزه بخرم.\r\nداروساز با تعجب پرسید: ببخشید؟!\r\nدخترک توضیح داد: برادر کوچک من، داخل سرش چیزی رفته و بابایم می‌گوید که فقط معجزه می تواند او را نجات دهد. من میخواهم معجزه بخرم، قیمتش چند است؟!\r\nداروساز گفت: متأسفم دختر جان، ولی ما اینجا معجزه نمی‌فروشیم.\r\n\r\nچشمان دخترک پر از اشک شد و گفت: شما را به خدا، او خیلی مریض است، بابایم پول ندارد تا معجزه بخرد این هم تمام پول من است، من کجا می‌توانم معجزه بخرم؟\r\n\r\nمردی که گوشه ایستاده بود و لباس تمیز و مرتبی داشت، از دخترک پرسید چقدر پول داری؟\r\nدخترک پولها را کف دستش ریخت و به مرد نشان داد. مرد لبخندی زد و گفت: آه چه جالب، فکر می‌کنم این پول برای خرید معجزه برادرت کافی باشد!\r\nبعد به آرامی دست او را گرفت و گفت:‌ من میخواهم برادر و والدینت را ببینم، فکر می‌کنم معجزه برادرت پیش من باشد.\r\nآن مرد دکتر آرمسترانگ فوق تخصص مغز و اعصاب در شیکاگو بود\r\nفردای آن روز عمل جراحی روی مغز پسرک با موفقیت انجام شد و او از مرگ نجات یافت\r\nپس از جراحی، پدر نزد دکتر رفت و گفت: از شما متشکرم، نجات پسرم یک معجزه واقعی بود. می‌خواهم بدانم بابت هزینه عمل جراحی چقدر باید پرداخت کنم؟\r\nدکتر لبخندی زد و گفت:‌ فقط پنج دلار\r\n"},{"id":1626,"category_id":10,"category_code":"s10","source_id":188,"title":"خدایا شکر ","content":"روزی مردی خواب عجیبی دید.\r\nدید که پیش فرشته هاست و به کارهای آنها نگاه می کند. هنگام ورود، دسته بزرگی از فرشتگان را دیدکه سخت مشغول کارند و تند تند نامه هایی را که توسط پیک ها از زمین می رسند، باز می کنند و آنها را داخل جعبه می گذارند. مرد از فرشته ای پرسید: شما چکار می کنید؟ فرشته در حالی که داشت نامه ای را باز می کرد، گفت: اینجا بخش دریافت است و ما دعاها و تقاضاهای مردم از خداوند را تحویل می گیریم.\r\n\r\nمرد کمی جلوتر رفت. باز تعدادی از فرشتگـــان را دید که کاغذهـایی را داخل پاکت می گذارند و آن ها را توسط پیک هایی به زمین می فرستند.\r\n\r\nمرد پرسید:\r\nشماها چکار می کنید؟ یکی از فرشتگان با عجله گفت: اینجا بخش ارسال است، ما الطاف و رحمت های خداوند را برای بندگان به زمین می فرستیم.\r\n\r\nمرد کمی جلوتر رفت و یک فرشته را دید که بیکار نشسته است. با تعجب از فرشته پرسید: شما چرا بیکارید؟\r\n\r\nفرشته جواب داد: اینجا بخش تصدیق جواب است. مردمی که دعاهایشان مستجاب شده، باید جواب بفرستند ولی فقط عده بسیار کمی جواب می دهند.\r\n\r\nمرد از فرشته پرسید: مردم چگونه می توانند جواب بفرستند؟\r\n\r\nفرشته پاسخ داد: بسیار ساده، فقط کافیست بگویند: خدایا شکر.\r\n"},{"id":1627,"category_id":10,"category_code":"s10","source_id":189,"title":"معجون آرامش ","content":"کسری انوشیروان بر بزرگمهر خشم گرفت و در خانه ای تاریک به زندانش فکند و فرمود او را به زنجیر بستند.چون روزی چند بر این حال بود،کسری کسانی را فرستاد تا از حالش پرسند. آنان بزرگمهر را دیدند با دلی قوی و شادمان.بدو گفتند:در این تنگی و سختی تو را آسوده دل می بینم!\r\n\r\nگفت:معجونی ساخته ام از شش جزئ و به کار می برم و چنین که می بینید مرا نیکو می دارد.\r\n\r\nگفتند:\r\nآن معجون را شرح بازگوی که ما را نیز هنگام گرفتاری به کار آید\r\n\r\nگفت:آری جزئ نخست اعتماد بر خدای است ،عزوجل،دوم آنچه مقدر است بودنی است،سوم شکیبایی برای گرفتار بهترین چیزهاست.چهارم اگر صبر نکنم چه کنم،پس نفس خویش را به جزع و زاری بیش نیازارم،پنجم آنکه شاید حالی سخت تر از این رخ دهد.ششم آنکه از این ساعت تا ساعت دیگر امید گشایش باشد چون این سخنان به کسری رسید او را آزاد کرد و گرامی داشت.\r\n"},{"id":1628,"category_id":10,"category_code":"s10","source_id":190,"title":"زاهد کیست! ","content":"درویشی نزد پادشاهی رفت.پادشاه گفت :«ای زاهد!» درویش گفت :«زاهد تویی!» پادشاه پرسید :«من چگونه زاهد باشم هنگامی که همه  دنیا از آن من است؟» درویش گفت :«نه،وارونه می بینی.این دنیا و آن دنیا برای من است.زمین در مشت من جای دارد.این تو هستی که از این همه چیز،به لقمه ای و جامه ای خرسند شده ای!»....\r\nزاهد آن کسی است که آخر ببیند،دوستاران دنیا آخور می بینند.در هر راهی،این درد است که آدم را با خود می برد.در همه کارها تا درد  هوس و عشق در درون کسی بر نخیزد،او در آن کار به جایی نمی رسد.از کار دنیا گرفته تا کار آخرت؛خواه بازرگانی،خواه پادشاهی،خواه دانش،خواه هنر. تا درد زایمان به درون مریم چنگ نینداخت،به سراغ آن درخت نرفت.آن درد،در جان آن درخت نیز پیچید و آنگاه از تن خشک و سترون او،شکوفه ها جوشید و میوه ها زایید.ما نیز در اندرون خود همچون مریم،عیسایی پنهان داریم.اگر در ما،دردی پیدا شود،عیسای  ما نیز زاییده خواهد شد وگرنه؛از همان راه پنهانی باز خواهد گشت.\r\n"},{"id":1629,"category_id":10,"category_code":"s10","source_id":191,"title":"نشانه عشق ","content":"پسری جوان که یکی از مریدان شیفته شیوانا بود، چندین سال نزد استاد درس معرفت و عشق می آموخت. شیوانا نام او را \"ابر نیمه تمام\" گذاشته بود و به احترام استاد بقیه شاگردان نیز او را به همین اسم صدا می زدند. روزی پسر نزد شیوانا آمد و گفت دلباخته دختر آشپز مدرسه شده است و نمی داند چگونه عشقش را ابراز کند!؟ شیوانا از \"ابر نیمه تمام\" پرسید:\" چطور فهمیدی که عاشق شده ای؟!\"\r\nپسر گفت:\" هرجا می روم به یاد او هستم. وقتی می بینمش نفسم می گیرد و ضربان قلبم تند می شود. در مجموع احساس خوبی نسبت به او دارم و بر این باورم که می توانم بقیه عمرم را در کنار او زندگی کنم!\"\r\nشیوانا گفت:...\r\n\" اما پدر او آشپز مدرسه است و دخترک نیز مجبور است به پدرش در کار آشپزی کمک کند. آیا تصور می کنی می توانی با کسی ازدواج کنی که برای بقیـه همکلاسی هایت غذا می پزد و ظرف های غذای آنها را تمیز می کند.\"\r\n\"ابرنیمه تمام\" کمی در خود فرو رفت و بعد گفت:\" به این موضوع فکر نکرده بودم. خوب این نقطه ضعف مهمی است که باید در نظر می گرفتم.\"\r\nشیوانا تبسمی کرد و گفت:\" پس بدان که عشق و احساس تو به این دختر هوسی زودگذر و التهابی گذرا بیش نیست و بی جهت خودت و او را بی حیثیت مکن!\"\r\nدو هفته بعد \"ابر نیمه تمام\" نزد شیوانا آمد و گفت که نمی تواند فکر دختر آشپز را از سر بیرون کند. هر جا می رود او را می بیند و به هر چه فکر می کند اول و آخر فکرش به او ختم می شود.\" شیوانا تبسمی کرد و گفت:\" اما دخترک نصف صورتش زخم دارد و دستانش به خاطر کار، ضخیم و کلفت شده است. به راستی بد نیست که همسر تو فردی چنین زشت و خشن باشد. آیا به زیبایی نه چندان زیاد او فکر کرده ای! شاید علت این که تا الان تردید کرده ای و قدم پیش نگذاشته ای همین کم بودن زیبایی او باشد؟!\" پسر کمی در خود فرو رفت و گفت:\" حق با شماست استاد! این دخترک کمی هم پیر است و چند سال دیگر  شکسته می شود. آن وقت من باید با یک مادربزرگ تا آخر عمر سر کنم!\"\r\nشیوانا تبسمی کرد و گفت:\" پس بدان که عشق و احساس تو به این دختر هوسی زودگذر است و التهابی گذرا بیش نیست پس بی جهت خودت و او را بی حیثیت مکن!\"\r\nپسرک راهش را کشید و رفت. یکی از شاگردان خطاب به شیوانا گفت که چرا بین عشق دو جوان شک و تردید می اندازید و مانع از جفت شدن آنها می شوید. شیوانا تبسمی کرد و پاسخ داد:\" هوس لازمه جفت شدن دو نفر نیست. عشق لازم است و \"ابر نیمه تمام\" هنوز چیزهای دیگر را بیشتر از دختر آشپز دوست دارد.\"\r\nیک ماه بعد خبر رسید که \"ابر نیمه تمام\" بی اعتنا به شیوانا و اندرزهای او درس و مشق را رها کرده است و نزد دختر آشپز رفته و او را به همسری خود انتخاب کرده است و چون شغلی نداشته است در کنار پدر همسر خود به عنوان کمک آشپز استخدام شده است.\r\nیکی از شاگردان نزد شیوانا آمد و در مقابل جمع به بدگویی \"ابر نیمه تمام\" پرداخت و گفت: \" این پسر حرمت استاد و مدرسه را زیر پا گذاشته است و به جای آموختن عشق و معرفت در حضور شما به سراغ آشپزی رفته است. جا دارد او را به خاطر این بی حرمتی به مرام عشق و معرفت از مدرسه بیرون کنید؟!\"\r\nشیوانا تبسمی کرد و گفت:\"دیگر کسی حق ندارد به کمک آشپز جدید مدرسه \"ابر نیمه تمام\" بگوید. از این پس نام او \"تمام آسمان\" است. اگر من از این به بعد در مدرسه نبودم سوالات خود در مورد عشق و معرفت را از \"تمام آسمان\" بپرسید. همه این درس و معرفت برای این است که به مرحله و درک \"تمام آسمان \" برسید. او اکنون معنای عملی و واقعی عشق را در رفتار و کردار خود نشان داده است.\"\r\n"},{"id":1630,"category_id":10,"category_code":"s10","source_id":192,"title":"از حرف تا عمل ","content":"در زمـان پـیـغمبر اکرم (ص ), طفلى بسیار خرما مى خورد.\r\nهر چه اورا نصیحت مى کردند که زیاد خوردن خرما ضرر دارد, فایده نداشت .\r\nمادرش تصمیم گرفت او را به نزد پیغمبر(ص ) بیاورد تا او را نـصـیـحت کند.\r\nوقتى او را به حضور پیغمبر آورد, از پیغمبر خواست تا به طفل بفرماید که خرما نخورد, اما آن حضرت فرمود: امروز بروید و او رافردا دوباره بیاورید.\r\nروز دیـگر....\r\nزن به همراه فرزندش خدمت پیغمبر(ص ) حاضر شد.حضرت به کودک فرمود که خرما نـخورد.\r\nدر این هنگام زن , که نتوانست کنجکاوى و تعجب خود را مخفى کند, از ایشان سؤال کرد: یارسول اللّه , چرا دیروز به او نفرمودید خرما نخورد؟\r\nحـضـرت فـرمـود: دیـروز وقتى این کودک را حاضر کردید, خودم خرما خورده بودم و اگر او را نصیحت مى کردم , تاثیرى نداشت .\r\nامـام صـادق (ع ) فـرمود: به راستى هنگامى که عالم به علم خودعمل نکرد, موعظه او در دل هاى مردم اثر نمى کند, همان طور که باران از روى سنگ صاف مى لغزد و در آن نفوذ نمى کند !\r\n"},{"id":1631,"category_id":10,"category_code":"s10","source_id":193,"title":"ادعای خدایی","content":"می گویند ابلیس، زمانی نزد فرعون آمد در حالیکه فرعون خوشه ای انگور در دست\r\n\r\nداشت و می خورد.ابلیس به او گفت: هیچکس می تواندکه این خوشهء انگور را به\r\n\r\nمروارید خوش آب و رنگ مبدل سازد؟ فرعون گفت:\r\nنه. ابلیس با جادوگری و سحر، آن\r\n\r\n خوشهء انگور را به دانه های مروارید خوشاب تبدیل کرد. فرعون تعجب کرد و گفت:\r\n\r\nآفرین بر تو که استاد و ماهری. ابلیس سیلی ای بر گردن او زد و گفت: مرا با این\r\n\r\nاستادی به بندگی قبول نکردند، تو با این حماقت چگونه دعوی خدایی می کنی؟ \r\n"},{"id":1632,"category_id":10,"category_code":"s10","source_id":194,"title":"پا یا کفش ؟! ","content":"کفش هایش انگشت نما شده بود و جیبش خالی!\r\nیک روز دل انگیز بهاری از کنار مغازه ای می گذشت ؛ مأیوسانه به کفشها نگاه می کرد و غصه ی نداشتن بر همه ی وجودش چنگ انداخته بود .\r\nناگاه! جوانی کنارش ایستاد ، سلام کرد و با خنده گفت :...\r\nچه روز قشنگی ! مرد به خود آمد ، نگاهی به جوان انداخت و از تعجب دهانش باز ماند! جوان خوش سیما و خنده بر لب ، پا نداشت . پاهایش از زانو قطع بود! مرد هاج و واج ، پاسخ سلامش را داد ؛ سر شرمندگی پایین آورد و عرق کرده ، دور شد .\r\nلحظاتی بعد ، عقل گریبانش را گرفته بود و بر او نهیب می زد که : غصه می خوردی که کفش نداری و از زندگی دلگیر بودی ؛ دیدی آن جوانمرد را که پا نداشت ؛ اما خوشخال بود از زندگی خوشنود !\r\n به خانه که رسید از رضایت لبریز بود...\r\n"},{"id":1633,"category_id":10,"category_code":"s10","source_id":195,"title":"همه امور را به خدا بسپار ","content":"مردی ثروتمند وجود داشت که همیشه پر از اضطراب و دلواپسی بود . با اینکه از همه ثروتهای مادی دنیا بهرهمند بود قلبش هیچگاه شاد نبود .\r\nاو خدمتکاری داشت که ایمان به خداوند درونش موج می زد.\r\nروزی خدمتکار وقتی که دید مرد تا حد مرگ نگران است به او گفت \" ارباب , آیا حقیقت ندارد که خداوند پیش از به دنیا آمدن شما جهان را اداره می کرده است ؟ \"\r\nاو پاسخ داد : \" بله \"....\r\nخدمتکار پرسید \" آیا درست است که خداوند پس از آنکه شما دنیا را ترک کردید آن را اداره میکند . \"\r\nارباب دوباره پاسخ داد \"بله\"\r\nخدمتکار گفت : \"پس چطور است به خداوند اجازه بدهید وقتی که شما در این دنیا هستید او آن را اداره کند؟\"\r\nبه او اعتماد کن, وقتی که تردید های تیره به تو هجوم می آورد !\r\nبه او اعتماد کن , وقتی که نیرویت کم است!\r\nبه او اعتماد کن , زیرا وقتی که به سادگی به او اعتماد کنی , اعتمادت سخت ترین چیز ها خواهد بود.\r\nآیا راه سخت و ناهموار است؟.\r\nآن را به خدا بسپار . !\r\nآیا می کاری و برداشت نمی کنی؟\r\nآن را به خدا بسپار.\r\nاراده انسانی خود را به او واگذار .\r\nبا تواضع گوش کن و خاموش باش.\r\nذهن تو از عشق الهی لبریز می شود .\r\nآن را به خدا بسپار !\r\nدر این دنیای گذارا دنیایی که چیزها می آیند و می روند , هیچ چیز باقی نمی ماند .پس آیا چیزی ارزش نگران شدن دارد.\r\n"},{"id":1634,"category_id":10,"category_code":"s10","source_id":196,"title":"پسرک بیسکویت فروش ","content":"خانم تورو خدا بیاین بیسکوییت بخرین ارزونه فقط پنجاه تومان\r\nزن به او مینگرد و در حالی که به وی مینگرد فقط میگوید:\r\nیک دونه بده ولی فردا مییام ازت صد تا میخرم چون نذر دارم فردام اینجا هستی؟\r\n-آره خانم من همیشه اینجام فردام می یام و واسه شما صد تا بیسکوییت نگه میدارم\r\n\r\nسلام آقا پسر ....\r\nلطفا بیسکوییتای منو بده که زود باید برم\r\nپسرک از اینکه صد تا بیسکوییت را یک جا فروخته و میتواند مادر بیمارش را به نزد پزشک ببرد خوشحال است.\r\n\r\n-سلام پسرم آماده شم بریم دکتر\r\nدر یک لحظه دست پسرک در جیبش گیر میکند و جز یک سوراخ بزرگ چیزی در آنجا پیدا نمیکند.\r\n\r\nدر آن طرف شهر پسری در پیتزا فروشی مشغول خوردن پیتزاست.\r\n"},{"id":1635,"category_id":10,"category_code":"s10","source_id":197,"title":"دریا باش ","content":"روزی شاگرد یه راهب پیر هندو از او خواست که بهش  یه درس به یاد موندنی بده\r\n\r\nراهب از شاگردش خواست کیسه نمک رو بیاره پیشش ، بعد یه مشت از اون نمک رو داخل لیوان نیمه پری ریخت و از او خواست اون آب رو سر بکشه .\r\n\r\nشاگرد فقط تونست یه جرعه کوچک از آب داخل لیوان رو بخوره ، اونم بزحمت .\r\n\r\nاستاد پرسید : \" مزه اش چطور بود ؟ \"\r\n\r\nشاگرد پاسخ داد :...\r\n\" بد جوری شور و تنده ، اصلا نمیشه خوردش \"\r\n\r\nپیر هندو از شاگردش خواست یه مشت نمک برداره و اونو همراهی کنه . رفتند تا رسیدن کنار دریاچه . استاد از او خواست تا نمکها رو داخل دریاچه بریزه ، بعد یه لیوان آب از دریاچه برداشت و داد دست شاگرد و ازش خواست اونو بنوشه . شاگرد براحتی تمام آب داخل لیوان رو سر کشید .\r\n\r\nاستاد اینبارهم از او مزه آب داخل لیوان رو پرسید. شاگرد پاسخ داد : \" کاملا معمولی بود . \"\r\n\r\n\r\nپیر هندو گفت :\r\n\r\nرنجها و سختیهائی که انسان در طول زندگی با آنها روبرو میشه همچون یه مشت نمکه و اما این روح و قدرت پذیرش انسانه که هر چه بزرگتر و وسیعتر بشه ، میتونه بار اون همه رنج و اندوه رو براحتی تحمل کنه ، بنابراین سعی کن یه دریا باشی تا یه لیوان آب.\r\n"},{"id":1636,"category_id":10,"category_code":"s10","source_id":198,"title":"خانه ای با پنجره های طلایی ","content":"پسر کوچکی در مزرعه ای دور دست زندگی می کرد هر روز صبح قبل از طلوع خورشید از خواب برمی خواست وتا شب به کارهای سخت روزانه مشغول بود\r\n\r\nهم زمان با طلوع خورشید از نردها بالا می رفت تا کمی استراحت کند در دور دست ها خانه ای با پنجرهایی طلایی همواره نظرش را جلب می کرد و با خود فکر می کرد چقدر زندگی در آن خانه با آن وسایل شیک و مدرنی که باید داشته باشد لذت بخش و عالی خواهد بود . با خود می گفت : \" اگر آنها قادرند پنجره های خود را از طلا بسازند پس سایر اسباب خانه حتما بسیار عالی خواهد بود . بالاخره یک روز به آنجا می روم و از نزدیک آن را می بینم \".....\r\nیک روز پدر به پسرش گفت به جای او کارها را انجام می دهد و او می تواند در خانه بماند . پسر هم که فرصت را مناسب دید غذایی برداشت و به طرف آن خانه و پنجره های طلایی رهسپار شد .\r\nراه بسیار طولانی تر از آن بود که تصورش را می کرد . بعد از ظهر بود که به آن جا رسید و با نزدیک شدن به خانه متوجه شد که از پنجره های طلایی خبری نیست و در عوض خانه ای رنگ و رو رفته و با نرده های شکسته دید . به سمت در قدیمی رفت و آن را به صدا در آورد . پسر بچه ای هم سن خودش در را گشود . سوال کرد که آیا او خانه پنجره طلایی را دیده است یا خیر ؟ پسرک پاسخ مثبت داد و او را به سمت ایوان برد . در حالی که آنجا می نشستند نگاهی به عقب انداختند و در انتهای همان مسیری که طی کرده بود و هم زمان با غروب آفتاب , خانه خودشان را دید که با پنجره های طلایی می درخشید.\r\n"},{"id":1637,"category_id":10,"category_code":"s10","source_id":199,"title":"موهبت الهی ","content":"روزی مردی خواب دید که مرده و پس از گذشتن از پلی به دروازه بهشت رسیده است. دربان بهشت به مرد گفت: برای ورود به بهشت\r\n\r\nباید صد امتیاز داشته باشید، کارهای خوبی را که در دنیا انجام داده اید، بگوئید تا من به شما امتیاز بدهم.\r\n\r\nمرد گفت: من با همسرم ازدواج کردم، 50 سال با او به مهربانی رفتار کردم و هرگز به او خیانت نکردم.\r\n\r\nفرشته گفت: این سه امتیاز.\r\n\r\nمرد اضافه کرد:\r\nمن در تمام طول عمرم به خداوند اعتقاد داشتم و حتی دیگران را هم به راه راست هدایت می کردم.\r\n\r\nفرشته گفت: این هم یک امتیاز.\r\n\r\nمرد باز ادامه داد: در شهر نوانخانه ای ساختم و کودکان بی خانمان را آنجا جمع کردم و به آنها کمک کردم.\r\n\r\nفرشته گفت: این هم دو امتیاز.\r\n\r\nمرد در حالی که گریه می کرد گفت: با این وضع من هرگز نمی توانم داخل بهشت شوم مگر اینکه خداوند لطفش را شامل حال من کند.\r\n\r\n\r\nفرشته لبخندی زد و گفت: بله، تنها راه ورود بشر به بهشت موهبت الهی است و اکنون این لطف شامل حال شما شد و اجازه ورود به بهشت برایتان صادر شد !!\r\n"},{"id":1638,"category_id":10,"category_code":"s10","source_id":200,"title":"تصویر آرامش ","content":"پادشاهی جایزه بزرگی برای هنرمندی گذاشت که بتواند به بهترین شکل ، آرامش را تصویر کند.\r\n\r\nنقاشان بسیاری آثار خود را به قصر فرستادند. آن تابلو ها ، تصاویری بودند از جنگل به هنگام غروب ، رودهای آرام ، کودکانی که در خاک می دویدند ، رنگین کمان در آسمان ، و قطرات شبنم بر گلبرگ گل سرخ.\r\n\r\nپادشاه تمام تابلو ها را بررسی کرد ، اما سرانجام فقط دو اثر را انتخاب کرد.\r\n\r\nاولی ، تصویر دریاچه ی آرامی بود که....\r\nکوههای عظیم و آسمان آبی را در خود منعکس کرده بود. در جای جایش می شد ابرهای کوچک و سفید را دید، و اگر دقیق نگاه می کردند، در گوشه ی چپ دریاچه، خانه ی کوچکی قرار داشت، پنجره اش باز بود، دود از دودکش آن بر می خواست، که نشان می داد شام گرم و نرمی آماده است.\r\n\r\nتصویر دوم هم کوهها را نمایش می داد. اما کوهها ناهموار بود ، قله ها تیز و دندانه ای بود. آسمان بالای کوهها بطور بیرحمانه ای تاریک بود، و ابرها آبستن آذرخش، تگرگ و باران سیل آسا بود. این تابلو با تابلو های دیگری که برای مسابقه فرستاده بودند، هیچ هماهنگی نداشت.اما وقتی آدم با دقت به تابلو نگاه می کرد، در بریدگی صخره ای شوم، جوجه پرنده ای را می دید.آنجا، در میان غرش وحشیانه ی طوفان ، جوجه گنجشکی ، آرام نشسته بود.\r\n\r\nپادشاه درباریان را جمع کرد و اعلام کرد که برنده ی جایزه ی بهترین تصویر آرامش، تابلو دوم است.بعد توضیح داد :\r\n\r\nآرامش چیزی نیست که در مکانی بی سر و صدا ، بی مشکل ، بی کار سخت یافت می شود ، بلکه معنای حقیقی آرامش این است که هنگامیکه شرایط سختی بر ما می گذرد آرامش در قلب ما حفظ شود.\r\n"},{"id":1639,"category_id":10,"category_code":"s10","source_id":201,"title":"دزد جوانمردی! ","content":"اسب سواری ، مرد چلاق و افلیجی را سر راه خود دید که از او کمک می خواست . مرد سوار دلش به حال او سوخت . از اسب پیاده شد و او را از جا بلند کرد و روی اسب گذاشت تا او را به مقصد برساند .\r\nمرد چاق وقتی بر اسب سوار شد ، دهنه ی اسب را کشید و گفت : ...\r\nاسب را بردم ، و با اسب گریخت! اما پیش از آنکه دور شود صاحب اسب داد زد : تو ، تنها اسب را نبردی ، جوانمردی را هم بردی!\r\nاسب مال تو ؛ اما گوش کن ببین چه می گویم! مرد چلاق اسب را نگه داشت . مرد سوار گفت : هرگز به هیچ کس نگو چگونه اسب را به دست آوردی ؛ زیرا می ترسم که دیگر « هیچ سواری » به پیاده ای رحم نکند!\r\n"},{"id":1640,"category_id":10,"category_code":"s10","source_id":202,"title":"قدرت دعا ","content":"زنی بود با لباسهای کهنه و مندرس ، و نگاهی مغموم . وارد خواربار فروشی محله شد و با\r\nفروتنی از صاحب مغازه خواست کمی خواروبار به او بدهد . به نرمی گفت شوهرش بیمار است و نمی‌تواند کار کند و شش بچه‌شان بی غذا مانده‌اند جان لانگ هاوس ،صاحب مغازه ، با بی‌اعتنایی محلش نگذاشت و با حالت بدی خواست او را بیرون کند .\r\nزن نیازمند در حالی که اصرار می‌کرد گفت : «آقا شما را به خدا به محض اینکه بتوانم پولتان را می‌آورم .»\r\nجان گفت نسیه نمی‌دهد .مشتری دیگری که کنار پیشخوان ایستاده بود و گفت و گوی آن دو را می‌شنید به مغازه دار گفت :...\r\n«ببین این خانم چه می‌خواهد؟خرید این خانم با من .»\r\nخواربار فروش گفت :لازم نیست خودم می‌دهم لیست خریدت کو ؟\r\nزن گفت : اینجاست .\r\n- « لیست ‌ات را بگذار روی ترازو به اندازه ی وزنش هر چه خواستی ببر . » !!\r\nزن با خجالت یک لحظه مکث کرد، از کیفش تکه کاغذی درآورد و چیزی رویش نوشت و آن را روی کفه ترازو گذاشت . همه با تعجب دیدند کفه ی ترازو پایین رفت .\r\nخواربارفروش باورش نمی‌شد .\r\nمشتری از سر رضایت خندید .\r\nمغازه‌دار با ناباوری شروع به گذاشتن جنس در کفه ی دیگر ترازو کرد کفه ی ترازو برابر نشد ، آن قدر چیز گذاشت تا کفه‌ها برابر شدند .\r\nدر این وقت ، خواربار فروش با تعجب و دل‌خوری تکه کاغذ را برداشت ببیند روی آن چه نوشته است .\r\nکاغذ لیست خرید نبود، دعای زن بود که نوشته بود (ای خدای عزیزم! تو از نیاز من باخبری خودت آن را برآورده کن) . مغازه ‌دار با بهت جنسها را به زن داد و همان جا ساکت و متحیر خشکش زد. زن خداحافظی کرد و رفت. مشتری یک اسکناس باارزش به مغازه ‌دار داد و گفت: فقط خداست که می‌‌داند وزن دعای پاک و خالص چقدر است ؟\r\n"},{"id":1641,"category_id":10,"category_code":"s10","source_id":203,"title":"انعکاس ","content":"پدر و پسری داشتند در کوه قدم میزدند که ناگهان پای پسر به سنگی گیر کرد. به زمین افتاد و داد کشید: آآی ی ی ی!\r\n\r\nصدایی از دور دست آمد: آآی ی ی ی!\r\n\r\nپسرک با کنجکاوی فریاد زد: کی هستی؟\r\n\r\nپاسخ شنید: کی هستی؟\r\n\r\nپسرک خشمگین شد و فریاد زد: ترسو!\r\n\r\nباز پاسخ شنید: ترسو!\r\n\r\nپسرک با تعجب ازپدرش پرسید: چه خبر است؟\r\n\r\nپدر لبخندی زد و گفت: پسرم خوب توجه کن....\r\nو بعد با صدای بلند فریاد زد: تو یک قهرمان هستی!\r\n\r\nصدا پاسخ داد: تو یک قهرمان هستی!\r\n\r\nپسرک باز بیشتر تعجب کرد.پدرش توضیح داد: مردم میگویند که این انعکاس کوه است ولی این در حقیقت انعکاس زندگی است.\r\n\r\nهر چیزی که بگویی یا انجام دهی،زندگی عینا\" به تو جواب میدهد؛ اگر عشق را بخواهی، عشق بیشتری در قلب بوجود می آید و\r\n\r\nاگر به دنبال موفقیت باشی، آن را حتما بدست خواهی آورد. هر چیزی را که بخواهی، زندگی همان را به تو خواهد داد!\r\n"},{"id":1642,"category_id":10,"category_code":"s10","source_id":204,"title":"امید ","content":"تنها بازمانده یک کشتی شکسته توسط جریان آب به یک جزیره دورافتاده برده شد، او با بیقراری به درگاه خداوند دعا می‌کرد تا او را نجات بخشد، او ساعتها به اقیانوس چشم می‌دوخت، تا شاید نشانی از کمک بیابد اما هیچ چیز به چشم نمی‌آمد.\r\nسرآخر ناامید شد و تصمیم گرفت که کلبه ای کوچک خارج از ساحل بسازد ....\r\nتا از خود و وسایل اندکش را بهتر محافظت نماید، روزی پس از آنکه از جستجوی غذا بازگشت، خانه کوچکش را در آتش یافت، دود به آسمان رفته بود، بدترین چیز ممکن رخ داده بود، او عصبانی و اندوهگین فریاد زد: «خدایا چگونه توانستی با من چنین کنی؟»\r\n\r\n\r\nصبح روز بعد او با صدای یک کشتی که به جزیره نزدیک می‌شد از خواب برخاست، آن می‌آمد تا او را نجات دهد.\r\n\r\n\r\nمرد از نجات دهندگانش پرسید: «چطور متوجه شدید که من اینجا هستم؟»\r\nآنها در جواب گفتند: «ما علامت دودی را که فرستادی، دیدیم!»\r\n"},{"id":1643,"category_id":10,"category_code":"s10","source_id":205,"title":"باغ انار ","content":"زمانی‌ که بچه بودیم، باغ انار بزرگی داشتیم که ما بچه ها خیلی دوست\r\nداشتیم، تابستونا که گرمای شهر طاقت فرسا میشد، برای چند هفته ای کوچ میکردیم\r\nبه این باغ خوش آب و هوا که حدوداً ۳۰ کیلومتری با شهر فاصله داشت، اکثراً\r\nفامیل های نزدیک هم برای چند روزی میومدن و با بچه هاشون، در این باغ مهمون\r\nما بودن، روزهای بسیار خوش و خاطره انگیزی ما در این باغ گذروندیم اما خاطره ای\r\nکه میخوام براتون تعریف کنم، شاید زیاد خاطره خوشی نیست اما درس بزرگی شد برای\r\nمن در زندگیم!.....\r\nتا جایی که یادمه، اواخر شهریور بود، همه فامیل اونجا جمع بودن چونکه وقت جمع\r\nکردن انارها رسیده بود، ۸-۹ سالم بیشتر نبود، اون روز تعداد زیادی از کارگران\r\nبومی در باغ ما جمع شده بودن برای برداشت انار، ما بچه ها هم طبق معمول مشغول\r\nبازی کردن و خوش گذروندن بودیم!\r\n\r\nبزرگترین تفریح ما در این باغ، بازی گرگم به هوا بود اونم بخاطر درختان\r\nزیاد انار و دیگر میوه ها و بوته ای انگوری که در این باغ وجود داشت، بعضی وقتا\r\nمیتونستی، ساعت ها قائم شی، بدون اینکه کسی بتونه پیدات کنه!\r\nبعد از نهار بود که تصمیم به بازی گرفتیم، من زیر یکی از این درختان قایم\r\nشده بودم که دیدم یکی از کارگرای جوونتر، در حالی که کیسه سنگینی پر از انار در\r\nدست داشت، نگاهی به اطرافش انداخت و وقتی که مطمئن شد که کسی اونجا نیست، شروع\r\nبه کندن چاله ای کرد و بعد هم کیسه انارها رو اونجا گذاشت و دوباره این چاله رو\r\nبا خاک پوشوند، دهاتی ها اون زمان وضعشون خیلی اسفناک بود و با همین چند تا\r\nانار دزدی، هم دلشون خوش بود!\r\n\r\nبا خودم گفتم، انارهای مارو میدزی! صبر کن بلایی سرت بیارم که دیگه از این غلطا\r\nنکنی، بدون اینکه خودمو به اون شخص نشون بدم به بازی کردن ادامه دادم، به هیچ\r\nکس هم چیزی در این مورد نگفتم!\r\nغروب که همه کار گرها جمع شده بودن و میخواستن مزدشنو از بابا بگیرن، من هم\r\nاونجا بودم، نوبت رسید به کارگری که انارها رو زیر خاک قایم کرده بود، پدر در\r\nحال دادن پول به این شخص بود که من با غرور زیاد با صدای بلند گفتم، بابا\r\nمن دیدم که علی‌ اصغر، انارها رو دزدید و زیر خاک قایم کرد! جاشم میتونم به همه\r\nنشون بدم، این کارگر دزده و شما نباید بهش پول بدین!\r\nپدر خدا بیامرز ما، هیچوقت در عمرش دستشو رو کسی بلند نکرده بود، برگشت به طرف\r\nمن، نگاهی به من کرد، همه منتظر عکس العمل پدر بودن، بابا اومد پیشم و بدون\r\nاینکه حرفی بزنه، سیلی محکمی زد تو صورتم و گفت برو دهنتو آب بکش، من خودم به\r\nعلی اصغر گفته بودم، انار هارو اونجا چال کنه، واسه زمستون!\r\n\r\nبعدشم رفت پیش علی اصغر، گفت شما ببخشش، بچس اشتباه کرد، پولشو بهش داد،\r\n۲۰ تومان هم گذاشت روش، گفت اینم بخاطر زحمت اضافت! من گریه کنان رفتم تو اطاق،\r\nدیگم بیرون نیومدم!\r\nکارگرا که رفتن، بابا اومد پیشم، صورتمو بوسید، گفت میخواستم ازت عذر خواهی\r\nکنم! اما این، تو زندگیت هیچوقت یادت نره که هیچوقت با آبروی کسی بازی نکنی،\r\nعلی اصغر کار بسیار ناشایستی کرده اما بردن آبروی مردی جلو فامیل و در\r\nو همسایه، از کار اونم زشت تره!\r\n\r\nشب شده بود، اومدم از ساختمون بیرون که برم تو باغ پیش بچه های دیگه، دیدم علی\r\nاصغر سرشو انداخته پایین و واستاده پشت در، کیسه ای تو دستش بود گفت اینو بده\r\nبه حاج آقا بگو از گناه من بگذره! کیسه رو بردم پیش بابا، بازش کرد، دیدیم کیسه\r\nای که چال کرده بود توشه، به اضافه همه پولایی که بابا بهش داده بود…\r\n"},{"id":1644,"category_id":10,"category_code":"s10","source_id":206,"title":"راز خوشبختی ","content":"روزگاری مردی فاضل زندگی می‌کرد. او هشت‌سال تمام مشتاق بود راه خداوند را بیابد؛ او هر روز از دیگران جدا می‌شد و دعا می‌کرد تا روزی با یکی از اولیای خدا و یا مرشدی آشنا شود.\r\n\r\nیک روز هم‌چنان که دعا می‌کرد، ندایی به او گفت به‌جایی برود. در آن‌ جا مردی را خواهد دید که راه حقیقت و خداوند را نشانش ‌خواهد داد. مرد وقتی این ندا را شنید، بی‌اندازه مسرور شد و به ‌جایی که به او گفته شده بود، رفت. در آن ‌جا با دیدن مردی ساده، متواضع و فقیر با لباس‌‌های مندرس و پاهایی خاک‌ آلود، متعجب شد.\r\n\r\nمرد آن اطراف را کاملاً نگاه کرد اما کس دیگری را ندید. بنابراین به مرد فقیر رو کرد و گفت:\r\n\r\nروز شما به ‌خیر. مرد فقیر به ‌آرامی پاسخ داد: \"هیچ‌وقت روز شری نداشته‌ام.\"\r\n\r\nپس مرد فاضل گفت:...\r\n\"خداوند تو را خوشبخت کند.\"\r\n\r\nمرد فقیر پاسخ داد: \"هیچ‌گاه بدبخت نبوده‌ام.\"\r\n\r\nتعجب مرد فاضل بیش‌‌تر شد: \"همیشه خوشحال باشید.\"\r\n\r\nمرد فقیر پاسخ داد: \"هیچ‌گاه غمگین نبوده‌ام.\"\r\n\r\nمرد فاضل گفت: \"هیچ سر درنمی‌آورم. خواهش می‌کنم بیش‌تر به من توضیح دهید.\"\r\n\r\nمرد فقیر گفت: \" با خوشحالی این‌کار را می‌کنم. تو روزی خیر را برایم آرزو کردی درحالی‌که من هرگز روز شری نداشته‌ام زیرا در همه‌حال، خدا را ستایش می‌کنم. اگر باران ببارد یا برف، اگر هوا خوب باشد یا بد، من هم‌چنان خدا را می‌پرستم. اگر تحقیر شوم و هیچ انسانی دوستم نباشد، باز خدا را ستایش می‌کنم و از او یاری می‌خواهم بنابراین هیچ‌گاه روز شری نداشته‌ام.\r\n\r\nتو برایم خوشبختی آرزو کردی در حالی‌که من هیچ‌وقت بدبخت نبوده‌ام زیرا همیشه به درگاه خداوند متوسل بوده‌ام و می‌دانم هرگاه که خدا چیزی بر من نازل کند، آن بهترین است و با خوشحالی هر آن‌چه را برایم پیش‌بیاید، می‌پذیرم. سلامت یا بیماری، سعادت یا دشمنی، خوشی یا غم، همه‌ هدیه‌هایی از سوی خداوند هستند.\r\n\r\nتو برایم خوشحالی آرزو کردی، در حالی‌که من هیچ‌گاه غمگین نبوده‌ام زیرا عمیق‌ترین آرزوی قلبی من، زندگی‌کردن بنا بر خواست و اراده‌ی خداوند است.\"\r\n"},{"id":1645,"category_id":10,"category_code":"s10","source_id":207,"title":"انتخاب وزیر ","content":"پادشاهی می خواست نخست وزیرش را انتخاب کند... \r\nچهار اندیشمند بزرگ کشور فراخوانده شدند. \r\nآنان را در اتاقی قرار دادند و پادشاه به آنان گفت که: «در اتاق به روی شما بسته خواهد شد و قفل اتاق، قفلی معمولی نیست و با یک جدول ریاضی باز خواهد شد، تا زمانی که آن جدول را حل نکنید نخواهید توانست قفل را باز کنید. اگر بتوانید مسئله را حل کنید می توانید در را باز کنید و بیرون بیایید»... \r\nپادشاه بیرون رفت و در را بست...\r\nسه تن از آن چهار مرد بلافاصله شروع به کار کردند. اعدادی روی قفل نوشته شده بود، آنان اعداد را نوشتند و با آن اعداد، شروع به کار کردند. \r\nنفر چهارم فقط در گوشه ای نشسته بود! \r\nآن سه نفر فکر کردند که او دیوانه است. او با چشمان بسته در گوشه ای نشسته بود و کاری نمی کرد. پس از مدتی او برخاست، به طرف در رفت، در را هل داد،باز شد و بیرون رفت!!! \r\nو آن سه تن پیوسته مشغول کار بودند. آنان حتی ندیدند که چه اتفاقی افتاد که نفر چهارم از اتاق بیرون رفته! \r\nوقتی پادشاه با این شخص به اتاق بازگشت، گفت: «کار را بس کنید. آزمون پایان یافته و من نخست وزیرم را انتخاب کردم». \r\nآنان نتوانستند باور کنند و پرسیدند: «چه اتفاقی افتاد؟ او کاری نمی کرد، او فقط در گوشه ای نشسته بود. او چگونه توانست مسئله را حل کند؟» \r\nمرد گفت: «مسئله ای در کار نبود. من فقط نشستم و نخستین \r\nسؤال و نکته ی اساسی این بود که آیا قفل بسته شده بود یا نه؟ لحظه ای که این احساس را کردم فقط در سکوت مراقبه کردم. کاملأ ساکت شدم و به خودم گفتم که از کجا شروع کنم؟ \r\nنخستین چیزی که هر انسان هوشمندی خواهد پرسید این است که آیا واقعأ مسأله ای وجود دارد، چگونه می توان آن را حل کرد؟ اگر سعی کنی آن را حل کنی تا بی نهایت به قهقرا خواهی رفت؛ \r\nهرگز از آن بیرون نخواهی رفت. پس من فقط رفتم که ببینم آیا در، واقعأ قفل است یا نه و دیدم قفل باز است». \r\n\r\nپادشاه گفت: «آری، کلک در همین بود. در قفل نبود. قفل باز بود. من منتظر بودم که یکی از شما پرسش واقعی را بپرسد و شما شروع به حل آن کردید؛ در همین جا نکته را از دست دادید. اگر تمام عمرتان هم روی آن کار می کردید نمی توانستید آن را حل کنید. این مرد، می داند که چگونه در یک موقعیت هشیار باشد. پرسش درست را او مطرح کرد».\r\n"},{"id":1646,"category_id":10,"category_code":"s10","source_id":208,"title":"من بی حیا نیستم ","content":"روزی روزگاری، عابد خداپرستی بود که در عبادتکده ای در دل کوه راز و نیاز خدا میکرد، آنقدر مقام و منزلتش پیش خدا زیاد شده بود که خدا هر شب به فرشتگانش امر میکرد تا از طعام بهشتی، برای او ببرند... و او را بدینگونه سیر نمایند. بعد از 70 سال عبادت ، روزی خدا به فرشتگانش گفت: امشب برای او طعام نبرید، بگذارید امتحانش کنیم آن شب عابد هر چه منتظر غذا شد، خبری نشد، تا جایی که گرسنگی بر او غالب شد. طاقتش تمام شد و از کوه پایین آمد و به خانه آتش پرستی که در دامنه کوه منزل داشت رفت و از او طلب نان کرد، آتش پرست 3 قرص نان به او داد و او بسمت عبادتگاه خود حرکت کرد.\r\n\r\nسگ نگهبان خانه آتش پرست به دنبال او راه افتاد، جلوی راه او را گرفت...\r\nمرد عابد یک قرص نان را جلوی او انداخت تا برگردد و بگذارد او براهش ادامه دهد، سگ نان را خورد و دوباره راه او را گرفت، مرد قرص دوم نان را نیز جلوی او انداخت و خواست برود اما سگ دست بردار نبود و نمی گذاشت مرد به راهش ادامه دهد. مرد عابد با عصبانیت قرص سوم را نیز جلوی او انداخت و گفت : ای حیوان تو چه بی حیایی! صاحبت قرص نانی به من داد اما تو نگذاشتی آنرا ببرم؟\r\n\r\nبه اذن خدای عز و جلٌ ، سگ به سخن آمد و گفت: من بی حیا نیستم، من سالهای سال سگ در خانه مردی هستم، شبهابی که به من غذا داد پیشش ماندم ، شبهایی هم که غذا نداد باز هم پیشش ماندم، شبهایی که مرا از خانه اش راند، پشت در خانه اش تا صبح نشستم... تو بی حیایی، تو که عمری خدایت هر شب غذای شبت را برایت فرستاد و هر چه خواستی عطایت کرد، یک شب که غذایی نرسید، فراموشش کردی و از او بریدی و برای رفع گرسنگی ات به در خانه یک آتش پرست آمدی و طلب نان کردی...\r\n\r\nمرد با شنیدن این سخنان منقلب شد و به عبادتگاه خویش بازگشت و توبه کرد.\r\n"},{"id":1647,"category_id":10,"category_code":"s10","source_id":209,"title":"خرید شوهر ","content":"یک مرکز خرید وجود داشت که زنان می توانستند به آنجا بروند و مردی را انتخاب کنند که شوهر آنان باشد.\r\n\r\nاین مرکز، پنج طبقه داشت و هر چه که به طبقات بالاتر می رفتند خصوصیات مثبت مردان بیشتر میشد. اما اگر در طبقه ای دری را باز می کردند باید حتما آن مرد را انتخاب می کردند و اگر به طبقه ی بالاتر می رفتند دیگر اجازه ی برگشت نداشتند و هرکس فقط یک بار می توانست از این مرکز استفاده کند.\r\n\r\nروزی دو دختر که با هم دوست بودند به این مرکز خرید رفتند تا شوهر مورد نظر خود را پیدا کنند.\r\nدر اولین طبقه، بر روی دری نوشته بود: “این مردان، شغل و بچه های دوست داشتنی دارند.”\r\nدختری که تابلو را خوانده بود گفت: “خوب، بهتر از کار داشتن یا بچه نداشتن است ولی دوست دارم ببینیم بالاتری ها چگونه اند؟”\r\n\r\nپس به طبقه ی بالایی رفتند…\r\nدر طبقه ی دوم نوشته بود: “این مردان، شغلی با حقوق زیاد، بچه های دوست داشتنی و چهره ی زیبا دارند.”\r\n\r\nدختر گفت: “هوووومممم… طبقه بالاتر چه جوریه…؟”\r\nطبقه ی سوم: “این مردان شغلی با حقوق زیاد، بچه های دوست داشتنی و چهره ی زیبا دارند و در کارهای خانه نیز به شما کمک می کنند.”\r\n\r\nدختر: “وای…. چقدر وسوسه انگیر… ولی بریم بالاتر.” و دوباره رفتند…\r\n\r\nطبقه ی چهارم: “این مردان شغلی با حقوق زیاد و بچه های دوست داشتنی دارند. دارای چهره ای زیبا هستند. همچنین در کارهای خانه نیز به شما کمک می کنند و اهداف عالی در زندگی دارند”\r\nآن دو واقعا به وجد آمده بودند…\r\nدختر: “وای چقدر خوب. پس چه چیزی ممکنه در طبقه ی آخر باشه؟”\r\n\r\nپس به طبقه ی پنجم رفتند…\r\n\r\nآنجا نوشته بود: “این طبقه فقط برای این است که ثابت کند زنان راضی شدنی نیستند! از این که به مرکز ما آمدید متشکریم و روز خوبی را برای شما آرزومندیم!”\r\n"},{"id":1648,"category_id":10,"category_code":"s10","source_id":210,"title":"تربیت قبل از تولد ","content":"مـلامحمدتقى مجلسى از علماى بزرگ اسلام است .\r\nوى در تربیت فرزندش اهتمام فراوان داشت و نـسـبـت به حرام و حلال , دقت فراوان نشان مى داد تا مبادا گوشت و پوست فرزندش با مال حرام رشدکند.مـحمدباقر, فرزند ملامحمدتقى , کمى بازیگوش بود.شبى پدربراى نماز و عبادت به مسجد جامع اصـفـهـان رفـت .\r\nآن کـودک نـیـز همراه پدر بود.محمدباقر در حیاط مسجد ماند و به بازیگوشى پرداخت .\r\nوى مشک پر از آبى را که در گوشه حیاطمسجد قرار داشت با سوزن سوراخ ‌کرد و آب آن را بـه زمـین ریخت .\r\nبا تمام شدن نماز, وقتى پدر از مسجدبیرون آمد, با دیدن این صحنه , ناراحت شد.\r\nدست فرزند را گرفت وبه سوى منزل رهسپار شد. رو به همسرش کرد و گفت :\r\nمى دانید که مـن در تربیت فرزندم دقت بسیار داشته ام .\r\nامروز عملى از او دیدم که مرابه فکر واداشت . با این که در مورد غذایش دقت کرده ام که از راه حلال به دست بیاید, نمى دانم به چه دلیل دست\r\n به این عمل زشت زده است . حال بگو چه کرده اى که فرزندمان چنین کارى را مرتکب شده است ؟!\r\nزن کمى فکر کرد و عاقبت گفت : راستش هنگامى که محمدباقر رادر رحم داشتم , یک بار وقتى به خانه همسایه رفتم , درخت انارى که درخانه شان بود, توجه مرا جلب کرد. سوزنى را در یکى از انارها فروبردم و مقدارى از آب آن را چشیدم !\r\nملامحمدتقى مجلسى با شنیدن سخن همسرش آهى کشید و به رازمطلب پى برد!!\r\n"},{"id":1649,"category_id":10,"category_code":"s10","source_id":211,"title":"آهنگری که روحش را وقف خدا کرده بود ","content":"آهنگری پس از گذراندن جوانی پرشر و شور، تصمیم گرفت روحش را وقف خدا کند. سال‌ها با علاقه کار کرد، به دیگران نیکی کرد، اما با تمام پرهیزگاری، در زندگی‌اش اوضاع درست به نظر نمی‌آمد. حتی مشکلاتش مدام بیش‌تر می‌شد.\r\n\r\nیک روز عصر، دوستی که به دیدنش آمده بود و از وضعیت دشوارش مطلع شد، گفت: «واقعا که عجبا. درست بعد از این که تصمیم گرفته‌ای مرد خداترسی بشوی، زندگی‌ات بدتر شده، نمی‌خواهم ایمانت را ضعیف کنم اما با وجود تمام رنجهایی که در مسیر معنویت به خود داده‌ای، زندگیی‌ات بهتر نشده.\r\n\r\nآهنگر مکث کرد و بلافاصله پاسخ نداد.\r\n\r\nسرانجام در سکوت، پاسخی را که می‌خواست یافت.\r\n\r\nاین پاسخ آهنگر بود:\r\nدر این کارگاه، فولاد خام برایم می‌آورند و باید از آن شمشیر بسازم. می‌دانی چه طور این کار را می‌کنم؟ اول تکه‌ی فولاد را به اندازه‌ی جهنم حرارت می‌دهم تا سرخ شود. بعد با بی‌رحمی، سنگین‌ترین پتک را بر می‌دارم و پشت سر هم به آن ضربه می‌زنم، تا این که فولاد، شکلی را بگیرد که می‌خواهم. بعد آن را در تشت آب سرد فرو می‌کنم، و تمام این کارگاه را بخار آب می‌گیرد، فولاد به خاطر این تغییر ناگهانی دما، ناله می‌کند و رنج می‌برد. باید این کار را آن قدر تکرار کنم تا به شمشیر مورد نظرم دست بیابم. یک بار کافی نیست.\r\n\r\nآهنگر مدتی سکوت کرد و سپس ادامه داد:\r\n\r\nگاهی فولادی که به دستم می‌رسد، نمی‌تواند تاب این عملیات را بیاورد. حرارت، ضربات پتک و آب سر، تمامش را ترک می‌اندازد. می‌دانم که این فولاد، هرگز تیغه‌ی شمشیر مناسبی در نخواهد آمد. آنوقت است که آنرا به میان انبوه زباله‌های کارگاه میاندازم.\r\n\r\nباز مکث کرد و بعد ادامه داد:\r\n\r\nمی‌دانم که در آتش رنج فرو می‌روم. ضربات پتکی را که زندگی بر من وارد کرده، پذیرفته‌ام، و گاهی به شدت احساس سرما می‌کنم. انگار فولادی باشم که از آبدیده شدن رنج می‌برد. اما تنها دعایی که به درگاه خداوند دارم این است :\r\n\r\n«خدای من، از آنچه برای من خواسته‌ ای صرفنظر نکن تا شکلی را که  می‌خواهی ، به خود بگیرم. به هر روشی که می‌پسندی  ادامه بده ؛ هر مدت که لازم است، ادامه بده، اما هرگز، هرگز مرا به کوه زباله‌های فولادهای بی فایده پرتاب نکن».\r\n"},{"id":1650,"category_id":10,"category_code":"s10","source_id":212,"title":"دو گدا ","content":"دو گدا تو یه خیابون شهر رم کنار هم نشسته بودن. یکیشون یه صلیب گذاشته بود جلوش، اون یکی یه ستاره داوود.. مردم زیادی که از اونجا رد میشدن به هر دو نگاه میکردن ولی فقط تو کلاه اونی که پشت صلیب نشسته بود پول مینداختن.\r\n\r\n\r\nیه کشیش که از اونجا رد میشد مدتی ایستاد و دید که مردم فقط به گدایی که پشت صلیبه پول میدن و هیچ کس به گدای پشت ستاره داوود چیزی نمیده. رفت جلو و گفت: ....\r\nرفیق بیچاره من، متوجه نیستی؟ اینجا یه کشور کاتولیکه، تازه مرکز مذهب کاتولیک هم هست.\r\n\r\nپس مردم به تو که ستاره داوود گذاشتی جلوت پول نمیدن، به خصوص که درست نشستی بغل دست یه گدای دیگه که صلیب داره جلوش. در واقع از روی لجبازی هم که باشه مردم به اون یکی پول میدن نه به تو.\r\n\r\n\r\nگدای پشت ستاره داوود بعد از شنیدن حرفهای کشیش رو کرد به گدای پشت صلیب و گفت: هی \"موشه\" نگاه کن کی اومده به برادران \"گلدشتین*\" بازاریابی یاد بده؟\r\n\r\n \r\n\r\n* گلدشتین یه اسم فامیل معروف یهودی\r\n"},{"id":1651,"category_id":10,"category_code":"s10","source_id":213,"title":"حضرت سلیمان (ع ) ","content":"روزی حضرت سلیمان (ع ) در کنار دریا نشسته بود ، نگاهش به مورچه ای افتاد که دانه گندمی را باخود به طرف دریا حمل می کرد .سلیمان (ع) همچنان به او نگاه می کرد که دید او نزدیک آب رسید.در همان لحظه قورباغه ای سرش را از آب دریا بیرون آورد و دهانش را گشود ، مورچه به داخل دهان او وارد شد ، و قورباغه به درون آب رفت.\r\nسلیمان مدتی در این مورد به فکر فرو رفت و شگفت زده فکر می کرد ، ناگاه دید آن قورباغه سرش را از آب بیرون آورد و دهانش را گشود ، آن مورچه آز دهان او بیرون آمد، ولی دانه ی گندم را همراه خود نداشت .\r\nسلیمان(ع) آن مورچه را طلبید و سرگذشت او را پرسید.\r\nمورچه گفت : \" ای پیامبر خدا در قعر این دریا سنگی تو خالی وجود دارد و کرمی در درون آن زندگی می کند . خداوند آن را در آنجا آفریداو نمی تواند ار آنجا خارج شود و منروزی او را حمل می کنم . خداوند این قورباغه را مامور کرده مرا درون آب دریا به سوی آن کرم حمل کرده و ببرد .\r\nاین قورباغه مرا به کنار سوراخی که در آن سنگ است می برد و دهانش را به درگاه آن سوراخ می گذارد من از دهان او بیرون آمده و خود را به آن کرم می رسانم و دانه گندم را نزد او می گذارم و سپس باز می گردم وبه دهان همان قورباغه که در انتظار من است وارد می شود او در میان آب شناوری کرده مرا به بیرون آب دریا می آورد و دهانش را باز می کند ومن از دهان او خارج میشوم .\"\r\nسلیمان به مورچه گفت : (( وقتی که دانه گندم را برای آن کرم میبری آیا سخنی از او شنیده ای ؟ ))\r\nمورچه گفت آری او می گوید :\r\nای خدایی که رزق و روزی مرا درون این سنگ در قعر این دریا فراموش نمی کنی رحمتت را نسبت به بندگان با ایمانت فراموش نکن.\r\n"},{"id":1652,"category_id":10,"category_code":"s10","source_id":214,"title":"ایمان واقعی ","content":"روزی بازرگان  موفقی از مسافرت بازگشت و متوجه  شد خانه و مغازه اش در غیاب  او آتش گرفته و کالا های گرانبهایش  همه سوخته و خاکستر شده اند  و خسارت هنگفتی به او وارد امده  است .\r\n\r\nفکر می کنید آن مرد چه کرد؟!\r\nخدا را مقصر شمرد و ملامت کرد؟ و یا اشک ریخت ؟ نه.....\r\nاو با لبخندی بر لبان و نوری بر دیدگان سر به سوی آسمان بلند کرد و گفت : \"خدایا ! می خواهی که اکنون چه کنم؟\r\nمرد تاجر پس از نابودی کسب پر رونق خود ، تابلویی بر ویرانه های خانه و مغازه اش آویخت که روی آن نوشته بود :\r\nمغازه ام سوخت ! اما ایمانم نسوخته است ! فردا شروع به کار خواهم کرد!\r\n"},{"id":1653,"category_id":10,"category_code":"s10","source_id":215,"title":"ببر مردم شناس ","content":"یکی بود یکی نبود. در روزگاران قدیم ببری از باغ‌وحش امریکا گریخت و به جنگل بازگشت. در دوران اسارت بسیاری از عادات آدمیان را آموخته بود و با خود فکر کرد خوب است آن رسوم را در جنگل به کاربَرَد.\r\n\r\nاولین روزی که به منزل رسید یوز‌پلنگی را ملاقات کرد و به او گفت:«صحیح نیست که من و تو برای قوت‌مان به شکار رویم. حیوانات دیگر را وا می‌داریم که غذای‌مان را برای‌مان تهیه ببینند.»\r\n\r\nیوز‌پلنگ پرسید:«چه‌گونه این کار را می‌توانیم انجام دهیم؟»....\r\nببر گفت:«خیلی ساده است به آن‌ها می‌گوییم که من و تو با هم مشت‌بازی خواهیم کرد و برای تماشای این مسابقه بایستی هر کدام از جانوران گراز وحشی تازه‌کشته‌ای با خود بیاورند. بعد من و تو بدون این‌که آزاری به هم رسانیم به سرو کول یک‌دیگر می‌پریم و بعد خواهی گفت که استخوان پنجه‌ات در روند دوم شکست و من ادعا خواهم کرد که استخوان پنجه‌ام در روند اول شکست. پس از آن هم مسابقة بعد‌مان را اعلان می‌کنیم و آن‌ها بایستی دو‌باره گراز وحشی همراه بیاورند.»\r\n\r\nیوز‌پلنگ گفت:«تصور نمی‌کنم کارگر بیفتد.»\r\n\r\nببر گفت:«چرا، حتماَ مؤثراست. تو به همه بگو تو برنده خواهی بود، چون من مشت‌زن بی‌تجربه‌ای هستم و من به همه می گویم حتماَ من بازنده نیستم، زیرا تو مشت‌زن بی‌تجربه‌ای هستی و همه آرزو می‌کنند که تماشاگر چنین جنگی باشند.»\r\n\r\nبه این ترتیب یوز‌پلنگ به همه گفت که برندة مسلم است چون ببر مشت‌زن بی‌تجربه‌ای است و ببر به همه گفت که مسلماَ بازنده نیست چون یوز‌پلنگ مشت‌زن خامی است. شب مسابقه فرا‌ رسید. ببر و یوز‌پلنگ به شکار نرفته بودند و خیلی گرسنه بودند، می‌خواستند هرچه زودتر مسابقه به اتمام رسد و گراز‌های وحشی تازه شکارشده را که جانوران بایستی همراه داشته باشند بخورند. اما در ساعت موعود هیچ‌کس نیامد.\r\n\r\nروباهی گفته بود:«من این قضیه را این‌طور تجزیه و تحلیل می‌کنم: اگر یوز‌پلنگ برندة مسلم است و ببر مسلماَ بازنده نیست پس مساوی خواهند شد و چنین مسابقه‌ای بسیار خسته‌کننده است. مخصوصاَ وقتی طرفین مسابقه مشت‌زن‌های خام و بی‌تجربه‌ای هستند.» جانوران دیگر این منطق را پذیرفتند و به گود نزدیک نشدند. وقنی شب به نیمه رسید و مشهود گشت که حیوانات نخواهند آمد و گرازی برای خوردن نخواهد بود ببر و یوز‌پلنگ به جان یک‌دیگر افتادند وهر دوآن چنان مجروح گشتند و آن چنان از پا در افتادند که یک جفت گراز وحشی که از آن حوالی می‌گذشتند به آن‌ها حمله‌ور شدند و به سادگی آن‌ها را کشتند.\r\n"},{"id":1654,"category_id":10,"category_code":"s10","source_id":216,"title":"تصویر آرامش ","content":"پادشاهی جایزه بزرگی برای هنرمندی گذاشت که بتواند به بهترین شکل ، آرامش را به تصویر بکشد. \r\nنقاشان بسیاری آثار خود را به قصر فرستادند. آن تابلو ها ، تصاویری بودند از خورشید به هنگام غروب ، رودهای آرام ، کودکانی که در چمن می دویدند ، رنگین کمان در آسمان ، و قطرات شبنم بر گلبرگ گل سرخ. \r\nپادشاه تمام تابلو ها را بررسی کرد ، اما سرانجام فقط دو اثر را انتخاب کرد. ...\r\nاولی ، تصویر دریاچه ی آرامی بود که کوههای عظیم و آسمان آبی را در خود منعکس کرده بود. در جای جایش می شد ابرهای کوچک و سفید را دید، و اگر دقیق نگاه می کردند، در گوشه ی چپ دریاچه، خانه ی کوچکی قرار داشت، پنجره اش باز بود، دود از دودکش آن بر می خواست، که نشان می داد شام گرم و نرمی آماده است.\r\nتصویر دوم هم کوهها را نمایش می داد. اما کوهها ناهموار بود ، قله ها تیز و دندانه ای بود. آسمان بالای کوهها بطور بیرحمانه ای تاریک بود، و ابرها آبستن آذرخش، تگرگ و باران سیل آسا بودند. این تابلو با تابلو های دیگری که برای مسابقه فرستاده بودند، هیچ هماهنگی نداشت.اما وقتی آدم با دقت به تابلو نگاه می کرد، در بریدگی صخره ای شوم، جوجه پرنده ای را می دید.آنجا، در میان غرش وحشیانه ی طوفان ، جوجه گنجشکی ، آرام نشسته بود. \r\n\r\nپادشاه درباریان را جمع کرد و اعلام کرد که برنده ی جایزه ی بهترین تصویر آرامش، تابلو دوم است.بعد توضیح داد : \r\nآرامش چیزی نیست که در مکانی بی سر و صدا ، بی مشکل و بدون کار سخت یافت شود ، بلکه معنای حقیقی آرامش این است که هنگامیکه شرایط سختی بر ما می گذرد آرامش در قلب ما حفظ شود.\r\n"},{"id":1655,"category_id":10,"category_code":"s10","source_id":217,"title":"رنج شیطان ","content":"شیطان به حضرت یحیی گفت : می خواهم تو را نصیحت کنم !\r\nحضرت یحیی فرمود : من میل ندارم ولی می خواهم بدانم طبقات مردم نزد شما چگونه اند .\r\nشیطان گفت :‌مردم از نظر ما به سه دسته تقسیم می شوند :....\r\n۱) عده ای مانند شما معصومند ، ار آنها مایوسیم و می دانیم که نیرنگ ما در آنها اثر نمی کند\r\n\r\n۲) دسته ای هم بر عکس در پیش ما شبیه توپی هستند که به هر طرف می خواهیم می گردانیم\r\n۳) دسته ای هم هستند که از دست انها رنج می بریم ؛ زیرا فریب می خورند ؛ ولی سپس از کرده خود پشیمان می شوند و استغفار می کنند و تمام زحمات ما را به هدر می دهند دفعه دیگر که نزدیکه که موفق شویم ،؛ اما آنها دوباره به یاد خدا می افتند و از چنگال ما فرار می کنند . ما از چنین افرادی پیوسته رنج می بریم .\r\n"},{"id":1656,"category_id":10,"category_code":"s10","source_id":218,"title":"مهلت خدا برای زندگی ","content":"یک خانم 45 ساله که یک حملهء قلبی داشت و در بیمارستان بستری بود . در اتاق جراحی که کم مونده بود مرگ را تجربه کند خدا رو دید و پرسید آیا وقت من تمام است؟ خدا گفت:نه شما 43 سال و 2 ماه و 8 روز دیگه عمر می کنید.\r\n\r\nدر وقت مرخصی خانم تصمیم گرفت در بیمارستان بماند و عملهای زیر را انجام دهد کشیدن پوست صورت-تخلیهء چربیها(لیپو ساکشن)-عمل سینه هاو جمع و جور کردن شکم . او حالا کسی رو نداشت که بیاد و موهاشو رنگ کنه و دندوناشو سفید کنه !!....\r\nاز اونجایی که او زمان بیشتری برای زندگی داشت از این رو او تصمیم گرفت که بتواند بیشترین استفاده را از این موقعیت (زندگی) ببرد.بعد از آخرین عملش او از بیمارستان مرخص شد\r\n\r\nدر وقت گذشتن از خیابان در راه منزل بوسیلهء یک آمبولانس کشته شد . وقتی با خدا روبرو شد او پرسید:: من فکر کردم شما فرمودید من 43 سال دیگه فرصت دارم چرا شما مرا از زیر آمبولانس بیرون نکشیدید؟\r\n\r\nخدا جواب داد :من چهره شما رو تشخیص ندادم!!!\"\r\n"},{"id":1657,"category_id":10,"category_code":"s10","source_id":219,"title":"یک زندگی در خطر بود ","content":"آبراهام لینکلن در وسط جلسه سنا بود که بچه خوکی در جوی آب گرفتار شد. از جلسه بیرون دوید و گفت: فعلن بحث را چند دقیقه نگه دارید، زود برمی گردم.\r\nاین کاری عجیب بود. شاید .....\r\nپارلمان آمریکا هرگز به چنین دلیلی متوقف نشده بود. او دوید تا آن بچه خوک را آزاد کند! لباس هایش تمامن گلی شده بود. او آن  بچه خوک را از آن جوی نجات داد و سپس به جلسه برگشت.\r\nمردم پرسیدند : این چه کاری بود کردی؟ چرا جلسه را نگه داشتی و با چنین عجله ای بیرون دویدی؟\r\nاو پاسخ داد: یک زندگی در خطر بود.\r\n"},{"id":1658,"category_id":10,"category_code":"s10","source_id":220,"title":"قضاوت ","content":"مردی چهار پسر داشت. آنها را به ترتیب به سراغ درخت گلابی ای فرستاد که در فاصله ای دور از خانه شان روییده بود:\r\nپسر اول در زمستان، دومی در بهار، سومی در تابستان و پسر چهارم در پاییز به کنار درخت رفتند.\r\nسپس پدر همه را فراخواند و از آنها خواست که بر اساس آنچه دیده بودند درخت را توصیف کنند .\r\nپسر اول گفت: درخت زشتی بود، خمیده و در هم پیچیده.\r\n\r\nپسر دوم گفت: نه.. درختی پوشیده از جوانه بود و پر از امید شکفتن.....\r\n\r\nپسر سوم گفت: نه.. درختی بود سرشار از شکوفه های زیبا و عطرآگین.. و باشکوهترین صحنه ای بود که تابه امروز دیده ام.\r\nپسر چهارم گفت: نه!!! درخت بالغی بود پربار از میوه ها.. پر از زندگی و زایش!\r\nمرد لبخندی زد و گفت: همه شما درست گفتید، اما هر یک از شما فقط یک فصل از زندگی درخت را دیده اید! شما نمیتوانید درباره یک درخت یا یک انسان براساس یک فصل قضاوت کنید: همه حاصل انچه هستند و لذت، شوق و عشقی که از زندگیشان برمی آید فقط در انتها نمایان میشود، وقتی همه فصلها آمده و رفته باشند!\r\nاگر در ” زمستان” تسلیم شوید، امید شکوفایی ” بهار” ، زیبایی “تابستان” و باروری “پاییز” را از کف داده اید!\r\nمبادا بگذاری درد و رنج یک فصل زیبایی و شادی تمام فصلهای دیگر را نابود کند!\r\nزندگی را فقط با فصلهای دشوارش نبین ؛\r\nدر راههای سخت پایداری کن: لحظه های بهتر بالاخره از راه میرسند!\r\n"},{"id":1659,"category_id":10,"category_code":"s10","source_id":221,"title":"عاشق بر نمی گردد! ","content":"دختری به کورش کبیر گفت: من عاشق شما هستم. کورش به او گفت: لیاقت تو برادر من است که از من زیبا تر است و پشت سرت ایستاده است.\r\nدختر برگشت و کسی‌ را پشت سر خود ندید. کورش به او گفت اگر عاشق بودی، پشت سرت را نگاه نمی‌‌کردی.\r\n"},{"id":1660,"category_id":10,"category_code":"s10","source_id":222,"title":"بابا جان فقط پنج دقیقه ، باشه ؟ ","content":"در یک پارک زنی با یک مرد روی نیمکت نشسته بودند و به کودکانی که در حال بازی بودند نگاه میکردند.\r\nزن رو به مرد کرد و گفت پسری که لباس ورزشی قرمز دارد و از سرسره بالا می¬رود پسر من است .\r\nمرد در جواب گفت : چه پسر زیبایی و در ادامه گفت او هم پسر من است و به پسری که تاب بازی می¬کرد اشاره کرد .\r\nمرد نگاهی به ساعتش انداخت و پسرش را صدا زد :...\r\nسامی وقت رفتن است .\r\nسامی که دلش نمی¬آمد از تاب پایین بیاید با خواهش گفت بابا جان فقط 5 دقیقه . باشه ؟\r\nمرد سرش را تکان داد و قبول کرد . مرد و زن باز به صحبت ادامه دادند . دقایقی گذشت و پدر دوباره فرزندش را صدا زد : سامی دیر میشود برویم . ولی سامی باز خواهش کرد 5 دقیقه این دفعه قول میدهم .\r\nمرد لبخند زد و باز قبول کرد . زن رو به مرد کرد و گفت : شما آدم خونسردی هستید ولی فکر نمی¬کنید پسرتان با این کارها لوس بشود ؟\r\nمرد جواب داد دو سال پیش یک راننده مست پسر بزرگم را در حال دوچرخه¬سواری زیر گرفت و کشت .\r\nمن هیچ¬گاه برای تام وقت کافی نگذاشته بودم . و همیشه به خاطر این موضوع غصه می-خورم . ولی حالا تصمیم گرفتم این اشتباه را در مورد سامی تکرار نکنم . سامی فکر می-کند که 5 دقیقه بیش¬تر برای بازی کردن وقت دارد ولی حقیقت آن است که من 5 دقیقه بیشتر وقت می¬دهم تا بازی کردن و شادی او را ببینم .\r\n5 دقیقه¬ای که دیگر هرگز نمی¬توانم بودن در کنار تام ِ از دست رفته¬ام را تجربه کنم.\r\n"},{"id":1661,"category_id":10,"category_code":"s10","source_id":223,"title":"شکایتی جالب از جنرال موتورز !!! ","content":"بخش پونتیاک شرکت خودروسازی جنرال موتورز شکایتی را از یک مشتری با این مضمون دریافت کرد:» این دومین باری است که برایتان می نویسم و برای این که بار قبل پاسخی نداده اید، گلایه ای ندارم، چرا که موضوع از نظر من نیز احمقانه است!\r\nبه هر حال، موضوع این است که طبق یک رسم قدیمی، خانواده ما عادت دارد هر شب پس از شام به عنوان دسر، بستنی بخورد. سالهاست که ما پس از شام رأی گیری می کنیم و براساس اکثریت آرا نوع بستنی، انتخاب و خریداری می شود. این را هم باید بگویم که من به تازگی یک خودروی شورولت پونتیاک جدید خریده ام و با خرید این خودرو، رفت و آمدم به فروشگاه برای تهیه بستنی دچار مشکل شده است.\r\n لطفاً دقت بفرمایید! هر دفعه که برای خرید بستنی وانیلی...\r\nبه مغازه می روم و به خودرو باز می گردم، ماشین روشن نمی شود. اما هر بستنی دیگری که بخرم، چنین مشکلی نخواهم داشت. خواهش می کنم درک کنید که این مسأله برای من بسیار جدی و دردسر آفرین است و من هرگز قصد شوخی با شما را ندارم. می خواهم بپرسم چطور می شود پونتیاک من وقتی بستنی وانیلی می خرم، روشن نمی شود، اما هر بستنی دیگری می خرم، راحت استارت می خورد؟ \r\nمدیر شرکت به نامه عجیب دریافتی با شک و تردید برخورد کرد، اما از روی وظیفه و تعهد، یک مهندس را مأمور بررسی مسأله کرد. مهندس خبره شرکت، شب هنگام پس از شام با مشتری قرار گذاشت، آن دو به اتفاق به بستنی فروشی رفتند، آن شب نوبت بستنی وانیلی بود. پس از خرید بستنی، همانطور که در نامه شرح داده شد، ماشین روشن نشد! مهندس جوان و کنجکاو،۳ شب پیاپی دیگر نیز با صاحب خودرو به فروشگاه رفت. شبی نوبت بستنی شکلاتی بود، ماشین روشن شد. شب بعد بستنی توت فرنگی، و خودرو براحتی استارت خورد. اما شب سوم دوباره نوبت بستنی وانیلی شد، باز ماشین روشن نشد!\r\n نماینده شرکت به جای این که به فکر یافتن دلیل حساسیت داشتن خودرو به بستنی وانیلی باشد، تلاش کرد با موضوع منطقی و متفکرانه برخورد کند. او مشاهدات فنی خود را از لحظه ترک منزل مشتری تا خریدن بستنی و بازگشت به ماشین و استارت زدن برای انواع بستنی ثبت کرد. این مشاهده و ثبت اتفاق ها و مدت زمان آنها، نکته جالبی را به او نشان داد: بستنی وانیلی پرطرفدار و پر فروش است و نزدیک در مغازه در قفسه ها چیده می شود، اما دیگر بستنی ها داخل مغازه و دورتر از در قرار می گیرند، پس مدت زمان خروج از خودرو تا خرید بستنی و برگشتن و استارت زدن برای بستنی وانیلی کمتر از دیگر بستنی هاست. این مدت زمان مهندس را به تحلیل علمی موضوع راهنمایی کرد و او دریافت پدیده ای به نام قفل بخار باعث بروز این مشکل می شود. روشن شدن خیلی زود خودرو پس از خاموش شدن، به دلیل تراکم بخار در موتور و پیستون ها مسأله اصلی شرکت پونتیاک و مشتری بود.\r\n"},{"id":1662,"category_id":10,"category_code":"s10","source_id":224,"title":"یادگیری ","content":"روزی پسری نزد شیوانا آمد و به او گفت که یکی از افسران امپراتوری مزاحم او و خانواده اش شده است و هر روز به نحوی آن ها را اذیت می کند. پسر جوان گفت که افسر گارد امپراتور مبارزی بسیار جنگاور است و در سراسر سرزمین امپراتوری کسی سریع تر و پر شتاب تر از او حرکات رزمی را اجرا نمی کند. به همین خاطر هیچ کس جرات مبارزه با او را ندارد. این افسر نامش \"برق آسا\" است و آنچنان حرکات رزمی را به سرعت اجرا می کند که حتی قوی ترین رزم آوران هم در مقابل سرعت ضربات او کم می آورند. من چگونه می توانم از خودم و حریم خانواده ام در مقابل او دفاع کنم؟!\r\nشیوانا تبسمی کرد و گفت:\" او را به مبارزه دعوت کن و در نبردی مردانه او را سرجایش بنشان!\"\r\n\r\nپسر جوان لبخند تلخی زد و گفت:\" چه می گوئید؟! او \"برق آسا\" است و سریع تر از برق ضربات خود را وارد می سازد. من چگونه می توانم به سرعت به او ضربه بزنم؟!\"\r\n...\r\nشیوانا با همان لحن آرام و مطمئن خود گفت:\" او را به مبارزه دعوت کن و در نبردی مردانه سر جایش بنشان! برای تمرین ضربه زنی برق آسا هم فردا نزد من آی تا به تو راه سریع تر جنگیدن را بیاموزم!\"\r\nفردای آن روز پسر جوان لباس تمرین رزم به تن کرد و مقابل شیوانا ایستاد. شیوانا از جا برخاست به آهستگی دستانش را بالا برد و با چرخش همزمان بدن و دست و سر و کمر و پاهایش ژست مردی را گرفت که قصد دارد به پسر جوان ضربه بزند. اما نکته اینجا بود که شیوانا حرکت ضربه زنی را با سرعتی فوق العاده کم و تقریبا صفر انجام داد. یک ضربه شیوانا به صورت پسر نزدیک یک ساعت طول کشید. پسر جوان ابتدا مات و مبهوت به این بازی آهسته شیوانا خیره شد و سپس با بی تفاوتی در گوشه ای نشست. یک ساعت بعد وقتی نمایش ضربه زنی شیوانا به اتمام رسید. شیوانا از پسر خواست تا با سرعتی بسیار کمتر از او همان ضربه را اجرا کند.\r\nپسر با اعتراض فریاد زد که حریف او سریع ترین مبارز سرزمین امپراتور است. آن وقت شیوانا با این حرکات آهسته و لاک پشت وار می خواهد روش مبارزه با برق آسا را آموزش دهد؟!؟ اما شیوانا با اطمینان به پسر گفت که این تنها راه مبارزه است و او چاره ای جز اطاعت را ندارد.\"\r\nپسر به ناچار حرکات رزمی را با سرعتی فوق العاده کم اجرا نمود.\r\n\r\nیک حرکت چرخیدن که در حالت عادی در کسری از ثانیه قابل انجام بود به دستور شیوانا در دو ساعت انجام شد. روزهای بعد نیز شیوانا حرکات جدید را با همین شکل یعنی اجرای حرکات چند ثانیه ای در چند ساعت آموزش داد. سرانجام روز مبارزه فرا رسید. پسر جوان مقابل افسر امپراتور ایستاد و از او خواست تا دست از سر خانواده اش بردارد. افسر امپراتور خشمگین بدون هیچ توضیحی دست به شمشیر برد و به سوی پسر جوان حمله کرد. اما در مقابل چشمان حیرت زده سربازان و ساکنین دهکده پسر جوان با سرعتی باور نکردنی سر و صورت افسر را زیر ضربات خود گرفت و در یک چشم به هم زدن برق آسا را بر زمین کوبید.\r\n\r\nهمه حیرت کردند و افسر امپراتور ترسان و شرم زده از دهکده گریخت. پسر جوان نزد شیوانا آمد و از او راز سرعت بالای خود را پرسید. او به شیوانا گفت:\" ای استاد بزرگ! من که تمام حرکات را آهسته اجرا کردم چگونه بود که هنگام رزم واقعی این قدر سریع عمل کردم؟\"\r\n\r\nشیوانا خندید و گفت:\" تک تک اجزای وجود تو در تمرینات آهسته تمام جزئیات فرم های مبارزه را ثبت کردند و با فرصت کافی ریزه کاری های تک تک حرکات را برای خود تحلیل کردند. به این ترتیب هنگام رزم واقعی بدن تو فارغ از همه چیز دقیقا می دانست چه حرکتی را به چه شکل درستی باید انجام دهد و به طور خودکار آن حرکت را با حداکثر سرعت اجرا کرد. در واقع سرعت اجرای حرکات تو به خاطر تمرین آهسته آن بود. هرچه تمرین آهسته تر باشد سرعت اجرا در شرایط واقعی بیشتر است. در زندگی هم اگر می خواهی بهترین باشی باید عجله و شتاب را کنار بگذاری و تمام حرکات را ابتدا به صورت آهسته مسلط شوی. فقط با صبر و حوصله و سرعت پایین است که می توان به سریع ترین و پیچیده ترین امور زندگی مسلط شد. راز موفقیت آنها که سریع ترین هستند همین است. تمرین در سرعت پایین. به همین سادگی!\"\r\n"},{"id":1663,"category_id":10,"category_code":"s10","source_id":225,"title":"اشتباه لپی ","content":"میگفتن علف باید به دهن بزی شیرین بیاد یه عمری خودمونو کشتیم شیرین ترین علف دنیا بشیم غافل از اینکه اصلا طرف بز نبود . . .\r\nگاو بود به خوردن مقوا عادت کرده بود.\r\n"},{"id":1664,"category_id":10,"category_code":"s10","source_id":226,"title":"خودکشی ","content":"\r\nکالین ویلسون که امروز نویسنده ی مشهوری است،وسوسه ی\r\nخودکشی راکه در شانزده سالگی به او دست داده بود،چنین توصیف میکند:\r\nوارد آزمایشگاه شیمی مدرسه شدم و شیشه ی زهر را برداشتم....\r\n\r\nزهر را در لیوان پیش رویم خالی کردم،غرق تماشایش شدم،رنگش را نگاه کردم\r\nو مزه ی احتمالی اش را در ذهن ام تصور کردم.سپس اسید را به بینی ام نزدیک کردم، و\r\nبویش به مشامم خورد، در این لحظه، ناگهان جرقه ای از اینده در ذهنم\r\nدرخشید..... و توانستم سوزش ان را در گلویم احساس کنم و سوراخ ایجاد\r\nشده در درئن معده ام را ببینم. احساس اسیب ان زهر ان چنان حقیقی بود که\r\nگویی به راستی ان را نوشیده بودم.سپس مطمئن شدم که هنوز این کار را نکرده ام.\r\nدر طول چند لحظه ای که ان لیوان را در دست گرفته بودمو امکان مرگ را مزه مزه میکردم،با خودم فکر کردم:اگر شجاعت کشتن خودم را دارم، پس شجاعت ادامه دادن زندگی ام را هم دارم.\r\n"},{"id":1665,"category_id":10,"category_code":"s10","source_id":227,"title":"کمک به رقباء","content":"یکی از کشاورزان منطقه ای، همیشه در مسابقه‌ها، جایزه بهترین غله را به ‌دست می‌آورد و به ‌عنوان کشاورز نمونه شناخته شده بود. رقبا و همکارانش، علاقه‌مند شدند راز موفقیتش را بدانند. به همین دلیل، او را زیر نظر گرفتند و مراقب کارهایش بودند. پس از مدتی جستجو، سرانجام با نکته‌ عجیب و جالبی روبرو شدند.\r\nاین كشاورز پس از هر نوبت كِشت، بهترین بذرهایش را به همسایگانش می‌داد و آنان را از این نظر تأمین می‌كرد. بنابراین، همسایگان او می‌بایست برنده‌ مسابقه‌ها می‌شدند نه خود او!\r\nكنجكاویشان بیش‌تر شد و كوشش علاقه‌مندان به كشف این موضوع كه با تعجب و تحیر نیز آمیخته شده بود، به جایی نرسید. سرانجام، تصمیم گرفتند ماجرا را از خود او بپرسند و پرده از این راز عجیب بردارند.\r\nكشاورز هوشیار و دانا، در پاسخ به پرسش همكارانش گفت: چون جریان باد، ذرات باروركننده غلات را از یك مزرعه به مزرعه‌ دیگر می‌برد، من بهترین بذرهایم را به همسایگان می‌دادم تا باد، ذرات باروركننده نامرغوب را از مزرعه‌های آنان به زمین من نیاورد و كیفیت محصول‌های مرا خراب نكند!\r\n"},{"id":1666,"category_id":10,"category_code":"s10","source_id":228,"title":"مرغابی یا عقاب! کدام می خواهید باشید؟","content":"وقتی شما به شهر نیویورک سفر کنید، جالب ترین بخش سفر شما هنگامی است که پس از خروج از هواپیما و فرودگاه، قصد گرفتن یک تاکسی را داشته باشید. اگر یک تاکسی برای ورود به شهر و رسیدن به مقصد بیابید شانس به شما روی آورده است. اگر راننده ی تاکسی شهر را بشناسد و از نشانی شما سر در آورد با اقبال دیگری روبرو شده اید.\r\nاگر زبان راننده را بدانيد و بتوانيد با او سخن بگوييد بخت يارتان است و اگر راننده عصباني نباشد، با حسن اتفاق ديگري مواجه هستيد. خلاصه براي رسيدن به مقصد بايد از موانع متعددي بگذريد.\r\nهاروي مك كي مي گويد: روزي پس از خروج از هواپيما، در محوطه اي به انتظار تاكسي ايستاده بودم كه ناگهان راننده اي با پيراهن سفيد و تميز و پاپيون سياه از اتومبيلش بيرون پريد، خود را به من رساند و پس از سلام و معرفي خود گفت: لطفا چمدان خود را در صندوق عقب بگذاريد.\r\nسپس كارت كوچكي را به من داد و گفت: لطفا به عبارتي كه رسالت مرا تعريف مي كند توجه كنيد.\r\nبر روي كارت نوشته شده بود: در كوتاه ترين مدت، با كمترين هزينه، مطمئن ترين راه ممكن و در محيطي دوستانه شما را به مقصد مي رسانم.\r\nمن چنان شگفت زده شدم كه گفتم نكند هواپيما به جاي نيويورك در كره اي ديگر فرود آمده است. راننده در را گشود و من سوار اتومبيل بسيار آراسته اي شدم. پس از آنكه راننده پشت فرمان قرار گرفت، رو به من كرد و گفت: پيش از حركت، قهوه ميل داريد؟ در اينجا يك فلاسك قهوه معمولي و فلاسك ديگري از قهوه مخصوص براي كسانيكه رژيم تغذيه دارند، هست.\r\nگفتم: خير، قهوه ميل ندارم، اما با نوشابه موافقم.\r\nراننده پرسيد: در يخدان هم نوشابه دارم و هم آب ميوه.\r\nسپس با دادن يك بطري نوشابه، حركت كرد و گفت: اگر ميل به مطالعه داريد مجلات تايم، ورزش و تصوير و آمريكاي امروز در اختيار شما است.\r\nآنگاه، بار ديگر كارت كوچك ديگري در اختيارم گذاشت و گفت: اين فهرست ايستگاههاي راديويي است كه مي توانيد از آنها استفاده كنيد. ضمنا من مي توانم درباره بناهاي ديدني و تاريخي و اخبار محلي شهر نيويورك اطلاعاتي به شما بدهم و اگر تمايلي نداشته باشيد مي توانم سكوت كنم. در هر صورت من در خدمت شما هستم.\r\nاز او پرسيدم: چند سال است كه به اين شيوه كار مي كنيد؟\r\nپاسخ داد:  دو سال\r\nپرسيدم: چند سال است كه به اين كار مشغوليد؟\r\nجواب داد: هفت سال\r\nپرسيدم: پنج سال اول را چگونه كار مي كردي؟\r\nگفت: از همه چيز و همه كس،از اتوبوسها و تاكسي هاي زيادي كه هميشه راه را بند مي آورند، و از دستمزدي كه نويد زندگي بهتري را به همراه نداشت مي ناليدم. روزي در اتومبيلم نشسته بودم و به راديو گوش مي دادم كه وين داير شروع به سخنراني كرد. مضمون حرفش اين بود كه مانند مرغابيها كه مدام واك واك مي كنند، غرغر نكنيد، به خود آييد و چون عقابها اوج گيريد. پس از شنيدن آن گفتار راديويي، به پيرامون خود نگريستم و صحنه هايي را ديدم كه تا آن زمان گويي چشمانم را بر آنها بسته بودم. تاكسيهاي كثيفي كه رانندگانش مدام غرولند مي كردند، هيچگاه شاد و سرخوش نبودند و با مسافرانشان برخورد مناسبي نداشتند. سخنان وين داير، بر من چنان تاثيري گذاشت كه تصميم گرفتم تجديد نظري كلي در ديدگاهها و باورهايم به وجود آورم\r\nپرسيدم:  چه تفاوتي در زندگي تو حاصل شد؟\r\nگفت: سال اول، درآمدم دوبرابر شد و سال گذشته به چهار برابر رسيد. نكته اي كه مرا به تعجب واداشت اين بود كه در يكي دو سال گذشته، اين داستان را حداقل با سي راننده تاكسي در ميان گذاشتم اما فقط دو نفر از آنها به شنيدن آن رغبت نشان دادند و از آن استقبال كردند. بقيه چون مرغابيها، به انواع و اقسام عذر و بهانه ها متوسل شدند و به نحوي خود را متقاعد كردند كه چنين شيوه اي را نمي توانند برگزينند.\r\nشما، در زندگي خود از اختيار كامل برخورداريد و به همين دليل نمي توانيد گناه نابسامانيهاي خود را به گردن اين و آن بيندازيد. پس بهتر است برخيزيد، به عرصه پر تلاش زندگي وارد شويد و مرزهاي موفقيت را يكي پس از ديگري بگشاييد\r\nدنيا مانند پژواك اعمال و خواستهاي ماست\r\nاگر به جهان بگويي: سهم منو بده... \r\nدنيا مانند پژواكي كه از كوه برمي گردد، به تو خواهد گفت: سهم منو بده... و تو در كشمكش با دنيا دچار جنگ اعصاب مي شوي\r\nاما اگر به دنيا بگويي: چه خدمتي برايتان انجام دهم؟، دنيا هم به تو خواهد گفت: چه خدمتي برايتان انجام دهم؟\r\n"},{"id":1667,"category_id":10,"category_code":"s10","source_id":229,"title":"راه رفتن سگ روی آب","content":"شکارچی پرنده سگ جدیدی خریده بود، سگی که ویژگی منحصر به فردی داشت. این سگ میتوانست روی آب راه برود. شکارچی وقتی این را دید نمی توانست باور کند و خیلی مشتاق بود که این را به دوستانش بگوید. برای همین یکی از دوستانش را به شکار مرغابی در برکه ای آن اطراف دعوت کرد.\r\nاو و دوستش شكار را شروع كردند و چند مرغابي شكار كردند. بعد به سگش دستور داد كه مرغابي هاي شكار شده را جمع كند. در تمام مدت چند ساعت شكار، سگ روي آب مي دويد و مرغابي ها را جمع مي كرد. صاحب سگ انتظار داشت دوستش درباره اين سگ شگفت انگيز نظري بدهد يا اظهار تعجب كند، اما دوستش چيزي نگفت.\r\nدر راه برگشت، او از دوستش پرسيد آيا متوجه چيز عجيبي در مورد سگش شده است؟\r\nدوستش پاسخ داد: آره، در واقع، متوجه چيز غيرمعمولي شدم. سگ تو نمي تواند شنا كند.\r\nبعضي از افراد هميشه به ابعاد و نكات منفي توجه دارند. روي وجوه منفي تيم هاي كاري متمركز نشويد. با توجه به جنبه هاي مثبت و نقاط قوت، در كاركنان و تيم هاي كاري ايجاد انگيزه كنيد.\r\n"},{"id":1668,"category_id":10,"category_code":"s10","source_id":230,"title":"امسال زمستان سختی در راه است","content":"پائیز بود و سرخپوست ها از رئیس جدید قبیله پرسیدند که زمستان پیش رو سرد خواهد بود یا نه. از آنجایی که رئیس جدید از نسل جامعه مدرن بود از اسرار قدیمی سرخپوست ها چیزی نیاموخته بود. او با نگاه به آسمان نمی توانست تشخیص دهد زمستان چگونه خواهد بود. بنابراین برای اینکه جانب احتیاط را رعایت کند به افراد قبیله گفت که زمستان امسال سرد خواهد بود و آنان باید هیزم جمع کنند.\r\nچند روز بعد ايده اي به نظرش رسيد. به مركز تلفن رفت و با اداره هواشناسي تماس گرفت و پرسيد:آيا زمستان امسال سرد خواهد بود؟\r\nكارشناس هواشناسي پاسخ داد:به نظر مي رسد اين زمستان واقعاً سرد باشد.\r\nرئيس جديد به قبيله برگشت و به افرادش گفت كه هيزم بيشتري انبار كنند. يك هفته بعد دوباره از مركز هواشناسي پرسيد: آيا هنوز فكر مي كنيد كه زمستان سردي پيش رو داريم؟\r\nكارشناس جواب داد:بله، زمستان خيلي سردي خواهد بود.\r\nرئيس دوباره به قبيله برگشت و به افراد قبيله دستور داد كه هر تكه هيزمي كه مي بينند جمع كنند. هفته بعد از آن دوباره از اداره هواشناسي پرسيد:آيا شما كاملاً مطمئن هستيد كه زمستان امسال خيلي سرد خواهد بود؟\r\nكارشناس جواب داد: قطعاً و به نظر مي رسد زمستان امسال يكي از سردترين زمستان هايي باشد كه اين منطقه به خود ديده است.\r\nرئيس قبيله پرسيد:شما چطور مي توانيد اين قدر مطمئن باشيد؟\r\nكارشناس هواشناسي جواب داد:چون سرخپوست ها ديوانه وار در حال جمع آوري هيزم هستند.\r\nمديران ناكارآمد به دليل نداشتن دانش و تخصص لازم، مغرور بودن و خودخواهي، منفعت طلبي شخصي، انحصارطلبي و فراهم نكردن نظام هاي اطلاعاتي و تصميم گيري مناسب، در بيشتر موارد مرتكب تصميم هاي اشتباه و نابخردانه و شايد هم مغرضانه مي شوند كه هزينه هاي زيادي را به مجموعه تحت مديريت آنان وارد مي كند. اگر تصميم هاي نادرست اين گونه مديران آغازگر چرخه معيوبي نيز باشد در اين صورت اثرات منفي و مخرب اين تصميم ها بيشتر و بيشتر خواهد شد تا حدي كه مي تواند به بحران و يا نابودي سيستم منجر شود.\r\nمثالي از چرخه معيوب كه در واقعيت زياد اتفاق مي افتد از اين قرار است: مديريت سرمايه گذاري را كاهش مي دهد و از منابع مالي برداشت مي كند. مديريت با كاهش يا حذف توسعه كاركنان، توسعه محصولات جديد، تحقيق بازار و ديگر موارد هزينه ها را كاهش مي دهد و سود سهام و حقوق و مزاياي مديران را افزايش مي دهد و بدين صورت از سرمايه برداشت مي كند. نتيجه اين كار كاهش حقوق كاركنان، آموزش كاركنان در پايين ترين سطح، خط توليد روزآمد نشده يا منسوخ و ضعف در شناخت نيازهاي بازار و مشتريان خواهد بود. اين اثرات منفي باعث نارضايتي كاركنان، كاهش تعهد سازماني و افزايش نرخ خروج كاركنان خواهد شد. اين موارد موجب كاهش كيفيت محصولات و خدمات، نارضايتي مشتريان و جذب شدن آنان به سمت رقبا و از دست رفتن سهم بازار خواهد شد. كاهش فروش و سود باعث مي شود كه مديريت براي پرداخت هزينه هاي اوليه و جاري هم، دوباره از سرمايه برداشت كنند و بدين ترتيب چرخه معيوب ادامه مي يابد.\r\n"},{"id":1669,"category_id":10,"category_code":"s10","source_id":231,"title":"تله موش","content":"موش ازشکاف دیوار سرک کشید تا ببیند این همه سر و صدا برای چیست. مرد مزرعه دار تازه از شهر رسیده بود و بسته‌ای با خود آورده بود و زنش با خوشحالی مشغول باز کردن بسته بود .موش لب‌هایش را لیسید و با خود گفت :کاش یک غذای حسابی باشد. اما همین که بسته را باز کردند، از ترس تمام بدنش به لرزه افتاد چون صاحب مزرعه یک تله موش خریده بود.\r\nموش با سرعت به مزرعه برگشت تا اين خبر جديد را به همه حيوانات بدهد. او به هركسي كه مي‌رسيد، مي گفت: توي مزرعه يك تله موش آورد‌ه‌اند، صاحب مزرعه يك تله موش خريده است . مرغ با شنيدن اين خبر بال هايش را تكان داد و گفت:  آقاي موش، برايت متأسفم. از اين به بعد خيلي بايد مواظب خودت باشي، به هر حال من كاري به تله موش ندارم، تله موش هم ربطي به من ندارد. ميش وقتي خبر تله موش را شنيد ، صداي بلند سر داد و گفت: آقاي موش من فقط مي‌توانم دعايت كنم كه توي تله نيفتي، چون خودت خوب مي‌داني كه تله موش به من ربطي ندارد. مطمئن باش كه دعاي من پشت و پناه تو خواهد بود.موش كه از حيوانات مزرعه انتظار همدردي داشت، به سراغ گاو رفت. اما گاو هم با شنيدن خبر، سري تكان داد و گفت:  من كه تا حالا نديده‌ام يك گاوي توي تله موش بيفتد!او اين را گفت و زير لب خنده‌اي كرد و دوباره مشغول چريدن شد. سرانجام، موش نااميد از همه جا به سوراخ خودش برگشت و در اين فكر بود كه اگر روزي در تله موش بيفتد، چه مي شود؟ \r\nدر نيمه‌هاي همان شب، صداي شديد به هم خوردن چيزي در خانه پيچيد. زن مزرعه دار بلافاصله بلند شد و به سوي انباري رفت تا موش را كه در تله افتاده بود، ببيند. او در تاريكي متوجه نشد كه آنچه در تله موش تقلا مي كرده، موش نبود بلكه مار خطرناكي بود كه دمش در تله گير كرده بود. همين كه زن به تله موش نزديك شد، مار پايش را نيش زد و صداي جيغ و فريادش به هوا بلند شد. صاحب مزرعه با شنيدن صداي جيغ از خواب پريد و به طرف صدا رفت. وقتي زنش را در اين حال ديد او را فوراً به بيمارستان رساند. بعد از چند روز، حال وي بهتر شد. اما روزي كه به خانه برگشت، هنوز تب داشت. زن همسايه كه به عيادت بيمار آمده بود، گفت: براي تقويت بيمار و قطع شدن تب او هيچ غذايي مثل سوپ مرغ نيست. مرد مزرعه دار كه زنش را خيلي دوست داشت فوراً به سراغ مرغ رفت و ساعتي بعد بوي خوش سوپ مرغ در خانه پيچيد. اما هرچه صبر كردند، تب بيمار قطع نشد. بستگان او شب و روز به خانه آنها رفت و آمد مي‌كردند تا جوياي سلامتي او شوند. براي همين مرد مزرعه دار مجبور شد، ميش را هم قرباني كند تا با گوشت آن براي ميهمانان عزيزش غذا بپزد .\r\nروزها مي‌گذشت و حال زن مزرعه دار هر روز بدتر مي شد تا اين كه يك روز صبح، در حالي كه از درد به خود مي پيچيد از دنيا رفت و خبر مردن او خيلي زود در روستا پيچيد. افراد زيادي در مراسم خاكسپاري او شركت كردند. بنابراين، مرد مزرعه دار مجبور شد از گاوش هم بگذرد و غذاي مفصلي براي ميهمانان دور و نزديك تدارك ببيند .حالا، موش به تنهايي در مزرعه مي گرديد و به حيوانان زبان بسته‌اي فكر مي كرد كه كاري به كار تله موش نداشتند!به مسائل سطحي نگاه نكنيد. شايد مسائلي كه در نگاه اول، بي ارتباط با يكديگر به نظر مي رسند، به هم مربوط باشند. نگاه عميق و سيستماتيك به مسائل و تفكر دقيق در مورد آنها، مي‌تواند به مديران كمك كند تا ريشه مسائل و مشكلات را بهتر و درست تر شناسايي كنند و بتوانند راه حل هاي مناسبي براي حل آنها بيابند.\r\n"},{"id":1670,"category_id":10,"category_code":"s10","source_id":232,"title":"راه و رسم عاشقی ","content":"من یک عمر به خدا دروغ گفتم و خدا هیچ گاه به خاطر دروغ هایم مرا تنبیه نکرد. می توانست، اما رسوایم نساخت و مرا مورد قضاوت قرار نداد. هر آن چه گفتم باور کرد و هر بهانه ای آوردم پذیرفت. هر چه خواستم عطا کرد و هرگاه خواندمش حاضر شد.\r\nاما من! هرگز حرف خدا را باور نکردم، وعده هایش را شنیدم اما نپذیرفتم. چشم هایم را بستم تا خدا را نبینم و گوش هایم را نیز، تا صدای خدا را نشنوم. من از خدا گریختم بی خبر از آن که خدا با من و در من بود.\r\nمی خواستم کاخ آرزوهایم را آن طور که دلم می خواهد بسازم نه آن گونه که خدا می خواهد. به همین دلیل اغلب ساخته هایم ویران شد و زیر خروارها آوار بلا و مصیبت ماندم. من زیر ویرانه های زندگی دست و پا زدم و از همه کس کمک خواستم. اما هیچ کس فریادم را نشنید و هیچ کس یاریم نکرد. دانستم که نابودی ام حتمی است. با شرمندگی فریاد زدم خدایا اگر مرا نجات دهی، اگر ویرانه های زندگی ام را آباد کنی با تو پیمان می بندم هر چه بگویی همان را انجام دهم. خدایا! نجاتم بده که تمام استخوان هایم زیر آوار بلا شکست. در آن زمان خدا تنها کسی بود که حرف هایم را باور کرد ومرا پذیرفت. نمی دانم چگونه اما در کمترین مدت خدا نجاتم داد. از زیر آوار زندگی بیرون آمدم و دوباره احساس آرامش کردم. گفتم: خدای عزیز بگو چه کنم تا محبت تو را جبران نمایم.\r\nخدا گفت: هیچ، فقط عشقم را بپذیر و مرا باور کن و بدان در همه حال در کنار تو هستم.\r\nگفتم: خدایا عشقت را بپذیرفتم و از این لحظه عاشقت هستم. سپس بی آنکه نظر خدا را بپرسم به ساختن کاخ رویایی زندگی ام ادامه دادم. اوایل کار هر آن چه را لازم داشتم از خدا درخواست می کردم و خدا فوری برایم مهیا می کرد. از درون خوشحال نبودم. نمی شد هم عاشق خدا شوم و هم به او بی توجه باشم. از طرفی نمی خواستم در ساختن کاخ آرزوهای زندگی ام از خدا نظر بخواهم زیرا سلیقه خدا را نمی پسندیدم. با خود گفتم اگر من پشت به خدا کار کنم و از او چیزی در خواست نکنم بالاخره او هم مرا ترک می کند و من از زحمت عشق و عاشقی به خدا راحت می شوم. پشتم را به خدا کردم و به کارم ادامه دادم تا این که وجودش را کاملاً فراموش کردم. در حین کار اگر چیزی لازم داشتم از رهگذرانی که از کنارم رد می شدند درخواست کمک می کردم. عده ای که خدا را می دیدند با تعجب به من و به خدا که پشت سرم آماده کمک ایستاده بود نگاه می کردند و سری به نشانه تاسف تکان داده و می گذشتند. اما عده ای دیگر که جز سنگهای طلایی قصرم چیزی نمی دیدند به کمکم آمدند تا آنها نیز بهره ای ببرند. در پایان کار همان ها که به کمکم آمده بودند از پشت خنجری زهرآلود بر قلب زندگی ام فرو کردند. همه اندوخته هایم را یک شبه به غارت بردند و من ناتوان و زخمی بر زمین افتادم و فرار آنها را تماشا کردم. آنها به سرعت از من گریختند همان طور که من از خدا گریختم. هر چه فریاد زدم صدایم را نشنیدند همان طور که من صدای خدا را نشنیدم. من که از همه جا ناامید شده بودم باز خدا را صدا زدم. قبل از آنکه بخوانمش کنار من حاضر بود. گفتم: خدایا! دیدی چگونه مرا غارت کردند و گریختند. انتقام مرا از آنها بگیر و کمکم کن که برخیزم.\r\nخدا گفت: تو خود آنها را به زندگی ات فرا خواندی. از کسانی کمک خواستی که محتاج تر از هر کسی به کمک بودند. گفتم: مرا ببخش. من تو را فراموش کردم و به غیر تو روی آوردم و سزاوار این تنبیه هستم. اینک با تو پیمان می بندم که اگر دستم را بگیری و بلندم کنی هر چه گویی همان کنم. دیگر تو را فراموش نخواهم کرد. خدا تنها کسی بود که حرف ها و سوگندهایم را باور کرد. نمی دانم چگونه اما متوجه شدم که دوباره می توانم روی پای خود بایستم و به زودی خدای مهربان نشانم داد که چگونه آن دشمنان گریخته مرا، تنبیه کرد.\r\nگفتم: خدا جان بگو چگونه محبت تو را جبران کنم.\r\nخدا گفت: هیچ، فقط عشقم را بپذیر و مرا باور کن و بدان بی آنکه مرا بخوانی همیشه در کنار تو هستم.\r\nگفتم: چرا اصرار داری تو را باور کنم و عشقت را بپذیرم.\r\nگفت: اگر مرا باور کنی خودت را باور می کنی و اگر عشقم را بپذیری وجودت آکنده از عشق می شود. آن وقت به آن لذت عظیمی که در جست و جوی آنی می رسی و دیگر نیازی نیست خود را برای ساختن کاخ رویایی به زحمت بیندازی. چیزی نیست که تو نیازمند آن باشی زیرا تو و من یکی می شویم. بدان که من عشق مطلق، آرامش مطلق و نور مطلق هستم و از هر چیزی بی نیازم. اگر عشقم را بپذیری می شوی نور، آرامش و بی نیاز از هر چیز... \r\n\r\n\r\n\r\nخدایا همشه دوستت دارم ..\r\nهر آنچه شکر نعمتت را بجا آورم کم است\r\n"},{"id":1671,"category_id":10,"category_code":"s10","source_id":233,"title":"هر چه خدا بخواهد.. ","content":"\r\nآرتور اش\r\nقهرمان افسانه ای تنیس\r\nهنگامی که تحت عمل جراحی قلب قرار گرفت، با تزریق خون آلوده، به بیماری ایدز مبتلا شد.\r\nطرفداران آرتور از سر تا سر جهان نامه هایی محبت آمیز برایش فرستادند.\r\n\r\nیکی از دوستداران وی در نامه خویش نوشته بود: \"چرا خدا تو را برای ابتلا به چنین بیماری خطرناکی انتخاب کرده؟\"\r\nآرتور اش، در پاسخ این نامه چنین نوشت:...\r\nدر سر تا سر دنیا\r\nبیش از پنجاه میلیون کودک به انجام بازی تنیس علاقه مند شده و شروع به آموزش می کنند.\r\nحدود پنج میلیون از آن ها بازی را به خوبی فرا می گیرند.\r\nاز آن میان قریب پانصد هزار نفر تنیس حرفه ای را می آموزند\r\nو شاید پنجاه هزار نفر در مسابقات شرکت می کنند\r\nپنج هزار نفر به مسابقات تخصصی تر راه می یابند.\r\nپنجاه نفر اجازه شرکت در مسابقات بین المللی ویمبلدون را می یابند.\r\nچهار نفر به مسابقات نیمه نهایی راه می یابند.\r\nو دو نفر به مسابقات نهایی.\r\nوقتی که من جام جهانی تنیس را در دست هایم می فشردم هرگز نپرسیدم که \"خدایا چرا من؟\"\r\nو امروز وقتی که درد می کشم، باز هم اجازه ندارم که از خدا بپرسم :\"چرا من؟\"\r\n"},{"id":1672,"category_id":10,"category_code":"s10","source_id":234,"title":"لبخند ","content":"\r\nدر یکی از شهرهای اروپایی پیرمردی زندگی می کرد که تنها بود.\r\nهیچکس نمی دانست که چرا او تنهاست و زن و فرزندی ندارد.\r\nاو دارای صورتی زشت و کریه المنظر بود.\r\nشاید به خاطر همین خصوصیت هیچکس به سراغش نمی آمد ...\r\nو از او وحشت داشتند ، کودکان از او دوری می جستند\r\nو مردم از او کناره گیری می کردند.\r\nقیافه ی زننده و زشت پیرمرد مانع از این بود که کسی او را دوست داشته باشد\r\nو بتواند ساعتی او را تحمل نماید. علاوه بر این ، زشتی صورت پیرمرد باعث تغییر\r\nاخلاق او نیز شده بود.او که همه را گریزان از خود می دید دچار نوعی ناراحتی روحی شد\r\nکه می توان آن را به مالیخولیا تشبیه نمود همانطور که دیگران از او می گریختند\r\nاو هم طاقت معاشرت با دیگران را نداشت\r\nو با آنها پرخاشگری می نمود و مردم را از خود دور می کرد.\r\nسالها این وضع ادامه یافت تا اینکه یک روز همسایگان جدیدی در نزدیکی پیرمرد سکنی گزیدند آنها خانواده ی خوشبختی بودند که دختر جوان و زیبایی داشتند.یک روز دخترک که از ماجرای پیرمرد آگاهی نداشت از کنار خانه ی او گذشت اتفاقا همزمان با عبور او از کنار خانه ، پیرمرد هم بیرون آمد و دیدگان دخترک با وی برخورد نمود. اما ناگهان اتفاق تازه ای رخ داد پیرمرد با کمال تعجب مشاهده کرد که دخترک بر خلاف سایر مردم با دیدن صورت او احساس انزجار نکرد و به جای اینکه متنفر شده و از آنجا بگریزد به او لبخند زد.\r\nلبخند زیبای دخترک همچون گلی بر روی زشت پیرمرد نشست.آن دو بدون اینکه کلمه ای با هم سخن بگویند به دنبال کار خویش رفتند.همین لبخند دخترک در روحیه ی پیرمرد تاثیر بسزایی داشت . او هر روز انتظار دیدن او و لبخند زیبایش را می کشید.دخترک هر بار که پیرمرد را می دید ، شدت علاقه ی وی را به خویش در می یافت و با حرکات کودکانه ی خود سعی در جلب محبت او داشت.\r\n\r\nچند ماهی این ماجرا ادامه داشت تا اینکه دخترک دیگر پیرمرد را ندید. یک روز پستچی نامه ای به منزل آنها آورد و پدر دخترک نامه را دریافت کرد. وصیت نامه ی پیرمرد همسایه بود که همه ی ثروتش را به دختر او بخشیده بود.\r\n"},{"id":1673,"category_id":10,"category_code":"s10","source_id":235,"title":"دو ماهیگیر","content":"دو مرد در کنار دریاچه ای مشغول ماهیگیری بودند . یکی از آنها ماهیگیر با تجربه و ماهری بود اما دیگری ماهیگیری نمی دانست. \r\nهر بار که مرد با تجربه یک ماهی بزرگ می گرفت ، آن را در ظرف یخی که در کنار دستش بود می انداخت تا ماهی ها تازه بمانند ، اما دیگری به محض گرفتن یک ماهی بزرگ آنرا به دریا پرتاب می کرد. \r\nماهیگیر با تجربه از اینکه می دید آن مرد چگونه ماهی را از دست می دهد بسیار متعجب بود . لذا پس از مدتی از او پرسید: \r\n- چرا ماهی های به این بزرگی را به دریا پرت می کنی ؟\r\nمرد جواب داد : آخر تابه من کوچک است!\r\n"},{"id":1674,"category_id":10,"category_code":"s10","source_id":236,"title":"خروس ","content":"می گویند مردی ، خروسی خرید و به خانه برد. وقتی وارد شد ، همسر جوانش ، سر و رویش را پوشاند و نهیب زد: ای مرد! غیرتت چه شده است؟ روزها که تو نیستی ، آیا من باید با این خروس که جنس مخالف است ، تنها بمانم؟ خروس را بیرون ببر و از هر که خریده ای به او بازگردان!\r\n\r\nمرد ، خوشحال از این که ...\r\nزن چنان پاکدامنی دارد که حتی از خروس هم دوری می کند ، به بازار برگشت و خروس را به فروشنده اش که پیر مرد دنیا دیده ای بود پس داد.\r\n\r\nپیرمرد که ماوقع را شنید ، گفت: اشکالی ندارد؛ من خروسم را پس می گیرم ولی برو درباره زنت بیشتر تحقیق کن! کسی که درباره یک خروس چنین می کند ، لابد ریگی به کفش دارد و می خواهد رد گم کند.\r\n"},{"id":1675,"category_id":10,"category_code":"s10","source_id":237,"title":"لحظه آخر ","content":"به هنگام حمله ی ناپلئون به روسیه دسته ای از سربازان او در مرکز شهر کوچکی از آن سرزمین همیشه برف در حال جنگ بودند ...\r\nیکی از فرماندهان به طور اتفاقی از سواران خود جدا می افتد و گروهی از قزاقان روسی رد او را می گیرند و در خیابانهای پر پیچ و خم شهر به تعقیب او می پردازند .\r\n\r\nفرمانده که جان خود را در خطر می بیند پا به فرار می گذارد و سر انجام در کوچه ای سراسیمه وارد یک دکان پوست فروشی می شود و با مشاهده ی پوست فروش ملتمسانه و با نفس های بریده بریده فریاد می زند : کمکم کن جانم را نجات بده . کجا می توانم پنهان شوم؟!\r\nپوست فروش میگوید : زود باش بیا زیر این پوستینها و سپس روی فرمانده مقداری زیادی پوستین می ریزد ...\r\nپوست فروش تازه از این کار فارغ شده بود که قزاقان روسی شتابان وارد دکان می شوند و فریاد زنان می پرسند : او کجاست ؟ ما دیدیم که او آمد تو!!!\r\nقزاقان علیرغم اعتراضهای پوست فروش دکان را برای پیدا کردن فرمانده فرانسوی زیر و رو می کنند . آنها تل پوستین ها را با شمشیرهای تیز خود سیخ می زنند اما او را نمی یابند سپس راه خود را می گیرند و می روند .\r\nفرمانده پس از مدتی صحیح و سالم از زیر پوستینها بیرون می خزد و در همین لحظه سربازان او از راه می رسند .\r\n\r\nپوست فروش رو به فرمانده کرده و محجوب از او می پرسد : ببخشید که همچین سوالی از شخص مهمی چون شما می کنم اما می خواهم بدانم که اون زیر با علم به اینکه لحظه ی بعد آخرین لحظات زندگیتان است چه احساس داشتید ؟\r\nفرمانده قامتش را راست کرده و در حالی که سینه اش را جلو میداد خشمگین می غرد : تو به چه حقی جرات میکنی که همچین سوالی از من بپرسی ؟ سرباز این مردک گستاخ را ببرید چشماشو ببندید و اعدامش کنید . من خودم شخصا فرمان آتش را صادر خواهم کرد !!!\r\nمحافظان بر پیکر پوست فروش چنگ زده کشان کشان او را با خود می برند و سینه کش دیوار چشمان او را می بندند پوست فروش نمی تواند چیزی ببیند اما صدای ملایم و موجدار لباسهایش را در جریان باد سرد می شنود و برخورد ملایم باد سرد بر لباسهایش خنک شدن گونه هایش و لرزش غیر قابل کنترل پاهایش را احساس می کند ...\r\nسپس صدای فرمانده را می شنود که پس از صاف کردن گلویش به آرامی میگوید :\r\nآماده ............. هدف ......\r\nدر این لحظه پوست فروش با علم به این که تا چند لحظه ی دیگر همین چند احساس را نیز از دست خواهد داد ؛ احساسی غیر قابل وصف سر تا سر وجودش را در بر می گیرد و قطرات اشک از گونه هایش فرو می غلتد پس از سکوتی طولانی پوست فروش صدای گامهای را میشنود که به او نزدیک میشوند ...\r\n\r\nسپس نوار دور چشمان پوست فروش را بر می دارند . پوست فروش که در اثر تابش ناگهانی نور خورشید هنوز نیمه کور بود در مقابل خود فرمانده فرانسوی را می بیند که با چشمانی نافذ و معنی دار چشمانی که انگار بر ذره ذره وجودش اشراف دارد به او می نگرد...\r\nآنگاه به سخن آمده و به نرمی می گوید : حالا فهمیدی که چه احساسی داشتم ؟!\r\n"},{"id":1676,"category_id":10,"category_code":"s10","source_id":238,"title":"از پلنگ های زندگی نترسید! ","content":"روزی پلنگی وحشی به دهکده حمله کرده بود. شیوانا همراه با تعدادی ازجوانان برای شکار پلنگ به جنگل اطراف دهکده رفتند.\r\nاما پلنگ خودش را نشان نمی داد و دائم از تله شکارچیان می گریخت. سرانجام هوا تاریک شد و یکی از جوانان دهکده با اظهار اینکه پلنگ دارای قدرت جادویی است و مقصود آنها را حدس می زند خودش را ترساند و ترس شدیدی را بر تیم حاکم کرد.\r\nشیوانا با خوشحالی گفت که زمان شکار پلنگ فرا رسیده است و امشب ...\r\nحتما پلنگ خودش را نشان می دهد . ازقضا پلنگ همان شب خودش را به گروه شکارچیان نشان داد و با زخمی کردن جوانی که به شدت می ترسید ، سرانجام با تیر های بقیه از پا افتاد.\r\n\r\nیکی از جوانان از شیوانا پرسید:\r\n”چه چیزی باعث شد شما رخ نمایی پلنگ را پیش بینی کنید؟ در حالی که شب های قبل چنین چیزی نمی گفتید!؟”\r\nشیوانا گفت:\r\n” ترس جوان و باور او که پلنگ دارای قدرت جادویی است باعث شد پلنگ احساس قدرت کند و خود را شکست ناپذیر حس کند. این ترس ها و باورهای ترس آور و فلج کننده ما هستند که باعث قدرت گرفتن زورگویان و قدرت طلبان می شوند.\r\nپلنگ اگر می دانست که در تیم شکارچیان کسانی حضور دارند که از او نمی ترسند هرگز خودش را نشان نمی داد!”\r\n"},{"id":1677,"category_id":10,"category_code":"s10","source_id":239,"title":"جواب دندان شکن ","content":"روزی لئون تولستوی در خیابانی راه می رفت که ناآگاهانه به زنی تنه زد. زن بی وقفه شروع به فحش دادن و بد وبیراه گفتن کرد .\r\nبعد از مدتی که خوب تولستوی را فحش مالی کرد ،تولستوی کلاهش را از سرش برداشت و ...\r\nمحترمانه معذرت خواهی کرد و در پایان گفت : مادمازل من لئون تولستوی هستم .\r\nزن که بسیار شرمگین شده بود ،عذر خواهی کرد و گفت :چرا شما خودتان را زودتر معرفی نکردید ؟\r\nتولستوی در جواب گفت : شما آنچنان غرق معرفی خودتان بودید که به من مجال این کار را ندادید.\r\n"},{"id":1678,"category_id":10,"category_code":"s10","source_id":240,"title":"باورها ","content":"استفان کاوی (از سرشناسترین چهره‌های علم موفقیت) احتمالاً با الهام از همین حرف انیشتین است که می‌گوید:« اگر می‌خواهید در زندگی و روابط شخصی‌تان تغییرات جزیی به وجود آورید به گرایش‌ها و رفتارتان توجه کنید؛ اما اگر دلتان می‌خواهد قدم‌های کوانتومی بردارید و تغییرات اساسی در زندگی‌تان ایجاد کنید باید نگرش‌ها و برداشت‌هایتان را عوض کنید .»\r\nاو حرفهایش را با یک مثال خوب و واقعی، ملموس‌تر می‌کند:...\r\n« صبح یک روز تعطیل در نیویورک سوار اتوبوس شدم. تقریباً یک سوم اتوبوس پر شده بود. بیشتر مردم آرام نشسته بودند و یا سرشان به چیزی گرم بود و درمجموع فضایی سرشار از آرامش و سکوتی دلپذیر برقرار بود تا اینکه مرد میانسالی با بچه‌هایش سوار اتوبوس شد و بلافاصله فضای اتوبوس تغییر کرد. بچه‌هایش داد و بیداد راه انداختند و مدام به طرف همدیگر چیز پرتاب می‌کردند. یکی از بچه‌ها با صدای بلند گریه می‌کرد و یکی دیگر روزنامه را از دست این و آن می‌کشید و خلاصه اعصاب همه‌مان توی اتوبوس خرد شده بود. اما پدر آن بچه‌ها که دقیقاً در صندلی جلویی من نشسته بود، اصلاً به روی خودش نمی‌آورد و غرق در افکار خودش بود. بالاخره صبرم لبریز شد و زبان به اعتراض بازکردم که: «آقای محترم! بچه‌هایتان واقعاً دارند همه را آزار می‌دهند. شما نمی‌خواهید جلویشان را بگیرید؟» مرد که انگار تازه متوجه شده بود چه اتفاقی دارد می‌افتد، کمی خودش را روی صندلی جابجا کرد و گفت: بله، حق با شماست. واقعاً متاسفم. راستش ما داریم از بیمارستانی برمی‌گردیم که همسرم، مادر همین بچه‌ها٬ نیم ساعت پیش در آنجا مرده است. من واقعاً گیجم و نمی‌دانم باید به این بچه‌ها چه بگویم. نمی‌دانم که خودم باید چه کار کنم و ... و بغضش ترکید و اشکش سرازیر شد.»\r\n\r\nاستفان کاوی بلافاصله پس از نقل این خاطره می‌پرسد:« صادقانه بگویید آیا اکنون این وضعیت را به طور متفاوتی نمی‌بینید؟ چرا این طور است؟ آیا دلیلی به جز این دارد که نگرش شما نسبت به آن مرد عوض شده است؟ » و خودش ادامه می‌دهد که:« راستش من خودم هم بلافاصله نگرشم عوض شد و دلسوزانه به آن مرد گفتم: واقعاً مرا ببخشید. نمی‌دانستم. آیا کمکی از دست من ساخته است؟ و....\r\n\r\nاگر چه تا همین چند لحظه پیش ناراحت بودم که این مرد چطور می‌تواند تا این اندازه بی‌ملاحظه باشد٬ اما ناگهان با تغییر نگرشم همه چیز عوض شد و من از صمیم قلب می‌خواستم که هر کمکی از دستم ساخته است انجام بدهم .»\r\n"},{"id":1679,"category_id":10,"category_code":"s10","source_id":241,"title":"به خاطر خودم ","content":"مرد جوانی پدر پیرش مریض شد. چون وضع بیماری پیرمرد شدت گرفت او را در گوشه جاده ای رها کرد و از آنجا دور شد. پیرمرد ساعت ها کنار جاده افتاده بود و به زحمت نفس های آخرش را می کشید. رهگذران از ترس واگیرداشتن بیماری و فرار از دردسر روی خود را به سمت دیگری می چرخاندند و بی اعتنا به پیرمرد ....\r\nنالان راه خود را می گرفتند و می رفتند. شیوانا از آن جاده عبور می کرد. به محض اینکه پیرمرد را دید او را بر دوش گرفت تا به مدرسه ببرد و درمانش کند. یکی از رهگذران به طعنه به شیوانا گفت:\" این پیرمرد فقیر است و بیمار و مرگش نیز نزدیک! نه از او سودی به تو می رسد و نه کمک تو تغییری در اوضاع این پیرمرد باعث می شود. حتی پسرش هم او را در اینجا به حال خود رها کرده و رفته است. تو برای چی به او کمک می کنی!؟\"شیوانا به رهگذر گفت:\" من به او کمک نمی کنم!! من دارم به خودم کمک می کنم. اگر من هم مانند پسرش و رهگذران او را به حال خود رها کنم چگونه روی به آسمان برگردانم و از خالق هستی تقاضای هم صحبتی داشته باشم. من دارم به خودم کمک می کنم !\"\r\n"},{"id":1680,"category_id":10,"category_code":"s10","source_id":242,"title":"خدا پشت پنجره ایستاده ","content":"جانی کوچولو با پدر و مادر و خواهرش سالی برای دیدن پدربزرگ و مادربزرگ رفته بودن به مزرعه. مادربزرگ یه تیرکمون به جانی داد تا باهاش بازی کنه. موقع بازی جانی به اشتباه یه تیر به سمت اردک خونگی مادربزرگش پرت کرد که به سرش خورد و اونو کشت\r\nجانی وحشت زده شد...\r\nلاشه رو برداشت و برد پشت هیزمها قایم کرد. وقتی سرشو بلند کرد دید که خواهرش  همه چیزو دیده ... ولی حرفی نزد.\r\nمادربزرگ به سالی گفت \"توی شستن ظرفها کمکم کن\" ولی سالی گفت: \" مامان بزرگ جانی بهم گفته که میخواد تو کارای آشپزخونه کمک کنه\" و زیر لبی به جانی گفت: \" اردکه رو یادت میاد؟\" ... جانی ظرفا رو شست\r\nبعد از ظهر اون روز پدربزرگ گفت که میخواد بچه ها رو ببره ماهیگیری ولی مادربزرگ گفت :\" متاسفانه من برای درست کردن شام به کمک سالی احتیاج دارم\" سالی لبخندی زد و گفت:\"نگران نباشید چونکه جانی به من گفته میخواد کمک کنه\" و زیر لبی به جانی گفت: \" اردکه رو یادت میاد؟\"... اون روز سالی رفت ماهیگیری و جانی تو درست کردن شام کمک کرد.\r\nچند روزی به همین منوال گذشت و جانی مجبور بود علاوه بر کارای خودش کارای سالی رو هم انجام بده. تا اینکه نتونست تحمل کنه و رفت پیش مادربزرگش و همه چیز رو بهش اعتراف کرد. مادربزرگ لبخندی زد و اونو در آغوش گرفت و گفت:\" عزیزدلم میدونم چی شده. من اون موقع کنارپنجره بودم و همه چیزو دیدم اما چون خیلی دوستت دارم بخشیدمت. من فقط میخواستم ببینم تا کی میخوای به سالی اجازه بدی به خاطر یه اشتباه تو رو در خدمت خودش بگیره!\"\r\n"},{"id":1681,"category_id":10,"category_code":"s10","source_id":243,"title":"رحمت خدا ","content":"پیر مرد تهی دست، زندگی را در نهایت فقر و تنگدستی می گذراند و با سائلی برای زن و فرزندانش قوت و غذائی ناچیز فراهم می کرد. از قضا یک روز که به آسیاب رفته بود، دهقان مقداری گندم در دامن لباس اش ریخت و پیرمرد گوشه های آن را به هم گره زد و در...\r\nهمان حالی که به خانه بر می گشت با پروردگار از مشکلات خود سخن می گفت و برای گشایش آنها فرج می طلبید و تکرار می کرد: ای گشاینده گره های ناگشوده عنایتی فرما و گره ای از گره های زندگی ما بگشای. پیر مرد در حالی که این دعا را با خود زمزمه می کرد و می رفت، یکباره یک گره از گره های دامنش گشوده شد و گندم ها به زمین ریخت او به شدت ناراحت شد و رو به خدا کرد و گفت:\r\nمن تو را کی گفتم ای یار عزیز / کاین کره بگشای و گندم را بریز / آن گره را چون نیارستی گشود/ این گره بگشوندنت دیگر چه بود\r\nپیر مرد نشست تا گندم های به زمین ریخته را جمع کند ولی در کمال ناباوری دید دانه های گندم روی همیانی از زر ریخته است. پس متوجه فضل و رحمت خداوندی شد و متواضعانه به سجده افتاد و از خدا طلب بخشش نمود.\r\n\r\nتو مبین اندر درختی یا به چاه/ تو مرا بین که منم مفتاح راه ( مولانا)\r\n"},{"id":1682,"category_id":10,"category_code":"s10","source_id":244,"title":"زنجیر عشق ","content":"یک روز بعد از ظهر وقتی اسمیت داشت از کار برمی گشت خانه، سر راه زن مسنی را دید که ماشینش خراب شده و ترسان توی برف ایستاده بود .اون زن برای او دست تکان داد تا متوقف شود.\r\nاسمیت پیاده شد و خودشو معرفی کرد و گفت من اومدم کمکتون کنم....\r\nزن گفت صدها ماشین از جلوی من رد شدند ولی کسی نایستاد، این واقعا لطف شماست .\r\nوقتی که او لاستیک رو عوض کرد و درب صندوق عقب رو بست و آماده رفتن شد، زن پرسید:\" من چقدر باید بپردازم؟\"\r\nو او به زن چنین گفت: \" شما هیچ بدهی به من ندارید. من هم در این چنین شرایطی بوده ام.\r\nو روزی یکنفر هم به من کمک کرد¸همونطور که من به شما کمک کردم.\r\nاگر تو واقعا می خواهی که بدهیت رو به من بپردازی، باید این کار رو بکنی.\r\nنگذار زنجیر عشق به تو ختم بشه!\"\r\n****\r\nچند مایل جلوتر زن کافه کوچکی رو دید و رفت تو تا چیزی بخوره و بعد راهشو ادامه بده ولی نتونست\r\nبی توجه از لبخند شیرین زن پیشخدمتی بگذره که می بایست هشت ماهه باردار باشه و از خستگی روی پا بند نبود.\r\nاو داستان زندگی پیشخدمت رو نمی دانست و احتمالا هیچ گاه هم نخواهد فهمید.\r\nوقتی که پیشخدمت رفت تا بقیه صد دلار شو بیاره ، زن از در بیرون رفته بود ،\r\nدرحالیکه بر روی دستمال سفره یادداشتی رو باقی گذاشته بود.\r\nوقتی پیشخدمت نوشته زن رو می خوند اشک در چشمانش جمع شده بود.\r\nدر یادداشت چنین نوشته بود:\" شما هیچ بدهی به من ندارید.\r\n\r\nمن هم در این چنین شرایطی بوده ام. و روزی یکنفر هم به من کمک کرد، همونطور که من به شما کمک کردم.\r\nاگر تو واقعا می خواهی که بدهیت رو به من بپردازی، باید این کار رو بکنی.\r\nنگذار زنجیر عشق به تو ختم بشه!\".\r\n****\r\nهمان شب وقتی زن پیشخدمت از سرکار به خونه رفت در حالیکه به اون پول و یادداشت زن فکر می کرد به شوهرش گفت :\"دوستت دارم اسمیت همه چیز داره درست میشه...\r\n"},{"id":1683,"category_id":10,"category_code":"s10","source_id":245,"title":"جوان ثروتمند و پند عارف ","content":"جوان ثروتمندی نزد عارفی رفت و از او اندرزی برای زندگی نیک خواست.\r\nعارف او را به کنار پنجره برد و پرسید: چه می بینی؟\r\nگفت: آدم هایی که می آیند و می روند و گدای کوری که در خیابان صدقه می گیرد\r\nبعد آینه بزرگی به او نشان داد و باز پرسید: در آینه نگاه کن و بعد بگو چه می بینی؟\r\nگفت: خودم را می بینم !\r\nعارف گفت: ....\r\nدیگر دیگران را نمی بینی !\r\nآینه و پنجره هر دو از یک ماده ی اولیه ساخته شده اند : شیشه\r\nاما در آینه لایه ی نازکی از نقره در پشت شیشه قرار گرفته و در آن چیزی جز شخص خودت را نمی بینی\r\nاین دو شی شیشه ای را با هم مقایسه کن :\r\nوقتی شیشه فقیر باشد، دیگران را می بیند و به آن ها احساس محبت می کند.\r\nاما وقتی از جیوه (یعنی ثروت) پوشیده می شود، تنها خودش را می بیند\r\nتنها وقتی ارزش داری که شجاع باشی و آن پوشش جیوه ای را از جلو چشم هایت برداری،\r\nتا بار دیگر بتوانی دیگران را ببینی و دوستشان بداری\r\n"},{"id":1684,"category_id":10,"category_code":"s10","source_id":246,"title":"افسوس تکراری ","content":"پیری برای جمعی سخن میراند،\r\nلطیفه ای برای حضار تعریف کرد همه دیوانه وار خندیدند.\r\n\r\nبعد از لحظه ای او دوباره همان لطیفه را گفت و تعداد کمتری از حضار\r\nخندیدند....\r\nاو مجدد لطیفه را تکرار کرد تا اینکه دیگر کسی در جمعیت به آن لطیفه نخندید.\r\n\r\nاو لبخندی زد و گفت:\r\nوقتی که نمیتوانید بارها و بارها به لطیفه ای یکسان بخندید،\r\nپس چرا بارها و بارها به گریه و افسوس خوردن در مورد مسئله ای مشابه ادامه\r\nمیدهید؟\r\n\r\nگذشته را فراموش کنید و به جلو نگاه کنید\r\n"},{"id":1685,"category_id":10,"category_code":"s10","source_id":247,"title":"نیت ","content":"مدت ها پیش کشاورز فقیری برای پیداکردن غذا یا شکاری به دل جنگل رفت .هنوز مسیر زیادی را طی نکرده بود که صدای فریاد کمکی به گوشش رسید.او صدا را دنبال کرد تا به منبع آن رسید و دید که پسر بچه ای در باتلاقی افتاد و آهسته و آرام به سمت پایین می رود .آن پسربچه به شدت وحشت زده بود و با چشمانش به کشاورز التماس می کرد تا جانش را نجات دهد.کشاورز با هزار بدبختی با به خطر انداختن جان خودش بالاخره موفق شد پسرک را از مرگ حتمی و تدریجی نجات دهد و او را از باتلاق بیرون بکشد....\r\nفردای آن روز وقتی که کشاورز روی روی زمینش مشغول کار بود،کالسکه سلطنتی مجللی در کنار نرده های ورودی زمین کشاورز ایستاد .دو سرباز از آن پیاده شدند و در را برای آقای قد بلندی که لباس های اشرافی بر تن داشت ،بازکردند.زمانی که آن مرد با لباس های گران قیمتی که برتن داشت پایین آمد ،خود را پدر پسری که کشاورز روز گذشته او را از مرگ نجات داده بود،معرفی کرد.اوبه کشاورز گفت که می خواهد این محبتش را جبران کند وحاضر است در عوض کار بزرگی که او انجام داده،هرچه بخواهد به او بدهد .\r\nکشاورز با مناعت طبعی که داشت به مرد ثروتمند گفت که او این کار را برای رضای خدا وبه خاطر انسانیت انجام داده و هیچ چشم داشتی در مقابل آن ندارد.در همین موقع پسرکشاورز از ساختمان وسط زمین بیرون آمد.مرد ثروتمند که متوجه شد کشاورز پسرس هم سن وسال پسر خودش دارد ،به پیرمردگفت که می خواهد یک معامله با او بکند.مردثروتمند گفت حال که تو پسرم را نجات دادی ،من هم پسر تو را مثل پسر خودم می دانم .پس اجازه بده هزینه تحصیل او را در بهترین مدارس ودانشگاهها بپردازم .کشاورز موافقت کرد وپسرش پس از چند سال از دانشگاه علوم پزشکی لندن فارغ التحصیل شد وبه خاطر کشف یکی از بزرگ ترین ومهم ترین داروهای نجات بخش جهان که پنی سیلین بود،به عنوان یک دانشمند مشهور شناخته شد .آن پسر کسی نبود جز الکساندر فلیمینگ .چندسال گذشت .دست بر قضا پسر مرد ثروتمند به بیماری لاعلاجی مبتلا شد و این بار الکساندر،پسر کشاورز که امروز یک دانشمند برجسته بود با داروی جدیدش بار دیگر جان آن پسر را نجات داد .\r\nجالب است بدانید که آن مرد ثروتمند و نجیب زاده کسی نبود جز لردراندلف چرچیل و پسرش هم کسی نبود جز وینستون چرچیل .\r\n"},{"id":1686,"category_id":10,"category_code":"s10","source_id":248,"title":"برادر.... ","content":"شخصی به نام پل یک دستگاه اتومبیل سواری به عنوان عیدی از برادرش دریافت کرده بود\" شب عید هنگامی که پل از اداره اش بیرون امد متوجه پسر بچه شیطانی شد که دور و بر ماشین نو و براقش قدم میزند و ان راتحسین می کرد\"پل نزدیک ماشین که رسید پسر پرسید:این ماشین مال شماست\" اقا؟ پل سرش را به علامت تائید تکان داد و گفت: برادرم به عنوان عیدی به من داده است.پسر متعجب شد وگفت:منظورتان این است که برادرتان این ماشین را همین جوری \"بدون اینکه دیناری بابت ان پرداخت کنید\"به شما داده است؟ اخ جون \" ای کاش...؟\r\nالبته پل کاملا واقف بود که پسر چه ارزویی می خواهد بکند\" او می خواست ارزو کند که ای کاش او هم یک همچون برادری داشت\" اما انچه که پسر گفت:سر تا پای وجود پل را به لرزه در اورد:ای کاش من هم یک همچو برادری بودم\"\r\n\r\nپل مات و مبهوت به پسر نگاه کرد و سپس با یک انگیزه انی گفت: دوست داری با هم تو ماشین یه گشتی بزنیم؟\r\n\"اوه بله دوست دارم\"\r\n\r\nتازه راه افتاده بودند که پسر به طرف پل برگشت و با چشمانی که از خوشحالی برق می زد گفت:\"اقا می شه خواهش کنم که بری به طرف خونه ما؟\"\r\nپل لبخند زد. او خوب فهمید که پسر چه می خواهد بگوید: او می خواست به همسایگانش نشان دهد که توی چه ماشین بزرگ و شیکی به خانه برگشته است. اما پل باز هم در اشتباه بود... پسر گفت: بی زحمت اونجایی که دوتا پله داره نگهدارید.\r\nپسر از پله ها بالا دوید\" چیزی نگذشت که پل صدای برگشتن او را شنید. اما دیگر تند وتیز بر نمی گشت\"او برادر کوچک فلج و زمین گیر خود را بر پشت حمل کرده بود. سپس او را روی پله پائینی نشاند و به طرف ماشین اشاره کرد: \"اوناهاش جیمی\"می بینی؟درست همون طوریه که طبقه بالا برات تعریف کردم \"برادرش عیدی بهش داده و دیناری بابت ان پرداخت نکرده. یه روزی من هم یه همچو ماشینی به تو هدیه خواهم داد...\r\nاونوقت می تونی برای خودت بگردی و چیزهای قشنگ ویترین مغازه های شب عید رو همان طوری که همیشه برات شرح میدم ببینی\"\r\nپل در حالی که اشکهای گوشه چشمش را پاک می کرد از ماشین پیاده شد و پسر بچه را در صندلی جلوئی ماشین نشاند\" برادر بزرگتر با چشمانی براق و درخشان کنار او نشست و سه تائی رهسپار گردشی فراموش ناشدنی شدند.\r\n"},{"id":1687,"category_id":10,"category_code":"s10","source_id":249,"title":"اثر ","content":"یکشنبه بود و طبق معمول هر هفته\r\nرزی ، خانم نسبتا مسن محله ، داشت از کلیسا برمیگشت …\r\nدر همین حال نوه اش از راه رسید و با کنایه بهش گفت :\r\nمامان بزرگ ، تو مراسم امروز ، پدر روحانی براتون چی موعظه کرد ؟!\r\nخانم پیر مدتی فکر کرد و سرش رو تکون داد و گفت :...\r\nعزیزم ، اصلا یک کلمه اش رو هم نمیتونم به یاد بیارم !!!\r\nنوه پوزخند ی زد و بهش گفت :\r\nتو که چیزی یادت نمیاد ، واسه چی هر هفته همش میری کلیسا ؟!!\r\nمادر بزرگ تبسمی بر لبانش نقش بست .\r\nخم شد سبد نخ و کامواش رو خالی کرد و داد دست نوه و گفت :\r\nعزیزم ممکنه بری اینو از حوض پر آب کنی و برام بیاری ؟!\r\nنوه با تعجب پرسید : تو این سبد ؟ غیر ممکنه\r\nبا این همه شکاف و درز داخل سبد آبی توش بمونه !!!\r\nرزی در حالی که تبسم بر لبانش بود اصرار کرد : لطفا این کار رو انجام بده عزیزم\r\nدخترک غرولند کنان و در حالی که مادربزرگش رو تمسخر میکرد\r\nسبد رو برداشت و رفت ، اما چند لحظه بعد ، برگشت و با لحن پیروزمندانه ای گفت :\r\nمن میدونستم که امکان پذیر نیست ، ببین حتی یه قطره آب هم ته سبد نمونده !\r\nمادر بزرگ سبد رو از دست نوه اش گرفت و با دقت زیادی وارسیش کرد گفت :\r\nآره ، راست میگی اصلا آبی توش نیست\r\nاما بنظر میرسه سبده تمیزتر شده ، یه نیگاه بنداز …!\r\n"},{"id":1688,"category_id":10,"category_code":"s10","source_id":250,"title":"داستان عشق ","content":"دختری کنجکاو میپرسید: ایها الناس عشق یعنی چه؟\r\nدختری گفت: اولش رویا آخرش بازی است و بازیچه\r\nمادرش گفت: عشق یعنی رنج پینه و زخم و تاول کف دست\r\nپدرش گفت: بچه ساکت باش بی ادب! این به تو نیامده است\r\nرهروی گفت: کوچه ای بن بست\r\nسالکی گفت: ....\r\nراه پر خم و پیچ\r\nدر کلاس سخن معلم گفت: عین و شین است و قاف، دیگر هیچ\r\nدلبری گفت: شوخی لوسی است\r\nتاجری گفت: عشق کیلو چند؟\r\nمفلسی گفت: عشق پر کردن شکم خالی زن و فرزند\r\nشاعری گفت: یک کمی احساس مثل احساس گل به پروانه\r\nعاشقی گفت: خانمان سوز است بار سنگین عشق بر شانه\r\nشیخ گفتا: گناه بی بخشش\r\nواعظی گفت: واژه بی معناست\r\nزاهدی گفت: طوق شیطان است\r\nمحتسب گفت: منکر عظماست\r\nقاضی شهر گفت: عشق را فرمود حد هشتاد تازیانه به پشت\r\nجاهلی گفت: عشق را عشق است\r\nپهلوان گفت: جنگ آهن و مشت\r\nرهگذر گفت: طبل تو خالی است یعنی آهنگ آن ز دور خوش است\r\nدیگری گفت: از آن بپرهیزید یعنی از دور کن بر آتش دست\r\nچون که بالا گرفت بحث و جدل توی آن قیل و قال من دیدم\r\nطفل معصوم با خودش می گفت: من فقط یک سوال پرسیدم!\r\n"},{"id":1689,"category_id":10,"category_code":"s10","source_id":251,"title":"علامه جعفری و ازدواج با زیباترین دختر دنیا ","content":"از علامه جعفری می‌پرسند چی شد که به این کمالات رسیدی؟! ایشان در جواب خاطره‌ای از دوران طلبگی تعریف و اظهار می‌کنند که هرچه دارند از کراماتی است که به دنبال این امتحان الهی نصیبشان شده\r\n«ما در نجف در مدرسه صدر اقامت داشتیم. خیلی مقید بودیم، در جشن‌ها و ایام سرور، مجالس جشن بگیریم و ایام سوگواری را هم، سوگواری می‌گرفتیم.\r\nشبی مصادف شده بود با ولادت حضرت فاطمه زهرا(س) اول شب نماز مغرب و عشا می‌خواندیم و شربتی می‌خوردیم. آن گاه با فکاهیاتی مجلس جشن و سرور ترتیب می‌دادیم.\r\nآقایی بود به نام آقا شیخ حیدرعلی اصفهانی که نجف‌آبادی بود. معدن ذوق بود. او که می‌آمد من به الکفایه قطعاً به وجود می‌آمد جلسه دست او قرار می‌گرفت.\r\n\r\nآن ایام مصادف شده بود با...\r\nایام قلب‌الاسد (۱۰ تا ۲۱ مرداد) که ما خرماپزان می‌گوییم و نجف با ۲۵ یا ۳۵ درجه خیلی گرم می‌شد. آن سال در اطراف نجف باتلاقی درست شده بود و پشه‌هایی به وجود آمده بود که عرب‌های بومی را اذیت می‌کرد. ما ایرانی‌ها هم که، اصلاً خواب و استراحت نداشتیم.آن سال آنقدر گرما زیاد بود که اصلاً قابل تحمل نبود نکته سوم این‌که حجره من رو به شرق بود. تقریباً هم مخروبه بود.من فروردین را آنجا به طور طبیعی مطالعه می‌کردم و می‌خوابیدم. اردیبهشت هم مقداری قابل تحمل بود، ولی دیگر از خرداد امکان استفاده از حجره نبود.\r\nگرما واقعاً کشنده بود. وقتی می‌خواستم بروم از حجره کتاب بردارم مثل این بود که با دست نان را از داخل تنور برمی‌دارم، در اقل وقت و سریع!\r\nبا این تعاریف این جشن افتاده بود به این موقع، در بغداد و بصره و نجف، گرما تلفات هم گرفته بود. ما بعد از شب نشستیم، شربت هم درست شد، آقا شیخ حیدرعلی اصفهانی که کتابی هم نوشته بود به نام «شناسنامه خر» آمد.\r\nمدیر مدرسه‌مان، مرحوم آقا سیداسماعیل اصفهانی هم آنجا بود. به آقا شیخ علی گفت: آقا شب نمی‌گذره، حرفی داری بگو، ایشان یک تکه کاغذ روزنامه در آورد.\r\nعکس یک دختر بود که زیرش نوشته بود «اجمل بنات عصرها» (زیباترین دختر روزگار)، گفت: آقایان من درباره این عکس از شما سوالی می‌کنم.\r\nاگر شما را مخیر کنند بین این‌که با این دختر به طور مشروع و قانونی ازدواج کنید (از همان اولین لحظه ملاقات عقد جاری شود و حتی یک لحظه هم خلاف شرع نباشد) و هزار سال هم زندگی کنید، با کمال خوشرویی و بدون غصه، یا این‌که جمال علی(ع) را مستحباً زیارت و ملاقات کنید، کدام را انتخاب می‌کنید.\r\n\r\nسوال خیلی حساب شده بود. طرف دختر حلال بود و زیارت علی(ع) هم مستحبی. گفت: آقایان واقعیت را بگویید. جانماز آب نکشید، عجله نکنید، درست جواب دهید.\r\nاول کاغذ را مدیر مدرسه گرفت و نگاه کرد و خطاب به پسرش که در کنارش نشسته بود با لهجه اصفهانی، گفت: سیدمحمد! ما یک چیزی بگوییم نری به مادرت بگویی‌ها؟ معلوم شد نظر آقا چیست. شاگرد اول ما نمره‌اش را گرفت! همه زدند زیر خنده. کاغذ را به دومی دادند. نگاهی به عکس کرد و گفت: آقا شیخ علی، اختیار داری، وقتی آقا (مدیر مدرسه) این‌طور فرمودند مگر ما قدرت داریم که خلافش را بگوییم. آقا فرمودند دیگه! خوب در هر تکه خنده راه می‌افتاد.\r\nنفر سوم گفت: آقا شیخ حیدر این روایت از امام علی(ع) معروف است که فرموده‌اند: «یا حارث حمدانی من یمت یرنی» (ای حارث حمدانی هر کی بمیرد مرا ملاقات می‌کند)‌\r\nپس ما ان‌شاءالله در موقعش جمال علی(ع) را ملاقات می‌کنیم! باز هم همه زدند زیرخنده، خوب اهل ذوق بودند. واقعاً سوال مشکلی بود. یکی از آقایان گفت: آقا شیخ حیدر گفتی زیارت آقا مستحبی است؟ گفتی آن هم شرعی صد درصد؟ آقا شیخ حیدر گفت: بلی.\r\nگفت: والله چه عرض کنم. (باز هم خنده حضار)‌\r\nنفر پنجم من بودم. این کاغذ را دادند دست من. دیدم که نمی‌توانم نگاه کنم، کاغذ را رد کردم به نفر بعدی، گفتم: من یک لحظه دیدار علی(ع) را به هزاران سال زناشویی با این زن نمی‌دهم. یک وقت دیدم یک حالت خیلی عجیبی دست داد. تا آن وقت همچو حالتی ندیده بودم. شبیه به خواب و بیهوشی بلند شدم. اول شب قلب‌الاسد وارد حجره‌ام شدم، حالت غیرعادی، حجره رو به مشرق دیگر نفهمیدم، یک‌بار به حالتی دست یافتم. یکدفعه دیدم یک اتاق بزرگی است یک آقایی نشسته در صدر مجلس، تمام علامات و قیافه‌ای که شیعه و سنی درباره امام علی(ع) نوشته در این مرد موجود است. یک جوانی پیش من در سمت راستم نشسته بود. پرسیدم: این آقا کیست؟\r\nگفت: این آقا خود علی(ع) است، من سیر او را نگاه کردم. آمدم بیرون، رفتم همان جلسه، کاغذ رسیده دست نفر نهم یا دهم، رنگم پریده بود. نمی‌دانم شاید مرحوم شمس‌آبادی بود خطاب به من گفت: آقا شیخ محمدتقی شما کجا رفتید و آمدید؟ نمی‌خواستم ماجرا را بگویم، اگر بگم عیششون بهم می‌خوره، اصرار کردند و من بالاخره قضیه را گفتم و ماجرا را شرح دادم، خیلی منقلب شدند.\r\nخدا رحمت کند آقا سیداسماعیل (مدیر) را خطاب به آقا شیخ حیدر، گفت: آقا دیگر از این شوخی‌ها نکن، ما را بد آزمایش کردی. این از خاطرات بزرگ زندگی من است. \r\n"},{"id":1690,"category_id":10,"category_code":"s10","source_id":252,"title":"جایزه ","content":"جنایت کاری که یک آدم را کشته بود، در حال فرار و آوارگی، با لباس ژنده و پرگرد و خاک و دست و صورت کثیف، خسته و کوفته ، به یک دهکده رسید.\r\nچند روزی چیزی نخورده و بسیار گرسنه بود. او جلوی مغازه میوه فروشی ایستاد و به پرتقال های بزرگ و تازه خیره شد. اما بی پول بود. بخاطر همین دو دل بود که پرتقال را به زور از میوه فروش بگیرد یا آن را گدائی کند. دستش توی جیبش تیغه چاقو را لمس می کرد که به یکباره پرتقالی را جلوی چمشش دید. بی اختیار چاقو را در جیب خود رها کرد و....پرتقال را از دست مرد میوه فروش گرفت. میوه فروش گفت : بخور نوش جانت ، پول نمی خواهم\r\nسه روز بعد آدمکش فراری باز در جلو دکه میوه فروش ظاهر شد. این دفعه بی آنکه کلمه ای ادا کند ،صاحب دکه فوراً چند پرتقال را در دست او گذاشت، فراری دهان خود را باز کرده گوئی میخواست چیزی بگوید، ولی نهایتاً در سکوت پرتقال ها را خورد و با شتاب رفت.\r\nآخر شب صاحب دکه وقتی که بساط خود را جمع می کرد، صفحه اول یک روزنامه به چشمش خورد. میوه فروش مات و متحیر شد وقتی که عکس توی روزنامه را شناخت. عکس همان مردی بود که با لباسهای ژنده از او پرتقال مجانی میگرفت. زیر عکس او با حروف درشت نوشته بودند قاتل فراری و برای کسی که او را معرفی کند نیز مبلغی بعنوان جایزه تعیین کرده بودند.\r\nمیوه فروش بلافاصله شماره پلیس را گرفت. پلیس ها چند روز متوالی در اطراف دکه در کمین بودند. سه چهار روز بعد مرد جنایتکار دوباره در دکه میوه فروشی ظاهر شد، با همان لباسی که در عکس روزنامه پوشیده بود .\r\nاو به اطراف نگاه کرد، گوئی متوجه وضعیت غیر عادی شده بود. دکه دار و پلیس ها با کمال دقت جنایتکار فراری را زیر نظر داشتند. او ناگهان ایستاد و چاقویش را از جیب بیرون آورده و به زمین انداخت و با بالا نگهداشتن دو دست خود به راحتی وارد حلقه محاصره پلیس شده و بدون هیچ مقاومتی دستگیر گردید.\r\nموقعی که داشتند او را می بردند زیر گوش میوه فروش گفت : \" آن روزنامه را من پیش تو گذاشتم، برو پشتش را بخوان .\r\n سپس لبخند زنان و با قیافه کاملاً راضی سوار ماشین پلیس شد. میوه فروش با شتاب آن روزنامه را بیرون آورد و در صفحه پشتش، چند سطر دست نویس را دید که نوشته بود : من دیگر از فرار خسته شدم از پرتقالت متشکرم . هنگامی که داشتم برای پایان دادن به زندگیم تصمیم میگرفتم، نیکدلی تو بود که بر من تاثیر گذاشت . بگذار جایزه پیدا کردن من ،جبران زحمات تو باشد.\r\n"},{"id":1691,"category_id":10,"category_code":"s10","source_id":253,"title":"نیوتن ","content":"روزی همه دانشمندان مردند و وارد بهشت شدند آنها تصمیم گرفتند تا قایم باشک بازی کنند.\r\nانیشتین اولین نفری بود که باید چشم می گذاشت. او باید تا 100 میشمرد و سپس شروع به جستجو میکرد.\r\nهمه پنهان شدند الا نیوتون ...\r\n\r\nنیوتون فقط یک مربع به طول یک متر کشید و درون آن ایستاد، دقیقا در مقابل انیشتین.\r\n\r\nانیشتین شمرد 97, 98, 99..100…\r\nاو چشماشو باز کرد ودید که نیوتون در مقابل چشماش ایستاده.\r\nانیشتین فریاد زد نیوتون بیرون( سک سک)\r\nنیوتون بیرون( سک سک)\r\nنیوتون با خونسردی تکذیب کرد و گفت من بیرون نیستم. او ادعا کرد که اصلا من نیوتون نیستم !!!\r\n\r\n... تمام دانشمندان از مخفیگاهشون بیرون اومدن تا ببینن اون چطور میخواد ثابت کنه که نیوتون نیست ...\r\n. . . . . . . . . . نیوتون ادامه داد که من در یک مربع به مساحت یک متر مربع ایستاده ام ...\r\nکه من رو،نیوتون بر متر مربع میکنه .........\r\nو از آنجایی که نیوتون بر متر مربع برابر \"یک پاسکال\" می باشد\r\nبنابراین من \"پاسکالم\" پس پاسکال باید بیرون بره (پاسکال سک سک) !!!\r\n"},{"id":1692,"category_id":10,"category_code":"s10","source_id":254,"title":"قدر همین شاه را باید دانست ","content":"پادشاهی از وزیر خود خشمگین شد به همین دلیل او را به زندان انداخت.مدتی بعد وضع اقتصاد کشور رو به وخامت گذاشت. بنابراین مردم از پادشاه خود ناراضی شدند و پادشاه هرکاری برای جلب رضایت آنها نمود،موفق نمی شد.لذا دستور داد وزیر را از زندان بیاورند.هنگامی که وزیر در محضر او حاضر شد گفت:مدتی است که مردم از من روی گردان شده اند،اگر توانستی رضایت آنها را جلب کنی من نیز از گناه تو می گذرم.وزیر گفت:...\r\nمن دستور شما را اجرا خواهم کرد،فقط از شما می خواهم تعدادی سرباز به من بدهید.شاه گفت:نبینم که از راه اعمال خشونت بر مردم وارد شوی.سرباز برای چه می خواهی؟ وزیر گفت:من هرگز هدف سرکوب کردن ندارم.شاه با شنیدن این حرف تعدادی سرباز به وزیرش داد.شب هنگام وزیر به  هر کدام از سربازان لباس مبدل دزدان را پوشاند و به  هر کدام دستور داد که به تمام خانه ها بروند  و  از هر خانه چیزی  بدزدند به طوری که آن چیز نه  زیاد بی ارزش باشد و نه زیاد با ارزش تا به مردم ضرر چندانی وارد نشود  و  هم چنین کاغذی به آنها داد و گفت در هر  مکانی که  دزدی می کنید این کاغذ را قرار دهید.روی کاغذ چنین نوشته شده بود:هدف  ما  تصاحب قصر امپراطوری و حکومت بر مردم است.سربازان نیز مطابق دستور  وزیر عمل کردند.مردم نیز با خواندن آن کاغذ  دور هم جمع شدند.\r\nنفر اول گفت: درست است که  در  زمان حکومت پادشاه وقت با وخامت اقتصادی روبه رو شدیم،اما هرگز پادشاه به دزدی اموال ما اقدام نمی کند..این دزدان اکنون که قدرتی ندارند توانسته اند  اموال ما را بدزدند،وای به روزی که به حاکمیت دست یابند.نفر دوم نیز گفت:درست است،قدر این شاه را باید دانست و از او حمایت نمود تا از شر  این دزدان مصون بمانیم.و همه حرف  های یکدیگر را تایید کردند و  بنابراین تصمیم گرفتند از شاه حمایت کنند.\r\n"},{"id":1693,"category_id":10,"category_code":"s10","source_id":255,"title":"داستان سنگ و سنگ تراش ","content":"روزی، سنگ تراشی که از کار خود ناراضی بود و احساس حقارت می کرد، از نزدیکی خانه بازرگانی رد می شد. در باز بود و او خانه مجلل، باغ و نوکران بازرگان را دید و به حال خود غبطه خورد با خود گفت: ....\r\nاین بازرگان چقدر قدرتمند است! و آرزو کرد که او هم مانند بازرگان باشد. در یک لحظه، به فرمان خدا او تبدیل به بازرگانی با جاه و جلال شد! تا مدت ها فکر می کرد که از همه قدرتمندتر است. تا این که یک روز حاکم شهر از آنجا عبور کرد، او دید که همه مردم به حاکم احترام می گذارند حتی بازرگانان.\r\n\r\nمرد با خودش فکر کرد: کاش من هم یک حاکم بودم، آن وقت از همه قوی تر می شدم! در همان لحظه، او تبدیل به حاکم مقتدر شهر شد. در حالی که روی تخت روانی نشسته بود، مردم همه به او تعظیم می کردند. احساس کرد که نور خورشید او را می آزارد و با خودش فکر کرد که خورشید چقدر قدرتمند است.\r\n\r\nاو آرزو کرد که خورشید باشد و تبدیل به خورشید شد و با تمام نیرو سعی کرد که به زمین بتابد و آن را گرم کند. پس از مدتی ابری بزرگ و سیاه آمد و جلوی تابش او را گرفت. پس با خود اندیشید که نیروی ابر از خورشید بیشتر است و آرزو کرد که تبدیل به ابری بزرگ شود و آن چنان شد. کمی نگذشته بود که بادی آمد و او را به این طرف و آن طرف هل داد. این بار آرزو کرد که باد شود و تبدیل به باد شد. \r\nولی وقتی به نزدیکی صخره سنگی رسید، دیگر قدرت تکان دادن صخره را نداشت. با خود گفت که قوی ترین چیز در دنیا، صخره سنگی است و تبدیل به سنگی بزرگ و عظیم شد. همان طور که با غرور ایستاده بود، ناگهان صدایی شنید و احساس کرد که دارد خـُرد می شود. نگاهی به پایین انداخت و سنگ تراشی را دید که با چکش و قلم به جان او افتاده است!\r\n"},{"id":1694,"category_id":10,"category_code":"s10","source_id":256,"title":"شکست یک شخص نیست! ","content":"یکی از مریدان شیوانا مرد تاجری بود که ورشکست شده بود. روزی برای تصمیم گیری در مورد یک موضوع تجاری نیاز به مشاور بود. شیوانا از شاگردان خواست تا آن مرد تاجر را نزد او آورند. یکی از شاگردان به اعتراض گفت: اما او یک تاجر ورشکسته است و نمی توان به مشورتش اعتماد کرد. شیوانا پاسخ داد:.....\r\nشکست یک اتفاق است. یک شخص نیست! کسی که شکست خورده در مقایسه با کسی که چنین تجربه ای نداشته است ، هزاران قدم جلوتراست. او روی دیگر موفقیت را به وضوح لمس کرده است و تارهای متصل به شکست را می شناسد. او بهتر از هر کس دیگری می تواند سیاهچاله های منجر به شکست را به ما نشان دهد.وقتی کسی موفق می شود بدانید که چیزی یاد نگرفته است! اما وقتی کسی شکست می خورد آگاه باشیدکه او هزاران چیز یاد گرفته است که اگر شجاعت خود را از دست نداده باشد می تواند به دیگران منتقل کند. وقتی کسی شکست می خورد هرگز نگوئید او تا ابد شکست خورده است! بلکه بگوئید او هنوز موفق نشده است.\r\n"},{"id":1695,"category_id":10,"category_code":"s10","source_id":257,"title":"همیشه یک راه حل وجود دارد ","content":"روزگاری یک کشاورز در روستایی زندگی می کرد که باید پول زیادی را که از یک پیرمرد قرض گرفته بود، پس می داد.\r\n\r\nکشاورز دختر زیبایی داشت که خیلی ها آرزوی ازدواج با او را داشتند. وقتی پیرمرد طمعکار متوجه شد کشاورز نمی تواند پول او را پس بدهد، پیشهاد یک معامله کرد و گفت اگر با دختر کشاورز ازدواج کند بدهی او را می بخشد، و دخترش از شنیدن این حرف به وحشت افتاد و پیرمرد کلاه بردار برای اینکه حسن نیت خود را نشان بدهد گفت: ...\r\n اصلا یک کاری می کنیم، من یک سنگریزه سفید و یک سنگریزه سیاه در کیسه ای خالی می اندازم، دختر تو باید با چشمان بسته یکی از این دو را بیرون بیاورد. اگر سنگریزه سیاه را بیرون آورد باید همسر من بشود و بدهی بخشیده می شود و اگر سنگریزه سفید را بیرون آورد لازم نیست که با من ازدواج کند و بدهی نیز بخشیده می شود، اما اگر او حاضر به انجام این کار نشود باید پدر به زندان برود.\r\n\r\nاین گفت و گو در جلوی خانه کشاورز انجام شد و زمین آنجا پر از سنگریزه بود. در همین حین پیرمرد خم شد و دو سنگریزه برداشت. دختر که چشمان تیزبینی داشت متوجه شد او دو سنگریزه سیاه از زمین برداشت و داخل کیسه انداخت. ولی چیزی نگفت!\r\n\r\nسپس پیرمرد از دخترک خواست که یکی از آنها را از کیسه بیرون بیاورد.\r\nدخترک دست خود را به داخل کیسه برد و یکی از آن دو سنگریزه را برداشت و به سرعت و با ناشی بازی، بدون اینکه سنگریزه دیده بشود، وانمود کرد که از دستش لغزیده و به زمین افتاده. پیدا کردن آن سنگریزه در بین انبوه سنگریزه های دیگر غیر ممکن بود.\r\nدر همین لحظه دخترک گفت: آه چقدر من دست و پا چلفتی هستم! اما مهم نیست. اگر سنگریزه ای را که داخل کیسه است دربیاوریم معلوم می شود سنگریزه ای که از دست من افتاد چه رنگی بوده است....\r\nو چون سنگریزه ای که در کیسه بود سیاه بود، پس باید طبق قرار، آن سنگریزه سفید باشد. آن پیرمرد هم نتوانست به حیله گری خود اعتراف کند و شرطی را که گذاشته بود به اجبار پذیرفت و دختر نیز تظاهر کرد که از این نتیجه حیرت کرده است.\r\n"},{"id":1696,"category_id":10,"category_code":"s10","source_id":258,"title":"حکایت خدا و گنجشک ","content":"روزها گذشت و گنجشک با خدا هیچ نگفت.\r\nفرشتگان سراغش را از خدا گرفتند و خدا هر بار به فرشتگان این گونه می گفت: \" می آید، من تنها گوشی هستم که غصه هایش را می شنود و یگانه قلبی ام که دردهایش را در خود نگه می دارد و سر انجام گنجشک روی شاخه ای از درخت دنیا نشست.\r\n\" فرشتگان چشم به لب هایش دوختند، گنجشک هیچ نگفت و خدا لب به سخن گشود:\r\n\" با من بگو از آنچه سنگینی سینه توست.\r\n\" گنجشک گفت:\r\n\" لانه کوچکی داشتم، آرامگاه خستگی هایم بود و سرپناه بی کسی ام. تو همان را هم از من گرفتی. این توفان بی موقع چه بود؟ چه می خواستی از لانه محقرم کجای دنیا را گرفته بود و سنگینی بغضی راه بر کلامش بست.\r\nسکوتی در عرش طنین انداز شد. فرشتگان همه سر به زیر انداختند. خدا گفت:\r\n\" ماری در راه لانه ات بود. خواب بودی. باد را گفتم تا لانه ات را واژگون کند. آنگاه تو از کمین مار پر گشودی. \" گنجشک خیره در خدایی خدا مانده بود. \r\nخدا گفت: \" و چه بسیار بلاها که به واسطه محبتم از تو دور کردم و تو ندانسته به دشمنی ام بر خاستی. \" اشک در دیدگان گنجشک نشسته بود. ناگاه چیزی در درونش فرو ریخت. های های گریه هایش ملکوت خدا را پر کرد.\r\n"},{"id":1697,"category_id":10,"category_code":"s10","source_id":259,"title":"نه به جنیفر لوپز! ","content":"هیزم شکنی مشغول قطع کردن یه شاخه درخت بالای رودخونه بود، تبرش افتاد تو رودخونه. \r\nوقتی در حال گریه کردن بود، یه فرشته اومد و ازش پرسید: چرا گریه می کنی؟ \r\nهیزم شکن گفت: تبرم توی رودخونه افتاده. \r\nفرشته رفت و با یه تبر طلایی برگشت و از هیزم شکن پرسید:\"آیا این تبر توست؟\" \r\nهیزم شکن جواب داد: \"نه\" \r\nفرشته دوباره...\r\nبه زیر آب رفت و این بار با یه تبر نقره ای برگشت و پرسید: آیا این تبر توست؟ \r\nدوباره، هیزم شکن جواب داد: \"نه\". \r\nفرشته باز هم به زیر آب رفت و این بار با یه تبر آهنی برگشت و پرسید: آیا این تبر توست؟\r\nجواب داد: آره. \r\nفرشته از صداقت مرد خوشحال شد و هر سه تبر را به اوداد و هیزم شکن خوشحال روانه خونه شد. \r\nروزی دیگر هیزم شکن وقتی داشت با زنش کنار رودخونه راه می رفت زنش افتاد توی همان رودخانه. هیزم شکن داشت گریه می کرد که فرشته باز هم اومد و پرسید که چرا گریه می کنی؟ اوه فرشته، زنم افتاده توی آب. \r\nفرشته رفت زیر آب و با جنیفر لوپز برگشت و پرسید: زنت اینه؟ هیزم شکن فریاد زد: آره!\r\nفرشته عصبانی شد. \" تو تقلب کردی، این نامردیه \" \r\nهیزم شکن جواب داد : اوه، فرشته من منو ببخش. سوء تفاهم شده. می دونی، اگه به جنیفر لوپز \"نه\" می گفتم تو می رفتی و با کاترین زتاجونز می اومدی.و باز هم اگه به کاترین زتاجونز \"نه\" میگفتم، تو می رفتی و با زن خودم می اومدی و من هم می گفتم آره. اونوقت تو هر سه تا رو به من می دادی. اما فرشته، من یه آدم فقیرم و توانایی نگهداری سه تا زن رو ندارم، و به همین دلیل بود که این بار گفتم آره. \r\n"},{"id":1698,"category_id":10,"category_code":"s10","source_id":260,"title":"شگرد پسرک در مقابل نادر شاه ","content":"زمانی که نادر شاه افشار عزم تسخیر هندوستان داشته در راه کودکی را دید که به مکتب می‌رفت. از او پرسید: پسر جان چه می‌خوانی؟\r\nقرآن.\r\n- از کجای قرآن؟\r\n- انا فتحنا….\r\nنادر از پاسخ او بسیار خرسند شد و از شنیدن آیه فتح فال پیروزی زد.\r\nسپس یک سکه زر به پسر داد اما پسر از گرفتن آن اباکرد.\r\nنادر گفت: چر ا نمی گیری؟\r\nگفت: مادرم مرا می‌زند می‌گوید تو این پول را دزدیده ای.\r\nنادر گفت: به او بگو نادر داده است.\r\nپسر گفت: مادرم باور نمی‌کند.\r\nمی‌گوید: نادر مردی سخاوتمند است. او اگر به تو پول می‌داد یک سکه نمی‌داد. زیاد می‌داد.\r\nحرف او بر دل نادر نشست. یک مشت پول زر در دامن او ریخت.\r\nاز قضا چنانچه مشهور تاریخ است در آن سفر بر حریف خویش محمد شاه گورکانی پیروز شد.\r\n"},{"id":1699,"category_id":10,"category_code":"s10","source_id":261,"title":"مردم چه می گویند؟؟ ","content":"می خواستم به دنیا بیایم، در زایشگاه عمومی، پدر بزرگم به مادرم گفت: فقط بیمارستان خصوصی. مادرم گفت: چرا؟...گفت: مردم چه می گویند؟!...\r\nمی خواستم به مدرسه بروم، مدرسه ی سر کوچه ی مان. مادرم گفت: فقط مدرسه ی غیر انتفاعی! پدرم گفت: چرا؟...مادرم گفت: مردم چه می گویند؟!...\r\nبه رشته ی انسانی علاقه داشتم. پدرم گفت: ...\r\nفقط ریاضی! گفتم: چرا؟...گفت: مردم چه می گویند؟!...\r\nبا دختری روستایی می خواستم ازدواج کنم. خواهرم گفت: مگر من بمیرم. گفتم: چرا؟...گفت: مردم چه می گویند؟!...\r\nمی خواستم پول مراسم عروسی را سرمایه ی زندگی ام کنم. پدر و مادرم گفتند: مگر از روی نعش ما رد شوی. گفتم: چرا؟...گفتند: مردم چه می گویند؟!...\r\n\r\nمی خواستم به اندازه ی جیبم خانه ای در پایین شهر اجاره کنم. مادرم گفت: وای بر من. گفتم: چرا؟...گفت: مردم چه می گویند؟!...\r\nاولین مهمانی بعد از عروسیمان بود. می خواستم ساده باشد و صمیمی. همسرم گفت: شکست، به همین زودی؟!...گفتم: چرا؟... گفت:مردم چه می گویند؟!...\r\nمی خواستم یک ماشین مدل پایین بخرم، در حد وسعم، تا عصای دستم باشد. زنم گفت: خدا مرگم دهد. گفتم: چرا؟... گفت: مردم چه می گویند؟!...\r\nبچه ام می خواست به دنیا بیاید، در زایشگاه عمومی. پدرم گفت: فقط بیمارستان خصوصی. گفتم: چرا؟...گفت: مردم چه می گویند؟!...\r\nبچه ام می خواست به مدرسه برود، رشته ی تحصیلی اش را برگزیند، ازدواج کند... می خواستم بمیرم. بر سر قبرم بحث شد. پسرم گفت: پایین قبرستان. زنم جیغ کشید. دخترم گفت: چه شده؟...گفت: مردم چه می گویند؟!...\r\n\r\nمُردم. برادرم برای مراسم ترحیمم مسجد ساده ای در نظر گرفت. خواهرم اشک ریخت و گفت: مردم چه می گویند؟!...\r\nاز طرف قبرستان سنگ قبر ساده ای بر سر مزارم گذاشتند. اما برادرم گفت: مردم چه می گویند؟!...\r\nخودش سنگ قبری برایم سفارش داد که عکسم را رویش حک کردند. حالا من در اینجا در حفره ای تنگ خانه کرده ام و تمام سرمایه ام برای ادامه ی زندگی جمله ای بیش نیست: مردم چه می گویند؟!... مردمی که عمری نگران حرفهایشان بودم، لحظه ای نگران من نیستند.\r\n"},{"id":1700,"category_id":10,"category_code":"s10","source_id":262,"title":"فرار از زندگی ","content":"روزی شاگردی به استاد خویش گفت:استاد می خواهم یکی از مهمترین خصایص انسان ها را به من بیاموزی؟استاد گفت: واقعا می خواهی آن را فرا گیری؟شاگرد گفت:بله با کمال میل.استاد گفت:پس آماده شو با هم به جایی برویم.شاگرد قبول کرد.استاد شاگرد جوانش را به پارکی که در آّن کودکان مشغول بازی بودند،برد.استاد گفت:....\r\nخوب به مکالمات بین کودکان گوش کن.مکالمات بین کودکان به این صورت بود:\r\n-الان نوبت من است که فرار کنم و تو باید دنبال من بدوی.\r\n-نخیر الان نوبت توست که دنبالم بدوی.\r\n-اصلا چرا من هیچوقت نباید فرار کنم؟\r\nو حرف هایی از این قبیل...\r\n\r\nاستاد ادامه داد:همانطور که شنیدی تمام این کودکان طالب آن بودند که از دست دیگری فرار کنند.انسان نیز این گونه است.او هیچگاه حاضر نیست با شرایط موجود رو به رو شود و دائم در تلاش است از حقایق و واقعیات زندگی خود فرار کند و هرگز کاری برای بهبود زندگی خود انجام نمی دهد.تو از من خواستی یکی از مهم ترین ویزگی های انسان را برای تو بگویم و من آن را در چند کلام خلاصه میکنم:تلاش برای فرار از زندگی.\r\n"},{"id":1701,"category_id":10,"category_code":"s10","source_id":263,"title":"حتمی دلیلی دارد ... ","content":"مردی تاجر در حیاط  قصرش انواع مختلف درختان و گیاهان و گلها را کاشته و باغ بسیار زیبایی را به وجود آورده بود. هر روز بزرگترین سرگرمی و تفریح او گردش در باغ و لذت بردن از گل و گیاهان آن بود.\r\nتا این که یک روز به سفر رفت. در بازگشت، در اولین فرصت به دیدن باغش رفت.\r\nاما با دیدن آنجا، سر جایش خشکش زد...\r\nتمام درختان و گیاهان در حال خشک شدن بودند ، رو به درخت صنوبر که پیش از این بسیار سر سبز بود، کرد و از او پرسید که چه اتفاقی افتاده است؟\r\n\r\nدرخت به او پاسخ داد: من به درخت سیب نگاه می کردم و باخودم گفتم که من هرگز نمی توانم مثل او چنین میوه هایی زیبایی بار بیاورم و با این فکر چنان احساس نارحتی کردم که شروع به خشک شدن کردم...\r\nمرد بازرگان به نزدیک درخت سیب رفت، اما او نیز خشک شده بود...!\r\n\r\nعلت را پرسید و درخت سیب پاسخ داد: با نگاه به گل سرخ و احساس بوی خوش آن، به خودم گفتم که من هرگز چنین بوی خوشی از خود متصاعد نخواهم کرد و با این فکر شروع به خشک شدن کردم.\r\nاز آنجایی که بوته ی یک گل سرخ نیز خشک شده بود علت آن پرسیده شد، او چنین پاسخ داد: من حسرت درخت افرا را خوردم، چرا که من در پاییز نمی توانم گل بدهم. پس از خودم نا امید شدم و آهی بلند کشیدم. همین که این فکر به ذهنم خطور کرد، شروع به خشک شدن کردم.\r\n\r\nمرد در ادامه ی گردش خود در باغ متوجه گل بسیار زیبایی شد که در گوشه ای از باغ روییده بود.\r\nعلت شادابی اش را جویا شد. گل چنین پاسخ داد: ابتدا من هم شروع به خشک شدن کردم، چرا که هرگز عظمت درخت صنوبر را که در تمام طول سال سر سبزی خود را حفظ می کرد نداشتم، و از لطافت و خوش بویی گل سرخ نیز برخوردار نبودم، با خودم گفتم: اگر مرد تاجر که این قدر ثروتمند، قدرتمند و عاقل است و این باغ به این زیبایی را پرورش داده است می خواست چیزی دیگری جای من پرورش دهد، حتماً این کار را می کرد. بنابراین اگر او مرا پرورش داده است، حتماً می خواسته است که من وجود داشته باشم. پس از آن لحظه به بعد تصمیم گرفتم تا آنجا که می توانم زیباترین موجود باشم... \r\n"},{"id":1702,"category_id":10,"category_code":"s10","source_id":264,"title":"مرد خوشبخت ","content":"پادشاهی پس از اینکه بیمار شد گفت: \"نصف قلمرو پادشاهی‌ام را به کسی می‌دهم که بتواند مرا معالجه کند\".\r\nتمام آدم‌های دانا دور هم جمع شدند تا ببیند چطور می شود شاه را معالجه کرد، اما هیچ یک ندانست.\r\nتنها یکی از مردان دانا گفت: \"فکر کنم می‌توانم شاه را معالجه کنم. اگر یک آدم خوشبخت را پیدا کنید، پیراهنش را بردارید و تن شاه کنید، شاه معالجه می شود\".\r\nشاه پیک‌هایش را برای پیدا کردن یک آدم خوشبخت فرستاد....\r\nآنها در سرتاسر مملکت سفر کردند ولی نتوانستند آدم خوشبختی پیدا کنند. حتی یک نفر پیدا نشد که کاملا راضی باشد.\r\nآن که ثروت داشت، بیمار بود. آن که سالم بود در فقر دست و پا میزد، یا اگر سالم و ثروتمند بود زن و زندگی بدی داشت. یا اگر فرزندی داشت، فرزندانش بد بودند. خلاصه هر آدمی چیزی داشت که از آن گله و شکایت کند.\r\nآخرهای یک شب، پسر شاه از کنار کلبه‌ای محقر و فقیرانه رد میشد که شنید یک نفر دارد چیزهایی می‌گوید. \"شکر خدا که کارم را تمام کرده‌ام. سیر و پر غذا خورده‌ام و می‌توانم دراز بکشم و بخوابم! چه چیز دیگری می‌توانم بخواهم؟\"\r\nپسر شاه خوشحال شد و دستور داد که پیراهن مرد را بگیرند و پیش شاه بیاورند و به مرد هم هر چقدر بخواهد بدهند.\r\nپیک‌ها برای بیرون آوردن پیراهن مرد توی کلبه رفتند، اما مرد خوشبخت آن قدر فقیر بود که پیراهن نداشت!!!\r\n"},{"id":1703,"category_id":10,"category_code":"s10","source_id":265,"title":"قضاوت سریع","content":"دو کبوتر بودند در گوشه مزرعه ای با خوشحالی زندگی می کردند . در فصل بهار ، وقتی که باران زیاد می بارید ، کبوتر ماده به همسرش گفت : این لانه خیلی مرطوب است . اینجا دیگر جای خوبی برای زندگی کردن نیست . کبوتر جواب داد : \" به زودی تابستان از راه می رسد و هوا گرمتر خواهد شد . علاوه براین ، ساختن این چنین لانه ای که هم بزرگ باشد و هم انبار داشته باشد ، خیلی مشکل است.\"  \r\nبنابراین دو كبوتر در همان لانه قبلی ماندند تا این که تابستان فرا رسید و لانه آنها خشک تر شد و زندگی خوشی را در مزرعه سپری کردند . آنها هر چقدر برنج و گندم می خواستند می خوردند و مقداری از آن را نیز برای زمستان در انبار ذخیره می کردند . یک روز ، متوجه شدند که انبارشان از گندم و برنج پر شده است . با خوشحالی به یكدیگر گفتند : \" حالا یک انبار پر از غذا داریم . بنابراین ، این زمستان هم زنده خواهیم ماند.\" \r\nآنها در انبار را بستند و دیگر سری به آن نزدند تا این که تابستان به پایان رسید و دیگر در مزرعه دانه به ندرت پیدا می شد . پرنده ماده که نمی توانست تا دور دست پرواز کند ، در خانه استراحت می کرد و کبوتر نر برای او غذا تهیه می کرد . در فصل پائیز وقتی که بارندگی آغاز شد و کبوترها نمی توانستند برای خوردن غذا به مزرعه بروند ، یاد انبار آذوقه شان افتادند . دانه های انبار بر اثر گرمای زیاد تابستان ، حجمشان کمتر از حجم اولیه شان شده بود و کمتر به نظر می رسید . کبوتر نر با عصبانیت به پیش جفت خود بازگشت و فریاد زد : \" عجب بی فکر و شکمو هستی ! ما این دانه ها را برای زمستان ذخیره کرده بودیم ، ولی تو نصف انبار را ظرف همان چند روز که در خانه ماندی ، خورده ای ؟ مگر زمستان و سرما و یخبندان را فراموش کردی ؟  کبوتر ماده با عصبانیت پاسخ داد: : \r\n\" من دانه ها را نخوردم و نمی دانم که چرا نصف انبار خالی شده ؟ \"\r\nکبوتر ماده که از دیدن مقدار کم دانه های انبار ، متعجب شده بود ، با اصرار گفت : \" قسم می خورم که از همان روزی که این دانه ها را ذخیره کردیم ، به آنها نگاه نکردم . آخر چطور می توانستم آنها را بخورم ؟ من در حیرتم چرا این قدر دانه های انبار کم شده است . این قدر عصبانی نباش و مرا سرزنش نکن . بهتر است که صبور باشی و دانه های باقی مانده را بخوریم . شاید کف انبار فرو رفته باشد یا شاید موش ها انبار را پیدا کرده اند و مقداری از آنها را خورده اند . شاید هم شخص دیگری دانه های ما را دزدیده است . در هرصورت تو نباید عجولانه قضاوت کنی . اگر آرام باشی و صبر کنی ، حقیقت روشن می شود. \r\nکبوتر نر با عصبانیت گفت : \" کافی است ! من به حرف های تو گوش نمی دهم و لازم نیست مرا نصیحت کنی . من مطمئن هستم که هیچکس غیر از تو به اینجا نیامده است . اگر هم کسی آمده ، تو خوب می دانی که آن چه کسی بوده است. \r\nاگر تو دانه ها را نخوردی باید راستش را بگویی . من نمی توانم منتظر بمانم و این اجازه را به تو نمی دهم که هر کاری دلت می خواهد بکنی . خلاصه ، اگر چیزی می دانی و قصد داری که بعد بگویی بهتر است همین الان بگویی . کبوتر ماده که چیزی درباره کم شدن دانه ها نمی دانست ، شروع به گریه و زاری کرد و گفت : \" من به دانه ها دست نزدم و نمی دانم که چه بلایی بر سر آنها آمده است \" و به کبوتر نر گفت که صبر کن تا علت کم شدن دانه ها معلوم شود . اما کبوتر نر متقاعد نشد ، بلکه ناراحت تر شد و جفت خود را از خانه بیرون انداخت. \r\nکبوتر ماده گفت : \" تو نباید به این سرعت درباره من قضاوت کنی و به من تهمت ناروا بزنی . به زودی از کرده خود پشیمان خواهی شد . ولی باید بگویم که آن وقت خیلی دیر است. \"و بلافاصله به طرف بیابان پرواز کرد و پس از مدتی گرفتار دام صیاد شد.  \r\n \r\nکبوتر نر ، تنها در لانه به زندگی خود ادامه داد . او از این که اجازه نداد جفتش او را فریب دهد ، خیلی خوشحال بود . چند روز بعد هوا دوباره بارانی و مرطوب شد . دانه های انبار ، دوباره چاق تر و پرحجم تر شدند و انبار دوباره به اندازه اولش پر شد . کبوتر عجول با دیدن این موضوع ، فهمید که قضاوتش درباره جفتش اشتباه بوده و از کرده خود خیلی پشیمان شد ، ولی دیگر برای توبه کردن خیلی دیر شده بود و او به خاطر قضاوت نادرستش تا آخر عمر با ناراحتی زندگی کرد.\r\n"},{"id":1704,"category_id":10,"category_code":"s10","source_id":266,"title":"مرد هیزم شکن","content":"مردي هر روز صبح به صحرا مي رفت ، هيزم جمع مي کرد و براي فروش به شهر مي برد . زندگي ساده اش از همين راه مي گذشت . تنها بود و همين روزي اندک بي نيازش مي کرد . آن روز به هيزم هايي که جمع کرده بود ، نگاه کرد . براي آن روز کافي بود . حالا بايد به شهر بر مي گشت . هيزمها را روي دوش گذشت و به راه افتاد . از دور سايه اي ديد . در ابتدا سايه مبهمي بود که به سرعت تکان مي خورد . دقت کرد شايد بفهمد سايه چيست . سايه هر لحظه نزديک و نزديکتر مي شد و شکل مبهم خود را از دست مي داد . اين بار بيشتر دقت کرد . واي ! شتري رم کرده بود که جنون آسا به سمت او مي آمد و هر لحظه امکان داشت او را زير پاهاي خود له کند . مرد به وحشت افتاد. نمي دانست چه کار کند و کدام طرف برود . شتر نزديکتر مي شد . پا به فرار گذاشت . هيزمهاي روي دوشش سنگين بودند و او مجبور شد آنها را به زمين اندازد ، وگرنه با آن سرعتي که شتر مي دويد حتما ً به او مي رسيد . حالا سبکتر شده بود . او مي دويد و شتر هم دنبالش / چاهي را ديد که هر روز از کنارش مي گذشت . فکري به ذهنش رسيد . بايد داخل چاه مي رفت . بله ! تنها راه نجاتش همين بود . شايد اين گونه از شر آن شتر راحت مي شد . بعد مي توانست از چاه بيرون بيايد و هيزمهايش را دوباره بردارد و به شهر برود . به چاه رسيد . دو شاخه اي را که از دهانه چاه روييده بود ، گرفت و آويزان شد . بين زمين و هوا معلق بود و دستهايش شاخه ها را محکم چسبيده بود . اما آن شاخه ها تنها وسيله پيوند بين مرگ و زندگي او بودند .\r\nيکي دو دقيقه گذشت . صداي پاي شتر را مي شنيد که هنوز داشت در آن اطراف ، پرسه مي زد. ديگر بيشتر از اين نمي توانست آويزان بماند. بايد پاهايش را به جايي محکم نگه مي داشت . به اين طرف و آن طرف تکان خورد ، شايد بتواند ديواره چاه را پيدا کند . يک دفعه پاهايش به جايي محکم شد . همان جا پاهايش را نگه داشت . نفسي به آرامي کشيد و با خود گفت : ” خيالم راحت شد. چند دقيقه ديگر مي ايستم و بعد بيرون مي روم . ديگر صدايي نمي آيد . حتما ً شتر رفته است . کمي ديگر هم صبر کنم بهتر است . ”\r\nبه پايين نگاه کرد . مي خواست بفهمد پاهايش را کجا گذاشته است. چاه تاريک بود و چيزي نمي ديد . کم کم چشم هايش به تاريکي عادت کرد. پاهايش را ديد که روي …\r\nواي ! خدايا باورش نمي شد . از سوراخ هاي ديوار چاه ، سر چهار مار بيرون آمده بود و او پاهايش را درست روي آنها گذاشته بود . کافي بود پايش را براي لحظه اي از سر مارها بردارد تا آنها او را مثل يک تکه چوب ، خشک و سياه کنند. از ترس و وحشت نزديک بود تعادلش را از دست بدهد. دست هايش مي لرزيد. نگاهش به ته چاه افتاد . نمي دانست چاه چقدر عمق دارد . ناگهان ترسش دو چندان شد و بي اختيار فرياد کشيد : ” نه ! خدايا به دادم برس .” ته چاه دو چشم درشت برق مي زد . دو چشم درشت اژدهايي که از پائين او را تماشا مي کرد و منتظر بود تا او پرت شود و حسابش را برسد. حالا بايد چه کار مي کرد ؟ عقلش به هيچ جا نمي رسيد . خدا را شکر که شاخه ها سفت و محکم بودند . نگاهي به بالا انداخت . اي داد و بيداد ! دو موش صحرايي سياه و درشت سر چاه نشسته بودند و شاخه ها را مي جويدند . اوضاع و احوال لحظه به لحظه بدتر مي شد . سعي کرد موشها را بترساند و فراري بدهد . اما فايده اي نداشت . آنها همچنان مشغول جويدن شاخه ها بودند. ديگر حسابي نااميد شده بود. مرگ را در يک قدمي خود احساس مي کرد . به خودش گفت : ” کارم تمام است . ديگر راه نجاتي نمانده ، نه بالا و نه پائين . از زمين و آسمان بلا بر سرم مي بارد. ”\r\nدستهايش از شدت خستگي مي لرزيد. بيشتر از اين نمي توانست از شاخه ها آويزان بماند. بايد راه چاره اي پيدا مي کرد. هر لحظه امکان داشت دست هايش شل شوند و يا موشها شاخه ها را ببرند و او به ته چاه بيفتد و طعمه اژدها شود . پاهايش همچنان روي سر مارها بود. نمي توانست کوچکترين تکاني بخورد.\r\nدوباره به شاخه ها نگاه کرد . موشها سرگرم جويدن بودند. فکر کرد چيزي بردارد و به طرف آنها پرتاب کند. با اين کار حداقل خيالش از شاخه ها راحت مي شد. آن وقت مي توانست به مارها فکر کند. دستش را دراز کرد و به اطراف شاخه ها دست کشيد . دستش به چيزي خورد . نگاه کرد . شبيه کندوي عسل بود . اما چرا تا به حال متوجه آن نشده بود ؟ از شدت ترس و فکر و خيال به آن توجهي نکرده بود . گرسنه اش بود و عسل مي توانست گرسنگي او را فرو بنشاند و آن لحظات تلخ را شيرين کند . انگشت خود را در عسل فرو برد و در دهانش گذاشت . چه شيرين بود ! يک انگشت ديگر برداشت و در دهان گذاشت . بعد يک انگشت ديگر و بعد … ديگر به کلي يادش رفت که کجاست و در چه وضعيتي قرار دارد . به تنها چيزي که فکر مي کرد اين بود که عسل ها را انگشت بزند و تا آخر بخورد. نه به فکر موشها و مارها بود و نه به اژدهايي که منتظر بلعيدنش بود ، مي انديشيد . شيريني عسل همه چيز را از يادش برده بود .\r\nناگهان تکاني خورد و کمي پائين رفت . به خودش آمد و کندو و عسل شيرين از يادش رفت  به موشها نگاه کرد . داشتند آخرين بندهاي نازک شاخه ها را پاره مي کردند . ديگر فرصت هيچ کاري نبود . به ياد غفلت خودش افتاد که در اوج گرفتاري و بدبختي ، به خوردن مشغول شده بود. شايد اگر کمي زودتر به فکر مي افتاد ، مي توانست نجات پيدا کند و شايد هم نه . اما به هرحال غفلت او همه چيز را خراب کرد . شاخه ها کاملا ً پاره شدند . فريادي از ترس کشيد و خودش را بين زمين و آسمان ديد که به سرعت به ته چاه مي رفت.  صداي فريادش در دل چاه پيچيد . انگار کسي به او مي گفت : ” اين است سزاي کسي که در هنگام خطر ، بي خيال و بي تفاوت باشد و دست روي دست بگذارد . ” چند لحظه بعد ، صداي فرياد او و انعکاسش محو شد و سکوتي عميق چاه را فرا گرفت . مثل اينکه هيچ اتفاقي نيفتاده بود و هرگز کسي از شاخه ها آويزان نشده بود .\r\nمارها که از شر پاهاي او خلاص شده بودند ، دوباره به سوراخهاي خود خزيدند . آن بالا و بيرون از چاه هيچ چيزي نبود . نه موشي و نه شتري . فقط هيزمهاي مرد هيزم شکن بودند که باد آنها را به اين طرف و آن طرف مي برد .\r\n"},{"id":1705,"category_id":10,"category_code":"s10","source_id":267,"title":"شتر در دام حیله زاغ وگرگ و شغال","content":" آورده اند كه در بيشه اي سبز و خرم، كلاغ و گرگ و شغالي در خدمت شيري مهربان، اما ساده دل زندگي مي كردند. از قضا روزي شتر بازرگاني براي يافتن چراگاه به اطراف آن بيشه آمد و در حين قدم زدن به سلطان آن جا يعني شير برخورد و به ناچار تعظيم و تكريم بسيار كرد. شير با او احوال پرسي كرد و پرسيد: آيا قصد رفتن داري يا مي خواهي در اين جا منزل كني!؟ شتر جواب داد: هرچه سلطان گويد همان مي كنم. شير گفت: اگر ميل ماندن داشته باشي در هم نشيني با من هم از مال دنيا بي نياز مي شوي و هم در سايه حمايت من از خطرات احتمالي ايمن مي باشي. شتر خوشحال شد و در آن بيشه ماند. مدتي بر همين منوال گذشت. از قضا روزي شير در جستجوي شكار با فيل مستي روبه رو شد و ميان آنها جنگي سخت درگرفت و برخلاف هميشه، شير آن بار مجروح و نالان به لانه برگشت. زخم هاي شير طوري بود كه روزهاي بسيار توان راه رفتن و شكار كردن نداشت و كلاغ و گرگ و شغال بي غذا مانده بودند! شير كه اثر بي غذايي و ضعف شديد را در چهره آنها مي ديد، بلاخره طاقت نياورد و به آنها گفت: برويد سر و گوشي بجنبانيد و به من خبر دهيد؛ آيا صيدي در اين نزديكي ها مي بينيد تا من آن را شكار كنم و نياز شما را برآورده سازم؟ بعد از اين صحبت شير، كلاغ و گرگ و شغال به گوشه اي رفته و در مشورت با يكديگر گفتند: بودن شتر ميان ما چه فايده اي دارد؟ نه ما با او انس و الفتي داريم و نه وجودش مايه آسايش و راحتي پادشاه است. بايد شير را مجبور كنيم تا او را بكشد تا هم خودش سير شود و هم خرده غذايي به ما برسد. شغال گفت: اين كار شدني نيست، زيرا او به شتر امان داده است. مراقب باشيد! كه هر كس پادشاه را به بي وفايي تشويق كند و گناه شكستن عهد را در دل او سبك گرداند ياران و دوستانش را در گرداب بلا انداخته است و آفت مرگ و نيستي را به جان خود خريده است! كلاغ گفت: براي آن امان چاره اي مي توان انديشيد تا شير را از عهده عمل به آن بيرون آورد. شما اينجا بمانيد تا من برگردم. كلاغ نزد شير بازگشت. شير پرسيد: چيزي به دست آورديد؟ كلاغ پاسخ داد: چشم هيچ كداممان از گرسنگي نوري ندارد، اما چاره ديگري هست كه اگر پادشاه با آن موافقت كند همه مان در نعمت فراوان مي افتيم. شير گفت: بگو كلاغ ادامه داد: شتر ميان ما غريب و بيگانه است و بودن او ميان ما به هيچ كداممان فايده اي نمي رساند. شير خشمگين شد و گفت: اين صحبت از وفا و مردانگي دور است و با بزرگواري و مهرباني مناسبتي ندارد. من به شتر امان داده ام. به چه دليلي جفا و خيانت را واجب بدانم؟ كلاغ گفت: من اين چيزها را نمي دانم، اما حكما گفته اند: يك نفر فداي خانواده و خانواده فداي قبيله و قبيله فداي شهر و اهل شهر فداي ذات و وجود پادشاه، اگر خطري در ميان باشد. براي زير قول زدن راهي وجود دارد تا ننگ پشيماني و سرشكستگي نصيب پادشاه نشود درحالي كه وجود پادشاه از رنج و ترس هلاك شدن بيمناك است. شير سرش را پايين انداخت. كلاغ برگشت و به دوستانش گفت: شير كمي ناراحتي و سركشي كرد، اما بلاخره راضي شد. الان وقت آن است كه پيش شتر برويم و داستان رنجي كه به شير رسيده است را تازه گردانيم و بگوييم ما تا حال در زير سايه بزرگواري و جبروت شير روزگار خوشي را گذرانده ايم. اكنون كه شير در رنج و مضيقه افتاده است اگر جان خود را فداي راحتي او نكنيم كفران نعمت كرده ايم. خوب است كه همگي پيش شير برويم و سپاسگزار خوبي هايش باشيم و بگوييم كاري از ما برنمي آيد، مگر اين كه جانمان را فداي تو كنيم؟ آن وقت هر يك از ما بگويد: من امروز غذاي پادشاه خواهم شد و ديگران پيشنهاد او را با عذر و بهانه اي رد كنند. با اين كار هم ابراز دوستي كرده ايم و هم حق خود را ادا كرده ايم و هم زياني نديده ايم! پس همگي پيش شتر رفتند و نقشه خودرا عملي كردند و شتر بيچاره را در تنگنا قرار دادند و خلاصه پيش شير رفتند. كلاغ آغاز سخن كرد و گفت: آسايش ما وابسته به آسايش و راحتي پادشاه است حالا كه ضرورتي پيش آمده تقاضا دارم امروز پادشاه از گوشت من رفع گرسنگي كند. ديگران گفتند: چه فايده از خوردن تو! گوشت تو چه كسي را سير مي كند!؟ پس شغال هم با همان حيله شروع به صحبت كرد، به او جواب دادند كه؛ گوشت تو بوي نا مي دهد و مضر است و شايستگي غذاي پادشاه شدن ندارد. به دنبال او گرگ هم به همين صورت سخن گفت و در جواب او هم گفتند: گوشت تو حناق و خفگي مي آورد و جانشين زهر هلاهل است و شايستگي غذاي پادشاه شدن را نداري. اين بار شتر زبان باز كرد و از روي مهرباني مانند آنها سخن گفت، اما بر خلاف تصورش همه آنها باهم موافق شدند و گفتند: راست مي گويي! چه مهربان و صادقي! و يك باره بر سرش ريختند و او را پاره پاره كردند. اين داستان به ما مي گويد: مكر و حيله افراد مغرض اگر باهم يكي شوند بي تأثير نيست و قطعاً در قوي ترين اراده ها نفوذ مي كند، پس رهايي از اين حيله هوشياري بسيار مي خواهد."},{"id":1706,"category_id":10,"category_code":"s10","source_id":268,"title":"کبک ساده لوح","content":"در دامنه کوهستاني ، کبکي زندگي مي کرد که از کبک هاي ديگر زيباتر و و با وقارتر بود.  او آن قدر زيبا و جذاب بود و آن قدر ظريف راه مي رفت که شکارچيان آرزو داشتند او را به دام بيندازند و پرنده هاي شکاري نيز مي خواستند او را به دست آورند . اما اين کبک که  کبک خوشرو  نام داشت ، بسيار زيرک و عاقل بود . او براي آنکه زندگيش به خطر نيفتد ، از تنها پرواز کردن خودداري مي کرد و هيچگاه با پرنده هاي بيگانه همنشين نمي شد. يک روز وقتي کبک خوشرو ، نزديک خانه اش با صداي بلند آواز مي خواند، يک باز که در آسمان پرواز مي کرد ، او را ديد و صداي آواز دلنشين اش را شنيد . آن قدر مجذوب و عاشق کبک خوشرو شد که نتوانست او را ترک کند . باز با خود گفت :  هرکس به يک دوست مهربان و خوب نياز دارد . چقدر خوب مي شد اگر مي توانستم با اين کبک زيبا دوست شوم . من با ديدن و زندگي کردن با او تمام غم هاي دنيا را فراموش خواهم کرد. باز فرود آمد و خيلي آهسته به سوي کبک رفت. کبک با ديدن باز ، با قدمهاي کوتاه خود در شکاف بين سنگها پنهان شد. باز به سوراخ نزديک شد و به آرامي گفت : اي کبک زيبا ، از من نترس . من دوست و عاشق تو هستم. پيش از اين از همه جذابيتهاي تو غافل بودم ، اما حالا به همه زيبايي هاي تو پي برده ام و مي خواهم با تو دوست شوم. کبک با تندي و خشونت پاسخ داد : اي قهرمان بزرگ مرا تنها بگذار و برو. کار تو شکار است . برو و يک موجود  ديگر را پيدا کن . تو نمي تواني مرا فريب دهي . باز گفت :  اي کبک ، همانطور که مي گويي ، کبک هاي زيادي وجود دارند و کار من شکار است، اما حيله گري کار ضعيف هاست. با همه قدرتم ، نيازي به چاپلوسي ندارم. اگر قصد من شکار بود ، مي توانستم بروم و کبک ديگري را شکار کنم . حقيقت اين است که مهر تو ، قلب مرا لبريز از عشق کرده است و دلم مي خواهد که دوست تو باشم و با تو زندگي کنم.  کبک گفت :  حتي اگر راست بگويي و مجذوب رفتار من شده باشي ، اين دليل قانع کننده اي براي دوستي ما نخواهد بود. من معتقدم که محبت تو زودگذر است ، زيرا تو يک پرنده شکاري هستي و من لقمه لذيذي براي تو خواهم بود. بنابراين دوستي بين ما منطقي به نظر نمي رسد . درست همانگونه که آب و آتش نمي توانند با يکديگر باشند ، همنشيني ما با زوال و نابودي پايان مي پذيرد .\r\nباز گفت :  تو خوب مي داني که من از يافتن غذاي خود عاجز نيستم . بنابراين هيچ دليلي براي صدمه رساندن به تو وجود ندارد . اگر ما با هم دوست شويم ، چند فايده براي تو دارد.  اول آنکه همنوعان ديگر من به تو آسيبي نمي رسانند و به تو احترام خواهند گذاشت ، به خاطر اينکه مي دانند تو دوست من هستي . دوم آنکه ، لانه من در جاي خوشايند و راحتي روي نوک يک درخت بلند است و من تو را به آنجا مي برم . به علاوه ، دشت و صحرا را زير پاهايت خواهي ديد . سوم آنکه ، من قوي هستم و هميشه براي تو بهترين خانه و بهترين غذا را تهيه مي کنم . در طول روز ، تو را به جاهايي مي برم که کبک هاي ديگر آرزو دارند آنجاها را ببينند ، اما نمي توانند . بالاخره کاري مي کنم که خوشي تو کامل شود ، و با خوشحالي تو ، من هم خوشحالتر خواهم شد. تو تنها موجودي هستي که من دوست دارم . مرا مأيوس نکن . \r\nکبک با شنيدن حرفهاي محبت آميز باز ، دلش سوخت و جواب داد :  بسيار خوب ، اما تو سر دسته پرنده ها هستي و به فرض آنکه مرا دوست داشته باشي، شايد کساني باشند که به خوشبختي ما حسادت کنند و سعي داشته باشند با بدگويي ، ما را از يکديگر متنفر سازند. در آن صورت چه کنيم ؟ يا اگر به دليلي از من عصباني شوي و بخواهي به من آسيب برساني ، هيچ چيز نمي تواند مانع تو شود . بنابراين براي من بهتر است که به همين زندگي آرام خود قانع باشم و براي خودم دردسر درست نکنم .\r\nباز گفت : عزيزم ، چه چيزهاي عجيبي مي گويي ! من قول مي دهم که به حرف هيچ کس گوش نکنم ، با عشق به تو نگاه کنم و هرگز عصباني نشوم . به تو قول مي دهم تا زماني که با من زندگي مي کني ، از ديگران بهتر زندگي خواهي کرد.  کبک با شنيدن اين حرفهاي شيرين و قولهايي که باز به او داد ، متقاعد شد و سرانجام از پناهگاه بيرون آمد . يکبار ديگر کبک از باز درباره وفاداري و مهربان بودن با او پرسيد . وقتي باز قول خود را تکرار کرد و کبک را از وفاداريش مطمئن ساخت ، کبک را روي شانه هاي خود گذاشت و او را به لانه اش در بالاي درخت برد .\r\nباز پس از آنکه رضايت کبک را جلب کرد ، او را روي شانه هاي خود گذاشت و به لانه اش بالاي درخت برد .چند روزي گذشت . باز با گرمي و مهرباني ، کبک را سرگرم مي کرد و او را به مرغزارها ، کوهستان و جنگل ها مي برد و با هم خوشحال و خوشبخت بودند . کبک به اين مهرباني و سرگرمي راضي بود و خوشحال بود که مي ديد پرنده هاي ديگر با احترام به آنها مي نگرند . به همين دليل ، کبک که خوشحالتر از هميشه بود ، بلندتر آواز مي خواند و با ناز بيشتري راه مي رفت . هر دو از اين وضع خوشحال و راضي بودند و لذت مي بردند . کم کم کبک به زندگي جديد خود عادت کرد و بعضي وقت ها کبک هاي ديگر را نيز مسخره مي کرد و مي گفت :  چه موجودهاي بدبختي هستند و چه زندگي يکنواخت و خسته کننده اي دارند . هميشه روي زمين توي سوراخ هايشان هستند ! چيزي از زندگي درک نکرده اند . تا حالا روي نوک درخت نبوده اند … مدتي به همين شکل گذشت . يک روز وقتي از گردش به خانه برمي گشتند ، باز خيلي ساکت بود و نمي خنديد . وقتي به خانه رسيدند ، کبک را آن قدر محکم و بي دقت پايين انداخت که پاي کبک صدمه ديد . کبک کمي ناراحت شد ، اما فکر کرد شايد باز با کسي بحث و دعوا کرده و عصباني شده است . لذا با خنده و گفتن موضوعات خوشايند ، سعي کرد باز را به صحبت کردن وا دارد . اما باز ترشرو بود و جواب نمي داد . کم کم کبک ترسيد و فکر کرد :  جاي افسوس و پشيماني است که من زندگي را با اين چنين پرنده اي هدر بدهم . اشتباه خودم بود که کسي را انتخاب کردم که همنوع من نيست و از من قوي تر است ، در حالي که مي توانستم زندگي خوبي داشته باشم . اگر اوضاع از اين بدتر شود ، بايد چکار کنم ؟\r\nبالاخره اين اتفاق افتاد . آن روز باز چيزي براي شکار و خوردن پيدا نکرده بود و خيلي گرسنه بود . ديگر هوا تاريک شده بود و چيزي در مرغزار پيدا نمي شد . او سعي مي کرد بهانه اي پيدا کند تا کبک را بخورد . کبک خيلي با احتياط رفتار مي کرد تا به باز بهانه اي ندهد و به خصوص با باز خيلي مؤدب و مهربان بود . ناگهان باز از کبک پرسيد :  چرا معذّب و ناراحت هستي ؟  کبک گفت :  تا زماني که با تو هستم ، هيچ چيز مرا ناراحت نمي کند .  باز گفت :  چرا نمي نشيني ؟  کبک گفت :  هر کاري بگويي مي کنم . اگر بخواهي مي نشينم “. و با ادب روبروي باز نشست . باز بهانه ديگري گرفت و گفت :  چرا اينقدر با تکبر رفتار مي کني و حرف نمي زني ؟  کبک گفت :  از آنجايي که تو هم صحبت نمي کني ، فکر کردم شايد خسته باشي و بخواهي استراحت کني . حاضرم هرچه بخواهي انجام دهم .  باز متوجه شد که همه بهانه هاي او با احترام پاسخ داده مي شود ، اما گرسنگي او را بي طاقت و بي صبر کرده بود . پس با خشونت گفت :  آيا انصاف است که من در چنين فصل داغي در زير آفتاب بنشينم و تو در سايه ؟  کبک گفت :  عزيزم ، منظورت از اين حرف ها چيست ؟ الان شب است و آفتاب وجود ندارد . اين چه جور بهانه اي است ؟  باز عصباني شد ، کبک را به چنگال گرفت و گفت :  پرنده گستاخ و بي ادب ! چطور جرأت مي کني حرف مرا تکذيب کني و مرا دروغگو خطاب کني ؟ چرا بايد تو راضي و خوشحال باشي ، در حالي که من گرسنه ام ؟  باز درحالي که اين حرف ها را مي زد ، کبک بي پناه و بي دفاع را تکه تکه کرد و در حين خوردن گوشت کبک گفت :  از همه اينها که بگذريم ، کبک فقط به درد خوردن مي خورد . من فقط مي خواستم چند روزي سرگرم باشم . اين کبک ساده لوح ، فکر مي کرد که مي تواند مرا با ناز و ادا تا ابد سرگرم کند .\r\n"},{"id":1707,"category_id":10,"category_code":"s10","source_id":269,"title":"دزدان و زن و مرد","content":"\r\nشبی  دزدي با ياران خود براي دزدي به بام خانه اي رفت .\r\n صاحب خانه بيدار شد آهسته زنش را بيدار كرد و به او گفت:\r\n دزد آمده من خود را به خواب مي زنم وتو به طوري كه   صداي تو را دزدان بشنوند به ترتیبی که میگویم با من گفتگو کن...\r\n زن با صداي بلند گفت: راستش را بگو مرد اين طلاها را از كجا آورده اي؟\r\nمرد گفت:اين راز را نمي گويم.\r\n زن اصرار كرد.\r\n مرد گفت : دزديده ام.\r\n زن بسيار ناراحت شد وگفت: از كجا؟\r\nمرد گفت: من ا فسوني بلدم كه دزدي را برايم بسيار آسان كرده است.\r\n زن گفت : تورا خدا به من هم ياد بده.\r\n مرد گفت : در شبهاي مهتابي ميروم كنار ديوار خانه ثروتمندان مي ايستم وهفت بار مي گويم: شولي شولي شلماني . بعد غيب ميشوم و روي بام آن خانه ظاهرمیشوم. دوباره هفت بار ميگويم: شولي شولي شلماني   و درحياط خانه مي جهم بدون آ نكه آسيبي .ببينم  مجددا افسون را خوانده  واين بار  داخل اطاق میشوم و بار ديگر که ورد می خوانم  هرقدر طلا در خانه هست جلو من جمع مي شود.\r\nز ن گفت: جطور از خانه بيرون میايي؟ مرد گفت: يادت رفت شولي شولي ؟ با اين افسون نه مرا كسي مي بيند ونه كسي به من بد گمان مي شود.\r\nدزدان اين سخنان شنيدند و بسيار خوشحال شدند و منتظر شدند تا مرد و زن خوابيدند بعد همه باهم خواندند: شولي شولي شلماني واز بام  به حياط پريدند.\r\n"},{"id":1708,"category_id":10,"category_code":"s10","source_id":270,"title":"حج","content":"\r\nگویند شیخ ابو سعید ابوالخیر چند درهم اندوخته بود تا به زیارت كعبه رود. با كاروانی همراه شد و چون توانایی پرداخت برای مركبی نداشت، پیاده سفر كرده و خدمت دیگران می كرد. تا در منزلی فرود آمدند و شیخ برای جمع اوری هیزم به اطراف رفت. زیر درختی، مرد ژنده پوشی با حالی پریشان دید و از احوال وی جویا شد. دریافت كه از خجالت اهل و عیال در عدم كسب روزی به اینجا پناه اورده است و هفته ای است كه خود و خانواده اش در گرسنگی به سر برده اند. شیخچند درهم اندوخته خود را به وی داد و گفت برو.\r\nمرد بینوا گفت: مرا رضایت نیست تو در سفر حج در حرج باشی تا من برای فرزندانم توشه ای ببرم.\r\nشیخ گفت حج من، تو بودی و اگر هفت بار گرد تو طواف كنم به ز آنكه هفتاد بار زیارت آن بنا كنم.\r\n"},{"id":1709,"category_id":10,"category_code":"s10","source_id":271,"title":"سرمایه ابدی","content":"می گویند: روزی مولانا ، شمس تبریزی را به خانه اش دعوت کرد.شمس به خانه جلال الدین رومی رفت و پس از این که وسائل پذیرایی میزبانش را مشاهده کرد از او پرسید: آیا برای من شراب فراهم نموده ای؟ \r\nمولانا حیرت زده پرسید:مگر تو شراب خوارهستی؟ \r\nشمس پاسخ داد: بلی.\r\n مولانا: ولی من از این موضوع اطلاع نداشتم. ـ حال که فهمیدی برای من شراب مهیا کن. در این موقع شب ،شراب از کجا گیر بیاورم؟ \r\nبه یکی از خدمتکارانت بگو برود و تهیه کند. - با این کار آبرو و حیثیتم بین خدام از بین خواهد رفت. پس خودت برو و شراب خریداری کن. در این شهر همه مرا میشناسند،چگونه به محله نصاری نشین بروم و شراب بخرم؟ اگر به من ارادت داری باید وسیله راحتی مرا هم فراهم کنی چون من شب ها بدون شراب نه میتوانم غذا بخورم ،نه صحبت کنم و نه بخوابم. \r\nمولوی به دلیل ارادتی که به شمس داشت، خرقه ای به دوش می اندازد، شیشه ای بزرگ زیر آن پنهان میکند و به سمت محله نصاری نشین راه می افتد. تا قبل از ورود او به محله مذکور کسی نسبت به مولوی کنجکاوی نمیکرد اما همین که وارد آنجا شد. مردم حیرت کردند و به تعقیب وی پرداختند.آنها دیدند که مولوی داخل میکده ای شدو شیشه ای شراب خریداری کرد و پس از پنهان نمودن آن،از میکده خارج شد. هنوز از محله مسیحیان خارج نشده بود که گروهی از مسلمانان ساکن آنجا، در قفایش به راه افتادند و لحظه به لحظه بر تعدادشان افزوده شد تا این که مولوی به جلوی مسجدی که خود امام جماعت آن بود و مردم همه روزه در آن به او اقتدا می کردند رسید.\r\nدر این حال یکی از رقیبان مولوی که در جمعیت حضور داشت فریاد زد:ای مردم!شیخ جلال الدین که هر روز هنگام نماز به او اقتدا میکنید به محله نصاری نشین رفته و شراب خریداری نموده است. آن مرد این را گفت و خرقه را از دوش مولوی کشید. چشم مردم به شیشه افتاد.مرد ادامه داد:این منافق که ادعای زهد میکند و به او اقتدا میکنید، اکنون شراب خریداری نموده و با خود به خانه میبرد. سپس بر صورت جلال الدین رومی آب دهان انداخت و طوری بر سرش زد که دستار از سرش باز شد و بر گردنش افتاد. زمانی که مردم این صحنه را دیدند و به ویژه زمانی که مولوی را در حال انفعال و سکوت مشاهده نمودند یقین پیدا کردند که مولوی یک عمر آنها را با لباس زهد و تقوای دروغین فریب داده و درنتیجه خود را آماده کردند که به او حمله کنند و به قتلش رسانند.\r\nدر این هنگام شمس از راه رسید و فریاد زد: ای مردم بی حیا! شرم نمیکنید که به مردی متدین و فقیه تهمت شرابخواری میزنید.این شیشه که میبینید حاوی سرکه است  که هرروز با غذای خود تناول می کنید. رقیب مولوی فریاد زد:این سرکه نیست بلکه شراب است. شمس در شیشه را باز کرد و در کف دست همه  مردم از جمله آن رقیب، قدری از محتویات شیشه ریخت و بر همگان ثابت شد که درون شیشه چیزی جز سرکه نیست. رقیب مولوی بر سر خود کوبید و خود را به پای مولوی انداخت. دیگران هم دست های او را بوسیدند و متفرق شدند.\r\nآنگاه مولوی از شمس پرسید:برای چه امشب مرا دچار این فاجعه نمودی و مجبورم کردی تا به آبرو و حیثیتم چوب حراج بزنم؟  شمس گفت: برای این که بدانی آنچه که به آن می نازی جز یک سراب نیست، تو فکر میکردی که احترام یک مشت عوام برای تو سرمایه ایست ابدی، در حالی که خود دیدی،با تصور یک شیشه شراب همه  آن از بین رفت و آب دهان به صورتت انداختند و بر فرقت کوبیدند و چه بسا تو را به قتل میرساندند.این سرمایه  تو همین بود که امشب دیدی و در یک لحظه بر باد رفت.\r\n"},{"id":1710,"category_id":10,"category_code":"s10","source_id":272,"title":"جا خواستیم و جانشین نخواستیم","content":"می گویند زمانی که قرار بود دادگاه لاهه برای رسیدگی به دعاوی انگلیس در ماجرای ملی شدن صنعت نفت تشکیل شود ، دکتر مصدق با هیات همراه زودتر از موقع به محل رفت . در حالی که پیشاپیش جای نشستن همه ی شرکت کنندگان تعیین شده بود ، دکتر مصدق رفت و به نمایندگی هیات ایران روی صندلی نماینده انگلستان نشست. \r\n قبل از شروع جلسه ، یکی دو بار به دکتر مصدق گفتند که اینجا برای نماینده هیات انگلیسی در نظر گرفته شده و جای شما آن جاست ، اما پیرمرد توجهی نکرد و روی همان صندلی نشست. \r\n جلسه داشت شروع می شد و نماینده هیات انگلیس روبروی دکتر مصدق منتظر ایستاده بود تا بلکه بلند شود و روی صندلی خویش بنشیند ، اما پیرمرد اصلاً نگاهش هم نمی کرد. \r\n جلسه شروع شد و قاضی رسیدگی کننده به مصدق رو کرد و گفت که شما جای نماینده انگلستان نشسته اید ، جای شما آن جاست.\r\n کم کم ماجرا داشت پیچیده می شد و بیخ پیدا میکرد که مصدق بالاخره به صدا در آمد و گفت : شما فکر می کنید نمی دانیم صندلی ما کجاست و صندلی نماینده هیات انگلیس کدام است ؟\r\nنه جناب رییس ، خوب می دانیم جایمان کدام است ..اما علت اینکه چند دقیقه ای روی صندلی دوستان نشستم به خاطر این بود تا دوستان بدانند برجای دیگران نشستن یعنی چه ؟\r\nاو اضافه کرد که سال های سال است دولت انگلستان در سرزمین ما خیمه زده و کم کم یادشان رفته که جایشان این جا نیست و ایران سرزمین آبا و اجدادی ماست نه سرزمین آنان  سکوتی عمیق فضای دادگاه را احاطه کرده بود و دکتر مصدق بعد از پایان سخنانش کمی سکوت کرد و آرام بلند شد و به روی صندلی خویش قرار گرفت.\r\n با همین ابتکار و حرکت ، عجیب بود که تا انتهای نشست ، فضای جلسه تحت تاثیر مستقیم این رفتار پیرمرد قرار گرفته بود و در نهایت نیز انگلستان محکوم شد.\r\n"},{"id":1711,"category_id":10,"category_code":"s10","source_id":273,"title":"چاپلوسی در دربار کریم خان","content":"کریم خان زند هر روز صبح علی الطلوع تا شامگاه برای دادخواهی ستمدیدگان، رفع ستم و احقاق حقوق مردم در ارگ شاهی می نشست و به امور مردم رسیدگی می کرد. یک روز مردک حقه باز و چاپلوسی پیش آمد و همین که چشمش به کریم خان افتاد، شروع به های و های گریستن کرده و سیلاب اشک از دیدگان فرو ریخت، او طوری گریه می کرد که هق و هق هایش اجازه سخن گفتن به او نمی داد.\r\nشاه که خود را وکیل الرعایا می نامید؛ دستور داد او را به گوشه ای برده، آرام کنند زان پس به حضور برسد. مردک حقه باز را بردند و آرام کردند و در فرصت مناسب دیگری به حضور کریم خان آوردند.\r\nکریم خان قبل از آنکه رسیدگی به کار او را آغاز کند نوازش و دلجویی فراوانی از وی به عمل آورد و آنگاه از خواسته اش جویا شد. آن مرد گفت: “من از مادر کور و نابینا متولد شدم و سالها با وضع اسف باری زندگی کرده و نعمت بینایی و دیدن اطراف و اکناف خود محروم بودم تا اینکه روزی افتان خیزان و کورمال خود را روی زمین کشیدم و به سختی به زیارت آرامگاه پدر شما رفته و برای کسب سلامتی خود، متوسل به مرقد مطهر ابوی مرحوم شما شدم. در آن مزار متبرک آنقدر گریه کردم که از فرط خستگی ضعف،‌ بیهوش شده ، به خواب عمیقی فرو رفتم! در عالم خواب و رویا، مردی جلیل القدر و نورانی را دیدم که سراغ من آمد و گفت: ابوالوکیل پدر کریم خان هستم. آنگاه دستی به چشمان من کشید و گفت برخیز که تو را شفا دادم! از خواب که بیدار شدم،‌ خود را بینا دیدم و جهان تاریک پیش چشمانم روشن شد! این همه گریه و زاری امروز من از باب تشکر و قدر دانی و سپاسگذاری از والد ماجد شما بود!.\r\nمردک حقه باز که باادای این جملات و انجام این صحنه سازی مطمئن بود کریم خان را خام کرده است، منتظر دریافت صله و هدیه و مرحمتی بود که مشاهده کرد کریم خان برافروخته شده، دنبال د‍ژخیم می گردد! موقعی که دژخیم حاضر گردید کریم خان دستور داد چشمان مرد حقه باز را از حدقه بیرون بکشد! درباریان و بزرگان قوم زندیه به دست و پای کریم خان افتادند و شفاعت مرد متملق و چاپلوس را کرده و از وکلیل الرعایا خواستند از گناه او در گذرد. کریم خان که ذاتا آدم رقیق القلبی بود، خواهش درباریان و اطرافیان را پذیرفت، ولی دستور داد مرد متملق را به فلک بسته، چوب بزنند!\r\nهنگامی که نوکران شاه مشغول سیاست کردن مرد حقه باز بودند کریم خان خطاب به او گفت: “مردک پدر سوخته! پدر من تا وقتی زنده بود در گردنه بید سرخ، خر دزدی می کرد من که مقام و مسند شاهی رسیدم عده ای متملق برای خوشایند من و از باب چاپلوسی برایش آرامگاهی ساختند و مقبره ای برپا کردند و آنجا را عنیان ابوالوکیل نامیدند. اکنون تو چاپلوس دروغگو آمده ای و پدر خر دزد مرا صاحب کرامت و معجزه معرفی می کنی؟! اگر بزرگان مجلس اجازه داده بودند دوباره چشمانت را در می آوردم تا بروی برای بار دوم از او چشمان تازه و پر فروغ بگیری!” \r\nمردک سرافکنده و شرمسار به سرعت از پیش او رفت و ناپدید شد.\r\n"},{"id":1712,"category_id":10,"category_code":"s10","source_id":274,"title":"گرانبهاترین دارایی","content":"بر بالای تپه‌ای در شهر وینسبرگ آلمان، قلعه ای قدیمی‌و بلند وجود دارد که مشرف بر شهر است. اهالی وینسبرگ افسانه ای جالب در مورد این قلعه دارند که بازگویی آن مایه مباهات و افتخارشان است.\r\nافسانه حاکی از آن است که در قرن 15، لشکر دشمن این شهر را تصرف و قلعه را محاصره می‌کند. اهالی شهر از زن و مرد گرفته تا پیر و جوان، برای رهایی از چنگال مرگ به داخل قلعه پناه می‌برند.\r\nفرمانده دشمن به قلعه پیام می‌فرستد که\r\nقبل از حمله ویران کننده خود حاضر است به زنان و کودکان اجازه دهد تا صحیح و سالم از قلعه خارج شده و پی کار خود روند.\r\nپس از کمی‌مذاکره، فرمانده دشمن به خاطر رعایت آیین جوانمردی و بر اساس قول شرف، موافقت می‌کند که هر یک از زنان در بند، گرانبها ترین دارایی خود را نیز از قلعه خارج کند به شرطی که به تنهایی قادر به حمل آن باشد.\r\nنا گفته پیداست که قیافه حیرت زده و سرشار از شگفتی فرمانده دشمن به هنگامی‌که هر یک از زنان شوهر خود را کول گرفته و از قلعه خارج می‌شدند بسیار تماشایی بود...\r\n"},{"id":1713,"category_id":10,"category_code":"s10","source_id":275,"title":"حکمت خداوند","content":"کشیش تازه کار و همسرش برای نخستین ماموریت و خدمت خود کـه بازگشایی کلیسایی در حومه بروکلین ( شهر نیویورک ) بود در اوایل ماه کتبر وارد شهر شدند. \r\nزمانی که کلیسا را دیدند ، دلشان از شور و شوق آکنده بود . کلیسا کهنه و قدیمی بود و به تعمیرات زیادی نیاز داشت. \r\nدو نفری نشستند و برنامه ریزی کردند تا همه چیز برای شب کریسمس یعـنـی 24 دسامبر آماده شود . کمی بیش از دو ماه برای انجام کار ها وقت داشتند. \r\nکشیش و همسرش سخت مشغول کار شدند . دیوار ها را با کاغذ دیواری پوشاندند . جاهایی را که رنگ لازم داشت ، رنگ زدند و کار های دیگری را که باید می کردند ، انجام دادند . روز 18 دسامبر آنها از برنامه شان جلو بودند و کـارها تقریباً رو به پایان بود. \r\nروز 19 دسامبر باران تندی گرفت که دو روز ادامه داشت . روز 21 دسامبر پس از پایان بارندگی ، کشیش سری به کلیسا زد ، وقتی وارد تـالار کلیسا شد ، نزدیک بود قلب کشیش از کار بیافتد . سقف کلیسا چکه کـرده بود و در نتیجه بخش بزرگی از کاغذ دیواری به اندازه ای حدود 6 متر در 5/2 متر از روی دیوار جلویی و پشت میز موعظه کنده شده و سوراخ شده بود. \r\nکشیش در حالی که همه خاکروبه های کف زمین را پاک می کرد ، با خود اندیشید که چاره ای جز به عقب انداختن برنامه شب کریسمس ندارد. \r\nدر راه بازگشت به خانه دید که یکی از فروشگاه های محلّه ، یک حـراج خیریه برگزار کرده است . کشیش از اتومبیلش پیاده شد و به سراغ حـراج رفت . در بین اجناس حراجی ، یک رومیزی بسیار زیبای شیری رنگ دستبافت دید که به طرز هنرمندانه ای روی آن کار شده بود . رنگ آمیزی اش عالی بود . در میانه رو میزی یک صلیب گلدوزی شده به چشم می خورد . رومیزی درست به اندازه سوراخ روی دیوار بـود. \r\nکشیش رومیزی را خرید و به کلیسا برگشت. \r\nحالا دیگر بارش برف آغاز شده بود . زن سالمندی که از جهت رو به روی کشیش می آمد دوان دوان کوشید تا به اتوبوسی که تقریباً در حال حرکت بود برسد ، ولی تلاشش بی فایده بود و اتوبوس راه افتاد . اتوبوس بعـدی 45 دقیقه دیگر می رسید . کشیش به زن پیشنهاد کرد که به جای ایستادن در هوای سـرد به درون کلیسا بیاید و آنجا منتظر شود . زن دعوت کشیش را پذیرفت و به کلیسـا آمـد و روی یکی از نیمکت های تالار نیایش نشست . کشیش رفت نردبان را آورد تا رومیـزی را روی دیوار نصب کند . پس از نصب ، کشیش نگاه رضایت مندانه ای به پرده آویخـتـه شـده کرد ، باورش نمی شد که این قدر زیبا باشد. \r\nکشیش متوجه شد که زن به سوی او می آید . زن پرسید : این رومیزی را از کـجا گرفته اید ؟ و بعد گوشه رومیزی را به دقت نگاه کرد . در گوشه آن سه حـرف گلدوزی شده بود . این ها سه حرف نخست نام و نام خانوادگی او بودند . او 35 سال پیش این رومیزی را در کشور اتریش درست کرده بود . وقتی کشیش برای زن شرح داد کـه از کجا رومیزی را خریده است . باورکردنش برای زن سخت بود . سپس زن برای کشیش تعریف کرد که چگونه پیش از جنگ جهانی دوم ، او و شوهرش در اتریش زندگی خوبی داشتند ، ولی هنگامی که هیتلر و نازی ها سر کار آمدند ، او ناچار شد اتریش را ترک کند. \r\nشوهرش قرار بود که یک هفته پس از او ، به وی بپیوندد ولی شوهرش توسط نازی ها دستگیر و زندانی شد و زن دیگر هرگز شوهرش را ندید و هرگز هم به میهنش برنگشت. \r\nکشیش می خواست رومیزی را به زن بدهد ، ولی زن گفت : بهتر است آن را برای کلیسا نگه دارید . کشیش اصرار کرد که اقلاً بگذارد او را با اتومبیل به خانه اش برساند و گفت این کمترین کاری است که می توانم برایتان انجام دهم . زن پذیرفت . زن در سوی دیگر ، یعنی جزیره استاتن زندگی می کرد و آن روز برای تمیز کردن خانه یک نفر به این سوی شهر آمده بود. \r\nشب کریسمس برنامه عالی برگزارشد . تالار کلیسا تقریباً پـر بود. \r\nموسیقی و روح حکمفرما بر کلیسا فوق العاده بود . در پایان برنامه و هنگام خداحافظی ، کشیش و همسرش با یکایک میهمانان دست داده و خدا نگهدار گفتند ، بسیاری از آنها گفتند که بازهـم بـه کلیسا خواهند آمد . وقتی کشیش به درون تالار نیایش برگشت مرد سالمندی را که در نزدیکی کلیسا زندگی می کرد ، دید که هنوز روی نیمکت نشسته است . مرد از کشیش پرسید کـه این رومیزی را از کجا گرفته اید ؟ و سپس برای کشیش شرح داد که همسرش سال ها پیش در اتریش که رومیزی درست شبیه به این درست کرده بود و شگفت زده بود که چگونه ممکن است دو رومیزی عیناً شکل هم باشند . مرد به کشیش گفت که چگونه توسط نازی ها دستگیر و زندانی شده و هرگز نتوانسته همسر گم شده اش پیدا کند . پس از شنیدن این سخنان ، کشیش به مرد گفت : اجازه بدهید با ماشین دوری بزنیم و با هم گفت و گویی داشته باشیم . سپس او را سوار اتومبیل کرد و به جزیره استاتن و خانه زنی که سه روز پیش او را دیده بود ، برد . کشیش به مرد کمک کرد تا از پله های ساختمان سه طبقه بالا برود و وقتی جلوی در آپارتمان زن رسید ، زنگ در را به صدا درآورد . وقتی زن در را باز کرد ، صحنه دیدار دوباره زن و شوهر پس از سال ها وصف ناشدنی بود... \r\nآنچه خواندید یک داستان واقعی بود که توسط کشیش راب رید گزارش شده است.\r\n"},{"id":1714,"category_id":10,"category_code":"s10","source_id":276,"title":"کریسمس در جنگ","content":"ارتش های آلمان ، بریتانیا و فرانسه در جریان جنگ جهانی اول در بلژیک با هم می جنگیدند.\r\nشب کریسمس جنگ را تعطیل می کنند تا دست کم برای چند ساعت کریسمس را جشن بگیرند در ارتش آلمان یکی از سربازان که سابقه خواندن در اپرا را داشت ،\r\nشروع به خواندن ترانه کریسمس مبارک می کند.\r\nصدای خواننده آلمانی را سربازان جبهه های دیگر می شنوند و با پرچم های سفید به نشانه صلح از خاکریز بالا می آیند و بسوی ارتش آلمان می روند.\r\nآن شب سربازان هر سه ارتش در کنار هم شام می خورند و کریسمس را جشن می گیرند\r\nولی هر ۳ فرمانده توافق می کنند:\r\nکه از روز بعد صلح شکسته شود و جنگ را از سر بگیرند!\r\nصبح روز بعد دست و دل سربازان برای جنگ نمی رفت.\r\nشب قبل آنقدر با دشمن رفیق شده بودند که بی خیال جنگ شدند و از پشت خاکریز برای هم دست تکان می دادند!\r\nچند ساعت که گذشت باز هم پرچم های سفید بالا رفت و پس از گفتگوی سه نماینده ارتش ها تصمیم بر این گرفته شد که برای سرگرم شدن با هم فوتبال بازی کنند.\r\nآنها آنقدر با هم رفیق می شوند که با هم عکس می گیرند و حتی آدرس خانه های خود را به همدیگر می دهند تا بعد از جنگ به کشور های هم سفر کنند!\r\nکار به جایی می رسد که این سه 3 ارتش به هم پناه می دهند و ...\r\nتنها چیزی که باعث می شود قضیه لو برود متن نامه هایی بود که سربازان برای خانواده هایشان فرستاده بودند و به آنها اطمینان داده بودند که اینجا از جنگ خبری نیست!\r\n"},{"id":1715,"category_id":10,"category_code":"s10","source_id":277,"title":"اصالت یا تربیت","content":"در تاریخ آمده است ، به رسم قدیم روزی شاه عباس کبیر در اصفهان به خدمت عالم زمانه \" شیخ بهائی\" رسید. پس از سلام واحوالپرسی از شیخ پرسید: « در برخورد با افراد اجتماع  \" اصالت ذاتی\" آنها بهتر است یا \"تربیت خانوادگی\" شان ؟  \r\n   شیخ گفت : هر چه نظر حضرت اشرف باشد همان است، ولی به نظر من \" اصالت \" ارجح است.شاه برخلاف او گفت: شک نکنید که \"تربیت\" مهم تر است! بحث میان آن دو بالا گرفت و هیچیک نتوانستندیکدیگر را قانع کنند. بناچار، شاه برای اثبات حقانیت خود، او را به کاخ دعوت کرد تا حرفش رابه کرسی نشاند.\r\nفردای آن روز هنگام غروب، شیخ به کاخ رسید. بعد از تشریفات اولیه،وقت شام فرارسید. سفره ای بلند پهن کردند ولی چون چراغ وبرقی نبود، مهمانخانه سخت تاریک بود در این لحظه پادشاه دستی به کف زد و با اشاره او، چهارگربه شمع به دست حاضر شدند وآنجا را روشن کردند!درهنگام ِ شام ، شاه دستی پشت شیخ زد و گفت: دیدی گفتم \"تربیت\" از \"اصالت\" مهم تر است! مااین گربه های نا اهل را اهل و رام کردیم که این نتیجه ی اهمیت \" تربیت \" است.\r\nشیخ در عین اینکه هاج و واج مانده بود گفت من فقط به یک شرط حرف شما را می پذیرم و آن اینکه فردا هم گربه ها مثل امروز چنین کنند!! شاه که از حرف شیخ سخت تعجب کرده بود، گفت: این چه حرفیست؟ فردا مثل امروز وامروز هم مثل دیروز!!! کار آنها اکتسابی است که با تربیت و ممارست وتمرین زیاد انجام می شود.\r\nولی شیخ دست بردار نبود که نبود تا جایی که شاه عباس را مجبور کرد تا این کار را فردا تکرار کند. لذا شیخ، فکورانه به خانه رفت.او وقتی از کاخ برگشت بیدرنگ دست به کار شد. چهار جوراب برداشت و چهار موش  بخت برگشته در آن نهاد.\r\nفردا او باز طبق قرار قبلی به کاخ رفت. تشریفات همان و سفره همان و گربه های بازیگر همان ! شاه که مغرورانه تکرار مراسم دیروز را تأکیدی برصحّت حرفهایش می دید، زیر لب برای شیخ رجز میخواند  که در این زمان، شیخ موشها را رها کرد. هنگامه ای به پا شد یک گربه به شرق، دیگری به غرب، آن یکی، شمال واین یکی،جنوب! واین بار شیخ دستی برپشت شاه زد و گفت: شهریارا! یادت باشد اصالت  گربه، موش گرفتن است گرچه \"تربیت\" هم بسیار مهم است ولی\" اصالت \" مهم تر!\r\nیادت باشد با \"تربیت\" میتوان گربه را  رام  و آرام کرد ولی هرگاه گربه موش را دید، به اصل و ”اصالت\" خود بر می گردد و شیر نا اهل و نا آرام و درنده می شود!\r\n"},{"id":1716,"category_id":10,"category_code":"s10","source_id":278,"title":"همه ی ماستها را کیسه کردند","content":"وزیری به پادشاه (شاه عباس) می گوید: قوت مردم فقیر ماست است و ماست بند ها نیز مرتب قیمت ماست را بالا می برند. حکمی بده که قیمت ماست ها زیاد نشود.\r\nپادشاه نیز امر می کند که قیمت ماست نباید از فلان مقدار بیشتر شود.\r\nروزی به پادشاه خبر می دهند که ماست بند های شهر دو نوع ماست می فروشند. ماست شاه عباسی که به قیمت اعلام شده فروش می رود و ماستی که به قیمت بالا فروش می رود.\r\nپادشاه با لباس مبدل به بازار می رود و طلب ماست می کند. ماست بند می گوید: چه ماستی می خواهی؟ پادشاه با تعجب می پرسد: ماست می خواهم دیگر! چه فرقی می کند؟ ماست بند می گوید: گوئی تازه به این مملکت آمدی؟! در این ولایت دو نوع ماست داریم. ماست شاه عباسی که همان دوغی است که در جلوی در است و به قیمت اعلام شده به فروش می رود و ماستی هم پشت دکان داریم که ماستی سفت و آب رفته است و قیمتش بالاتر از قیمت اعلام شده است. حالا از کدام می خواهی؟\r\nپادشاه دستور می دهد که ماست بند را وارونه از در دکان آویزان کنند و کمرش را محکم ببندند و تمام ماست های آب بسته را در پاچه های شلوارش بریزند و بعد پاچه هایش را محکم ببندند و آن قدر در آن حالت بماند تا تمام آب ماست ها کشیده شود.\r\nبعد از این حکم تمام ماست بند ها از ترس شاه ماست های خود را در کیسه کردند و مقابل در دکان آویختند.\r\nاز آن پس هر کسی که کاری را از روی ترس و اجبار انجام می دهد می گویند که: فلانی ماستش را کیسه کرده است.\r\n"},{"id":1717,"category_id":10,"category_code":"s10","source_id":279,"title":"دعای کوروش کبیر","content":"روزی بزرگان ایرانی و مریدان زرتشتی از کوروش بزرگ خواستند که برای ایران زمین دعای خیر کند وایشان بعد از ایستادن در کنار اتش مقدس اینگونه دعا کردن:\r\nخداوندا اهورا مزدا ای بزرگ آفریننده , آفریننده این سرزمین\r\nبزرگ،سرزمینم ومردمم راازدروغ و دروغگویی به دور بدار\r\nبعد از اتمام دعا عده ای در فکرفرو رفتند واز شاه ایران پرسیدند که چرا این گونه دعانمودید؟فرمودند:چه باید می گفتم؟ یکی جواب داد :برای خشکسالی دعا مینمودید؟\r\nکوروش بزرگ فرمودند: برای جلو گیری از خوشکسالی \r\nانبارهای اذوقه وغلات می سازیم.\r\nدیگری اینگونه سوال نمود: برای جلوگیری از هجوم بیگانگان دعا می کردید ؟\r\nایشان جواب دادند: قوای نظامی را قوی میسازیم واز مرزها دفاع می کنیم\r\nگفتند:برای جلوگیری از سیلهای خروشان دعا می کردید ؟\r\nپاسخ دادند: نیرو بسیج میکنیم وسدهایی برای جلوگیری از هجوم سیل می سازیم\r\nو همینگونه سوال کردندوبه همین ترتیب جواب شنیدند\r\nتا این که یکی پرسید: شاها منظور شما از این گونه دعا چه بود؟\r\nوکوروش تبسمی نمودند واین گونه جواب دادند: \r\n\r\nمن برای هر سوال شما جوابی قانع کننده آوردم ولی اگر روزی یکی از شما نزد من آید و دروغی گوید که به ضرر سرزمینم باشد من چگونه از آن باخبر گردم واقدام نمایم؟ پس بیاییم از کسانی شویم که به راست گویی روی آورند ودروغ را از سرزمینمان دور سازیم...که هر عمل زشتی صورت گیرد باعث اولین آن دروغ است.\r\n"},{"id":1718,"category_id":10,"category_code":"s10","source_id":280,"title":"بانو ام رستم","content":"شیرین\" ملقب \"ام رستم\" دختر رستم بن شروین از سپهبدان خانان باوند در مازندران و همسر فخرالدوله دیلمی(387ق. ـ 366ق.) که پس از مرگ همسر به پادشاهی رسید او اولین پادشاه زن ایرانی پس از ورود اسلام بود. او بر مازندران و گیلان ، ری ، همدان و اصفهان حکم می راند. \r\nبه او خبر دادند سواری از سوی محمود غزنوی آمده است. \r\nسلطان محمود در نامه ی خود نوشته بود : باید خطبه و سکه به نام من کنی و خراج فرستی والا جنگ را آماده باشی. \r\nام رستم ، به پیک محمود گفت : اگر خواست سرور شما را نپذیرم چه خواهد شد ؟ پیک گفت آنوقت محمود غزنوی سرزمین شما را براستی از آن خود خواهد کرد. \r\nام رستم به پیک گفت : که پاسخ مرا همین گونه که می گویم به سرورتان بگویید : در عهد شوهرم همیشه می ترسیدم که محمود با سپاهش بیاید و کشور ما را نابود کند ولی امروز ترسم فرو ریخته است برای اینکه می بینم شخصی مانند محمود غزنوی که می گویند یک سلطانی باهوش و جوانمرد است برروی زنی شمشیر می کشد به سرورتان بگویید اگر میهنم مورد یورش قرار گیرد با شمشیر از او پذیرایی خواهم نمود اگر محمود را شکست دهم تاریخ خواهد نوشت که محمود غزنوی را زن جنگاور کشت و اگر کشته شوم باز تاریخ یک سخن خواهد گفت محمود غزنوی زنی را کشت. \r\nپاسخ هوشمندانه بانو ام رستم ، سبب شد که محمود تا پایان زندگی خویش از لشکرکشی به ری خودداری کند . \r\n"},{"id":1719,"category_id":10,"category_code":"s10","source_id":281,"title":"جهان پهلوان تختی","content":"يكى از بهترين و قابل توجه‌ترين كشتى‌هاى «غلامرضا تختى» با «پتكوف سيراكف» قهرمان نامدار بلغارستانى بود. هر دو به دور نهايى رسيده بودند. شگرد سيراكف، فن «بارانداز» سريع و بسيار فنى بود. كشتى كه شروع شد، تختى يك‌بار «زير» گرفت و سيراكف را «خاك» كرد و پاى او را در «سگك» خود گير انداخت. سيراكف روى سگك مقاومت كرد و كشتى «سرپا» اعلام شد... \r\nغلامرضا زير گرفت و او را خاك كرد و باز هم پاى او را در سگك خود، تحت فشار قرار داد. دقيقه سوم كشتى بود. فشار سگك موجب ناراحتى شديد پاى سيراكف شد. او با دست به پايش اشاره كرد. تختى كه متوجه ناراحتى او شده بود، سيراكف را رها كرد و از جا بلند شد. فرياد اعتراض تماشاچيان بلند شد كه چرا اين كار را كردى؟ \r\nتختى ايستاده بود و سرش پايين؛ او در برابر همه اين فريادها سكوت كرده بود. سيراكف كه اين عمل جوانمردانه را از حريف خود ديد، منتظر داور نشد و خودش دست تختى را به عنوان برنده بلند كرد. \r\nزنده‌باد تختى، مرام و مردانگى بى‌نظيرش\r\n"},{"id":1720,"category_id":10,"category_code":"s10","source_id":282,"title":"ثروت کوروش","content":"زمانی به کوروش بزرگ گفتند: چرا از غنیمت های جنگی چیزی را برای خود بر نمیداری و همه را به سربازانت می بخشی؟ کوروش گفت: اگر غنیمت های جنگی را نمیبخشیدیم الان دارایی من چقدر بود؟ عددی را با معیار آن زمان گفتند. کوروش یکی از سربازانش را صدا زد و گفت: برو به مردم بگو کوروش برای امری به مقداری پول و طلا نیاز دارد. سرباز در بین مردم جار زد و سخن کوروش را به گوششان رسانید. مردم هرچه در توان داشتند برای کوروش فرستادند. وقتی که مالهای گرد آوری شده را حساب کردند،از آنچه تخمین زده بودند بسیار بیشتر بود. کوروش رو به آنان کرده و گفت: ثروت من اینجاست. اگر آنها را پیش خود نگه میداشتم، همیشه باید نگران آنها می بودم .زمانی که ثروت در اختیار توست و مردم از آن بی بهره اند مثل این می ماند که تو نگهبان پولهایی که مبادا کسی آن را ببرد."},{"id":1721,"category_id":10,"category_code":"s10","source_id":283,"title":"غرور عابد","content":"روزی حضرت عیسی از صحرایی می‌گذشت. \r\nدر راه، به عبادت‌گاه عابدی رسید و با او مشغول سخن گفتن شد.\r\nدر این هنگام، جوانی که به کارهای زشت و ناروا مشهور بود، از آن جا می‌گذشت. وقتی چشمش به حضرت عیسی و مرد عابد افتاد، پایش سست شد و از رفتن باز ماند. همان جا ایستاد و گفت:\r\n«خدایا! من از کردار زشت خویش شرمنده‌ام، اکنون اگر پیامبرت مرا ببیند و سرزنش کند، چه کنم؟! خدایا! عذرم را بپذیر و آبرویم را مبر!»\r\nچشم عابد که بر جوان افتاد، سر به سوی آسمان بلند کرد و گفت: «خدایا! مرا در قیامت با این جوان گناه‌کار محشور مکن!»\r\nدر این هنگام خدای برترین به پیامبرش وحی فرمود که: «به این عابد بگو ما دعایت را مستجاب کردیم و تو را با آن جوان محشور نمی‌کنیم. چه، او به دلیل توبه و پشیمانی، اهل بهشت است و تو، به علِّت غرور و خودبینی، اهل دوزخ!»\r\n"},{"id":1722,"category_id":10,"category_code":"s10","source_id":284,"title":"مرد آخربین","content":"اردشیر بابکان، شاه ساسانی با همسر خود به خوبی رفتار نمیکرد.رفتار وی با همسرش به طوری شده بود که ، زن قصد کشتن اردشیر را کرد. روزی غذایی برای شاه آماده و به سم آغشته کرد و آن را نزد وی برد.در راه زن مراقب بود تا غذا بر زمین نریزد و نقشه اش نقشه بر آب نشود.اما زمانی که چشمانش به چشمان اردشیرافتاد ترسید و سینی غذا از دستش افتاد و غذاها برزمین ریخت.در همان زمان عقابی بر زمین نشست و گوشتهای غذا را خورد.پس از لحظه کوتاهی عقاب نقش بر زمین شد و مرد.شاه فهمید که غذا سمی بوه است ، سپس رییس موبدان را فراخواند و خشم فراوان گفت:این زن را به دست جلاد بسپار تا خون او را برزمین بریزد.موبد که میدانست اگر حرفی بزند اردشیر بیشترعصبانی میشود گفت:چشم قربان.سپس به همراه زن از آنجا خارج شد.در راه زن به موبد گفت:من باردار هستم.موبدبا اینکه از قبل نقشه کشیده بود تا زن را نجات دهد بیشتر به این موضوع اندیشید و زن را به روستایی دوردست برد و هر چند وقت به دیداروی میرفت.یک روز که به منزل آنها رفت دید که نوزادی در گهواره خوابیده است.بله آن نوزاد فرزند اردشیربابکان بود.موبد کمی فکر کرد و گفت:باید نام این کودک را شاپور بگذاریم. سالها گذشت و شاپور بزرگ شد و به سنی رسید که زمان یاد گرفتن خواندن و نوشتن بود.موبد به شاپور راه و روش زندگی و دینداری را آموزش داد.بالاخره شاپور جوانی دانا و جنگجو شد.روزی اردشیر درقصر مشغول قدم زدن بود و بسیار ناراحت و مغموم بود.موبد آمد و گفت:شاهنشاها چراناراحت هستید؟ شاه گفت:حس میکنم زمان مرگ من رسیده است و من فرزندی ندارم که جانشین من شود.موبد لبخندی زد و گفت: شما فرزندی دارید به نام شاپور.شاه باتعجت و خوشحالی گفت: چگونه؟؟مگر دیوانه شده ای که این حرف را میزنی؟؟!! موبد گفت:خیر قربان، زمانی که شما امر کردید همسرتان را بکشم ، من فهمیدم که وی باردار است ولی نتوانستم آن را به شما بگویم.اردشیر که بسار خوشنود شده بود مود را در آغوش گرفت و همراه وی به دیدارهمسر و فرزندش رفت.شاه همسرش را بخشید و همراه آنها به کاخ سلطنتی بازگشت.اردشیر از موبد قدردانی نمودو او را از ثروت بی نیاز کرد."},{"id":1723,"category_id":10,"category_code":"s10","source_id":285,"title":"بودا و زن هرزه","content":"بودا به دهی سفر کرد .زنی که مجذوب سخنان او شده بود از بودا خواست تا مهمان وی باشد.بودا پذیرفت و مهیای رفتن به خانه‌ی زن شد .کدخدای دهکده هراسان خود را به بودا رسانید و گفت :«این زن، هرزه است به خانه‌ی او نروید»بودا به کدخدا گفت :«یکی از دستانت را به من بده»کدخدا تعجب کرد و یکی از دستانش را در دستان بودا گذاشت .آنگاه بودا گفت :«حالا کف بزن» کدخدا بیشتر تعجب کرد و گفت: « هیچ کس نمی‌تواند با یک دست کف بزند»بودا لبخندی زد و پاسخ داد :هیچ زنی نیز نمی تواند به تنهایی بد و هرزه باشد، مگر این که مردان دهکده نیز هرزه باشند .بنابراین مردان و پول‌هایشان است که از این زن، زنی هرزه ساخته‌اند .برو و به جای نگرانی برای من نگران خودت و دیگر مردان دهکده ات باش..."},{"id":1724,"category_id":10,"category_code":"s10","source_id":286,"title":"داستان تاریخی اعدام بابک خرمدین ","content":"روز قبل از اعدام،خلیفه با بزرگان دربارش مشورت کرد که چگونه بابک را درشهر بگرداند و به مردم نشان بدهد تا همه بتوانند وی را ببینند.\r\n\r\nبنا بر نظر یکی از درباریان قرار برآن شد که وی را سوار بر پیلی کرده در شهر بگردانند.\r\nپیل را با حنا رنگ کردند و نقش و نگار برآن زدند؛ و بابک را در رختی زنانه و بسیارزننده و تحقیرکننده برآن نشاندند و درشهر به گردش درآوردند.\r\nپس ازآن مراسم اعدام بابک با سروصدای بسیار زیاد با حضور شخص خلیفه برفراز سکوی مخصوصی که برای این کار دربیرون شهر تهیه شده بود، برگزار شد.\r\nبرای آنکه همه‌ی مردم بشنوند ....\r\nکه اکنون دژخیم به بابک نزدیک میشود و دقایقی دیگر بابک اعدام خواهد شد، چندین جارچی در اطراف و اکناف با صدای بلند بانگ میزدند نَوَد نَوَد این اسمِ دژخیم بود و همه اورا میشناختند .\r\nابن الجوزی مینویسد که وقتی بابک را برای اعدام بردند خلیفه درکنارش نشست و به او گفت: تو که اینهمه استواری نشان میدادی اکنون خواهیم دید که طاقتت دربرابر مرگ چند است!\r\nبابک گفت: خواهید دید.\r\nچون یک دست بابک را به شمشیر زدند، بابک با خونی که از بازویش فوران میکرد صورتش را رنگین کرد. خلیفه ازاوپرسید: چرا چنین کردی؟ بابک گفت: وقتی دستهایم را قطع کنند خونهای بدنم خارج میشود و چهره‌ام زرد میشود، و تو خواهی پنداشت که رنگ رویم از ترسِ مرگ زرد شده است.. چهره‌ام را خونین کردم تا زردیش دیده نشود .\r\nبه این ترتیب دستها و پاهای بابک را بریدند . چون بابک برزمین درغلتید، خلیفه دستور داد شکمش را بدرد... پس از ساعاتی که این حالت بربابک گذشت، دستور داد سرش را از تن جدا کند.\r\nپس ازآن چوبه‌ی داری در میدان شهر سامرا افراشتند و لاشه‌ی بابک را بردار زدند، و سرش را خلیفه به خراسان فرستاد .\r\n\r\nآخرین گفتار بابک چنین بوده است :\r\nتو ای معتصم خیال مکن که با کشتن من فریاد استقلال طلبی ایرانیان را خاموش خواهی کرد من لرزه ای بر ارکان حکومت عرب انداخته ام که دیر یا زود آن را سرنگون خواهد نمود ..\r\nتو اکنون که مرا تکه تکه میکنی هزاران بابک در شمال و شرق و غرب ایران ظهور خواهد کرد و قدرت پوشالی شما پاسداران جهل و ستم را از میان بر خواهد داشت !\r\nاین را بدان که ایرانی هرگز زیر بار زور و ستم نخواهد رفت و سلطه بیگانگان را تحمل نخواهد کرد من درسی به جوانان ایران داده ام که هرگز آنرا فراموش نخواهند کرد .\r\n\r\nمن مردانگی و درس مبارزه را به جوانان ایران آموختم و هم اکنون که جلاد تو شمشیرش را برای بریدن دست و پاهای من تیز میکند صدها ایرانی با خون بجوش آمده آماده طغیان هستند مازیار هنوز مبارزه میکند و صدها بابک و مازیار دیگر آماده اند تا مردانه برخیزند و میهن گرامی را از دست متجاوزان و یوغ اعراب بدوی و مردم فریب برهانند .\r\nاما تو ای افشین . . . در انتظار\r\nو بدینسان نخست دست چپ بابک بریده شد و سپس دست راست او و بعد پاهایش و در نهایت دو خنجر در میان دنده هایش فرو رفت و آخرین سخنی که بابک با فریادی بلند بر زبان آورد این بود :\r\n\" پاینده ایران \"\r\nروز اعدام بابک خرمدین و تکه تکه کردن بدنش در تاریخ 2 صفر سال 223 هجری قمری انجام گرفت که مسعودی در کتاب مشهور مروج الذهب این تاریخ را برای ایرانیان بسیار مهم دانسته است اعدام بابک چنان واقعه‌ی مهمی تلقی شد که محل اعدامش تا چند قرن دیگر بنام خشبه‌ی بابک یعنی چوبه‌ی دار بابک در شهرِ سامرا که در زمان اعدام بابک پایتخت دولت عباسی بود شهرت همگانی داشت و یکی از نقاط مهم و دیدنی شهر تلقی میشد\r\nبرادر بابک یعنی آذین را نیز خلیفه به بغداد فرستاد و به نایبش در بغداد دستور نوشت که اورا مثل بابک اعدام کند.\r\nطبری مینویسد که وقتی دژخیمْ دستها و پاهای برادر بابک را می‌بُرید، او نه واکنشی از خودش بروز میداد و نه فریادی برمی‌آورد. جسد این مرد را نیز در بغداد بردار کردند.\r\nمعتصم خلیفه عباسی، چنانکه نظام الملک در سیاست نامه خود می نویسد به شکرانه آنکه سه سردار مبارز ایرانی، بابک ، مازیار وافشین رو که هر سه آنها به حیله اسیر شده بودند به دار آویخته بود،مجلس ضیافتی ترتیب داده بود که در طول آن 3 بار پیاپی مجلس را ترک گفت و هربار ساعتی بعد برمی گشت.\r\n\r\nدر بار سوم در پاسخ حاضران که جویای علت این غیبت ها شده بودند فاش کرد که در هر بار به یکی از دختران پدر کشته این سه سردار تجاوز کرده است، و حاضران با او از این بابت به نماز ایستادند و خداوند را شکر گفتند. (تولدی دیگر-شجاع الدین شفا).\r\n"},{"id":1725,"category_id":10,"category_code":"s10","source_id":287,"title":"آش نخورده","content":"\r\nروزی مردی به خانه یکی از آشنایان خود رفت. صاحبخانه برای او کاسه ای آش داغ آورد. میهمان هنوز دست به کاسه آش نبرده بود که دندانش به شدت درد گرفت. او دست روی دهان خود گذاشته بود و از درد به خود می پیچید.صاحبخانه به خیال آن که او از آن آش داغ خورده و دهانش سوخته است، گفت: بهتر بود صبر می کردی تا آش کمی سرد می شد و دهانت نمی سوخت. میهمان که هم از درد دندان رنج می برد و هم از حرف صاحبخانه شرمگین شده بود، گفت: بله، آش نخورده و دهان سوخته!!این مثل در مورد کسی به کار می رود که گناهی نکرده و کار بدی انجام نداده است، اما مردم بی دلیل او را گناهکار می دانند.\r\n"},{"id":1726,"category_id":10,"category_code":"s10","source_id":288,"title":"کارت ویزیت","content":"روزی یکی از اشخاص از خود راضی در غیاب \"ولتر\" نویسنده و فیلسوف شهیر فرانسوی به دیدنش رفته بود. بر خلاف انتظار، دید که وضع اتاق او بسیار درهم و آشفته بوده و گرد و خاک زیادی روی میز تحریرش نشسته است.\r\nمرد ازخود راضی از فرط ناراحتی با انگشت خود روی همان میز گرد آلود نوشت :«خر » و اتاق را ترک کرد . فردای آن روز تصادفا ولتر را در خیابان دید و گفت:دیروز خدمت رسیدم تشریف نداشتید.\r\nولتر با نگاهی به او گفت: بله، کارت ویزیت شما را روی میز تحریر دیدم!\r\n"},{"id":1727,"category_id":10,"category_code":"s10","source_id":289,"title":"دیر خانه آمدن شوهر","content":"\r\nﺷﻮﻫﺮﻩﺷﺐ ﺩﻳﺮ ﻣﻴﺎﺩﺧﻮﻧﻪ\r\nزنش دادو بیداد میکنه \r\n    ﻣﻴﮕﻪ ﺍﮔﻪ ﺩﻭ ﺭﻭﺯ ﻣﻨﻮ ﻧﺒﻴﻨﻰ ﭼﻪ ﺣﺴﻰ ﺑﻬﺖ ﺩﺳﺖ ﻣﻴﺪﻩ ؟\r\n  ﺷﻮﻫﺮﻩ ﺑﺎ ﺧﻮﺷﺤﺎﻟﻰ ﻣﻴﮕﻪ ﺧﻴﻠﻰ ﻋﺎﻟﻰ ﻣﻴﺸﻪ\r\n ! ...اونوقت بود که شوهره دیگه زنش رو ندید\r\n ﯾﮏ ﺭﻭﺯ ﮔﺬﺷﺖ ﺷﻮﻫﺮﻩ ﺯﻧﺸﻮ ﻧﺪﯾﺪ\r\n  ﺩﻭ ﺭﻭﺯ ﮔﺬﺷﺖ ﺷﻮﻫﺮﻩ ﺯﻧﺸﻮ ﻧﺪﯾﺪ\r\n   ﺭﻭﺯ ﺳﻮﻡ ﻫﻢ ﮔﺬﺷﺖ ﺑﺎﺯﻡ ﺷﻮﻫﺮﻩ ﺯﻧﺸﻮ ﻧﺪﯾﺩ ...\r\n    .\r\n    .\r\n    .\r\n    ﺧﻼﺻﻪ ﺭﻭﺯﻩ ﭼﻬﺎﺭﻡ ﻭﺭﻡ ﭼﺸﻤﻪ ﺷﻮﻫﺮﻩ ﺑﻬﺘﺮ ﺷﺪ ﻭ ﺗﻮﻧﺴﺖ\r\n    ﺍﺯ ﮔﻮﺷﻪ ﭼﺸﻢ ﺯﻧﺸﻮ ﺑﺒﯿﻨﻪ\r\n"},{"id":1728,"category_id":10,"category_code":"s10","source_id":290,"title":"پند دزد","content":"گويند ابوحامد محمد غزالى آن چه را فرا مى گرفت در دفترها مى نوشت. وقتى (زمانی) با كاروانى در سفر بود و نوشته ها را يك جا بسته با خود برداشت ... در راه گرفتار راهزنان شدند.غزالى رو به آنان كرد و به التماس گفت:اين بسته را از من نگيريد، ديگر هر چه دارم از آن شما.دزدان را طمع زيادت شد، آن را گشودند و جز دفترهاى نوشته چيزى نيافتند.دزدى پرسيد كه اين ها چيست؟چون غزالى وى را به آن ها آگاهى داد، دزد راهزن گفت:علمى را كه دزد ببرد، به چه كار آيد!اين سخن دزد، در غزالى اثرى عميق گذاشت و گفت:پندى به از اين از كسى نشنيدم و ديگر در پى آن شد كه علم را در دفتر جان بنگارد."},{"id":1729,"category_id":10,"category_code":"s10","source_id":291,"title":"جاده ی قدیمی","content":"دوستم تعریف میکرد که یک شب موقع برگشتن از ده پدری تو شمال طرف اردبیل، جای اینکه از جاده اصلی بیاد، یاد باباش افتاده که می گفت جاده قدیمی با صفا تره و از وسط جنگل رد میشه!\r\nاینطوری تعریف میکنه: من احمق حرف بابام رو باور کردم و پیچیدم تو خاکی 20کیلومتر از جاده دور شده بودم که یهو ماشینم خاموش شد و هرکاری کردم\r\nروشن نمیشد.\r\nوسط جنگل، داره شب میشه، نم بارون هم گرفت.\r\nاومدم بیرون یکمی با موتور ور رفتم دیدم نه میبینم، نه از موتور ماشین سر در میارم!\r\nراه افتادم تو دل جنگل، راست جاده خاکی رو کرفتم و مسیرم رو ادامه دادم.\r\nدیگه بارون حسابی تند شده بود.\r\nبا یه صدایی برگشتم، دیدم یه ماشین خیلی آرام وبی صدا بغل دستم وایساد.\r\nمن هم بی معطلی پریدم توش. \r\nاینقدر خیس شده بودم که به فکر اینکه توی ماشینو نیگا کنم هم نبودم.\r\nوقتی روی صندلی عقب جا گرفتم، سرم رو آوردم بالا واسه تشکر دیدم هیشکی پشت فرمون و صندلی جلو نیست\r\nداشتم به خودم میومدم که ماشین یهو همونطور بی صدا راه افتاد هنوز خودم رو جفت و جور نکرده بودم که تو یه نور رعدو برق دیدم یه پیچ جلومونه\r\nتمام تنم یخ کرده بود.\r\nنمیتونستم حتی جیغ بکشم ماشین هم همینطور داشت میرفت طرف دره\r\nتو لحظه های آخر خودم رو به خدا اینقدر نزدیک دیدم که بابا بزرگ خدا بیامرزم اومد جلو چشمم\r\nتو لحظه های آخر، یه دست از بیرون پنجره، اومد تو و فرمون رو چرخوند به سمت جاده. نفهمیدم چه مدت گذشت تا به خودم اومدم\r\nولی هر دفعه که ماشین به سمت دره یا کوه میرفت، یه دست میومد و فرمون رو میپیچوند\r\nاز دور یه نوری رو دیدم و حتی یک ثانیه هم تردید به خودم راه ندادم\r\nدر رو باز کردم و خودم رو انداختم بیرون\r\nاینقدر تند میدویدم که هوا کم آورده بودم\r\nدویدم به سمت آبادی که نور ازش میومد\r\nرفتم توی قهوه خونه و ولو شدم رو زمین\r\nبعد از اینکه به هوش اومدم جریان رو تعریف کردم\r\nوقتی تموم شد، تا چند ثانیه همه ساکت بودند یهو در قهوه خونه باز شد و دو نفر خیس اومدن تو\r\nیکیشون داد زد:\r\nعلی نیگا! این همون احمقیه که وقتی ما داشتیم ماشینو هل میدادیم سوار شده بود.\r\n"},{"id":1730,"category_id":10,"category_code":"s10","source_id":292,"title":"خانه ی وحشت","content":"هیچ کس نمی دانست میلت چنی اهل کجا بود ولی در دهه هزار و هشتصد و پنجاه این مرد که صاحب مهمانسرایی در منطقه بود، اسرارآمیزترین مرد لانکاستر کانتی شد . بعضی چنی را که به رک گویی شهره بود مجسمه شیطان می دانستند \r\nوقتی مردم جسد او را دیدند که برابر دادگاه شهر به چوب بستی آویزان بود و تاب می خورد زیاد تعجب نکردند . بعد از اینکه چنی به اتهام دزدیدن برده (( دکتر کرافورد )) محکوم شد، خیلی ها فکر می کردند او به مکافات عملش رسیده است \r\nچنی یک برده داشت که هر از گاهی او را به یک مسافر می فروخت.چند روز بعد برده از موقعیتی استفاده می کرد و از پیش صاحب تازه می گریخت و دوباره به مهمانخانه بر می گشت تا در یک فرصت مناسب چنی دوباره او را به مسافر ساده لودح دیگری بفروشد . ولی همه مسافران خوش شانس نبودند . هیچ کس تمایلی نداشت که در آن مهمانخانه بماند ولی چاره دیگری نبود . اما برای بعضی از مسافران، آن مهمانخانه آخرین محل استراحت به شمار می رفت. \r\n\r\nمدتی بعد خانواده های آنها به دنبال همسر یا پسر گمشده شان به آن مهمانخانه خلوت می رفتند ولی هیچ وقت نتیجه ای نمی گرفتند. \r\nدر طول سال ها مردم بسیاری که از حوالی مهمانخانه عبور می کردند ، پیکرهای مه آلودی را می دیدند که در میان درختان اطراف مهمانخانه سرگردان بودند. \r\nاز اهالی آن منطقه کمتر کسی جرات می کرد به آن مهمانخانه برود . چنی همه چیز را انکار میکرد و مدرکی به دست نمی داد .ولی سالها بعد معما ها حل شد . یک شرکت ساختمانی به آن منطقه رفت و زمین را حفاری کرد در آن هنگام بود که چندین اسکلت از زیر خاک بیرون آمد که همگی به قتل رسیده بودند . مردم نام آن مهمانخانه را (( خانه وحشت میلت چنی )) گذاشتند . این خانه تا اوایل دهه 1970 در آن محل باقی ماند . ولی دیگر تبدیل به خانه متروکه درست شبیه به خانه ارواح شده بود . خانه ای که محل زندگی ارواح مسافران بی گناه بود.\r\n"},{"id":1731,"category_id":10,"category_code":"s10","source_id":293,"title":"دعا","content":"کشتی در طوفان شکست و غرق شد . فقط دو مرد توانستند به سوی جزیره ی کوچک بی آب و علفی شنا کنند و نجات یابند.\r\nدو نجات یافته دیدند هیچ نمی توانند بکنند، با خود گفتند بهتر است از خدا کمک بخواهیم\r\nبنابراین دست به دعا شدند و برای این که ببینند دعای کدام بهتر مستجاب می شود به گوشه ای از جزیره رفتند...\r\nنخست، از خدا غذا خواستند .فردا مرد اول، درختی یافت و میوه ای بر آن، آن را خورد . اما مرد دوم چیزی برای خوردن نداشت.\r\nهفته بعد، مرد اول از خدا همسر و همدم خواست، فردا کشتی دیگری غرق شد، زنی نجات یافت وبه مرد رسید. در سمت دیگر، مرد دوم هیچ کس را نداشت.\r\nمرد اول از خدا خانه، لباس و غذای بیشتری خواست، فردا، به صورتی معجزه آسا، تمام چیزهایی که خواسته بود به او رسید. مرد دوم هنوز هیچ نداشت.\r\nدست آخر، مرد اول از خدا کشتی خواست تا او همسرش را با خود ببرد . فردا کشتی ای آمد و درسمت او لنگر انداخت، مرد خواست به همراه همسرش از جزیره برود و مرد دوم را همانجا رها کند...!\r\nپیش خود گفت، مرد دیگر حتما شایستگی نعمت های الهی را ندارد، چرا که درخواستهای او پاسخ داده نشد، پس همینجا بماند بهتر است!\r\nزمان حرکت کشتی، ندایی از او پرسید:«چرا همسفر خود را در جزیره رها می کنی؟» مرد پاسخ داد:«این همه نعمت هایی که به دست آورده ام همه مال خودم است و خودم درخواست کرده ام.درخواست های همسفرم که پذیرفته نشد.پس چه بهتر که همینجا بماند» آن ندا گفت:اشتباه می کنی! تو مدیون او هستی..هنگامی که تنها خواسته او را اجابت کردم، این نعمات به تو رسید... \r\nمرد با تعجب پرسید: مگر او چه خواست که من باید مدیونش باشم؟ \r\nو آن ندا پاسخ داد:\"از من خواست که تمام دعاهای تو را مستجاب کنم...!\" \r\nنکته اخلاقی:شاید داشته هایمان را مدیون کسانی باشیم که برای خود هیچ نمی خواستند و \"فقط برای ما\" دعا می کردند...ممکن است همه موفقیت و ثروت و هرچیز دیگر که داریم را مدیون آن دو فرشته ای باشیم که ما را بزرگ کردند..بدون هیچ توقعی!\r\n"},{"id":1732,"category_id":10,"category_code":"s10","source_id":294,"title":"لشکرکشی نادرشاه","content":"می گویند...زمانی که نادر شاه افشار عزم تسخیر هندوستان داشته درراه کودکی را دید که به مکتب می‌رفت.\r\nاز او پرسید: پسر جان چه می‌خوانی؟\r\n. قرآن\r\nاز کجای قرآن؟\r\n... انا فتحنا لک فتحا مبینا\r\nنادر از پاسخ او بسیار خرسند شد و از شنیدن آیه فتح فال پیروزی زد.\r\nسپس یک سکه زر به پسر داد اما پسر از گرفتن آن ابا کرد.\r\nنادر گفت: چرا نمی گیری؟\r\nگفت: مادرم مرا می‌زند می‌گوید تو این پول را دزدیده ای...\r\nنادر گفت: به او بگو نادر داده است.\r\nپسر گفت: مادرم باور نمی‌کند.\r\nمی‌گوید: نادر مردی سخاوتمند است. او اگر به تو پول می‌داد یک سکه نمی‌داد. زیاد می‌داد...!\r\nحرف او بر دل نادر نشست. یک مشت پول زر در دامن او ریخت.\r\nاز قضا چنانچه مشهور تاریخ است در آن سفر بر حریف خویش محمد شاه گورکانی پیروز شد...\r\n"},{"id":1733,"category_id":10,"category_code":"s10","source_id":295,"title":"مسافر مسجد","content":"مردی صبح زود از خواب بیدار شد تا نمازش را در مسجد بخواند. لباس پوشید و راهی خانه خدا شد. در راه به مسجد، مرد زمین خورد و لباسهایش کثیف شد. او بلند شد، خودش را پاک کرد و به خانه برگشت. \r\nمرد لباسهایش را عوض کرد و دوباره راهی خانه خدا شد. در راه به مسجد و در همان نقطه مجدداً زمین خورد! \r\nاو دوباره بلند شد، خودش را پاک کرد و به خانه برگشت. یک بار دیگر لباسهایش را عوض کرد و راهی خانه خدا شد. \r\nدر راه به مسجد، با مردی که چراغ در دست داشت برخورد کرد و نامش را پرسید. مرد پاسخ داد: (( من دیدم شما در راه به مسجد دو بار به زمین افتادید.))، از این رو چراغ آوردم تا بتوانم راهتان را روشن کنم. مرد اول از او بطور فراوان تشکر می کند و هر دو راهشان را به طرف مسجد ادامه می دهند. \r\nهمین که به مسجد رسیدند، مرد اول از مرد چراغ بدست در خواست می کند تا به مسجد وارد شود و با او نماز بخواند. مرد دوم از رفتن به داخل مسجد خودداری می کند. \r\nمرد اول درخواستش را دوبار دیگر تکرار می کند و مجدداً همان جواب را می شنود. مرد اول سوال می کند که چرا او نمی خواهد وارد مسجد شود و نماز بخواند؟؟ \r\nمرد دوم پاسخ داد: ((من شیطان هستم.)) مرد اول با شنیدن این جواب جا خورد. شیطان در ادامه توضیح می دهد:\r\nمن شما را در راه به مسجد دیدم و این من بودم که باعث زمین خوردن شما شدم. وقتی شما به خانه رفتید، خودتان را تمیز کردید و به راهمان به مسجد برگشتید، خدا همه گناهان شما را بخشید. من برای بار دوم باعث زمین خوردن شما شدم و حتی آن هم شما را تشویق به ماندن در خانه نکرد، بلکه بیشتر به راه مسجد برگشتید. به خاطر آن، خدا همه گناهان افراد خانواده ات را بخشید... \r\nمن ترسیدم که اگر یک بار دیگر باعث زمین خوردن شما بشوم، آنگاه خدا گناهان افراد دهکده تان را خواهد بخشید. بنا براین، من سالم رسیدن شما را به خانه خدا (مسجد) مطمئن ساختم. \r\n: نتیجه اخلاقی داستان \r\nکار خیری را که قصد دارید انجام دهید به تعویق نیاندازید. زیرا هرگز نمی دانید چقدر اجر و پاداش ممکن است ازمواجهه با سختی های در حین تلاش به انجام کار خیر دریافت کنید. پارسائی شما می تواند خانواده و قوم تان را بطور کلی نجات بخشد...\r\n"},{"id":1734,"category_id":10,"category_code":"s10","source_id":296,"title":"کار خوب","content":"آدمی بد کار به هنگام مرگ فرشته ای را دید که نزدیک در دروازه های جهنم ایستاده بود. \r\nفرشته ای به او گفت: یک کار خوب در زندگیت انجام داده ای و همان به تو کمک خواهد کرد. خوب فکر کن چی بوده! مرد به یاد آورد که یک بار هنگامی که در جنگل مشغول رفتن بود عنکبوتی را سر راهش دید و برای آنکه آن را زیر پا له نکند مسیرش را تغییر داد. فرشته لبخند زد و تار عنکبوتی از آسمان پایین آمد و با خود مرد را به بهشت برد. عده ای از جهنمی ها نیز از فرصت استفاده کرده تا از تار بالا بیایند. اما مرد آنها را به پایین هل داد مبادا که تار پاره شود. در این لحظه تار پاره شد و مرد دوباره به جهنم سقوط کرد. \r\nفرشته گفت: افسوس! تنها به فکر خود بودن همان یک کار خوبی را که باعث نجات تو بود ضایع کرد.\r\n"},{"id":1735,"category_id":10,"category_code":"s10","source_id":297,"title":"کاغذ کادو","content":"در شهری دور افتاده، خانواده فقیری زندگی می‌کرد. پدر خانواده از اینکه دختر ۵ساله‌شان مقداری پول برای خرید کاغذ کادوی طلایی رنگ مصرف کرده بود، ناراحت بود چون همان قدر پول هم به سختی به دست می‏آمد. دخترک با کاغذ کادو یک جعبه را بسته‌بندی کرده و آن را زیر درخت کریسمس گذاشته بود. \r\nصبح روز بعد، دخترک جعبه را نزد پدرش برد و گفت: بابا! این هدیه من است. پدر جعبه را از دختر خردسالش گرفت و آن را باز کرد. داخل جعبه خالی بود! پدر با عصبانیت فریاد زد: مگر نمی‌دانی وقتی به کسی هدیه می‌دهی باید داخل جعبه چیزی هم بگذاری؟ اشک از چشمان دخترک سرازیر شد و با اندوه گفت: باباجان! من پول نداشتم ولی در عوض هزار بوسه برایت داخل جعبه گذاشتم. چهره پدر از شرمندگی سرخ شد. دختر خردسالش را بغل و او را غرق بوسه کرد.\r\n"},{"id":1736,"category_id":10,"category_code":"s10","source_id":298,"title":"سگ بیمار","content":"سالها پيش مدتي را در جايي بيابان گونه بسربردم و عزيزي چهار ديواري خود را در آن بيابان در اختيار من قرار داد ... يك محوطه بزرگ با يك سرپناه و يك سگ. سگ پير و قوي هيكلي كه براي بودن در آن محيط خلوت و ناامن  دوست مناسبي به نظر مي رسيد... ما مدتي با هم بودیم و من بخشي از غذاي خود را با او سهيم مي شدم و او مرا از دزدان شب محافظت مي كرد تا روزي كه آن سگ بيمار شد.به دليل نامعلومي بدن او زخم بزرگي برداشت و هر روز عود كرد تا كرم برداشت. دامپزشك، درمان او را بي اثر دانست و گفت كه نگهداري او بسيار خطرناك است و بايد كشته شود!\r\nصاحب سگ نتوانست اين كار بكند. از من خواست كه او را از ملك بيرون كنم تا خود در بيابان بميرد و من او را بيرون كردم ! ابتدا مقاومت مي كرد ولي وقتي ديد اصرار دارم رفت و هيچ نشاني از خود باقي نگذاشت... \r\nهرگز او را نديدم. تا اينكه روزي برگشت از سوراخي مخفي وارد شده بود، اين راه اختصاصي او بود. بدون آن زخم وحشتناك. او زنده مانده بود و برخلاف همه قواعد علمي هيچ اثري از آن زخم باقي نمانده بود!!  \r\nنمي دانم چكار كرده بود و يا غذا از كجا تهيه كرده بود. اما فهميده بود كه چرا بايد آنجارا ترك مي كرده و اكنون كه ديگر بيمار و خطرناك نبود بازگشته بود در آن نزديكي چهارديواري ديگري بود كه نگهباني داشت و چند روز بعد از بازگشت سگ، آن نگهبان را ملاقات كردم و او چيزي به من گفت كه تا عمق وجودم را لرزاند:  \r\nاو گفت كه سگ در آن اوقاتي كه بيرون شده بود هر شب مي‌آمده پشت در و تا صبح نگهباني ميداده و صبح پيش از اينكه كسي متوجه حضورش بشود از آنجا مي رفته. هرشب ... ! من نتوانستم از سكوت آن بيابان چيزي بياموزم اما عشق و قدرشناسي آن سگ و بيكرانگي قلبش مرا در خود خرد كرد و فروريخت. او هميشه از اساتيد من خواهد بود!  \r\nاستاد من آن كسي است كه به من آموخت كه چگونه همه را استاد خويش ببينم...\r\n"},{"id":1737,"category_id":10,"category_code":"s10","source_id":299,"title":"حسرتهای مسافران برزخ","content":"یه پرستار استرالیایی بزرگ‌ترین حسرت‌های آدم‌های در حال مرگ رو جمع کرده و پنج حسرت رو که بین بیشتر آدم‌ها مشترک بوده منتشرکرده:  \r\nاولین حسرت: کاش جرات‌اش رو داشتم اون جوری زندگی می‌کردم که می‌خواستم٬ نه اون جوری که دیگران ازم توقع داشتن. \r\nحسرت دوم: کاش این قدر سخت کار نمی‌کردم. \r\nحسرت سوم: کاش شجاعت‌اش رو داشتم که احساسات‌ام رو به صدای بلند بگم. \r\nحسرت چهارم: کاش رابطه‌هام رو با دوستام حفظ می‌کردم \r\nحسرت پنجم: کاش شادتر می‌بودم.\r\n"},{"id":1738,"category_id":10,"category_code":"s10","source_id":300,"title":"شنوایی","content":"مردي متوجه شد که گوش همسرش سنگين شده و شنوايي اش کم شده است... \r\nبه نظرش رسيد که همسرش بايد سمعک بگذارد ولي نمي دانست اين موضوع را چگونه با او\r\nدرميان بگذارد.\r\nبه اين خاطر، نزد دکتر خانوادگي شان رفت و مشکل را با او درميان گذاشت.\r\nدکتر گفت: براي اينکه بتواني دقيقتر به من بگويي که ميزان ناشنوايي همسرت چقدر است\r\n، آزمايش ساده اي وجود دارد. اين کار را انجام بده و جوابش را به من بگو...\r\nابتدا در فاصله 4 متري او بايست و با صداي معمولي ، مطلبي را به او بگو. اگر\r\nنشنيد ، همين کار را در فاصله 3 متري تکرار کن. بعد در 2 متري و به همين ترتيب تا\r\nبالاخره جواب بدهد.\r\nآن شب همسر آن مرد در آشپزخانه سرگرم تهیه شام بود و خود او در اتاق پذيرايي\r\nنشسته بود. مرد به خودش گفت: الان فاصله ما حدود 4 متر است. بگذار امتحان کنم.\r\nسپس با صداي معمولي از همسرش پرسيد:\r\nعزيزم ، شام چي داريم؟ \r\n جوابي نشنيد بعد بلند شد و يک متر به جلوتر به سمت\r\nآشپزخانه رفت و همان سوال را دوباره پرسيد و باز هم جوابي نشنيد. بازهم جلوتر رفت و\r\nبه درب آشپزخانه رسيد. سوالش را تکرار کرد و بازهم جوابي نشنيد. اين بار جلوتر رفت\r\nو درست از پشت همسرش گفت: عزيزم شام چي داريم؟ \r\nو همسرش گفت:\r\n« مگه کري؟! » براي چهارمين بار ميگم: « خوراک مرغ »  \r\nچرا همیشه فکر میکنم اشکال از دیگرونه؟؟؟\r\n"},{"id":1739,"category_id":10,"category_code":"s10","source_id":301,"title":"پروانه","content":"پسرک كه سرش حسابی گرم بود،برگشت و دید یه پـروانه كوچیک اونجاست...!\r\nپروانه با شور و شوق گفت:میخوام باهات دوست بشم،لطفا پنجره رو باز كن.\r\nاما پسرک با اوقات تلخی جواب داد: نمیشه،تو یه پروانه هستی!\r\nپروانه خجالت زده سرش رو كج كرد و با صدای لرزون گفت: لطفا پنجـــــره رو باز كن،هـــــوا اینجـــا خیلی ســــرده!\r\nاون پسر باز هم قبول نكرد: برو از اینجا و منو راحت بذار!\r\nپروانه با غم زیاد از اونجا دور شد.\r\nفرداش پسرک از رفتارش پشیمون شد و پیش خودش گفت: برای اولین بار كسی خواست با من دوست بشه ولی من حرفشو گوش نكردم و پیش خودش فكر كرد كه \"ممكنه پــروانه برگرده و این بار با هم دوست میشیم\".مدتها كنار پنجره باز اتاقش نشست. پــــروانههای زیــــادی اومدن اما از پـــــروانه اون شب خبـــــری نشد.\r\nخسته از انتظار،پسرک پیش مرد دانا رفت و ماجرا رو براش تعریف كرد.\r\nمرد دانا بهش گفت: پسر عزیزم عمر پروانهها بیشتر از یک یا دو روز نیست!\r\nپسرک از اون روز دیگه همیشه یادش موند كه برای دوستی و دوست داشتن فرصت كوتاهی داره و نباید از کوچکترین فرصتی دریغ کرد.\r\n"},{"id":1740,"category_id":10,"category_code":"s10","source_id":302,"title":"چهار پیرمرد","content":"چهار تا پیرمرد که30سال بود هم دیگر را ندیده بودند با هم به رستوران آمدند یکی از آن ها به دستشویی رفت. بقیه درباره بچه هاشون حرف میزدند یکی از اونا گفت پسر من خیلی پولداره هفته پیش برای تولد بهترین دوستش یه مرسدس بنز کادو داد.دومی گفت پسر منم خیلی پول داره هفته پیش برای تولد بهترین دوستش بهش یه هواپیما خصوصی کادو داد سومی گفت پسر منم خیلی پولداره و هفته پیش براتولد صمیمی ترین دوستش یه خونه 3000  متری کادو داد چهارمی اومد بعد گفت دخترمنم رقاص کابارس یکی از اون پیرمردا گفت اوه باعث خجالته. اما گفت من از دخترم راضیم هفته پیش برای تولدش از دوست پسراش یه مرسدس بنز و خونه 3000 متری و هواپیما خصوصی کادو گرفت!       \r\nنکته:هیچ گاه نباید زود قضاوت کرد.\r\n\r\n"},{"id":1741,"category_id":10,"category_code":"s10","source_id":303,"title":"زاهد و دختر زیبا روی ","content":"\r\nدختری زیبا بود , اسیر پدری عیاش \r\nکه در آمدش فروش شبانه دخترش بود. \r\nدخترک روزی گریزان از منزل پدری نزد حاکم پناه گرفت\r\nو قصه خود بازگو کرد \r\nحاکم دختر را نزد زاهد شهر اما نت سپرد که در امان باشد \r\nاما جناب زاهد همان شب اول دخترک را \r\nنیمه شب دختر نیمه برهنه به جنگل گریخت \r\nو چهار پسر مست او را اطراف کلبه خود یافتند!! \r\nپرسیدند : این زمان , در این سرما , اینجا چه میکنی ؟\r\nدختر از ترس حیوانات بیشه و جانش گفت که آری پدرم این بود و زاهد آن \r\nپسرها با کمی فکر و مکث و دیدن دختر نیمه برهنه , او را گفتند: \r\nتو برو در منزل ما بخواب ما نیز میاییم... \r\nدختر ترسان از اینکه با این 4 پسر مست تا صبح چگونه بگذراند در کلبه خوابش برد \r\nصبح که بیدار شد , دید بر زیر و برش 4 پوستین برای حفاظت اون از سرما هست \r\nو چهار پسر بیرون کلبه از سرما مرده اند!! \r\nبازگشت و بر دروازه شهر فریاد زد: \r\nاز قضا روزی  اگر حاکم این شهر شدم\r\nخون صد شیخ به یک مست فدا خواهم کرد\r\nوسط کعبه دو میخانه بنا خواهم کرد\r\nتا نگویند مستان ز خدا بی خبرند\r\n"},{"id":1742,"category_id":10,"category_code":"s10","source_id":304,"title":"کره فروش","content":"روزی روزگاری مرد و زن فقیری که شغل آنها درست کردن کره محلی بود باهم مشغول کار بودند. آنها باهم کره ها را گرد میکردند و کنار میگذاشتند و تا اینکه به حدحساب برسد و آنها را به مغازه برای فروش تحویل دهند. وقتی کره ها آماده شد آنرا به مغازه بردند. صاحب مغازه گفت : تو این ها را به عنوان یک کیلو به من میفروشی ولی وزن فعلی اینها نهصد گرم است. مرد فقیر گفت: آقا ما در خانه ترازویی نداریم من مدتی پیش از شما شکر خریدم و از همان یه عنوان ترازو استفاده کردم."},{"id":1743,"category_id":10,"category_code":"s10","source_id":305,"title":"دعای فرزند","content":"زنی در جوار بارگاه امام رضا(ع) آرزوی داشتن فرزند می کرد و با اشک و لابه از خداوند تمنای بچه دار شدن داشت در همین حین صدای گریه زنی به گوشش رسید که می گفت:\r\nبیست سال پیش در همین مکان از تو خاستم تا فرزندی به من عطا کنی و تو حاجتم را بر آورده ساختی اکنون فرزند من مرا از خانه بیرون رانده و به تو پناه آورده ام تا اینک جانم را بستانی خداوندا من از آنچه که برایم مقدر ساختی شکایت کردم و اکنون پشیمانم جانم را بستان که از درد کبودی های کتک های پسرم توان خوابیدن ندارم و ساکت ماند.آن زن به سمتش شتافت و چادرش را بالا زد و دید زن به خواب ابدی فرو رفت. از خواسته ی خود پشیمان شد و گفت:خدایا راضیم به رضای تو\r\n"},{"id":1744,"category_id":10,"category_code":"s10","source_id":306,"title":"گدایی","content":"روزی مرد کوری روی پله های ساختمانی نشسته و کلاه و تابلویی را در کنار پایش قرار داده بود. روی تابلو نوشته بود: من کور هستم لطفا کمک کنید. روزنامه نگارخلاقی از کنار او میگذشت نگاهی به او انداخت فقط چند سکه در داخل کلاه بود. او چند سکه داخل کلاه انداخت و بدون اینکه از مرد کور اجازه بگیرد تابلوی او را برداشت آن را برگرداند و اعلان دیگری روی آن نوشت و تابلو را کنار پای او گذاشت و آنجا را ترک کرد.\r\nعصر آنروز روزنامه نگار به آن محل برگشت و متوجه شد که کلاه مرد کور پر از سکه و اسکناس شده است. مرد کور از صدای قدمهای او، خبرنگار را شناخت و خواست اگر او همان کسی است که آن تابلو را نوشته بگوید، که بر روی آن چه نوشته است؟ روزنامه نگار جواب داد: چیز خاص و مهمی نبود، من فقط نوشته شما را به شکل دیگری نوشتم و لبخندی زد و به راه خود ادامه داد.\r\nمرد کور هیچوقت ندانست که او چه نوشته است، ولی روی تابلوی او نوشته شده بود: امروز بهار است، ولی من نمیتوانم آنرا ببینم.\r\n"},{"id":1745,"category_id":10,"category_code":"s10","source_id":307,"title":"قرآن خواندن","content":"مردی بود قرآن میخواند واز معنی قرآن هیچی نمیفهمید. \r\nپس پسرکوچکش از پدرش پرسید چه فایده ای دارد قرآن میخوانی بدون اینکه معنی آن رابفهمی؟\r\nپدر گفت پسرم سبدی بگیر واز آب دریا پرکن وبرایم بیاور. \r\nپسر به پدرش گفت که غیر ممکن است که آب درسبد باقی بماند.\r\nپدر گفت امتحان کن پسرم.پسر سبدی که درآن زغال میگذاشتند گرفت ورفت بطرف دریا وامتحان کرد سبدرازیرآب زد وبسرعت بطرف پدرش دوید ولی همه آبها از سبد ریخت وهیچ آبی در سبد باقی نماند.پس به پدرش گفت که هیچ فایده ای ندارد. \r\nپدرش گفت دوباره امتحان کن پسرم .سپس دوباره امتحان کرد ولی موفق نشد که آب رابرای پدر بیاورد .برای بار سوم وچهارم هم امتحان کرد تا اینکه خسته شد وبه پدرش گفت که غیر ممکن است.\r\nسپس پدر به پسرش گفت سبد قبلا چطور بود؟\r\nاینجا بود که پسرک متوجه شد به پدرش گفت بله پدر قبلا سبد از باقیمانده های زغال کثیف وسیاه بود ولی الان سبد پاک وتمیز شده است.سپس پدر به پسرش گفت این حداقل کاری است که قرآن برای قلبت انجام میدهد.\r\nپس دنیاوکارهای آن قلبت را از کثافتها پرمیکند وخواندن قرآن همچون دریا سینه ات راپاک میکند اگرچه هیچی ازآن حفظ نباشی ومعنی اش رانفهمی.\r\n"},{"id":1746,"category_id":10,"category_code":"s10","source_id":308,"title":"تغییر","content":"مردي كت و شلواري با كراواتي زيبا ، قصد طلاق دادن زنش رو داشت. \r\nدوستش علت رو جويا شد و مرد پاسخ داد: اين زن از روز اول هميشه مي خواست من رو عوض كنه.\r\nمنو وادار كرد سيگار و مشروب رو ترك كنم ... طرز پوشيدن لباسم رو عوض كرد ، و كاري كرد تا ديگه قماربازي نكنم، و همچنين در سهام سرمايه گذاري كنم و حتي منو عادت داده كه به موسيقي كلاسيك گوش كنم و لذت ببرم و الان هر هفته جمعه ها هم با دوستانم كه همه آدمهاي سرشناسي هستند ميرم بازي گلف! \r\n \r\nدوستش با تعجب گفت: ولي اينايي كه ميگي چيز بدي نيستند!!  \r\nمرد گفت: خب اين رو مي دونم ولي حالا حس ميكنم كه ديگه اين زن در شان من نيست.\r\n"},{"id":1747,"category_id":10,"category_code":"s10","source_id":309,"title":"دزد","content":"مادر پسرک فقیر مریض بود.پسرک به دارو خانه رفت و از بی پولی،مجبور شد دارو های مورد نظر را بدزدد.اما گیر می افتد و دارو ها را از او می گیرد.همان زمان مردی او را میبیند.وقتی متوجه می شود که جریان چیست،پول دارو ها را حساب می کند و ودارو ها را به او می دهد.\r\nسی سال بعد همان مرد ناگهان در محل کار خود سکته می کند و نقش بر زمین می شود.زمانی که او را به بیمارستان می برند،می فهمند هزینه ی عمل بسیار سنگین است.روزی یکی از بچه های آن مرد کنار تخت پدر صورت حسابی را می بیند که زیر آن پرداخت شد را نوشته بود.و یک یادداشت دیگر:«این هزینه سی سال پیش پرداخت شده است»در واقع،او همان پسرکی بود که آن مرد سی سال پیش آن کار را برایش کرده بود.\r\n"},{"id":1748,"category_id":10,"category_code":"s10","source_id":310,"title":"موذن","content":"در شهری سه برادر بودند که یکی از آن ها مؤذن مسجد بود و در بالای مناره مسجد، اذان می گفت.\r\nاین برادر پس از چند سال فوت کرد و برادر دوم مؤذن شد و بر بالای مناره مسجد اذان می گفت او هم حدود ده سال به مؤذنی مشغول بود تا اینکه برادر دوم هم فوت کرد.\r\nپس از آن مردم نزد برادر سوم رفتند و از او خواستند او هم چون دو برادرش به اذان گوئی بپردازد. اما وی از پذیرفتن اجتناب کرد.\r\nوقتی با اصرار زیاد مردم روبرو شد به آنان گفت: «من اذان گفتن را بد نمی دانم ولی اگر صد برابر پولی را که پیشنهاد می کنید به من بدهید باز هم نخواهم پذیرفت زیرا این کار باعث شد دو برادر من بی ایمان از دنیا بروند. وقتی لحظات آخر عمر برادر بزرگترم رسید خواستم بر بالینش سوره یس تلاوت کنم که با اعتراض و فریاد و نهیب او مواجه شدم.\r\nاو می گفت: قرآن چیست؟ چرا برایم قرآن می خوانی؟\r\nبرادر دوم هم به این صورت در هنگام مرگش به من اعتراض کرد.\r\nاز خداوند کمک خواستم که علت این امر را برایم روشن گرداند زیرا آنان مؤذن بودند و این کار از آنان انتظار نمی رفت.\r\nخداوند برای آنکه ماجرا را به من بفهماند زبان او را گویا کرد و در این هنگام برادرم گفت: ما هر گاه که بالای مناره مسجد می رفتیم به خانه های مردم نگاه می کردیم و به محارم مردم چشم می دوختیم و خلاصه چشم چرانی باعث این بی ایمانی و عذاب گردیده است.\r\n"},{"id":1749,"category_id":10,"category_code":"s10","source_id":311,"title":"شانس خوب یا بد؟","content":"پیر مرد روستا زاده ای بود که یک پسر و یک اسب داشت\r\nروزی اسب پیرمرد فرار کرد، همه همسایه ها برای دلداری به خانه پیر مرد آمدند و گفتند: عجب شانس بدی آوردی که اسبت فرارکرد! \r\nروستا زاده پیر جواب داد: از کجا میدانید که این از خوش شانسی من بوده یا از بد شانسی ام؟ \r\nهمسایه ها با تعجب جواب دادن: خوب معلومه که این از بد شانسیه! \r\nهنوز یک هفته از این ماجرا نگذشته بود که اسب پیر مرد به همراه بیست اسب وحشی به خانه برگشت. این بار همسایه ها برای تبریک نزد پیرمرد آمدند: عجب اقبال بلندی داشتی که اسبت به همراه بیست اسب دیگر به خانه بر گشت! \r\nپیر مرد بار دیگر در جواب گفت: از کجا میدانید که این از خوش شانسی من بوده یا از بد شانسی ام؟ \r\nفردای آن روز پسر پیرمرد در میان اسب های وحشی، زمین خورد و پایش شکست. \r\nهمسایه ها بار دیگر آمدند: عجب شانس بدی! \r\nو کشاورز پیر گفت: از کجا میدانید که این از خوش شانسی من بوده یا از بد شانسی ام؟\r\nو چند تا از همسایه ها با عصبانیت گفتند: خب معلومه که از بد شانسیه تو بوده پیرمرد کودن! \r\nچند روز بعد نیروهای دولتی برای سربازگیری از راه رسیدند و تمام جوانان سالم را برای جنگ در سرزمینی دوردست با خود بردند. پسر کشاورز پیر به خاطر پای شکسته اش از اعزام، معاف شد. \r\nهمسایه ها بار دیگر برای تبریک به خانه پیرمرد رفتند: عجب شانسی آوردی که پسرت معاف شد! \r\nو کشاورز پیر گفت: از کجا میدانید که...؟\r\n"},{"id":1750,"category_id":10,"category_code":"s10","source_id":312,"title":"ساختن زندگی","content":"مارک البیون در کتاب خود تحت عنوان  «ساختن زندگی و امرار معاش» ، درباره یک مطالعه آشکارکننده از سوداگرانی می نویسد که دو مسیر کاملا متفاوت را پس از فراغت از تحصیل دانشگاهی طی کرده اند.\r\n وی چنین می گوید:یک بررسی از فارغ التحصیلان دانشکده بازرگانی، سابقه 1500 نفر را از سال 1960 تا سال 1980 مورد مطالعه قرار داده است. در آغاز، فارغ التحصیلان به دو گروه تقسیم شدند.\r\n گروه الف: کسانی بودند که گفته بودند می خواستند اول پول درآورند تا بعداً هر کار خواستند بکنند. یعنی اول مشکلات مالی خود را حل و فصل کنند، بعداً به امور دیگر زندگی بپردازند.\r\n گروه ب : شامل کسانی بود که ابتدا به دنبال علاقه واقعی خود بودند و اطمینان داشتند که پول عاقبت خود به دنبال آن می آید.\r\n چه درصدی در هر گروه وجود داشت؟ از 1500 فارغ التحصیل در مطالعه مورد نظر، کسانی که در گروه الف « اول پول» بودند 83 درصدکل یا 1245 نفر را تشکیل می دادند. گروه ب « اول علاقه واقعی» یعنی خطرپذیرها جمعاً 17 درصد یا 255 نفر بودند\r\n پس از بیست سال 101 نفر میلیونر در کل این دو گروه به وجود امده بود که یک نفر از گروه «الف» و 100 نفر از گروه «ب» بودند.\r\n"},{"id":1751,"category_id":10,"category_code":"s10","source_id":313,"title":"عجایب هفتگانه ","content":"از یک گروه از دانش اموز خواستد اسامی عجایب هفتگانه را بنویسند... \r\nعلی رغم اختلاف نظر ها، اکثرا اینها را جزو عجایب هفت گانه نام بردند:اهرام مصر \r\nتاج محل \r\nدره بزرگ به نام گراند کانیون در امریکا(کانال پاناما)\r\nکلیسای پطرس مقدس\r\nدیوار بزرگ چین \r\nآبشار نیاگارا \r\nآموزگار هنگام جمع کردن نوشته های دانش آموزان، متوجه شد که یکی از آنها هنوز کارش را تمام نکرده است.\r\nاز دخترک پرسید که آیا مشکلی دارد...\r\nدختر جواب داد : بله کمی مشکل دارم، چون تعداد شگفتی ها خیلی زیاد است و نمیدانم کدام را بنویسم...! \r\nآموزگار گفت: آنهایی را که نوشته ای نام ببر شاید ما هم بتوانیم کمک کنیم... \r\nدخترک با تردید چنین خواند:به نظر من عجایب هفت گانه دنیا عبارتند از:دیدن\r\nشنیدن\r\nلمس کردن\r\nچشیدن\r\nاحساس کردن\r\nخندیدن\r\nدوست داشتن\r\n \r\nاتاق در چنان سکوتی فرو رفت که حتی صدای زمین افتادن سنجاق شنیده می شد...!آن چیزهایی که به نظرمان ساده و معمولی میرسند، آنها را نادیده و دست کم میگیریم، حقیقا شگفت انگیزند...\r\nبا ملایمت به یادمان می آورند که با ارزش ترین چیزهای زندگی ساخته دست انسان نیستند و آنها را نمیتوان خرید ، آن قدر خود را مشغول نکنید که بی توجه از کنارشان بگذرید.\r\n"},{"id":1752,"category_id":10,"category_code":"s10","source_id":314,"title":"نصایح شیخ","content":"\r\n. ..نصايح شيخ بهايي به فرزندش\r\nآدمي اگر پيامبر هم باشد از زبان مردم آسوده نيست.\r\nاگر بسيار کار کند، مي‌گويند احمق است.\r\nاگر کم کار کند، مي‌گويند تنبل است.\r\nاگر بخشش کند مي‌گويند افراط مي‌کند.\r\nاگر ثروت اندوزي کند، مي‌گويند بخيل است.\r\nاگر ساکت و خاموش باشد مي‌گويند لال است.\r\nاگر زبان‌آوري کند، مي‌گويند وراج و پر روست.\r\nاگر روزه بدارد و شب‌ها نماز بخواند مي‌گويند رياکار است.\r\nو اگر نماز نخواند مي‌گويند کافر و بي دين است.\r\nپس فرزندم نبايد به حمد و ثناي مردم اعتنا کرد و جز از خداوند نبايد از کسي ترسيد.\r\n"},{"id":1753,"category_id":10,"category_code":"s10","source_id":315,"title":"پیرمرد زارع","content":"داستانی عبرت آموز در مورد زندگی یک زارع  پیر افریقایی وجود دارد که به موفقیت زیادی دست یافت، ولی یک روز از شنیدن داستان کسانی که به افریقا می روند به هیجان آمد. \r\nاو مزرعه خود را می فروشد و تصمیم می گیرد به افریقا برود ، معدن الماس کشف کند و به ثروتی افسانه ای دست یابد . او قاره افریقا را در مدت 12 سال زیر پا می گذارد و عاقبت در نتیجه بی پولی ، تنهایی، خستگی و بیماری و ناامیدی ، خود را به درون اقیانوس پرت می کند و غرق می شود.\r\nاز طرف دیگر ، زارع جدیدی که مزرعه او را خریده بود ، هنگامی که  به قاطر خود ، در رودخانه ای که از وسط مزرعه اش می گذرد ، آب دهد ، تکه سنگی پیدا می کند که نور درخشانی از خود ساطع می کند.\r\nمعلوم می شود آن سنگ الماسی است که قیمتی بر آن متصور نیست . کسی که الماس را شناخته است از زارع درخواست می کند که او را به مزرعه اش ببرد و محل را به او نشان دهد و زارع او را به محلی که قاطرش را آب داده بود می برد . آنها در آنجا قطعه سنگ های بسیاری از همان نوع پیدا می کنند و بعداً متوجه می شوند که سرتا سر مزرعه پوشیده از فرسنگ ها معدن الماس است. \r\nزارع پیر پیشین بدون آنکه حتی زیر پای خود را نگاه کند برای کشف الماس به جای دیگری رفته بود.  \r\nوقتی هدفی را برای خود تعیین می کنید فکر نکنید برای عملی ساختن آن باید سراسر کشور را زیر پا بگذارید ، شغل خود را عوض کنید...  \r\nببینید دقیقاً کجا هستید و از همان جا کار خود را آغاز کنید . در بیشتر موارد میدان های الماس خود را در همان جا خواهید یافت.\r\n"},{"id":1754,"category_id":10,"category_code":"s10","source_id":316,"title":"زن میخوام!","content":"جوانی می خواست زن بگیرد به پیرزنی سفارش کرد تا برای او دختری پیدا کند. پیرزن به جستجو پرداخت، دختری را پیدا کرد و به جوان معرفی کرد وگفت این دختر از هر جهت سعادت شما را در زندگی فراهم خواهد کرد.\r\nجوان گفت: شنیده ام قد او کوتاه است\r\nپیرزن گفت:اتفاقا این صفت بسیار خوبی است، زیرا لباس های خانم ارزان تر تمام می شود. \r\nجوان گفت: شنیده ام زبانش هم لکنت دارد.\r\nپیرزن گفت: این هم دیگر نعمتی است زیرا می دانید که عیب بزرگ زن ها پر حرفی است اما این دختر چون لکنت زبان دارد پر حرفی نمی کند و سرت را به درد نمی آورد. \r\nجوان گفت: خانم همسایه گفته است که چشمش هم معیوب است.\r\nپیرزن گفت: درست است ، این هم یکی از خوشبختی هاست که کسی مزاحم آسایش شما نمی شود و به او طمع نمی برد. \r\nجوان گفت: شنیده ام پایش هم می لنگد و این عیب بزرگی است.\r\nپیرزن گفت: شما تجربه ندارید، نمی دانید که این صفت ، باعث می شود که خانمتان کمتر از خانه بیرون برود و علاوه بر سالم ماندن، هر روز هم از خیابان گردی ، خرج برایت نمی تراشد. \r\nجوان گفت: این همه به کنار، ولی شنیده ام که عقل درستی هم ندارد.\r\nپیرزن گفت: ای وای، شما مرد ها چقدر بهانه گیر هستید، پس یعنی می خواستی عروس به این نازنینی، این یک عیب کوچک را هم نداشته باشد.\r\n"},{"id":1755,"category_id":10,"category_code":"s10","source_id":317,"title":"سلطان و عابد","content":"سلطان سلجوقی بر عابدی گوشه نشین و عزلت گزین وارد شد. حکیم سرگرم مطالعه بود و سر بر نداشت و به ملکشاه تواضع نکرد، بدان سان که سلطان به خشم اندر شد و به او گفت: آیا تو نمی دانی من کیستم؟\r\n  \r\nمن آن سلطان مقتدری هستم که فلان گردنکش را به خواری کشتم و فلان یاغی را به غل و زنجیر کشیدم و کشوری را به تصرف در آوردم.  \r\nحکیم خندید و گفت: من نیرومند تر از تو هستم، زیرا من کسی را کشته ام که تو اسیر چنگال بی رحم او هستی. شاه با تحیر پرسید: اوکیست؟  \r\nحکیم گفت: آن نفس است. من نفس خود را کشته ام و تو هنوز اسیر نفس اماره خود هستی و اگر اسیر نبودی از من نمی خواستی که پیش پای تو به خاک افتم و عبادت خدا بشکنم و ستایش کسی را کنم که چون من انسان است.  \r\nشاه از شنیدن این سخن شرمنده شد و عذر خطای گذشته خود را خواست.\r\n"},{"id":1756,"category_id":10,"category_code":"s10","source_id":318,"title":"شاپور","content":"یکی از سلاطین به نام «اساطرون» در شهری کنار رود فرات سلطنت می کرد. او در اداره امور کشور خود به اندازه ای قدرت به خرج داده بود که «شاپور ذوالاکتاف» احترام او را داشت.\r\nوقتی که «شاپور» با دولت «روم» صلح کرد، در فکر تسخیر شهر «اساطرون» افتاد. پس سپاهی مجهز را حرکت داد و گرداگرد شهر را گرفت. ولی بخاطر استحکام حصار قلعه، از فتح آن مأیوس گردید و پیوسته در خارج شهر راه می رفت تا شاید چاره ای پیدا کند.\r\nروزی دختر «اساطرون» بالای حصار شهر آمده بود و لشگر دشمن را تماشا می کرد.ناگاه چشمش به قامت مردانه «شاپور» افتاد و با همین یک نگاه عاشق او شد. پنهانی نامه ای به او نوشت که: «اگر مرا به ازدواج خود در آوری، وسیله تسخیر شهر را فراهم می کنم.» «شاپور» نیز پذیرفت.\r\nدختر شبانه وسایل ورود لشگریان را فراهم نمود و «شاپور» با سپاهیانش وارد شدند و شهر را فتح کردند.«اساطرون» را کشته و سر او را به نیزه زدند و به مردم نشان دادند. مردم نیز پس از مشاهده سرِ سلطان خود، از «شاپور» اطاعت کردند.\r\nشهریار ایران هم به پیمان خود عمل نمود و با دختر ازدواج کرد و مدتی با او بسر برد.\r\nشبی چشم «شاپور» به پشت دختر افتاد که بر اثر خراشیدگی، خون آلود شده بود. پرسید: این خراش از چیست؟\r\nگفت: در محل استراحت من برگ «موردی» (برگی است لطیف که برای تقویت موی سر و صورت بکار برده می شود) بود که بر اثر تماس با او، بدنم خراش برداشت.\r\nشاپور گفت: پدرت، تو را چه اندازه با ناز پروریده است که چنین پوست لطیفی پیدا کرده ای؟\r\nاو گفت: پدرم مرا با بهترین وسائل، پرورش می داد و غذایم را از مغز سر گوسفند و زرده تخم مرغ و عسل قرار داده بود.\r\n«شاپور مدتی سر به زیر انداخت و پس از مدتی تفکر، سر برداشت و گفت: «تو با پدری چنین مهربان اینگونه بی وفایی کردی! چگونه با من پایداری خواهی کرد؟! پس دستور داد که گیسوان او را بر دم اسبی بسته و در میان خارستانی کشیدند تا به درک واصل گردید.\r\n"},{"id":1757,"category_id":10,"category_code":"s10","source_id":319,"title":"کلاه فروش ","content":"کلاه فروشی روزی از جنگلی می گذشت. تصمیم گرفت زیر درخت مدتی استراحت کند. لذا کلاه ها را کنار گذاشت و خوابید. وقتی بیدار شد متوجه شد که کلاه ها نیست!\r\nبالای سرش را نگاه کرد. تعدادی میمون را دید که کلاه ها را برداشته اند.\r\nفکر کرد که چگونه کلاه ها را پس بگیرد. در حال فکر کردن سرش را خاراند و دید که میمون ها همین کار را کردند. او کلاه را از سرش برداشت و دید که میمون ها هم از او تقلید کردند.\r\nبه فکرش رسید... که کلاه خود را روی زمین پرت کند. لذا این کار را کرد. میمونها هم کلاهها را بطرف زمین پرت کردند و او همه کلاه ها را جمع کرد و روانه شهر شد.\r\nسالهای بعد نوه او هم کلاه فروش شد. پدر بزرگ این داستان را برای نوه اش تعریف کرد و تاکید کرد که اگر چنین وضعی برایش پیش آمد چگونه برخورد کند... \r\nیک روز که او از همان جنگل گذشت در زیر درختی استراحت کرد و همان قضیه برایش اتفاق افتاد.\r\nاو شروع به خاراندن سرش کرد. میمون ها هم همان کار را کردند. او کلاهش را برداشت، میمون ها هم همان کار را کردند. نهایتا کلاهش را بر روی زمین انداخت. ولی میمون ها این کار را نکردند!\r\nیکی از میمون ها از درخت پایین آمد و کلاه را از روی زمین برداشت و در گوشی محکمی به او زد و گفت : فکر می کنی فقط تو پدر بزرگ داری؟! \r\nنکته : رقابت هیچگاه سکون نمی شناسد.\r\n"},{"id":1758,"category_id":10,"category_code":"s10","source_id":320,"title":"نامه ی پدربزرگ","content":"پسرک پدربزرگش را تماشا کرد که نامه ای می نوشت. \r\nبالاخره پرسید: \r\n- ماجرای کارهای خودمان را می نویسید ؟ درباره ی من می نویسید ؟\r\nپدربزرگش از نوشتن دست کشید و لبخند زنان به نوه اش گفت: \r\n- درسته درباره ی تو می نویسم اما مهم تر از نوشته هایم مدادی است که با آن می نویسم \r\nمی خواهم وقتی بزرگ شدی مانند این مداد شوی \r\nپسرک با تعجب به مداد نگاه کرد و چیز خاصی در آن ندید  \r\n- اما این هم مثل بقیه مدادهایی است که دیده ام \r\n- بستگی داره چطور به آن نگاه کنی . در این مداد 5 خاصیت است که اگر به دستشان بیاوری ، تا آخر عمرت با آرامش زندگی می کنی. \r\nصفت اول: \r\nمی توانی کارهای بزرگ کنی اما نباید هرگز فراموش کنی که دستی وجود دارد که حرکت تو را هدایت می کند. \r\nاسم این دست خداست.\r\nاو همیشه باید تو را در مسیر اراده اش حرکت دهد. \r\nصفت دوم: \r\nگاهی باید از آنچه می نویسی دست بکشی و از مداد تراش استفاده کنی . این باعث می شود مداد کمی رنج بکشد اما آخر کار ، نوکش تیزتر می شود. \r\nپس بدان که باید رنج هایی را تحمل کنی چرا که این رنج باعث می شود انسان بهتری شوی. \r\nصفت سوم: \r\nمداد همیشه اجازه می دهد برای پاک کردن یک اشتباه از پاک کن استفاده کنیم. \r\nبدان که تصحیح یک کار خطا ، کار بدی نیست . در واقع برای اینکه خودت را در مسیر درست نگهداری مهم است.\r\nصفت چهارم: \r\nچوب یا شکل خارجی مداد مهم نیست ، زغالی اهمیت دارد که داخل چوب است. \r\nپس همیشه مراقبت درونت باش چه خبر است. \r\nصفت پنجم: \r\nهمیشه اثری از خود به جا می گذارد. \r\nبدان هر کار در زندگی ات می کنی ردی به جا می گذارد و سعی کن نسبت به هر کاری می کنی هوشیار باشی و بدانی چه می کنی.\r\n"},{"id":1759,"category_id":10,"category_code":"s10","source_id":321,"title":"چغندر تا پیاز شکر خدا","content":"میگویند در روزگار قدیم مرد فقیری در دهی زندگی میکرد. یک روز مرد فقیر به همسرش گفت:((می خواهم هدیه ای برای پادشاه ببرم.شاید شاه در عوض چیزی شایسته شان ومقام خودش به من ببخشد و من آن را بفروشم و با پول آن زندگیمان عوض شود))\r\nهمسرش که چغندر دوست داشت،گفت:((برای پادشاه چغندر ببر!))اما مرد که پیاز دوست داشت،مخالفت کرد وگفت:((نه!پیاز بهتر است خاصیتش هم بیشتر است.))بااین انگیزه کیسه ای پیاز دستچین کرد و برای پادشاه برد. \r\nاز بد حادثه،آن روز از روز های بد اخلاقی پادشاه بود و اصلا حوصله چیزی رانداشت. وقتی به او گفتند که مرد فقیری برایش یک کیسه پیاز هدیه آورده، عصبانی شد ودستور داد پیاز ها را یکی یکی بر سر مرد بیچاره بکوبند. مرد فقیر در زیر ضربات پی در پی پیازهایی که بر سرش می خورد، با صدای بلند میگفت:((چغندر تا پیاز، شکر خدا!!)) \r\nپادشاه که صدای مرد فقیر را می شنید ، تعجب کرد و جلو آمد و پرسید: این حرف چیست که مرتب فریاد می کنی؟ مرد فقیر با ناله گفت:شکر می کنم که به حرف همسرم اعتنا نکردم وچغندر با خود نیاوردم وگرنه الان دیگر زنده نبودم! \r\nشاه از این حرف مرد خندید وکیسهای زر به او بخشید تا زندگیش را سرو سامان دهد! واز آن پس عبارت پیاز تا چغندر شکر خدا در هنگامی که فردی به گرفتاری دچار شود که ممکن بود بدتر از آن هم باشد به کار میرود.\r\n"},{"id":1760,"category_id":10,"category_code":"s10","source_id":322,"title":"فریب دادن مرگ","content":"\r\nیه بنده خدا نشسته بود داشت تلویزیون میدید که یهو مرگ اومد پیشش \r\nمرگ گفت : الان نوبت توئه که ببرمت  \r\nطرف یه کم آشفته شد و گفت : داداش اگه راه داره بیخیال ما بشو بذار واسه بعد \r\nمرگ : نه اصلا راه نداره. همه چی طبق برنامست. طبق لیست من الان نوبت توئه \r\nاون مرد گفت : حداقل بذار یه شربت بیارم خستگیت در بره بعد جونمو بگیر \r\nمرگ قبول کرد و اون مرد رفت شربت بیاره\r\n \r\n \r\nتوی شربت 2 تا قرص خواب خیلی قوی ریخت \r\nمرگ وقتی شربته رو خورد به خواب عمیقی فرو رفت \r\nمرد وقتی مرگ خواب بود لیستو برداشت اسمشو پاک کرد و نوشت آخر لیست و منتظر شد تا مرگ بیدار شه  \r\nمرگ وقتی بیدار شد گفت : دمت گرم داداش حسابی حال دادی خستگیم در رفت!\r\nبخاطر این محبتت منم بیخیال تو میشم و میرم از آخر شروع به جون گرفتن میکنم!\r\n"},{"id":1761,"category_id":10,"category_code":"s10","source_id":323,"title":"نکات مثبت","content":"پروفسور ﺣﺴﺎﺑﯽ ﻣﻴﮕﻔﺖ ﺩﺭ ﺩﻭﺭﻩ ﺗﺤﺼﻴﻼﺗﻢ ﺩﺭ\r\nﺁﻣﺮﻳﻜﺎ ﺩﺭ\r\nﻳﻚ ﻛﺎﺭ ﮔﺮﻭﻫﻲ ﺑﺎ ﻳﻜﺪﺧﺘﺮ ﺁﻣﺮﻳﻜﺎﻳﻲ ﺑﻪ ﻧﺎﻡ\r\nﻛﺎﺗﺮﻳﻨﺎ ﻭ ﻫﻤﻴﻨﻄﻮﺭ\r\nﻓﻴﻠﻴﭗ، ﻛﻪ ﻧﻤﻴﺸﻨﺎﺧﺘﻤﺶ ﻫﻤﮕﺮﻭﻩ ﺷﺪﻡ . ﺍﺯ\r\nﻛﺎﺗﺮﻳﻨﺎ ﭘﺮﺳﻴﺪﻡ ﻓﻴﻠﻴﭗ\r\nﺭﻭ ﻣﻴﺸﻨﺎﺳﻲ؟ ﻛﺎﺗﺮﻳﻨﺎ ﮔﻔﺖ ﺁﺭﻩ، ﻫﻤﻮﻥ ﭘﺴﺮﻱ ﻛﻪ\r\nﻣﻮﻫﺎﻱ ﺑﻠﻮﻧﺪ\r\nﻗﺸﻨﮕﻲ ﺩﺍﺭﻩ ﻭ ﺭﺩﻳﻒ ﺟﻠﻮ ﻣﻴﺸﻴﻨﻪ ! ﮔﻔﺘﻢ\r\nﻧﻤﻴﺪﻭﻧﻢ ﻛﻴﻮ ﻣﻴﮕﻲ! \r\nﮔﻔﺖ ﻫﻤﻮﻥ ﭘﺴﺮ ﺧﻮﺵ ﺗﻴﭗ ﻛﻪ ﻣﻌﻤﻮﻻ ﭘﻴﺮﺍﻫﻦ\r\nﻭ ﺷﻠﻮﺍﺭ ﺭﻭﺷﻦ\r\nﺷﻴﻜﻲ ﺗﻨﺶ ﻣﻴﻜﻨﻪ ! ﮔﻔﺘﻢ ﻧﻤﻴﺪﻭﻧﻢ ﻣﻨﻈﻮﺭﺕ\r\nﻛﻴﻪ؟ ﮔﻔﺖ ﻫﻤﻮﻥ\r\nﭘﺴﺮﻱ ﻛﻪ ﻛﻴﻒ ﻭﻛﻔﺸﺶ ﻫﻤﻴﺸﻪ ﺳﺖ ﻫﺴﺖ\r\nﺑﺎﻫﻢ ! ﺑﺎﺯﻡ ﻧﻔﻬﻤﻴﺪﻡ\r\nﻣﻨﻈﻮﺭﺵ ﻛﻲ ﺑﻮﺩ ! ﻛﺎﺗﺮﻳﻨﺎ ﺗﻮﻥ ﺻﺪﺍﺷﻮ ﻳﻜﻢ\r\nﭘﺎﻳﻴﻦ ﺁﻭﺭﺩ ﻭ ﮔﻔﺖ\r\nﻓﻴﻠﻴﭗ ﺩﻳﮕﻪ، ﻫﻤﻮﻥ ﭘﺴﺮ ﻣﻬﺮﺑﻮﻧﻲ ﻛﻪ ﺭﻭﻱ\r\nﻭﻳﻠﭽﻴﺮ ﻣﻴﺸﻴﻨﻪ... \r\nﺍﻳﻦ ﺑﺎﺭ ﺩﻗﻴﻘﺎ ﻓﻬﻤﻴﺪﻡ ﻛﻴﻮ ﻣﻴﮕﻪ ﻭﻟﻲ ﺑﻪ ﻃﺮﺯ\r\nﻏﻴﺮ ﻗﺎﺑﻞ ﺑﺎﻭﺭﻱ\r\nﺭﻓﺘﻢ ﺗﻮ ﻓﻜﺮ ... ﺁﺩﻡ ﭼﻘﺪﺭ ﺑﺎﻳﺪ ﻧﮕﺎﻫﺶ ﺑﻪ\r\nﺍﻃﺮﺍﻑ ﻣﺜﺒﺖ ﺑﺎﺷﻪ ﻛﻪ\r\nﺑﺘﻮﻧﻪ ﺍﺯ ﻭﻳﮋﮔﻲ ﻫﺎﻱ ﻣﻨﻔﻲ ﻭ ﻧﻘﺺ ﻫﺎ ﭼﺸﻢ\r\nﭘﻮﺷﻲ ﻛﻨﻪ... \r\nﭼﻘﺪﺭ ﺧﻮﺑﻪ ﻣﺜﺒﺖ ﺩﻳﺪﻥ ﺍﮔﺮ ﻛﺎﺗﺮﻳﻦ ﺍﺯ ﻣﻦ ﺩﺭ\r\nﻣﻮﺭﺩ ﻓﻴﻠﻴﭗ\r\nﻣﻴﭙﺮﺳﻴﺪ ﭼﻲ ﻣﻴﮕﻔﺘﻢ؟ ﺣﺘﻤﺎ ﺳﺮﻳﻊ ﻣﻴﮕﻔﺘﻢ\r\nﻫﻤﻮﻥ ﻣﻌﻠﻮﻟﻪ ﺩﻳﮕﻪ!! \r\nﻭﻗﺘﻲ ﻧﮕﺎﻩ ﻛﺎﺗﺮﻳﻨﺎ ﺭﻭ ﺑﺎ ﺩﻳﺪ ﺧﻮﺩﻡ ﻣﻘﺎﻳﺴﻪ\r\nﻛﺮﺩﻡ ﺧﻴﻠﻲ ﺧﺠﺎﻟﺖ\r\nﻛﺸﻴﺪﻡ.\r\n"},{"id":1762,"category_id":10,"category_code":"s10","source_id":324,"title":"زن باهوش و زرنگ","content":"یه روز یه زن و مرد ماشینشون تصادف ناجوری میکنه و هر دو ماشین به شدت داغون میشه، ولی هر دو نفر سالم میمونن.\r\nوقتی که از ماشینشون پیاده میشن و صحنه تصادف رو میبینن، مرد میگه:\r\n!- ببین چیکار کردی خانم! ماشینم داغون شده\r\n!- آه چه جالب، شما یه مرد هستید\r\nمرد با تعجب میگه:\r\n- بله، چطور مگه؟\r\n!- چقدر عجیب! همه چیز داغون شده ولی ما دو نفر کاملاً سالم هستیم\r\n- منظورتون چیه؟\r\n!- این باید نشونه ای از طرف خدا باشه که اینجوری با هم ملاقات کنیم و آشنا بشیم\r\nمرد با هیجان زیادی میگه:\r\n!- اوه بله، کاملاً موافقم! این حتماً نشونه خوبیه\r\nزن دوباره نگاهی به ماشین میکنه و میگه:\r\n- یه معجزه دیگه! ماشین من کاملاً داغون شده ولی این بطری مشروب کاملاً سالمه! این یعنی باید این آشنایی رو جشن بگیریم!\r\n!- بله بله، حتماً همینطوره! کاملاً موافقم\r\nزن در بطری رو باز میکنه و به طرف مرد تعارف میکنه، مرد هم بطری رو تا نصف سر میکشه و برمیگردونه به زن.\r\nولی زن در بطری رو میبنده و دوباره برمیگردونه به مرد! مرد با تعجب میگه:\r\n- مگه شما نمینوشین؟\r\nزن با شیطنت خاصی میگه:\r\n- نه عزیزم، فکر کنم الان بهتره منتظر پلیس باشیم \r\n"},{"id":1763,"category_id":10,"category_code":"s10","source_id":325,"title":"خدمت به مادر","content":"دو برادر مادر پیر و بیماری داشتند . هر دو متقی و پرهیزکار بودند و عالم وعارف . با خود پیمان بستند که یکی خدمت خدا کند و دیگری در خدمت مادر بیمار باشد. \r\nبرادری که پیمان بسته بود خدمت خدا کند به صومعه رفت و به عبادت مشغول شد وآن دیگری در خانه ماند و به پرستاری مادر مشغول شد. \r\nچندی که گذشت برادر صومعه نشین مشهور عام وخاص شد و از اقصی نقاط دنیا ،عالمان و عرفا و زهاد به دیدارش شتافتند و آن دیگری که خدمت مادر می کرد فرصت همنشینی وهمکلاسی با دوستان قدیم را نیز از دست داد و یکسره به امور مادر می پرداخت. \r\nبرادر صومعه نشین کم کم به خود غره شد که خدمت من ارزشمند تر از خدمت برادر است ،چرا که او در اختیار مخلوق است ومن در خدمت خالق ،و من از او برترم! \r\nهمان شب که این کلام در خاطر او بگذشت ،پروردگار را در خواب دید که وی را خطاب کرد و گفت :برادر تو را بیا مرزیدم و تو را به حرمت او بخشیدم و از این پس تو را حکم کردیم که در خدمت برادر باشی. \r\nعارف صومعه نشین اشک در چشمانش آمد وگفت :یا رب العالمین ،من در خدمت تو بودم و او به خدمت مادر ،چگونه است مرا در خدمت او می گماری وبه حرمت او می بخشی، آنچه کرده ام مایه رضای تو نیست ؟َ! ندا رسید : آنچه تو می کنی ما از آن بی نیازم و لاکن مادرت از آنچه او می کند ،بی نیاز نیست ،تو خدمت بی نیاز می کنی و او خدمت نیازمند ، بدین حرمت مرتبت او را از تو فزونی بخشیدیم و تو را در کاراو کردیم.\r\n"},{"id":1764,"category_id":10,"category_code":"s10","source_id":326,"title":"دو رکعت نماز","content":"\r\nبراى پيامبر خدا صلى الله عليه و آله دو شتر بزرگ آوردند. حضرت به اصحاب فرمود:\r\nآيا در ميان شما كسى هست دو ركعت نماز بخواند كه در آن هيچ گونه فكر دنيا به خود راه ندهد، تا يكى از اين دو شتر را به او بدهم. \r\nاين فرمايش را چند بار تكرار فرمود. كسى از اصحاب پاسخ نداد. اميرالمؤ منين عليه السلام به پا خواست و عرض كرد:\r\nيا رسول الله ! من مى توانم آن دو ركعت نماز را بخوانم. \r\nپيامبر صلى الله عليه و آله فرمود:\r\nبسيار خوب بجاى آور!\r\nاميرالمؤ منين عليه السلام مشغول نماز شد، هنگامى كه سلام نماز را داد جبرئيل نازل شد، عرض كرد:\r\nخداوند مى فرمايد يكى از شترها را به على بده! \r\nرسول خدا صلى الله عليه و آله فرمود:\r\nشرط من اين بود كه هنگام نماز انديشه اى از امور دنيا را به خود راه ندهد. على در تشهد كه نشسته بود فكر كرد كدام يك از شترها را بگيرد.\r\nجبرئيل گفت: \r\nخداوند مى فرمايد:\r\nهدف على اين بود كدام شتر چاقتر است او را بگيرد، بكشد و به فقرا بدهد، انديشه اش براى خدا بود. نه براى خودش بود و نه براى دنيا.\r\nآنگاه پيامبر صلى الله عليه و آله به خاطر تشكر از على عليه السلام هر دو شتر را به او داد. خداوند نيز در ضمن آيه اى از آن حضرت قدردانى نموده و فرمود:\r\n((ان فى ذالك لذكرى لمن كان له قلب او القى السمع و هو شهيد)) (1)\r\nسپس رسول خدا صلى الله عليه و آله فرمود:\r\nهر كس دو ركعت نماز بخواند و در آن انديشه اى از امور دنيا به خود راه ندهد، خداوند از او خشنود شده و گناهانش را مى آمرزد.\r\n \r\n \r\nسوره ق آيه 37. حقا در اين موضوع ياد آورى است براى آن كس كه داراى قلب هوشيار است يا گوش دل به كلام خدا سپرده و به حقانيتش توجه كامل دارد.\r\n  بحار: ج 36، ص 191\r\n"},{"id":1765,"category_id":10,"category_code":"s10","source_id":327,"title":"اسیر زیبا روی","content":"در زمان کوروش کبیر زنی به نام پانته ا زیباترین زن جهان بود. \r\n. او همسر یکی از سرداران اشوری بود\r\nدر جنگ, پانته ا اسیر میشود و به کوروش مشتاقانه خبر می اورند که زیباترین زن جهان اسیر ماست و میخواهیم او را به شما تقدیم نماییم. \r\nکوروش پاسخ داد او را به اینجا نیاورید شاید با دیدن او نتوانم اراده ام را نگه دارم او را به نزد شوهرش برده و دستش را در دست شوهرش قرار دهید. \r\nشوهر این زن در دیدن بزرگواری و سخاوت کوروش کبیر شیفته او میشود و با لشکریان تحت فرماندهیش به خدمت کوروش میرسد و به او میگوید تا اخرین قطره خونم در راه تو مجنگم ای کوروش.\r\nکوروش کبیر بر مردم حکومت نمیکرد او بر دلها حکومت میکرد او سلطان قلبها نام داشت پدر ایران... \r\nکورش کبیر دستور داد برای ساختمان قصر پله هایی بسازند که ارتفاع هر پله بیشتر از یک وجب نباشد. \r\nملازمان از وی پرسیدند چرا درحالیکه میتواند پله های کمتر و با ارتفاع کمی بلندتر بسازد این همه پله با این ارتفاع کم میسازد؟\r\nکورش گفت: \r\nزنان دربار ما از این پله ها عبور خواهند کرد. در شأن زن ایرانی نیست پایش را بیشتر از یک وجب بالا برد.\r\n"},{"id":1766,"category_id":10,"category_code":"s10","source_id":328,"title":"جهان هر کس به اندازه‌ی وسعت فکر اوست","content":"\r\nیک روز وقتى کارمندان به اداره رسیدند،\r\nاطلاعیه بزرگى را در تابلوى اعلانات دیدند که روى آن نوشته شده بود:\r\nدیروز فردى که مانع پیشرفت شما در این شرکت بود درگذشت.\r\nشما را به شرکت در مراسم تشییع جنازه ساعت 10 دعوت مى‌کنیم.\r\nدر ابتدا، همه از دریافت خبر مرگ یکى از همکارانشان ناراحت مى‌شدند\r\nامّا پس از مدتى، کنجکاو مى‌شدند که چه کسی مانع پیشرفت آنها در شرکت شده.\r\nکارمندان در صفى قرار گرفتند و یکى یکى نزدیک تابوت مى‌رفتند\r\nووقتى به درون تابوت نگاه مى‌کردند ناگهان خشکشان مى‌زد\r\nو زبانشان بند مى‌آمد.\r\nآینه‌اى درون تابوت قرار داده شده بود\r\nو هر کس به درون تابوت نگاه مى‌کرد، تصویر خود را مى‌دید.\r\nنوشته‌اى نیز بدین مضمون در کنار آینه بود:\r\nتنها1نفر وجود دارد که مى‌تواند مانع رشد شما شود و او هم خود شمایید.\r\nشما تنها کسی هستید که می توانید بر روی تصورات و موفقیت هایتان اثر گذار باشید.\r\nزندگی شما وقتی رئیستان،دوستانتان،والدینتان شریک زدگیتان تغییر کنند تغیير نمی کند\r\nزندگی شما وقتی تغیيرمیکند که شما تغیر کنید.\r\nجهان هرکس به اندازه ی وسعت دید اوست\r\nپس زیبا بیندیش\r\n"},{"id":1767,"category_id":10,"category_code":"s10","source_id":329,"title":"دیدن خدا","content":"\r\nدانشجویی به استادش گفت: \r\nاستاد ! اگر شما خدا را به من نشان بدهید عبادتش می کنم و تا وقتی خدا را نبینم او را عبادت نمی کنم! \r\nاستاد به انتهای کلاس رفت و به آن دانشجو گفت : آیا مرا می بینی ؟ دانشجو پاسخ داد : نه استاد ! وقتی پشت من به شما باشد مسلما شما را نمی بینم! \r\nاستاد کنار او رفت و نگاهی به او کرد و گفت : تا وقتی به خدا پشت کرده باشی او را نخواهی دید!\r\n"},{"id":1768,"category_id":10,"category_code":"s10","source_id":330,"title":"از فرصت ها استفاده کنید! ","content":"\r\nمردی با اسلحه وارد یک بانک شد و تقاضای پول کرد\r\nوقتی پولهارا دریافت کرد رو به یکی از مشتریان بانک کرد و پرسید : آیا شما دیدید که من از این بانک دزدی کنم؟\r\nمرد پاسخ داد : بله قربان من دیدم\r\nسپس دزد اسلحه را....\r\nبه سمت شقیقه مرد گرفت و اورا در جا کشت\r\nاو مجددا رو به زوجی کرد که نزدیک او ایستاده بودند و از آنها پرسید آیا شما دیدید که من از این بانک دزدی کنم؟\r\nمرد پاسخ داد : نه قربان. من ندیدم اما همسرم دید.\r\n"},{"id":1769,"category_id":10,"category_code":"s10","source_id":331,"title":"بز شما چیست؟ ","content":"روزگاری مرید ومرشدی خردمند در سفر بودند. در یکی از سفر هایشان در بیابانی گم شدند وتا آمدند راهی پیدا کنند شب فرا رسید. نا گهان از دور نوری دیدند وبا شتاب سمت آن رفتند. دیدند زنی در چادر محقری با چند فرزند خود زندگی می کند.آن ها آن شب را مهمان او شدند. واو نیز از شیر تنها بزی که داشت به آن ها داد تا گرسنگی راه بدر کنند.\r\nروز بعد مرید و مرشد از زن تشکر کردند و به راه خود ادامه دادند. در مسیر، مرید همواره در فکرآن زن بود و این که چگونه فقط با یک بز زندگی می گذرانند و ای کاش قادر بودند به آن زن کمک می کردند،تا این که به مرشد خود قضیه را گفت.مرشد فرزانه پس از اندکی تامل پاسخ داد:\"اگر واقعا می خواهی به آن ها کمک کنی برگرد و بزشان را بکش!\".\r\nمرید ابتدا بسیار متعجب شد ولی از آن جا که به مرشد خود ایمان داشت چیزی نگفت وبرگشت و شبانه بز را در تاریکی کشت واز آن جا دور شد....\r\nسال های سال گذشت و مرید همواره در این فکر بود که بر سر آن زن و بجه هایش چه آمد.\r\nروزی از روزها مرید ومرشد قصه ما وارد شهری زیبا شدند که از نظر تجاری نگین آن منطقه بود.سراغ تاجر بزرگ شهر را گرفتند و مردم آن ها را به قصری در داخل شهر راهنمایی کردند.صاحب قصر زنی بود با لباس های بسیار مجلل و خدم و حشم فراوان که طبق عادتش به گرمی از مسافرین استقبال و پذیرایی کرد، و دستور داد به آن ها لباس جدید داده  و اسباب راحتی و استراحت فراهم کنند. پس از استرا حت آن ها نزد زن رفتند تا از رازهای موفقیت وی جویا شوند. زن نیز چون آن ها را مرید و مرشدی فرزانه یافت، پذیرفت و شرح حال خود این گونه بیان نمود:\r\n\r\nسال های بسیار پیش من شوهرم را از دست دادم و با چند فرزندم و تنها بزی که داشتیم زندگی سپری می کردیم. یک روز صبح دیدیم که بزمان مرده و دیگر هیچ نداریم. ابتدا بسیار اندوهگین شدیم ولی پس از مدتی مجبور شدیم برای گذران زندگی با فرزندانم هر کدام به کاری روی آوریم.ابتدا بسیار سخت بود ولی کم کم هر کدام از فرزندانم موفقیت هایی در کارشان کسب کردند.فرزند بزرگ ترم زمین زراعی مستعدی در آن نزدیکی یافت. فرزند دیگرم معدنی از فلزات گرانبها پیدا کرد ودیگری با قبایل اطراف شروع به داد و ستد نمود. پس از مدتی با آن ثروت شهری را بنا نهادیم و حال در کنار هم زندگی می کنیم.\r\nمرید که پی به راز مسئله برده بود از خوشحالی اشک در چشمانش حلقه زده بود.\r\n"},{"id":1770,"category_id":10,"category_code":"s10","source_id":332,"title":"دو روز مانده به پایان جهان ","content":"دو روز مانده به پایان جهان، تازه فهمیده که هیچ زندگی نکرده است، تقویمش پر شده بود و تنها دو روز خط نخورده باقی مانده بود، پریشان شد. آشفته و عصبانی نزد فرشته مرگ رفت تا روزهای بیش‌تری از خدا بگیرد.\r\nداد زد و بد و بیراه گفت!(فرشته سکوت کرد)\r\nآسمان و زمین را به هم ریخت!(فرشته سکوت کرد)\r\nجیغ زد و جار و جنجال راه انداخت!(فرشته سکوت کرد)\r\nبه پرو پای فرشته پیچید!(فرشته سکوت کرد)\r\nکفر گفت و سجاده دور انداخت!(باز هم فرشته سکوت کرد)\r\nدلش گرفت و گریست به سجاده افتاد!\r\nاین بار فرشته سکوتش را شکست و گفت:...\r\nبدان که یک روز دیگر را هم از دست دادی! تنها یک روز دیگر باقی است. بیا و لااقل این یک روز را زندگی کن!\r\n\r\nلابلای هق هقش گفت: اما با یک روز... با یک روز چه کاری می‌توان کرد...؟\r\nفرشته گفت: آن کس که لذت یک روز زیستن را تجربه کند، گویی که هزار سال زیسته است و آن که امروزش را درنیابد، هزار سال هم به کارش نمی‌آید و آنگاه سهم یک روز زندگی را در دستانش ریخت و گفت: حالا برو و زندگی کن!\r\nاو مات و مبهوت به زندگی نگاه کرد که در گودی دستانش می‌درخشید. اما می‌ترسید حرکت کند! می‌ترسید راه برود! نکند قطره‌ای از زندگی از لای انگشتانش بریزد. قدری ایستاد، بعد با خود گفت: وقتی فردایی ندارم، نگاه داشتن این زندگی جه فایده ای دارد؟ بگذار این یک مشت زندگی را خرج کنم.\r\nآن وقت شروع به دویدن کرد. زندگی را به سرو رویش پاشید، زندگی را نوشید و بویید و چنان به وجد آمد که دید می‌تواند تا ته دنیا بدود، می‌تواند پا روی خورشید بگذارد و می‌تواند...\r\n\r\nاو در آن روز آسمان خراشی بنا نکرد، زمینی را مالک نشد، مقامی ‌را به دست نیاورد، اما... اما در همان یک روز روی چمن‌ها خوابید، کفش دوزکی را تماشا کرد، سرش را بالا گرفت و ابرها را دید و به آن‌هایی که نمی‌شناختنش سلام کرد و برای آن‌ها که دوستش نداشتند از ته دل دعا کرد.\r\nاو همان یک روز آشتی کرد و خندید و سبک شد و لذت برد و سرشار شد و بخشید، عاشق شد و عبور کرد و تمام شد!\r\nاو همان یک روز زندگی کرد، اما فرشته‌ها در تقویم خدا نوشتند: او درگذشت، کسی که هزار سال زیسته بود.\r\n"},{"id":1771,"category_id":10,"category_code":"s10","source_id":333,"title":"هیچوقت زود قضاوت نکن ","content":"مسئولین یک مؤسسه خیریه متوجه شدند که وکیل پولداری در شهرشان زندگی می‌کند و تا کنون حتی یک ریال هم به خیریه کمک نکرده است. پس یکی از افرادشان را نزد او فرستادند.\r\nمسئول خیریه: آقای وکیل ما در مورد شما تحقیق کردیم و متوجه شدیم که الحمدالله از درآمد بسیار خوبی برخوردارید ولی تا کنون هیچ کمکی به خیریه نکرده‌اید. نمی‌خواهید در این امر خیر شرکت کنید؟\r\nوکیل: آیا شما در تحقیقاتی که در مورد من کردید متوجه شدید...\r\nکه مادرم بعد از یک بیماری طولانی سه ساله، هفته پیش درگذشت و در طول آن سه سال، حقوق بازنشستگی‌اش کفاف مخارج سنگین درمانش را نمی‌کرد؟\r\nمسئول خیریه: (با کمی شرمندگی) نه، نمی‌دانستم. خیلی تسلیت می‌گویم.\r\nوکیل: آیا در تحقیقاتی که در مورد من کردید فهمیدید که برادرم در جنگ هر دو پایش را از دست داده و دیگر نمی‌تواند کار کند و زن و ۵ بچه دارد و سالهاست که خانه نشین است و نمی‌تواند از پس مخارج زندگیش برآید؟\r\nمسئول خیریه: (با شرمندگی بیشتر) نه . نمی‌دانستم. چه گرفتاری بزرگی ...\r\nوکیل: آیا در تحقیقاتتان متوجه شدید که خواهرم سالهاست که در یک بیمارستان روانی است و چون بیمه نیست در تنگنای شدیدی برای تأمین هزینه‌های درمانش قرار دارد؟\r\nمسئول خیریه که کاملاً شرمنده شده بود گفت: ببخشید. نمی‌دانستم اینهمه گرفتاری دارید .\r\n\r\nوکیل: خوب. حالا وقتی من به اینها یک ریال کمک نکرده‌ام شما چطور انتظار دارید به خیریه شما کمک کنم؟\r\n"},{"id":1772,"category_id":10,"category_code":"s10","source_id":334,"title":"نشانه های زن و شوهر! ","content":"\r\nزن و مرد از راهی می رفتند، ماموران آنها را دیدند وآنها را خواستند!\r\nپرسیدند شما چه نسبتی با هم دارید؟\r\nزن و مرد جواب دادند زن و شوهریم\r\nماموران مدرک خواستند،\r\nزن و مرد گفتند نداریم !\r\nماموران گفتند چگونه باور کنیم که شما زن و شوهرید ؟!\r\nزن و مرد گفتند ...\r\nبرای ثابت کردن این امرنشانه های فراوانی داریم ... !\r\n\r\nاول اینکه آن افرادی که شما می گویید دست در دست هم می روند،\r\nما دستهایمان از هم جداست!\r\nدوم، آنها هنگام راه رفتن و صحبت کردن به هم نگاه می کنند،\r\nما رویمان به طرف دیگریست!\r\nسوم آنکه آنها هنگام صحبت کردن و راه رفتن،با هم با احساس حرف می زنند،\r\nما احساسی به هم نداریم!\r\nچهارم آنکه آنها با هم بگو بخند می کنند،\r\nمی بینید که، ما غمگینیم!\r\nپنجم، آنها چسبیده به هم راه می روند،\r\nاما یکی ازما جلوترازدیگری می رود!\r\nششم آنکه آنها هنگام با هم بودن کیکی، بستنی ای، چیزی می خورند،\r\nما هیچ نمی خوریم!\r\nهفتم، آنها هنگام با هم بودن بهترین لباسهایشان را می پوشند،\r\nما لباسهای کهنه تنمان است.. !\r\n\r\nهشتم، ...\r\nماموران گفتند\r\nخیلی خوب،\r\nبروید،\r\nبروید،..\r\nفقط بروید ... !\r\n"},{"id":1773,"category_id":10,"category_code":"s10","source_id":335,"title":"تغییر نگرش ","content":"میگویند در کشور ژاپن مرد میلیونری زندگی میکرد که از درد چشم خواب بچشم نداشت و برای مداوای چشم دردش انواع قرصها و آمپولها را بخود تزریق کرده بود اما نتیجه چندانی نگرفته بود. وی پس از مشاوره فراوان با پزشکان و متخصصان زیاد درمان درد خود را مراجعه به یک راهب مقدس و شناخته شده میبیند.\r\nوی به راهب مراجعه میکند و راهب نیز پس از معاینه وی به او پیشنهاد کرد ....\r\nکه مدتی به هیچ رنگی بجز رنگ سبز نگاه نکند.وی پس از بازگشت از نزد راهب به تمام مستخدمین خود دستور میدهد با خرید بشکه های رنگ سبز تمام  خانه را با سبز رنگ آمیزی کند . همینطور تمام اسباب و اثاثیه خانه را با همین رنگ عوض میکند. پس از مدتی رنگ ماشین ، ست لباس اعضای خانواده و مستخدمین و هر آنچه به چشم می آید را به رنگ سبز و ترکیبات آن تغییر میدهد و البته چشم دردش هم تسکین می یابد.\r\nبعد از مدتی مرد میلیونر برای تشکر از راهب وی را به منزلش دعوت می نماید. راهب نیز که با لباس نارنجی رنگ به منزل او وارد میشود متوجه میشود که باید لباسش را عوض کرده و خرقه ای به رنگ سبز به تن کند. او نیز چنین کرده و وقتی به محضر بیمارش میرسد از او می پرسد آیا چشم دردش تسکین یافته ؟ مرد ثروتمند نیز تشکر کرده و میگوید :\" بله . اما این گرانترین مداوایی بود که تاکنون داشته.\"\r\nمرد راهب با تعجب به بیمارش میگوید بالعکس این ارزانترین نسخه ای بوده که تاکنون تجویز کرده ام. برای مداوای چشم دردتان،  تنها کافی بود عینکی با شیشه سبز خریداری کنید و هیچ نیازی به این همه مخارج نبود.برای این کار نمیتوانی تمام دنیا را تغییر دهی، بلکه با تغییر چشم اندازت(نگرش) میتوانی دنیا را به کام خود درآوری. تغییر دنیا کار احمقانه ای است اما تغییر چشم اندازمان(نگرش) ارزانترین و موثرترین روش میباشد.\r\n"},{"id":1774,"category_id":10,"category_code":"s10","source_id":336,"title":"همیشه راهکار ساده تری نیز هست! ","content":"در یک شرکت بزرگ ژاپنی که تولید وسایل آرایشی را برعهده داشت ، یک  مورد تحقیقاتی به یاد ماندنی اتفاق افتاد :  \r\nشکایتی از سوی یکی مشتریان به کمپانی رسید . او  اظهار داشته  بود  که  هنگام  خرید  یک بسته صابون  متوجه شده بود که  آن قوطی خالی است.\r\nبلافاصله  با تاکید و پیگیریهای مدیریت ارشد  کارخانه  این مشکل  بررسی و ...\r\nدستور صادر شد که خط بسته بندی اصلاح گردد و قسمت فنی  و مهندسی نیز تدابیر لازمه را جهت پیشگیری از تکرار چنین مسئله ای اتخاذ نماید  .  مهندسین نیز دست به کار شده و راه حل پیشنهادی خود را چنین ارائه دادند :\r\nپایش ( مونیتورینگ )  خط بسته بندی با اشعه ایکس\r\nبزودی سیستم مذکور خریداری شده و با تلاش شبانه روزی گروه مهندسین ،‌ دستگاه تولید اشعه ایکس و مانیتورهائی با رزولیشن بالا نصب شده  و خط مذبور تجهیز گردید  . سپس دو نفر اپراتور نیز جهت کنترل دائمی پشت آن دستگاهها به کار گمارده شدند  تا از عبور احتمالی قوطیهای خالی  جلوگیری نمایند .     \r\n\r\nنکته جالب توجه در این بود که درست همزمان با این ماجرا ،  مشکلی مشابه  نیز در یکی از کارگاههای کوچک تولیدی پیش آمده بود اما آنجا  یک  کارمند معمولی و غیر متخصص آنرا به شیوه ای بسیار ساده تر و کم خرجتر حل کرد :  \r\nتعبیه یک دستگاه پنکه در مسیر خط  بسته بندی\r\nتا قوطی خالی را باد ببرد!!!!\r\n"},{"id":1775,"category_id":10,"category_code":"s10","source_id":337,"title":"جذابیت انسانی ","content":"دختر دانش آموزی صورتی زشت داشت . دندان هایی نامتناسب با گونه هایش ، موهای کم پشت و رنگ چهره ای تیره . روز اولی که به مدرسه جدیدی آمد ، هیچ دختری حاضر نبود کنار او بنشیند . نقطه مقابل او دختر زیبارو و پولداری بود که مورد توجه همه قرار داشت . او در همان روز اول مقابل تازه وارد ایستاد و از او پرسید :\r\n‘میدونی زشت ترین دختر این کلاسی ؟ ‘\r\nیک دفعه کلاس از خنده ترکید …\r\nبعضی ها هم اغراق آمیزتر می خندیدند . اما تازه وارد با نگاهی مملو از مهربانی و عشق در جوابش جمله ای گفت که موجب شد در همان روز اول، احترام ویژه ای در میان همه و از جمله من پیدا کند :\r\nاما بر عکس من ، تو بسیار زیبا و جذاب هستی .\r\nاو با همین یک جمله نشان داد که قابل اطمینان ترین فردی است که می توان به او اعتماد کرد و لذا کار به جایی رسید که برای اردوی آخر هفته همه می خواستند با او هم گروه باشند .\r\nاو برای هر کسی نام مناسبی انتخاب کرده بود . به یکی می گفت چشم عسلی و به یکی ابرو کمانی و … . به یکی از دبیران ، لقب خوش اخلاق ترین معلم دنیا و به مستخدم مدرسه هم محبوب ترین یاور دانش آموزان را داده بود . آری ویژگی برجسته او در تعریف و تمجید هایش از دیگران بود که واقعاً به حرف هایش ایمان داشت و دقیقاً به جنبه های مثبت فرد اشاره می کرد . مثلاً به من می گفت بزرگترین نویسنده دنیا و به خواهرم می گفت بهترین آشپز دنیا ! و حق هم داشت . آشپزی خواهرم حرف نداشت و من از این تعجب کرده بودم که او توی هفته اول چگونه این را فهمیده بود .\r\nسالها بعد وقتی او به عنوان شهردار شهر کوچک ما انتخاب شده بود به دیدنش رفتم و بدون توجه به صورت ظاهری اش احساس کردم شدیداً به او علاقه مندم .\r\nپنج سال  پیش وقتی برای خواستگاری اش رفتم ، دلیل علاقه ام را جذابیت سحر آمیزش می دانستم و او با همان سادگی و وقار همیشگی اش گفت :\r\n‘برای دیدن جذابیت یک چیز ، باید قبل از آن جذاب بود ! ‘\r\nدر حال حاضر من از او یک دختر سه ساله دارم . دخترم بسیار زیبا ست و همه از زیبایی صورتش در حیرتند .\r\nروزی مادرم از همسرم سؤال کرد که راز زیبایی دخترمان در چیست ؟\r\nهمسرم جواب داد :\r\nمن زیبایی چهره دخترم را مدیون خانواده پدری او هستم .\r\nو مادرم روز بعد نیمی از دارایی خانواده را به ما بخشید .\r\n"},{"id":1776,"category_id":10,"category_code":"s10","source_id":338,"title":"انتخاب همسر ","content":"جوانی می خواست زن بگیرد به پیرزنی سفارش کرد تا برای او دختری پیدا کند. پیرزن به جستجو پرداخت، دختری را پیدا کرد و به جوان معرفی کرد وگفت این دختر از هر جهت سعادت شما را در زندگی فراهم خواهد کرد. \r\nجوان گفت: شنیده ام قد او کوتاه است! \r\nپیرزن گفت:اتفاقا این صفت بسیار خوبی است، زیرا لباس های خانم ارزان تر تمام می شود! \r\nجوان گفت: شنیده ام زبانش هم لکنت دارد! \r\nپیرزن گفت: این هم دیگر نعمتی است زیرا ...\r\nمی دانید که عیب بزرگ زن ها پر حرفی است اما این دختر چون لکنت زبان دارد پر حرفی نمی کند و سرت را به درد نمی آورد! \r\nجوان گفت: خانم همسایه گفته است که چشمش هم معیوب است! \r\nپیرزن گفت: درست است ، این هم یکی از خوشبختی هاست که کسی مزاحم آسایش شما نمی شود و به او طمع نمی برد. \r\nجوان گفت: شنیده ام پایش هم می لنگد و این عیب بزرگی است! \r\nپیرزن گفت: شما تجربه ندارید، نمی دانید که این صفت ، باعث می شود که خانمتان کمتر از خانه بیرون برود و علاوه بر سالم ماندن، هر روز هم از خیابان گردی ، خرج برایت نمی تراشد! \r\nجوان گفت: این همه به کنار، ولی شنیده ام که عقل درستی هم ندارد! \r\nپیرزن گفت: ای وای، شما مرد ها چقدر بهانه گیر هستید، پس یعنی می خواستی عروس به این نازنینی، این یک عیب کوچک را هم نداشته\r\n"},{"id":1777,"category_id":10,"category_code":"s10","source_id":339,"title":"امروز ظهر شیطان را دیدم ! ","content":"نشسته بر بساط صبحانه و آرام لقمه برمیداشت...\r\nگفتم: ظهر شده، هنوز بساط کار خود را پهن نکرده ای؟ بنی آدم نصف روز خود را بی تو گذرانده اند...\r\nشیطان گفت: خود را بازنشسته کرده ام. پیش از موعد!\r\nگفتم:...\r\nبه راه عدل و انصاف بازگشته ای یا سنگ بندگی خدا به سینه می زنی؟\r\n\r\n گفت: من دیگر آن شیطان توانای سابق نیستم. دیدم انسانها، آنچه را من شبانه به ده ها وسوسه پنهانی انجام میدادم، روزانه به صدها دسیسه آشکارا انجام میدهند. اینان را به شیطان چه نیاز است؟\r\nشیطان در حالی که بساط خود را برمیچید تا در کناری آرام بخوابد، زیر لب گفت: آن روز که خداوند گفت بر آدم و نسل او سجده کن، نمیدانستم که نسل او در زشتی و دروغ و خیانت، تا کجا میتواند فرا رود، و گرنه در برابر آدم به سجده می رفتم و میگفتم که : همانا تو خود پدر منی.\r\n"},{"id":1778,"category_id":10,"category_code":"s10","source_id":340,"title":"این است مردانگی.... ","content":"او دزدى ماهر بود و با چند نفر از دوستانش باند سرقت تشکیل داده بودند. روزى با هم نشسته بودند و گپ مى زدند. \r\nدر حین صحبتهاشان گفتند: چرا ما همیشه با فقرا و آدمهایى معمولى سر و کار داریم و قوت لایموت آنها را از چنگشان بیرون مى آوریم؟! بیائید این بار خود را به خزانه سلطان بزنیم که تا آخر عمر برایمان بس باشد. \r\nالبته دسترسى به خزانه سلطان هم کار آسانى نبود. آنها ...\r\nتمامى راهها و احتمالات ممکن را بررسى کردند، این کار مدتى فکر و ذکر آنها را مشغول کرده بود، تا سرانجام بهترین راه ممکن را پیدا کردند و خود را به خزانه رسانیدند. \r\nخزانه مملو از پول و جواهرات قیمتى و ... بود. آنها تا مى توانستند از انواع و اقسام طلاجات و عتیقه جات در کوله بار خود گذاشتند تا ببرند. در این هنگام چشم سر کرده باند به شى ء درخشنده و سفیدى افتاد، گمان کرد گوهر شب چراغ است، نزدیکش رفت آن را برداشت و براى امتحان به سر زبان زد، معلوم شد نمک است!\r\nبسیار ناراحت و عصبانى شد و از شدت خشم و غضب دستش را بر پیشانى زد بطورى که رفقایش متوجه او شدند و خیال کردند اتفاقى پیش آمد یا نگهبانان خزانه با خبر شدند. خیلى زود خودشان را به او رسانیدند و گفتند: چه شد؟ چه حادثه اى اتفاق افتاد؟ او که آثار خشم و ناراحتى در چهره اش پیدا بود گفت : افسوس که تمام زحمتهاى چندین روزه ما به هدر رفت و ما نمک گیر سلطان شدیم، من ندانسته نمکش را چشیدم، دیگر نمى شود مال و دارایى پادشاه را برد، از مردانگى و مروت به دور است که ما نمک کسى را بخوریم و نمکدان او را هم بشکنیم و ... \r\n\r\nآنها در آن دل سکوت سهمگین شب، بدون این که کسى بویى ببرد دست خالى به خانه هاشان باز گشتند. صبح که شد و چشم نگهبانان به درهاى باز خزانه افتاد تازه متوجه شدند که شب خبرهایى بوده است، سراسیمه خود را به جواهرات سلطنتى رسانیدند، دیدند سر جایشان نیستند، اما در آنجا بسته هایى به چشم مى خورد، آنها را که باز کردند دیدند جواهرات در میان بسته ها مى باشد، بررسى دقیق که کردند دیدند که دزد خزانه را نبرده است و گرنه الآن خدا مى داند سلطان با ما چه مى کرد و ... \r\nبالاخره خبر به گوش سلطان رسید و خود او آمد و از نزدیک صحنه را مشاهده کرد، آنقدر این کار برایش عجیب و شگفت آور بود که انگشتش را به دندان گرفته و با خود مى گفت : عجب ! این چگونه دزدى است ؟ براى دزدى آمده و با آنکه مى توانسته همه چیز را ببرد ولى چیزى نبرده است ؟ آخر مگر مى شود؟ چرا؟... ولى هر جور که شده باید ریشه یابى کنم و ته و توى قضیه را در آورم ...\r\nدر همان روز اعلام کرد: هر کس شب گذشته به خزانه آمده در امان است او مى تواند نزد من بیاید، من بسیار مایلم از نزدیک او را ببینم و بشناسم.\r\n\r\nاین اعلامیه سلطان به گوش سرکرده دزدها رسید، دوستانش را جمع کرد و به آنها گفت : سلطان به ما امان داده است، برویم پیش او تا ببینیم چه مى گوید. آنها نزد سلطان آمده و خود را معرفى کردند، سلطان که باور نمى کرد دوباره با تعجب پرسید: این کار تو بوده ؟ گفت : آرى.\r\nسلطان پرسید: چرا آمدى دزدى و با این که مى توانستى همه چیز را ببرى ولى چیزى را نبردى؟\r\nگفت : چون نمک شما را چشیدم و نمک گیر شدم و بعد جریان را مفصل براى سلطان گفت ...\r\n\r\nسلطان به قدرى عاشق و شیفته کرم و بزرگوارى او شد که گفت : حیف است جاى انسان نمک شناسى مثل تو، جاى دیگرى باشد، تو باید در دستگاه حکومت من کار مهمى را بر عهده بگیرى، و حکم خزانه دارى را براى او صادر کرد.\r\nآرى او یعقوب لیث صفاری بود و پس از چند سالى حکمرانى در مسند خود سلسله صفاریان را تاسیس نمود. یعقوب لیث صفاری سردار بزرگ و نخستین شهریار ایرانی (پس از اسلام) قرون متوالی است که در آرامگاهش واقع در روستای شاه‌آباد واقع در 10 کیلومتری دزفول بطرف شوشتر آرمیده است. گفتنی است در کنار این آرامگاه بازمانده‌های شهر گندی شاپور نیز دیده می‌شود.\r\n"},{"id":1779,"category_id":10,"category_code":"s10","source_id":341,"title":"گرگ و پیرزن ","content":"گرگ گرسنه‌ای برای تهیة غذا به شکار رفت. در کلبه‌ای در حاشیة دهکده پسر کوچکی داشت گریه می‌کرد و گرگ صدای پیرزنی را شنید که داشت به او می‌گفت: «اگر دست از گریه و زاری برنداری تو را به گرگ می‌دهم.»\r\nگرگ از آن‌جا رفت و....\r\nنشست و منتظر ماند تا پسر کوچولو را به او بدهند. شب فرا رسید و او هنوز انتظار می‌کشید. ناگهان صدای پیرزن را شنید که می‌گوید: «کوچولو گریه نکن، من تو را به گرگ نمی‌دهم. بگذار همین که گرگ پیر بیاید او را می‌کشیم.»\r\nگرگ با خود گفت: «انگار این‌جا آدم‌هایی پیدا می‌شوند که چیزی می‌گویند اما کار دیگری می‌کنند.»\r\nو بلند شد و روستا را ترک گفت.\r\n"},{"id":1780,"category_id":10,"category_code":"s10","source_id":342,"title":"راز خوشبختی در زندگی مشترک ","content":"روزی یک زوج،بیست و پنجمین سالگرد ازداوجشان را جشن گرفتند.آنها در شهر مشهور شده بودند به خاطر اینکه در طول 25 سال حتی کوچکترین اختلافی با هم نداشتند.تو این مراسم سردبیرهای روزنامه های محلی هم جمع شده بودند تا علت مشهور بودنشون (راز خوشبختی شون رو) بفهمند.\r\n\r\nسردبیر میگه:آقا واقعا باور کردنی نیست؟ یه همچین چیزی چطور ممکنه؟\r\nشوهره روزای ماه عسل رو بیاد میاره و میگه:بعد از ازدواج برای ماه عسل به شمیلا رفتیم،اونجا ...\r\nبرای اسب سواری هر دو،دو تا اسب مختلف انتخاب کردیم.اسبی که من انتخاب کرده بودم خیلی خوب بود ولی اسب همسرم به نظر یه کم سرکش بود.سر راهمون اون اسب ناگهان پرید و همسرم رو زین انداخت .\r\nهمسرم خودشو جمع و جور کرد و به پشت اسب زد و گفت :\"این بار اولته\" دوباره سوار اسب شد و به راه افتاد.بعد یه مدتی دوباره همون اتفاق افتاد این بار همسرم نگاهی با آرامش به اسب انداخت و گفت:\"این دومین بارت\" بعد بازم راه افتادیم .وقتی که اسب برای سومین بار همسرم رو انداخت خیلی با آرامش تفنگشو از کیف برداشت و با آرامش شلیک کرد و اونو کشت.\r\nسر همسرم داد کشیدم و گفتم :\"چیکار کردی روانی؟ حیوان بیچاره رو کشتی!دیونه شدی؟\"\r\nهمسرم با خونسردی یه نگاهی به من کرد و گفت:\"این بار اولت بود.\r\n"},{"id":1781,"category_id":10,"category_code":"s10","source_id":343,"title":"زن زیبا ","content":"\r\nیکی از دوستانم با یک زن بازیگر معروف که فوق‌العاده زیبا است ازدواج کرد.\r\nاما درست زمانی که همه به خوشبختی این زن و شوهر غبطه می‌خوردند، آنها از هم جدا شدند.\r\nطولی نکشید که دوستم دوباره ازدواج کرد. همسر دومش یک دختر عادی با چهره‌ای بسیار معمولی است. \r\nاما به نظر می‌رسد که دوستم بیشتر و عمیق‌تر از گذشته عاشق همسرش است.\r\n\r\nعده‌ای آدم فضول در اطراف از او می‌پرسند:...\r\nفکر نمی‌کنی همسر قبلی‌ات خوشگل‌تر بود؟  \r\nدوستم با قاطعیت به آنها جواب می‌دهد: نه! اصلاً! اتفاقا وقتی از چیزی عصبانی میشد و فریاد میزد، خیلی وحشی و زشت به نظرم می‌رسید.\r\nاما هسمر کنونی‌ام این طور نیست. به نظر من او همیشه زیبا، با سلیقه و باهوش است.  \r\nوقتی این حرف را می‌زند، دوستانش می‌خندند و می‌گویند : کاملا متوجه شدیم...\r\nمی‌گویند :   \r\nزن‌ها به خاطر زیبا بودنشان دوست داشتنی نمی‌شوند، بلکه اگر دوست داشتنی باشند، زیبا به نظر می‌رسند.\r\nبچه‌ها هرگز مادرشان را زشت نمی‌دانند؛  \r\nسگ‌ها اصلا به صاحبان فقیرشان پارس نمی‌کنند.\r\nاسکیموها هم از سرمای آلاسکا بدشان نمی‌آید.\r\nاگر کسی یا جایی را دوست داشته باشید، آنها را زیبا هم خواهید یافت.   \r\nزیرا \"حس زیبا دیدن\" همان عشق است ... \r\n"},{"id":1782,"category_id":10,"category_code":"s10","source_id":344,"title":"وای از دست خانم ها ","content":"روزی خانمی در حال بازی گلف بود که توپش تو جنگل افتاد. او دنبال توپ رفت و دید که یک قورباغه در تله گیر کرده است. \r\nقورباغه به او گفت : اگر مرا از این تله آزاد کنی سه آرزوی تو را برآورده می کنم . \r\nزن قورباغه را آزاد کرد و قورباغه گفت : \"متشکرم\" ولی من یادم رفت بگویم شرایطی برای آرزوهایت هست؛ هر آرزویی داشته باشی شوهرت 10 برابر آن را میگیرد. \r\nزن گفت :....\r\nاشکال ندارد ! \r\nزن برای اولین آرزویش میخواست که زیباترین زن دنیا شود ! \r\nقورباغه اخطار داد که شما متوجه هستید با این آرزو شوهر شما نیز جذابترین مرد دنیا می شود و تمام زنان به او جذب خواهند شد ؟ \r\nزن جواب داد : اشکالی ندارد من زیباترین زن جهان خواهم شد و او فقط به من نگاه میکند ! \r\nبنابراین اجی مجی ....... و او زیباترین زن جهان شد ! \r\nبرای آرزوی دوم خود، زن میخواست که ثروتمندترین زن جهان باشد ! \r\nقورباغه گفت : این طوری شوهرت ثروتمندترین مرد جهان خواهد شد و او 10 برابر از تو ثروتمندتر می شود. \r\nزن گفت اشکالی ندارد ! چون هرچه من دارم مال اوست و هرچه او دارد مال من است ... \r\nبنابراین اجی مجی ....... و او ثروتمندترین زن جهان شد ! \r\nسپس قورباغه از آرزوی سوم زن سوال کرد و او جواب داد : \r\nمن دوست دارم که یک سکته قلبی خفیف بگیرم و شوهرم...!!!\r\n"},{"id":1783,"category_id":10,"category_code":"s10","source_id":345,"title":"چه کسی موثرتر هست، زن یا مرد؟ ","content":"توماس هیلر ، مدیر اجرایی شرکت بیمه عمر ماساچوست ، میو چوال و همسرش در بزرگراهی بین ایالتی در حال رانندگی بودند که او متوجه شد بنزین اتومبیلش کم است. هیلر به خروجی بعدی پیچید و از بزرگراه خارج شد و خیلی زود یک پمپ بنزین مخروبه که فقط یک پمپ داشت پیدا کرد.او از تنها مسئول آن خواست باک بنزین را پر و روغن اتومبیل را بازرسی کند.سپس ...\r\nبرای رفع خستگی پاهایش به قدم زدن در اطراف پمپ بنزین پرداخت.\r\nاو هنگامی که به سوی اتومبیل خود باز می گشت ، دید که متصدی پمپ بنزین و همسرش گرم گفتگو هستند. وقتی او به داخل اتومبیل برگشت ، دید که متصدی پمپ بنزین دست تکان می دهد و شنید که می گوید :” گفتگوی خیلی خوبی بود.”\r\nپس از خروج از جایگاه ، هیلر از زنش پرسید که آیا آن مرد را می شناسد.او بی درنگ پاسخ داد که می شناسد.آنان در دوران تحصیل به یک دبیرستان می رفتند و یک سال هم با هم نامزد بوده اند.\r\nهیلر با لحنی آکنده از غرور گفت :” هی خانم ، شانس آوردی که من پیدا شدم . اگر با اون ازدواج می کردی به جای زن مدیر کل، همسر یک کارگر پمپ بنزین شده بودی.\r\n” زنش پاسخ داد :” عزیزم ، اگر من با او ازدواج می کردم ، اون مدیر کل بود و تو کارگر پمپ بنزین .”\r\n"},{"id":1784,"category_id":10,"category_code":"s10","source_id":346,"title":"چهار سخنی که زاهد را تکان داد! ","content":"زاهدی گوید:\r\nجواب چهار نفر مرا سخت تکان داد . اول مرد فاسدی از کنار من گذشت و من گوشه لباسم را جمع کردم تا به او نخورد . او گفت ای شیخ خدا میداند که فردا حال ما چه خواهد بود!\r\n\r\nدوم مستی دیدم که ...\r\nافتان و خیزان راه میرفت به او گفتم قدم ثابت بردار تا نیفتی . گفت تو با این همه ادعا قدم ثابت کرده ای؟\r\nسوم کودکی دیدم که چراغی در دست داشت گفتم این روشنایی را از کجا اورده ای ؟ کودک چراغ را فوت کرد و ان را خاموش ساخت و گفت:تو که شیخ شهری بگو که این روشنایی کجا رفت؟\r\nچهارم زنی بسیار زیبا که درحال خشم از شوهرش شکایت میکرد . گفتم اول رویت را بپوشان بعد با من حرف بزن .\r\n گفت من که غرق خواهش دنیا هستم  چنان از خود بیخود شده ام که از خود خبرم نیست تو چگونه غرق محبت خالقی که از نگاهی بیم داری؟\r\n"},{"id":1785,"category_id":10,"category_code":"s10","source_id":347,"title":"عروسک چهارم و شاهزاده ","content":"روزی عارف پیری با مریدانش از کنار قصر پادشاه گذر میکرد. شاه که در ایوان کاخش مشغول به تماشا بود، او را دید و بسرعت به نگهبانانش دستور داد تا استاد پیر را به قصر آورند.\r\nعارف به حضور شاه شرفیاب شد. شاه ضمن تشکر از او...\r\nخواست که نکته ای آموزنده به شاهزاده جوان بیاموزد مگر در آینده او تاثیر گذار شود. استاد دستش را به داخل کیسه فرو برد و سه عروسک از آن بیرون آورد و به شاهزاده عرضه نمود و گفت: \"بیا اینان دوستان تو هستند، اوقاتت را با آنها سپری کن.\"\r\nشاهزاده با تمسخر گفت: \" من که دختر نیستم با عروسک بازی کنم! \" عارف اولین عروسک را برداشته و تکه نخی را از یکی از گوشهای آن عبور داد که بلافاصله از گوش دیگر خارج شد.\r\nسپس دومین عروسک را برداشته و اینبار تکه نخ از گوش عروسک داخل و از دهانش خارج شد. او سومین عروسک را امتحان نمود.\r\nتکه نخ در حالی که در گوش عروسک پیش میرفت، از هیچیک از دو عضو یادشده خارج نشد. استاد بلافاصله گفت : \" جناب شاهزاده، اینان همگی دوستانت هستند، اولی که اصلا به حرفهایت توجهی نداشته، دومی هرسخنی را که از تو شنیده، همه جا بازگو خواهد کرد و سومی دوستی است که همواره بر آنچه شنیده لب فرو بسته \" شاهزاده فریاد شادی سر داده و گفت: \" پس بهترین دوستم همین نوع سومی است و منهم او را مشاور امورات کشورداری خواهم نمود. \"\r\nعارف پاسخ داد : \" نه \" و بلافاصله عروسک چهارم را از کیسه خارج نمود و آنرا به شاهزاده داد و گفت: \" این دوستی است که باید بدنبالش بگردی \" شاهزاده تکه نخ را بر گرفت و امتحان نمود. با تعجب دید که نخ همانند عروسک اول از گوش دیگر این عروسک نیز خارج شد، گفت : \" استاد اینکه نشد ! \"\r\nعارف پیر پاسخ داد: \" حال مجددا امتحان کن \" برای بار دوم تکه نخ از دهان عروسک خارج شد. شاهزاده برای بار سوم نیز امتحان کرد و تکه نخ در داخل عروسک باقیماند استاد رو به شاهزاده کرد و گفت: \" شخصی شایسته دوستی و مشورت توست که بداند کی حرف بزند، چه موقع به حرفهایت توجهی نکند و کی ساکت بماند.\r\n"},{"id":1786,"category_id":10,"category_code":"s10","source_id":348,"title":"ما ایرانی ها.... ","content":"ما ایرانی ها صبح در تهران از خواب بیدار می شویم. محل شرکت تجاری و مرکز خریدمان در دبی است؛ \r\nاستعدادمان در تهران کشف شده، اما نبوغمان در اروپا شکوفا می شود؛ \r\nبرای تحصیل به فرانسه یا لندن می رویم، اما چون از کار در اروپا خوشمان نمی آید، در ایالات متحده آمریکا کار می کنیم، و هر وقت بیکار شدیم برای گرفتن حقوق بیکاری به اروپای مرکزی می رویم؛ \r\nبرنامه های تلویزیونی مان از لوس آنجلس پخش و در...\r\nخرم آباد دریافت می شود. فیلم های مان را در بیابان های ایران می سازیم، اما در ونیز و پاریس و برلین آنها را نمایش می دهیم و از آنجا جایزه فیلمسازی می گیریم؛ \r\nدر کلن طرفدار جمهوری و در تهران طرفدار سلطنت هستیم؛ \r\nمهم ترین مقالات سیاسی مان در اوین نوشته می شود، اما در پاریس خوانده می شود؛ \r\nاز واشنگتن نامزد انتخابات می شویم، اما صلاحیتمان در تهران رد می شود، بنابراین در برلین انتخابات را تحریم می کنیم و در لندن تصمیم می گیریم رفراندوم برگزار کنیم؛ \r\nدر هلند عضو پارلمان و در اسرائیل رئیس جمهور می شویم، در تهران با حکومت مخالفت می کنیم، در عراق با حکومت می جنگیم، اما در لبنان از حکومت دفاع می کنیم؛ \r\nدر تهران کنسرت موسیقی راک برگزار می کنیم، ما در فرانکفورت کنسرت موسیقی سنتی مان با استقبال آلمانی ها روبرو می شود؛ \r\nدر آنکارا در کنسرت موسیقی پاپ ایرانی شرکت می کنیم، اما در آنتالیا می رقصیم، در کانادا برنده مسابقه ملکه زیبایی می شویم، حقوق زنانمان در مشهد نقض می شود، اما در سوئد از حقوق زنان دفاع می کنیم؛ \r\nولیعهدمان در امریکاست، ملکه مان در یکی از شهرهای فرانسه زندگی می کند، رئیس جمهور سابقمان در پاریس زندگی می کند، رئیس قوه قضائیه مان متولد عراق است، در عوض نخست وزیر عراق سالها در ایران زندگی می کرد و رئیس جمهور اسرائیل متولد ایران است؛ \r\nدر ایران زندگی می کنیم، در ترکیه تفریح می کنیم، در آمریکا پولدار می شویم و برای مرگ به ایران برمی گردیم. در نهایت هم از وضع موجود ناراضی هستیم.\r\n"},{"id":1787,"category_id":10,"category_code":"s10","source_id":349,"title":"مدیرارشد ","content":"مردی به یک مغازه فروش حیوانات رفت و درخواست یک طوطی کرد.\r\nصاحب فروشگاه به سه طوطی خوش چهره اشاره کرد و گفت: طوطی سمت چپ ۵۰۰ دلار است.\r\nمشتری: چرا این طوطی اینقدر گران است؟\r\nصاحب فروشگاه: این طوطی توانایی انجام تحقیقات علمی و فنی دارد.\r\nمشتری: قیمت طوطی وسطی چقدر است؟‌\r\nصاحب فروشگاه: ...\r\nطوطی وسطی ۱۰۰۰ دلار است. برای اینکه این طوطی هر کاری را که سایر طوطی ها انجام می دهند، انجام داده و علاوه بر این توانایی نوشتن مقاله ای که در هر مسابقه ای پیروز شود را نیز دارد.\r\nو سرانجام مشتری از طوطی سوم پرسیده و صاحب فروشگاه گفت:  ۴۰۰۰ دلار !\r\nمشتری: این طوطی چه کاری می تواند انجام دهد؟\r\nصاحب فروشگاه جواب داد: صادقانه بگویم من چیز خاصی از این طوطی ندیدم ولی دو طوطی دیگر او را مدیر ارشد صدا می زنند!\r\n"},{"id":1788,"category_id":10,"category_code":"s10","source_id":350,"title":"وعده ","content":"پادشاهى در یک شب سرد زمستان از قصر خارج شد. هنگام بازگشت سرباز پیرى را دید که با لباسى اندک در سرما نگهبانى مى‌داد.\r\nاز او پرسید: آیا سردت نیست؟ \r\nنگهبان پیر گفت: چرا اى پادشاه اما لباس گرم ندارم و مجبورم تحمل کنم. \r\nپادشاه گفت:....\r\nمن الان داخل قصر مى‌روم و مى‌گویم یکى از لباس‌هاى گرم مرا برایت بیاورند.\r\nنگهبان ذوق زده شد و از پادشاه تشکر کرد. اما پادشاه به محض ورود به داخل قصر وعده‌اش را فراموش کرد.\r\nصبح روز بعد جسد سرمازده پیرمرد را در حوالى قصر پیدا کردند، در حالى که در کنارش با خطى ناخوانا نوشته بود:\r\nاى پادشاه من هر شب با همین لباس کم سرما را تحمل مى‌کردم اما وعده لباس گرم تو مرا از پاى درآورد!\r\n"},{"id":1789,"category_id":10,"category_code":"s10","source_id":351,"title":"امنیت، آزاد و نان ","content":"نیمروز بود کشاورز و خانواده اش برای نهار خود را آماده می کردند یکی از فرزندان گفت در کنار رودخانه هزاران سرباز اردو زده اند چادری سفید رنگ هم در آنجا بود که فکر می کنم پادشاه ایران در میان آنان باشد سه پسر از میان هفت فرزند او بلند شدند به پدر رو کردند و گفتند زمان مناسبی است که ما را به خدمت ارتش ایران زمین درآوری ، پدر از این کار آنان ناراضی بود اما به خاطر خواست پیگیر آنها پذیرفت و به همراهشان به سوی اردو رفت .\r\n\r\nدو جنگاور در کنار درختی ایستاده بودند که با دیدن پدر و سه پسرش پیش آمدند :...\r\nجنگاوری رشید که سیمایی مردانه داشت پرسید چرا به سپاه ایران نزدیک می شود . پدر گفت فرزندانم می خواهند همچون شما سرباز ایران شوند .\r\nجنگاور گفت تا کنون چه می کردند . پدر گفت همراه من کشاورزی می کنند .\r\nجنگاور نگاهی به سیمای سه برادر افکند و گفت و اگر آنان همراه ما به جنگ بیایند زمین های کشاورزیت را می توانی اداره کنی ؟\r\nپیرمرد گفت آنگاه قسمتی از زمین ها همچون گذشته برهوت خواهد شد .\r\nجنگاور گفت : دشمن کشور ما تنها سپاه آشور نیست دشمن بزرگتری که مردم ما را به رنج و نابودی می افکند گرسنگی است کارزار شما بسیار دشوارتر از جنگ در میدانهای نبرد است .\r\nآنگاه روی برگرداند و گفت مردم ما تنها پیروزی نمی خواهند آنها باید شکم کودکانشان را سیر کنند . و از آنها دور شد .\r\n\r\nجنگاور دیگری که ایستاده بود به آنها گفت سخن پادشاه ایران فرورتیش ( فرزند بنیانگذار ایران دیاکو ) ! را بگوش بگیرید و کشاورزی کنید . و سپس او هم از پدر و سه برادر دور شد .\r\nفرزند بزرگ رو به پدر پیرش کرد و گفت : پدر بی مهری های ما را ببخش تا پایان زندگی سربازان تو خواهیم بود . ارد بزرگ خردمند برجسته کشورمان می گوید : فرمانروایان همواره سه کار مهم در برابر مردم دارند . نخست : امنیت ، دوم : آزادی و سوم : نان .\r\n"},{"id":1790,"category_id":10,"category_code":"s10","source_id":352,"title":"شوهر ","content":"شیوانا جعبه‌اى بزرگ پر از مواد غذایى و سکه و طلا را به خانه زنى با چندین بچه قد و نیم قد برد.\r\nزن خانه وقتى بسته‌هاى غذا و پول را دید شروع کرد به بدگویى از همسرش و گفت: «اى کاش همه مثل شما اهل معرفت و جوانمردى بودند.\r\nشوهر من آهنگرى بود که از روى بى‌عقلى دست راست و نصف صورتش را در یک حادثه در کارگاه آهنگرى از دست داد و مدتى بعد از سوختگى علیل و از کار افتاده گوشه خانه افتاد تا درمان شود.\r\nوقتى هنوز مریض و بى‌حال بود چندین بار در مورد برگشت سر کارش با او صحبت کردم ولى به جاى اینکه دوباره سر کار آهنگرى برود مى‌گفت که دیگر با این بدنش چنین کارى از او ساخته نیست و تصمیم دارد سراغ کار دیگر برود.\r\nمن هم که دیدم او دیگر به درد ما نمى‌خورد....\r\nبرادرانم را صدا زدم و با کمک آن‌ها او از خانه و دهکده بیرون انداختیم تا لا اقل خرج اضافى او را تحمل نکنیم.\r\nبا رفتن او ، بقیه هم وقتى فهمیدن وضع ما خراب شده از ما فاصله گرفتن و امروز که شما این بسته‌هاى غذا و پول را برایمان آوردید ما به شدت به آنها نیاز داشتیم.\r\nاى کاش همه انسان‌ها مثل شما جوانمرد و اهل معرفت بودند!\r\nشیوانا تبسمى کرد و گفت: حقیقتش من این بسته‌ها را نفرستادم. یک فروشنده دوره‌گرد امروز صبح به مدرسه ما آمد و از من خواست تا اینها را به شما بدهم و ببینم حالتان خوب هست یا نه!؟ همین!\r\nشیوانا این را گفت و از زن خداحافظى کرد تا برود.\r\nدر آخرین لحظات ناگهان برگشت و ادامه داد: راستى یادم رفت بگویم که دست راست و نصف صورت این فروشنده دوره گردهم سوخته بود.\r\n"},{"id":1791,"category_id":10,"category_code":"s10","source_id":353,"title":"کسی سوالی نداره!؟ ","content":"\r\nاز بدو تولد موفق بودم، وگرنه پام به این دنیا نمی رسید.\r\nاز همون اول کم نیاوردم، با ضربه دکتر چنان گریه‌ای کردم که فهمید جواب «های»، «هوی» است.\r\nهیچ وقت نگذاشتم هیچ چیز شکستم بدهد، پی‌درپی شیر میخوردم و به درد دلم توجه نمی کردم!\r\nاین شد که وقتی رفتم مدرسه از همه هم سن و سالهای خودم بلندتر بودم و همه ازم حساب می‌بردند.\r\nهیچ وقت درس نخوندم، هر وقت نوبت من شد که...\r\nبرم پای تخته زنگ می‌خورد.\r\nهر صفحه‌ای از کتاب را که باز می کردم، جواب سوالی بود که معلمم از من می‌پرسید.\r\nاین بود که سال سوم، چهارم دبیرستان که بودم، معلمم که من را نابغه می‌دانست منو فرستاد المپیاد ریاضی!\r\nتو المپیاد مدال طلا بردم! آخه ورق من گم شده بود و یکی از ورقه‌ها بی اسم بود، منم گفتم اسممو یادم رفته بنویسم!\r\nبدون کنکور وارد دانشگاه شدم هنوز یک ترم نگذشته بود که توی راهروی دانشگاه یه دسته عینک پیدا کردم،\r\nاومدم بشکنمش که خانمی سراسیمه خودش را به من رسوند و از این که دسته عینکش رو پیدا کرده\r\nبودم حسابی تشکر کرد و گفت: نیازی به صاف کردنش نیست زحمت نکشید این شد که هر وقت\r\nچیزی از زمین برمی‌داشتم، یهو جلوم سبز می شد و از این که گمشده‌اش را پیدا کرده بودم حسابی تشکر می کرد.\r\nبعدا توی دانشگاه پیچید: دختر رئیس دانشگاه، عاشق ناجی‌اش شده، تازه فهمیدم که اون دختر کیه و اون ناجی کیه!\r\nیک روز که برای روز معلم برای یکی از استادام گل برده بودم یکی از بچه‌ها دسته گلم رو از پنجره شوت کرد بیرون،\r\nمنم سرک کشیدم ببینم کجاست که دیدم افتاده تو بغل اون دختره!\r\nخلاصه این شد ماجری خواستگاری ما\r\nو الان هم استاد شمام! کسی سوالی نداره!؟\r\n"},{"id":1792,"category_id":10,"category_code":"s10","source_id":354,"title":"یک کلام و تمام ","content":"ابو سعیدابولخیر در مسجدی سخنرانی داشت مردم از تمام اطراف روستا ها و شهرها امده بودند  \r\nجای نشستن نبود و بعضی ها در بیرون نشسته بودند.\r\nسپس شاگرد ابو سعید گفت تو رو به خدا از انجا که هستید یک قدم پیش بگزارید همه یک قدم پیش گزاشتند سپس...\r\nنوبت به سخنرانی ابو سعید رسید او از سخنرانی خود داری  کرد مردم که به مدت یک ساعت در مسجدبودن و خسته شده  بودند شروع به اعتراض کردند ابو سعید پس از مدتی گفت هر انچه که من میخواستم بگویم شاگردم به شما گفت، شما یک قدم به جلو حرکت کنید تا خدا ده قدم به شما نزدیک شود.\r\n"},{"id":1793,"category_id":10,"category_code":"s10","source_id":355,"title":"جنبه !! ","content":"\r\nمردی می‌خواست زنش را طلاق دهد.\r\nدوستش علت را جویا شد و او گفت: این زن از روز اول همیشه می خواست من را عوض کند.\r\nمرا وادار کرد سیگار و مشروب را ترک کنم..\r\nلباس بهتر بپوشم، قماربازی نکنم، در سهام سرمایه‌گذاری کنم و حتی ...\r\nمرا عادت داده که به موسیقی کلاسیک گوش کنم و لذت ببرم!\r\nدوستش گفت: اینها که می‌گویی که چیز بدی نیست!\r\n\r\nمرد گفت: ولی حالا حس می‌کنم که دیگر این زن در شان من نیست!\r\n"},{"id":1794,"category_id":10,"category_code":"s10","source_id":356,"title":"قورباغه ها ","content":"مارها قورباغه ها را می خوردند و قورباغه ها غمگین بودند\r\nقورباغه ها به لک لک ها شکایت کردند\r\nلک لک ها مارها را خوردند و قورباغه ها شادمان شدند\r\nلک لک ها گرسنه ماندند و شروع کردند به خوردن قورباغه ها\r\nقورباغه ها دچار اختلاف دیدگاه شدند\r\nعده ای از آنها ...\r\nبا لک لک ها کنار آمدند و عده ای دیگر خواهان باز گشت مارها شدند\r\nمارها باز گشتند و همپای لک لک ها شروع به خوردن قورباغه ها کردند\r\nحالا دیگر قورباغه ها متقاعد شده اند که برای خورده شدن  به دنیا می آیند\r\nتنها یک مشکل برای آنها حل نشده باقی مانده است\r\nاینکه نمی دانند توسط دوستانشان خورده می شوند یا دشمنانشان\r\n"},{"id":1795,"category_id":10,"category_code":"s10","source_id":357,"title":"هم راز هم باشیم! ","content":"در یک دهکده ای دور افتاده دو تا دوست زندگی می کردند. یکی از اونها جانسون و دیگری پیتر بود. این دو تا از کودکی با هم بزرگ شده بودند. آنقدر این دو دوست رابطه خوبی با هم داشتند که نصف اهالی دهکده فکر میکردند که ِاین دو نفر با هم برادرند. با این حال که هیچ شباهتی به هم نداشتند. اما این حرف اهالی نشان از اوج محبتی بود که بین این دو نفر وجود داشت. همیشه پیتر و جانسون راز دلشون رو به همدیگه میگفتند و \r\nبرای مشکلاتشون با همدیگه همفکری میکردند و بالاخره یه راه چاره براش پیدا می کردند. اما اکثر اوقات جانسون این مسائل رو بدون اینکه پیتر بدونه با دوستای دیگه اش در میان میگذاشت.\r\n\r\nوقتی پیتر متوجه این کار جانسون می شد ناراحت می شد اما به روش هم نمی آورد. چون آنقدر جانسون رو دوست داشت که حاضر نبود حتی برای یک دقیقه تلخی این رابطه رو شاهد باشه. به خاطر همین احترام جانسون رو نگه می داشت و باز هم مثل همیشه با اون درد دل می کرد. سالها گذشت و پیتر ازدواج کرد و رفت سر خونه زندگیش، اما این رابطه همچنان ادامه داشت و روز به روز عمیق تر می شد. یه روز پیتر می خواست برای یه کار خیلی مهم با خانواده اش بره به شهر. به خاطر همین اومد و به جانسون گفت من دارم می رم به طرف شهر، اما اگه امکان داره این کیسه پول رو توی خونت نگهدار تا من از شهر برگردم.\r\n\r\nجانسون هم پول رو گرفت و رفیقش رو تا دروازه خروجی بدرقه کرد. وقتی داشت به خونه برمی گشت، سر راه رفت پاتوق خودش و شروع کرد با دوستاش تفریح کردن. هوا دیگه داشت کم کم تاریک می شد و جانسون با دوستاش می خواست خداحافظی کنه. اما دوستاش گفتن هنوز که زوده چرا مثل هر شب نمی ری؟ اونم گفت که پولهای پیتر توی خونست و باید زودتر بره خونه و از پولها مراقبت کنه. خلاصه خداحافظی کرد و رفت. وقتی رسید خونه سریع غذاشو خورد و رفت توی اتاقش. پولها رو هم گذاشت توی صندوقش و گرفت تخت تخت خوابید. بی خبر از اتفاقی که در انتظارش بود ...\r\n\r\nبله درست حدس زدید. چند نفر شبونه ریختن توی خونه و پولها رو با خودشون بردند! جانسون صبح که از خواب بیدار شد متوجه این موضوع شد و از ناراحتی داشت سکته می کرد ! تمام زندگیش رو هم اگه می فروخت نمی تونست جبران پولهای دزدیده شده رو بکنه. از ناراحتی لب به غذا هم نزد. دم دمای غروب بود که دید صدای در میاد. در رو که باز کرد دید پیتر اومده تا پولها رو با خودش ببره. وقتی جانسون ماجرا رو براش تعریف کرد، پیتر به جای اینکه ناراحت بشه و از دست جانسون عصبانی باشه، شروع کرد به خندیدن و گفت می دونستم، می دونستم که بازم مثل همیشه نمی تونی جلوی زبونت رو بگیری. اما اصلاً نترس. چون من فکرشو می کردم که این اتفاق بیافته. به خاطر همین چند تا سکه از آهن درست کردم و توی اون کیسه ریختم و اصل سکه ها رو توی خونه خودم نگه داشتم و چون می دونستم که کسی از این موضوع با خبر می شه و تو به همه می گی که سکه ها پیش تو بوده، خونه من امن تر از تو بود. الآن هم اصلاً نگران و ناراحت نباش شاید از دست من و این رفتارم ناراحت بشی، اما این درسی برات می شه که همیشه مسائلی رو که دیگران با تو در میون میگذارند توی قلبت محفوظ نگه داری و به شخص ناشناسی راز دلت رو بازگو نکنی ...\r\n"},{"id":1796,"category_id":10,"category_code":"s10","source_id":358,"title":"سرخ پوست ها و رئیس جدید ","content":"اعضای قبیله سرخ پوست از رییس جدید می پرسن: «آیا زمستان سختی در پیش است؟»\r\nرییس جوان قبیله که هیچ تجربه ای در این زمینه نداشت، جواب میده «برای احتیاط برید هیزم تهیه کنید» بعد میره به سازمان هواشناسی کشور زنگ میزنه: «آقا امسال زمستون سردی در پیشه؟»\r\nپاسخ: «اینطور به نظر میاد»، پس رییس به مردان قبیله دستور میده که ...\r\nبیشتر هیزم جمع کنند و برای اینکه مطمئن بشه یه بار دیگه به سازمان هواشناسی زنگ میزنه: «شما نظر قبلی تون رو تایید می کنید؟»\r\nپاسخ: «صد در صد»، رییس به همه افراد قبیله دستور میده که تمام توانشون رو برای جمع آوری هیزم بیشتر صرف کنند. بعد دوباره به سازمان هواشناسی زنگ میزنه: «آقا شما مطمئنید که امسال زمستان سردی در پیشه؟»\r\nپاسخ: بگذار اینطوری بگم؛ سردترین زمستان در تاریخ معاصر!\r\n\r\nرییس: «از کجا می دونید؟»\r\nپاسخ: «چون سرخ پوست ها دیوانه وار دارن هیزم جمع می کنن!\r\n"},{"id":1797,"category_id":10,"category_code":"s10","source_id":359,"title":"زندگی خروسی ","content":"کوه بلندی بود که لانه عقابی با چهار تخم، بر بلندای آن قرار داشت.\r\nیک روز زلزله ای کوه را به لرزه در آورد و باعث شد که یکی از تخم ها از دامنه کوه به پایین بلغزد.\r\nبر حسب اتفاق آن تخم به مزرعه ای رسید که پر از مرغ و خروس بود.\r\nمرغ و خروس ها می دانستند که ...\r\nباید از این تخم مراقبت کنند و بالاخره هم مرغ پیری داوطلب شد تا روی آن بنشیند و آن را گرم نگهدارد تا جوجه به دنیا بیاید.\r\nیک روز تخم شکست و جوجه عقاب از آن بیرون آمد.\r\nجوجه عقاب مانند سایر جوجه ها پرورش یافت و طولی نکشید که جوجه عقاب باور کرد که چیزی جز یک جوجه خروس نیست. او زندگی و خانواده اش را دوست داشت اما چیزی از درون او فریاد می زد که تو بیش از این هستی. تا این که یک روز که داشت در مزرعه بازی می کرد متوجه چند عقاب شد که در آسمان اوج می گرفتند و پرواز می کردند. عقاب آهی کشید و گفت: ای کاش من هم می توانستم مانند آنها پرواز کنم.مرغ و خروس ها شروع کردند به خندیدن و گفتند: تو خروسی و یک خروس هرگز نمی تواند پرواز کند.اما عقاب همچنان به خانواده واقعی اش که در آسمان پرواز می کردند خیره شده بود و در آرزوی پرواز به سر می برد.\r\nاما هر موقع که عقاب از رویایش سخن می گفت به او می گفتند که رویای تو به حقیقت نمی پیوندد و عقاب هم کم کم باور کرد.\r\nبعد از مدتی او دیگر به پرواز فکر نکرد و مانند یک خروس به زندگی ادامه داد و بعد از سالها زندگی خروسی، از دنیا رفت\r\n"},{"id":1798,"category_id":10,"category_code":"s10","source_id":360,"title":"تلخند ","content":"توی قصابی بودم که یه پیرزن اومد تو و یه گوشه وایستاد .....\r\nیه آقای خوش تیپی هم اومد تو گفت: ابرام آقا قربون دستت پنج کیلو فیله گوساله بکش عجله دارم .....\r\nآقای قصاب شروع کرد به بریدن فیله و جدا کردن اضافه‌هاش .....\r\nهمینجور که داشت کارشو می‌کرد رو به پیرزن کرد گفت: چی مِخی نِنه ؟\r\nپیرزن اومد جلو یک پونصد تومنی مچاله گذاشت تو ترازو گفت: هَمینو گُوشت بده نِنه .....\r\nقصاب یه نگاهی به پونصد تومنی کرد گفت: پُونصَد تُومَن فَقَط اّشغال گوشت مِشِه نِنه بدم؟\r\nپیرزن یه فکری کرد گفت بده نِنه!\r\nقصاب اشغال گوشت‌های اون جوون رو می‌کند می‌ذاشت برای پیره زن .....\r\nاون جوونی که فیله سفارش داده بود همین جور که با موبایلش بازی می‌کرد گفت: اینارو واسه سگت می‌خوای مادر؟\r\nپیرزن نگاهی به جوون کرد گفت: سَگ؟\r\nجوون گفت اّره ..... سگ من این فیله‌ها رو هم با ناز می‌خوره ..... سگ شما چجوری اینا رو می‌خوره؟\r\nپیرزن گفت: مُخُوره دیگه نِنه ..... شیکم گشنه سَنگم مُخُوره .....\r\nجوون گفت نژادش چیه مادر؟ پیرزنه گفت بهش مِگن تُوله سَگِ دوپا نِنه ..... اینا رو برا بچه‌هام می‌خام اّبگوشت بار بیذارم!\r\nجوونه رنگش عوض شد ..... یه تیکه از گوشتای فیله رو برداشت گذاشت رو اشغال گوشتای پیرزن .....\r\nپیرزن بهش گفت: تُو مَگه ایناره بره سَگِت نگرفته بُودی؟\r\nجوون گفت: چرا\r\nپیرزن گفت ما غِذای سَگ نِمُخُوریم نِنه .....\r\nبعد گوشت فیله رو گذاشت اون طرف و اشغال گوشتاش رو برداشت و رفت.\r\n"},{"id":1799,"category_id":10,"category_code":"s10","source_id":361,"title":"بزرگترین حکمت ","content":"روزی سقراط در کنار دریا راه می رفت که نوجوانی نزد او آمد و گفت: «استاد! می شود در یک جمله به من بگویید بزرگترین حکمت چیست » سقراط از نوجوان خواست وارد آب بشود. نوجوان این کار را کرد.\r\nسقراط با حرکتی سریع، سر نوجوان را زیر آب برد و همان جا نگه داشت، طوری که نوجوان شروع به ...\r\nدست و پا زدن کرد. سقراط سر او را مدتی زیر آب نگه داشت و سپس رهایش کرد. نوجوان وحشت زده از آب بیرون آمد و با تمام قدرتش نفس کشید.\r\nو که از کار سقراط عصبانی شده بود، با اعتراض گفت: «استاد! من از شما درباره حکمت سؤال می کنم و شما می خواهید مرا خفه کنید » سقراط دستی به نوازش به سر او کشید و گفت: «فرزندم! حکمت همان نفس عمیقی است که کشیدی تا زنده بمانی. هر وقت معنی آن نفس حیات بخش را فهمیدی، معنی حکمت را هم می فهمی!»\r\n"},{"id":1800,"category_id":10,"category_code":"s10","source_id":362,"title":"روش شناخت شیطان! ","content":"\r\nروزی روزگاری شیطان به فکر سفر افتاد. با خود عهد کرد تازمانی که\r\n انسانی نیابد که بتواند او را به حیرت وا دارد، از این سفر بر نگردد. نیم \r\nدو جین روح را در خورجین ریخت. نان جویی بر داشت و به راه افتاد.\r\n رفت و رفت و رفت. هزاران فرسنگ راه رفت تا اینکه تردید در دلش \r\nجوانه بست که شاید تصمیم غلطی گرفته باشد.\r\nدر هیچ کدام از جاده های دنیا به هیچ بنده ای که ....\r\nتوجه او را جلب \r\nکند ویا حتی کنجکاوی او را بر انگیزد، بر نخورد. دیگر داشت خسته \r\nمی شد. تصمیم گرفت به مکان مقدسی سر بزند؛ ولی حتی آنجا هم، \r\nکه همیشه مبارزه ای ریشه دار از زمانهای دور، علیه او جریان \r\nداشت، هیچ چیز نتوانست حیرت زده اش کند. دلسرد و نا امید و \r\nافسرده در سایه درختی  ایستاده بود که رهگذری گرما زده با\r\n کیفی بر دوش کنا او ایستاد. کمی که استراحت کرد خواست به\r\n رفتنش ادامه دهد. مرد قبل از اینکه به راه خود ادامه دهد، به او \r\nگفت:\"تو شیطان هستی!\"\r\nابلیس حیرت زده پرسید:\"از کجا فهمیدی؟!\"\r\n\" از روی تجربه ام گفتم. ببین من فروشنده دوره گردم. خیلی سفر \r\nمی کنم و مردم را خوب می شناسم . در نتیجه در همین ده دقیقه \r\nای که اینجا هستیم، تو را شنا ختم. چون:\r\nمثل کنه به من نچسبیدی، پس مزاحم یا گدا نیستی !\r\nاز آب و هوا شکایت نکردی، پس احمق نیستی !\r\nبه من حمله نکردی، پس راهزن نیستی !\r\nبه من حتی سلام نکردی، پس شخص محترمی نیستی !\r\nاز من نپرسیدی داخل کیفم چه دارم، پس فضول هم نیستی !\r\nحالا که نه مزاحمی، نه احمق، نه راهزن، نه محترم، نه فضول پس \r\nآدمیزاد نیستی ! هیچ کس نیستی ! پس خود شیطانی !\"\r\nشیطان با شنیدن این حرفها کلاه ازسر برداشت و کله اش را خاراند. \r\nمرد با دست به پاها یش زد و گفت:\"خوبه! تازه، شاخ هم که داری!\"\r\n"},{"id":1801,"category_id":10,"category_code":"s10","source_id":363,"title":"من کی هستم؟! ","content":"من« دوشیزه مکرمه» هستم، وقتی زن ها روی سرم قند می سابند و  همزمان قند توی دلم آب می شود.\r\n\r\nمن «مرحومه مغفوره» هستم، وقتی زیر یک سنگ سیاه گرانیت قشنگ خوابیده ام و احتمالاً هیچ خوابی نمی بینم\r\n\r\nمن «والده مکرمه» هستم، وقتی اعضای هیات مدیره شرکت پسرم برای خودشیرینی 20 آگهی تسلیت در 20 روزنامه معتبر چاپ می کنند\r\nمن «همسری مهربان و مادری فداکار» هستم، وقتی شوهرم ...\r\nبرای اثبات وفاداری اش  البته تا چهلم- آگهی وفات مرا در صفحه اول پرتیراژترین روزنامه شهر به چاپ می رساند\r\nمن «زوجه» هستم، وقتی شوهرم پس از چهار سال و دو ماه و سه روز به  حکم قاضی دادگاه خانواده قبول می کند به من و دختر شش ساله ام ماهیانه فقط بیست و پنج هزار تومان ، بدهد\r\nمن «سرپرست خانوار» هستم، وقتی شوهرم چهار سال پیش با کامیون قراضه اش از گردنه حیران رد نشد و برای همیشه در ته دره خوابید.\r\nمن «خوشگله» هستم، وقتی پسرهای جوان محله زیر تیر چراغ برق وقت شان را بیهودهمی گذرانند.\r\nمن «مجید» هستم، وقتی در ایستگاه چراغ برق، اتوبوس خط واحد می ایستد و شوهرم مرا از پیاده رو مقابل صدا می زند.\r\nمن «ضعیفه» هستم، وقتی ریش سفیدهای فامیل می خواهند از برادر بزرگم حق ارثم را بگیرند.\r\nمن «بی بی» هستم، وقتی تبدیل به یک شیء آرکائیک می شوم و نوه و  نتیجه هایم تیک تیک از من عکس می گیرند.\r\nمن «مامی» هستم، وقتی دختر نوجوانم در جشن تولد دوستش دروغ پردازی  می کند.\r\nمن «مادر» هستم، وقتی مورد شماتت همسرم قرار می گیرم چون آن روز به  یک مهمانی زنانه رفته بودم و غذای بچه ها را درست نکرده بودم.\r\nمن «زنیکه» هستم، وقتی مرد همسایه، تذکرم را در خصوص درست گذاشتن ماشینش در پارکینگ می شنود.\r\nمن «مامانی» هستم، وقتی بچه هایم خرم می کنند تا خلاف هایشان را به پدرشان نگویم.\r\nمن «ننه» هستم، وقتی شلیته می پوشم و چارقدم را با سنجاق زیر گلویم محکم می کنم و نوه ام خجالت می کشد به دوستانش بگوید من مادربزرگش هستم... به آنها می گوید من خدمتکار پیر مادرش هستم.\r\nمن «یک کدبانوی تمام عیار» هستم، وقتی شوهرم آروغ های بودار می زند و کمربندش را روی شکم برآمده اش جابه جا می کند.\r\n\r\nمن «بانو» هستم، وقتی از مرز پنجاه سالگی گذشته ام و هیچ مردی دلش نمی خواهد وقتش را با من تلف بکند.\r\nمن در ماه اول عروسی ام؛ «خانم کوچولو، عروسک، ملوسک، خانمی،عزیزم،عشق من، پیشی، قشنگم، عسلم، ویتامین و.....» هستم.\r\nمن در فریادهای شبانه شوهرم، وق دیر به خانه می آید، چند تار موی زنانه روی یقه کتش است و دهانش بوی سگ مرده می دهد، «سلیطه» هستم.\r\nمن در محاوره ی دیرپای این کهن بوم ؛ «دلیله محتاله، نفس محیله مکاره، مار،ابلیس،شجره مثمره، اثیری، لکاته و....» هستم.\r\nدامادم به من «وروره جادو» می گوید.\r\nحاج آقا مرا «والده» آقا مصطفی صدا می زند..\r\nمن «مادر فولادزره» هستم، وقتی بر سر حقوقم با این و آن می جنگم.\r\nمادرم مرا به خان روستا «کنیز» شما معرفی می کند..\r\nواقعا من کیستم؟\r\n"},{"id":1802,"category_id":10,"category_code":"s10","source_id":364,"title":"انسان های بزرگ ","content":"روزی روبرت دوونسنزو گلف باز بزرگ آرژانتینی، پس از بردن مسابقه و دریافت چک قهرمانی لبخند بر لب مقابل دوربین خبرنگاران وارد رختکن می شود تا آماده رفتن شود.\r\nپس از ساعتی، او داخل پارکینگ تک و تنها به طرف ماشینش می رفت که زنی به وی نزدیک می شود. زن پیروزیش را تبریک می گوید و سپس عاجزانه می افزاید که پسرش به خاطر ابتلا به بیماری سخت مشرف به مرگ است و او قادر به ...\r\nپرداخت حق ویزیت دکتر و هزینه بالای بیمارستان نیست.\r\nدو ونسنزو تحت تاثیر حرفهای زن قرار گرفت و چک مسابقه را امضا نمود و در حالی که آن را در دست زن می فشرد گفت: برای فرزندتان سلامتی و روزهای خوشی را آرزو می کنم.\r\nیک هفته پس از این واقعه دوونسنزو در یک باشگاه روستایی مشغول صرف ناهار بود که یکی از مدیران عالی رتبه انجمن گلف بازان به میز او نزدیک می شود و می گوید: هفته گذشته چند نفر از بچه های مسئول پارکینگ به من اطلاع دادند که شما در آنجا پس از بردن مسابقه با زنی صحبت کرده اید. می خواستم به اطلاعتان برسانم که آن زن یک کلاهبردار است. او نه تنها بچه مریض و مشرف به مرگ ندارد، بلکه ازدواج هم نکرده. او شما را فریب داده، دوست عزیر!\r\nدو ونسزو می پرسد: منظورتان این است که مریضی یا مرگ هیچ بچه ای در میان نبوده است؟\r\nبله کاملا همینطور است.\r\nدو ونسزو می گوید: در این هفته، اینبهترین خبری است که شنیدم.\r\n"},{"id":1803,"category_id":10,"category_code":"s10","source_id":365,"title":"شاعر بی پول ","content":"یک شب نصرت رحمانی وارد کافه نادری شد و به اخوان ثالث گفت : من همین حالا سی تومن پول احتیاج دارم . اخوان جواب داد : من پولم کجا بود ؟ برو خدا روزی ات را جای دیگری حواله کند. نصرت رحمانی رفت و بعد از مدتی بر گشت و بیست تومان پول و یک خودکار به اخوان داد . اخوان گفت این پول چیه ؟....\r\nتو که پول نداشتی . نصرت رحمانی گفت : از دم در ؛ پالتوی تو رو ورداشتم بردم پنجاه تومن فروختم . چون بیش از سی تومن لازم نداشتم ؛ بگیر ؛ این بیست تومن هم بقیه پولت ! ضمنا، این خودکار هم توی پالتوت بود.\r\n"},{"id":1804,"category_id":10,"category_code":"s10","source_id":366,"title":"بوسه و سیلی ","content":"ژنرال و ستوان جوان زیردستش سوار قطار شدند. تنها صندلی های خالی در کوپه، روبروی خانمی جوان و زیبا و مادربزرگش بود. ژنرال و ستوان روبروی آن خانمها نشستند. قطار راه افتاد و وارد تونلی شد. حدود ده ثانیه تاریکی محض بود. در آن لحظات سکوت، کسانی که در کوپه بودند 2 چیز شنیدند: صدای بوسه و سیلی. هریک از افرادی که در کوپه بودند از اتفاقی که افتاده بود تعبیر خودش را داشت\r\n\r\nخانم جوان در دل گفت: \r\nاز اینکه ستوان مرا بوسید خوشحال شدم اما از اینکه مادربزرگم او را کتک زد خیلی خجالت کشیدم\r\n\r\nمادربزرگ به خود گفت: از اینکه آن جوانک نوه ام را بوسید کفرم درامد اما افتخار میکنم که نوه ام جرات تلافی کردن داشت\r\nژنرال آنجا نشسته بود و فکر کرد ستوان جسارت زیادی نشان داد که آن دختر را بوسید اما چرا اشتباهی من سیلی خوردم\r\nستوان تنها کسی بود که میدانست واقعا چه اتفاقی افتاده است. در آن لحظات تاریکی او فرصت را غنیمت شمرده که دختر زیبا را ببوسد و به زنرال سیلی بزند\r\nزندگی کوپه قطاری است و ما انسانها مسافران آن. هرکدام از ما آنچه را می بینم و می شنویم بر اساس پیش فرضها و حدسیات و معتقدات خود ارزیابی و معنی می کنیم. غافل از اینکه ممکن است برداشت ما از واقعیت منطبق بر آن نباشد.\r\nما میگوییم حقیقت را دوست داریم اما اغلب چیزهایی را که دوست داریم، حقیقت می نامیم.\r\n"},{"id":1805,"category_id":10,"category_code":"s10","source_id":367,"title":"دل عزراییل برای چه کسانی سوخته است؟ ","content":"روزی رسول خدا (صل الله علیه و آله) نشسته بود، عزراییل به زیارت آن حضرت آمد. پیامبر(صل الله علیه و آله) از او پرسید: ای برادر! چندین هزار سال است که تو مأمور قبض روح انسان ها هستی، آیا در هنگام جان کندن آنها دلت برای کسی سوخته است؟\r\nعزارییل گفت در این مدت دلم برای دو نفر سوخت:...\r\n۱- روزی دریایی طوفانی شد و امواج سهمگین آن یک کشتی را در هم شکست همه سر نشینان کشتی غرق شدند، تنها یک زن حامله نجات یافت او سوار بر پاره تخته کشتی شد و امواج ملایم دریا او را به ساحل آورد و در جزیره ای افکند و در همین هنگام فارغ شد و پسری از وی متولد شد، من مأمور شدم که جان آن زن را بگیرم، دلم به حال آن پسر سوخت.\r\n۲- هنگامی که شداد بن عاد سالها به ساختن باغ بزرگ و بی نظیر خود پرداخت و همه توان و امکانات و ثروت خود را در ساختن آن صرف کرد و خروارها طلا و جواهرات برای ستونها و سایر زرق و برق آن خرج نمود تا تکمیل نمود. وقتی خواست به دیدن باغ برود همین که خواست از اسب پیاده شود و پای راست از رکاب به زمین نهد، هنوز پای چپش بر رکاب بود که فرمان از سوی خدا آمد که جان او را بگیرم، آن تیره بخت از پشت اسب بین زمین و رکاب اسب گیر کرد و مرد، دلم به حال او سوخت بدین جهت که او عمری را به امید دیدار باغی که ساخته بود سپری کرد اما هنوز چشمش به باغ نیفتاده بود اسیر مرگ شد.\r\nدر این هنگام جبرئیل به محضر پیامبر (صل الله علیه و آله) رسید و گفت ای محمد! خدایت سلام می رساند و می فرماید: به عظمت و جلالم سوگند شداد بن عاد همان کودکی بود که او را از دریای بیکران به لطف خود گرفتیم و از آن جزیره دور افتاده نجاتش دادیم و او را بی مادر تربیت کردیم و به پادشاهی رساندیم، در عین حال کفران نعمت کرد و خود بینی و تکبر نمود و پرچم مخالفت با ما بر افراشت، سر انجام عذاب سخت ما او را فرا گرفت، تا جهانیان بدانند که ما به آدمیان مهلت می دهیم و لی آنها را رها نمی کنیم.\r\n"},{"id":1806,"category_id":10,"category_code":"s10","source_id":368,"title":"قیمت تجربه ","content":"مهندسی بود که در تعمیر دستگاه های مکانیکی استعداد و تبحر داشت\r\nاو پس از۳۰ سال خدمت صادقانه با یاد و خاطری خوش باز نشسته شد\r\nدو سال بعد، از طرف شرکت درباره رفع اشکال به ظاهر لاینحل یکی از دستگاه های\r\nچندین میلیون دلاری با اوتماس گرفتند\r\nآنها هر کاری که از دستشان بر می آمد انجام داده بودند\r\nو هیچ کسی نتوانسته بود اشکال را رفع کند بنابراین....\r\nنومیدانه به او متوسل شده بودند\r\nکه در رفع بسیاری از این مشکلات موفق بوده است.\r\nمهندس، این ا مر را به رغبت می پذیرد. او یک روز تمام به وارسی دستگاه می پردازد\r\nو در پایان کار، با یک تکه گچ علامت ضربدر روی یک قطعه مخصوص دستگاه می کشد\r\nو با سربلندی می گوید: اشکال اینجاست\r\nآن قطعه تعمیر می شود و دستگاه بار دیگر به کار می افتد.\r\nمهندس دستمزد خود را ۵۰۰۰۰ دلار معرفی می کند.\r\nحسابداری تقاضای ارائه گزارش و صورتحساب مواد مصرفی می کند\r\nو او بطور مختصر این گزارش را می دهد:\r\nبابت یک قطعه گچ: ۱ دلار و بابت\r\nدانستن اینکه ضربدر را کجا بزنم: ۴۹۹۹۹ دلار !\r\n"},{"id":1807,"category_id":10,"category_code":"s10","source_id":369,"title":"خدا را شکر... ","content":"خدا را شکر که تمام شب صدای خرخر شوهرم را می شنوم . این یعنی او زنده و سالم در کنار من خوابیده است. \r\nخدا را شکر که دختر نوجوانم همیشه از شستن ظرفها شاکی است.این یعنی او در خانه است و در خیابانها پرسه نمی زند. \r\nخدا را شکر که مالیات می پردازم این یعنی شغل و در آمدی دارم و بیکار نیستم. ..\r\nخدا را شکر که لباسهایم کمی برایم تنگ شده اند. این یعنی غذای کافی برای خوردن دارم. \r\nخدا را شکر که در پایان روز از خستگی از پا می افتم.این یعنی توان سخت کار کردن را دارم. \r\nخدا را شکر که باید زمین را بشویم و پنجره ها را تمیز کنم.این یعنی من خانه ای دارم. \r\nخدا را شکر که در جائی دور جای پارک پیدا کردم.این یعنی هم توان راه رفتن دارم و هم اتومبیلی برای سوار شدن. \r\nخدا را شکر که سرو صدای همسایه ها را می شنوم. این یعنی من توانائی شنیدن دارم. \r\nخدا را شکر که این همه شستنی و اتو کردنی دارم. این یعنی من لباس برای پوشیدن دارم. \r\nخدا را شکر که هر روز صبح باید با زنگ ساعت بیدار شوم. این یعنی من هنوز زنده ام. \r\nخدا را شکر که گاهی اوقات بیمار می شوم. این یعنی بیاد آورم که اغلب اوقات سالم هستم.\r\nخدا را شکر که خرید هدایای سال نو جیبم را خالی می کند. این یعنی عزیزانی دارم که می توانم برایشان هدیه بخرم. \r\n\r\nشکر شکر خدا را شکر\r\n"},{"id":1808,"category_id":10,"category_code":"s10","source_id":370,"title":"ملاقاتی ","content":"سرباز از برج دیده بانی نگاه می کرد و عکاس را می دید که بی خیال پیش می آمد. سه پایه اش را به دوش می کشید. هیچ توجهی به تابلوی«منطقه نظامی/ عکاسی ممنوع» نکرد. هوا سرد بود و حوصله نداشت از دکل ....\r\nپایین بیاید. مگسک را تنظیم کرد و لحظه نفس در سینه اش حبس شد. تلفن که زنگ زد، تیرش خطا رفت.\r\n  ـ جک خواهرت از مینه سوتا آمده بود تو را ببیند. همان که می گفتی عکاس روزنامه است.فرستادمش سر پستت تا غافلگیر شوی.\r\n"},{"id":1809,"category_id":10,"category_code":"s10","source_id":371,"title":"زن و مرد ","content":"\r\nمرد از راه می رسه\r\nناراحت و عبوس\r\nزن:چی شده؟\r\nمرد:هیچی ( و در دل از خدا می خواد که زنش بی خیال شه و بره پی کارش)\r\nزن حرف مرد رو باور نمی کنه: یه چیزیت هست.بگو!\r\nمرد برای اینکه اثبات کنه راست می گه ....\r\nلبخند می زنه \r\nزن اما \"می فهمه\"مرد دروغ میگه:راستشو بگو یه چیزیت هست\r\nتلفن زنگ می زنه\r\nدوست زن پشت خطه\r\nازش می خواد حاضر شه تا با هم برن استخر. از صبح قرارشو گذاشتن\r\nمرد در دلش خدا خدا می کنه که زن زودتر بره \r\nزن خطاب به دوستش: متاسفم عزیزم.جدا متاسفم که بدقولی می کنم.شوهرم ناراحته و نمی تونم تنهاش بذارم!\r\nمرد داغون می شه\r\n\"می خواست تنها باشه\"\r\n"},{"id":1810,"category_id":10,"category_code":"s10","source_id":372,"title":"هاچیکو ","content":"\r\nدر ژاپن سگ معروفی با نام هاچیکو به دنیا آمد که زندگی و منش او به افسانه ای از یاد نرفتنی بدل گشت. هاچیکو سگ سفید نری از نژاد آکیتا که در اوداته ژاپن در نوامبر سال ۱۹۲۳ به دنیا آمد. زمانی که هاچیکو دو ماه داشت به وسیلۀ قطار اوداته به توکیو فرستاده شد و زمانی که به ایستگاه شیبوئی میرسید قفس حمل آن از روی باربر به پائین می افتد و آدرسی که قرار بود هاچیکو به آنجا برود گم می شود و او از قفس بیرون آمده و تنها در ایستگاه به این سو و آن سو میرود در همین زمان یکی از مسافران هاچیکو را پیدا کرده و با خود به منزل میبرد و به نگهداری از او می پردازد.این فرد پروفسور دانشگاه توکیو دکتر شابرو اوئنو بود.\r\n\r\nپروفسور به قدری به این سگ دلبسته می شود که بیشتر وقت خود را به نگهداری از این سگ اختصاص می دهد. دور گردن هاچیکو قلاده ای بود که روی آن عدد ۸ نوشته شده بود (عدد هشت در زبان ژاپنی هاچی بیان می شود و نماد شانس و موفقیت است) و پروفسور نام اورا هاچیکو می گذارد. منزل پروفسور در حومه شهر توکیو قرار داشت و هر روز برای رفتن به دانشگاه به ایستگاه قطار شیبوئی میرفت و ساعت ۴ برمی گشت. هاچیکو یک روز به دنبال پروفسور به ایستگاه می آید و هرچه شابرو از او می خواهد که به خانه برگردد هاچیکو نمی‌رود و او مجبور می شود که خود هاچیکو را به منزل برساند و از قطار آن روز جا می ماند.\r\n\r\n در زمان بازگشت از دانشگاه با تعجب می بیند هاچیکو روبروی در ورودی ایستگاه به انتظارش نشسته و با هم به خانه برمیگردند از آن تاریخ به بعد هرروز هاچیکو و پروفسور باهم به ایستگاه قطار میرفتند و ساعت ۴ هاچیکو جلوی در ایستگاه منتظر بازگشت او می ماند، تمام فروشندگان و حتی مسافران هاچیکو را می شناختند و با تعجب به این رابطۀ دوستانه نگاه میکردند. در سال۱۹۲۵ دکتر شابرو اوئنو در سر کلاس درس بر اثر سکتۀ قلبی از دنیا میرود، آن روز هاچیکو که۱۸ ماه داشت تا شب روبروی در ایستگاه به انتظار صاحبش می نشیند و خانوادۀ پروفسور به دنبالش آمده و به خانه میبرندش اما روز بعد نیز مثل گذشته هاچیکو به ایستگاه رفته و منتظر بازگشت صاحبش می ماند و هربار که خانوادۀ پروفسور جلوی رفتنش را می گرفتند هاچیکو فرار میکرد و به هر طریقی بود خود را رأس ساعت ۴ به ایستگاه میرساند. این رفتار هاچیکو خبرنگاران و افراد زیادی را به ایستگاه شیبوئی می کشاند، و در روزنامه ها اخبار زیادی دربارۀ او نوشته می شد و همه میخواستند از نزدیک با این سگ باوفا آشنا شوند. هاچیکو خانوادۀ پروفسور را ترک کرد و شبها در زیر قطار فرسوده‌ای میخوابید، فروشندگان و مسافران برایش غذا می آوردند و او ۹ سال هر بعد از ظهر روبروی در ایستگاه منتظر بازگشت صاحب عزیزش میماند و در هیچ شرایطی از این انتظار دلسرد نشد و تا زمان مرگش در مارس ۱۹۳۴ در سن ۱۱ سال و ۴ ماهگی منتظر صاحب مورد علاقه‌اش باقی‌ماند  \r\nوفاداری هاچیکو در سراسر ژاپن پیچید و در سال ۱۹۳۵ تندیس یادبودی روبروی در ایستگاه قطار شیبوئی از او ساخته شد.\r\n\r\nتا امروز تندیس برنزی هاچیکو همچنان در ایستگاه شیبوئی منتظر بازگشت پروفسور است.\r\n\r\n در زمان جنگ جهانی دوم تندیس تخریب شد و در سال ۱۹۴۷ دوباره تندیس جدیدی از هاچیکو در وعدگاه همیشگی اش بنا شد، اگرچه این بنا حالت ایستاده داشت و به زیبایی تندیس اول نبود، اما یادبودی بود از وفاداری و عشق زیبای هاچیکو برای مردم ژاپن؛ در سال ۱۹۶۴ تندیس دیگری از هاچیکو همراه با خانواده ای که هرگز، انتظار و عشق اجازۀ داشتنش را به او نداده بود در اوداته روبروی زادگاهش بنا شد.\r\n"},{"id":1811,"category_id":10,"category_code":"s10","source_id":373,"title":"سایه ی هیتلر","content":"اوا براون دختر نجیب و زیبای بود که در روز 6 فوریه سال 1912 در شهر شلوغ مونیخ متولد شد او عاشق آلمان و حزب نازی بود این باعث شده بود که هنگامی که هیتلر رهبر حزب می آمد به عکاسخانه ایی که او در آن کار می کرد بیاید همه تلاش خود را می نمود تا بهترین و زیباترین عکس ممکن را از او بگیرد او می خواست در خطوط چهره آدلف هیتلر قدرت آلمان و عشق به سرزمین مظلومش که پس از جنگ جهانی اول دچار بحران و هزار مصیبت دیگر بود و مجبور بود طبق عهد نامه ورسای خراج به انگلیس و فرانسه بپردازد را نشان دهد او در هیتلر این توان را می دید که او می تواند کشورش را نجات بخشد . با این که هیتلر هنوز شناسنامه آلمانی نداشت او شیفته این مرد اتریشی شده بود .\r\nدر سال 1932 هیتلر شناسنامه آلمانی گرفت و به تابعیت آلمان درآمد آلمانی که به خاطر آن پانزده سال قبل در جنگ جهانی اول در جنگ اول جهانی در جبهه فرانسه به مدت یک سال کور و زخمی شد .همان سال هیتلر هنگامی که اوا براون فقط 20 سال داشت از او خواست که با هم زندگی کنند. این در حالی بود که هیتلر در آن زمان 43 سال داشت . \r\nاوا  با وجود مخالفت پدرش فریدریش براون پیشنهاد آدولف هیتلر را عاشقانه پذیرفت و از آن پس تا آخرین لحظه عمر در کنار او زندگی کرد.\r\nیک سال بعد در ژانویه 1933 هیتلر پس از پیروزی در انتخابات به صدر اعظمی رسید و کابینه خود را با همکاری حزب دست راستی آلمان تشکیل داد. پس از اندکی با مرگ هیندنبورگ رئیس جمهور آلمان شد .\r\nگرمای عشق اوا براون قلب زخمی هیتلر از عشق ناکام گذشته ژلی روبال ، گرمایی دوباره بخشید او تواناست دوباره استواری و اقتدار سیاسی و مبارزاتی خویش را بدست بیاورد .هیتلر پس از به قدرت رسیدن هرگز اوا براون رادر امور دولتی و سیاست دخالت نمی داد و به ندرت در مراسم او را به همراه خود می‌برد و عملا اوا در سایه هیتلر زندگی می کرد.اوا براون اغلب به اسکی و یا دوختن لباس برای عشقش می پرداخت و پناه آخر آدلف بود . این مسیر را تا آخرین لحظه عمر ادامه داد .در هنگامی که سقوط برلین نزدیک شده بود، هیتلر مایل نبود اوا براون را به همراه خود به پناهگاه زیر زمینی ببرد، اما اوا اصرار کرد که می خواهد در کنار او بمیرد.  \r\n\r\nاوا 13 سال همسر غیر رسمی هیتلر بود .هیتلر  در روز 29 آوریل سال 1945 در مراسمی ساده که در پناهگاه زیر زمینی و با حضور تعداد اندکی از جمله جوزف گوبلز ، وزیر تبلیغات آلمان نازی و همسرش برگزارشد‌ ، به طور رسمی با اوا براون ازدواج کرد و روز بعد هر دو خودکشی کردند و اجساد آنان را در کنار هم آتش زدند تا به دست سربازان شوروی نیفتند. با وجود این ، سربازان شوروی بقایای اجساد نیمه سوخته آنها را به دست آوردند. در روز 30 آوریل سال 1945 که پناهگاه هیتلر در شهر برلین از نزدیک زیر آتش ارتش سرخ بود، هیتلر با تپانچه خود خودکشی کرد و اوا در همان لحظه با خوردن سیانور روح عشقش را یک لحظه هم تنها نگذاشت  گوبلز وزیر فرهنگ رژیم نازی طبق وصیت هیتلر پس از مردن آن دو ،  اجساد آنها را در گودالی که از پرتاب بمب های متفقین پدید آمده بود  آنها را با بنزین سوزاند و سپس خود همسر و فرزندانش به شکل دسته جمعی خودکشی کردند .اوا براون هنگام مرگ فقط 33 سال داشت  او فقط مدت 24 ساعت همسر رسمی عشقش بود. نام اوا براون زنی که تنها 24  ساعت همسر قانونی آدولف هیتلر بود در کنار نام او در تاریخ ثبت شد . اوا براون دختری که همه وجودش برای تعالی آلمان در تب و تاب بود در تمام سالهایی که هزاران جنایت و انگ انگلیس و اسرائیل و آمریکا به هیتلر چسباندن نامش پاک ماند . چون قلب او سپید و پاک بود به قول متفکر فاخر حال حاضر کشورمان ارد بزرگ : ستایشگران میهن مردان و زنان آزاده اند . اوا براون ستایشگر کشورش بود و در این راه تا آخر راه را پیمود و برای همین امروز محبوب صدها میلیون آدم میهن میهن پرست در سرتاسر جهان است.\r\n"},{"id":1812,"category_id":10,"category_code":"s10","source_id":374,"title":"خورشید سربازان اشک نهم ","content":" مهرداد دوم اشکانی با سپاهش از کنار باغ سبزی می گذشت سایه درختان باغ مکان خوبی بود برای استراحت .\r\nفرمانروا دستور داد در کنار دیوار بزرگ باغ لشکریان کمی استراحت کنند . باغبان نزدیک پادشاه ایران زمین آمده و از او و سربازان دعوت کرد که به باغ وارد شوند . مهرداد گفت ما باید خیلی زود اینجا را ترک کنیم و همین جا مناسب است . باغبان گفت دیشب خواب می دیدم خورشید ایران در پشت دیوار باغم است و امروز پادشاه کشورم را اینجا می بینم . مهرداد گفت اشتباه نکن آنخورشید من نیستم آن خورشید سربازان ایران هستند که در کنار دیوار باغت نشسته اند . \r\nاز این همه فروتنی و بزرگی پادشاه ایران زمین اشک در چشمان باغبان گرد آمد .\r\nمهرداد دوم ( اشک نهم ) بسیار فروتن بود و همواره در کنار سربازان خویش و بدور از تجملات بود . \r\n"},{"id":1813,"category_id":10,"category_code":"s10","source_id":375,"title":"درویش یکدست ","content":"درویشی در کوهساری دور از مردم زندگی می‌کرد و در آن خلوت به ذکر خدا و نیایش مشغول بود. در آن کوهستان، درختان سیب و گلابی و انار بسیار بود و درویش فقط میوه می‌خورد. روزی با خدا عهد کرد که هرگز از درخت میوه نچیند و فقط از میوه‌هایی بخورد که باد از درخت بر زمین می‌ریزد. درویش مدتی به پیمان خود وفادار بود، تا اینکه امر الهی، امتحان سختی برای او پیش ‌آورد. تا پنج روز، هیچ میوه‌ای از درخت نیفتاد. درویش بسیار گرسنه و ناتوان شد، و بالاخره گرسنگی بر او غالب شد. عهد و پیمان خود را شکست و از درخت گلابی چید و خورد. خداوند به سزای این پیمان شکنی او را به بلای سختی گرفتار کرد.\r\nقصه از این قرار بود که روزی حدود بیست نفر دزد به کوهستان نزدیک درویش آمده بودند و اموال دزدی را میان خود تقسیم می‌کردند. یکی از جاسوسان حکومت آنها را دید و به داروغه خبر داد. ناگهان ماموران دولتی رسیدند و دزدان را دستگیر کردند و درویش را هم جزو دزدان پنداشتند و او را دستگیر کردند. بلافاصله، دادگاه تشکیل شد و طبق حکم دادگاه یک دست و یک پای دزدان را قطع کردند. وقتی نوبت به درویش رسید ابتدا دست او را قطع کردند و همینکه خواستند پایش را ببرند، یکی از ماموران بلند مرتبه از راه رسید و درویش را شناخت و بر سر مامور اجرای حکم فریاد زد و گفت: ای سگ صفت! این مرد از درویشان حق است چرا دستش را بریدی؟\r\n  \r\nخبر به داروغه رسید، پا برهنه پیش شیخ آمد و گریه کرد و از او پوزش و معذرت بسیار خواست.اما درویش با خوشرویی و مهربانی گفت : این سزای پیمان شکنی من بود من حرمت ایمان به خدا را شکستم و خدا مرا مجازات کرد.\r\nاز آن پس در میان مردم با لقب درویش دست بریده معروف بود. او همچنان در خلوت و تنهایی و به دور از غوغای خلق در کلبه‌ای بیرون شهر به عبادت و راز و نیاز با خدا مشغول بود. روزی یکی از آشنایان سر زده، نزد او آمد و دید که درویش با دو دست زنبیل می‌بافد. درویش ناراحت شد و به دوست خود گفت چرا بی خبر پیش من آمدی؟ مرد گفت: از شدت مهر و اشتیاق تاب دوری شما را نداشتم. شیخ تبسم کرد و گفت: ترا به خدا سوگند می‌‌دهم تا زمان مرگ من، این راز را با هیچکس نگویی.\r\nاما رفته رفته راز کرامت درویش فاش شد و همه مردم از این راز با خبر شدند. روزی درویش در خلوت با خدا گفت: خدایا چرا راز کرامت مرا بر خلق فاش کردی؟ خداوند فرمود: زیرا مردم نسبت به تو گمان بد داشتند و می‌گفتند او ریاکار و دزد بود و خدا او را رسوا کرد. راز کرامت تو را بر آنان فاش کردم تا بدگمانی آنها بر طرف شود و به مقام والای تو پی ببرند.\r\n"},{"id":1814,"category_id":10,"category_code":"s10","source_id":376,"title":"پوستین کهنه در دربار ","content":"ایاز، غلام شاه محمود غزنوی (پادشاه ایران) در آغاز چوپان بود. وقتی در دربار سلطان محمود به مقام و منصب دولتی رسید، چارق و پوستین دوران فقر و غلامی خود را به دیوار اتاقش آویزان کرده بود و هر روز صبح اول به آن اتاق می‌رفت و به آنها نگاه می‌کرد و از بدبختی و فقر خود یاد می‌‌آورد و سپس به دربار می‌رفت. او قفل سنگینی بر در اتاق می‌بست. درباریان حسود که به او بدبین بودند خیال کردند که ایاز در این اتاق گنج و پول پنهان کرده و به هیچ کس نشان نمی‌دهد. به شاه خبر دادند که ایاز طلاهای دربار را در اتاقی برای خودش جمع و پنهان می‌کند. سلطان می‌دانست که ایاز مرد وفادار و درستکاری است. اما گفت: وقتی ایاز در اتاقش نباشد بروید و همه طلاها و پولها را برای خود بردارید.\r\nنیمه شب، سی نفر با مشعل‌های روشن در دست به اتاق ایاز رفتند. با شتاب و حرص قفل را شکستند و وارد اتاق شدند. اما هرچه گشتند چیزی نیافتند. فقط یک جفت چارق کهنه و یک دست لباس پاره آنجا از دیوار آویزان بود. آنها خیلی ترسیدند، چون پیش سلطان دروغزده می‌شدند. \r\nوقتی پیش شاه آمدند شاه گفت: چرا دست خالی آمدید؟ گنجها کجاست؟ آنها سرهای خود را پایین انداختند و معذرت خواهی کردند.سلطان گفت: من ایاز را خوب می‌شناسم او مرد راست و درستی است. آن چارق و پوستین کهنه را هر روز نگاه می‌کند تا به مقام خود مغرور نشود. و گذشته اش را همیشه به یاد بیاورد.\r\n"},{"id":1815,"category_id":10,"category_code":"s10","source_id":377,"title":"معمایی به نام زندگی ","content":"از خردمندی سؤال کردند که: می توانی بگویی زندگی آدمیان مانند چیست؟\r\nوی در جوابشان گفت: زندگی مردم مانند الاکلنگی است، که از یک طرفش سن آنها بالا می رود و از طرف دیگر زندگی آنها پائین می آید...!\r\n"},{"id":1816,"category_id":10,"category_code":"s10","source_id":378,"title":"آخرین آرزوی سقراط ","content":"پیش از آنکه سقراط را محاکمه کنند از وی پرسیدند: بزرگترین آرزویی که در دل داری چیست؟\r\n \r\nپاسخ داد: بزرگترین آرزوی من این است که به بالاترین مکان آتن صعود کنم و با صدای بلند به مردم بگویم: ای دوستان، چرا با این حرص و ولع بهترین و عزیزترین سال های زندگی خود را به جمع ثروت و سیم و طلا می گذرانید، در حالیکه آنگونه که باید و شاید در تعلیم و تربیت اطفالتان که مجبور خواهید شد ثروت خود را برای آنها باقی بگذارید، همت نمی گمارید؟!\r\n"},{"id":1817,"category_id":10,"category_code":"s10","source_id":379,"title":"دلبستگی مال دنیا ","content":"یکی ازعلمای ربانی نقل می کرد:درایام طلبگی دوستی داشتم که ساعتی داشت وبسیارآن رادوست می داشت ،همواره دریادآن بودکه گم نشودو آسیبی به آن نرسد،اوبیمارشدوبراثربیماری آنچنان حالش بدشدکه حالت احتضاروجان دادن پیداکرد، دراین میان یکی ازعلماءدرآنجا حاضربودواوراتلقین می دادومی گفت :بگولااله الاالله اودرجواب می گفت : نشکن نمی گویم :ماتعجب کردیم که چرابه جای ذکرخدا،می گوید:نشکن نمی گویم ، همچنان این معمابرای مابدون حل ماند،تااینکه حال آن دوست بیمارم اندکی خوب شدومن ازاوپرسیدم ،این چه حالی بودکه پیداکردی ،مامی گفتیم بگولا اله الاالله ،تودرجواب می گفتی :نشکن نمی گویم .\r\nاوگفت :اول آن ساعت را بیاوریدتابشکنم ،آن راآوردندوشکست. ،سپس گفت من دلبستگی خاصی به این ساعت داشتم ،هنگام احتضارشمامی گفتیدبگولااله الاالله ،شخصی شیطان را دیدم که همان ساعت رادریک دست خودگرفته ،وبادست دیگرچکشی بالای آن ساعت نگه داشته ومی گوید:اگربگوئی لااله الاالله ،این ساعت رامی شکنم ،من هم به خاطرعلاقه وافری که به ساعت داشتم می گفتم :ساعت رانشکن ،من لااله الا الله نمی گویم !\r\n"},{"id":1818,"category_id":10,"category_code":"s10","source_id":380,"title":"شنا ","content":"مردی جان خود را با شنا کردن از میان امواج خروشان و سهمناک رودخانه ای به خطر انداخت و پسر بچه ای را که بر اثر جریان آب به دریا رانده شده بود,از مرگ حتمی نجات داد.\r\nپسر بچه پس از غلبه بر اضطراب و وحشت ناشی از غرق شدن رو به مرد کرد و گفت:از اینکه جان مرا نجات دادید,متشکرم...\r\nمرد به چشمان پسر بچه نگریست و گفت:تشکر لازم نیست، پسرم فقط اطمینان حاصل کن که جانت ارزش نجات دادن را داشت ...\r\n"},{"id":1819,"category_id":10,"category_code":"s10","source_id":381,"title":"همزیستی","content":"در عصر یخبندان بسیاری از حیوانات یخ زدند و مردند.\r\n خارپشتها وخامت اوضاع را دریافتند و تصمیم گرفتند دورهم جمع شوند و بدین ترتیب خود را حفظ کنند ...\r\n ولی خارهایشان یکدیگررا زخمی میکرد با اینکه وقتی نزدیکتر بودند گرمتر میشدند ولی تصمیم گرفتند ازکنارهم دور شوند ولی با این وضع از سرما یخ زده می مردند ازاینرو مجبور بودند برگزینند: یا خارهای دوستان را تحمل کنند و یا نسلشان از روی زمین محو گردد...\r\n دریافتند که باز گردند و گردهم آیند.\r\n  \r\n آموختند که با زخم های کوچکی که از همزیستی بسیار نزدیک با کسی بوجود می آید کنار بیایند\r\n و زندگی کنند چون گرمای وجود آنها مهمتراست و این چنین توانستند زنده بمانند .\r\n  بهترین رابطه این نیست که اشخاص بی عیب و نقص را گردهم آورد بلکه \r\nآن است هر فرد بیاموزد با معایب دیگران کنارآید و محاسن آنانرا تحسین نماید...\r\n"},{"id":1820,"category_id":10,"category_code":"s10","source_id":382,"title":"معصومیت کودکانه ","content":"یک انسان شناس به تعدادی از بچه های آفریقایی یک بازی را پیشنهاد کرد:\r\nاو سبدی از میوه را در نزدیکی یک درخت گذاشت و گفت هر کسی که زودتر به آن برسد آن میوه های خوشمزه را برنده می شود.\r\nهنگامی که او فرمان دویدن را داد ، تمامی بچه ها دستان یکدیگر را گرفتند و  با یکدیگر دویده و در کنار درخت، خوشحال نشستند.\r\nهنگامی که انسان شناس از این رفتار آنها پرسید درحالیکه یک نفر می توانست به تنهایی همه میوه ها را برنده شود.\r\nآنها گفتند: آبونتو ، چگونه یکی از ما میتونه خوشحال باشه در حالیکه دیگران ناراحت اند.\r\n(آبونتو در فرهنگ ژوسا یعنی من هستم چون ما هستیم)\r\n"},{"id":1821,"category_id":10,"category_code":"s10","source_id":383,"title":"صد دلاری ","content":" یک سخنران معروف در مجلسی که دویست نفر در آن حضور داشتند، یک صد دلاری را از جیبش بیرون آورد و پرسید: چه کسی مایل است این اسکناس را داشته باشد؟ دست همه حاضرین بالا رفت.\r\n\r\nسخنران گفت: بسیار خوب، من این اسکناس را به یکی از شما خواهم داد ولی قبل از آن می خواهم کاری بکنم. و سپس در برابر نگاه های متعجب، اسکناس را مچاله کرد و پرسید: چه کسی هنوز مایل است این اسکناس را داشته باشد؟ و باز هم دست های حاضرین بالا رفت.\r\n\r\nاین بار مرد، اسکناس مچاله شده را به زمین انداخت و چند بار آن را لگد مال کرد و با کفش خود آن را روی زمین کشید. بعد اسکناس را برداشت و پرسید: خوب، حالا چه کسی حاضر است صاحب این اسکناس شود؟ و باز دست همه بالا رفت. سخنران گفت: دوستان، با این بلاهایی که من سر اسکناس در آوردم، از ارزش اسکناس چیزی کم نشد و همه شما خواهان آن هستید.  \r\nو ادامه داد: در زندگی واقعی هم همین طور است، ما در بسیاری موارد با تصمیمــاتی که می گیریم یا با مشکلاتی که روبرو می شویم، خم می شویم، مچالــه می شویم، خاک آلود می شویم و احساس می کنیم که دیگر پشیزی ارزش نداریم، ولی این گونه نیست و صرف نظر از این که چه بلایی سرمان آمده است هرگز ارزش خود را از دست نمی دهیم و هنوز هم برای افرادی که دوستمان دارند، آدم با ارزشی هستیم.\r\n"},{"id":1822,"category_id":10,"category_code":"s10","source_id":384,"title":"قهوه مبادا ","content":"\r\nبا یکی از دوستانم وارد قهوه‌خانه‌‌ای کوچک شدیم و سفارش‌ دادیم...\r\n\r\nبسمت میزمان می‌رفتیم که دو نفر دیگر وارد قهوه‌خانه شدند... و سفارش دادند:  پنج‌تا قهوه لطفا... دوتا برای ما و سه تا هم قهوه مبادا... سفارش‌شان را حساب کردند، و دوتا قهوه‌شان را برداشتند و رفتند...\r\nاز دوستم پرسیدم: ماجرای این قهوه‌های مبادا چی بود؟\r\nدوستم گفت: اگه کمی صبر کنی بزودی تا چند لحظه دیگه حقیقت رو می‌فهمی...\r\nآدم‌های دیگری وارد کافه شدند... دو تا دختر آمدند، نفری یک قهوه سفارش دادند، پرداخت کردند و رفتند...\r\nسفارش بعدی هفت‌تا قهوه بود از طرف سه تا وکیل... سه تا قهوه برای خودشان و چهارتا قهوه مبادا...\r\n\r\nهمان‌طور که به ماجرای قهوه‌های مبادا فکر می‌کردم و از هوای آفتابی و منظره‌ی زیبای میدان روبروی کافه لذت می‌بردم،\r\nمردی با لباس‌های مندرس وارد کافه شد که بیشتر به گداها شباهت داشت... با مهربانی از قهوه‌چی پرسید: قهوه‌ی مبادا دارید؟\r\nخیلی ساده‌ ست! مردم به جای کسانی که نمی‌توانند پول قهوه و نوشیدنی گرم بدهند، به حساب خودشان قهوه مبادا می‌خرند...\r\n\r\nسنت قهوه‌ی مبادا از شهرناپل ایتالیا شروع شد و کم‌کم به همه‌جای جهان سرایت کرد.\r\nبعضی‌ جاها هست که شما نه تنها می‌توانید نوشیدنی گرم به جای کسی بخرید،\r\nبلکه می‌توانید پرداخت پول یک ساندویچ یا یک وعده غذای کامل را نیز تقبل کنید...\r\n"},{"id":1823,"category_id":10,"category_code":"s10","source_id":385,"title":"دکتر گلن گانینگهام ","content":"مدرسه‌ی کوچک روستایی بود که به‌وسیله‌ی بخاری زغالی قدیمی، گرم می‌شد. پسرکی موظف بود هر روز زودتر از همه به مدرسه بیاید و بخاری را روشن کند تا قبل از ورود معلم و هم‌کلاسی‌هایش، کلاس گرم شود. روزی، وقتی شاگردان وارد محوطه‌ی مدرسه شدند، دیدند مدرسه در میان شعله‌های آتش می‌سوزد. آنان بدن نیمه بی‌هوش هم‌کلاسی خود را که دیگر رمقی در او باقی نمانده بود، پیدا کردند و بی‌درنگ به بیمارستان رساندند. \r\nپسرک با بدنی سوخته و نیمه جان روی تخت بیمارستان دراز کشیده بود ، که ناگهان شنید دکتر به مادرش می‌گفت: «هیچ امیدی به زنده ماندن پسرتان نیست، چون شعله‌های آتش به‌طور عمیق، بدنش را سوزانده و از بین برده است». اما پسرک به هیچوجه نمی‌خواست بمیرد. او با توکل به خدا و طلب یاری از او تصمیم گرفت تا تمام تلاش خود را برای زنده ماندن به کار بندد و زنده بماند و ... چنین هم شد. \r\nاو در مقابل چشمان حیرت زده‌ی دکتر به راستی زنده ماند و نمرد. هنگامی که خطر مرگ از بالای سر او رد شد، پسرک دوباره شنید که دکتر به مادرش می‌گفت: طفلکی به خاطر قابل استفاده نبودن پاهایش، مجبور است تا آخر عمر لنگ‌لنگان راه برود. \r\nپسرک بار دیگر تصمیم خود را گرفت. او به هیچ‌وجه نخواهد لنگید. او راه خواهد رفت، اما متاسفانه هیچ تحرکی در پاهای او دیده نمی‌شد. بالاخره روزی فرا رسید که پسرک از بیمارستان مرخص شد. مادرش هر روز پاهای کوچک او را می‌مالید، اما هیچ احساس و حرکتی در آنها به چشم نمی‌خورد. با این حال، هیچ خللی در عزم و اراده‌ی پسرک وارد نشده بود و همچنان قاطعانه عقیده داشت که روزی قادر به راه رفتن خواهد بود.\r\n  \r\nیک روز آفتابی، مادرش او را در صندلی چرخ‌دار قرارداد و برای هواخوری به حیاط برد. آن روز، پسرک بر خلاف دفعه‌های قبل، در صندلی چرخ‌دار نماند. او خود را از آن بیرون کشید و در حالی که پاهایش را می‌کشید، روی چمن شروع به خزیدن کرد. او خزید و خزید تا به نرده‌های چوبی سفیدی که دور تا دور حیاط‌شان کشیده شده بود، رسید. \r\nبا هر زحمتی که بود، خود را بالا کشید و از نرده‌ها گرفت و در امتداد نرده‌ها جلو رفت و در نهایت، راه افتاد. او این کار را هر روز انجام می‌داد، به‌طوری که جای پای او در امتداد نرده‌های اطراف خانه دیده می‌شد. او چیزی جز بازگرداندن حیات به پاهای کوچکش نمی‌خواست. \r\nسرانجام، با خواست خدا و عزم و اراده‌ی پولادینش، توانست روی پاهای خود بایستد و با کمی صبر و تحمل توانست گام بردارد و سپس راه برود و در نهایت، بدود. او دوباره به مدرسه رفت و فاصله‌ی بین خانه و مدرسه را به خاطر لذت، می‌دوید. او حتی در مدرسه یک تیم دو تشکیل داد.\r\n \r\nسال‌ها بعد، این پسرکی که هیچ امیدی به زنده ماندن و راه رفتنش نبود، یعنی دکتر «گلن گانینگهام» در باغ چهارگوش «مادیسون» موفق به شکستن رکورد دوی سرعت در مسافت یک مایلی شد!\r\n"},{"id":1824,"category_id":10,"category_code":"s10","source_id":386,"title":"زندانی بدون دیوار ","content":"بعد از جنگ آمریکا با کره، ژنرال ویلیام مایر که بعدها به سمت روانکاو ارشد ارتش آمریکا منصوب شد، یکی از پیچیده ترین موارد تاریخ جنگ در جهان را مورد مطالعه قرار میداد.\r\nحدود هزار نفر از نظامیان آمریکایی در کره، در اردوگاهی زندانی شده بودند که از استانداردهای بین المللی برخوردار بود.\r\nزندان با تعریف متعارف تقریباً محصور نبود. آب و غذا و امکانات به وفور یافت میشد. از هیچیک از تکنیکهای متداول شکنجه استفاده نمیشد. اما...  بیشترین آمار مرگ زندانیان در این اردوگاه گزارش شده بود.\r\nزندانیان به مرگ طبیعی میمردند. امکانات فرار وجود داشت اما فرار نمیکردند. بسیاری از آنها شب میخوابیدند و صبح دیگر بیدار نمیشدند. آنهایی که مانده بودند احترام درجات نظامی را میان خود رعایت نمیکردند‏ و عموماً با زندانبانان خود طرح دوستی میریختند.\r\n\r\nدلیل این رویداد، سالها مورد مطالعه قرار گرفت و ویلیام مایر نتیجه تحقیقات خود را به این شرح ارائه کرد:\r\n ‏در این اردوگاه، فقط نامه هایی که حاوی خبرهای بد بودند به دست زندانیان رسیده میشد، نامه های مثبت و امیدبخش تحویل نمیشدند.\r\nهرروز از زندانیان میخواستند در مقابل جمع، خاطره یکی از مواردی که به دوستان خود خیانت کرده اند یا میتوانستند خدمتی بکنند و نکرده اند را تعریف کنند.\r\nهرکس که جاسوسی سایر زندانیان را میکرد، سیگار جایزه میگرفت. اما کسی که در موردش جاسوسی شده بود هیچ نوع تنبیهی نمیشد. همه به جاسوسی برای دریافت جایزه (که خطری هم برای دوستانشان نداشت) عادت کرده بودند.\r\nتحقیقات نشان داد که این سه تکنیک در کنار هم، سربازان را به نقطه مرگ رسانده است.\r\nبا دریافت خبرهای منتخب (فقط منفی) امید از بین میرفت.\r\nبا جاسوسی، عزت نفس زندانیان تخریب میشد و خود را انسانی پست می یافتند.\r\nبا تعریف خیانتها، اعتبار آنها نزد همگروهی ها از بین میرفت.\r\nو این هر سه برای پایان یافتن انگیزه زندگی، و مرگ های خاموش کافی بود.\r\n\r\nاین سبک شکنجه، شکنجه خاموش نامیده میشود.\r\n"},{"id":1825,"category_id":10,"category_code":"s10","source_id":387,"title":"شمع ","content":"مردی در بستر مرگ افتاده بود. همسرش را فراخواند تا نزدش بیاید و به او گفت: «دیگر زمان وداع ابدی من و تو فرارسیده است؛ پس بیا و برای آخرین بار به من مهر و وفاداری خود را ثابت کن...\r\n\r\n چراکه در مسلک ما گفته شده مرد متاهل هنگام گذر از دروازه بهشت باید سوگند بخورد که تمام عمر کنار زنی والا زندگی کرده است. در کشوی میز من شمعی قرمز هست،  این شمع متبرک است و آن را از کشیشی گرفته‌ام و برای همین ارزشی بسیار دارد. سوگند بخور تا زمانی که این شمع وجود دارد دوباره ازدواج نکنی.»\r\n\r\nزن سوگند خورد و مرد مُرد. در مراسم تشییع جنازه مرد، زن بالای قبر ایستاده بود و پذیرای تسلیت اقوام بود و شمع قرمز روشنی در دست داشت و تا تمام شدن آن بالای سر قبر ایستاد!\r\n"},{"id":1826,"category_id":10,"category_code":"s10","source_id":388,"title":"بدون شرح ","content":"«به کسی گفتند امامزاده یعقوب را در کوه، پلنگ خورد! آنکه می دانست تصحیح کرد که اولاً: امامزاده نبود و پیغمبر بود، ثانیاً: یعقوب نبود و یونس بود، ثالثاً: کوه نبود و دریا بود، رابعاً: پلنگ نبود و نهنگ بود و خامساً: او را نخورد و در شکمش نگه داشته و به ساحل رساند.»"},{"id":1827,"category_id":10,"category_code":"s10","source_id":389,"title":"وصیت نامه الکساندر ","content":"پادشاه بزرگ یونان، الکساندر، پس از تسخیر کردن حکومت های پادشاهی بسیار، در حال بازگشت به وطن خود بود. در بین راه، بیمار شد و به مدت چند ماه بستری \r\nگردید.\r\nبا نزدیک شدن مرگ، الکساندر دریافت که چقدر پیروزی هایش، سپاه بزرگش، شمشیر\r\nتیزش و همه ی ثروتش بی فایده بوده است. او فرمانده هان ارتش را فرا خواند و گفت:\r\nمن این دنیا را بزودی ترک خواهم کرد. اما سه خواسته دارم. لطفاً، خواسته هایم را حتماً\r\nانجام دهید. \r\nفرمانده هان ارتش درحالی که اشک از گونه هایشان سرازیر شده بود موافقت\r\nکردند که از آخرین خواسته های پادشاهشان اطاعت کنند. الکساندر گفت:...  اولین خواسته ام این است که پزشکان من باید تابوتم را به تنهایی حمل کنند.\r\nثانیاً، وقتی تابوتم دارد به قبر حمل می گردد ، مسیر منتهی به قبرستان باید با طلا، نقره و سنگ های قیمتی که در خزانه داری جمع آوری کرده ام پوشانده شود. \r\nسومین و آخرین خواسته این است که هر دو دستم باید بیرون از تابوت آویزان باشد.\r\nمردمی که آنجا گرد آمده بودند از خواسته های عجیب پادشاه تعجب کردند. اما هیچ کس جرأت اعتراض نداشت. فرمانده ی مورد علاقه الکساندر دستش را بوسید و \r\n\r\nروی قلب خود گذاشت و گفت : پادشاها، به شما اطمینان می دهیم که همه ی خواسته هایتان اجرا\r\nخواهد شد. اما بگویید چرا چنین خواسته های عجیبی دارید؟ در پاسخ به این پرسش، الکساندر نفس عمیقی کشید و گفت:\r\nمن می خواهم دنیا را آگاه سازم از سه درسی که تازه یاد گرفته ام. می خواهم پزشکان تابوتم را حمل کنند چرا که مردم بفهمندکه هیچ دکتری نمی تواند هیچ کس را \r\n\r\nواقعاً شفا دهد. آن ها ضعیف هستند و نمی توانند انسانی را از چنگال های مرگ نجات دهند.\r\nبنابراین، نگذارید مردم فکر کنند زندگی ابدی دارند.\r\nدومین خواسته ی درمورد ریختن طلا، نقره و جواهرات دیگر در مسیر راه به قبرستان،\r\nاین پیام را به مردم می رساند که حتی یک خرده طلا هم نمی توانم با خود ببرم. بگذارید مردم بفهمند که دنبال ثروت رفتن اتلاف وقت محض است. \r\nسومین خواسته ام یعنی دستهایم بیرون از تابوت باشد، می خواهم مردم بدانند که من با دستان خالی به این دنیا آمده ام و با دستان خالی این دنیا را ترک می کنم.\r\n"},{"id":1828,"category_id":10,"category_code":"s10","source_id":390,"title":"اینگونه آرمش داشته باشید ","content":"\r\nیکی از شاگردان سقراط وی را پرسید: زچه رو هرگزت اندوهگین ندیده‌ام ؟\r\nسقراط گفت: از آن رو که چیزی را مالک نیستم که عدمش اندوهگینم کند\r\n"},{"id":1829,"category_id":10,"category_code":"s10","source_id":391,"title":"داستان گربه را دم حجله کشتن ","content":"میگویند در ایام قدیم دختری تندخو و بد اخلاق وجود داشته که هیج کس حاضر به ازدواج با او نبوده است. پس از چندی پسری از اهالی شهامت به خرج می دهد و تصمیم می گیرد که با وی ازدواج کند. بر خلاف نظر همه ، او میگوید که میتواند دخترک را رام کند. خلاصه پس از مراسم عروسی ، عروس و داماد وارد حجله میشوند و....  چند دقیقه از زفاف که میگذرد پسرک احساس تشنگی میکند . گربه ای در اتاق وجود داشته از او میخواهد که آب بیاورد. چند بار تکرار میکند که ای گربه برو و برای من آب بیاور. گربه بیچاره که از همه جا بی خبر بوده از جایش تکان نمی خورد تا اینکه مرد جوان چاقویش را از غلاف بیرون می کشد و سر از تن گربه جدا میکند. سپس رو یه دختر میکند و میگوید برو آب بیار..."},{"id":1830,"category_id":10,"category_code":"s10","source_id":392,"title":"چند دقیقه سکوت کنید! ","content":"\r\nروزی کشاورزی متوجّه شد ساعتش را در انبار علوفه گم کرده است.  \r\nساعتی معمولی امّا با خاطره ای از گذشته و ارزشی عاطفی بود.\r\nبعد از آن که در میان علوفه بسیار جستجو کرد و آن را نیافت از گروهی کودکان که در بیرون انبار مشغول بازی بودند مدد خواست و وعده داد که هر کسی آن را پیدا کند جایزه ای دریافت نماید.\r\n\r\nکودکان به محض این که موضوع جایزه مطرح شد به درون انبار هجوم آوردند و تمامی کپّه های علف و یونجه را گشتند امّا باز هم ساعت پیدا نشد.\r\n\r\nکودکان از انبار بیرون رفتند و درست موقعی که کشاورز از ادامۀ جستجو نومید شده بود،  پسرکی نزد او آمد و از وی خواست به او فرصتی دیگر بدهد.\r\nکشاورز نگاهی به او انداخت و با خود اندیشید، \"چرا که نه؟ به هر حال، کودکی صادق به نظر میرسد.\"\r\nپس کشاورز کودک را به تنهایی به درون انبار فرستاد.\r\nبعد از اندکی کودک در حالی که ساعت را در دست داشت از انبار علوفه بیرون آمد.\r\nکشاورز از طرفی شادمان شد و از طرف دیگر متحیّر گشت که چگونه کامیابی از آنِ این کودک شد.\r\nپس پرسید، \"چطور موفّق شدی در حالی که بقیه کودکان ناکام ماندند؟\"\r\nپسرک پاسخ داد، \"من کار زیادی نکردم؛ روی زمین نشستم و در سکوت کامل گوش دادم تا صدای تیک تاک ساعت را شنیدم و در همان جهت حرکت کردم و آن را یافتم.\"\r\n"},{"id":1831,"category_id":10,"category_code":"s10","source_id":393,"title":"امید ","content":"سه نفر جواب آزمایش هایشان را در دست داشتند . به هر سه ، دکتر گفته بود که بر اساس آزمایشات انجام شده به بیماری های لاعلاجی مبتلا شده اند به صورتی که دیگر امیدی به ادامه زندگی برای آنها وجود ندارد .در آینده ای نزدیک عمرشان به پایان می رسد .آنها داشتند در این باره صحبت می کردند که می خواهند باقیمانده عمرشان را چه کار کنند . \r\nنفر اول گفت :\r\n  « من در زندگی ام همیشه مشغول کسب و تجارت بوده ام و حالا که نگاه می کنم حتی یک روز از زندگی ام را به تفریح و استراحت نپرداخته ام . اما حالا که متوجه شده ام بیش از چند روزی از عمرم باقی نمانده می خواهم تمام ثروتم را در این چند روز خرج کامجویی و لذت از دنیا کنم. \r\nمی خواهم جاهایی بروم که یک عمر خیال رفتنش را داشتم . چیزهایی را بپوشم که دلم می خواسته اما نپوشیده ام . کارهایی انجام دهم که به علت مشغله زیاد انجام نداده ام و چیزهایی بخورم که تا به حال نخورده ام .» \r\n\r\nنفر دوم می گوید : « من نیز یک عمر درگیر تجارت بوده ام و از اطرافیانم غافل بوده ام . \r\nاولین کاری که می کنم اینست که می روم سراغ پدر و مادرم و آنها را به خانه ام می آورم تا این چند روز را در کنار آنها و همراه با همسر و فرزندانم سپری کنم . در این چند روز می خواهم به تمام دوستان و فامیلم سر بزنم و از بودن با آنها لذت ببرم . در این چند روز باقی مانده می خواهم نصف ثروتم را صرف کارهای خیر خواهانه و عام المنفعه بکنم . و نیمی دیگر را برای خانواده ام بگذارم تا پس از مرگ من دچار مشکلات مالی نشوند .» \r\n\r\nنفر سوم با شنیدن سخنان دو نفر اول لحظه ای ساکت ماند و اندیشید و سپس گفت : \r\nمن مثل شما هنوز نا امید نشده ام و امیدم را از زندگی از دست نداده ام . من می خواهم سالهای سال عمر کنم و از زنده بودنم لذت ببرم اولین کاری که من می خواهم انجام بدهم اینست که دکترم را عوض کنم می خواهم سراغ دکترهای با تجربه تر بروم من می خواهم زنده بمانم و زنده می مانم .\r\n"},{"id":1832,"category_id":10,"category_code":"s10","source_id":394,"title":"تدبیر درست ","content":"در یک شرکت بزرگ ژاپنی که تولید وسایل آرایشی را برعهده داشت یک مورد به یاد ماندنی اتفاق افتاد\r\nشکایتی از سوی یکی مشتریان به کمپانی رسید . او  اظهار داشته  بود  که  هنگام  خرید  یک بسته صابون  متوجه شده بود که  آن قوطی خالی است.\r\nبلافاصله  با تاکید و پیگیریهای مدیریت ارشد  کارخانه  این مشکل  بررسی ،  و دستور صادر شد که خط بسته بندی اصلاح گردد و قسمت فنی  و مهندسی نیز تدابیر لازمه را جهت پیشگیری از تکرار چنین مسئله ای اتخاذ نماید  .  \r\nمهندسین نیز دست به کار شده و راه حل پیشنهادی خود را چنین ارائه دادند:....  پایش ( مونیتورینگ )  خط بسته بندی با اشعه ایکس\r\nبزودی سیستم مذکور خریداری شده و با تلاش شبانه روزی گروه مهندسین ،‌ دستگاه تولید اشعه ایکس و مانیتورهائی با رزولوشن بالا نصب شده  و خط مذبور تجهیز گردید.\r\nسپس دو نفر اپراتور نیز جهت کنترل دائمی پشت آن دستگاهها به کار گمارده شدند  تا از عبور احتمالی قوطیهای خالی جلوگیری نمایند.  \r\nنکته جالب توجه در این بود که درست همزمان با این ماجرا ،  مشکلی مشابه  نیز در یکی از کارگاههای کوچک تولیدی پیش آمده بود اما آنجا  یک کارمند معمولی و غیر متخصص آنرا به شیوه ای بسیار ساده تر و کم خرجتر حل کرد :  \r\nتعبیه یک دستگاه پنکه در مسیر خط  بسته بندی تا قوطی خالی را باد ببرد !!! \r\n"},{"id":1833,"category_id":10,"category_code":"s10","source_id":395,"title":"توبه ی نصوح","content":"نصوح مردى بود شبیه زنها ،صدایش نازک بود صورتش مو نداشت و اندامی زنانه داشت او مردی شهوتران بود با سواستفاده از وضع ظاهرش در حمام زنانه کار مى کرد و کسى از وضع او خبر نداشت او از این راه هم امرارمعاش می کرد هم ارضای شهوت.\r\nگرچه چندین بار به حکم وجدان توبه کرده بود اما هر بار توبه اش را می شکست. \r\nاو دلاک و کیسه کش حمام زنانه بود. آوازه تمیزکارى و زرنگى او به گوش همه رسیده و زنان و دختران و رجال دولت و اعیان و اشراف دوست داشتند که وى آنها را دلاکى کند و از او قبلاً وقت مى گرفتند تا روزى در کاخ شاه صحبت از او به میان آمد. دختر شاه به حمام رفت و مشغول استحمام شد.\r\n\r\nاز قضا گوهر گرانبهاى دختر پادشاه در آن حمام مفقود گشت ، از این حادثه دختر پادشاه در غضب شد و دستور داد که همه کارگران را تفتیش کنند تا شاید آن گوهر ارزنده پیدا شود. \r\nکارگران را یکى بعد از دیگرى گشتند تا اینکه نوبت به نصوح رسید او از ترس رسوایى ، حاضر نـشد که وى را تفتیش ‍ کنند، لذا به هر طرفى که مى رفتند تا دستگیرش کنند، او به طرف دیگر فرار مى کرد و...\r\n  این عمل او سوء ظن دزدى را در مورد او تقویت مى کرد و لذا مأمورین براى دستگیرى او بیشتر سعى مى کردند. نصوح هم تنها راه نجات را در این دید که خود را در میان خزینه حمام پنهان کند، ناچار به داخل خزینه رفته و همین که دید مأمورین براى گرفتن او به خزینه آمدند و دیگر کارش از کار گذشته و الان است که رسوا شود به خداى تعالى متوجه شد و از روى اخلاص توبه کرد در حالی که بدنش مثل بید می‌لرزید با تمام وجود و با دلی شکسته گفت: خداوندا گرچه بارها توبه‌ام بشکستم، اما تو را به مقام ستاری ات این بار نیز فعل قبیحم بپوشان تا زین پس گرد هیچ گناهی نگردم و از خدا خواست که از این غم و رسوایى نجاتش دهد.\r\n \r\nنصوح از ته دل توبه واقعی نمود ناگهان از بیرون حمام آوازى بلند شد که دست از این بیچاره بردارید که گوهر پیدا شد. پس از او دست برداشتند و نصوح خسته و نالان شکر خدا به جا آورده و از خدمت دختر شاه مرخص ‍ شد و به خانه خود رفت.\r\n \r\nاو عنایت پرودگار را مشاهده کرد. این بود که بر توبه اش ثابت قدم ماند و فوراً از آن کار کناره گرفت.\r\n \r\nچند روزی از غیبت او در حمام سپری نشده بود که دختر شاه او را به کار در حمام زنانه دعوت کرد، ولی نصوح جواب داد که دستم علیل شده و قادر به دلاکی و مشت و مال نیستم، و دیگر هم نرفت. هر مقدار مالى که از راه گناه کسب کرده بود در راه خدا به فقرا داد و چون زنان شهر از او دست بردار نبودند، دیگر نمى توانست در آن شهر بماند و از طرفى نمى توانست راز خودش را به کسى اظهار کند، ناچار از شهر خارج و در کوهى که در چند فرسنگی آن شهر بود، سکونت اختیار نمود و به عبادت خدا مشغول گردید.\r\n\r\nشبی در خواب دید که کسی به او می گوید:\"ای نصوح! تو چگونه توبه کرده اى و حال آنکه گوشت و پوست تو از فعل حرام روئیده شده است؟ تو باید چنان توبه کنى که گوشتهاى حرام از بدنت بریزد.» همین که از خواب بیدار شد با خودش قرار گذاشت که سنگ هاى سنگین حمل کند تا گوشت هاى حرام تنش را آب کند.\r\n \r\nنصوح این برنامه را مرتب عمل مى کرد تا در یکى از روزها همانطورى که مشغول به کار بود، چشمش به میشى افتاد که در آن کوه چرا می کرد. از این امر به فکر فرو رفت که این میش از کجا آمده و از کیست؟\r\n \r\nعاقبت با خود اندیشید که این میش قطعاً از شبانى فرار کرده و به اینجا آمده است، بایستى من از آن نگهدارى کنم تا صاحبش پیدا شود . لذا آن میش را گرفت و نگهدارى نمود خلاصه میش زاد ولد کرد و نصوح از شیر آن بهره مند مى شد تا سرانجام کاروانى که راه را گم کرده بود و مردمش از تشنگى مشرف به هلاکت بودند عبورشان به آنجا افتاد، همین که نصوح را دیدند از او آب خواستند و او به جاى آب به آنها شیر مى داد به طورى که همگى سیر شده و راه شهر را از او پرسیدند.\r\nوى راهى نزدیک را به آنها نشان داده و آنها موقع حرکت هر کدام به نصوح احسانى کردند و او در آنجا قلعه اى بنا کرده و چاه آبى حفر نمود و کم کم در آنجا منازلى ساخته و شهرکى بنا نمود و مردم از هر جا به آنجا آمده و در آن محل سکونت اختیار کردند، همگى به چشم بزرگى به او مى نگریستند.\r\n \r\nرفته رفته، آوازه خوبى و حسن تدبیر او به گوش پادشاه آن عصر رسید که پدر آن دختر بود. از شنیدن این خبر مشتاق دیدار او شده، دستور داد تا وى را از طرف او به دربار دعوت کنند. همین که دعوت شاه به نصوح رسید، نپذیرفت و گفت: من کارى و نیازى به دربار شاه ندارم و از رفتن نزد سلطان عذر خواست.\r\n \r\nمامورین چون این سخن را به شاه رساندند  شاه بسیار تعجب کرد و اظهار داشت حال که او نزد ما نمی آید ما مى رویم او را ببینیم.پس با درباریانش به سوى نصوح حرکت کرد، همین که به آن محل رسید به عزرائیل امر شد که جان پادشاه را بگیرد، پس پادشاه در آنجا سکته کرد و نصوح چون خبردار شد که شاه براى ملاقات و دیدار او آمده بود، در مراسم تشییع او شرکت و آنجا ماند تا او را به خاک سپردند و چون پادشاه پسرى نداشت، ارکان دولت مصلحت دیدند که نصوح را به تخت سلطنت بنشانند. چنان کردند و نصوح چون به پادشاهى رسید، بساط عدالت را در تمام قلمرو مملکتش گسترانیده و بعد با همان دختر پادشاه که ذکرش رفت، ازدواج کرد و چون شب زفاف و عروسى رسید، در بارگاهش ‍ نشسته بود که ناگهان شخصى بر او وارد شد و گفت چند سال قبل، میش من گم شده بود و اکنون آن را نزد تو یافته ام، مالم را به من برگردان.\r\n \r\nنصوح گفت : درست است و دستور داد تا میش را به او بدهند، گفت چون میش مرا نگهبانى کرده اى هرچه از منافع آن استفاده کرده اى، بر تو حلال ولى باید آنچه مانده با من نصف کنى.\r\n \r\nگفت: درست است و دستور داد تا تمام اموال منقول و غیر منقول را با او نصف کنند.آن شخص گفت: بدان اى نصوح، نه من شبانم و نه آن میش است بلکه ما دو فرشته براى آزمایش تو آمده ایم. تمام این ملک و نعمت اجر توبه راستین و صادقانه ات بود که بر تو حلال و گوارا باد، و از نظر غایب شدند...\r\n"}];
